let coachMode='quick';let dealContext={};let conversationHistory=[];let _copyStore={};let _hsContacts={};let hsContactData=null;let hsSearchTimer=null;var COACH_CONTEXT={pitches:{title:'✏️ Pitch Writer',subtitle:'AI helps you write your elevator pitch',placeholder:'Describe who you\'re pitching to and I\'ll write a pitch for you...',callType:null,hideCallTypes:true},competition:{title:'🔍 Competitor Research',subtitle:'AI scrapes the web for intel on any competitor',placeholder:'Name a competitor and I\'ll research them and tell you exactly how to win...',callType:null,hideCallTypes:true},coldcall:{title:'📞 Cold Call Coach',subtitle:'AI writes cold calls for your specific prospect',placeholder:'Tell me about who you\'re calling and I\'ll write your cold call script...',callType:'coldcall',hideCallTypes:false},discovery:{title:'🔍 Discovery Coach',subtitle:'AI helps you run a better discovery call',placeholder:'Tell me about this prospect and I\'ll guide your discovery questions...',callType:'discovery',hideCallTypes:false},demo:{title:'🖥️ Demo Meeting Coach',subtitle:'AI tells you exactly what to show and skip',placeholder:'Tell me about who you\'re demoing for and I\'ll build your demo plan...',callType:'demo',hideCallTypes:false},closing:{title:'🏆 Closing Meeting Coach',subtitle:'AI helps you close this specific deal',placeholder:'Tell me where this deal stands and I\'ll give you your closing strategy...',callType:'closing',hideCallTypes:false},onboarding:{title:'🚀 Onboarding Meeting Coach',subtitle:'AI helps you set up new customers for success',placeholder:'Tell me about your new customer and I\'ll guide the onboarding...',callType:'onboarding',hideCallTypes:false},objections:{title:'🛡️ Objection Handler',subtitle:'Tell me the objection — AI tells you how to handle it',placeholder:'What objection are you facing? Paste it here and I\'ll give you the exact response...',callType:null,hideCallTypes:true},battlecards:{title:'✕ Battle Card Coach',subtitle:'AI helps you win against specific competitors',placeholder:'Which competitor did they bring up? I\'ll tell you exactly how to position against them...',callType:null,hideCallTypes:true},talktracks:{title:'💬 Talk Track Builder',subtitle:'AI writes talk tracks for any situation',placeholder:'Describe the situation and I\'ll write a talk track for it...',callType:null,hideCallTypes:true},};function openCoach(){document.getElementById('coachPanel').classList.add('open');document.getElementById('coachOverlay').classList.add('open');var ctx=COACH_CONTEXT[_currentSection]||{};var selector=document.getElementById('callTypeSelector');var titleEl=document.querySelector('#coachPanel .coach-title');var subtitleEl=document.querySelector('#coachPanel .coach-subtitle');if(titleEl&&ctx.title)titleEl.textContent=ctx.title;if(subtitleEl&&ctx.subtitle)subtitleEl.textContent=ctx.subtitle;var extraEl=document.getElementById('f-extra');if(extraEl&&ctx.placeholder)extraEl.placeholder=ctx.placeholder;if(selector){selector.style.display=ctx.hideCallTypes?'none':'block';}
if(ctx.callType&&!ctx.hideCallTypes){document.querySelectorAll('.call-type-btn').forEach(function(btn){btn.classList.remove('active','selected');if(btn.getAttribute('data-type')===ctx.callType){btn.classList.add('active','selected');}});}}
function closeCoach(){document.getElementById('coachPanel').classList.remove('open');document.getElementById('coachOverlay').classList.remove('open');}
