var seScripts=[],seCurrentId=null,seDirty=false,seAutoTimer=null,seDragEl=null;var SE_TEMPLATES={coldcall:{name:'Cold Call Script',type:'coldcall',steps:[{title:'Opening (0:00-0:15)',body:'Hey [Name], this is [Your name] from AgentNav. Quick question - we built a platform for health brokers: ACA and STM quoting, full CRM, SMS, and Renewal Autopilot that automates your entire OEP. Worth two minutes?'},{title:'Earn the minute (0:15-0:45)',body:'What does your OEP process look like right now? Running it manually or do you have something in place?'},{title:'Connect pain to feature (0:45-1:30)',body:'[Repeat back what they said.] That is exactly the problem we solve. [Name one specific feature that addresses their pain.]'},{title:'Soft pitch (1:30-2:00)',body:'AgentNav is the only platform built for health brokers - ACA quoting, HealthSherpa, Renewal Autopilot, CRM, SMS, all in one place. Starts at $79 per month.'},{title:'Close for meeting (2:00-2:30)',body:'I would love to show you a 15-minute demo. Do you have time Thursday or Friday?'}]},discovery:{name:'Discovery Call Script',type:'discovery',steps:[{title:'Set the agenda',body:'Thanks for making time. I want to spend most of this call learning about how you are set up right now. Then if I think AgentNav could help, I will be honest about that. Sound good?'},{title:'Current setup',body:'Walk me through your agency. How big is your team? What tools for quoting, CRM, SMS, enrollment? How are you managing renewals?'},{title:'Find the pain',body:'What does your OEP look like? How many clients are you manually reaching out to in November? How many slip through?'},{title:'Qualify',body:'What percentage of your book is ACA vs other lines? Do you use HealthSherpa or EDE? Looking to grow the team this year?'},{title:'Set up the demo',body:'Based on what you told me, here is what I want to show you: [Name 2-3 specific features]. Does that sound right?'}]},demo:{name:'Demo Meeting Script',type:'demo',steps:[{title:'Confirm discovery',body:'Before I share my screen - last time you mentioned [pain point]. Is that still the main thing you want to see solved today?'},{title:'Client record',body:'This is where a client lives - everything in one place. Medical history, Rx, FPL tracking, policy history, SMS thread, calendar.'},{title:'Renewal Autopilot',body:'Every renewal client has a status. For each one with Autopilot on, the system sends the campaign, collects preferences, and generates a new quote. You just review and approve.'},{title:'Quoting',body:'ACA, STM, Life, Ancillary, Indemnity - all quoted side by side. Pull from HealthSherpa or EDE directly. One-click to send the proposal.'},{title:'Close',body:'What questions do you have? [Pause.] Based on what you saw today, what would need to be true for this to be a yes?'}]},objections:{name:'Objection Handling',type:'objections',steps:[{title:'"Too expensive"',body:'What are you paying right now for CRM, quoting, SMS, and enrollment combined? Most agents are at $200-400 per month. AgentNav replaces all of it for $79.'},{title:'"Need to think about it"',body:'Totally fair. What specifically do you want to think through? Price, timing, or something you want to verify?'},{title:'"Happy with what we have"',body:'What does your OEP process look like? How many clients did you lose last November because they fell through? That is what Renewal Autopilot eliminates.'},{title:'"Need to talk to my partner"',body:'Of course. Can we get them on a quick call together this week?'},{title:'"Not the right time"',body:'When is? Agents who switch before OEP go in with Autopilot already configured.'}]}};var SE_GROUPS=[{label:'Before The Call',types:['coldcall','discovery']},{label:'On The Call',types:['demo','closing','onboarding']},{label:'Reference',types:['objections','talktracks']},{label:'My Scripts',types:['custom']}];var SE_TYPE_LABELS={coldcall:'Cold Call',discovery:'Discovery',demo:'Demo Meeting',closing:'Closing',onboarding:'Onboarding',objections:'Objections',talktracks:'Talk Track',custom:'Custom'};var SE_SUGGESTIONS={coldcall:['Rewrite step 1 to sound more natural','Make the pitch under 30 words','Add a line for when they say they are happy with their setup'],discovery:['Write 3 follow-up questions for step 2','Add a question about how they handle renewals','Make the agenda line more conversational'],demo:['Rewrite Renewal Autopilot step for a solo agent','Add a line for when they compare to EZLynx','Write a closing line that creates urgency'],objections:['Write a response for when they bring up HawkSoft','Make the price objection shorter','Add a response for not ready until after OEP'],custom:['Improve the flow of this script','Make this more conversational','Suggest a stronger opening line']};function seLoad(){try{seScripts=JSON.parse(localStorage.getItem('se2')||'[]')}catch(e){seScripts=[]}}
function sePersist(){localStorage.setItem('se2',JSON.stringify(seScripts))}
function seRenderLib(){
var el=document.getElementById('se-lib-list');
if(!el)return;
el.innerHTML='';

// ── PREBUILT TEMPLATES SECTION (always shown at top) ──
var prebuiltDiv=document.createElement('div');
prebuiltDiv.style.cssText='padding-bottom:4px;border-bottom:1px solid #2a2a38;margin-bottom:4px;';
var prebuiltLbl=document.createElement('div');
prebuiltLbl.style.cssText='font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#6366f1;padding:10px 14px 6px;';
prebuiltLbl.textContent='📋 Prebuilt Templates';
prebuiltDiv.appendChild(prebuiltLbl);

Object.keys(SE_TEMPLATES).forEach(function(k){
  var t=SE_TEMPLATES[k];
  var alreadyLoaded=seScripts.some(function(s){return s._tpl===k;});
  var btn=document.createElement('div');
  btn.style.cssText='display:flex;align-items:center;cursor:pointer;padding:7px 14px;font-size:12px;color:'+(alreadyLoaded?'#4a4a5a':'#c7d2fe')+';border-left:3px solid transparent;';
  btn.innerHTML=(alreadyLoaded?'✓ ':'+ ')+t.name;
  if(!alreadyLoaded){
    btn.onmouseover=function(){this.style.background='#1e1e2e';this.style.borderLeftColor='#6366f1';};
    btn.onmouseout=function(){this.style.background='';this.style.borderLeftColor='transparent';};
    btn.onclick=function(){seLoadTemplate(k);};
  }
  prebuiltDiv.appendChild(btn);
});
el.appendChild(prebuiltDiv);

// ── MY SCRIPTS SECTION ──
SE_GROUPS.forEach(function(g){
  var inGrp=seScripts.filter(function(s){return g.types.indexOf(s.type)>=0;});
  if(!inGrp.length)return;
  var grp=document.createElement('div');grp.style.cssText='padding-bottom:4px;';
  var lbl=document.createElement('div');lbl.style.cssText='font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#52525b;padding:10px 14px 4px;';lbl.textContent=g.label;
  grp.appendChild(lbl);
  inGrp.forEach(function(s){
    var item=document.createElement('div');item.style.cssText='display:flex;align-items:center;cursor:pointer;'+(seCurrentId===s.id?'background:#2a2a38;':'');
    var inner=document.createElement('div');inner.style.cssText='flex:1;padding:7px 14px;font-size:12.5px;color:'+(seCurrentId===s.id?'#6366f1':'#a1a1aa')+';overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border-left:3px solid '+(seCurrentId===s.id?'#6366f1':'transparent')+';font-weight:'+(seCurrentId===s.id?'600':'400')+';';inner.textContent=s.name||'Untitled';
    var del=document.createElement('button');del.style.cssText='padding:7px 8px;background:none;border:none;cursor:pointer;color:#52525b;font-size:11px;flex-shrink:0;';del.textContent='x';del.title='Delete';
    del.onclick=function(e){e.stopPropagation();seDelById(s.id);};
    item.appendChild(inner);item.appendChild(del);
    item.onclick=function(){seOpenScript(s.id);};
    grp.appendChild(item);
  });
  el.appendChild(grp);
});

// My Scripts empty state
var myScripts=seScripts.filter(function(s){return s.type==='custom';});
if(seScripts.length===0){
  var note=document.createElement('div');note.style.cssText='padding:12px 14px;font-size:11px;color:#4a4a5a;font-style:italic;';note.textContent='Load a template or create a new script.';el.appendChild(note);
}
}
function seOpenScript(id){if(seDirty&&!confirm('Unsaved changes. Discard?'))return;seCurrentId=id;seDirty=false;var s=seScripts.find(function(x){return x.id===id});if(!s)return;seShowEditor(s);seRenderLib();seUpdateAI(s);}
function seNewScript(){
  var id='s'+Date.now();
  var s={id:id,name:'My Script',type:'custom',steps:[{title:'Step 1',body:''}]};
  seScripts.push(s);sePersist();seRenderLib();
  setTimeout(function(){
    seOpenScript(id);
    var n=document.getElementById('se-script-name');
    if(n){n.focus();n.select();}
  },10);
}
function seLoadTemplate(k){var t=SE_TEMPLATES[k];if(!t)return;var id='s'+Date.now();var s={id:id,name:t.name,type:t.type,_tpl:k,steps:t.steps.map(function(st){return{title:st.title,body:st.body}})};seScripts.push(s);sePersist();seRenderLib();seOpenScript(id);}
function seDelById(id){if(!confirm('Delete this script?'))return;seScripts=seScripts.filter(function(s){return s.id!==id});if(seCurrentId===id){seCurrentId=null;seDirty=false;seShowEmpty()}
sePersist();seRenderLib();}
function seDeleteScript(){if(seCurrentId)seDelById(seCurrentId)}
function seShowEditor(s){var ew=document.getElementById('se-editor-wrap');var emp=document.getElementById('se-empty-wrap');if(ew){ew.style.display='flex';ew.style.flex='1';ew.style.flexDirection='column';ew.style.overflow='hidden';}
if(emp)emp.style.display='none';var n=document.getElementById('se-script-name');var t=document.getElementById('se-script-type');if(n)n.value=s.name||'';if(t)t.value=s.type||'custom';seRenderSteps(s.steps||[]);seUpdateCount(s.steps||[]);var st=document.getElementById('se-save-status');if(st)st.textContent='';}
function seShowEmpty(){var ew=document.getElementById('se-editor-wrap');var emp=document.getElementById('se-empty-wrap');if(ew)ew.style.display='none';if(emp){emp.style.display='flex';emp.style.flex='1';}}
function seRenderSteps(steps){var list=document.getElementById('se-steps-list');if(!list)return;list.innerHTML='';steps.forEach(function(st,i){list.appendChild(seMakeStep(st,i))});}
function seMakeStep(st,idx){var div=document.createElement('div');div.style.cssText='background:#f8f8fa;border:1.5px solid #e4e4e7;border-radius:10px;overflow:hidden;';div.draggable=true;var head=document.createElement('div');head.style.cssText='display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid #e4e4e7;background:#fff;';var num=document.createElement('div');num.style.cssText='width:22px;height:22px;border-radius:50%;background:#6366f1;color:#fff;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;';num.textContent=idx+1;var ti=document.createElement('input');ti.type='text';ti.value=st.title||'';ti.placeholder='Step name...';ti.style.cssText='flex:1;border:none;background:none;font-size:13px;font-weight:600;color:#09090b;font-family:inherit;outline:none;';ti.oninput=seMarkDirty;var drag=document.createElement('span');drag.textContent=':::';drag.style.cssText='cursor:grab;color:#d4d4d8;font-size:14px;padding:0 2px;';var del=document.createElement('button');del.textContent='x';del.style.cssText='background:none;border:none;color:#d4d4d8;font-size:12px;cursor:pointer;padding:2px 4px;border-radius:3px;';del.onclick=function(){div.remove();seRenumber();seMarkDirty()};head.append(num,ti,drag,del);var ta=document.createElement('textarea');ta.value=st.body||'';ta.placeholder='Write this step...';ta.style.cssText='width:100%;min-height:80px;border:none;background:none;padding:10px 12px;font-size:13px;color:#52525b;font-family:inherit;resize:vertical;outline:none;line-height:1.65;box-sizing:border-box;';ta.oninput=seMarkDirty;div.append(head,ta);div.addEventListener('dragstart',function(e){e.dataTransfer.effectAllowed='move';div.style.opacity='.4';seDragEl=div});div.addEventListener('dragend',function(){div.style.opacity='';seDragEl=null;seRenumber();seMarkDirty()});div.addEventListener('dragover',function(e){e.preventDefault();if(seDragEl&&seDragEl!==div){var items=Array.from(div.parentNode.children);if(items.indexOf(seDragEl)<items.indexOf(div))div.parentNode.insertBefore(seDragEl,div.nextSibling);else div.parentNode.insertBefore(seDragEl,div)}});return div;}
function seRenumber(){var list=document.getElementById('se-steps-list');if(!list)return;list.querySelectorAll('div>div:first-child>div:first-child').forEach(function(num,i){if(num&&!isNaN(parseInt(num.textContent)))num.textContent=i+1});seUpdateCount(seCollectSteps());}
function seAddStep(){var list=document.getElementById('se-steps-list');if(!list)return;var idx=list.children.length;var el=seMakeStep({title:'Step '+(idx+1),body:''},idx);list.appendChild(el);seMarkDirty();seUpdateCount(seCollectSteps());el.scrollIntoView({behavior:'smooth',block:'nearest'});}
function seUpdateCount(steps){var el=document.getElementById('se-step-count');if(el)el.textContent=steps.length+' step'+(steps.length!==1?'s':'');}
function seCollectSteps(){var list=document.getElementById('se-steps-list');if(!list)return[];return Array.from(list.children).map(function(div){var ti=div.querySelector('input');var ta=div.querySelector('textarea');return{title:ti?ti.value:'',body:ta?ta.value:''};});}
function seMarkDirty(){seDirty=true;var st=document.getElementById('se-save-status');if(st){st.textContent='Unsaved changes';st.style.color='#f59e0b';}
clearTimeout(seAutoTimer);seAutoTimer=setTimeout(seSave,2000);}
function seSave(){
  if(!seCurrentId)return;
  var s=seScripts.find(function(x){return x.id===seCurrentId});
  if(!s)return;
  var n=document.getElementById('se-script-name');
  var t=document.getElementById('se-script-type');
  var newType=t?t.value:s.type;
  var newName=n?n.value.trim()||'':s.name;
  // If name is still a default placeholder, auto-update it to match the type
  var defaults=['My Script','New Script','Untitled'];
  var typeNames={coldcall:'Cold Call Script',discovery:'Discovery Call Script',demo:'Demo Meeting Script',closing:'Closing Meeting Script',onboarding:'Onboarding Meeting Script',objections:'Objection Handling Script',battlecards:'Battle Card',talktracks:'Talk Track',custom:'My Script'};
  if(!newName||defaults.indexOf(newName)>=0){
    newName=typeNames[newType]||'My Script';
    if(n)n.value=newName;
  }
  s.name=newName;
  s.type=newType;
  s.steps=seCollectSteps();
  s.updatedAt=new Date().toISOString();
  sePersist();seDirty=false;
  var st=document.getElementById('se-save-status');
  if(st){st.textContent='✓ Saved';st.style.color='#10b981';}
  seRenderLib();
  if(typeof showToast==='function')showToast('Script saved!');
}

// ── ON A CALL SCRIPT PICKER ───────────────────────────────────────────
function showScriptPicker(){
  // If Script Editor isn't open, go there first
  var existing=document.getElementById('se-script-picker-modal');
  if(existing)existing.remove();

  seLoad();
  var modal=document.createElement('div');
  modal.id='se-script-picker-modal';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;';

  var box=document.createElement('div');
  box.style.cssText='background:#fff;border-radius:14px;padding:28px;width:480px;max-width:95vw;max-height:80vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,0.3);';

  var title=document.createElement('div');
  title.style.cssText='font-size:18px;font-weight:800;color:#09090b;margin-bottom:6px;';
  title.textContent='🔴 On A Call — Which script?';
  var sub=document.createElement('div');
  sub.style.cssText='font-size:13px;color:#71717a;margin-bottom:20px;';
  sub.textContent='Pick the script to open in the editor.';

  box.appendChild(title);
  box.appendChild(sub);

  // Group scripts by type
  var groups=[
    {label:'Cold Call',type:'coldcall',icon:'📞'},
    {label:'Discovery Call',type:'discovery',icon:'🔍'},
    {label:'Demo Meeting',type:'demo',icon:'🖥️'},
    {label:'Closing Meeting',type:'closing',icon:'🏆'},
    {label:'Onboarding Meeting',type:'onboarding',icon:'🚀'},
    {label:'Objection Handling',type:'objections',icon:'🛡️'},
    {label:'Talk Track',type:'talktracks',icon:'💬'},
    {label:'Custom',type:'custom',icon:'✏️'}
  ];

  var hasAny=false;
  groups.forEach(function(g){
    var matches=seScripts.filter(function(s){return s.type===g.type;});
    if(!matches.length)return;
    hasAny=true;
    var grpLabel=document.createElement('div');
    grpLabel.style.cssText='font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#a1a1aa;margin-bottom:6px;margin-top:14px;';
    grpLabel.textContent=g.icon+' '+g.label;
    box.appendChild(grpLabel);
    matches.forEach(function(s){
      var btn=document.createElement('button');
      btn.style.cssText='width:100%;text-align:left;padding:12px 14px;border:1.5px solid #e4e4e7;border-radius:8px;margin-bottom:6px;background:#fff;cursor:pointer;font-family:inherit;font-size:13px;font-weight:600;color:#09090b;display:flex;align-items:center;justify-content:space-between;';
      btn.innerHTML='<span>'+s.name+'</span><span style="font-size:11px;color:#6366f1;font-weight:700;">Open →</span>';
      btn.onmouseover=function(){this.style.background='#f5f5ff';this.style.borderColor='#6366f1';};
      btn.onmouseout=function(){this.style.background='#fff';this.style.borderColor='#e4e4e7';};
      btn.onclick=function(){
        modal.remove();
        showSection('scripteditor',null);
        setTimeout(function(){seOpenScript(s.id);},100);
      };
      box.appendChild(btn);
    });
  });

  if(!hasAny){
    var empty=document.createElement('div');
    empty.style.cssText='text-align:center;padding:24px;color:#a1a1aa;font-size:13px;';
    empty.innerHTML='No scripts saved yet.<br><br><button onclick="document.getElementById(\'se-script-picker-modal\').remove();showSection(\'scripteditor\',null);" style="background:#6366f1;color:#fff;border:none;border-radius:7px;padding:10px 18px;font-size:13px;font-weight:700;cursor:pointer;">Go to Script Editor →</button>';
    box.appendChild(empty);
  }

  var closeBtn=document.createElement('button');
  closeBtn.style.cssText='width:100%;margin-top:16px;padding:10px;border:1.5px solid #e4e4e7;border-radius:8px;background:#fff;color:#71717a;font-size:13px;cursor:pointer;font-family:inherit;';
  closeBtn.textContent='Cancel';
  closeBtn.onclick=function(){modal.remove();};
  box.appendChild(closeBtn);

  modal.appendChild(box);
  modal.onclick=function(e){if(e.target===modal)modal.remove();};
  document.body.appendChild(modal);
}
function seCopyAll(){var steps=seCollectSteps();var text=steps.map(function(s,i){return'Step '+(i+1)+(s.title?': '+s.title:'')+'\n'+s.body}).join('\n\n');if(navigator.clipboard)navigator.clipboard.writeText(text.trim());}
function seUpdateAI(s){var ctx=document.getElementById('se-ai-ctx');var sl=document.getElementById('se-sugg-list');if(ctx)ctx.textContent='Coaching: '+(SE_TYPE_LABELS[s.type]||s.name);if(!sl)return;sl.innerHTML='';var suggs=SE_SUGGESTIONS[s.type]||SE_SUGGESTIONS.custom;suggs.forEach(function(p){var btn=document.createElement('button');btn.style.cssText='width:100%;text-align:left;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:6px;padding:7px 10px;font-size:11px;color:rgba(255,255,255,.6);cursor:pointer;font-family:inherit;line-height:1.5;display:block;margin-bottom:5px;';btn.textContent=p;btn.onclick=function(){var inp=document.getElementById('se-ai-input');if(inp){inp.value=p;inp.focus()}};sl.appendChild(btn);});}
async function seAskAI(){var inp=document.getElementById('se-ai-input');var msgs=document.getElementById('se-ai-msgs');if(!inp||!msgs)return;var q=inp.value.trim();if(!q)return;var s=seScripts.find(function(x){return x.id===seCurrentId});var ctx=s?'Script: '+s.name+' ('+s.type+')\nSteps:\n'+seCollectSteps().map(function(st,i){return(i+1)+'. '+st.title+': '+st.body}).join('\n'):'';var uDiv=document.createElement('div');uDiv.style.cssText='background:rgba(99,102,241,.2);border-radius:8px;padding:8px 10px;font-size:12px;color:#c7d2fe;line-height:1.5;';uDiv.textContent=q;msgs.appendChild(uDiv);inp.value='';var bDiv=document.createElement('div');bDiv.style.cssText='background:rgba(255,255,255,.06);border-radius:8px;padding:8px 10px;font-size:12px;color:rgba(255,255,255,.75);line-height:1.6;';bDiv.textContent='...';msgs.appendChild(bDiv);bDiv.scrollIntoView({behavior:'smooth',block:'nearest'});try{var sys='You are an elite sales coach for AgentNav, a health insurance broker platform. Help reps write and improve call scripts. Be direct and give word-for-word suggestions.';if(ctx)sys+='\n\nCurrent script:\n'+ctx;var r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:600,system:sys,messages:[{role:'user',content:q}]})});var d=await r.json();bDiv.textContent=d.content&&d.content[0]?d.content[0].text:'Could not get response.';}catch(e){bDiv.textContent='Error: '+e.message;bDiv.style.color='#fca5a5';}}
function initScriptEditor(){
var fab=document.querySelector('.coach-fab');
if(fab)fab.style.display='none';
seLoad();seRenderLib();
if(seScripts.length===0){seShowEmpty();}else{seOpenScript(seScripts[0].id);}
}
function switchObjTab(tab){var script=document.getElementById('obj-panel-script');var library=document.getElementById('obj-panel-library');var tabScript=document.getElementById('obj-tab-script');var tabLibrary=document.getElementById('obj-tab-library');if(tab==='script'){if(script)script.style.display='block';if(library)library.style.display='none';if(tabScript){tabScript.style.borderBottomColor='#6366f1';tabScript.style.color='#6366f1';}
if(tabLibrary){tabLibrary.style.borderBottomColor='transparent';tabLibrary.style.color='#71717a';}}else{if(script)script.style.display='none';if(library)library.style.display='block';if(tabScript){tabScript.style.borderBottomColor='transparent';tabScript.style.color='#71717a';}
if(tabLibrary){tabLibrary.style.borderBottomColor='#6366f1';tabLibrary.style.color='#6366f1';}
renderUserObjections();}}
function getUserObjections(){try{return JSON.parse(localStorage.getItem('user-objections')||'[]');}catch(e){return[];}}
function saveUserObjections(list){localStorage.setItem('user-objections',JSON.stringify(list));}
function renderUserObjections(){var list=document.getElementById('obj-user-list');if(!list)return;var objections=getUserObjections();list.innerHTML='';objections.forEach(function(obj,idx){var el=document.createElement('div');el.style.cssText='background:#fff;border:1px solid #e4e4e7;border-radius:10px;overflow:hidden;margin-bottom:4px;';el.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;background:#fafafa;border-bottom:1px solid #e4e4e7;">'+'<div style="font-size:13.5px;font-style:italic;color:#09090b;font-weight:500;">"'+obj.title.replace(/"/g,'&quot;')+'"</div>'+'<div style="display:flex;gap:6px;">'+'<button onclick="editUserObjection('+idx+')" style="background:none;border:1px solid #e4e4e7;border-radius:6px;padding:4px 10px;font-size:11px;cursor:pointer;color:#6366f1;font-weight:600;">Edit</button>'+'<button onclick="deleteUserObjection('+idx+')" style="background:none;border:1px solid #fca5a5;border-radius:6px;padding:4px 10px;font-size:11px;cursor:pointer;color:#ef4444;font-weight:600;">Delete</button>'+'</div>'+'</div>'+'<div style="padding:14px 18px;font-size:13px;color:#52525b;line-height:1.7;">'+(obj.response||'<em style="color:#a1a1aa;">No response written yet.</em>')+'</div>';list.appendChild(el);});}
function addUserObjection(){var title=prompt('What objection do you want to handle?\n\nExamples:\n• "I already have a system"\n• "The timing isn\'t right"\n• "My team won\'t learn new software"');if(!title||!title.trim())return;var list=getUserObjections();list.push({title:title.trim(),response:''});saveUserObjections(list);renderUserObjections();switchObjTab('library');setTimeout(function(){editUserObjection(list.length-1);},100);}
function editUserObjection(idx){var list=getUserObjections();var obj=list[idx];if(!obj)return;var newTitle=prompt('Edit objection title:',obj.title);if(newTitle===null)return;var newResponse=prompt('Your response to this objection:\n(How do you handle it?)',obj.response||'');if(newResponse===null)return;list[idx]={title:newTitle.trim(),response:newResponse.trim()};saveUserObjections(list);renderUserObjections();showToast('Objection saved!');}
function deleteUserObjection(idx){if(!confirm('Delete this objection?'))return;var list=getUserObjections();list.splice(idx,1);saveUserObjections(list);renderUserObjections();}
function switchTTTab(tab){var prewritten=document.getElementById('tt-panel-prewritten');var mine=document.getElementById('tt-panel-mine');var tabPre=document.getElementById('tt-tab-prewritten');var tabMine=document.getElementById('tt-tab-mine');if(tab==='prewritten'){if(prewritten)prewritten.style.display='block';if(mine)mine.style.display='none';if(tabPre){tabPre.style.background='#0f0f17';tabPre.style.color='#fff';}
if(tabMine){tabMine.style.background='transparent';tabMine.style.color='#71717a';}}else{if(prewritten)prewritten.style.display='none';if(mine)mine.style.display='block';if(tabPre){tabPre.style.background='transparent';tabPre.style.color='#71717a';}
if(tabMine){tabMine.style.background='#0f0f17';tabMine.style.color='#fff';}
renderUserTalkTracks();}}
function getUserTalkTracks(){try{return JSON.parse(localStorage.getItem('user-talk-tracks')||'[]');}catch(e){return[];}}
function saveUserTalkTracks(list){localStorage.setItem('user-talk-tracks',JSON.stringify(list));}
function renderUserTalkTracks(){var listEl=document.getElementById('tt-user-list');var emptyEl=document.getElementById('tt-empty');if(!listEl)return;var tracks=getUserTalkTracks();listEl.innerHTML='';if(tracks.length===0){if(emptyEl)emptyEl.style.display='block';return;}
if(emptyEl)emptyEl.style.display='none';tracks.forEach(function(track,idx){var card=document.createElement('div');card.className='talk-card';card.style.cssText='position:relative;';card.innerHTML='<div class="talk-situation">'+(track.situation||'Custom Track')+'</div>'+'<h3>'+(track.title||'Untitled')+'</h3>'+'<p>'+(track.body||'<em style="color:#a1a1aa;">No content yet.</em>')+'</p>'+'<div style="display:flex;gap:8px;margin-top:10px;">'+'<button onclick="editUserTalkTrack('+idx+')" class="qa-btn">✏️ Edit</button>'+'<button onclick="qaCopy(\''+(track.body||'').replace(/'/g,"\\'")+'\')" class="qa-btn">📋 Copy</button>'+'<button onclick="deleteUserTalkTrack('+idx+')" class="qa-btn" style="color:#ef4444;border-color:#fca5a5;">Delete</button>'+'</div>';listEl.appendChild(card);});}
function addUserTalkTrack(){var situation=prompt('When does this talk track apply?\n\nExamples:\n• When they ask about integrations\n• After a warm referral intro\n• When they bring up budget concerns');if(!situation||!situation.trim())return;var title=prompt('Give this track a short title:','');if(title===null)return;var tracks=getUserTalkTracks();tracks.push({situation:situation.trim(),title:(title||'').trim(),body:''});saveUserTalkTracks(tracks);switchTTTab('mine');setTimeout(function(){editUserTalkTrack(tracks.length-1);},100);}
function editUserTalkTrack(idx){var tracks=getUserTalkTracks();var track=tracks[idx];if(!track)return;var newSit=prompt('When does this apply?',track.situation||'');if(newSit===null)return;var newTitle=prompt('Track title:',track.title||'');if(newTitle===null)return;var newBody=prompt('What do you say? (Your talk track):',track.body||'');if(newBody===null)return;tracks[idx]={situation:newSit.trim(),title:newTitle.trim(),body:newBody.trim()};saveUserTalkTracks(tracks);renderUserTalkTracks();showToast('Talk track saved!');}
function deleteUserTalkTrack(idx){if(!confirm('Delete this talk track?'))return;var tracks=getUserTalkTracks();tracks.splice(idx,1);saveUserTalkTracks(tracks);renderUserTalkTracks();}
async function researchCompetitor(){var input=document.getElementById('bc-competitor-input');var output=document.getElementById('bc-research-output');var btn=document.getElementById('bc-research-btn');var competitor=(input&&input.value.trim())||'';if(!competitor){showToast('Enter a competitor name first');return;}
if(!output||!btn)return;btn.disabled=true;btn.textContent='⏳ Researching...';output.style.display='block';output.innerHTML='<div style="padding:16px;color:rgba(255,255,255,0.6);font-size:13px;display:flex;align-items:center;gap:8px;"><div class="loading-spinner" style="width:18px;height:18px;border-width:2px;border-color:rgba(255,255,255,0.2);border-top-color:#6366f1;margin:0;"></div>Searching the web for '+competitor+'...</div>';try{var response=await fetch('/.netlify/functions/coach',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+(window._anAuthToken||'')},body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:1000,system:'You are a competitive intelligence researcher for AgentNav, a health insurance broker platform. When given a competitor name, research and provide a structured battle card. Use web search tool to find current information about the competitor. Format your response EXACTLY as:\n\nTIER: [Direct / Adjacent / Indirect]\nDESCRIPTION: [1-2 sentence description]\nSTRENGTH: [Their main strength]\nWEAKNESS: [Their true weakness vs AgentNav]\nACKNOWLEDGE: [One sentence to say that acknowledges their strength]\nWIN_WHEN: [bullet 1]\nWIN_WHEN: [bullet 2]\nWIN_WHEN: [bullet 3]\nLOSE_WHEN: [bullet 1]\nLOSE_WHEN: [bullet 2]\nREFRAME: [One reframe sentence to say on a call]',messages:[{role:'user',content:'Research this competitor for AgentNav battle card: '+competitor+'. Use web search to find current info about their product, pricing, strengths and weaknesses. Focus on the health insurance broker market.'}],tools:[{type:'web_search_20250305',name:'web_search'}]})});var data=await response.json();var text='';if(data.content){for(var i=0;i<data.content.length;i++){if(data.content[i].type==='text'){text+=data.content[i].text;}}}
if(!text||text.length<50){var r2=await fetch('/.netlify/functions/coach',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+(window._anAuthToken||'')},body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:800,system:'You are a competitive intelligence researcher for AgentNav, a health insurance broker platform. Format response exactly as specified.',messages:[{role:'user',content:'Create a battle card for: '+competitor+'. AgentNav sells to health insurance brokers — ACA, STM, Life, Ancillary. Format:\n\nTIER: [Direct / Adjacent / Indirect]\nDESCRIPTION: [1-2 sentence]\nSTRENGTH: [their main strength]\nWEAKNESS: [weakness vs AgentNav]\nACKNOWLEDGE: [acknowledge their strength]\nWIN_WHEN: [bullet 1]\nWIN_WHEN: [bullet 2]\nWIN_WHEN: [bullet 3]\nLOSE_WHEN: [bullet 1]\nLOSE_WHEN: [bullet 2]\nREFRAME: [reframe line]'}]})});var d2=await r2.json();if(d2.content)d2.content.forEach(function(b){if(b.type==='text')text+=b.text;});}
var bc=parseBattleCardText(text,competitor);renderNewBattleCard(bc,competitor);if(input)input.value='';}catch(err){output.innerHTML='<div style="padding:12px;color:#fca5a5;font-size:13px;">Could not research competitor. Check your connection. Error: '+err.message+'</div>';}
btn.disabled=false;btn.textContent='🤖 Research + Add Card';}
function parseBattleCardText(text,name){var get=function(key){var re=new RegExp(key+':[ \\t]*(.+)','i');var m=text.match(re);return m?m[1].trim():'';};var getAll=function(key){var re=new RegExp(key+':[ \\t]*(.+)','ig');var results=[];var m;while((m=re.exec(text))!==null)results.push(m[1].trim());return results;};return{name:name,tier:get('TIER')||'Adjacent',description:get('DESCRIPTION')||'',strength:get('STRENGTH')||'',weakness:get('WEAKNESS')||'',acknowledge:get('ACKNOWLEDGE')||'',winWhen:getAll('WIN_WHEN'),loseWhen:getAll('LOSE_WHEN'),reframe:get('REFRAME')||''};}
