// ============================================================
// PATCH 2 — Pricing fix + Commission Plan (admin-only)
// Include after app.js and after patch1 (fixes_patch.js)
// ============================================================

// ── FIX: Pricing logic + quote builder/PDF sync ──────────────
window._lastQuotePricing = null;

function anFormatMoney(n){
  if(!n || n <= 0) return '—';
  return '$' + Math.round(n).toLocaleString();
}

function anFormatPerPersonMonthly(n){
  if(!n || n <= 0) return '—';
  var v = Math.round(n * 100) / 100;
  return '$' + (Math.abs(v % 1) < 0.001 ? v.toLocaleString() : v.toFixed(2));
}

function calcUniversalPricing(agents, assistants){
  agents = Math.max(0, parseInt(agents, 10) || 0);
  assistants = Math.max(0, parseInt(assistants, 10) || 0);
  var monthly = 0, planName = '', planDesc = '', breakdown = '', custom = false;

  if(agents === 0){
    planName = 'Enter agents above';
  } else if(agents === 1){
    monthly = 79 + assistants * 25;
    planName = 'Independent Agent';
    planDesc = '1 agent' + (assistants ? ', ' + assistants + ' assistant' + (assistants > 1 ? 's' : '') : '');
    breakdown = '$79 flat' + (assistants ? ' + ' + assistants + ' asst @ $25' : '');
  } else if(agents <= 3){
    monthly = agents * 79 + assistants * 25;
    planName = 'Independent Agent';
    planDesc = agents + ' agents' + (assistants ? ', ' + assistants + ' assistant' + (assistants > 1 ? 's' : '') : '');
    breakdown = agents + ' × $79' + (assistants ? ' + ' + assistants + ' asst @ $25' : '');
  } else if(agents <= 9){
    var extraAgents = Math.max(0, agents - 4);
    var extraAssts = Math.max(0, assistants - 1);
    monthly = 247 + extraAgents * 60 + extraAssts * 15;
    planName = 'Small Agency';
    planDesc = agents + ' agents (1 asst included)';
    breakdown = '$247 base' +
      (extraAgents ? ' + ' + extraAgents + ' extra agent' + (extraAgents > 1 ? 's' : '') + ' @ $60' : '') +
      (extraAssts ? ' + ' + extraAssts + ' extra asst' + (extraAssts > 1 ? 's' : '') + ' @ $15' : '');
  } else if(agents === 10){
    var extraAssts10 = Math.max(0, assistants - 2);
    monthly = 597 + extraAssts10 * 10;
    planName = 'Large Agency';
    planDesc = '10 agents (2 assts included)';
    breakdown = '$597 base' + (extraAssts10 ? ' + ' + extraAssts10 + ' extra asst @ $10' : '');
  } else if(agents <= 50){
    monthly = agents * 30 + assistants * 10;
    planName = 'Growth Agency';
    planDesc = agents + ' agents @ $30/agent';
    breakdown = agents + ' × $30/agent' + (assistants ? ' + ' + assistants + ' asst @ $10' : '');
  } else if(agents <= 100){
    monthly = agents * 27 + assistants * 10;
    planName = 'Regional Agency';
    planDesc = agents + ' agents @ $27/agent';
    breakdown = agents + ' × $27/agent' + (assistants ? ' + ' + assistants + ' asst @ $10' : '');
  } else if(agents <= 200){
    monthly = agents * 24 + assistants * 10;
    planName = 'Scale Agency';
    planDesc = agents + ' agents @ $24/agent';
    breakdown = agents + ' × $24/agent' + (assistants ? ' + ' + assistants + ' asst @ $10' : '');
  } else if(agents <= 500){
    monthly = agents * 22 + assistants * 10;
    planName = 'Enterprise Agency';
    planDesc = agents + ' agents @ $22/agent';
    breakdown = agents + ' × $22/agent' + (assistants ? ' + ' + assistants + ' asst @ $10' : '');
  } else if(agents <= 10000){
    monthly = agents * 20 + assistants * 10;
    planName = 'National Agency';
    planDesc = agents + ' agents @ $20/agent';
    breakdown = agents + ' × $20/agent' + (assistants ? ' + ' + assistants + ' asst @ $10' : '');
  } else {
    custom = true;
    planName = 'Enterprise — Custom Pricing';
    planDesc = agents.toLocaleString() + '+ agents — contact us';
    breakdown = 'Custom quote required';
  }

  var annual = monthly > 0 ? Math.round(monthly * 12 * 0.8) : 0;
  var savings = monthly > 0 ? Math.round(monthly * 12 * 0.2) : 0;
  var totalPpl = agents + assistants;
  var perPersonList = totalPpl > 0 && monthly > 0 ? monthly / totalPpl : 0;
  var perPersonAnnual = totalPpl > 0 && annual > 0 ? annual / 12 / totalPpl : 0;

  return {
    agents: agents, assistants: assistants, monthly: monthly, annual: annual, savings: savings,
    planName: planName, planDesc: planDesc, breakdown: breakdown, custom: custom,
    totalPpl: totalPpl, perPersonList: perPersonList, perPersonAnnual: perPersonAnnual
  };
}

function anRenderUniversalPricing(p){
  var set = function(id, val){ var el = document.getElementById(id); if(el) el.textContent = val; };
  set('univ-plan-name', p.planName);
  set('univ-plan-desc', p.planDesc + (p.planDesc ? ' · all features' : ''));
  set('univ-monthly', p.monthly > 0 ? anFormatMoney(p.monthly) : '—');
  set('univ-annual', p.annual > 0 ? anFormatMoney(p.annual) + '/yr' : (p.custom ? 'Custom' : '—'));
  set('univ-per-person', p.custom ? '—' : anFormatPerPersonMonthly(p.perPersonAnnual));
  set('univ-savings', p.savings > 0 ? 'Save ' + anFormatMoney(p.savings) : '—');
  set('univ-breakdown', p.breakdown || 'Standard plan');
}

window.calcUniversal = function(){
  var agents = Math.max(0, parseInt((document.getElementById('univ-agents') || {value:'1'}).value, 10) || 0);
  var assts = Math.max(0, parseInt((document.getElementById('univ-assistants') || {value:'0'}).value, 10) || 0);
  var p = calcUniversalPricing(agents, assts);
  window._lastQuotePricing = p;
  anRenderUniversalPricing(p);
  if(typeof updateQuoteBuilderPreview === 'function') updateQuoteBuilderPreview();
};

window.applyCalcToQuote = function(){
  calcUniversal();
  var p = window._lastQuotePricing;
  if(p && p.monthly > 0){
    var cm = document.getElementById('qb-custom-monthly');
    var ca = document.getElementById('qb-custom-annual');
    if(cm && !cm.value) cm.value = Math.round(p.monthly);
    if(ca && !ca.value && p.annual > 0) ca.value = p.annual;
  }
  updateQuoteBuilderPreview();
  var el = document.getElementById('qb-fname') || document.getElementById('qb-agency');
  if(el) el.scrollIntoView({behavior:'smooth', block:'center'});
  if(typeof showToast === 'function') showToast('Price locked in — add setup fee or custom quote, then download PDF');
};

function anMergeQuotePricing(baseP){
  var p = Object.assign({}, baseP || {});
  p.setupFee = Math.max(0, parseFloat((document.getElementById('qb-setup-fee') || {}).value) || 0);
  p.annualDiscountPct = 20;
  var customOn = !!(document.getElementById('qb-custom-enabled') || {}).checked;
  if(!customOn) return p;

  var customMonthly = parseFloat((document.getElementById('qb-custom-monthly') || {}).value);
  var customAnnual = parseFloat((document.getElementById('qb-custom-annual') || {}).value);
  var annualPct = parseFloat((document.getElementById('qb-custom-annual-pct') || {}).value);
  var customPlan = ((document.getElementById('qb-custom-plan') || {}).value || '').trim();

  if(!isNaN(annualPct) && annualPct >= 0) p.annualDiscountPct = annualPct;
  if(customPlan) p.planName = customPlan;
  if(customMonthly > 0) p.monthly = customMonthly;
  if(customAnnual > 0){
    p.annual = Math.round(customAnnual);
    p.savings = p.monthly > 0 ? Math.max(0, Math.round(p.monthly * 12 - p.annual)) : 0;
  } else if(p.monthly > 0){
    p.annual = Math.round(p.monthly * 12 * (1 - p.annualDiscountPct / 100));
    p.savings = Math.round(p.monthly * 12 * (p.annualDiscountPct / 100));
  }
  p.isCustomQuote = true;
  p.custom = false;
  p.breakdown = 'Custom quote' + (customPlan ? ' — ' + customPlan : '');
  if(p.totalPpl > 0 && p.monthly > 0) p.perPersonList = p.monthly / p.totalPpl;
  if(p.totalPpl > 0 && p.annual > 0) p.perPersonAnnual = p.annual / 12 / p.totalPpl;
  return p;
}

window.updateCustomQuoteUI = function(){
  var on = !!(document.getElementById('qb-custom-enabled') || {}).checked;
  var wrap = document.getElementById('qb-custom-fields');
  if(wrap) wrap.style.display = on ? 'flex' : 'none';
  if(on){
    var p = window._lastQuotePricing;
    var cm = document.getElementById('qb-custom-monthly');
    var ca = document.getElementById('qb-custom-annual');
    var cp = document.getElementById('qb-custom-annual-pct');
    if(p){
      if(cm && !cm.value && p.monthly > 0) cm.value = Math.round(p.monthly);
      if(ca && !ca.value && p.annual > 0) ca.value = p.annual;
    }
    if(cp && !cp.value) cp.value = '20';
  }
  updateQuoteBuilderPreview();
};

window.updateQuoteBuilderPreview = function(){
  var preview = document.getElementById('qb-price-preview');
  if(!preview) return;
  var base = window._lastQuotePricing || calcUniversalPricing(
    (document.getElementById('univ-agents') || {}).value || 1,
    (document.getElementById('univ-assistants') || {}).value || 0
  );
  var p = anMergeQuotePricing(base);
  var parts = [];
  if(p.monthly > 0) parts.push(anFormatMoney(p.monthly) + '/mo');
  if(p.annual > 0) parts.push(anFormatMoney(p.annual) + '/yr (' + (p.annualDiscountPct || 20) + '% off)');
  if(p.setupFee > 0) parts.push(anFormatMoney(p.setupFee) + ' setup');
  preview.textContent = parts.length ? ('PDF will show: ' + parts.join(' · ')) : '';
};

function anGetQuoteDiscount(){
  var type = (document.getElementById('qb-discount-type') || {}).value || '';
  if(!type) return null;
  var pct = parseFloat((document.getElementById('qb-disc-pct') || {}).value) || 0;
  var months = parseInt((document.getElementById('qb-disc-months') || {}).value, 10) || 0;
  var flat = parseFloat((document.getElementById('qb-disc-flat') || {}).value) || 0;
  var custom = (document.getElementById('qb-disc-custom') || {}).value || '';
  var label = '';
  if(type === 'percent_months' && pct > 0 && months > 0){
    label = pct + '% off first ' + months + ' month' + (months > 1 ? 's' : '');
  } else if(type === 'free_months' && months > 0){
    label = months + ' free month' + (months > 1 ? 's' : '');
  } else if(type === 'flat_off' && flat > 0){
    label = anFormatMoney(flat) + '/mo off';
  } else if(type === 'custom' && custom.trim()){
    label = custom.trim();
  }
  return label ? { type: type, label: label, pct: pct, months: months, flat: flat, custom: custom } : null;
}

window.updateDiscountLabel = function(){
  var type = (document.getElementById('qb-discount-type') || {}).value || '';
  var wrap = document.getElementById('qb-discount-inputs');
  var preview = document.getElementById('qb-discount-preview');
  if(!wrap) return;
  if(!type){
    wrap.style.display = 'none';
    wrap.innerHTML = '';
    if(preview) preview.textContent = '';
    return;
  }
  wrap.style.display = 'block';
  if(type === 'percent_months'){
    wrap.innerHTML = '<input id="qb-disc-pct" type="number" min="1" max="100" placeholder="% off" style="width:100%;border:1.5px solid #fde68a;border-radius:6px;padding:6px 8px;font-size:12px;" oninput="updateDiscountLabel()">'
      + '<input id="qb-disc-months" type="number" min="1" max="24" placeholder="Months" style="width:100%;border:1.5px solid #fde68a;border-radius:6px;padding:6px 8px;font-size:12px;" oninput="updateDiscountLabel()">';
  } else if(type === 'free_months'){
    wrap.innerHTML = '<input id="qb-disc-months" type="number" min="1" max="24" placeholder="# free months" style="width:100%;border:1.5px solid #fde68a;border-radius:6px;padding:6px 8px;font-size:12px;" oninput="updateDiscountLabel()">';
  } else if(type === 'flat_off'){
    wrap.innerHTML = '<input id="qb-disc-flat" type="number" min="1" placeholder="$ off / month" style="width:100%;border:1.5px solid #fde68a;border-radius:6px;padding:6px 8px;font-size:12px;" oninput="updateDiscountLabel()">';
  } else if(type === 'custom'){
    wrap.innerHTML = '<input id="qb-disc-custom" type="text" placeholder="Custom discount text" style="width:100%;border:1.5px solid #fde68a;border-radius:6px;padding:6px 8px;font-size:12px;" oninput="updateDiscountLabel()">';
  }
  var disc = anGetQuoteDiscount();
  if(preview) preview.textContent = disc ? ('🏷️ ' + disc.label) : '';
};

function anBuildQuotePdfLines(p, prospect, discount){
  var annualLabel = 'Annual (' + (p.annualDiscountPct || 20) + '% off)';
  var perLabel = 'Per Person/mo (' + (p.annualDiscountPct || 20) + '% off)';
  var lines = [
    ['Plan', p.planName + (p.isCustomQuote ? ' (Custom)' : '')],
    ['Team Size', p.agents + ' agent' + (p.agents !== 1 ? 's' : '') + (p.assistants ? ', ' + p.assistants + ' assistant' + (p.assistants !== 1 ? 's' : '') : '')],
    ['Monthly Price', anFormatMoney(p.monthly) + '/month'],
    [annualLabel, anFormatMoney(p.annual) + '/year'],
    [perLabel, anFormatPerPersonMonthly(p.perPersonAnnual)],
    ['Annual Savings', anFormatMoney(p.savings)]
  ];
  if(p.setupFee > 0) lines.push(['One-Time Setup Fee', anFormatMoney(p.setupFee)]);
  if(discount) lines.push(['Special Offer', discount.label]);
  if(prospect.notes) lines.push(['Notes', prospect.notes]);
  return lines;
}

window.generateQuotePDF2 = function(){
  var baseP = window._lastQuotePricing || calcUniversalPricing(
    (document.getElementById('univ-agents') || {}).value || 1,
    (document.getElementById('univ-assistants') || {}).value || 0
  );
  var p = anMergeQuotePricing(baseP);
  if(baseP.custom && !p.isCustomQuote){
    if(typeof showToast === 'function') showToast('Enterprise tier — enable Custom Quote and enter pricing, then download PDF');
    return;
  }
  if(p.isCustomQuote && !(p.monthly > 0)){
    if(typeof showToast === 'function') showToast('Enter a custom monthly price (or use calculator first)');
    return;
  }
  if(!p.monthly && !p.annual){
    if(typeof showToast === 'function') showToast('No pricing to quote — run the calculator first');
    return;
  }
  if(!window.jspdf || !window.jspdf.jsPDF){
    if(typeof showToast === 'function') showToast('PDF library not loaded — refresh and try again');
    return;
  }
  var prospect = {
    fname: (document.getElementById('qb-fname') || {}).value || '',
    lname: (document.getElementById('qb-lname') || {}).value || '',
    agency: (document.getElementById('qb-agency') || {}).value || '',
    email: (document.getElementById('qb-email') || {}).value || '',
    phone: (document.getElementById('qb-phone') || {}).value || '',
    repname: (document.getElementById('qb-repname') || {}).value || '',
    notes: (document.getElementById('qb-notes') || {}).value || ''
  };
  var discount = anGetQuoteDiscount();
  var doc = new window.jspdf.jsPDF();
  var y = 18;
  doc.setFillColor(99, 102, 241);
  doc.rect(0, 0, 210, 34, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(20);
  doc.text('AgentNav Quote', 14, 18);
  doc.setFontSize(10);
  doc.text('Prepared ' + new Date().toLocaleDateString(), 14, 27);
  y = 44;
  doc.setTextColor(30, 30, 30);
  doc.setFontSize(12);
  doc.text('Prepared for', 14, y); y += 7;
  doc.setFontSize(11);
  var prospectName = ((prospect.fname + ' ' + prospect.lname).trim() || prospect.agency || 'Prospect');
  doc.text(prospectName, 14, y); y += 6;
  if(prospect.agency) { doc.text(prospect.agency, 14, y); y += 6; }
  if(prospect.email) { doc.text(prospect.email, 14, y); y += 6; }
  if(prospect.phone) { doc.text(prospect.phone, 14, y); y += 8; }
  if(prospect.repname){
    doc.setFontSize(10);
    doc.setTextColor(100, 100, 100);
    doc.text('Your rep: ' + prospect.repname, 14, y); y += 10;
  }
  doc.setTextColor(30, 30, 30);
  doc.setFontSize(13);
  doc.text('Pricing Summary', 14, y); y += 8;
  doc.setFontSize(10);
  anBuildQuotePdfLines(p, prospect, discount).forEach(function(row){
    doc.setFont(undefined, 'bold');
    doc.text(row[0] + ':', 14, y);
    doc.setFont(undefined, 'normal');
    doc.text(String(row[1]), 72, y);
    y += 7;
  });
  y += 4;
  doc.setFontSize(9);
  doc.setTextColor(90, 90, 90);
  doc.text(p.breakdown, 14, y); y += 8;
  doc.text('All plans include ACA/STM/Life quoting, CRM, SMS, Renewal Autopilot, and calendar sync.', 14, y, {maxWidth: 180});
  y += 12;
  doc.text('Questions? Reply to your rep or visit agentnav.com', 14, y);
  var safeName = (prospect.agency || prospectName || 'Quote').replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '') || 'Quote';
  doc.save('AgentNav-Quote-' + safeName + '.pdf');
  if(typeof showToast === 'function') showToast('PDF quote downloaded');
};

window.updateQuotePreview = function(){
  var agents = Math.max(1, parseInt((document.getElementById('qf-agents') || {}).value, 10) || 1);
  var assts = Math.max(0, parseInt((document.getElementById('qf-assistants') || {}).value, 10) || 0);
  var p = calcUniversalPricing(agents, assts);
  var set = function(id, val){ var el = document.getElementById(id); if(el) el.textContent = val; };
  set('qp-plan', p.planName);
  set('qp-team', p.agents + ' agent' + (p.agents !== 1 ? 's' : '') + ', ' + p.assistants + ' assistant' + (p.assistants !== 1 ? 's' : ''));
  set('qp-monthly', p.monthly > 0 ? anFormatMoney(p.monthly) + '/month' : 'Custom');
  set('qp-annual', p.annual > 0 ? anFormatMoney(p.annual) + '/year' : 'Custom');
  set('qp-per', p.custom ? '—' : anFormatPerPersonMonthly(p.perPersonAnnual));
};

window.generateQuotePDF = function(){
  var agents = Math.max(1, parseInt((document.getElementById('qf-agents') || {}).value, 10) || 1);
  var assts = Math.max(0, parseInt((document.getElementById('qf-assistants') || {}).value, 10) || 0);
  window._lastQuotePricing = calcUniversalPricing(agents, assts);
  var sync = [['qb-agency','qf-prospect'],['qb-email','qf-prospectemail'],['qb-repname','qf-repname'],['qb-notes','qf-notes']];
  sync.forEach(function(pair){
    var dst = document.getElementById(pair[0]);
    var src = document.getElementById(pair[1]);
    if(dst && src) dst.value = src.value;
  });
  generateQuotePDF2();
};

window.closeQuoteModal = function(){
  var m = document.getElementById('quoteModal');
  if(m) m.classList.remove('open');
};

