// ── Rate persistence helpers ─────────────────────────────────
function loadRates() {
  try {
    var r = JSON.parse(localStorage.getItem('comm-rates') || '{}');
    var soloEl = document.getElementById('rate-solo');
    var smallEl = document.getElementById('rate-small');
    var largeEl = document.getElementById('rate-large');
    if (soloEl && r.solo)  soloEl.value = r.solo;
    if (smallEl && r.small) smallEl.value = r.small;
    if (largeEl && r.large) largeEl.value = r.large;
  } catch(e) {}
  updateRatePreviews();
}
function saveRates() {
  try {
    var soloEl = document.getElementById('rate-solo');
    var smallEl = document.getElementById('rate-small');
    var largeEl = document.getElementById('rate-large');
    localStorage.setItem('comm-rates', JSON.stringify({
      solo:  soloEl  ? soloEl.value  : 11,
      small: smallEl ? smallEl.value : 10,
      large: largeEl ? largeEl.value : 8
    }));
  } catch(e) {}
  updateRatePreviews();
}
function getRates() {
  var soloEl  = document.getElementById('rate-solo');
  var smallEl = document.getElementById('rate-small');
  var largeEl = document.getElementById('rate-large');
  return {
    solo:  parseFloat((soloEl  ? soloEl.value  : 11)) / 100,
    small: parseFloat((smallEl ? smallEl.value : 10)) / 100,
    large: parseFloat((largeEl ? largeEl.value : 8))  / 100
  };
}
function updateRatePreviews() {
  var r = getRates();
  var sp = document.getElementById('rate-solo-preview');
  var smp = document.getElementById('rate-small-preview');
  var lp = document.getElementById('rate-large-preview');
  var sb = document.getElementById('rate-solo-badge');
  var smb = document.getElementById('rate-small-badge');
  var lb = document.getElementById('rate-large-badge');
  var gsl = document.getElementById('goal-solo-rate-lbl');
  var gsml = document.getElementById('goal-small-rate-lbl');
  var gll = document.getElementById('goal-large-rate-lbl');

  var soloVal = document.getElementById('rate-solo') ? parseFloat(document.getElementById('rate-solo').value) : 11;
  var smallVal = document.getElementById('rate-small') ? parseFloat(document.getElementById('rate-small').value) : 10;
  var largeVal = document.getElementById('rate-large') ? parseFloat(document.getElementById('rate-large').value) : 8;

  if (sp)  sp.textContent  = '$' + (79 * r.solo).toFixed(2) + '/agent/mo';
  if (smp) smp.textContent = '$' + (247 * r.small).toFixed(2) + '+/mo';
  if (lp)  lp.textContent  = '$' + (597 * r.large).toFixed(2) + '+/mo';
  if (sb)  sb.textContent  = soloVal + '%';
  if (smb) smb.textContent = smallVal + '%';
  if (lb)  lb.textContent  = largeVal + '%';
  if (gsl)  gsl.textContent  = '(' + soloVal + '%)';
  if (gsml) gsml.textContent = '(' + smallVal + '%)';
  if (gll)  gll.textContent  = '(' + largeVal + '%)';
}

