var _commBilling = 'monthly';

function setCommBilling(type) {
  _commBilling = type;
  var mb = document.getElementById('comm-monthly-btn');
  var ab = document.getElementById('comm-annual-btn');
  var note = document.getElementById('comm-billing-note');
  if (mb) { mb.style.background = type === 'monthly' ? '#6366f1' : 'transparent'; mb.style.color = type === 'monthly' ? '#fff' : '#71717a'; }
  if (ab) { ab.style.background = type === 'annual'  ? '#6366f1' : 'transparent'; ab.style.color = type === 'annual'  ? '#fff' : '#71717a'; }
  if (note) note.textContent = type === 'annual' ? 'Full year upfront (one-time payment)' : 'Recurring every month';
  calcCommission();
}

function getSmallMonthly(numAgents) {
  // Small: $247 base + $60 per agent above 4
  var n = Math.max(4, Math.min(9, numAgents));
  return 247 + Math.max(0, n - 4) * 60;
}

function getLargeMonthly(numAgents) {
  // Large: $597 base + $55 per agent above 10
  var n = Math.max(10, numAgents);
  return 597 + Math.max(0, n - 10) * 55;
}

function fmt(n) { return '$' + Math.round(n).toLocaleString(); }

function calcCommission() {
  var soloCount  = Math.max(0, parseInt(document.getElementById('comm-solo')  ?.value || 0));
  var smallCount = Math.max(0, parseInt(document.getElementById('comm-small') ?.value || 0));
  var largeCount = Math.max(0, parseInt(document.getElementById('comm-large') ?.value || 0));
  var smallAgents = Math.max(4, Math.min(9, parseInt(document.getElementById('comm-small-agents')?.value || 4)));
  var largeAgents = Math.max(10, parseInt(document.getElementById('comm-large-agents')?.value || 10));

  var soloMonthly  = soloCount  * 79;
  var smallMonthly = smallCount * getSmallMonthly(smallAgents);
  var largeMonthly = largeCount * getLargeMonthly(largeAgents);

  var soloComm, smallComm, largeComm, label;

  var rates = getRates ? getRates() : {solo:0.11, small:0.10, large:0.08};
  if (_commBilling === 'annual') {
    soloComm  = soloMonthly  * 12 * rates.solo;
    smallComm = smallMonthly * 12 * rates.small;
    largeComm = largeMonthly * 12 * rates.large;
    label = 'lump sum';
  } else {
    soloComm  = soloMonthly  * rates.solo;
    smallComm = smallMonthly * rates.small;
    largeComm = largeMonthly * rates.large;
    label = '/mo';
  }

  var total = soloComm + smallComm + largeComm;

  var set = function(id, val) { var el = document.getElementById(id); if (el) el.textContent = val; };
  set('comm-solo-out',   fmt(soloComm));
  set('comm-small-out',  fmt(smallComm));
  set('comm-large-out',  fmt(largeComm));
  set('comm-total-out',  fmt(total));
  ['comm-solo-label','comm-small-label','comm-large-label','comm-total-label'].forEach(function(id){ set(id, label); });

  // Annual projection (always monthly basis × 12)
  var rates2 = getRates ? getRates() : {solo:0.11, small:0.10, large:0.08};
  var annualProj = (soloMonthly * rates2.solo + smallMonthly * rates2.small + largeMonthly * rates2.large) * 12;
  set('comm-annual-proj', fmt(annualProj) + '/yr');

  // Breakdown text
  var lines = [];
  var soloRatePct = document.getElementById('rate-solo') ? document.getElementById('rate-solo').value : 11;
  var smallRatePct = document.getElementById('rate-small') ? document.getElementById('rate-small').value : 10;
  var largeRatePct = document.getElementById('rate-large') ? document.getElementById('rate-large').value : 8;
  if (soloCount)  lines.push(soloCount + ' solo agent' + (soloCount>1?'s':'') + ' × $79 × ' + soloRatePct + '%' + (_commBilling==='annual'?' × 12 mo':''));
  if (smallCount) lines.push(smallCount + ' small agenc' + (smallCount>1?'ies':'y') + ' @ ' + fmt(getSmallMonthly(smallAgents)) + '/mo × ' + smallRatePct + '%' + (_commBilling==='annual'?' × 12 mo':''));
  if (largeCount) lines.push(largeCount + ' large agenc' + (largeCount>1?'ies':'y') + ' @ ' + fmt(getLargeMonthly(largeAgents)) + '/mo × ' + largeRatePct + '%' + (_commBilling==='annual'?' × 12 mo':''));
  set('comm-breakdown', lines.join(' · ') || 'Enter values above to see your commission');
}

function calcGoal() {
  var goal = Math.max(0, parseFloat(document.getElementById('comm-goal')?.value || 0));
  var set = function(id, val) { var el = document.getElementById(id); if (el) el.textContent = val; };

  set('comm-goal-annual', fmt(goal * 12));

  var gr = getRates ? getRates() : {solo:0.11, small:0.10, large:0.08};
  // Solo only
  var soloPerUnit = 79 * gr.solo;
  var soloNeeded = goal > 0 ? Math.ceil(goal / soloPerUnit) : '—';
  set('goal-solo-count', goal > 0 ? soloNeeded + ' agents' : '—');

  // Small only
  var smallPerUnit = 247 * gr.small;
  var smallNeeded = goal > 0 ? Math.ceil(goal / smallPerUnit) : '—';
  set('goal-small-count', goal > 0 ? smallNeeded + ' agencies' : '—');

  // Large only
  var largePerUnit = 597 * gr.large;
  var largeNeeded = goal > 0 ? Math.ceil(goal / largePerUnit) : '—';
  set('goal-large-count', goal > 0 ? largeNeeded + ' agencies' : '—');

  // Mixed: 2 solo + 3 small + 1 large
  var mixedComm = 2 * soloPerUnit + 3 * smallPerUnit + 1 * largePerUnit;
  if (goal > 0) {
    var mixedSets = Math.ceil(goal / mixedComm);
    var mixedOut = (mixedSets*2) + ' solo, ' + (mixedSets*3) + ' small, ' + mixedSets + ' large';
    set('goal-mixed-out', mixedOut);
  } else {
    set('goal-mixed-out', '—');
  }
}

