// ── SUPPORTED LANGUAGES ─────────────────────────────────────
var SE_LANGUAGES = [
  { code: 'en',  label: 'English',    flag: '🇺🇸' },
  { code: 'es',  label: 'Español',    flag: '🇲🇽' },
  { code: 'pt',  label: 'Português',  flag: '🇧🇷' },
  { code: 'fr',  label: 'Français',   flag: '🇫🇷' },
  { code: 'other', label: 'Other',    flag: '🌐' }
];

function getLangLabel(code) {
  var l = SE_LANGUAGES.find(function(x){ return x.code === code; });
  return l ? l.flag + ' ' + l.label : '🌐 ' + (code || 'English');
}

window.seCloneSteps = function(steps) {
  return (steps || []).map(function(st) {
    return { title: st.title || '', time: st.time || '', body: st.body || '' };
  });
};

window.seEnsureScriptI18n = function(s) {
  if (!s) return;
  if (!s.i18n) s.i18n = {};
  if (!s.sourceSteps && s.steps && s.steps.length) {
    s.sourceSteps = seCloneSteps(s.steps);
  }
  if (s.sourceSteps && !s.i18n.en) s.i18n.en = seCloneSteps(s.sourceSteps);
};

window.seSnapshotStepsToLang = function(s, langCode, steps) {
  if (!s) return;
  seEnsureScriptI18n(s);
  var cloned = seCloneSteps(steps);
  if (!langCode || langCode === 'en') s.sourceSteps = cloned;
  s.i18n[langCode || 'en'] = cloned;
};

window.seGetStepsForLang = function(s, langCode) {
  if (!s) return [];
  seEnsureScriptI18n(s);
  langCode = langCode || 'en';
  if (langCode === 'en') return seCloneSteps(s.sourceSteps || s.steps || []);
  if (s.i18n && s.i18n[langCode] && s.i18n[langCode].length) return seCloneSteps(s.i18n[langCode]);
  return seCloneSteps(s.sourceSteps || s.steps || []);
};

window.seGetScriptStepsForLead = function(script, leadLang) {
  if (!script) return [];
  leadLang = leadLang || 'en';
  seEnsureScriptI18n(script);
  if (leadLang === 'en') return seCloneSteps(script.sourceSteps || script.steps || []);
  if (script.i18n && script.i18n[leadLang] && script.i18n[leadLang].length) {
    return seCloneSteps(script.i18n[leadLang]);
  }
  return seCloneSteps(script.sourceSteps || script.steps || []);
};

window.seParseTranslatedSteps = function(text) {
  if (!text) return [];
  var raw = text.trim();
  var jsonMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) raw = jsonMatch[1].trim();
  var start = raw.indexOf('[');
  var end = raw.lastIndexOf(']');
  if (start >= 0 && end > start) {
    try {
      var parsed = JSON.parse(raw.slice(start, end + 1));
      if (Array.isArray(parsed) && parsed.length) {
        return parsed.map(function(st, i) {
          return {
            title: (st.title || st.name || ('Step ' + (i + 1))).trim(),
            time: (st.time || '').trim(),
            body: (st.body || st.text || '').trim()
          };
        }).filter(function(st) { return st.title || st.body; });
      }
    } catch(e) {}
  }
  var stepPattern = /\d+\.\s+([^\n:]+)[:\n]([\s\S]*?)(?=\n\d+\.|$)/g;
  var parsed = [];
  var m;
  while ((m = stepPattern.exec(text)) !== null) {
    parsed.push({ title: m[1].trim(), time: '', body: m[2].trim() });
  }
  return parsed;
};

window.seShowTranslating = function(on, langLabel) {
  var wrap = document.getElementById('se-editor-wrap');
  if (!wrap) return;
  var el = document.getElementById('se-translate-overlay');
  if (!on) {
    if (el) el.remove();
    return;
  }
  if (el) return;
  el = document.createElement('div');
  el.id = 'se-translate-overlay';
  el.style.cssText = 'position:absolute;inset:0;background:rgba(255,255,255,0.92);z-index:50;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;';
  el.innerHTML = '<div style="width:32px;height:32px;border:3px solid #e4e4e7;border-top-color:#6366f1;border-radius:50%;animation:seSpin 0.8s linear infinite;"></div>'
    + '<div style="font-size:14px;font-weight:700;color:#09090b;">Translating to ' + (langLabel || 'target language') + '…</div>'
    + '<div style="font-size:12px;color:#71717a;">This usually takes a few seconds</div>';
  if (!document.getElementById('se-spin-style')) {
    var st = document.createElement('style');
    st.id = 'se-spin-style';
    st.textContent = '@keyframes seSpin{to{transform:rotate(360deg)}}';
    document.head.appendChild(st);
  }
  wrap.style.position = 'relative';
  wrap.appendChild(el);
};

window.seTranslateScriptToLang = function(sourceSteps, langCode, callback) {
  var langLabel = getLangLabel(langCode);
  if (langCode === 'other') {
    callback('Pick a specific language (Español, Português, or Français) to auto-translate.');
    return;
  }
  if (langCode === 'en') {
    callback(null, seCloneSteps(sourceSteps));
    return;
  }
  var system = 'You are an expert bilingual sales coach for AgentNav, a health insurance broker platform. '
    + 'Translate sales scripts naturally for native speakers — not word-for-word. '
    + 'Keep merge fields like {{first_name}}, {{rep_name}}, {{company}} exactly as-is. '
    + 'Return ONLY a JSON array: [{"title":"...","time":"0:00-0:15","body":"..."}]. Keep time ranges unchanged. No markdown, no commentary.';
  var prompt = 'Translate this sales script to ' + langLabel + '. Same number of steps, translated titles and bodies.\n\n'
    + JSON.stringify(sourceSteps);

  fetch('/.netlify/functions/coach', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (window._anAuthToken||'') },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 2000,
      system: system,
      messages: [{ role: 'user', content: prompt }]
    })
  })
  .then(function(r) { return r.json(); })
  .then(function(data) {
    var text = '';
    if (data.content) {
      for (var i = 0; i < data.content.length; i++) {
        if (data.content[i].type === 'text') text += data.content[i].text;
      }
    }
    if (!text && data.error) throw new Error(data.error.message || data.error);
    var parsed = seParseTranslatedSteps(text);
    if (!parsed.length) throw new Error('Could not parse translation — try again');
    callback(null, parsed);
  })
  .catch(function(e) { callback(e.message || 'Translation failed'); });
};

window.seOnLanguageChange = function(newLang) {
  var s = (typeof seScripts !== 'undefined' && seCurrentId)
    ? seScripts.find(function(x) { return x.id === seCurrentId; })
    : null;
  if (!s) {
    if (typeof seMarkDirty === 'function') seMarkDirty();
    return;
  }

  var langEl = document.getElementById('se-script-lang');
  var prevLang = s._seViewLang || s.lang || 'en';
  if (newLang === prevLang) return;

  var currentSteps = (typeof seCollectSteps === 'function') ? seCollectSteps() : [];
  seSnapshotStepsToLang(s, prevLang, currentSteps);

  s._seViewLang = newLang;
  s.lang = newLang;

  if (newLang === 'en') {
    if (langEl) langEl.value = 'en';
    if (typeof seRenderSteps === 'function') seRenderSteps(seGetStepsForLang(s, 'en'));
    if (typeof seMarkDirty === 'function') seMarkDirty();
    return;
  }

  if (s.i18n && s.i18n[newLang] && s.i18n[newLang].length) {
    if (langEl) langEl.value = newLang;
    if (typeof seRenderSteps === 'function') seRenderSteps(seGetStepsForLang(s, newLang));
    if (typeof seMarkDirty === 'function') seMarkDirty();
    return;
  }

  var source = seGetStepsForLang(s, 'en');
  var hasContent = source.some(function(st) { return st.body && st.body.trim().length > 5; });
    if (!hasContent) {
    if (langEl) langEl.value = newLang;
    if (typeof seRenderSteps === 'function') seRenderSteps([{ title: 'Step 1', time: '', body: '' }]);
    if (typeof seMarkDirty === 'function') seMarkDirty();
    return;
  }

  seShowTranslating(true, getLangLabel(newLang));
  if (langEl) langEl.disabled = true;

  seTranslateScriptToLang(source, newLang, function(err, translated) {
    seShowTranslating(false);
    if (langEl) langEl.disabled = false;
    if (err) {
      if (langEl) langEl.value = prevLang;
      s._seViewLang = prevLang;
      s.lang = prevLang;
      if (typeof showToast === 'function') showToast('Translation failed: ' + err);
      return;
    }
    s.i18n[newLang] = seCloneSteps(translated);
    if (langEl) langEl.value = newLang;
    if (typeof seRenderSteps === 'function') seRenderSteps(translated);
    if (typeof seMarkDirty === 'function') seMarkDirty();
    if (typeof seSave === 'function') seSave();
    if (typeof showToast === 'function') showToast('Translated to ' + getLangLabel(newLang));
  });
};

// ── INJECT LANGUAGE SELECTOR INTO SCRIPT EDITOR TOOLBAR ─────
document.addEventListener('DOMContentLoaded', function() {
  // Wait for the editor toolbar to exist
  setTimeout(function injectLangSelector() {
    var typeSelect = document.getElementById('se-script-type');
    if (!typeSelect) { setTimeout(injectLangSelector, 300); return; }
    if (document.getElementById('se-script-lang')) return; // already injected

    var langSelect = document.createElement('select');
    langSelect.id = 'se-script-lang';
    langSelect.style.cssText = 'border:1.5px solid #e4e4e7;border-radius:6px;padding:5px 8px;font-size:12px;font-weight:600;color:#52525b;font-family:inherit;cursor:pointer;outline:none;background:#fff;';
    langSelect.title = 'Preferred language — auto-translates script when changed';
    SE_LANGUAGES.forEach(function(l) {
      var opt = document.createElement('option');
      opt.value = l.code;
      opt.textContent = l.flag + ' ' + l.label;
      langSelect.appendChild(opt);
    });
    langSelect.onchange = function() { seOnLanguageChange(this.value); };
    // Insert after the type dropdown
    typeSelect.parentNode.insertBefore(langSelect, typeSelect.nextSibling);
  }, 200);
});

// ── PATCH seShowEditor to load lang field ────────────────────
var _origSeShowEditor = window.seShowEditor;
window.seShowEditor = function(s) {
  _origSeShowEditor(s);
  seEnsureScriptI18n(s);
  var viewLang = s.lang || 'en';
  s._seViewLang = viewLang;
  var langEl = document.getElementById('se-script-lang');
  if (langEl) langEl.value = viewLang;
  var steps = seGetStepsForLang(s, viewLang);
  if (typeof seRenderSteps === 'function') seRenderSteps(steps);
};

// ── PATCH seSave to persist lang field (stay in editor on auto-save) ──
var _origSeSave_lang = window.seSave;
window.seSave = function(goToLibrary) {
  if (!seCurrentId) return;
  var s = seScripts.find(function(x){ return x.id === seCurrentId; });
  if (!s) return;

  var n = document.getElementById('se-script-name');
  var t = document.getElementById('se-script-type');
  var l = document.getElementById('se-script-lang');
  var newType = t ? t.value : s.type;
  var newLang = l ? l.value : (s.lang || 'en');
  var newName = n ? n.value.trim() || '' : s.name;

  var defaults = ['My Script', 'New Script', 'Untitled'];
  var typeNames = { coldcall:'Cold Call Script', discovery:'Discovery Call Script', demo:'Demo Meeting Script', closing:'Closing Meeting Script', onboarding:'Onboarding Meeting Script', objections:'Objection Handling Script', battlecards:'Battle Card', talktracks:'Talk Track', custom:'My Script' };
  if (!newName || defaults.indexOf(newName) >= 0) {
    newName = typeNames[newType] || 'My Script';
    if (n) n.value = newName;
  }

  var currentSteps = seCollectSteps();
  seSnapshotStepsToLang(s, newLang, currentSteps);

  s.name = newName;
  s.type = newType;
  s.lang = newLang;
  s._seViewLang = newLang;
  s.steps = currentSteps;
  s.updatedAt = new Date().toISOString();
  sePersist();
  seDirty = false;

  var st = document.getElementById('se-save-status');
  if (st) { st.textContent = '✓ Saved'; st.style.color = '#10b981'; }
  seRenderLib();
  if (typeof showToast === 'function') showToast('Script saved!');

  if (goToLibrary) {
    setTimeout(function() {
      if (typeof showSection === 'function') {
        showSection('scriptlibrary', null);
        document.querySelectorAll('.nav-item').forEach(function(nb) {
          nb.classList.remove('active');
          if (nb.getAttribute('onclick') && nb.getAttribute('onclick').indexOf("'scriptlibrary'") !== -1)
            nb.classList.add('active');
        });
      }
    }, 300);
  }
};

// ── PATCH seNewScriptOfType to default lang='en' ─────────────
var _origSeNewScriptOfType = window.seNewScriptOfType;
window.seNewScriptOfType = function(type) {
  var id = 's' + Date.now();
  var typeNames = { coldcall:'Cold Call Script', discovery:'Discovery Call Script', demo:'Demo Meeting Script', closing:'Closing Meeting Script', onboarding:'Onboarding Meeting Script', objections:'Objection Handling Script', battlecards:'Battle Card', talktracks:'Talk Track', custom:'New Script' };
  var s = { id:id, name:typeNames[type]||'New Script', type:type, lang:'en', steps:[{title:'Step 1', time:'', body:''}], sourceSteps:[{title:'Step 1', time:'', body:''}], i18n:{ en:[{title:'Step 1', time:'', body:''}] } };
  seScripts.push(s); sePersist(); seRenderLib();
  setTimeout(function(){ seOpenScript(id); var nEl = document.getElementById('se-script-name'); if(nEl){nEl.focus();nEl.select();} }, 50);
};

// ── REPLACE renderScriptLibrary with language-aware version ──
window.renderScriptLibrary = function() {
  var container = document.getElementById('scriptlibrary-content');
  if (!container) return;
  seLoad();
  container.innerHTML = '';

  var LANG_TABS = [
    { code: 'en',    label: '🇺🇸 English',   color: '#6366f1' },
    { code: 'es',    label: '🇲🇽 Español',    color: '#10b981' },
    { code: 'pt',    label: '🇧🇷 Português',  color: '#f59e0b' },
    { code: 'fr',    label: '🇫🇷 Français',   color: '#ec4899' },
    { code: 'other', label: '🌐 Other',       color: '#8b5cf6' }
  ];

  var LIBRARY_CATS = [
    { label:'Cold Call',   type:'coldcall',   icon:'📞', color:'#6366f1' },
    { label:'Discovery',   type:'discovery',  icon:'🔍', color:'#8b5cf6' },
    { label:'Demo',        type:'demo',       icon:'🖥️', color:'#06b6d4' },
    { label:'Closing',     type:'closing',    icon:'🏆', color:'#f59e0b' },
    { label:'Onboarding',  type:'onboarding', icon:'🚀', color:'#10b981' },
    { label:'Objections',  type:'objections', icon:'🛡️', color:'#ef4444' },
    { label:'Battle Cards',type:'battlecards',icon:'⚔️', color:'#ec4899' },
    { label:'Talk Tracks', type:'talktracks', icon:'💬', color:'#14b8a6' },
    { label:'Custom',      type:'custom',     icon:'✏️', color:'#a1a1aa' }
  ];

  // Determine which language tabs actually have scripts
  var activeLangTabs = LANG_TABS.filter(function(lt) {
    return seScripts.some(function(s) {
      var sLang = s.lang || 'en';
      if (lt.code === 'other') return ['en','es','pt','fr'].indexOf(sLang) === -1;
      return sLang === lt.code;
    });
  });
  // Always show English
  if (!activeLangTabs.find(function(t){ return t.code === 'en'; }))
    activeLangTabs.unshift(LANG_TABS[0]);

  // Language tab bar
  var langBar = document.createElement('div');
  langBar.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-bottom:20px;';

  var catPanelWrap = document.createElement('div');

  var activeLang = activeLangTabs[0].code;

  function renderCatPanel(langCode) {
    catPanelWrap.innerHTML = '';

    var langScripts = seScripts.filter(function(s) {
      var sLang = s.lang || 'en';
      if (langCode === 'other') return ['en','es','pt','fr'].indexOf(sLang) === -1;
      return sLang === langCode;
    });

    // Category tabs within this language
    var catTabBar = document.createElement('div');
    catTabBar.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-bottom:20px;border-bottom:2px solid #e4e4e7;padding-bottom:0;overflow-x:auto;';

    var catPanel = document.createElement('div');
    catPanel.style.cssText = 'min-height:180px;';

    var activeCat = LIBRARY_CATS[0];

    function renderScriptGrid(cat) {
      catPanel.innerHTML = '';

      var scripts = langScripts.filter(function(s){ return s.type === cat.type; });

      var hdr = document.createElement('div');
      hdr.style.cssText = 'display:flex;align-items:center;gap:10px;margin-bottom:16px;';
      hdr.innerHTML = '<div style="width:36px;height:36px;border-radius:10px;background:'+cat.color+'18;display:flex;align-items:center;justify-content:center;font-size:18px;">'+cat.icon+'</div>'
        +'<div><div style="font-size:15px;font-weight:700;color:#09090b;">'+cat.label+' Scripts</div>'
        +'<div style="font-size:12px;color:#a1a1aa;">'+getLangLabel(langCode)+' · '+scripts.length+' script'+(scripts.length!==1?'s':'')+'</div></div>'
        +'<button onclick="showSection(\'scripteditor\',null);setTimeout(function(){var s=seNewScriptWithLang(\''+cat.type+'\',\''+langCode+'\');},150);" style="margin-left:auto;padding:8px 14px;background:'+cat.color+';color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">+ New</button>';
      catPanel.appendChild(hdr);

      if (!scripts.length) {
        var empty = document.createElement('div');
        empty.style.cssText = 'text-align:center;padding:40px 20px;color:#a1a1aa;border:2px dashed #e4e4e7;border-radius:12px;';
        empty.innerHTML = '<div style="font-size:28px;margin-bottom:8px;">'+cat.icon+'</div>'
          +'<div style="font-size:13px;font-weight:600;color:#71717a;margin-bottom:4px;">No '+cat.label+' scripts in '+getLangLabel(langCode)+'</div>'
          +'<button onclick="showSection(\'scripteditor\',null);setTimeout(function(){seNewScriptWithLang(\''+cat.type+'\',\''+langCode+'\');},150);" style="margin-top:12px;background:'+cat.color+';color:#fff;border:none;border-radius:7px;padding:8px 16px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">+ Create One</button>';
        catPanel.appendChild(empty);
        return;
      }

      var grid = document.createElement('div');
      grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px;';

      scripts.forEach(function(s) {
        var card = document.createElement('div');
        card.style.cssText = 'background:#fff;border:1.5px solid #e4e4e7;border-radius:10px;padding:16px;cursor:pointer;transition:border-color 0.15s,box-shadow 0.15s;';
        card.onmouseover = function(){ this.style.borderColor=cat.color; this.style.boxShadow='0 4px 12px '+cat.color+'22'; };
        card.onmouseout  = function(){ this.style.borderColor='#e4e4e7'; this.style.boxShadow=''; };

        var steps = s.steps || [];
        var hasContent = steps.some(function(st){ return st.body && st.body.trim(); });
        var preview = steps.length ? steps[0].title : 'No steps yet';

        card.innerHTML = '<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:8px;">'
          +'<div style="font-size:14px;font-weight:700;color:#09090b;flex:1;">'+s.name+'</div>'
          +'<div style="width:8px;height:8px;border-radius:50%;background:'+(hasContent?cat.color:'#e4e4e7')+';margin-top:4px;flex-shrink:0;"></div>'
          +'</div>'
          +'<div style="font-size:11px;color:#a1a1aa;margin-bottom:4px;">'+getLangLabel(s.lang||'en')+'</div>'
          +'<div style="font-size:12px;color:#71717a;margin-bottom:12px;">'+steps.length+' step'+(steps.length!==1?'s':'')+' · '+(hasContent?'Has content':'Empty')+'</div>'
          +'<div style="font-size:12px;color:#a1a1aa;font-style:italic;margin-bottom:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+preview+'</div>'
          +'<div style="display:flex;gap:6px;">'
          +'<button onclick="event.stopPropagation();showSection(\'scripteditor\',null);setTimeout(function(){seOpenScript(\''+s.id+'\');},150);" style="flex:1;padding:7px;background:'+cat.color+';color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">Edit</button>'
          +'<button onclick="event.stopPropagation();seLoad();seScripts=seScripts.filter(function(x){return x.id!==\''+s.id+'\'});sePersist();renderScriptLibrary();" style="padding:7px 10px;background:#fff;color:#ef4444;border:1.5px solid #fca5a5;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;">Delete</button>'
          +'</div>';

        card.onclick = function(){ showSection('scripteditor',null); setTimeout(function(){ seOpenScript(s.id); }, 150); };
        grid.appendChild(card);
      });
      catPanel.appendChild(grid);
    }

    // Build category tabs
    LIBRARY_CATS.forEach(function(cat, i) {
      var count = langScripts.filter(function(s){ return s.type === cat.type; }).length;
      var tab = document.createElement('button');
      tab.style.cssText = 'padding:9px 14px;font-size:12px;font-weight:600;border:none;border-bottom:2.5px solid transparent;background:none;cursor:pointer;font-family:inherit;color:#71717a;white-space:nowrap;transition:all 0.12s;display:flex;align-items:center;gap:5px;margin-bottom:-2px;';
      tab.innerHTML = '<span>'+cat.icon+'</span><span>'+cat.label+'</span>'
        +(count ? '<span style="background:'+cat.color+'18;color:'+cat.color+';font-size:10px;font-weight:700;border-radius:10px;padding:1px 6px;">'+count+'</span>' : '');

      tab.onclick = function() {
        Array.from(catTabBar.children).forEach(function(tb){
          tb.style.borderBottomColor='transparent'; tb.style.color='#71717a';
        });
        tab.style.borderBottomColor = cat.color;
        tab.style.color = cat.color;
        activeCat = cat;
        renderScriptGrid(cat);
      };

      if (i === 0) {
        tab.style.borderBottomColor = cat.color;
        tab.style.color = cat.color;
        activeCat = cat;
      }
      catTabBar.appendChild(tab);
    });

    catPanelWrap.appendChild(catTabBar);
    catPanelWrap.appendChild(catPanel);
    renderScriptGrid(activeCat);

    // Empty state for whole language
    if (langScripts.length === 0) {
      catPanel.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#a1a1aa;">'
        +'<div style="font-size:40px;margin-bottom:12px;">'+getLangLabel(langCode).split(' ')[0]+'</div>'
        +'<div style="font-size:15px;font-weight:700;color:#71717a;margin-bottom:6px;">No '+getLangLabel(langCode)+' scripts yet</div>'
        +'<div style="font-size:13px;margin-bottom:16px;">Create your first script in this language.</div>'
        +'<button onclick="showSection(\'scripteditor\',null);" style="background:#6366f1;color:#fff;border:none;border-radius:8px;padding:10px 20px;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Open Script Editor →</button>'
        +'</div>';
    }
  }

  // Build language tabs
  activeLangTabs.forEach(function(lt, i) {
    var scriptCount = seScripts.filter(function(s) {
      var sLang = s.lang || 'en';
      if (lt.code === 'other') return ['en','es','pt','fr'].indexOf(sLang) === -1;
      return sLang === lt.code;
    }).length;

    var tab = document.createElement('button');
    var isActive = i === 0;
    tab.style.cssText = 'padding:8px 16px;border-radius:20px;font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;border:1.5px solid '+(isActive?lt.color:'#e4e4e7')+';background:'+(isActive?lt.color+'18':'transparent')+';color:'+(isActive?lt.color:'#71717a')+';transition:all 0.12s;display:flex;align-items:center;gap:6px;';
    tab.innerHTML = lt.label + (scriptCount > 0 ? ' <span style="background:'+lt.color+'18;color:'+lt.color+';font-size:10px;font-weight:700;padding:1px 7px;border-radius:10px;">'+scriptCount+'</span>' : '');

    tab.onclick = function() {
      Array.from(langBar.children).forEach(function(tb) {
        var ltc = tb._langCode;
        var ldata = LANG_TABS.find(function(x){ return x.code===ltc; })||{color:'#6366f1'};
        tb.style.borderColor = '#e4e4e7';
        tb.style.background = 'transparent';
        tb.style.color = '#71717a';
      });
      tab.style.borderColor = lt.color;
      tab.style.background = lt.color + '18';
      tab.style.color = lt.color;
      activeLang = lt.code;
      renderCatPanel(lt.code);
    };

    tab._langCode = lt.code;
    langBar.appendChild(tab);
  });

  // Add "+ New Language" button
  var addLangBtn = document.createElement('button');
  addLangBtn.style.cssText = 'padding:8px 14px;border-radius:20px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;border:1.5px dashed #d4d4d8;background:transparent;color:#a1a1aa;';
  addLangBtn.textContent = '+ Add Language';
  addLangBtn.onclick = function() {
    // Open script editor with a prompt to pick language
    showSection('scripteditor', null);
    setTimeout(function() {
      seNewScript();
      setTimeout(function() {
        var langEl = document.getElementById('se-script-lang');
        if (langEl) { langEl.focus(); showToast('Pick a language from the dropdown above, then write your script.'); }
      }, 200);
    }, 100);
  };
  langBar.appendChild(addLangBtn);

  container.appendChild(langBar);
  container.appendChild(catPanelWrap);
  renderCatPanel(activeLang);
};

// ── Helper: create a new script with specific lang preset ────
window.seNewScriptWithLang = function(type, lang) {
  var id = 's' + Date.now();
  var typeNames = { coldcall:'Cold Call Script', discovery:'Discovery Call Script', demo:'Demo Meeting Script', closing:'Closing Meeting Script', onboarding:'Onboarding Meeting Script', objections:'Objection Handling Script', battlecards:'Battle Card', talktracks:'Talk Track', custom:'New Script' };
  var s = { id:id, name:typeNames[type]||'New Script', type:type, lang:lang||'en', steps:[{title:'Step 1', body:''}] };
  seScripts.push(s); sePersist(); seRenderLib();
  setTimeout(function(){
    seOpenScript(id);
    var langEl = document.getElementById('se-script-lang');
    if (langEl) langEl.value = lang || 'en';
    var nEl = document.getElementById('se-script-name');
    if (nEl) { nEl.focus(); nEl.select(); }
  }, 50);
  return id;
};

// ── Migrate existing scripts to have lang='en' ───────────────
(function migrateScripts() {
  try {
    var scripts = JSON.parse(localStorage.getItem('se2') || '[]');
    var changed = false;
    scripts.forEach(function(s) {
      if (!s.lang) { s.lang = 'en'; changed = true; }
    });
    if (changed) localStorage.setItem('se2', JSON.stringify(scripts));
  } catch(e) {}
})();

// Re-hook showSection for scriptlibrary re-render

console.log('[PATCH 5] Multi-language scripts loaded.');

// ─── inline block 7 ───────────────────────
// ── UNIFIED showSection — single override replacing all patches ──
(function() {
  var _base = window.showSection;
  window.showSection = function(id, btn) {
    _base(id, btn);
    // Persist active section so refresh returns to same place
    try { localStorage.setItem('an-active-section', id); } catch(e) {}
    // Always scroll main content to top on section change
    var mainEl = document.querySelector('.main');
    if (mainEl) mainEl.scrollTop = 0;
    window.scrollTo(0, 0);

    if (id === 'scriptlibrary') {
      setTimeout(function() {
        if (typeof renderScriptLibrary === 'function') renderScriptLibrary();
      }, 50);
    }

    if (id === 'ai-assistant') {
      setTimeout(function() {
        var sec = document.getElementById('section-ai-assistant');
        if (sec && typeof renderAIAssistant === 'function') {
          if (!sec.querySelector('#ai-main')) renderAIAssistant();
        }
      }, 50);
    }
    if (id === 'dashboard') {
      setTimeout(function() {
        if (typeof renderSalesDashboard === 'function') renderSalesDashboard();
      }, 50);
    }
    if (id === 'competition') {
      setTimeout(function() {
        if (typeof renderCompetitionSection === 'function') renderCompetitionSection();
      }, 50);
    }
    if (id === 'commission') {
      setTimeout(function() {
        var sec = document.getElementById('section-commission');
        if (sec && typeof buildCommissionHTML === 'function') {
          sec.innerHTML = buildCommissionHTML();
        }
        if (typeof loadRates === 'function') loadRates();
        if (typeof calcCommission === 'function') calcCommission();
        if (typeof calcGoal === 'function') calcGoal();
      }, 50);
    }
    if (id === 'admin') {
      setTimeout(function() {
        if (typeof switchAdminTab === 'function') switchAdminTab('scripts');
      }, 50);
    }
    if (id === 'pricing') {
      setTimeout(function() {
        if (typeof calcUniversal === 'function') calcUniversal();
      }, 50);
    }
    var scriptSections = ['pitches','coldcall','discovery','demo','closing','onboarding','objections','battlecards','talktracks'];
    if (scriptSections.indexOf(id) >= 0) {
      setTimeout(function() {
        if (typeof loadMyScript === 'function') loadMyScript(id);
      }, 50);
    }
    if (id === 'opportunities') {
      setTimeout(function() {
        if (typeof anMountOpportunitiesSection === 'function') anMountOpportunitiesSection();
        else if (typeof renderOpportunities === 'function') renderOpportunities();
      }, 50);
    }
  };
})();

// ─── inline block 8 ───────────────────────
// ============================================================
// PATCH 7 — Fix AI panel: route through /.netlify/functions/coach
// Full chat history, markdown render, typing indicator
// ============================================================

// ── Simple markdown renderer (ES5) ──────────────────────────
function renderMD(text) {
  if (!text) return '';
  var s = text
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>')
    .replace(/\*([^*\n]+)\*/g,'<em>$1</em>')
    .replace(/`([^`\n]+)`/g,'<code style="background:rgba(255,255,255,0.15);padding:1px 5px;border-radius:3px;font-size:11px;font-family:monospace;">$1</code>');

  // Bullets
  var lines = s.split('\n');
  var out = [];
  var inList = false;
  for (var i = 0; i < lines.length; i++) {
    var ln = lines[i];
    var bulletMatch = ln.match(/^[\-\*\u2022] (.+)/);
    var numberedMatch = ln.match(/^(\d+)\. (.+)/);
    if (bulletMatch) {
      if (!inList) { out.push('<ul style="margin:6px 0 6px 16px;padding:0;">'); inList = true; }
      out.push('<li style="margin:3px 0;">' + bulletMatch[1] + '</li>');
    } else if (numberedMatch) {
      if (!inList) { out.push('<ol style="margin:6px 0 6px 16px;padding:0;">'); inList = 'ol'; }
      out.push('<li style="margin:3px 0;">' + numberedMatch[2] + '</li>');
    } else {
      if (inList) { out.push(inList === 'ol' ? '</ol>' : '</ul>'); inList = false; }
      if (ln.trim() === '') {
        out.push('<div style="height:6px;"></div>');
      } else {
        out.push('<div style="margin:2px 0;line-height:1.65;">' + ln + '</div>');
      }
    }
  }
  if (inList) out.push(inList === 'ol' ? '</ol>' : '</ul>');
  return out.join('');
}

// ── AI history per script ────────────────────────────────────
var _seAIHistories = {};

function getAIHistory() {
  if (!seCurrentId) return [];
  if (!_seAIHistories[seCurrentId]) _seAIHistories[seCurrentId] = [];
  return _seAIHistories[seCurrentId];
}

// ── Append a chat bubble ─────────────────────────────────────
function seAppendMsg(role, html, id) {
  var msgs = document.getElementById('se-ai-msgs');
  if (!msgs) return null;
  var wrap = document.createElement('div');
  wrap.style.cssText = 'display:flex;flex-direction:column;gap:2px;' + (id ? '' : '');
  if (id) wrap.id = id;

  var label = document.createElement('div');
  label.style.cssText = 'font-size:9px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;margin-bottom:3px;' +
    (role === 'user' ? 'color:#818cf8;text-align:right;' : 'color:#10b981;');
  label.textContent = role === 'user' ? 'You' : 'AI Coach';

  var bubble = document.createElement('div');
  bubble.style.cssText = 'border-radius:10px;padding:9px 12px;font-size:12px;line-height:1.6;' +
    (role === 'user'
      ? 'background:rgba(99,102,241,0.2);color:#c7d2fe;margin-left:16px;text-align:right;'
      : 'background:rgba(255,255,255,0.07);color:rgba(255,255,255,0.85);margin-right:8px;');
  bubble.innerHTML = html;

  wrap.appendChild(label);
  wrap.appendChild(bubble);
  msgs.appendChild(wrap);
  wrap.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  return bubble;
}

// ── Clear AI chat for current script ────────────────────────
function seClearAIChat() {
  if (seCurrentId) _seAIHistories[seCurrentId] = [];
  var msgs = document.getElementById('se-ai-msgs');
  if (msgs) msgs.innerHTML = '';
}

// ── Main override: seAskAI ───────────────────────────────────
window.seAskAI = function() {
  var inp = document.getElementById('se-ai-input');
  var sendBtn = document.querySelector('button[onclick="seAskAI()"]');
  if (!inp) return;
  var q = inp.value.trim();
  if (!q) return;

  // Build script context
  var s = (typeof seScripts !== 'undefined') && seScripts
    ? seScripts.find(function(x) { return x.id === seCurrentId; }) : null;
  var scriptCtx = '';
  if (s && typeof seCollectSteps === 'function') {
    var steps = seCollectSteps();
    scriptCtx = '\n\nCurrent script being edited: "' + s.name + '" (' + s.type + ')\n' +
      steps.map(function(st, i) {
        return (i + 1) + '. ' + st.title + ':\n' + (st.body || '(empty)');
      }).join('\n\n');
  }

  var system = 'You are an expert AgentNav sales coach embedded inside a sales tool. ' +
    'AgentNav is a health insurance broker platform with: ACA/STM/Life/Ancillary quoting, ' +
    'HealthSherpa + EDE integration, full CRM + household tracking, SMS with dedicated number, ' +
    'Renewal Autopilot for OEP, Google Calendar sync, policy tracker, white-label branding. ' +
    'Pricing: 1 agent $79/mo, 2-3 agents $79/ea, Small Agency (4+ agents) $247 base, Large Agency (10+ agents) $597 base. ' +
    'You help reps write and improve call scripts. Give word-for-word suggestions. Be direct and specific. ' +
    'When asked to rewrite a step, output the full rewritten text ready to copy in.' +
    scriptCtx;

  var history = getAIHistory();

  // Show user bubble
  inp.value = '';
  seAppendMsg('user', q.replace(/</g, '&lt;'));

  // Show typing indicator
  var thinkId = 'ai-think-' + Date.now();
  var thinkBubble = seAppendMsg('ai', '<span style="opacity:0.5;">Thinking<span class="ai-dots">...</span></span>', thinkId);

  // Animate dots
  var dotEl = document.querySelector('#' + thinkId + ' .ai-dots');
  var dotAnim = setInterval(function() {
    if (!dotEl) { clearInterval(dotAnim); return; }
    dotEl.textContent = dotEl.textContent.length >= 3 ? '.' : dotEl.textContent + '.';
  }, 400);

  if (sendBtn) sendBtn.disabled = true;

  // Add to history
  history.push({ role: 'user', content: q });

  fetch('/.netlify/functions/coach', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (window._anAuthToken||'') },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 1000,
      system: system,
      messages: history
    })
  })
  .then(function(r) { return r.json(); })
  .then(function(data) {
    clearInterval(dotAnim);
    var text = '';
    if (data.content) {
      for (var i = 0; i < data.content.length; i++) {
        if (data.content[i].type === 'text') text += data.content[i].text;
      }
    }
    if (!text && data.error) text = 'Error: ' + (typeof data.error === 'string' ? data.error : JSON.stringify(data.error));
    if (!text) text = 'No response received.';

    // Replace thinking bubble with real response
    var thinkWrap = document.getElementById(thinkId);
    if (thinkWrap) thinkWrap.remove();
    seAppendMsg('ai', renderMD(text));

    // Store assistant reply in history
    history.push({ role: 'assistant', content: text });
    // Keep history to last 20 messages to avoid token overflow
    if (history.length > 20) history.splice(0, 2);

    if (sendBtn) sendBtn.disabled = false;
  })
  .catch(function(e) {
    clearInterval(dotAnim);
    var thinkWrap = document.getElementById(thinkId);
    if (thinkWrap) thinkWrap.remove();
    seAppendMsg('ai', '<span style="color:#fca5a5;">Error: ' + e.message + '<br><span style="font-size:11px;opacity:0.7;">Check that your Netlify function is deployed and the ANTHROPIC_API_KEY env var is set.</span></span>');
    if (sendBtn) sendBtn.disabled = false;
  });
};

// ── Enter key to send (Shift+Enter for newline) ──────────────
document.addEventListener('DOMContentLoaded', function() {
  setTimeout(function() {
    var inp = document.getElementById('se-ai-input');
    if (inp) {
      inp.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          seAskAI();
        }
      });
      inp.placeholder = 'Ask anything... (Enter to send, Shift+Enter for newline)';
    }

    // Add clear button + context label to the AI panel header
    var ctx = document.getElementById('se-ai-ctx');
    if (ctx && !document.getElementById('se-ai-clear-btn')) {
      var clearBtn = document.createElement('button');
      clearBtn.id = 'se-ai-clear-btn';
      clearBtn.textContent = 'Clear';
      clearBtn.style.cssText = 'background:none;border:1px solid rgba(255,255,255,0.15);border-radius:5px;color:rgba(255,255,255,0.4);font-size:10px;padding:2px 7px;cursor:pointer;font-family:inherit;float:right;';
      clearBtn.onclick = seClearAIChat;
      ctx.parentNode.insertBefore(clearBtn, ctx);
    }

    // Upgrade suggestion chips to use seAskAI
    var suggList = document.getElementById('se-sugg-list');
    if (suggList) {
      var suggestions = [
        'Rewrite step 1 to sound more natural',
        'Make the pitch under 30 words',
        'Add a line for when they say they are happy with their current setup',
        'Give me a strong one-liner close for this script',
        'Translate this script to Spanish'
      ];
      suggList.innerHTML = '';
      suggestions.forEach(function(sugg) {
        var btn = document.createElement('button');
        btn.style.cssText = 'width:100%;text-align:left;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:7px;padding:7px 10px;font-size:11.5px;color:rgba(255,255,255,0.65);cursor:pointer;font-family:inherit;line-height:1.4;transition:background 0.12s;';
        btn.textContent = sugg;
        btn.onmouseover = function() { this.style.background = 'rgba(99,102,241,0.2)'; this.style.color = '#c7d2fe'; };
        btn.onmouseout  = function() { this.style.background = 'rgba(255,255,255,0.05)'; this.style.color = 'rgba(255,255,255,0.65)'; };
        btn.onclick = function() {
          var inp = document.getElementById('se-ai-input');
          if (inp) inp.value = sugg;
          seAskAI();
        };
        suggList.appendChild(btn);
      });
    }
  }, 500);
});

// ── Update AI context label when script changes ──────────────
var _origSeOpenScript_ai = window.seOpenScript;
window.seOpenScript = function(id) {
  if (typeof _origSeOpenScript_ai === 'function') _origSeOpenScript_ai(id);
  setTimeout(function() {
    var ctx = document.getElementById('se-ai-ctx');
    var s = (typeof seScripts !== 'undefined') && seScripts
      ? seScripts.find(function(x) { return x.id === id; }) : null;
    if (ctx && s) ctx.textContent = 'Coaching: ' + s.name;
    // Show existing history for this script
    var msgs = document.getElementById('se-ai-msgs');
    if (msgs && _seAIHistories[id]) {
      msgs.innerHTML = '';
      var hist = _seAIHistories[id];
      for (var i = 0; i < hist.length; i++) {
        var m = hist[i];
        if (m.role === 'user') seAppendMsg('user', m.content.replace(/</g,'&lt;'));
        else seAppendMsg('ai', renderMD(m.content));
      }
    }
  }, 100);
};

