// ─── inline block 9 ───────────────────────
// ============================================================
// PATCH 8 — Script Library grid fix + Commission auth fix
// ============================================================

// ── FIX 1: SCRIPT LIBRARY — force language+grid render ──────
// The original app.js seRenderLib draws the vertical left-panel list (correct).
// renderScriptLibrary draws the main Script Library page (should be grid).
// Our language patch (block 5) already has the right version with language tabs
// and grid cards. We just need to make sure it's the one that runs.
// Re-declare it here (last script block wins) to guarantee it.

window.renderScriptLibrary = function() {
  var container = document.getElementById('scriptlibrary-content');
  if (!container) return;
  seLoad();
  if (!window._anLibFocus) {
    try {
      var storedFocus = sessionStorage.getItem('an-last-lib-focus');
      if (storedFocus) window._anLibFocus = JSON.parse(storedFocus);
    } catch(e) {}
  }
  container.innerHTML = '';

  var LANG_TABS = [
    { code: 'en',    label: '🇺🇸 English',  color: '#6366f1' },
    { code: 'es',    label: '🇲🇽 Español',   color: '#10b981' },
    { code: 'pt',    label: '🇧🇷 Português', color: '#f59e0b' },
    { code: 'fr',    label: '🇫🇷 Français',  color: '#ec4899' },
    { code: 'other', label: '🌐 Other',      color: '#8b5cf6' }
  ];

  var CATS = [
    { label:'Cold Call',   type:'coldcall',   icon:'📞', color:'#6366f1' },
    { label:'Discovery',   type:'discovery',  icon:'🔍', color:'#8b5cf6' },
    { label:'Demo',        type:'demo',       icon:'🖥️',  color:'#06b6d4' },
    { label:'Closing',     type:'closing',    icon:'🏆', color:'#f59e0b' },
    { label:'Onboarding',  type:'onboarding', icon:'🚀', color:'#10b981' },
    { label:'Objections',  type:'objections', icon:'🛡️',  color:'#ef4444' },
    { label:'Battle Cards',type:'battlecards',icon:'⚔️',  color:'#ec4899' },
    { label:'Talk Tracks', type:'talktracks', icon:'💬', color:'#14b8a6' },
    { label:'Custom',      type:'custom',     icon:'✏️',  color:'#a1a1aa' }
  ];

  function getLang(code) {
    var l = LANG_TABS.filter(function(x){ return x.code === code; })[0];
    return l ? l.label : '🇺🇸 English';
  }

  function isOther(lang) {
    return ['en','es','pt','fr'].indexOf(lang) === -1;
  }

  // Which language tabs have scripts
  var activeLangs = LANG_TABS.filter(function(lt) {
    return seScripts.some(function(s) {
      var sl = s.lang || 'en';
      return lt.code === 'other' ? isOther(sl) : sl === lt.code;
    });
  });
  if (!activeLangs.filter(function(t){ return t.code === 'en'; }).length) {
    activeLangs.unshift(LANG_TABS[0]);
  }

  var libFocus = window._anLibFocus || null;
  if (libFocus) window._anLibFocus = null;
  var initialLang = (libFocus && libFocus.lang) ? libFocus.lang : (activeLangs[0] ? activeLangs[0].code : 'en');
  var initialCatType = (libFocus && libFocus.type) ? libFocus.type : 'coldcall';
  if (!activeLangs.some(function(t){ return t.code === initialLang; })) initialLang = activeLangs[0].code;
  var focusScriptId = libFocus && libFocus.id ? libFocus.id : null;

  function getCatMeta(type) {
    return CATS.filter(function(c){ return c.type === type; })[0] || CATS[0];
  }

  // ── Recently saved strip (scripts hide under category tabs) ──
  var recentScripts = seScripts.slice().sort(function(a, b) {
    var ta = a.updatedAt || ('' + a.id);
    var tb = b.updatedAt || ('' + b.id);
    return tb.localeCompare(ta);
  }).slice(0, 8);

  if (recentScripts.length) {
    var recentWrap = document.createElement('div');
    recentWrap.style.cssText = 'margin-bottom:18px;padding:14px 16px;background:#f8fafc;border:1.5px solid #e4e4e7;border-radius:12px;';
    recentWrap.innerHTML = '<div style="font-size:11px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:10px;">Recently saved</div>';
    var recentRow = document.createElement('div');
    recentRow.style.cssText = 'display:flex;flex-wrap:wrap;gap:8px;';
    recentScripts.forEach(function(s) {
      var cat = getCatMeta(s.type);
      var chip = document.createElement('button');
      chip.type = 'button';
      chip.style.cssText = 'display:flex;align-items:center;gap:6px;padding:7px 12px;border-radius:20px;border:1.5px solid '
        +(focusScriptId === s.id ? cat.color : '#e4e4e7')+';background:'+(focusScriptId === s.id ? cat.color+'18' : '#fff')
        +';color:#09090b;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;transition:all 0.12s;';
      chip.innerHTML = '<span>'+cat.icon+'</span><span>'+s.name+'</span>'
        +'<span style="font-size:10px;font-weight:700;color:'+cat.color+';background:'+cat.color+'18;padding:1px 7px;border-radius:10px;">'+cat.label+'</span>';
      chip.onclick = function() {
        window._anLibFocus = { type: s.type, lang: s.lang || 'en', id: s.id };
        renderScriptLibrary();
      };
      recentRow.appendChild(chip);
    });
    recentWrap.appendChild(recentRow);
    var recentHint = document.createElement('div');
    recentHint.style.cssText = 'font-size:11px;color:#a1a1aa;margin-top:10px;line-height:1.45;';
    recentHint.textContent = 'Scripts from Lead Call Session save under Cold Call. Deal Call Session saves under Discovery, Demo, or Closing.';
    recentWrap.appendChild(recentHint);
    container.appendChild(recentWrap);
  }

  // ── Language pill tabs ──
  var langBar = document.createElement('div');
  langBar.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px;';

  var catArea = document.createElement('div');

  var activeLang = initialLang;

  function renderCatArea(langCode) {
    catArea.innerHTML = '';

    var langScripts = seScripts.filter(function(s) {
      var sl = s.lang || 'en';
      return langCode === 'other' ? isOther(sl) : sl === langCode;
    });

    // ── Category tabs ──
    var catBar = document.createElement('div');
    catBar.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-bottom:20px;border-bottom:2px solid #e4e4e7;padding-bottom:0;overflow-x:auto;';

    var cardArea = document.createElement('div');
    cardArea.style.cssText = 'min-height:160px;';

    var activeCat = CATS[0];

    function renderCards(cat) {
      cardArea.innerHTML = '';
      var scripts = langScripts.filter(function(s){ return s.type === cat.type; });

      // Header
      var hdr = document.createElement('div');
      hdr.style.cssText = 'display:flex;align-items:center;gap:10px;margin-bottom:16px;';
      hdr.innerHTML = '<div style="width:36px;height:36px;border-radius:10px;background:'+cat.color+'18;display:flex;align-items:center;justify-content:center;font-size:18px;">'+cat.icon+'</div>'
        +'<div><div style="font-size:15px;font-weight:700;color:#09090b;">'+cat.label+' Scripts</div>'
        +'<div style="font-size:12px;color:#a1a1aa;">'+getLang(langCode)+' &middot; '+scripts.length+' script'+(scripts.length!==1?'s':'')+'</div></div>'
        +'<button onclick="showSection(\'scripteditor\',null);setTimeout(function(){seNewScriptWithLang(\''+cat.type+'\',\''+langCode+'\');},150);" '
        +'style="margin-left:auto;padding:8px 14px;background:'+cat.color+';color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">+ New</button>';
      cardArea.appendChild(hdr);

      if (!scripts.length) {
        var empty = document.createElement('div');
        empty.style.cssText = 'text-align:center;padding:40px 20px;color:#a1a1aa;border:2px dashed #e4e4e7;border-radius:12px;';
        empty.innerHTML = '<div style="font-size:28px;margin-bottom:8px;">'+cat.icon+'</div>'
          +'<div style="font-size:13px;font-weight:600;color:#71717a;margin-bottom:12px;">No '+cat.label+' scripts in '+getLang(langCode)+'</div>'
          +'<button onclick="showSection(\'scripteditor\',null);setTimeout(function(){seNewScriptWithLang(\''+cat.type+'\',\''+langCode+'\');},150);" '
          +'style="background:'+cat.color+';color:#fff;border:none;border-radius:7px;padding:8px 16px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">+ Create One</button>';
        cardArea.appendChild(empty);
        return;
      }

      // ── GRID of cards ──
      var grid = document.createElement('div');
      grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;';

      scripts.forEach(function(s) {
        var isFocused = focusScriptId && s.id === focusScriptId;
        var card = document.createElement('div');
        card.style.cssText = 'background:#fff;border:1.5px solid '+(isFocused ? cat.color : '#e4e4e7')+';border-radius:10px;padding:16px;cursor:pointer;transition:border-color 0.15s,box-shadow 0.15s;'
          +(isFocused ? 'box-shadow:0 0 0 3px '+cat.color+'33;' : '');
        card.onmouseover = function(){ this.style.borderColor=cat.color; this.style.boxShadow='0 4px 12px '+cat.color+'22'; };
        card.onmouseout  = function(){
          this.style.borderColor = isFocused ? cat.color : '#e4e4e7';
          this.style.boxShadow = isFocused ? '0 0 0 3px '+cat.color+'33' : '';
        };

        var steps = s.steps || [];
        var hasContent = steps.some(function(st){ return st.body && st.body.trim(); });
        var preview = steps.length ? steps[0].title : 'No steps yet';

        card.innerHTML = '<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:8px;">'
          +'<div style="font-size:14px;font-weight:700;color:#09090b;flex:1;padding-right:8px;">'+s.name+'</div>'
          +'<div style="width:8px;height:8px;border-radius:50%;flex-shrink:0;margin-top:4px;background:'+(hasContent?cat.color:'#e4e4e7')+'"></div>'
          +'</div>'
          +'<div style="font-size:11px;color:#a1a1aa;margin-bottom:4px;">'+getLang(s.lang||'en')+'</div>'
          +'<div style="font-size:12px;color:#71717a;margin-bottom:10px;">'+steps.length+' step'+(steps.length!==1?'s':'')+' &middot; '+(hasContent?'Has content':'Empty')+'</div>'
          +'<div style="font-size:12px;color:#a1a1aa;font-style:italic;margin-bottom:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+preview+'</div>'
          +'<div style="display:flex;gap:6px;">'
          +'<button onclick="event.stopPropagation();showSection(\'scripteditor\',null);setTimeout(function(){seOpenScript(\''+s.id+'\');},150);" '
          +'style="flex:1;padding:7px;background:'+cat.color+';color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">Edit</button>'
          +'<button onclick="event.stopPropagation();seLoad();seScripts=seScripts.filter(function(x){return x.id!==\''+s.id+'\'});sePersist();renderScriptLibrary();" '
          +'style="padding:7px 10px;background:#fff;color:#ef4444;border:1.5px solid #fca5a5;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;">Delete</button>'
          +'</div>';

        card.onclick = function(){
          showSection('scripteditor', null);
          setTimeout(function(){ seOpenScript(s.id); }, 150);
        };
        grid.appendChild(card);
        if (isFocused) {
          setTimeout(function(){ card.scrollIntoView({ behavior:'smooth', block:'center' }); }, 120);
        }
      });

      cardArea.appendChild(grid);
    }

    // Build category tab buttons
    CATS.forEach(function(cat, i) {
      var count = langScripts.filter(function(s){ return s.type === cat.type; }).length;
      var tab = document.createElement('button');
      var isActive = cat.type === initialCatType || (i === 0 && !CATS.some(function(c){ return c.type === initialCatType; }));
      tab.style.cssText = 'padding:9px 14px;font-size:12px;font-weight:600;border:none;'
        +'border-bottom:2.5px solid '+(isActive ? cat.color : 'transparent')+';'
        +'background:none;cursor:pointer;font-family:inherit;'
        +'color:'+(isActive ? cat.color : '#71717a')+';'
        +'white-space:nowrap;transition:all 0.12s;display:flex;align-items:center;gap:5px;margin-bottom:-2px;';
      tab.innerHTML = '<span>'+cat.icon+'</span><span>'+cat.label+'</span>'
        +(count ? '<span style="background:'+cat.color+'18;color:'+cat.color+';font-size:10px;font-weight:700;border-radius:10px;padding:1px 6px;">'+count+'</span>' : '');

      tab.onclick = function() {
        Array.from(catBar.children).forEach(function(b, bi) {
          var bc = CATS[bi] || {color:'#6366f1'};
          b.style.borderBottomColor = 'transparent';
          b.style.color = '#71717a';
        });
        tab.style.borderBottomColor = cat.color;
        tab.style.color = cat.color;
        activeCat = cat;
        renderCards(cat);
      };

      if (isActive) activeCat = cat;
      catBar.appendChild(tab);
    });

    catArea.appendChild(catBar);
    catArea.appendChild(cardArea);
    renderCards(activeCat || CATS[0]);

    if (langScripts.length === 0) {
      cardArea.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#a1a1aa;">'
        +'<div style="font-size:36px;margin-bottom:12px;">📝</div>'
        +'<div style="font-size:15px;font-weight:700;color:#71717a;margin-bottom:6px;">No '+getLang(langCode)+' scripts yet</div>'
        +'<div style="font-size:12px;margin-bottom:16px;">Create your first script in this language.</div>'
        +'<button onclick="showSection(\'scripteditor\',null);" style="background:#6366f1;color:#fff;border:none;border-radius:8px;padding:10px 20px;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Open Script Editor</button>'
        +'</div>';
    }
  }

  // Build language tabs
  activeLangs.forEach(function(lt, i) {
    var count = seScripts.filter(function(s) {
      var sl = s.lang || 'en';
      return lt.code === 'other' ? isOther(sl) : sl === lt.code;
    }).length;

    var tab = document.createElement('button');
    var isFirst = lt.code === initialLang;
    tab.style.cssText = 'padding:8px 16px;border-radius:20px;font-size:13px;font-weight:600;'
      +'cursor:pointer;font-family:inherit;'
      +'border:1.5px solid '+(isFirst ? lt.color : '#e4e4e7')+';'
      +'background:'+(isFirst ? lt.color+'18' : 'transparent')+';'
      +'color:'+(isFirst ? lt.color : '#71717a')+';'
      +'transition:all 0.12s;display:flex;align-items:center;gap:6px;';
    tab.innerHTML = lt.label
      +(count ? ' <span style="background:'+lt.color+'18;color:'+lt.color+';font-size:10px;font-weight:700;padding:1px 7px;border-radius:10px;">'+count+'</span>' : '');
    tab._ltColor = lt.color;

    tab.onclick = function() {
      Array.from(langBar.children).forEach(function(b) {
        var c = b._ltColor || '#6366f1';
        b.style.borderColor = '#e4e4e7';
        b.style.background = 'transparent';
        b.style.color = '#71717a';
      });
      tab.style.borderColor = lt.color;
      tab.style.background = lt.color + '18';
      tab.style.color = lt.color;
      activeLang = lt.code;
      renderCatArea(lt.code);
    };

    langBar.appendChild(tab);
  });

  // + Add Language button
  var addBtn = document.createElement('button');
  addBtn.style.cssText = 'padding:8px 14px;border-radius:20px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;border:1.5px dashed #d4d4d8;background:transparent;color:#a1a1aa;';
  addBtn.textContent = '+ Add Language';
  addBtn.onclick = function() {
    showSection('scripteditor', null);
    setTimeout(function() {
      seNewScript();
      setTimeout(function() {
        var langEl = document.getElementById('se-script-lang');
        if (langEl) langEl.focus();
        if (typeof showToast === 'function') showToast('Pick a language from the dropdown, then write your script.');
      }, 200);
    }, 100);
  };
  langBar.appendChild(addBtn);

  container.appendChild(langBar);
  container.appendChild(catArea);
  renderCatArea(activeLang);
};

// ── FIX 2: Commission auth — reliable check on login ────────
// Supabase fires onAuthStateChange which calls onUserLoggedIn.
// We patch onUserLoggedIn to always checkCommissionAccess.
var _origOnUserLoggedIn_p8 = window.onUserLoggedIn;
window.onUserLoggedIn = function(user) {
  if (typeof _origOnUserLoggedIn_p8 === 'function') _origOnUserLoggedIn_p8(user);
  if (typeof checkCommissionAccess === 'function') checkCommissionAccess();
  if (typeof checkAdminAccess === 'function') checkAdminAccess();
};

// Also poll on DOMContentLoaded with longer window for Supabase to resolve
document.addEventListener('DOMContentLoaded', function() {
  var tries = 0;
  var iv = setInterval(function() {
    tries++;
    if (typeof _currentUser !== 'undefined' && _currentUser) {
      if (typeof checkCommissionAccess === 'function') checkCommissionAccess();
      if (typeof checkAdminAccess === 'function') checkAdminAccess();
      clearInterval(iv);
    }
    if (tries > 40) clearInterval(iv); // 20 second timeout
  }, 500);
});

// Also hook Supabase auth state change directly if available
document.addEventListener('DOMContentLoaded', function() {
  setTimeout(function() {
    var sb = typeof getSupabase === 'function' ? getSupabase() : null;
    if (sb && sb.auth) {
      sb.auth.onAuthStateChange(function(event, session) {
        if (event === 'SIGNED_IN' && session) {
          setTimeout(function() {
            if (typeof checkCommissionAccess === 'function') checkCommissionAccess();
            if (typeof checkAdminAccess === 'function') checkAdminAccess();
          }, 100);
        }
        if (event === 'SIGNED_OUT') {
          var wrap = document.getElementById('nav-commission-wrap');
          if (wrap) wrap.style.display = 'none';
        }
      });
    }
  }, 1000);
});

