function getCustomCompetitors() {
  try { return JSON.parse(localStorage.getItem('custom-competitors') || '[]'); } catch(e) { return []; }
}
function saveCustomCompetitors(list) {
  localStorage.setItem('custom-competitors', JSON.stringify(list));
}
function getAllCompetitors() {
  var hidden = [];
  try { hidden = JSON.parse(localStorage.getItem('hidden-builtins') || '[]'); } catch(e){}
  var builtins = BUILTIN_COMPETITORS.filter(function(c) { return hidden.indexOf(c.id) === -1; });
  return builtins.concat(getCustomCompetitors());
}

