// Minimal script library — picker + recent only (templates live in toolbar picker)
window.seRenderLib = function() {
  var el = document.getElementById('se-lib-list');
  if (!el) return;
  el.innerHTML = '';

  var sorted = seScripts.slice().sort(function(a, b) {
    var ta = a.updatedAt ? new Date(a.updatedAt).getTime() : 0;
    var tb = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
    return tb - ta;
  });

  var pickerWrap = document.createElement('div');
  pickerWrap.style.cssText = 'padding:10px 10px 8px;';
  var picker = document.createElement('select');
  picker.id = 'se-lib-picker';
  picker.style.cssText = 'width:100%;border:1.5px solid #2a2a38;border-radius:7px;padding:7px 8px;font-size:11.5px;font-weight:600;color:#e4e4e7;background:#12121a;font-family:inherit;outline:none;cursor:pointer;';
  if (!sorted.length) {
    var emptyOpt = document.createElement('option');
    emptyOpt.textContent = 'No scripts yet';
    picker.appendChild(emptyOpt);
    picker.disabled = true;
  } else {
    sorted.forEach(function(s) {
      var opt = document.createElement('option');
      opt.value = s.id;
      opt.textContent = s.name || 'Untitled';
      if (s.id === seCurrentId) opt.selected = true;
      picker.appendChild(opt);
    });
    picker.onchange = function() {
      if (picker.value && picker.value !== seCurrentId) seOpenScript(picker.value);
    };
  }
  pickerWrap.appendChild(picker);
  el.appendChild(pickerWrap);

  var actions = document.createElement('div');
  actions.style.cssText = 'display:flex;gap:5px;padding:0 10px 10px;';
  actions.innerHTML = '<button type="button" id="se-lib-new-btn" style="flex:1;background:#6366f1;color:#fff;border:none;border-radius:6px;padding:6px 0;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">+ New</button>'
    + '<button type="button" id="se-lib-tpl-btn" style="flex:1;background:rgba(99,102,241,0.15);color:#c7d2fe;border:1px solid rgba(99,102,241,0.3);border-radius:6px;padding:6px 0;font-size:11px;font-weight:600;cursor:pointer;font-family:inherit;">Templates</button>';
  el.appendChild(actions);
  var newBtn = document.getElementById('se-lib-new-btn');
  if (newBtn) newBtn.onclick = function() { if (typeof seNewScript === 'function') seNewScript(); };
  var tplBtn = document.getElementById('se-lib-tpl-btn');
  if (tplBtn) tplBtn.onclick = function() { if (typeof seShowTemplatePicker === 'function') seShowTemplatePicker(); };

  var expanded = document.getElementById('se-root') && !document.getElementById('se-root').classList.contains('se-lib-collapsed');
  if (expanded && sorted.length) {
    var recentLbl = document.createElement('div');
    recentLbl.style.cssText = 'font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#52525b;padding:4px 10px 6px;';
    recentLbl.textContent = 'Recent';
    el.appendChild(recentLbl);
    sorted.slice(0, 3).forEach(function(s) {
      var isActive = seCurrentId === s.id;
      var row = document.createElement('div');
      row.style.cssText = 'padding:6px 10px;font-size:11.5px;cursor:pointer;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:' + (isActive ? '#c7d2fe' : '#71717a') + ';font-weight:' + (isActive ? '700' : '400') + ';border-left:2px solid ' + (isActive ? '#6366f1' : 'transparent') + ';';
      row.textContent = s.name || 'Untitled';
      row.title = s.name || 'Untitled';
      row.onclick = function() { seOpenScript(s.id); };
      el.appendChild(row);
    });
  }

  var foot = document.createElement('div');
  foot.style.cssText = 'padding:8px 10px 12px;margin-top:auto;';
  foot.innerHTML = '<button type="button" style="width:100%;background:transparent;border:1px solid #2a2a38;border-radius:6px;padding:7px;font-size:11px;color:#71717a;cursor:pointer;font-family:inherit;" onclick="showSection(\'scriptlibrary\',null)">All scripts (' + seScripts.length + ') →</button>';
  el.appendChild(foot);
};

// ── Language dropdown auto-translates via seOnLanguageChange ──

// ── Translation handler (AI panel fallback) ─────────────────
window.seOfferTranslate = function(langCode, langLabel, mode) {
  var msgs = document.getElementById('se-ai-msgs');
  var inp  = document.getElementById('se-ai-input');
  if (!msgs) return;

  var s = (typeof seScripts !== 'undefined') && seCurrentId
    ? seScripts.filter(function(x) { return x.id === seCurrentId; })[0]
    : null;

  var prompt = '';

  if (mode === true) {
    var steps = (typeof seCollectSteps === 'function') ? seCollectSteps() : [];
    seTranslateScriptToLang(steps, langCode, function(err, translated) {
      if (err) {
        if (typeof showToast === 'function') showToast('Translation failed: ' + err);
        return;
      }
      var s = seScripts.find(function(x) { return x.id === seCurrentId; });
      if (s) {
        seSnapshotStepsToLang(s, s._seViewLang || s.lang || 'en', steps);
        s.i18n[langCode] = translated;
        s.lang = langCode;
        s._seViewLang = langCode;
        var langEl = document.getElementById('se-script-lang');
        if (langEl) langEl.value = langCode;
      }
      if (typeof seRenderSteps === 'function') seRenderSteps(translated);
      if (typeof seMarkDirty === 'function') seMarkDirty();
      if (typeof seSave === 'function') seSave();
      if (typeof showToast === 'function') showToast('Translated to ' + langLabel);
    });
    return;

  } else if (mode === false) {
    // Write fresh
    var scriptType = s ? s.type : 'sales';
    prompt = 'Write a complete ' + scriptType + ' script in ' + langLabel + ' for AgentNav, a health insurance broker platform. Use natural, conversational ' + langLabel + '. Include all the key steps with titles and the full word-for-word text for each step.';

  } else {
    // Paste mode
    if (inp) {
      inp.value = 'Translate this to ' + langLabel + ' (making it sound natural, not literal): ';
      inp.focus();
      var suggList = document.getElementById('se-sugg-list');
      if (suggList) {
        suggList.innerHTML = '<div style="font-size:11px;color:rgba(255,255,255,0.5);padding:4px 2px;">Paste your text after the prompt above, then press Enter.</div>';
      }
    }
    return;
  }

  if (inp) inp.value = '';

  // Show user message
  var uBubble = document.createElement('div');
  uBubble.style.cssText = 'background:rgba(99,102,241,0.2);border-radius:8px;padding:8px 11px;font-size:12px;color:#c7d2fe;text-align:right;margin-left:20%;';
  uBubble.textContent = mode === true ? 'Translate my script to ' + langLabel : 'Write a new ' + langLabel + ' script';
  msgs.appendChild(uBubble);

  // Thinking bubble
  var thinkId = 'translate-think-' + Date.now();
  var tBubble = document.createElement('div');
  tBubble.id = thinkId;
  tBubble.style.cssText = 'background:rgba(255,255,255,0.06);border-radius:8px;padding:8px 11px;font-size:12px;color:rgba(255,255,255,0.5);margin-right:8px;';
  tBubble.textContent = mode === true ? 'Translating to ' + langLabel + '...' : 'Writing in ' + langLabel + '...';
  msgs.appendChild(tBubble);
  tBubble.scrollIntoView({ block: 'nearest' });

  var system = 'You are an expert bilingual sales coach for AgentNav, a health insurance broker platform. '
    + 'When translating or writing scripts, maintain the professional sales tone while sounding completely natural in the target language. '
    + 'Format the output clearly with numbered steps and their titles, followed by the full script text for each step.';

  fetch('/.netlify/functions/coach', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (window._anAuthToken||'') },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 1200,
      system: system,
      messages: [{ role: 'user', content: prompt }]
    })
  })
  .then(function(r) { return r.json(); })
  .then(function(data) {
    var text = '';
    if (data.content) {
      for (var i = 0; i < data.content.length; i++) {
        if (data.content[i].type === 'text') text += data.content[i].text;
      }
    }
    var el = document.getElementById(thinkId);
    if (el) {
      el.style.color = 'rgba(255,255,255,0.85)';
      el.innerHTML = (typeof renderMD === 'function' ? renderMD(text) : text)
        + '<div style="margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,0.1);">'
        + '<button onclick="seApplyTranslation(\'' + thinkId + '\')" '
        + 'style="background:#10b981;color:#fff;border:none;border-radius:7px;padding:7px 14px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">'
        + 'Apply to script steps</button>'
        + '<span style="font-size:11px;color:rgba(255,255,255,0.35);margin-left:8px;">or copy manually above</span>'
        + '</div>';
    }
    msgs.scrollTop = msgs.scrollHeight;
  })
  .catch(function(e) {
    var el = document.getElementById(thinkId);
    if (el) { el.style.color = '#fca5a5'; el.textContent = 'Error: ' + e.message; }
  });
};

// ── Apply translation back into steps ───────────────────────
window.seApplyTranslation = function(bubbleId) {
  var bubble = document.getElementById(bubbleId);
  if (!bubble) return;
  var raw = bubble.innerText || bubble.textContent || '';
  raw = raw.replace('Apply to script steps', '').replace('or copy manually above', '').trim();
  if (!raw || !confirm('This will replace your current step content with the translation. Continue?')) return;

  var parsed = seParseTranslatedSteps(raw);
  if (!parsed.length) parsed = [{ title: 'Step 1', time: '', body: raw }];

  var s = seScripts.find(function(x) { return x.id === seCurrentId; });
  var langCode = (document.getElementById('se-script-lang') || {}).value || (s && s.lang) || 'en';
  if (s) {
    seSnapshotStepsToLang(s, s._seViewLang || s.lang || 'en', typeof seCollectSteps === 'function' ? seCollectSteps() : []);
    seSnapshotStepsToLang(s, langCode, parsed);
    s.lang = langCode;
    s._seViewLang = langCode;
  }

  if (typeof seRenderSteps === 'function') seRenderSteps(parsed);
  else {
    var stepsList = document.getElementById('se-steps-list');
    if (stepsList) {
      var stepDivs = stepsList.querySelectorAll('[draggable="true"]');
      parsed.forEach(function(p, i) {
        if (i < stepDivs.length) {
          var ta = stepDivs[i].querySelector('textarea');
          var ti = stepDivs[i].querySelector('input[type="text"]');
          if (ta) ta.value = p.body;
          if (ti) ti.value = p.title;
        } else if (typeof seAddStep === 'function') seAddStep({ title: p.title, body: p.body });
      });
    }
  }

  if (typeof seMarkDirty === 'function') seMarkDirty();
  if (typeof seSave === 'function') seSave();
  if (typeof showToast === 'function') showToast('Translation applied! Review and save.');
};

