// PATCH 12 — Sales Dashboard: Supabase sync + inline deal form
// ============================================================

// ── Override dashLoad / dashSave to sync with Supabase ───────

function dashMergeField(localVal, remoteVal) {
  if (remoteVal === undefined || remoteVal === null) return localVal;
  if (Array.isArray(remoteVal)) {
    if (!Array.isArray(localVal) || localVal.length === 0) return remoteVal;
    if (remoteVal.length === 0) return localVal;
    return remoteVal.length >= localVal.length ? remoteVal : localVal;
  }
  if (typeof remoteVal === 'object') return Object.assign({}, localVal || {}, remoteVal);
  return remoteVal || localVal;
}

window.dashLoad = function(callback) {
  var sb = typeof getSupabase === 'function' ? getSupabase() : null;

  // Always load localStorage first (instant) — all fields
  try {
    var saved = JSON.parse(localStorage.getItem('sales-dashboard') || '{}');
    ['prospect','pipeline','goals','activity','demos','activityLog'].forEach(function(k) {
      if (saved[k] !== undefined) _dash[k] = saved[k];
    });
    if (saved._updatedAt) _dash._updatedAt = saved._updatedAt;
  } catch(e) {}

  if (typeof anSyncAllOpportunitiesToPipeline === 'function') anSyncAllOpportunitiesToPipeline({ skipSave: true });
  if (typeof anSyncAllPipelineDealsToOpportunities === 'function') anSyncAllPipelineDealsToOpportunities({ skipSave: true, skipRefresh: true });
  if (typeof anSyncAllDemosToOpportunities === 'function') anSyncAllDemosToOpportunities({ skipSave: true, skipRefresh: true });
  if (typeof anMigratePipelineStages === 'function' && anMigratePipelineStages()) {
    try { localStorage.setItem('sales-dashboard', JSON.stringify(_dash)); } catch(e) {}
  }
  if (typeof callback === 'function') callback();

  // Then overlay with Supabase if logged in
  if (!sb || !_currentUser) return;

  sb.from('sales_dashboard')
    .select('pipeline,goals,activity,prospect,demos,activity_log,rep_email,updated_at')
    .eq('user_id', _currentUser.id)
    .single()
    .then(function(result) {
      if (result.error || !result.data) return;
      var d = result.data;
      // Merge strategy: for activityLog, merge by date taking the HIGHER count
      // (never let a remote load wipe out calls that were just logged locally).
      // For other fields, prefer remote if it's newer.
      var localUpdated = _dash._updatedAt ? new Date(_dash._updatedAt).getTime() : 0;
      var remoteUpdated = d.updated_at ? new Date(d.updated_at).getTime() : 0;
      var preferRemote = remoteUpdated > localUpdated + 2000; // 2s grace for server clock skew

      // Always merge activityLog by taking MAX per date+field — never lose logged calls
      if (d.activity_log && Array.isArray(d.activity_log)) {
        if (!_dash.activityLog) _dash.activityLog = [];
        var localLogByDate = {};
        _dash.activityLog.forEach(function(e){ if(e.date) localLogByDate[e.date] = e; });
        d.activity_log.forEach(function(re) {
          if (!re || !re.date) return;
          var le = localLogByDate[re.date];
          if (!le) { _dash.activityLog.push(re); localLogByDate[re.date] = re; return; }
          // Keep the higher count for each numeric field
          ['calls','demos','closes','pickups','voicemails'].forEach(function(f) {
            if ((re[f]||0) > (le[f]||0)) le[f] = re[f];
          });
          // Merge by_hour objects — take max per hour
          ['calls_by_hour','pickups_by_hour','demos_by_hour','voicemails_by_hour','noanswer_by_hour','notinterested_by_hour'].forEach(function(bh) {
            if (!re[bh]) return;
            if (!le[bh]) { le[bh] = re[bh]; return; }
            Object.keys(re[bh]).forEach(function(h) {
              le[bh][h] = Math.max(le[bh][h]||0, re[bh][h]||0);
            });
          });
        });
      }

      ['pipeline','goals','activity','prospect','demos'].forEach(function(k) {
        var localV = _dash[k];
        var remoteV = d[k];
        if (k === 'activity' && localV && remoteV) {
          // For activity totals, take the max of each field
          ['calls','demos','closes'].forEach(function(f) {
            if ((remoteV[f]||0) > (localV[f]||0)) localV[f] = remoteV[f];
          });
        } else if (preferRemote && remoteV !== undefined && remoteV !== null) {
          _dash[k] = dashMergeField(localV, remoteV);
        } else if (!preferRemote) {
          _dash[k] = dashMergeField(remoteV, localV);
        }
      });
      if (d.updated_at) _dash._updatedAt = d.updated_at;
      if (typeof anMigratePipelineStages === 'function') anMigratePipelineStages();
      localStorage.setItem('sales-dashboard', JSON.stringify(_dash));
      // Light refresh only — never wipe Charts & Reports tab
      if (typeof dashRefreshVisiblePanes === 'function') dashRefreshVisiblePanes();
    });
};

window.dashSave = function(cb) {
  var now = new Date().toISOString();
  _dash._updatedAt = now;
  // Always save full dashboard blob locally, immediately (never debounced —
  // local persistence should never wait)
  localStorage.setItem('sales-dashboard', JSON.stringify(_dash));

  var sb = typeof getSupabase === 'function' ? getSupabase() : null;
  if (!sb || !_currentUser) { if (cb) cb(true, null, 'local'); return; }

  // Debounce the actual network write — if dashSave() fires many times in a
  // burst (bulk edits, rapid clicks, etc.) collapse them into a single request
  // using the latest _dash state, instead of firing one request per call.
  window._dashSaveCallbacks = window._dashSaveCallbacks || [];
  if (cb) window._dashSaveCallbacks.push(cb);
  if (window._dashSaveTimer) clearTimeout(window._dashSaveTimer);
  window._dashSaveTimer = setTimeout(function() {
    window._dashSaveTimer = null;
    var callbacks = window._dashSaveCallbacks || [];
    window._dashSaveCallbacks = [];
    var repEmail = _currentUser.email || '';
    sb.from('sales_dashboard')
      .upsert({
        user_id:      _currentUser.id,
        rep_email:    repEmail,
        pipeline:     _dash.pipeline     || [],
        goals:        _dash.goals        || {},
        activity:     _dash.activity     || {},
        prospect:     _dash.prospect     || {},
        demos:        _dash.demos        || [],
        activity_log: _dash.activityLog  || [],
        updated_at:   _dash._updatedAt
      }, { onConflict: 'user_id' })
      .then(function(result) {
        if (result.error) {
          console.warn('Dashboard sync error:', result.error.message);
          callbacks.forEach(function(fn) { fn(false, result.error, 'cloud'); });
        } else {
          callbacks.forEach(function(fn) { fn(true, null, 'cloud'); });
        }
      });
  }, 600);
};

