  modal.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;">'
    + '<div style="font-size:16px;font-weight:800;color:#09090b;">' + (isEdit ? 'Edit Deal' : 'Add Deal') + '</div>'
    + '<button onclick="document.getElementById(\'dash-deal-modal\').remove()" style="background:none;border:none;font-size:18px;cursor:pointer;color:#a1a1aa;">&#x2715;</button>'
    + '</div>'

    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px;">'

    // Name
    + '<div style="grid-column:1/-1;">'
    + '<label style="font-size:11px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Prospect / Agency Name</label>'
    + '<input id="dd-name" type="text" value="' + (existing ? existing.name : '') + '" placeholder="e.g. John Smith Insurance" '
    + 'style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;box-sizing:border-box;" '
    + 'onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'#e4e4e7\'">'
    + '</div>'

    // State
    + '<div>'
    + '<label style="font-size:11px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">State</label>'
    + '<select id="dd-state" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;cursor:pointer;">'
    + '<option value="">Select state...</option>'
    + US_STATES.map(function(s) {
        return '<option value="' + s + '"' + (existing && existing.state === s ? ' selected' : '') + '>' + s + '</option>';
      }).join('')
    + '</select>'
    + '</div>'

    // Size
    + '<div>'
    + '<label style="font-size:11px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Agency Size</label>'
    + '<select id="dd-size" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;cursor:pointer;">'
    + SIZES.map(function(s) {
        return '<option value="' + s.id + '"' + (existing && existing.size === s.id ? ' selected' : '') + '>' + s.label + ' \u2013 ' + s.price + '</option>';
      }).join('')
    + '</select>'
    + '</div>'

    // Stage
    + '<div>'
    + '<label style="font-size:11px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Stage</label>'
    + '<select id="dd-stage" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;cursor:pointer;">'
    + STAGES.map(function(s) {
        return '<option value="' + s + '"' + (existingStage === s ? ' selected' : '') + '>' + s + '</option>';
      }).join('')
    + '</select>'
    + '</div>'
    + (showCompleteHint ? '<div style="grid-column:1/-1;background:#ecfdf5;border:1px solid #a7f3d0;border-radius:8px;padding:10px 12px;font-size:12px;color:#047857;line-height:1.45;">Saving at <strong>Demo Completed</strong> will prompt for SDR/AE owners, add contacts to CRM, and create the opportunity.</div>' : '')

    // Notes
