window.dashSaveDeal = function(editIdx) {
  var name  = document.getElementById('dd-name');
  var state = document.getElementById('dd-state');
  var size  = document.getElementById('dd-size');
  var stage = document.getElementById('dd-stage');
  var notes = document.getElementById('dd-notes');

  if (!name || !name.value.trim()) {
    name.style.borderColor = '#ef4444';
    name.focus();
    return;
  }

  var stageVal = typeof anNormalizePipelineStageValue === 'function'
    ? anNormalizePipelineStageValue(stage ? stage.value : 'Prospecting')
    : (stage ? stage.value : 'Prospecting');
  var prev = (typeof editIdx === 'number' && editIdx !== null && _dash.pipeline[editIdx]) ? _dash.pipeline[editIdx] : null;
  var wasComplete = prev && typeof anIsDemoCompletedStage === 'function' && anIsDemoCompletedStage(prev.stage);
  var becomingComplete = typeof anIsDemoCompletedStage === 'function' && anIsDemoCompletedStage(stageVal);
  var needsCompleteFlow = becomingComplete && (!prev || !wasComplete || !prev.sdrEmail || !prev.aeEmail || !prev.leadId);

  var deal = {
    name:  name.value.trim(),
    state: state ? state.value : '',
    size:  size  ? size.value  : 'solo',
    stage: stageVal,
    notes: notes ? notes.value.trim() : '',
    updated: new Date().toISOString()
  };

  var pipeIdx;
  if (prev) {
    deal.added = prev.added || deal.updated;
    deal.leadId = prev.leadId;
    deal.demoId = prev.demoId;
    deal.sdrEmail = prev.sdrEmail;
    deal.aeEmail = prev.aeEmail;
    deal.sdrName = prev.sdrName;
    deal.aeName = prev.aeName;
    deal.company = prev.company;
    deal.contacts = prev.contacts;
    deal.contactLeadIds = prev.contactLeadIds;
    _dash.pipeline[editIdx] = Object.assign({}, prev, deal);
    pipeIdx = editIdx;
  } else {
    deal.added = deal.updated;
    _dash.pipeline.push(deal);
    pipeIdx = _dash.pipeline.length - 1;
  }

  dashSave();

  var modal = document.getElementById('dash-deal-modal');
  if (modal) modal.remove();

  if (needsCompleteFlow && typeof dashRunDealDemoCompleteFlow === 'function') {
    dashRunDealDemoCompleteFlow(pipeIdx);
    if (typeof showToast === 'function') showToast('Assign owners and contacts to finish Demo Completed');
    return;
  }

  if (typeof anSyncPipelineDealToOpportunity === 'function') {
    var savedDeal = _dash.pipeline[pipeIdx];
    if (savedDeal) anSyncPipelineDealToOpportunity(savedDeal);
    if (typeof AN !== 'undefined' && AN.save) AN.save();
    dashSave();
  }

  if (typeof renderSalesDashboard === 'function') renderSalesDashboard();
  if (typeof renderOpportunities === 'function') renderOpportunities();
  if (typeof showToast === 'function') showToast(typeof editIdx === 'number' ? 'Deal updated!' : 'Deal added!');
};

