    var stageColor = STAGE_COLORS[deal.stage] || STAGE_COLORS[stageLabel] || '#a1a1aa';
    html += '<div style="padding:8px 0;border-bottom:1px solid #f4f4f5;">'
      + '<div style="display:flex;align-items:center;gap:8px;">'
