// ── FIX 2: Contract type toggle ──────────────────────────────
var _contractType = 'mrr'; // 'mrr' | 'arr'

window.setContractType = function(type) {
  _contractType = type;
  var mBtn = document.getElementById('comm-mrr-btn');
  var aBtn = document.getElementById('comm-arr-btn');
  var note = document.getElementById('comm-contract-note');
  var badge = document.getElementById('comm-arr-badge');
  var explainer = document.getElementById('comm-arr-explainer');
  var projLabel = document.getElementById('comm-projection-label');
  var goalLabel = document.getElementById('goal-label');
  var goalPeriod = document.getElementById('goal-period-label');

  if (mBtn) { mBtn.style.background = type==='mrr'?'#6366f1':'transparent'; mBtn.style.color = type==='mrr'?'#fff':'#71717a'; }
  if (aBtn) { aBtn.style.background = type==='arr'?'#6366f1':'transparent'; aBtn.style.color = type==='arr'?'#fff':'#71717a'; }
  if (note) note.textContent = type==='mrr' ? 'Recurring monthly commission' : 'Full year commission paid in one sum';
  if (badge) badge.style.display = type==='arr' ? 'flex' : 'none';
  if (explainer) explainer.style.display = type==='arr' ? 'block' : 'none';
  if (projLabel) projLabel.textContent = type==='arr' ? 'MRR equivalent per month' : 'Annual projection (if monthly billing)';
  if (goalLabel) goalLabel.textContent = type==='arr' ? 'Annual income goal (lump sum)' : 'Monthly income goal';
  if (goalPeriod) goalPeriod.textContent = type==='arr' ? '/yr' : '/mo';

  // Show/hide ARR preview lines on rate cards
  ['solo','small','large'].forEach(function(k) {
    var el = document.getElementById('rate-' + k + '-arr');
    if (el) el.style.display = type==='arr' ? 'block' : 'none';
  });

  calcCommission();
  calcGoal();
};

// ── FIX 3: Override calcCommission to use contract type ───────
window.calcCommission = function() {
  var soloEl  = document.getElementById('comm-solo');
  var smallEl = document.getElementById('comm-small');
  var largeEl = document.getElementById('comm-large');
  var smallAgentsEl = document.getElementById('comm-small-agents');
  var largeAgentsEl = document.getElementById('comm-large-agents');
  if (!soloEl) return;

  var soloCount   = Math.max(0, parseInt(soloEl.value)  || 0);
  var smallCount  = Math.max(0, parseInt(smallEl ? smallEl.value : 0) || 0);
  var largeCount  = Math.max(0, parseInt(largeEl ? largeEl.value : 0) || 0);
  var smallAgents = Math.max(4, Math.min(9, parseInt(smallAgentsEl ? smallAgentsEl.value : 4) || 4));
  var largeAgents = Math.max(10, parseInt(largeAgentsEl ? largeAgentsEl.value : 10) || 10);

  var soloMo  = soloCount  * 79;
  var smallMo = smallCount * (typeof getSmallMonthly==='function' ? getSmallMonthly(smallAgents) : 247);
  var largeMo = largeCount * (typeof getLargeMonthly==='function' ? getLargeMonthly(largeAgents) : 597);

  var r = typeof getRates==='function' ? getRates() : {solo:0.11, small:0.10, large:0.08};

  var soloComm, smallComm, largeComm, label;

  if (_contractType === 'arr') {
    // Annual contract: full year MRR × 12 × rate, paid as one lump sum
    soloComm  = soloMo  * 12 * r.solo;
    smallComm = smallMo * 12 * r.small;
    largeComm = largeMo * 12 * r.large;
    label = 'lump sum';
  } else {
    soloComm  = soloMo  * r.solo;
    smallComm = smallMo * r.small;
    largeComm = largeMo * r.large;
    label = '/mo';
  }

  var total = soloComm + smallComm + largeComm;

  // Annual projection always shown as MRR × 12
  var annualProj = (soloMo * r.solo + smallMo * r.small + largeMo * r.large) * 12;

  function fmtN(n) { return '$' + Math.round(n).toLocaleString(); }
  function setEl(id, val) { var el=document.getElementById(id); if(el) el.textContent=val; }

  setEl('comm-solo-out',   fmtN(soloComm));
  setEl('comm-small-out',  fmtN(smallComm));
  setEl('comm-large-out',  fmtN(largeComm));
  setEl('comm-total-out',  fmtN(total));
  ['comm-solo-label','comm-small-label','comm-large-label','comm-total-label'].forEach(function(id){ setEl(id, label); });
  setEl('comm-annual-proj', fmtN(annualProj) + '/yr');

  // Breakdown text
  var soloRatePct  = document.getElementById('rate-solo')  ? document.getElementById('rate-solo').value  : 11;
  var smallRatePct = document.getElementById('rate-small') ? document.getElementById('rate-small').value : 10;
  var largeRatePct = document.getElementById('rate-large') ? document.getElementById('rate-large').value : 8;
  var contractNote = _contractType==='arr' ? ' \u00d7 12mo ARR' : '';
  var lines = [];
  if (soloCount)  lines.push(soloCount  + ' solo @ $79 \u00d7 ' + soloRatePct  + '%' + contractNote);
  if (smallCount) lines.push(smallCount + ' small @ $' + (typeof getSmallMonthly==='function'?getSmallMonthly(smallAgents):247) + ' \u00d7 ' + smallRatePct + '%' + contractNote);
  if (largeCount) lines.push(largeCount + ' large @ $' + (typeof getLargeMonthly==='function'?getLargeMonthly(largeAgents):597) + ' \u00d7 ' + largeRatePct + '%' + contractNote);
  setEl('comm-breakdown', lines.join(' \u00b7 ') || 'Enter values above to see your commission');

  // Update ARR preview lines
  if (typeof updateRatePreviews === 'function') updateRatePreviews();
};

// ── FIX 4: Override calcGoal for ARR mode ────────────────────
window.calcGoal = function() {
  var goalEl = document.getElementById('comm-goal');
  var goal = Math.max(0, parseFloat(goalEl ? goalEl.value : 0) || 0);

  function setEl(id, val) { var el=document.getElementById(id); if(el) el.textContent=val; }

  // In ARR mode, goal is annual lump sum; in MRR mode it's monthly recurring
  var r = typeof getRates==='function' ? getRates() : {solo:0.11, small:0.10, large:0.08};

  var soloPerUnit, smallPerUnit, largePerUnit;
  if (_contractType === 'arr') {
    // Per close in ARR: full year × rate
    soloPerUnit  = 79  * 12 * r.solo;
    smallPerUnit = 247 * 12 * r.small;
    largePerUnit = 597 * 12 * r.large;
    setEl('comm-goal-annual', goal > 0 ? '$' + Math.round(goal/12).toLocaleString() + '/mo equivalent' : '');
  } else {
    soloPerUnit  = 79  * r.solo;
    smallPerUnit = 247 * r.small;
    largePerUnit = 597 * r.large;
    setEl('comm-goal-annual', goal > 0 ? '$' + Math.round(goal*12).toLocaleString() + '/yr' : '');
  }

  var soloRateVal  = document.getElementById('rate-solo')  ? parseFloat(document.getElementById('rate-solo').value)  : 11;
  var smallRateVal = document.getElementById('rate-small') ? parseFloat(document.getElementById('rate-small').value) : 10;
  var largeRateVal = document.getElementById('rate-large') ? parseFloat(document.getElementById('rate-large').value) : 8;

  setEl('goal-solo-rate-lbl',  '(' + soloRateVal  + '%)');
  setEl('goal-small-rate-lbl', '(' + smallRateVal + '%)');
  setEl('goal-large-rate-lbl', '(' + largeRateVal + '%)');

  if (goal > 0) {
    setEl('goal-solo-count',  Math.ceil(goal / soloPerUnit)  + ' agents');
    setEl('goal-small-count', Math.ceil(goal / smallPerUnit) + ' agencies');
    setEl('goal-large-count', Math.ceil(goal / largePerUnit) + ' agencies');
    var mixedComm = 2*soloPerUnit + 3*smallPerUnit + 1*largePerUnit;
    var sets = Math.ceil(goal / mixedComm);
    setEl('goal-mixed-out', (sets*2)+' solo, '+(sets*3)+' small, '+sets+' large');
  } else {
    ['goal-solo-count','goal-small-count','goal-large-count','goal-mixed-out'].forEach(function(id){ setEl(id,'\u2014'); });
  }
};

// ── FIX 5: Re-inject section correctly on load ───────────────
