// ============================================================
// PATCH 16 — Admin Panel: Supabase sync, content loading,
// reps dashboard with activity stats
// ============================================================

// ── You need this SQL in Supabase (run once): ────────────────
// create table if not exists admin_content (
//   key text primary key,
//   value text,
//   updated_by text,
//   updated_at timestamp with time zone default now()
// );
// alter table admin_content enable row level security;
// create policy "Authenticated users can read admin_content"
//   on admin_content for select using (auth.role() = 'authenticated');
// create policy "Admins can write admin_content"
//   on admin_content for all using (auth.uid() is not null);
// ─────────────────────────────────────────────────────────────

// ── Load admin content from Supabase on tab switch ───────────
// Scroll admin section to top when tab switches
var _adminScrollFix = function() {
  var sec = document.getElementById('section-admin');
  if (sec) sec.scrollIntoView({ behavior: 'instant', block: 'start' });
  var mainEl = document.querySelector('.main');
  if (mainEl) mainEl.scrollTop = 0;
  window.scrollTo(0, 0);
};
var _origSwitchAdminTab = window.switchAdminTab;
window.switchAdminTab = function(tab) {
  if (typeof _origSwitchAdminTab === 'function') _origSwitchAdminTab(tab);
  if (typeof _adminScrollFix === 'function') _adminScrollFix();

  if (tab === 'scripts' || tab === 'reference' || tab === 'competition' || tab === 'pricing') {
    loadAdminContentFromSupabase();
  }
  if (tab === 'reps') {
    loadAdminRepsDashboard();
  }
};

function loadAdminContentFromSupabase() {
  var sb = typeof getSupabase === 'function' ? getSupabase() : null;
  if (!sb || !_currentUser) return;

  sb.from('admin_content')
    .select('key, value')
    .then(function(result) {
      if (result.error || !result.data) return;
      var cloudData = {};
      result.data.forEach(function(row) { cloudData[row.key] = row.value; });

      // Merge into localStorage
      var local = {};
      try { local = JSON.parse(localStorage.getItem('admin-scripts') || '{}'); } catch(e){}
      Object.keys(cloudData).forEach(function(k) { local[k] = cloudData[k]; });
      localStorage.setItem('admin-scripts', JSON.stringify(local));

      // Fill textareas
      Object.keys(cloudData).forEach(function(k) {
        var el = document.getElementById('afield-' + k);
        if (el) el.value = cloudData[k];
      });
    });
}

// ── Override saveAField to show better feedback ───────────────
var _origSaveAField = window.saveAField;
window.saveAField = function(key) {
  var el = document.getElementById('afield-' + key);
  if (!el) return;

  // Save to localStorage
  var saved = {};
  try { saved = JSON.parse(localStorage.getItem('admin-scripts') || '{}'); } catch(e) {}
  saved[key] = el.value;
  localStorage.setItem('admin-scripts', JSON.stringify(saved));

  var sb = typeof getSupabase === 'function' ? getSupabase() : null;
  if (sb && _currentUser) {
    sb.from('admin_content')
      .upsert({ key: key, value: el.value, updated_by: _currentUser.email, updated_at: new Date().toISOString() })
      .then(function(r) {
        if (r.error) {
          // Table might not exist yet — show SQL instructions
          showAdminSQLNotice();
          if (typeof showToast === 'function') showToast('Saved locally. See SQL setup notice.');
        } else {
          if (typeof showToast === 'function') showToast('Saved to team cloud!');
          // Flash the button green
          var btn = el.parentElement ? el.parentElement.querySelector('.aedit-btn') : null;
          if (btn) {
            btn.style.background = '#10b981';
            btn.textContent = '✓ Saved';
            setTimeout(function() {
              btn.style.background = '';
              btn.textContent = 'Save';
            }, 2000);
          }
        }
      });
  } else {
    if (typeof showToast === 'function') showToast('Saved locally. Sign in to sync with team.');
  }
};

function showAdminSQLNotice() {
  if (document.getElementById('admin-sql-notice')) return;
  var notice = document.createElement('div');
  notice.id = 'admin-sql-notice';
  notice.style.cssText = 'background:#fffbeb;border:1px solid #f59e0b;border-radius:10px;padding:14px 16px;margin-bottom:16px;font-size:12px;color:#92400e;line-height:1.6;';
  notice.innerHTML = '<strong style="font-size:13px;">⚠ One-time Supabase setup needed</strong><br>'
    + 'Run this SQL in your Supabase dashboard (SQL Editor) to enable cloud saving for admin content:<br>'
    + '<code style="display:block;background:rgba(0,0,0,0.06);border-radius:6px;padding:8px;margin-top:8px;font-size:11px;white-space:pre-wrap;">'
    + 'create table if not exists admin_content (\n'
    + '  key text primary key,\n'
    + '  value text,\n'
    + '  updated_by text,\n'
    + '  updated_at timestamp with time zone default now()\n'
    + ');\n'
    + 'alter table admin_content enable row level security;\n'
    + 'create policy "read" on admin_content for select using (auth.role() = \'authenticated\');\n'
    + 'create policy "write" on admin_content for all using (auth.uid() is not null);'
    + '</code>'
    + '<button onclick="this.closest(\'#admin-sql-notice\').remove()" style="margin-top:8px;background:none;border:1px solid #f59e0b;border-radius:6px;padding:3px 10px;font-size:11px;cursor:pointer;font-family:inherit;color:#92400e;">Dismiss</button>';

  var adminContent = document.querySelector('#section-admin .content');
  if (adminContent) adminContent.insertBefore(notice, adminContent.firstChild);
}

// ── Replace reps panel with real dashboard ───────────────────
window.loadAdminRepsDashboard = function() {
  var listEl = document.getElementById('admin-reps-list');
  if (!listEl) return;

  listEl.innerHTML = '<div style="padding:20px;text-align:center;color:#71717a;font-size:13px;">Loading...</div>';

  var sb = typeof getSupabase === 'function' ? getSupabase() : null;
  if (!sb || !_currentUser) {
    listEl.innerHTML = '<div style="padding:20px;color:#71717a;font-size:13px;">Sign in to see team data.</div>';
    return;
  }

  // Pull demo_recaps + sales_dashboard for rep names and activity
  Promise.all([
    sb.from('demo_recaps').select('user_id, prospect, created_at, outcome').order('created_at', { ascending: false }).limit(500),
    sb.from('sales_dashboard').select('user_id, rep_email, pipeline, goals, activity, demos, activity_log, updated_at')
  ]).then(function(results) {
    var recapResult = results[0];
    var dashResult  = results[1];

    var recaps = (!recapResult.error && recapResult.data) ? recapResult.data : [];
    var dashes = (!dashResult.error  && dashResult.data)  ? dashResult.data  : [];

    // Build per-user map
    var userMap = {};

    recaps.forEach(function(r) {
      if (!userMap[r.user_id]) userMap[r.user_id] = { userId: r.user_id, repEmail: '', recaps: [], dash: null };
      userMap[r.user_id].recaps.push(r);
    });
    dashes.forEach(function(d) {
      if (!userMap[d.user_id]) userMap[d.user_id] = { userId: d.user_id, repEmail: '', recaps: [], dash: null };
      userMap[d.user_id].dash = d;
      if (d.rep_email) userMap[d.user_id].repEmail = d.rep_email;
    });

    var users = Object.values(userMap);
    if (!users.length) {
      listEl.innerHTML = '<div style="padding:30px;text-align:center;color:#a1a1aa;font-size:13px;">No team activity yet. Data shows here when reps log in and use the tool.</div>';
      return;
    }

    // Sort by most recent activity
    users.sort(function(a, b) {
      var aDate = a.recaps.length ? new Date(a.recaps[0].created_at) : 0;
      var bDate = b.recaps.length ? new Date(b.recaps[0].created_at) : 0;
      return bDate - aDate;
    });

    var html = '<div style="display:flex;flex-direction:column;gap:10px;padding:4px 0;">';

    users.forEach(function(u, i) {
      var dash = u.dash || {};
      var activity = dash.activity || {};
      var pipeline = dash.pipeline || [];
      var demos    = dash.demos    || [];
      var goals    = dash.goals    || {};
      var actLog   = dash.activity_log || [];

      var calls   = activity.calls  || 0;
      var demosB  = activity.demos  || 0;
      var closes  = activity.closes || 0;
      var recapCount = u.recaps.length;

      // Show rate
      var decided = demos.filter(function(d){ return d.status==='showed'||d.status==='noshow'; });
      var showed  = demos.filter(function(d){ return d.status==='showed'; }).length;
      var completedBySdr = demos.filter(function(d){ return d.status==='showed' && (d.sdrEmail || d._repEmail); }).length;
      var showRate = decided.length > 0 ? Math.round((showed/decided.length)*100) + '%' : '—';

      // Pipeline value
      var pipeVal = pipeline.filter(function(d){ return d.stage!=='Closed Lost'; })
        .reduce(function(sum, d){ var mp={solo:79,small:247,large:597}; return sum+(mp[d.size]||79); }, 0);

      var won = pipeline.filter(function(d){ return d.stage==='Closed Won'; }).length;

      // Last active
      var lastDate = dash.updated_at ? new Date(dash.updated_at).toLocaleDateString('en-US',{month:'short',day:'numeric'}) : (u.recaps.length ? new Date(u.recaps[0].created_at).toLocaleDateString('en-US',{month:'short',day:'numeric'}) : 'Never');

      // Rep identity from email
      var repEmail = u.repEmail || (dash.rep_email || '');
      var repLabel = repEmail ? repEmail.split('@')[0].replace(/[._]/g, ' ') : ('Rep #' + (i + 1));
      var repInitial = repLabel.charAt(0).toUpperCase();

      html += '<div style="background:#fff;border:1px solid #e4e4e7;border-radius:12px;padding:16px 18px;">'
        + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;">'
        + '<div style="width:34px;height:34px;border-radius:50%;background:linear-gradient(135deg,#6366f1,#8b5cf6);display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;color:#fff;flex-shrink:0;">' + repInitial + '</div>'
        + '<div style="flex:1;">'
        + '<div style="font-size:13px;font-weight:700;color:#09090b;">' + repLabel + '</div>'
        + '<div style="font-size:11px;color:#a1a1aa;">' + (repEmail || 'No email on file') + ' &middot; Last active: ' + lastDate + ' &middot; ' + recapCount + ' demo recap' + (recapCount!==1?'s':'') + '</div>'
        + '</div>'
        + (won > 0 ? '<span style="background:#ecfdf5;color:#10b981;font-size:11px;font-weight:700;padding:3px 10px;border-radius:10px;">' + won + ' won</span>' : '')
        + '</div>'

        // Stat grid
        + '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:8px;">'
        + adminStatCell('Calls', calls, '#6366f1')
        + adminStatCell('Demos Booked', demosB, '#8b5cf6')
        + adminStatCell('Completed', completedBySdr || showed, '#10b981')
        + adminStatCell('Closes', closes, '#f59e0b')
        + adminStatCell('Show Rate', showRate, '#06b6d4')
        + adminStatCell('Pipeline $', pipeVal > 0 ? '$'+pipeVal+'/mo' : '—', '#10b981')
        + adminStatCell('Deals', pipeline.length, '#a1a1aa')
        + '</div>'

        // Activity log mini chart (last 7 days calls)
        + (actLog.length > 0 ? buildMiniActivity(actLog) : '')

        + '</div>';
    });

    html += '</div>';
    listEl.innerHTML = html;
  }).catch(function(e) {
    listEl.innerHTML = '<div style="padding:20px;color:#ef4444;font-size:13px;">Error loading data: ' + e.message + '</div>';
  });
};

// Rebuild the loadAdminReps to use new dashboard
window.loadAdminReps = window.loadAdminRepsDashboard;

// ── Invite a new rep via Supabase Auth ───────────────────────
window.adminInviteRep = function() {
  var nameEl  = document.getElementById('admin-rep-name');
  var emailEl = document.getElementById('admin-rep-email');
  var statusEl = document.getElementById('admin-invite-status');
  if (!nameEl || !emailEl || !statusEl) return;

  var name  = nameEl.value.trim();
  var email = emailEl.value.trim().toLowerCase();

  if (!name) { showAdminRepStatus('error', 'Please enter the rep\'s name.'); return; }
  if (!email || !email.includes('@')) { showAdminRepStatus('error', 'Please enter a valid email address.'); return; }

  showAdminRepStatus('loading', 'Sending invite to ' + email + '...');

  var sb = typeof getSupabase === 'function' ? getSupabase() : null;
  if (!sb) {
    showAdminRepStatus('error', 'Supabase not connected. Please sign in first.');
    return;
  }

  // Use Supabase admin invite (requires service role key server-side, so we use signUp with emailRedirectTo)
  // For Supabase Auth, inviteUserByEmail is admin-only; we use the standard signup flow instead
  sb.auth.signUp({
    email: email,
    password: Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2) + 'Aa1!',
    options: {
      data: { full_name: name },
      emailRedirectTo: window.location.origin + window.location.pathname
    }
  }).then(function(result) {
    if (result.error) {
      // If user already exists, treat as success (they just need to log in)
      if (result.error.message && result.error.message.includes('already registered')) {
        showAdminRepStatus('success', '✓ ' + name + ' (' + email + ') already has an account. They can log in anytime.');
        // Still add to rep views
        if (!_repViews[email]) { _repViews[email] = { hidden: [] }; saveRepViews(); }
      } else {
        showAdminRepStatus('error', 'Error: ' + result.error.message);
      }
      return;
    }
    showAdminRepStatus('success', '✓ Invite sent to ' + email + '! They will receive a confirmation email with login instructions.');
    // Add to local rep views list
    if (!_repViews[email]) { _repViews[email] = { hidden: [] }; saveRepViews(); }
    // Clear form
    nameEl.value = '';
    emailEl.value = '';
    // Refresh the reps list after a moment
    setTimeout(loadAdminRepsDashboard, 600);
  }).catch(function(e) {
    showAdminRepStatus('error', 'Error: ' + e.message);
  });
};

function showAdminRepStatus(type, msg) {
  var el = document.getElementById('admin-invite-status');
  if (!el) return;
  el.style.display = 'block';
  var colors = { success: { bg:'#ecfdf5', border:'#a7f3d0', text:'#065f46' }, error: { bg:'#fef2f2', border:'#fecaca', text:'#991b1b' }, loading: { bg:'#eef2ff', border:'#c7d2fe', text:'#3730a3' } };
  var c = colors[type] || colors.loading;
  el.style.cssText = 'margin-top:10px;font-size:12px;padding:9px 13px;border-radius:8px;background:'+c.bg+';border:1px solid '+c.border+';color:'+c.text+';display:block;';
  el.textContent = msg;
}

function adminStatCell(label, value, color) {
  return '<div style="background:#f8f8fa;border-radius:8px;padding:8px 10px;text-align:center;">'
    + '<div style="font-size:16px;font-weight:800;color:' + color + ';">' + value + '</div>'
    + '<div style="font-size:9px;font-weight:600;color:#a1a1aa;text-transform:uppercase;letter-spacing:0.08em;margin-top:2px;">' + label + '</div>'
    + '</div>';
}

function buildMiniActivity(actLog) {
  // Last 7 days
  var days = [];
  var now = new Date();
  for (var i = 6; i >= 0; i--) {
    var d = new Date(now);
    d.setDate(d.getDate() - i);
    days.push(d.toISOString().split('T')[0]);
  }

  var maxCalls = 1;
  var callsByDay = days.map(function(date) {
    var entry = actLog.filter(function(e){ return e.date === date; })[0];
    var v = entry ? (entry.calls || 0) : 0;
    if (v > maxCalls) maxCalls = v;
    return v;
  });

  var bars = days.map(function(date, i) {
    var v = callsByDay[i];
    var h = maxCalls > 0 ? Math.max(4, Math.round((v / maxCalls) * 28)) : 4;
    var d = new Date(date + 'T12:00:00');
    var label = d.toLocaleDateString('en-US', { weekday: 'short' });
    return '<div style="display:flex;flex-direction:column;align-items:center;gap:2px;flex:1;">'
      + '<div style="font-size:9px;font-weight:700;color:#6366f1;min-height:14px;">' + (v > 0 ? v : '') + '</div>'
      + '<div style="width:100%;max-width:20px;background:' + (v > 0 ? '#6366f1' : '#e4e4e7') + ';border-radius:3px;height:' + h + 'px;"></div>'
      + '<div style="font-size:8px;color:#a1a1aa;">' + label + '</div>'
      + '</div>';
  }).join('');

  return '<div style="margin-top:10px;padding-top:10px;border-top:1px solid #f4f4f5;">'
    + '<div style="font-size:9px;font-weight:700;color:#a1a1aa;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:6px;">Calls — Last 7 days</div>'
    + '<div style="display:flex;gap:4px;align-items:flex-end;height:52px;">' + bars + '</div>'
    + '</div>';
}

