// ── Hotzone data builder ──────────────────────────────────────
function buildHotzoneChartData() {
  var hourData = {};
  for (var h = 7; h <= 19; h++) hourData[h] = 0;
  (typeof anGetScopedActivityLog === 'function' ? anGetScopedActivityLog() : (_dash.activityLog||[])).forEach(function(entry){
    if (entry.calls_by_hour) {
      Object.keys(entry.calls_by_hour).forEach(function(h){
        var hr = parseInt(h);
        if (hr>=7&&hr<=19) hourData[hr]=(hourData[hr]||0)+entry.calls_by_hour[h];
      });
    }
  });
  var hours = Object.keys(hourData).map(Number).sort(function(a,b){return a-b;});
  var values = hours.map(function(h){return hourData[h];});
  var maxVal = Math.max.apply(null,values)||1;
  var labels = hours.map(function(h){ var a=h<12?'am':'pm'; var h12=h>12?h-12:(h===0?12:h); return h12+a; });
  var sorted = hours.slice().sort(function(a,b){return (hourData[b]||0)-(hourData[a]||0);});
  return { labels:labels, values:values, hours:hours, hourData:hourData, topHours:sorted.slice(0,3).filter(function(h){return hourData[h]>0;}), maxVal:maxVal };
}

// ── Goals card builder ────────────────────────────────────────
window.buildGoalsCard = function() {
  var card = document.createElement('div');
  card.style.cssText = 'background:#fff;border:1px solid #e4e4e7;border-radius:12px;overflow:hidden;';
  var actData = getActivityForPeriod(_goalPeriod);
  var KEYS=['calls','demos','closes'], LABELS=['Calls Made','Demos Booked','Closes'], COLORS=['#6366f1','#10b981','#f59e0b'];
  var periodBtns = ['today','week','month'].map(function(p){
    var lbl={today:'Today',week:'Week',month:'Month'}[p];
    return '<button id="gp-'+p+'" onclick="fastSetGoalPeriod(\''+p+'\')" style="padding:4px 10px;border-radius:6px;border:none;font-size:11px;font-weight:600;cursor:pointer;font-family:inherit;'+(_goalPeriod===p?'background:#6366f1;color:#fff;':'background:transparent;color:#71717a;')+'">'+lbl+'</button>';
  }).join('');
  var rows = KEYS.map(function(key,i){
    var actual=actData[key]||0, goal=getGoalForPeriod(key,_goalPeriod), pct=goal>0?Math.min(100,Math.round(actual/goal*100)):0;
    return '<div style="margin-bottom:14px;">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;">'
      +'<span style="font-size:12px;font-weight:600;color:#09090b;">'+LABELS[i]+'</span>'
      +'<div style="display:flex;align-items:center;gap:5px;">'
      +'<button onclick="dashDecrP(\''+key+'\')" style="width:22px;height:22px;border-radius:50%;background:#f4f4f5;border:none;cursor:pointer;font-size:13px;">-</button>'
      +'<input id="gact-'+key+'" type="number" min="0" value="'+actual+'" oninput="dashSetAct(\''+key+'\',this.value)" style="width:58px;text-align:center;border:1.5px solid #e4e4e7;border-radius:6px;font-size:14px;font-weight:800;color:'+COLORS[i]+';font-family:inherit;outline:none;padding:2px 4px;">'
      +'<button onclick="dashIncrP(\''+key+'\')" style="width:22px;height:22px;border-radius:50%;background:'+COLORS[i]+';border:none;cursor:pointer;font-size:13px;color:#fff;">+</button>'
      +'<span style="font-size:11px;color:#a1a1aa;">/ <input id="gg-'+key+'" type="number" min="0" value="'+goal+'" oninput="saveGoalP(\''+key+'\',_goalPeriod,parseInt(this.value)||0)" style="width:32px;border:none;background:none;font-size:11px;color:#a1a1aa;font-family:inherit;outline:none;padding:0;"></span>'
      +'</div></div>'
      +'<div style="background:#f4f4f5;border-radius:20px;height:5px;overflow:hidden;">'
      +'<div id="gb-'+key+'" style="background:'+COLORS[i]+';height:5px;border-radius:20px;width:'+pct+'%;transition:width 0.3s;"></div>'
      +'</div></div>';
  }).join('');
  card.innerHTML = '<div style="padding:14px 18px;border-bottom:1px solid #e4e4e7;background:#f8f8fa;display:flex;align-items:center;justify-content:space-between;">'
    +'<div><div style="font-size:10px;font-weight:700;color:#6366f1;text-transform:uppercase;letter-spacing:0.12em;">Activity Goals</div>'
    +'<div style="font-size:11px;color:#71717a;margin-top:1px;">Click number to edit · use View history for past days &amp; leadership prep</div></div>'
    +'<div style="display:flex;background:#f4f4f5;border-radius:8px;padding:2px;gap:1px;">'+periodBtns+'</div>'
    +'</div>'
    +'<div style="padding:16px 18px;">'+rows+'</div>'
    +'<div style="padding:0 18px 14px;display:flex;justify-content:space-between;">'
    +'<button onclick="openActivityHistory()" style="font-size:11px;color:#6366f1;background:none;border:none;cursor:pointer;font-family:inherit;text-decoration:underline;">View history →</button>'
    +'<button onclick="dashResetActivity()" style="font-size:10px;color:#a1a1aa;background:none;border:none;cursor:pointer;font-family:inherit;">Reset today</button>'
    +'</div>';
  return card;
};

// ── Fast goal period switch (no full re-render) ───────────────
window.fastSetGoalPeriod = function(period) {
  _goalPeriod = period;
  ['today','week','month'].forEach(function(p){
    var b=document.getElementById('gp-'+p);
    if(b){b.style.background=p===period?'#6366f1':'transparent';b.style.color=p===period?'#fff':'#71717a';}
  });
  var actData = getActivityForPeriod(period);
  ['calls','demos','closes'].forEach(function(key){
    var inp=document.getElementById('gact-'+key), goal=document.getElementById('gg-'+key), bar=document.getElementById('gb-'+key);
    var actual=actData[key]||0, gv=getGoalForPeriod(key,period), pct=gv>0?Math.min(100,Math.round(actual/gv*100)):0;
    if(inp) inp.value=actual; if(goal) goal.value=gv; if(bar) bar.style.width=pct+'%';
  });
};

window.saveGoalP = function(key,period,val){ if(!_dash.goals)_dash.goals={}; var sfx=period==='today'?'':'_'+period; _dash.goals[key+sfx]=val; dashSave(); };
window.saveGoalForPeriod = window.saveGoalP;

window.dashIncrP = function(key){
  var today = typeof anLocalDateStr === 'function' ? anLocalDateStr() : new Date().toISOString().split('T')[0];
  if(!_dash.activityLog) _dash.activityLog=[];
  var e=_dash.activityLog.filter(function(x){return x.date===today;})[0];
  if(!e){e={date:today,calls:0,demos:0,closes:0};_dash.activityLog.push(e);}
  e[key]=(e[key]||0)+1;
  _dash.activity[key]=(_dash.activity[key]||0)+1;
  if(key==='calls'){if(!e.calls_by_hour)e.calls_by_hour={};var hr=new Date().getHours();e.calls_by_hour[hr]=(e.calls_by_hour[hr]||0)+1;}
  if (typeof anPushTeamActivityCloud === 'function') {
    var delta = {}; delta[key] = 1;
    anPushTeamActivityCloud(delta);
  }
  dashSave();
  var actData=getActivityForPeriod(_goalPeriod), inp=document.getElementById('gact-'+key);
  if(inp) inp.value=actData[key]||0;
  updateGB(key);
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();
  if (typeof refreshActiveCharts === 'function') refreshActiveCharts();
};
window.dashDecrP = function(key){
  var today = typeof anLocalDateStr === 'function' ? anLocalDateStr() : new Date().toISOString().split('T')[0];
  if(!_dash.activityLog) _dash.activityLog=[];
  var e=_dash.activityLog.filter(function(x){return x.date===today;})[0];
  if(e&&e[key]>0) e[key]--;
  if(_dash.activity[key]>0) _dash.activity[key]--;
  dashSave();
  var actData=getActivityForPeriod(_goalPeriod), inp=document.getElementById('gact-'+key);
  if(inp) inp.value=actData[key]||0;
  updateGB(key);
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();
};
window.dashSetAct = function(key,val){
  var n=Math.max(0,parseInt(val)||0);
  var today = typeof anLocalDateStr === 'function' ? anLocalDateStr() : new Date().toISOString().split('T')[0];
  if(!_dash.activityLog) _dash.activityLog=[];
  var e=_dash.activityLog.filter(function(x){return x.date===today;})[0];
  if(!e){e={date:today,calls:0,demos:0,closes:0};_dash.activityLog.push(e);}
  if(_goalPeriod==='today'){
    var prev = e[key] || 0;
    e[key]=n;
    _dash.activity[key]=n;
    if (typeof anPushTeamActivityCloud === 'function' && n > prev) {
      var delta = {}; delta[key] = n - prev;
      anPushTeamActivityCloud(delta);
    }
  }
  dashSave(); updateGB(key);
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();
  if (typeof refreshActiveCharts === 'function') refreshActiveCharts();
};
function updateGB(key){
  var actData=getActivityForPeriod(_goalPeriod), gv=getGoalForPeriod(key,_goalPeriod), actual=actData[key]||0;
  var pct=gv>0?Math.min(100,Math.round(actual/gv*100)):0;
  var bar=document.getElementById('gb-'+key); if(bar) bar.style.width=pct+'%';
}
window.dashIncrement=window.dashIncrP;
window.dashDecrement=window.dashDecrP;

// ── Activity history modal ────────────────────────────────────
window.openActivityHistory = function openActivityHistory() {
  var old=document.getElementById('ah-modal'); if(old) old.remove();
  var log=(_dash.activityLog||[]).slice().sort(function(a,b){return b.date.localeCompare(a.date);});
  var wk=getActivityForPeriod('week'), mo=getActivityForPeriod('month');
  var rows=log.length?log.map(function(e){
    var d=new Date(e.date+'T12:00:00');
    var lbl=d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});
    return '<div style="display:grid;grid-template-columns:120px 1fr 1fr 1fr auto;gap:8px;align-items:center;padding:8px 0;border-bottom:1px solid #f4f4f5;">'
      +'<div style="font-size:12px;font-weight:600;color:#09090b;">'+lbl+'</div>'
      +'<div style="text-align:center;"><span style="font-size:14px;font-weight:700;color:#6366f1;">'+(e.calls||0)+'</span><div style="font-size:9px;color:#a1a1aa;">Calls</div></div>'
      +'<div style="text-align:center;"><span style="font-size:14px;font-weight:700;color:#10b981;">'+(e.demos||0)+'</span><div style="font-size:9px;color:#a1a1aa;">Demos</div></div>'
      +'<div style="text-align:center;"><span style="font-size:14px;font-weight:700;color:#f59e0b;">'+(e.closes||0)+'</span><div style="font-size:9px;color:#a1a1aa;">Closes</div></div>'
      +'<button onclick="editActivityDay(\''+e.date+'\')" style="background:none;border:none;color:#6366f1;cursor:pointer;font-size:11px;font-weight:700;margin-right:4px;">Edit</button>'
      +'<button onclick="delActivityDay(\''+e.date+'\')" style="background:none;border:none;color:#d4d4d8;cursor:pointer;">&#x2715;</button>'
      +'</div>';
  }).join(''):'<div style="text-align:center;padding:32px;color:#a1a1aa;">No activity logged yet.</div>';

  var ov=document.createElement('div');
  ov.id='ah-modal';
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;';
  ov.innerHTML='<div style="background:#fff;border-radius:14px;padding:24px;width:560px;max-width:95vw;max-height:85vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,0.3);">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;"><div style="font-size:16px;font-weight:800;">Activity History</div>'
    +'<button onclick="document.getElementById(\'ah-modal\').remove()" style="background:none;border:none;font-size:18px;cursor:pointer;color:#a1a1aa;">&#x2715;</button></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px;">'
    +'<div style="background:#f8f8fa;border-radius:10px;padding:12px 14px;"><div style="font-size:10px;font-weight:700;color:#6366f1;text-transform:uppercase;margin-bottom:6px;">This Week</div>'
    +'<div style="display:flex;gap:14px;">'
    +'<div><span style="font-size:18px;font-weight:800;color:#6366f1;">'+wk.calls+'</span><div style="font-size:10px;color:#a1a1aa;">Calls</div></div>'
    +'<div><span style="font-size:18px;font-weight:800;color:#10b981;">'+wk.demos+'</span><div style="font-size:10px;color:#a1a1aa;">Demos</div></div>'
    +'<div><span style="font-size:18px;font-weight:800;color:#f59e0b;">'+wk.closes+'</span><div style="font-size:10px;color:#a1a1aa;">Closes</div></div>'
    +'</div></div>'
    +'<div style="background:#f8f8fa;border-radius:10px;padding:12px 14px;"><div style="font-size:10px;font-weight:700;color:#8b5cf6;text-transform:uppercase;margin-bottom:6px;">This Month</div>'
    +'<div style="display:flex;gap:14px;">'
    +'<div><span style="font-size:18px;font-weight:800;color:#6366f1;">'+mo.calls+'</span><div style="font-size:10px;color:#a1a1aa;">Calls</div></div>'
    +'<div><span style="font-size:18px;font-weight:800;color:#10b981;">'+mo.demos+'</span><div style="font-size:10px;color:#a1a1aa;">Demos</div></div>'
    +'<div><span style="font-size:18px;font-weight:800;color:#f59e0b;">'+mo.closes+'</span><div style="font-size:10px;color:#a1a1aa;">Closes</div></div>'
    +'</div></div></div>'
    +'<div style="background:#eef2ff;border-radius:10px;padding:12px 14px;margin-bottom:14px;">'
    +'<div style="font-size:11px;font-weight:700;color:#6366f1;margin-bottom:8px;">Log Past Activity</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">'
    +'<input id="hd" type="date" value="'+(typeof anLocalDateStr==='function'?anLocalDateStr():new Date().toISOString().split('T')[0])+'" style="border:1.5px solid #e4e4e7;border-radius:6px;padding:6px 8px;font-size:12px;font-family:inherit;outline:none;">'
    +'<input id="hc" type="number" min="0" placeholder="Calls" style="width:62px;border:1.5px solid #e4e4e7;border-radius:6px;padding:6px 8px;font-size:12px;font-family:inherit;outline:none;">'
    +'<input id="hdm" type="number" min="0" placeholder="Demos" style="width:62px;border:1.5px solid #e4e4e7;border-radius:6px;padding:6px 8px;font-size:12px;font-family:inherit;outline:none;">'
    +'<input id="hcl" type="number" min="0" placeholder="Closes" style="width:62px;border:1.5px solid #e4e4e7;border-radius:6px;padding:6px 8px;font-size:12px;font-family:inherit;outline:none;">'
    +'<button onclick="saveHistEntry()" style="background:#6366f1;color:#fff;border:none;border-radius:6px;padding:7px 14px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">Save</button>'
    +'</div></div>'
    +'<div style="max-height:320px;overflow-y:auto;">'+rows+'</div>'
    +'</div>';
  document.body.appendChild(ov);
  ov.onclick=function(e){if(e.target===ov) ov.remove();};
};

window.saveHistEntry=function(){
  var d=document.getElementById('hd'),c=document.getElementById('hc'),dm=document.getElementById('hdm'),cl=document.getElementById('hcl');
  if(!d||!d.value) return;
  if(!_dash.activityLog) _dash.activityLog=[];
  var ex=_dash.activityLog.filter(function(e){return e.date===d.value;})[0];
  var calls=parseInt(c?c.value:0)||0, demos=parseInt(dm?dm.value:0)||0, closes=parseInt(cl?cl.value:0)||0;
  if(ex){ex.calls=calls;ex.demos=demos;ex.closes=closes;}
  else _dash.activityLog.push({date:d.value,calls:calls,demos:demos,closes:closes});
  if (d.value === (typeof anLocalDateStr === 'function' ? anLocalDateStr() : '')) {
    _dash.activity = { calls: calls, demos: demos, closes: closes };
  }
  dashSave();
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();
  if (typeof refreshActiveCharts === 'function') refreshActiveCharts();
  if(typeof showToast==='function') showToast('Logged!');
  openActivityHistory();
};

window.editActivityDay = function(dateStr) {
  var old = document.getElementById('ah-edit-modal'); if (old) old.remove();
  var e = (_dash.activityLog || []).find(function(x) { return x.date === dateStr; }) || { date: dateStr, calls: 0, demos: 0, closes: 0 };
  var ov = document.createElement('div');
  ov.id = 'ah-edit-modal';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:10060;display:flex;align-items:center;justify-content:center;';
  ov.innerHTML = '<div style="background:#fff;border-radius:14px;padding:22px;width:380px;max-width:95vw;box-shadow:0 20px 60px rgba(0,0,0,0.3);">'
    +'<div style="font-size:15px;font-weight:800;margin-bottom:14px;">Edit Activity — '+dateStr+'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:16px;">'
    +'<div><label style="font-size:10px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">Calls</label><input id="ahe-c" type="number" min="0" value="'+(e.calls||0)+'" style="width:100%;border:1.5px solid #e4e4e7;border-radius:6px;padding:7px;font-size:13px;font-family:inherit;box-sizing:border-box;"></div>'
    +'<div><label style="font-size:10px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">Demos</label><input id="ahe-d" type="number" min="0" value="'+(e.demos||0)+'" style="width:100%;border:1.5px solid #e4e4e7;border-radius:6px;padding:7px;font-size:13px;font-family:inherit;box-sizing:border-box;"></div>'
    +'<div><label style="font-size:10px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">Closes</label><input id="ahe-cl" type="number" min="0" value="'+(e.closes||0)+'" style="width:100%;border:1.5px solid #e4e4e7;border-radius:6px;padding:7px;font-size:13px;font-family:inherit;box-sizing:border-box;"></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;">'
    +'<button onclick="document.getElementById(\'ah-edit-modal\').remove()" style="padding:8px 14px;border:1.5px solid #e4e4e7;border-radius:8px;background:#fff;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;color:#71717a;">Cancel</button>'
    +'<button onclick="saveActivityDayEdit(\''+dateStr+'\')" style="padding:8px 14px;border:none;border-radius:8px;background:#6366f1;color:#fff;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">Save</button>'
    +'</div></div>';
  document.body.appendChild(ov);
  ov.onclick = function(ev) { if (ev.target === ov) ov.remove(); };
};

window.saveActivityDayEdit = function(dateStr) {
  var c = document.getElementById('ahe-c'), d = document.getElementById('ahe-d'), cl = document.getElementById('ahe-cl');
  if (!_dash.activityLog) _dash.activityLog = [];
  var ex = _dash.activityLog.find(function(e) { return e.date === dateStr; });
  var calls = parseInt(c ? c.value : 0) || 0, demos = parseInt(d ? d.value : 0) || 0, closes = parseInt(cl ? cl.value : 0) || 0;
  if (ex) { ex.calls = calls; ex.demos = demos; ex.closes = closes; }
  else _dash.activityLog.push({ date: dateStr, calls: calls, demos: demos, closes: closes });
  if (dateStr === (typeof anLocalDateStr === 'function' ? anLocalDateStr() : '')) {
    _dash.activity = { calls: calls, demos: demos, closes: closes };
  }
  dashSave();
  var em = document.getElementById('ah-edit-modal'); if (em) em.remove();
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();
  if (typeof refreshActiveCharts === 'function') refreshActiveCharts();
  if (typeof showToast === 'function') showToast('Activity updated');
  if (document.getElementById('ah-modal')) openActivityHistory();
  if (document.getElementById('dash-drilldown-modal') && typeof dashOpenDrilldown === 'function') dashOpenDrilldown('calls');
};

window.delActivityDay=function(dt){
  _dash.activityLog=(_dash.activityLog||[]).filter(function(e){return e.date!==dt;});
  dashSave();
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();
  if (typeof refreshActiveCharts === 'function') refreshActiveCharts();
  openActivityHistory();
};

// ── Hotzone HTML builder ──────────────────────────────────────
function buildHotzoneHTML() {
  var data=buildHotzoneChartData();
  var slots=[{l:'Early Morning',h:[7,8],e:'🌅'},{l:'Morning',h:[9,10,11],e:'☀️'},{l:'Midday',h:[12,13],e:'🕛'},{l:'Afternoon',h:[14,15,16],e:'🌤️'},{l:'Late Day',h:[17,18,19],e:'🌇'}];
  var total=data.values.reduce(function(s,v){return s+v;},0);
  var medals=['🥇','🥈','🥉'];
  var topCards=data.topHours.length
    ?'<div style="margin-bottom:20px;"><div style="font-size:11px;font-weight:700;color:#f59e0b;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:10px;">🔥 Your Hottest Hours</div>'
      +'<div style="display:grid;grid-template-columns:repeat('+Math.max(1,data.topHours.length)+',1fr);gap:10px;margin-bottom:16px;">'
      +data.topHours.map(function(h,i){var a=h<12?'am':'pm';var h12=h>12?h-12:(h===0?12:h);var c=['#f59e0b','#6366f1','#10b981'][i];return '<div style="background:#fff;border:1px solid #e4e4e7;border-radius:10px;padding:14px;text-align:center;"><div style="font-size:20px;margin-bottom:4px;">'+medals[i]+'</div><div style="font-size:22px;font-weight:800;color:'+c+';">'+h12+a+'</div><div style="font-size:11px;color:#71717a;margin-top:2px;">'+(data.hourData[h]||0)+' calls</div></div>';}).join('')
      +'</div></div>'
    :'<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:10px;padding:14px;margin-bottom:16px;font-size:12px;color:#92400e;">Use the + Calls button throughout the day and hotzone data will build up over time.</div>';
  var slotRows=slots.map(function(slot){
    var sc=slot.h.reduce(function(s,h){return s+(data.hourData[h]||0);},0);
    var pct=total>0?Math.round(sc/total*100):0;
    return '<div style="display:flex;align-items:center;gap:12px;margin-bottom:10px;">'
      +'<div style="width:130px;font-size:12px;font-weight:600;color:#09090b;display:flex;align-items:center;gap:6px;"><span>'+slot.e+'</span><span>'+slot.l+'</span></div>'
      +'<div style="flex:1;background:#f4f4f5;border-radius:20px;height:8px;overflow:hidden;"><div style="background:'+(pct>=30?'#10b981':pct>=20?'#6366f1':'#e4e4e7')+';height:8px;border-radius:20px;width:'+pct+'%;transition:width 0.4s;"></div></div>'
      +'<div style="width:56px;text-align:right;font-size:12px;font-weight:700;color:#09090b;">'+sc+' calls</div>'
      +'<div style="width:34px;text-align:right;font-size:11px;color:#71717a;">'+pct+'%</div>'
      +'</div>';
  }).join('');
  return '<div>'+topCards
    +'<div style="background:#fff;border:1px solid #e4e4e7;border-radius:12px;padding:18px;margin-bottom:16px;">'
    +'<div style="font-size:11px;font-weight:700;color:#6366f1;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:12px;">Calls by Hour of Day</div>'
    +'<canvas id="chart-hotzone" height="180"></canvas></div>'
    +'<div style="background:#fff;border:1px solid #e4e4e7;border-radius:12px;padding:18px;">'
    +'<div style="font-size:11px;font-weight:700;color:#10b981;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:12px;">Activity by Time of Day</div>'
    +slotRows+'</div></div>';
}

// ── Demo tracker HTML builders ────────────────────────────────
function buildDemoListHTML() {
  var demos = typeof dashGetScopedDemosAnyDate === 'function' ? dashGetScopedDemosAnyDate() : (_dash.demos||[]);
  if(!demos.length) return '<div style="text-align:center;padding:48px;border:2px dashed #e4e4e7;border-radius:12px;color:#a1a1aa;"><div style="font-size:32px;margin-bottom:10px;">📅</div><div style="font-size:14px;font-weight:600;color:#71717a;margin-bottom:6px;">No demos in '+dashRangeLabel().toLowerCase()+'</div><button onclick="openAddDemo()" style="background:#6366f1;color:#fff;border:none;border-radius:8px;padding:9px 18px;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">+ Log Demo</button></div>';
  var SC={'booked':'#6366f1','showed':'#10b981','noshow':'#ef4444','rescheduled':'#f59e0b'};
  var SL={'booked':'Booked','showed':'Demo Completed','noshow':'No Show','rescheduled':'Rescheduled'};
  var sorted=demos.slice().sort(function(a,b){var o={booked:0,rescheduled:1,showed:2,noshow:3};return (o[a.status]||0)-(o[b.status]||0);});
  return '<div style="display:flex;flex-direction:column;gap:8px;">'+sorted.map(function(d,i){
    var c=SC[d.status]||'#a1a1aa';
    var szl=((typeof SIZES!=='undefined'?SIZES:[]).filter(function(s){return s.id===d.size;})[0]||{label:d.size||''}).label;
    var dt=d.scheduledDate?new Date(d.scheduledDate+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'';
    var ownerBits = '';
    if (d.sdrName || d.sdrEmail) ownerBits += 'SDR: ' + (d.sdrName || (d.sdrEmail || '').split('@')[0]);
    if (d.aeName || d.aeEmail) ownerBits += (ownerBits ? ' · ' : '') + 'AE: ' + (d.aeName || (d.aeEmail || '').split('@')[0]);
    var contactCount = (d.contacts && d.contacts.length) || (d.contactLeadIds && d.contactLeadIds.length) || 0;
    if (contactCount > 1) ownerBits += (ownerBits ? ' · ' : '') + contactCount + ' contacts';
    return '<div style="background:#fff;border:1.5px solid #e4e4e7;border-left:4px solid '+c+';border-radius:10px;padding:14px 16px;">'
      +'<div style="display:flex;align-items:center;gap:10px;">'
      +'<div style="flex:1;min-width:0;">'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;"><div onclick="anOpenDemoFromTracker(\''+d.id+'\')" style="font-size:13px;font-weight:700;color:#09090b;cursor:pointer;text-decoration:underline;text-decoration-color:rgba(99,102,241,0.35);" title="Open in CRM / Opportunities">'+d.name+'</div>'
      +'<span style="font-size:10px;font-weight:700;color:'+c+';background:'+c+'18;padding:2px 8px;border-radius:10px;">'+SL[d.status]+'</span></div>'
      +'<div style="font-size:11px;color:#71717a;">'+(d.state?d.state+' \u00b7 ':'')+szl+(dt?' \u00b7 \uD83D\uDCC5 '+dt:'')+(d.outcome?' \u00b7 '+d.outcome:'')+(ownerBits?' \u00b7 '+ownerBits:'')+'</div>'
      +(d.notes?'<div style="font-size:11px;color:#a1a1aa;margin-top:3px;font-style:italic;">'+d.notes+'</div>':'')
      +'</div>'
      +'<div style="display:flex;gap:5px;flex-shrink:0;">'
      +(d.status==='booked'||d.status==='rescheduled'
        ?'<button onclick="updDemoStatus(\''+d.id+'\',\'showed\')" style="background:#10b981;color:#fff;border:none;border-radius:6px;padding:5px 9px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">\u2713 Demo Completed</button>'
        +'<button onclick="updDemoStatus(\''+d.id+'\',\'noshow\')" style="background:#ef4444;color:#fff;border:none;border-radius:6px;padding:5px 9px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">\u2715 No Show</button>'
        +'<button onclick="updDemoStatus(\''+d.id+'\',\'rescheduled\')" style="background:#f59e0b;color:#fff;border:none;border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">\u21ba</button>'
        :'')
      +'<button onclick="anOpenDemoFromTracker(\''+d.id+'\')" style="background:#6366f1;color:#fff;border:none;border-radius:6px;padding:5px 9px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">Open</button>'
      +'<button onclick="editDemo(\''+d.id+'\')" style="background:#fff;border:1px solid #e4e4e7;color:#6366f1;border-radius:6px;padding:5px 9px;font-size:11px;font-weight:600;cursor:pointer;font-family:inherit;">Edit</button>'
      +'<button onclick="delDemo(\''+d.id+'\')" style="background:none;border:none;color:#d4d4d8;cursor:pointer;font-size:13px;padding:5px;">&#x2715;</button>'
      +'</div></div></div>';
  }).join('')+'</div>';
}

window.updDemoStatus=function(id,status){
  var d=(_dash.demos||[]).filter(function(x){return x.id===id;})[0];
  if(!d) return;
  if (status === 'showed') {
    if (typeof anOpenDemoCompleteOwnersModal === 'function') {
      anOpenDemoCompleteOwnersModal(d, { createOpp: true });
      return;
    }
  }
  d.status=status;
  d.completedDate=typeof anLocalDateStr==='function'?anLocalDateStr():new Date().toISOString().split('T')[0];
  dashSave();
  var w=document.getElementById('demo-list-wrap');
  if(w) w.innerHTML=buildDemoListHTML();
  if (typeof anRefreshSdrCommissionAfterDemo === 'function') anRefreshSdrCommissionAfterDemo(d.sdrEmail || d._repEmail);
  else if (typeof anRefreshCommissionTrackerUI === 'function') anRefreshCommissionTrackerUI();
  if(typeof showToast==='function') showToast('Updated to '+status);
};

// ── Demo completed: SDR/AE owners + opportunity creation ─────
window.anParsePersonName = function(name) {
  var parts = (name || '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return { firstName: '', lastName: '' };
  if (parts.length === 1) return { firstName: parts[0], lastName: '' };
  return { firstName: parts[0], lastName: parts.slice(1).join(' ') };
};

window.anDemoContactToLeadShape = function(contact, company) {
  var parsed = anParsePersonName((contact && contact.name) || '');
  return {
    firstName: parsed.firstName,
    lastName: parsed.lastName,
    company: (company || '').trim(),
    email: (contact && contact.email) || '',
    phone: (contact && contact.phone) || '',
    title: (contact && contact.title) || ''
  };
};

window.anFindDemoContactDuplicates = function(contact, company) {
  if (typeof AN === 'undefined' || !AN.leads || !AN.leads.length) return [];
  if (!contact) return [];
  if (!(contact.name || '').trim() && !(contact.email || '').trim() && !(contact.phone || '').trim()) return [];
  if (typeof anFindDuplicateMatches !== 'function') return [];
  return anFindDuplicateMatches(anDemoContactToLeadShape(contact, company));
};

window.anLeadMatchSummary = function(lead) {
  if (!lead) return 'Contact';
  var name = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || lead.company || 'Contact';
  var bits = [name];
  if (lead.company && lead.company !== name) bits.push(lead.company);
  if (lead.phone) bits.push(typeof anFormatPhone === 'function' ? anFormatPhone(lead.phone) : lead.phone);
  if (lead.email) bits.push(lead.email);
  return bits.join(' · ');
};

window.anGetCompanyLeadMatches = function(company) {
  if (!company || typeof AN === 'undefined' || !AN.leads) return [];
  var norm = typeof coNormName === 'function' ? coNormName(company) : company.trim().toLowerCase();
  if (!norm) return [];
  return AN.leads.filter(function(l) {
    if (typeof coNormName === 'function') return coNormName(l.company) === norm;
    return (l.company || '').trim().toLowerCase() === norm;
  });
};

window.anGetCompanyNameSuggestions = function(query, limit) {
  limit = limit || 12;
  query = (query || '').trim().toLowerCase();
  var byKey = {};
  var counts = {};

  if (typeof AN !== 'undefined' && Array.isArray(AN.leads)) {
    AN.leads.forEach(function(l) {
      var cn = (l.company || '').trim();
      if (!cn) return;
      var key = typeof coNormName === 'function' ? coNormName(cn) : cn.toLowerCase();
      counts[key] = (counts[key] || 0) + 1;
      if (!byKey[key]) byKey[key] = cn;
    });
  }
  if (typeof _coData !== 'undefined' && Array.isArray(_coData)) {
    _coData.forEach(function(c) {
      if (!c || !c.name) return;
      var key = typeof coNormName === 'function' ? coNormName(c.name) : c.name.trim().toLowerCase();
      if (!byKey[key]) byKey[key] = c.name.trim();
    });
  }

  var results = Object.keys(byKey).map(function(key) {
    return { name: byKey[key], count: counts[key] || 0, key: key };
  });

  if (query) {
    results = results.filter(function(r) {
      return r.key.indexOf(query) >= 0 || r.name.toLowerCase().indexOf(query) >= 0;
    });
  }

  results.sort(function(a, b) {
    if (query) {
      var aStart = a.name.toLowerCase().indexOf(query) === 0 ? 0 : 1;
      var bStart = b.name.toLowerCase().indexOf(query) === 0 ? 0 : 1;
      if (aStart !== bStart) return aStart - bStart;
    }
    if (b.count !== a.count) return b.count - a.count;
    return a.name.localeCompare(b.name);
  });

  return results.slice(0, limit);
};

window.anOnDemoCompanyInput = function(prefix) {
  prefix = prefix || 'dm';
  if (typeof anRefreshAllDemoContactDuplicates === 'function') anRefreshAllDemoContactDuplicates(prefix);
  var input = document.getElementById(prefix + '-company');
  var list = document.getElementById(prefix + '-company-suggest');
  if (!input || !list) return;
  var q = input.value.trim();
  if (q.length < 1) {
    list.style.display = 'none';
    list.innerHTML = '';
    return;
  }
  var suggestions = typeof anGetCompanyNameSuggestions === 'function' ? anGetCompanyNameSuggestions(q, 12) : [];
  if (!suggestions.length) {
    list.style.display = 'none';
    list.innerHTML = '';
    return;
  }
  list.innerHTML = suggestions.map(function(s) {
    var safeName = (s.name || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    return '<button type="button" onclick="anSelectDemoCompany(\'' + prefix + '\', \'' + safeName + '\')" style="display:block;width:100%;text-align:left;padding:9px 12px;border:none;background:transparent;font-size:13px;font-family:inherit;cursor:pointer;color:#09090b;" onmouseover="this.style.background=\'#f5f3ff\'" onmouseout="this.style.background=\'transparent\'">'
      + '<span style="font-weight:700;">' + anEsc(s.name) + '</span>'
      + (s.count ? '<span style="font-size:11px;color:#71717a;margin-left:6px;">' + s.count + ' contact' + (s.count !== 1 ? 's' : '') + '</span>' : '')
      + '</button>';
  }).join('');
  list.style.display = 'block';
};

window.anSelectDemoCompany = function(prefix, name) {
  prefix = prefix || 'dm';
  var input = document.getElementById(prefix + '-company');
  var list = document.getElementById(prefix + '-company-suggest');
  if (input) input.value = name || '';
  if (list) { list.style.display = 'none'; list.innerHTML = ''; }
  if (typeof anRefreshAllDemoContactDuplicates === 'function') anRefreshAllDemoContactDuplicates(prefix);
};

if (!window._anDemoCompanySuggestBound) {
  window._anDemoCompanySuggestBound = true;
  document.addEventListener('click', function(e) {
    if (e.target.closest && (e.target.closest('.an-demo-company-wrap') || e.target.closest('.an-demo-contact-wrap'))) return;
    document.querySelectorAll('.an-demo-company-suggest, .an-demo-contact-suggest').forEach(function(el) {
      el.style.display = 'none';
    });
  });
}

window.anGetContactNameSuggestions = function(query, company, limit) {
  limit = limit || 12;
  query = (query || '').trim();
  if (query.length < 1) return [];
  var results = [];
  var seen = {};

  function addLead(lead) {
    if (!lead || !lead.id || seen[lead.id]) return;
    if (!anLeadNameMatchesQuery(lead, query)) return;
    seen[lead.id] = true;
    results.push({
      id: lead.id,
      name: ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || lead.email || 'Contact',
      summary: anLeadMatchSummary(lead),
      company: (lead.company || '').trim()
    });
  }

  var companyLeads = company ? anGetCompanyLeadMatches(company) : [];
  companyLeads.forEach(addLead);

  if (results.length < limit && query.length >= 2 && typeof AN !== 'undefined' && AN.leads) {
    AN.leads.forEach(function(l) {
      if (results.length >= limit) return;
      addLead(l);
    });
  }

  var qLower = query.toLowerCase();
  results.sort(function(a, b) {
    var aStart = a.name.toLowerCase().indexOf(qLower) === 0 ? 0 : 1;
    var bStart = b.name.toLowerCase().indexOf(qLower) === 0 ? 0 : 1;
    if (aStart !== bStart) return aStart - bStart;
    if (company) {
      var aCo = a.company && typeof coNormName === 'function' ? coNormName(a.company) === coNormName(company) : false;
      var bCo = b.company && typeof coNormName === 'function' ? coNormName(b.company) === coNormName(company) : false;
      if (aCo !== bCo) return aCo ? -1 : 1;
    }
    return a.name.localeCompare(b.name);
  });

  return results.slice(0, limit);
};

window.anOnDemoContactNameInput = function(prefix, rowIdx, el) {
  prefix = prefix || 'dm';
  var row = el && el.closest ? el.closest('.' + prefix + '-contact-row') : null;
  if (!row) {
    row = document.querySelector('#' + prefix + '-contacts-list .' + prefix + '-contact-row[data-idx="' + rowIdx + '"]');
  }
  if (!row) return;

  var companyEl = document.getElementById(prefix + '-company');
  var company = companyEl ? companyEl.value.trim() : '';
  var q = el ? el.value.trim() : '';
  var list = row.querySelector('.' + prefix + '-name-suggest');
  var leadIdEl = row.querySelector('.' + prefix + '-c-lead-id');
  var linkModeEl = row.querySelector('.' + prefix + '-c-link-mode');
  if (!list) return;

  if (typeof anRefreshDemoContactDuplicateRow === 'function') anRefreshDemoContactDuplicateRow(prefix, row);

  if (q.length < 1) {
    list.style.display = 'none';
    list.innerHTML = '';
    if (leadIdEl) leadIdEl.value = '';
    if (linkModeEl) linkModeEl.value = 'auto';
    return;
  }

  if (leadIdEl && leadIdEl.value && linkModeEl && linkModeEl.value === 'link' && typeof AN !== 'undefined' && AN.leads) {
    var linked = AN.leads.find(function(l) { return l.id === leadIdEl.value; });
    if (linked) {
      var linkedName = ((linked.firstName || '') + ' ' + (linked.lastName || '')).trim();
      if (linkedName.toLowerCase() === q.toLowerCase()) {
        list.style.display = 'none';
        list.innerHTML = '';
        return;
      }
    }
  }

  if (leadIdEl) leadIdEl.value = '';
  if (linkModeEl) linkModeEl.value = 'auto';

  var suggestions = typeof anGetContactNameSuggestions === 'function' ? anGetContactNameSuggestions(q, company, 10) : [];
  var suggestStyle = 'display:block;width:100%;text-align:left;padding:9px 12px;border:none;background:transparent;font-size:13px;font-family:inherit;cursor:pointer;color:#09090b;';
  var html = suggestions.map(function(s) {
  var safeId = (s.id || '').replace(/'/g, "\\'");
    return '<button type="button" onmousedown="event.preventDefault();anSelectDemoContactName(\'' + prefix + '\',' + rowIdx + ',\'' + safeId + '\')" style="' + suggestStyle + '" onmouseover="this.style.background=\'#f5f3ff\'" onmouseout="this.style.background=\'transparent\'">'
      + '<span style="font-weight:700;">' + anEsc(s.name) + '</span>'
      + '<span style="display:block;font-size:11px;color:#71717a;margin-top:2px;">' + anEsc(s.summary) + '</span>'
      + '</button>';
  }).join('');

  var safeQ = q.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  html += '<button type="button" onmousedown="event.preventDefault();anSelectDemoContactName(\'' + prefix + '\',' + rowIdx + ',\'\',\'' + safeQ + '\')" style="' + suggestStyle + 'border-top:1px solid #f0f0f5;color:#6366f1;font-weight:700;" onmouseover="this.style.background=\'#f5f3ff\'" onmouseout="this.style.background=\'transparent\'">'
    + '➕ Create new contact: <span style="font-weight:800;">' + anEsc(q) + '</span>'
    + '</button>';

  list.innerHTML = html;
  list.style.display = 'block';
};

window.anSelectDemoContactName = function(prefix, rowIdx, leadId, typedName) {
  prefix = prefix || 'dm';
  var row = document.querySelector('#' + prefix + '-contacts-list .' + prefix + '-contact-row[data-idx="' + rowIdx + '"]');
  if (!row) return;
  var list = row.querySelector('.' + prefix + '-name-suggest');
  if (list) { list.style.display = 'none'; list.innerHTML = ''; }

  if (leadId) {
    if (typeof anOnDemoContactLinkSelect === 'function') anOnDemoContactLinkSelect(prefix, rowIdx, leadId);
    return;
  }

  var nameEl = row.querySelector('.' + prefix + '-c-name');
  if (nameEl && typedName) nameEl.value = typedName;
  if (typeof anMarkDemoContactAsNew === 'function') anMarkDemoContactAsNew(prefix, rowIdx);
};

window.anFillDemoContactFromLead = function(prefix, row, lead) {
  if (!row || !lead) return;
  var nameEl = row.querySelector('.' + prefix + '-c-name');
  var titleEl = row.querySelector('.' + prefix + '-c-title');
  var phoneEl = row.querySelector('.' + prefix + '-c-phone');
  var emailEl = row.querySelector('.' + prefix + '-c-email');
  var fullName = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim();
  if (nameEl && fullName) nameEl.value = fullName;
  if (titleEl) titleEl.value = lead.title || '';
  if (phoneEl) {
    phoneEl.value = lead.phone
      ? (typeof anFormatPhone === 'function' ? anFormatPhone(lead.phone) : lead.phone)
      : '';
  }
  if (emailEl) emailEl.value = lead.email || '';
};

window.anLeadNameMatchesQuery = function(lead, query) {
  if (!lead || !query) return false;
  query = String(query).trim().toLowerCase();
  if (!query) return false;
  var full = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim().toLowerCase();
  var email = (lead.email || '').toLowerCase();
  var phone = String(lead.phone || '').replace(/\D/g, '');
  var qphone = query.replace(/\D/g, '');
  if (full && (full.indexOf(query) >= 0 || query.indexOf(full) >= 0)) return true;
  if (email && email.indexOf(query) >= 0) return true;
  if (qphone && phone && (phone.indexOf(qphone) >= 0 || qphone.indexOf(phone) >= 0)) return true;
  var qParts = query.split(/\s+/).filter(Boolean);
  if (qParts.length && full && qParts.every(function(p) { return full.indexOf(p) >= 0; })) return true;
  return false;
};

window.anBuildDemoContactLinkSelectHTML = function(prefix, rowIdx, matches, selectedLeadId, company, nameQuery) {
  prefix = prefix || 'adc';
  matches = matches || [];
  nameQuery = (nameQuery || '').trim();
  var MAX_OPTIONS = 50;
  var allOptions = matches.slice();
  var seen = {};
  allOptions.forEach(function(l) { if (l && l.id) seen[l.id] = true; });
  var companyLeads = typeof anGetCompanyLeadMatches === 'function' ? anGetCompanyLeadMatches(company) : [];
  var totalAtAgency = companyLeads.length;

  if (nameQuery) {
    companyLeads.forEach(function(l) {
      if (!l || !l.id || seen[l.id] || allOptions.length >= MAX_OPTIONS) return;
      if (anLeadNameMatchesQuery(l, nameQuery)) {
        allOptions.push(l);
        seen[l.id] = true;
      }
    });
  }
  companyLeads.forEach(function(l) {
    if (!l || !l.id || seen[l.id] || allOptions.length >= MAX_OPTIONS) return;
    allOptions.push(l);
    seen[l.id] = true;
  });

  allOptions.sort(function(a, b) {
    if (nameQuery) {
      var am = anLeadNameMatchesQuery(a, nameQuery) ? 0 : 1;
      var bm = anLeadNameMatchesQuery(b, nameQuery) ? 0 : 1;
      if (am !== bm) return am - bm;
    }
    return anLeadMatchSummary(a).localeCompare(anLeadMatchSummary(b));
  });

  var labelExtra = totalAtAgency > MAX_OPTIONS
    ? ' <span style="font-weight:500;color:#a16207;">(' + totalAtAgency + ' at agency — showing ' + Math.min(MAX_OPTIONS, totalAtAgency) + ')</span>'
    : (totalAtAgency ? ' <span style="font-weight:500;color:#a16207;">(' + totalAtAgency + ' at agency)</span>' : '');

  var html = '<label style="font-size:10px;font-weight:700;color:#92400e;display:block;margin-bottom:4px;">Link to existing contact' + labelExtra + '</label>'
    + '<select class="' + prefix + '-link-select" onchange="anOnDemoContactLinkSelect(\'' + prefix + '\',' + rowIdx + ', this.value)" style="width:100%;border:1.5px solid #fde68a;border-radius:8px;padding:8px 10px;font-size:12px;font-family:inherit;background:#fff;cursor:pointer;">'
    + '<option value=""' + (!selectedLeadId ? ' selected' : '') + '>— Create new contact —</option>';
  allOptions.forEach(function(l) {
    var sel = selectedLeadId === l.id ? ' selected' : '';
    html += '<option value="' + anEsc(l.id) + '"' + sel + '>' + anEsc(anLeadMatchSummary(l)) + '</option>';
  });
  html += '</select>';
  return html;
};

window.anOnDemoContactLinkSelect = function(prefix, rowIdx, leadId) {
  prefix = prefix || 'adc';
  var row = document.querySelector('#' + prefix + '-contacts-list .' + prefix + '-contact-row[data-idx="' + rowIdx + '"]');
  if (!row) return;
  var leadIdEl = row.querySelector('.' + prefix + '-c-lead-id');
  var linkModeEl = row.querySelector('.' + prefix + '-c-link-mode');
  if (!leadId) {
    if (leadIdEl) leadIdEl.value = '';
    if (linkModeEl) linkModeEl.value = 'new';
    anRefreshDemoContactDuplicateRow(prefix, row);
    return;
  }
  if (typeof AN === 'undefined' || !AN.leads) return;
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  if (leadIdEl) leadIdEl.value = leadId;
  if (linkModeEl) linkModeEl.value = 'link';
  anFillDemoContactFromLead(prefix, row, lead);
  anRefreshDemoContactDuplicateRow(prefix, row);
};

window.anRefreshDemoContactDuplicateRow = function(prefix, el) {
  prefix = prefix || 'adc';
  var row = el && el.closest ? el.closest('.' + prefix + '-contact-row') : el;
  if (!row || !row.classList.contains(prefix + '-contact-row')) return;
  var panel = row.querySelector('.' + prefix + '-dupe-panel');
  var leadIdEl = row.querySelector('.' + prefix + '-c-lead-id');
  var linkModeEl = row.querySelector('.' + prefix + '-c-link-mode');
  if (!panel) return;
  var companyEl = document.getElementById(prefix + '-company');
  var company = companyEl ? companyEl.value.trim() : '';
  var name = (row.querySelector('.' + prefix + '-c-name') || {}).value || '';
  var email = (row.querySelector('.' + prefix + '-c-email') || {}).value || '';
  var phone = (row.querySelector('.' + prefix + '-c-phone') || {}).value || '';
  var linkMode = linkModeEl ? linkModeEl.value : 'auto';
  var leadId = leadIdEl ? leadIdEl.value : '';
  var rowIdx = row.getAttribute('data-idx');

  if (!name.trim() && !email.trim() && !phone.trim() && !company) {
    panel.innerHTML = '';
    return;
  }

  if (linkMode === 'link' && leadId && typeof AN !== 'undefined' && AN.leads) {
    var linkedLead = AN.leads.find(function(l) { return l.id === leadId; });
    if (linkedLead) {
      panel.innerHTML = '<div style="font-size:11px;color:#047857;background:#ecfdf5;border:1px solid #a7f3d0;border-radius:8px;padding:8px 10px;">'
        + '🔗 <strong>Linked</strong> to existing CRM contact — info auto-filled'
        + '</div>';
      return;
    }
  }

  if (linkMode === 'new' && name.trim()) {
    panel.innerHTML = '<div style="font-size:11px;color:#6366f1;background:#f5f3ff;border:1px solid #ddd6fe;border-radius:8px;padding:8px 10px;">'
      + '➕ <strong>New contact</strong> will be created in CRM'
      + '</div>';
    return;
  }

  if (!company && name.trim()) {
    panel.innerHTML = '<div style="font-size:11px;color:#b45309;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:8px 10px;">'
      + '💡 Add the agency above to see matching contacts as you type'
      + '</div>';
    return;
  }

  if (name.trim()) {
    var dupes = anFindDemoContactDuplicates({ name: name.trim(), email: email.trim(), phone: phone.trim(), title: '' }, company);
    if (dupes.length) {
      panel.innerHTML = '<div style="font-size:11px;color:#b45309;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:8px 10px;">'
        + '⚠️ Possible match in CRM — pick from suggestions or choose create new'
        + '</div>';
    } else {
      panel.innerHTML = '<div style="font-size:11px;color:#10b981;background:#ecfdf5;border:1px solid #bbf7d0;border-radius:8px;padding:8px 10px;">'
        + '✓ Type to search contacts at this agency, or create new'
        + '</div>';
    }
    if (linkMode === 'auto' && leadIdEl) leadIdEl.value = '';
    return;
  }

  if (company) {
    var atAgency = anGetCompanyLeadMatches(company).length;
    if (atAgency) {
      panel.innerHTML = '<div style="font-size:11px;color:#6366f1;background:#f5f3ff;border:1px solid #ddd6fe;border-radius:8px;padding:8px 10px;">'
        + '👤 Start typing a name — ' + atAgency + ' contact' + (atAgency !== 1 ? 's' : '') + ' at this agency'
        + '</div>';
    }
  }
};

window.anRefreshAllDemoContactDuplicates = function(prefix) {
  prefix = prefix || 'adc';
  document.querySelectorAll('#' + prefix + '-contacts-list .' + prefix + '-contact-row').forEach(function(row) {
    anRefreshDemoContactDuplicateRow(prefix, row);
  });
  anRefreshDemoCompanyHint(prefix);
};

window.anRefreshDemoCompanyHint = function(prefix) {
  prefix = prefix || 'adc';
  var hint = document.getElementById(prefix + '-company-hint');
  var companyEl = document.getElementById(prefix + '-company');
  if (!hint || !companyEl) return;
  var company = companyEl.value.trim();
  if (!company) { hint.innerHTML = ''; return; }
  var matches = anGetCompanyLeadMatches(company);
  if (!matches.length) {
    hint.innerHTML = '<div style="font-size:11px;color:#10b981;margin-top:6px;">✓ New agency name in CRM</div>';
    return;
  }
  var names = matches.slice(0, 3).map(function(l) {
    return ((l.firstName || '') + ' ' + (l.lastName || '')).trim() || l.email || 'Contact';
  }).join(', ');
  hint.innerHTML = '<div style="font-size:11px;color:#6366f1;background:#f5f3ff;border:1px solid #ddd6fe;border-radius:8px;padding:8px 10px;margin-top:6px;">'
    + '🏢 <strong>' + matches.length + '</strong> existing contact' + (matches.length !== 1 ? 's' : '') + ' at this agency'
    + (names ? ' — e.g. ' + anEsc(names) + (matches.length > 3 ? '…' : '') : '')
    + '</div>';
};

window.anLinkDemoContactToLead = function(prefix, rowIdx, leadId) {
  anOnDemoContactLinkSelect(prefix, rowIdx, leadId);
};

window.anMarkDemoContactAsNew = function(prefix, rowIdx) {
  prefix = prefix || 'adc';
  var row = document.querySelector('#' + prefix + '-contacts-list .' + prefix + '-contact-row[data-idx="' + rowIdx + '"]');
  if (!row) return;
  var leadIdEl = row.querySelector('.' + prefix + '-c-lead-id');
  var linkModeEl = row.querySelector('.' + prefix + '-c-link-mode');
  var selectEl = row.querySelector('.' + prefix + '-link-select');
  if (leadIdEl) leadIdEl.value = '';
  if (linkModeEl) linkModeEl.value = 'new';
  if (selectEl) selectEl.value = '';
  anRefreshDemoContactDuplicateRow(prefix, row);
};

window.anValidateDemoContactsResolved = function(contacts, company) {
  var unresolved = [];
  (contacts || []).forEach(function(c) {
    if (c.linkMode === 'link' || c.linkMode === 'new') return;
    var matches = anFindDemoContactDuplicates(c, company);
    var companyLeads = typeof anGetCompanyLeadMatches === 'function' ? anGetCompanyLeadMatches(company) : [];
    if (matches.length > 0 || companyLeads.length > 0) unresolved.push(c.name || 'Contact');
  });
  return unresolved;
};

window.anBuildDemoContactRowHTML = function(prefix, idx, contact, opts) {
  prefix = prefix || 'dm';
  contact = contact || {};
  opts = opts || {};
  var canRemove = opts.canRemove !== false && idx > 0;
  var dupeHandler = 'oninput="anRefreshDemoContactDuplicateRow(\'' + prefix + '\', this)" onblur="anRefreshDemoContactDuplicateRow(\'' + prefix + '\', this)"';
  var nameHandler = 'oninput="anOnDemoContactNameInput(\'' + prefix + '\',' + idx + ', this)" onfocus="anOnDemoContactNameInput(\'' + prefix + '\',' + idx + ', this)"';
  var suggestBox = '<div class="' + prefix + '-name-suggest an-demo-contact-suggest" style="display:none;position:absolute;left:0;right:0;top:calc(100% + 4px);background:#fff;border:1.5px solid #e4e4e7;border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,0.12);max-height:220px;overflow-y:auto;z-index:10050;"></div>';
  return '<div class="'+prefix+'-contact-row" data-idx="'+idx+'" style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;padding:10px;background:#fafafa;border:1px solid #e4e4e7;border-radius:8px;">'
    + '<input type="hidden" class="'+prefix+'-c-lead-id" value="'+anEsc(contact.leadId||'')+'">'
    + '<input type="hidden" class="'+prefix+'-c-link-mode" value="'+anEsc(contact.linkMode||'auto')+'">'
    + '<div style="grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;">'
    + '<div style="font-size:10px;font-weight:700;color:#71717a;">'+(idx===0?'Primary contact *':'Contact '+(idx+1))+'</div>'
    +(canRemove ? '<button type="button" onclick="anRemoveDemoContactRow(this)" style="background:none;border:none;color:#a1a1aa;cursor:pointer;font-size:16px;line-height:1;">&#x2715;</button>' : '')
    + '</div>'
    + '<div style="grid-column:1/-1;" class="an-demo-contact-wrap"><label style="font-size:10px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">Full name *</label>'
    + '<div style="position:relative;">'
    + '<input class="'+prefix+'-c-name" type="text" value="'+anEsc(contact.name||'')+'" placeholder="Start typing name…" autocomplete="off" '+nameHandler+' style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:8px 10px;font-size:13px;font-family:inherit;outline:none;box-sizing:border-box;">'
    + suggestBox
    + '</div></div>'
    + '<div class="'+prefix+'-dupe-panel" style="grid-column:1/-1;margin-bottom:4px;"></div>'
    + '<div><input class="'+prefix+'-c-title" type="text" value="'+anEsc(contact.title||'')+'" placeholder="Title / role" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:8px 10px;font-size:12px;font-family:inherit;outline:none;box-sizing:border-box;"></div>'
    + '<div><input class="'+prefix+'-c-phone" type="tel" value="'+anEsc(contact.phone||'')+'" placeholder="Phone" '+dupeHandler+' style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:8px 10px;font-size:12px;font-family:inherit;outline:none;box-sizing:border-box;"></div>'
    + '<div style="grid-column:1/-1;"><input class="'+prefix+'-c-email" type="email" value="'+anEsc(contact.email||'')+'" placeholder="Email (optional)" '+dupeHandler+' style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:8px 10px;font-size:12px;font-family:inherit;outline:none;box-sizing:border-box;"></div>'
    + '</div>';
};

window.anBuildDemoContactsFieldsHTML = function(prefix, contacts, company) {
  prefix = prefix || 'dm';
  contacts = (contacts && contacts.length) ? contacts : [{ name: '', title: '', phone: '', email: '' }];
  company = company || '';
  var rows = contacts.map(function(c, i) {
    return anBuildDemoContactRowHTML(prefix, i, c, { canRemove: i > 0 });
  }).join('');
  return '<div id="'+prefix+'-contacts-panel" style="grid-column:1/-1;">'
    + '<div style="margin-bottom:10px;"><label style="font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Agency / Company *</label>'
    + '<div class="an-demo-company-wrap" style="position:relative;">'
    + '<input id="'+prefix+'-company" type="text" value="'+anEsc(company)+'" placeholder="Start typing agency name…" autocomplete="off" oninput="anOnDemoCompanyInput(\''+prefix+'\')" onfocus="anOnDemoCompanyInput(\''+prefix+'\')" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;box-sizing:border-box;">'
    + '<div id="'+prefix+'-company-suggest" class="an-demo-company-suggest" style="display:none;position:absolute;left:0;right:0;top:calc(100% + 4px);background:#fff;border:1.5px solid #e4e4e7;border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,0.12);max-height:220px;overflow-y:auto;z-index:10050;"></div>'
    + '</div>'
    + '<div id="'+prefix+'-company-hint"></div></div>'
    + '<div style="font-size:10px;font-weight:700;color:#6366f1;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:8px;">People on the demo</div>'
    + '<div id="'+prefix+'-contacts-list">'+rows+'</div>'
    + '<button type="button" onclick="anAddDemoContactRow(\''+prefix+'\')" style="margin-top:4px;background:#f5f3ff;color:#6366f1;border:1.5px dashed #c4b5fd;border-radius:8px;padding:8px 12px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;width:100%;">+ Add another contact</button>'
    + '</div>';
};

window.anAddDemoContactRow = function(prefix) {
  prefix = prefix || 'dm';
  var list = document.getElementById(prefix + '-contacts-list');
  if (!list) return;
  var idx = list.querySelectorAll('.' + prefix + '-contact-row').length;
  var wrap = document.createElement('div');
  wrap.innerHTML = anBuildDemoContactRowHTML(prefix, idx, {}, { canRemove: true });
  list.appendChild(wrap.firstChild);
  if (typeof anRefreshDemoContactDuplicateRow === 'function') {
    anRefreshDemoContactDuplicateRow(prefix, list.lastElementChild);
  }
};

window.anRemoveDemoContactRow = function(btn) {
  var row = btn && btn.closest ? btn.closest('[class$="-contact-row"]') : null;
  if (row) row.remove();
};

window.anToggleDemoContactsUI = function() {
  var st = document.getElementById('dm-st');
  var simple = document.getElementById('dm-simple-prospect');
  var multi = document.getElementById('dm-contacts-panel');
  if (!st || !simple || !multi) return;
  var isComplete = st.value === 'showed';
  simple.style.display = isComplete ? 'none' : '';
  multi.style.display = isComplete ? '' : 'none';
  if (isComplete) {
    var n = document.getElementById('dm-n');
    var firstName = document.querySelector('#dm-contacts-list .dm-c-name');
    if (n && n.value.trim() && firstName && !firstName.value.trim()) firstName.value = n.value.trim();
    if (typeof anRefreshAllDemoContactDuplicates === 'function') anRefreshAllDemoContactDuplicates('dm');
  }
};

window.anCollectDemoContactsFromForm = function(prefix) {
  prefix = prefix || 'dm';
  var companyEl = document.getElementById(prefix + '-company');
  var company = companyEl ? companyEl.value.trim() : '';
  var rows = document.querySelectorAll('#' + prefix + '-contacts-list .' + prefix + '-contact-row');
  var contacts = [];
  rows.forEach(function(row) {
    var nameEl = row.querySelector('.' + prefix + '-c-name');
    var name = nameEl ? nameEl.value.trim() : '';
    if (!name) return;
    var titleEl = row.querySelector('.' + prefix + '-c-title');
    var phoneEl = row.querySelector('.' + prefix + '-c-phone');
    var emailEl = row.querySelector('.' + prefix + '-c-email');
    var leadIdEl = row.querySelector('.' + prefix + '-c-lead-id');
    var linkModeEl = row.querySelector('.' + prefix + '-c-link-mode');
    contacts.push({
      name: name,
      title: titleEl ? titleEl.value.trim() : '',
      phone: phoneEl ? phoneEl.value.trim() : '',
      email: emailEl ? emailEl.value.trim() : '',
      leadId: leadIdEl ? leadIdEl.value.trim() : '',
      linkMode: linkModeEl ? linkModeEl.value.trim() || 'auto' : 'auto'
    });
  });
  return { company: company, contacts: contacts };
};

window.anDemoDisplayName = function(company, contacts, fallback) {
  var primary = (contacts && contacts[0]) ? contacts[0].name : (fallback || '');
  company = (company || '').trim();
  primary = (primary || '').trim();
  if (company && primary) return primary + ' @ ' + company;
  return company || primary || fallback || 'Demo';
};

window.anSaveDemoContactsToCRM = function(demo, sdrEmail, aeEmail) {
  if (!demo || typeof AN === 'undefined') return null;
  var contacts = demo.contacts || [];
  var company = (demo.company || '').trim();
  if (!contacts.length && demo.name) {
    contacts = [{ name: demo.name, title: '', phone: '', email: '' }];
  }
  if (!contacts.length) return null;

  var repEmail = (sdrEmail || AN.currentRepEmail || '').toLowerCase();
  aeEmail = (aeEmail || demo.aeEmail || '').toLowerCase();
  var created = [];
  var primary = null;

  contacts.forEach(function(c, i) {
    var name = (c.name || '').trim();
    if (!name) return;
    var parsed = anParsePersonName(name);
    var existing = null;

    if (c.leadId && c.linkMode !== 'new' && AN.leads) {
      existing = AN.leads.find(function(l) { return l.id === c.leadId; }) || null;
    }

    if (!existing && c.linkMode !== 'new' && typeof anFindDuplicateMatches === 'function') {
      var shape = anDemoContactToLeadShape(c, company);
      var matches = anFindDuplicateMatches(shape);
      if (matches.length === 1) existing = matches[0];
      else if (matches.length > 1 && c.leadId) {
        existing = AN.leads.find(function(l) { return l.id === c.leadId; }) || null;
      }
    }

    if (existing) {
      if (company && !(existing.company || '').trim()) existing.company = company;
      if (c.phone && !existing.phone) existing.phone = typeof anNormalizePhone === 'function' ? anNormalizePhone(c.phone) : c.phone;
      if (c.email && !existing.email) existing.email = c.email;
      if (c.title && !existing.title) existing.title = c.title;
      if (demo.state && !existing.state) existing.state = demo.state;
      if (demo.size && !existing.size) existing.size = demo.size;
      existing.sdrEmail = existing.sdrEmail || repEmail;
      existing.aeEmail = existing.aeEmail || aeEmail;
      if (demo.scheduledDate) existing.demoDate = existing.demoDate || demo.scheduledDate;
      existing.updated = new Date().toISOString();
      c.leadId = existing.id;
      created.push(existing);
      if (i === 0) primary = existing;
      return;
    }
    var leadCompany = company;
    if (!leadCompany && i === 0 && contacts.length === 1 && !parsed.lastName) leadCompany = name;
    var lead = {
      id: 'lead-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6) + '-' + i,
      firstName: parsed.firstName,
      lastName: parsed.lastName,
      company: leadCompany,
      title: c.title || '',
      phone: c.phone ? (typeof anNormalizePhone === 'function' ? anNormalizePhone(c.phone) : c.phone) : '',
      email: c.email || '',
      state: demo.state || '',
      size: demo.size || 'solo',
      status: i === 0 ? 'booked_demo' : 'new',
      _repEmail: repEmail,
      sdrEmail: repEmail,
      aeEmail: aeEmail,
      demoDate: demo.scheduledDate || '',
      source: 'manual_demo',
      callLog: [],
      notes: i === 0 ? (demo.notes || '') : ('Attended demo at ' + (company || 'agency') + (demo.notes ? ' — ' + demo.notes : '')),
      created: new Date().toISOString(),
      updated: new Date().toISOString()
    };
    if (!AN.leads) AN.leads = [];
    AN.leads.unshift(lead);
    created.push(lead);
    if (i === 0) primary = lead;
  });

  if (primary) {
    demo.leadId = primary.id;
    demo.contactLeadIds = created.map(function(l) { return l.id; });
    demo.company = company || primary.company || '';
    demo.contacts = contacts;
    demo.name = anDemoDisplayName(demo.company, contacts, demo.name);
    primary.relatedDemoContactIds = created.filter(function(l) { return l.id !== primary.id; }).map(function(l) { return l.id; });
  }
  return { primary: primary, all: created };
};

window.anBuildRepSelectOptions = function(selectedEmail, includeNone) {
  var reps = typeof anGetKnownRepEmails === 'function' ? anGetKnownRepEmails() : [];
  var myEmail = (typeof AN !== 'undefined' && AN.currentRepEmail) || '';
  var html = includeNone === false ? '' : '<option value="">— Select —</option>';
  return html + reps.map(function(em) {
    var label = typeof anGetRepName === 'function' ? anGetRepName(em) : em.split('@')[0];
    var sel = (selectedEmail || '').toLowerCase() === em.toLowerCase() ? ' selected' : '';
    return '<option value="'+anEsc(em)+'"'+sel+'>'+anEsc(label)+(em===myEmail?' (me)':'')+'</option>';
  }).join('');
};

window.anEnsureLeadForDemo = function(demo) {
  if (!demo || typeof AN === 'undefined') return null;
  var lead = typeof anFindLeadForDemo === 'function' ? anFindLeadForDemo(demo) : null;
  if (lead) {
    if (!demo.leadId) demo.leadId = lead.id;
    return lead;
  }
  if (demo.contacts && demo.contacts.length && typeof anSaveDemoContactsToCRM === 'function') {
    var batch = anSaveDemoContactsToCRM(demo, demo.sdrEmail, demo.aeEmail);
    return batch ? batch.primary : null;
  }
  var name = (demo.name || '').trim();
  if (!name) return null;
  var parts = name.split(/\s+/).filter(Boolean);
  var firstName = parts[0] || '';
  var lastName = parts.length > 1 ? parts.slice(1).join(' ') : '';
  var company = parts.length === 1 ? name : '';
  var repEmail = (demo.sdrEmail || (AN.currentRepEmail || '')).toLowerCase();
  lead = {
    id: 'lead-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
    firstName: firstName,
    lastName: lastName,
    company: company,
    state: demo.state || '',
    size: demo.size || 'solo',
    status: 'booked_demo',
    _repEmail: repEmail,
    sdrEmail: demo.sdrEmail || repEmail,
    aeEmail: demo.aeEmail || '',
    demoDate: demo.scheduledDate || '',
    created: new Date().toISOString(),
    updated: new Date().toISOString(),
    callLog: [],
    source: 'manual_demo'
  };
  if (!AN.leads) AN.leads = [];
  AN.leads.unshift(lead);
  demo.leadId = lead.id;
  if (typeof AN.save === 'function') AN.save();
  return lead;
};

window.anOpenDemoCompleteOwnersModal = function(demo, opts) {
  opts = opts || {};
  if (!demo) return;
  var existing = document.getElementById('an-demo-complete-modal');
  if (existing) existing.remove();

  var myEmail = (typeof AN !== 'undefined' && AN.currentRepEmail) || '';
  var defaultSdr = demo.sdrEmail || demo._repEmail || myEmail;
  var defaultAe = demo.aeEmail || '';
  var contacts = (demo.contacts && demo.contacts.length) ? demo.contacts.slice() : [{ name: demo.name || '', title: '', phone: '', email: '' }];
  var company = demo.company || '';
  if (!company && demo.name && demo.name.indexOf(' @ ') >= 0) {
    company = demo.name.split(' @ ').slice(1).join(' @ ').trim();
    if (!demo.contacts || !demo.contacts.length) contacts[0].name = demo.name.split(' @ ')[0].trim();
  }
  var contactsHTML = typeof anBuildDemoContactsFieldsHTML === 'function'
    ? anBuildDemoContactsFieldsHTML('adc', contacts, company) : '';

  var backdrop = document.createElement('div');
  backdrop.id = 'an-demo-complete-modal';
  backdrop.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:22000;display:flex;align-items:center;justify-content:center;padding:20px;';
  backdrop.onclick = function(e) { if (e.target === backdrop) backdrop.remove(); };
  backdrop.innerHTML = '<div style="background:#fff;border-radius:14px;padding:24px;width:520px;max-width:95vw;max-height:90vh;overflow-y:auto;box-shadow:0 24px 80px rgba(0,0,0,0.3);font-family:inherit;" onclick="event.stopPropagation()">'
    + '<div style="font-size:16px;font-weight:800;color:#09090b;margin-bottom:4px;">✅ Demo Completed</div>'
    + '<div style="font-size:12px;color:#71717a;margin-bottom:16px;">Add everyone from the demo, assign owners, and create the opportunity.</div>'
    + contactsHTML
    + '<div style="background:#f5f3ff;border:1.5px solid #ddd6fe;border-radius:10px;padding:14px;margin:14px 0;">'
    + '<div style="font-size:10px;font-weight:700;color:#6366f1;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:10px;">Who gets credit?</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'
    + '<div><label style="font-size:10px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">SDR Owner *</label>'
    + '<select id="adc-sdr" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px;font-size:13px;font-family:inherit;">'+anBuildRepSelectOptions(defaultSdr)+'</select></div>'
    + '<div><label style="font-size:10px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">AE Owner *</label>'
    + '<select id="adc-ae" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px;font-size:13px;font-family:inherit;">'+anBuildRepSelectOptions(defaultAe)+'</select></div>'
    + '</div></div>'
    + '<label style="font-size:10px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">Demo notes / pain points</label>'
    + '<textarea id="adc-notes" rows="3" placeholder="What came up on the demo? Next steps?" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:10px;font-size:12.5px;font-family:inherit;outline:none;resize:vertical;box-sizing:border-box;margin-bottom:16px;">'+anEsc(demo.notes||'')+'</textarea>'
    + '<div style="display:flex;gap:8px;">'
    + '<button type="button" onclick="document.getElementById(\'an-demo-complete-modal\').remove()" style="flex:1;padding:10px;border:1.5px solid #e4e4e7;border-radius:8px;background:#fff;color:#71717a;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Cancel</button>'
    + '<button type="button" onclick="anSubmitDemoCompleteOwners(\''+anEsc(demo.id)+'\','+(opts.createOpp?'true':'false')+')" style="flex:1;padding:10px;border:none;border-radius:8px;background:#10b981;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Create Opportunity →</button>'
    + '</div></div>';
  document.body.appendChild(backdrop);
  setTimeout(function() {
    if (typeof anRefreshAllDemoContactDuplicates === 'function') anRefreshAllDemoContactDuplicates('adc');
  }, 60);
};

window.anSubmitDemoCompleteOwners = function(demoId, createOpp) {
  var demo = (_dash.demos || []).find(function(d) { return d.id === demoId; });
  if (!demo) return;
  var sdrEl = document.getElementById('adc-sdr');
  var aeEl = document.getElementById('adc-ae');
  var notesEl = document.getElementById('adc-notes');
  var sdrEmail = (sdrEl ? sdrEl.value : '').trim().toLowerCase();
  var aeEmail = (aeEl ? aeEl.value : '').trim().toLowerCase();
  if (!sdrEmail || !aeEmail) {
    if (typeof showToast === 'function') showToast('Please select both SDR and AE owners');
    return;
  }
  var notes = notesEl ? notesEl.value.trim() : '';

  var collected = typeof anCollectDemoContactsFromForm === 'function' ? anCollectDemoContactsFromForm('adc') : { company: '', contacts: [] };
  if (!collected.contacts.length) {
    if (typeof showToast === 'function') showToast('Add at least one contact name');
    return;
  }
  if (!collected.company && collected.contacts.length === 1 && !collected.contacts[0].name.split(' ').slice(1).join(' ')) {
    collected.company = collected.contacts[0].name;
  }
  var unresolved = typeof anValidateDemoContactsResolved === 'function'
    ? anValidateDemoContactsResolved(collected.contacts, collected.company) : [];
  if (unresolved.length) {
    if (typeof showToast === 'function') showToast('Choose link or new contact for: ' + unresolved.join(', '));
    return;
  }

  var modal = document.getElementById('an-demo-complete-modal');
  if (modal) modal.remove();
  demo.company = collected.company;
  demo.contacts = collected.contacts;
  demo.name = typeof anDemoDisplayName === 'function' ? anDemoDisplayName(demo.company, demo.contacts, demo.name) : demo.name;

  var wasShowed = demo.status === 'showed';
  demo.status = 'showed';
  demo.completedDate = typeof anLocalDateStr === 'function' ? anLocalDateStr() : new Date().toISOString().split('T')[0];
  demo.sdrEmail = sdrEmail;
  demo.aeEmail = aeEmail;
  demo.sdrName = typeof anGetRepName === 'function' ? anGetRepName(sdrEmail) : '';
  demo.aeName = typeof anGetRepName === 'function' ? anGetRepName(aeEmail) : '';
  if (notes) demo.notes = notes;

  var batch = typeof anSaveDemoContactsToCRM === 'function' ? anSaveDemoContactsToCRM(demo, sdrEmail, aeEmail) : null;
  var lead = batch ? batch.primary : (typeof anEnsureLeadForDemo === 'function' ? anEnsureLeadForDemo(demo) : null);
  if (lead) {
    lead.sdrEmail = sdrEmail;
    lead._repEmail = lead._repEmail || sdrEmail;
    lead.aeEmail = aeEmail;
    if (typeof anAssignAE === 'function') anAssignAE(lead, aeEmail);
    if (notes) {
      lead.demoNotes = notes;
      if (!lead.callLog) lead.callLog = [];
      var now = new Date();
      lead.callLog.push({
        id: 'act-' + Date.now(),
        type: 'note',
        outcome: 'showed',
        date: typeof anLocalDateStr === 'function' ? anLocalDateStr() : now.toISOString().split('T')[0],
        time: String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0'),
        rep: (typeof AN !== 'undefined' && AN.currentRepEmail) || '',
        loggedAt: now.toISOString(),
        notes: notes,
        category: 'pain'
      });
    }
    lead.demoDate = demo.scheduledDate || lead.demoDate;
    lead.size = demo.size || lead.size;
    lead.state = demo.state || lead.state;
    lead.demoCompletedAt = lead.demoCompletedAt || new Date().toISOString();
    if (typeof anRecordDemoCompleted === 'function') anRecordDemoCompleted(lead, { source: 'manual_demo_complete' });
    if (typeof AN !== 'undefined' && AN.save) AN.save();
    if (createOpp && typeof anIsOpportunity === 'function' && !anIsOpportunity(lead)) {
      if (typeof anTriggerDemoCompleteConversion === 'function') {
        anTriggerDemoCompleteConversion(lead, { silent: false, save: false, source: 'manual_demo_complete' });
      } else if (typeof anPromoteLeadToOpportunity === 'function') {
        anPromoteLeadToOpportunity(lead, {
          stage: 'showed',
          sdrEmail: sdrEmail,
          aeEmail: aeEmail,
          notes: notes,
          size: demo.size,
          demoCompletedAt: true,
          skipRefresh: true,
          save: false
        });
        if (typeof anRecordDemoConverted === 'function') {
          anRecordDemoConverted(lead, { source: 'manual_demo_complete' });
        }
      }
    } else if (typeof AN !== 'undefined' && AN.save) {
      AN.save();
    }
    if (typeof renderOpportunities === 'function') renderOpportunities();
    if (typeof AN !== 'undefined' && AN.save) AN.save();
  }

  if (typeof dashSave === 'function') dashSave();
  if (demo._pipelineIdx != null && _dash.pipeline && _dash.pipeline[demo._pipelineIdx]) {
    var pipeDeal = _dash.pipeline[demo._pipelineIdx];
    pipeDeal.stage = 'Demo Completed';
    pipeDeal.leadId = demo.leadId || pipeDeal.leadId;
    pipeDeal.demoId = demo.id;
    pipeDeal.name = demo.name || pipeDeal.name;
    pipeDeal.company = demo.company || pipeDeal.company;
    pipeDeal.contacts = demo.contacts || pipeDeal.contacts;
    pipeDeal.contactLeadIds = demo.contactLeadIds || pipeDeal.contactLeadIds;
    pipeDeal.sdrEmail = demo.sdrEmail;
    pipeDeal.aeEmail = demo.aeEmail;
    pipeDeal.sdrName = demo.sdrName;
    pipeDeal.aeName = demo.aeName;
    pipeDeal.notes = demo.notes || pipeDeal.notes;
    pipeDeal.updated = new Date().toISOString();
  }
  if (typeof anPushTeamActivityCloud === 'function' && !wasShowed) {
    anPushTeamActivityCloud({ showed: 1 }, { repEmail: sdrEmail });
  }
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();
  if (typeof refreshActiveCharts === 'function') refreshActiveCharts();
  var w = document.getElementById('demo-list-wrap');
  if (w && typeof buildDemoListHTML === 'function') w.innerHTML = buildDemoListHTML();
  if (typeof showToast === 'function') {
    var nContacts = (demo.contactLeadIds || []).length || (demo.contacts || []).length || 1;
    showToast('Demo completed — ' + nContacts + ' contact' + (nContacts !== 1 ? 's' : '') + ' saved, opportunity ready');
  }
};

window.anOpenDemoShowedCapture = function(demo) {
  if (typeof anOpenDemoCompleteOwnersModal === 'function') {
    anOpenDemoCompleteOwnersModal(demo, { createOpp: true });
    return;
  }
  var existing = document.getElementById('an-demo-showed-modal');
  if (existing) existing.remove();
  var backdrop = document.createElement('div');
  backdrop.id = 'an-demo-showed-modal';
  backdrop.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:21500;display:flex;align-items:center;justify-content:center;';
  backdrop.onclick = function(e) { if (e.target === backdrop) backdrop.remove(); };
  backdrop.innerHTML = '<div style="background:#fff;border-radius:14px;padding:22px;width:420px;max-width:92vw;font-family:inherit;box-shadow:0 24px 80px rgba(0,0,0,0.3);" onclick="event.stopPropagation()">'
    + '<div style="font-size:15px;font-weight:800;color:#09090b;margin-bottom:4px;">✅ Demo Showed — what came up?</div>'
    + '<div style="font-size:12px;color:#71717a;margin-bottom:16px;">Capture pain points and needs for Field Insights and the deal record.</div>'
    + '<label style="font-size:11px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">Pain points, needs, or key takeaways</label>'
    + '<textarea id="an-ds-notes" rows="4" placeholder="e.g. struggling with OEP renewals, want to automate quoting, concerned about migration from EZLynx..." style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:10px;font-size:12.5px;font-family:inherit;outline:none;resize:vertical;box-sizing:border-box;margin-bottom:14px;"></textarea>'
    + '<div style="display:flex;gap:8px;">'
    + '<button type="button" onclick="document.getElementById(\'an-demo-showed-modal\').remove()" style="flex:1;padding:10px;border:1.5px solid #e4e4e7;border-radius:8px;background:#fff;color:#71717a;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Skip</button>'
    + '<button type="button" onclick="anSaveDemoShowedCapture(\''+anEsc(demo.id)+'\',\''+anEsc(demo.leadId||'')+'\')" style="flex:1;padding:10px;border:none;border-radius:8px;background:#10b981;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Save Notes</button>'
    + '</div></div>';
  document.body.appendChild(backdrop);
};

window.anSaveDemoShowedCapture = function(demoId, leadId) {
  var notes = (document.getElementById('an-ds-notes') ? document.getElementById('an-ds-notes').value : '').trim();
  var modal = document.getElementById('an-demo-showed-modal');
  if (modal) modal.remove();
  if (!notes) return;
  // Save onto the lead's callLog so it surfaces in Field Insights
  var lead = leadId && typeof AN !== 'undefined' && AN.leadById ? AN.leadById(leadId) : null;
  if (lead) {
    if (!lead.callLog) lead.callLog = [];
    var now = new Date();
    lead.callLog.push({
      id: 'act-' + Date.now(),
      type: 'note',
      outcome: 'showed',
      date: typeof anLocalDateStr === 'function' ? anLocalDateStr() : now.toISOString().split('T')[0],
      time: String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0'),
      rep: (typeof AN !== 'undefined' && AN.currentRepEmail) || '',
      loggedAt: now.toISOString(),
      notes: notes,
      category: 'pain'
    });
    lead.demoFollowUpNotes = notes;
    lead.updated = now.toISOString();
    if (typeof AN !== 'undefined' && AN.save) AN.save();
  }
  if (typeof showToast === 'function') showToast('Demo notes saved to Field Insights');
};
window.deleteDemo=window.delDemo=function(id){ if(!confirm('Remove this demo?')) return; _dash.demos=(_dash.demos||[]).filter(function(x){return x.id!==id;}); dashSave(); var w=document.getElementById('demo-list-wrap'); if(w) w.innerHTML=buildDemoListHTML(); if(typeof anRefreshCommissionTrackerUI==='function') anRefreshCommissionTrackerUI(); };
window.editDemo=function(id){ openAddDemo(id); };
window.updateDemoStatus=window.updDemoStatus;

// ── Show Rate HTML ────────────────────────────────────────────
var DASH_DOW_NAMES = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
var DASH_DOW_ORDER = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];

function dashDayOfWeek(dateStr){
  if(!dateStr) return null;
  var d = new Date(dateStr + 'T12:00:00');
  if(isNaN(d.getTime())) return null;
  return DASH_DOW_NAMES[d.getDay()];
}

function dashBuildDemoDayBuckets(demos, dateField){
  var buckets = {};
  DASH_DOW_ORDER.forEach(function(day){ buckets[day] = { booked:0, showed:0, noshow:0, pending:0, rescheduled:0 }; });
  (demos || []).forEach(function(demo){
    var day = dashDayOfWeek(demo[dateField] || (dateField === 'scheduledDate' ? demo.scheduledDate : demo.bookedDate));
    if(!day || !buckets[day]) return;
    buckets[day].booked++;
    if(demo.status === 'showed') buckets[day].showed++;
    else if(demo.status === 'noshow') buckets[day].noshow++;
    else if(demo.status === 'rescheduled') buckets[day].rescheduled++;
    else buckets[day].pending++;
  });
  return buckets;
}

function dashRenderDemoDayTable(buckets, title, subtitle){
  var rows = DASH_DOW_ORDER.map(function(day){
    var b = buckets[day] || { booked:0, showed:0, noshow:0, pending:0, rescheduled:0 };
    var decided = b.showed + b.noshow;
    var showRate = decided > 0 ? Math.round(b.showed / decided * 100) : null;
    var dropOff = decided > 0 ? Math.round(b.noshow / decided * 100) : null;
    var isFriday = day === 'Friday';
    var rowBg = isFriday && dropOff !== null && dropOff >= 40 ? 'rgba(239,68,68,0.06)' : 'transparent';
    return '<tr style="background:'+rowBg+';">'
      +'<td style="padding:8px 10px;font-size:12px;font-weight:'+(isFriday?'700':'600')+';color:#09090b;">'+day+(isFriday?' ⚠️':'')+'</td>'
      +'<td style="padding:8px 10px;font-size:12px;color:#71717a;text-align:center;">'+b.booked+'</td>'
      +'<td style="padding:8px 10px;font-size:12px;color:#10b981;text-align:center;font-weight:600;">'+b.showed+'</td>'
      +'<td style="padding:8px 10px;font-size:12px;color:#ef4444;text-align:center;font-weight:600;">'+b.noshow+'</td>'
      +'<td style="padding:8px 10px;font-size:12px;color:#6366f1;text-align:center;">'+b.pending+'</td>'
      +'<td style="padding:8px 10px;font-size:12px;text-align:center;font-weight:700;color:'+(showRate===null?'#a1a1aa':showRate>=70?'#10b981':showRate>=50?'#f59e0b':'#ef4444')+';">'+(showRate!==null?showRate+'%':'—')+'</td>'
      +'<td style="padding:8px 10px;font-size:12px;text-align:center;font-weight:700;color:'+(dropOff===null?'#a1a1aa':dropOff>=40?'#ef4444':dropOff>=25?'#f59e0b':'#71717a')+';">'+(dropOff!==null?dropOff+'%':'—')+'</td>'
      +'</tr>';
  }).join('');
  return '<div style="background:#fff;border:1px solid #e4e4e7;border-radius:12px;padding:18px;margin-bottom:16px;">'
    +'<div style="font-size:11px;font-weight:700;color:#6366f1;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;">'+title+'</div>'
    +'<div style="font-size:12px;color:#71717a;margin-bottom:12px;line-height:1.5;">'+subtitle+'</div>'
    +'<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;min-width:520px;">'
    +'<thead><tr style="border-bottom:2px solid #e4e4e7;">'
    +'<th style="padding:8px 10px;text-align:left;font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;">Day</th>'
    +'<th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;">Booked</th>'
    +'<th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;">Showed</th>'
    +'<th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;">No-Show</th>'
    +'<th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;">Pending</th>'
    +'<th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;">Show Rate</th>'
    +'<th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;">Drop-off</th>'
    +'</tr></thead><tbody>'+rows+'</tbody></table></div></div>';
}

function buildShowRateHTML() {
  var demos = dashGetScopedDemos('scheduledDate');
  var showed=demos.filter(function(d){return d.status==='showed';}).length;
  var noshow=demos.filter(function(d){return d.status==='noshow';}).length;
  var decided=showed+noshow, rate=decided>0?Math.round(showed/decided*100):0;
  var schedBuckets = dashBuildDemoDayBuckets(demos, 'scheduledDate');
  var bookedBuckets = dashBuildDemoDayBuckets(demos, 'bookedDate');
  var friSched = schedBuckets.Friday || { showed:0, noshow:0 };
  var friBooked = bookedBuckets.Friday || { showed:0, noshow:0 };
  var friSchedDecided = friSched.showed + friSched.noshow;
  var friBookedDecided = friBooked.showed + friBooked.noshow;
  var friSchedDrop = friSchedDecided > 0 ? Math.round(friSched.noshow / friSchedDecided * 100) : null;
  var friBookedDrop = friBookedDecided > 0 ? Math.round(friBooked.noshow / friBookedDecided * 100) : null;
  var fridayAlert = '';
  if((friSchedDrop !== null && friSchedDrop >= 35) || (friBookedDrop !== null && friBookedDrop >= 35)){
    fridayAlert = '<div style="background:linear-gradient(135deg,#fef2f2,#fff7ed);border:1.5px solid #fca5a5;border-radius:12px;padding:16px 18px;margin-bottom:16px;">'
      +'<div style="font-size:13px;font-weight:800;color:#b91c1c;margin-bottom:6px;">⚠️ Friday drop-off pattern detected</div>'
      +'<div style="font-size:12px;color:#7f1d1d;line-height:1.6;">'
      +(friSchedDrop !== null ? 'Demos <strong>scheduled on Friday</strong>: '+friSchedDrop+'% no-show ('+friSched.noshow+' of '+friSchedDecided+' decided). ' : '')
      +(friBookedDrop !== null ? 'Demos <strong>booked on Friday</strong>: '+friBookedDrop+'% no-show ('+friBooked.noshow+' of '+friBookedDecided+' decided). ' : '')
      +'Consider confirming Friday bookings with a reminder call or moving to Tue–Thu slots.'
      +'</div></div>';
  }
  var SIZES_D=typeof SIZES!=='undefined'?SIZES:[{id:'solo',label:'Solo Agent'},{id:'small',label:'Small Agency'},{id:'large',label:'Large Agency'}];
  var bySizeRows=SIZES_D.map(function(sz){
    var sd=demos.filter(function(d){return d.size===sz.id;}), dc=sd.filter(function(d){return d.status==='showed'||d.status==='noshow';});
    var sw=sd.filter(function(d){return d.status==='showed';}).length, r=dc.length>0?Math.round(sw/dc.length*100):null;
    var c={solo:'#6366f1',small:'#10b981',large:'#f59e0b'}[sz.id]||'#a1a1aa';
    return '<div style="margin-bottom:10px;"><div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span style="font-size:12px;font-weight:600;color:#09090b;">'+sz.label+'</span><span style="font-size:12px;color:#71717a;">'+(r!==null?r+'% ('+sw+'/'+dc.length+')':sd.length+' booked, no results yet')+'</span></div><div style="background:#f4f4f5;border-radius:20px;height:7px;"><div style="background:'+c+';height:7px;border-radius:20px;width:'+(r||0)+'%;"></div></div></div>';
  }).join('');
  return '<div>'
    +'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px;">'
    +buildStatTile('Total Booked', demos.length, '#6366f1')
    +buildStatTile('Showed', showed, '#10b981')
    +buildStatTile('No Shows', noshow, '#ef4444')
    +'<div style="background:linear-gradient(135deg,#0f0f17,#1e1b4b);border-radius:12px;padding:14px;text-align:center;"><div style="font-size:9px;font-weight:700;color:#a5b4fc;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:6px;">Show Rate</div><div style="font-size:40px;font-weight:800;color:#fff;line-height:1;">'+(decided>0?rate+'%':'—')+'</div>'+(decided>0?'<div style="font-size:11px;color:rgba(255,255,255,0.4);margin-top:4px;">'+showed+' of '+decided+' decided</div>':'')+'</div>'
    +'</div>'
    +(decided>0?'<div style="background:#fff;border:1px solid #e4e4e7;border-radius:12px;padding:18px;margin-bottom:16px;"><div style="display:flex;justify-content:space-between;margin-bottom:8px;"><span style="font-size:12px;font-weight:700;">Show Rate</span><span style="font-size:12px;font-weight:700;color:'+(rate>=70?'#10b981':rate>=50?'#f59e0b':'#ef4444')+';">'+rate+'%</span></div><div style="background:#f4f4f5;border-radius:20px;height:12px;overflow:hidden;margin-bottom:6px;"><div style="background:'+(rate>=70?'linear-gradient(90deg,#10b981,#06b6d4)':rate>=50?'linear-gradient(90deg,#f59e0b,#ef4444)':'#ef4444')+';height:12px;border-radius:20px;width:'+rate+'%;transition:width 0.5s;"></div></div><div style="display:flex;justify-content:space-between;font-size:11px;color:#a1a1aa;"><span>0%</span><span style="color:#f59e0b;">50%</span><span style="color:#10b981;">70%+ great</span><span>100%</span></div></div>':'')
    +fridayAlert
    +dashRenderDemoDayTable(schedBuckets, 'Drop-off by Scheduled Day', 'When the demo was set to happen — e.g. Friday demos that never showed.')
    +dashRenderDemoDayTable(bookedBuckets, 'Drop-off by Booking Day', 'When the demo was originally booked — e.g. booked on Friday but didn\'t make it.')
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px;"><div style="background:#fff;border:1px solid #e4e4e7;border-radius:12px;padding:18px;"><div style="font-size:11px;font-weight:700;color:#8b5cf6;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:12px;">Demo Outcomes</div><div style="position:relative;height:180px;"><canvas id="chart-showrate"></canvas></div></div>'
    +'<div style="background:#fff;border:1px solid #e4e4e7;border-radius:12px;padding:18px;"><div style="font-size:11px;font-weight:700;color:#f59e0b;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:12px;">Show Rate by Size</div>'+bySizeRows+'</div></div>'
    +'</div>';
}

// ── Demo modal (add/edit) ─────────────────────────────────────
window.anOnDemoProspectNameInput = function(el) {
  var q = el ? el.value.trim() : '';
  var list = document.getElementById('dm-prospect-suggest');
  var leadIdEl = document.getElementById('dm-lead-id');
  if (!list) return;
  if (q.length < 1) {
    list.style.display = 'none';
    list.innerHTML = '';
    if (leadIdEl) leadIdEl.value = '';
    return;
  }
  if (leadIdEl && leadIdEl.value) {
    var linked = typeof AN !== 'undefined' && AN.leads ? AN.leads.find(function(l) { return l.id === leadIdEl.value; }) : null;
    if (linked) {
      var linkedName = ((linked.firstName || '') + ' ' + (linked.lastName || '')).trim();
      var linkedDisplay = linkedName + (linked.company ? ' @ ' + linked.company : '');
      if (linkedDisplay.toLowerCase() === q.toLowerCase() || linkedName.toLowerCase() === q.toLowerCase()) {
        list.style.display = 'none';
        list.innerHTML = '';
        return;
      }
    }
    leadIdEl.value = '';
  }
  var suggestions = typeof anGetContactNameSuggestions === 'function' ? anGetContactNameSuggestions(q, '', 10) : [];
  var suggestStyle = 'display:block;width:100%;text-align:left;padding:9px 12px;border:none;background:transparent;font-size:13px;font-family:inherit;cursor:pointer;color:#09090b;';
  var html = suggestions.map(function(s) {
    var safeId = (s.id || '').replace(/'/g, "\\'");
    return '<button type="button" onmousedown="event.preventDefault();anSelectDemoProspectLead(\'' + safeId + '\')" style="' + suggestStyle + '" onmouseover="this.style.background=\'#f5f3ff\'" onmouseout="this.style.background=\'transparent\'">'
      + '<span style="font-weight:700;">' + anEsc(s.name) + '</span>'
      + '<span style="display:block;font-size:11px;color:#71717a;margin-top:2px;">' + anEsc(s.summary) + '</span>'
      + '</button>';
  }).join('');
  var safeQ = q.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  html += '<button type="button" onmousedown="event.preventDefault();anSelectDemoProspectLead(\'\',\'' + safeQ + '\')" style="' + suggestStyle + 'border-top:1px solid #f0f0f5;color:#6366f1;font-weight:700;" onmouseover="this.style.background=\'#f5f3ff\'" onmouseout="this.style.background=\'transparent\'">'
    + '➕ New prospect: <span style="font-weight:800;">' + anEsc(q) + '</span>'
    + '</button>';
  list.innerHTML = html;
  list.style.display = suggestions.length || q ? 'block' : 'none';
};

window.anSelectDemoProspectLead = function(leadId, typedName) {
  var list = document.getElementById('dm-prospect-suggest');
  if (list) { list.style.display = 'none'; list.innerHTML = ''; }
  var nameEl = document.getElementById('dm-n');
  var leadIdEl = document.getElementById('dm-lead-id');
  if (leadId && typeof AN !== 'undefined' && AN.leads) {
    var lead = AN.leads.find(function(l) { return l.id === leadId; });
    if (lead) {
      var fullName = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim();
      var display = fullName + (lead.company ? ' @ ' + lead.company : '');
      if (nameEl) nameEl.value = display || fullName;
      if (leadIdEl) leadIdEl.value = lead.id;
      var stateEl = document.getElementById('dm-s');
      var sizeEl = document.getElementById('dm-z');
      if (stateEl && lead.state) stateEl.value = lead.state;
      if (sizeEl && lead.size) sizeEl.value = lead.size;
      return;
    }
  }
  if (leadIdEl) leadIdEl.value = '';
  if (nameEl && typedName) nameEl.value = typedName;
};

window.openAddDemo=function(editId){
  var dmOpts = window._dmOpenOpts || {};
  window._dmOpenOpts = null;
  var ex=editId?(_dash.demos||[]).filter(function(d){return d.id===editId;})[0]:null;
  if (ex && dmOpts.sdrEmail && !ex.sdrEmail) ex = Object.assign({}, ex, { sdrEmail: dmOpts.sdrEmail });
  var old=document.getElementById('dm-modal'); if(old) old.remove();
  var STAGES=['booked','showed','noshow','rescheduled'], SLABELS={booked:'Booked',showed:'Demo Completed',noshow:'No Show',rescheduled:'Rescheduled'};
  var stateOpts='<option value="">State...</option>'+(typeof US_STATES!=='undefined'?US_STATES:[]).map(function(s){return '<option value="'+s+'"'+(ex&&ex.state===s?' selected':'')+'>'+s+'</option>';}).join('');
  var sizeOpts=(typeof SIZES!=='undefined'?SIZES:[]).map(function(s){return '<option value="'+s.id+'"'+(ex&&ex.size===s.id?' selected':'')+'>'+s.label+'</option>';}).join('');
  var statusOpts=STAGES.map(function(s){return '<option value="'+s+'"'+(ex?ex.status===s?' selected':'':s==='booked'?' selected':'')+'>'+SLABELS[s]+'</option>';}).join('');
  var isComplete = ex && ex.status === 'showed';
  var initContacts = (ex && ex.contacts && ex.contacts.length) ? ex.contacts.slice() : [{ name: (ex && ex.name) ? ex.name : '', title: '', phone: '', email: '' }];
  var initCompany = (ex && ex.company) ? ex.company : '';
  var defaultDate = (ex && ex.scheduledDate) ? ex.scheduledDate : (dmOpts.scheduledDate || (typeof anLocalDateStr==='function'?anLocalDateStr():new Date().toISOString().substring(0,10)));
  var presetSdr = (ex && ex.sdrEmail) || dmOpts.sdrEmail || '';
  var presetLeadId = (ex && ex.leadId) || '';
  if (!initCompany && ex && ex.name && ex.name.indexOf(' @ ') >= 0) {
    initCompany = ex.name.split(' @ ').slice(1).join(' @ ').trim();
    if (!ex.contacts || !ex.contacts.length) initContacts[0].name = ex.name.split(' @ ')[0].trim();
  }
  var contactsPanelHTML = typeof anBuildDemoContactsFieldsHTML === 'function'
    ? anBuildDemoContactsFieldsHTML('dm', initContacts, initCompany) : '';
  var ov=document.createElement('div'); ov.id='dm-modal'; ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;';
  ov.innerHTML='<div style="background:#fff;border-radius:14px;padding:24px;width:540px;max-width:95vw;max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,0.3);">'
    +'<input type="hidden" id="dm-lead-id" value="'+anEsc(presetLeadId)+'">'
    +'<input type="hidden" id="dm-sdr-email" value="'+anEsc(presetSdr)+'">'
    +'<input type="hidden" id="dm-booked-date-preset" value="'+anEsc(dmOpts.bookedDate || (ex && ex.bookedDate ? String(ex.bookedDate).slice(0,10) : ''))+'">'
    +'<input type="hidden" id="dm-from-commission" value="'+(dmOpts.fromCommission ? '1' : '')+'">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;"><div style="font-size:16px;font-weight:800;">'+(editId?'Edit Demo':'Log Demo')+'</div>'
    +'<button onclick="document.getElementById(\'dm-modal\').remove()" style="background:none;border:none;font-size:18px;cursor:pointer;color:#a1a1aa;">&#x2715;</button></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;">'
    +'<div id="dm-simple-prospect" style="grid-column:1/-1;'+(isComplete?'display:none;':'')+'"><label style="font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Prospect / Lead *</label>'
    +'<div style="position:relative;"><input id="dm-n" type="text" value="'+(ex?anEsc(ex.name):'')+'" placeholder="Search existing leads or type new name…" autocomplete="off" oninput="anOnDemoProspectNameInput(this)" onfocus="anOnDemoProspectNameInput(this)" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;box-sizing:border-box;">'
    +'<div id="dm-prospect-suggest" style="display:none;position:absolute;left:0;right:0;top:calc(100% + 4px);background:#fff;border:1.5px solid #e4e4e7;border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,0.12);max-height:220px;overflow-y:auto;z-index:10050;"></div></div>'
    +'<div style="font-size:10px;color:#a1a1aa;margin-top:4px;">Start typing to link an existing CRM lead, or enter a new prospect.</div></div>'
    +contactsPanelHTML
    +'<div><label style="font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">State</label><select id="dm-s" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;cursor:pointer;">'+stateOpts+'</select></div>'
    +'<div><label style="font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Size</label><select id="dm-z" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;cursor:pointer;">'+sizeOpts+'</select></div>'
    +'<div><label style="font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Scheduled Date</label><input id="dm-d" type="date" value="'+defaultDate+'" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;box-sizing:border-box;"></div>'
    +'<div><label style="font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Status</label><select id="dm-st" onchange="anToggleDemoContactsUI()" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;cursor:pointer;">'+statusOpts+'</select></div>'
    +'<div style="grid-column:1/-1;"><label style="font-size:10px;font-weight:700;color:#71717a;text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:5px;">Notes</label>'
    +'<textarea id="dm-nt" rows="2" placeholder="Pain points, outcome, next step..." style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;outline:none;resize:vertical;box-sizing:border-box;">'+(ex&&ex.notes?anEsc(ex.notes):'')+'</textarea></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;">'
    +'<button onclick="document.getElementById(\'dm-modal\').remove()" style="padding:9px 18px;border-radius:8px;border:1.5px solid #e4e4e7;background:#fff;font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;color:#71717a;">Cancel</button>'
    +'<button onclick="saveDemoEntry(\''+(editId||'')+'\')" style="padding:9px 18px;border-radius:8px;border:none;background:#6366f1;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">'+(editId?'Save Changes':'Log Demo')+'</button>'
    +'</div></div>';
  document.body.appendChild(ov);
  ov.onclick=function(e){if(e.target===ov) ov.remove();};
  var contactsPanel = document.getElementById('dm-contacts-panel');
  if (contactsPanel) contactsPanel.style.display = isComplete ? '' : 'none';
  setTimeout(function(){
    if (isComplete || (document.getElementById('dm-st') && document.getElementById('dm-st').value === 'showed')) {
      if (typeof anRefreshAllDemoContactDuplicates === 'function') anRefreshAllDemoContactDuplicates('dm');
      var co = document.getElementById('dm-company');
      if (co) co.focus();
    } else {
      var n=document.getElementById('dm-n');
      if(n) n.focus();
    }
  },50);
};

// ── Remove Demo Booked entries from pipeline (demos are not deals) ──
(function cleanDemosFromPipeline() {
  try {
    var stored = JSON.parse(localStorage.getItem('sales-dashboard') || '{}');
    if (stored.pipeline && Array.isArray(stored.pipeline)) {
      var before = stored.pipeline.length;
      stored.pipeline = stored.pipeline.filter(function(d) {
        return d.stage !== 'Demo Booked' && d.stage !== 'Demo Booked (from demo log)';
      });
      if (stored.pipeline.length < before) {
        localStorage.setItem('sales-dashboard', JSON.stringify(stored));
      }
    }
  } catch(e) {}
})();

window.saveDemoEntry=function(editId,addPipeline){
  var n=document.getElementById('dm-n'),s=document.getElementById('dm-s'),z=document.getElementById('dm-z'),d=document.getElementById('dm-d'),st=document.getElementById('dm-st'),nt=document.getElementById('dm-nt');
  var newStatus = st ? st.value : 'booked';
  var isCompleteForm = newStatus === 'showed';
  var collected = isCompleteForm && typeof anCollectDemoContactsFromForm === 'function'
    ? anCollectDemoContactsFromForm('dm') : { company: '', contacts: [] };
  if (isCompleteForm) {
    if (!collected.contacts.length) {
      if (typeof showToast === 'function') showToast('Add at least one contact');
      return;
    }
    if (!collected.company && collected.contacts.length === 1) collected.company = collected.contacts[0].name;
    var unresolved = typeof anValidateDemoContactsResolved === 'function'
      ? anValidateDemoContactsResolved(collected.contacts, collected.company) : [];
    if (unresolved.length) {
      if (typeof showToast === 'function') showToast('Choose link or new contact for: ' + unresolved.join(', '));
      return;
    }
  } else if (!n || !n.value.trim()) {
    if (n) { n.style.borderColor = '#ef4444'; n.focus(); }
    return;
  }
  if(!_dash.demos) _dash.demos=[];
  var prevDemo = editId ? (_dash.demos || []).filter(function(x){ return x.id === editId; })[0] : null;
  var prevStatus = prevDemo ? prevDemo.status : '';
  var myEmail = (typeof AN !== 'undefined' && AN.currentRepEmail) ? AN.currentRepEmail.toLowerCase() : '';
  var presetSdrEl = document.getElementById('dm-sdr-email');
  var presetBookedEl = document.getElementById('dm-booked-date-preset');
  var leadIdPresetEl = document.getElementById('dm-lead-id');
  var fromCommissionEl = document.getElementById('dm-from-commission');
  var assignedSdr = presetSdrEl && presetSdrEl.value ? presetSdrEl.value.toLowerCase() : '';
  if (!assignedSdr && window._dmPendingSdrRefresh) assignedSdr = String(window._dmPendingSdrRefresh).toLowerCase();
  if (!assignedSdr) assignedSdr = myEmail;
  var bookedPreset = presetBookedEl && presetBookedEl.value ? presetBookedEl.value : '';
  var linkedLeadId = leadIdPresetEl ? leadIdPresetEl.value.trim() : '';
  var fromCommission = fromCommissionEl && fromCommissionEl.value === '1';
  var displayName = isCompleteForm
    ? (typeof anDemoDisplayName === 'function' ? anDemoDisplayName(collected.company, collected.contacts, '') : collected.contacts[0].name)
    : n.value.trim();
  var demo={
    name: displayName,
    company: isCompleteForm ? collected.company : (prevDemo && prevDemo.company) || '',
    contacts: isCompleteForm ? collected.contacts : (prevDemo && prevDemo.contacts) || [],
    state:s?s.value:'',
    size:z?z.value:'',
    scheduledDate:d?d.value:'',
    status:newStatus,
    notes:nt?nt.value.trim():'',
    id:editId||('demo-'+Date.now()),
    bookedDate: prevDemo && prevDemo.bookedDate ? prevDemo.bookedDate : (bookedPreset || (typeof anLocalDateStr==='function'?anLocalDateStr():new Date().toISOString().split('T')[0])),
    sdrEmail: (prevDemo && prevDemo.sdrEmail) || assignedSdr,
    aeEmail: (prevDemo && prevDemo.aeEmail) || '',
    leadId: linkedLeadId || (prevDemo && prevDemo.leadId) || null
  };
  if (prevDemo) {
    demo.leadId = demo.leadId || prevDemo.leadId;
    demo.completedDate = prevDemo.completedDate;
    demo.sdrName = prevDemo.sdrName;
    demo.aeName = prevDemo.aeName;
  }

  var openingComplete = newStatus === 'showed' && prevStatus !== 'showed';
  if (openingComplete) {
    demo.status = prevStatus || 'booked';
    if (editId) {
      var idx = -1;
      _dash.demos.forEach(function(x,i){ if(x.id===editId) idx=i; });
      if (idx >= 0) _dash.demos[idx] = Object.assign({}, _dash.demos[idx], demo);
    } else {
      _dash.demos.push(demo);
    }
    dashSave();
    var m=document.getElementById('dm-modal'); if(m) m.remove();
    if (typeof anOpenDemoCompleteOwnersModal === 'function') {
      var saved = (_dash.demos || []).filter(function(x){ return x.id === demo.id; })[0] || demo;
      anOpenDemoCompleteOwnersModal(saved, { createOpp: true });
    }
    if (typeof anRefreshSdrCommissionAfterDemo === 'function') {
      anRefreshSdrCommissionAfterDemo(assignedSdr || window._dmPendingSdrRefresh);
    }
    window._dmPendingSdrRefresh = null;
    return;
  }

  if(editId){
    var idx2=-1;
    _dash.demos.forEach(function(x,i){if(x.id===editId) idx2=i;});
    if(idx2>=0){demo.id=editId;demo.bookedDate=_dash.demos[idx2].bookedDate||demo.bookedDate;_dash.demos[idx2]=demo;}
  } else {
    _dash.demos.push(demo);
  }
  dashSave();
  var m2=document.getElementById('dm-modal');if(m2) m2.remove();
  if (!fromCommission) {
    if (typeof switchChartPane === 'function') switchChartPane('demos');
  }
  if(typeof dashRefreshTopStatTiles==='function') dashRefreshTopStatTiles();
  var w=document.getElementById('demo-list-wrap');
  if(w&&typeof buildDemoListHTML==='function') w.innerHTML=buildDemoListHTML();

  var savedDemo = (_dash.demos || []).filter(function(x) { return x.id === demo.id; })[0] || demo;
  if (typeof anSyncDemoToOpportunity === 'function') {
    anSyncDemoToOpportunity(savedDemo);
    if (typeof AN !== 'undefined' && AN.save) AN.save();
    dashSave();
  }
  if (typeof renderOpportunities === 'function') renderOpportunities();
  if (typeof renderLeadsTable === 'function') renderLeadsTable();

  if(typeof showToast==='function') showToast(editId?'Demo updated!':'Demo logged!');
  if (fromCommission || assignedSdr || window._dmPendingSdrRefresh || document.querySelector('[id^="sdr-monthly-tracker-"]')) {
    if (typeof anRefreshSdrCommissionAfterDemo === 'function') {
      anRefreshSdrCommissionAfterDemo(assignedSdr || window._dmPendingSdrRefresh);
    } else if (typeof anRefreshCommissionTrackerUI === 'function') {
      anRefreshCommissionTrackerUI();
    }
  }
  window._dmPendingSdrRefresh = null;
};

// ── Reset activity ────────────────────────────────────────────
window.dashResetActivity=function(){
  if(!confirm('Reset today\'s activity counters?')) return;
  _dash.activity={calls:0,demos:0,closes:0};
  var today = typeof anLocalDateStr === 'function' ? anLocalDateStr() : new Date().toISOString().split('T')[0];
  if(_dash.activityLog){var e=_dash.activityLog.filter(function(x){return x.date===today;})[0];if(e){e.calls=0;e.demos=0;e.closes=0;}}
  dashSave();
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();
  if (typeof refreshActiveCharts === 'function') refreshActiveCharts();
  if (typeof fastSetGoalPeriod === 'function') fastSetGoalPeriod(_goalPeriod || 'today');
};

