  { id:'small', label:'Small Agency', agents:'4-9 agents', price:'$247/mo', color:'#10b981', desc:'Small team, values white-label' },
  { id:'large', label:'Large Agency', agents:'10+ agents', price:'$597/mo', color:'#f59e0b', desc:'Enterprise mindset' }
