var STATE_INTEL_DASH = {
  'Florida':    { market:'Largest ACA market — 3.5M+ enrollees. FFM state. OEP chaos is massive.', pitch:'Renewal Autopilot was built for markets exactly like Florida.' },
  'Texas':      { market:'No state exchange — uses FFM. Large uninsured population. Strong STM market.', pitch:'Texas brokers juggle ACA and STM. AgentNav quotes both side by side.' },
  'California': { market:'Covered California — state-based exchange. Strong broker comp.', pitch:'HealthSherpa integrates directly with Covered California.' },
  'Georgia':    { market:'FFM state. Growing market. High agent competition.', pitch:'Agents who automate renewals keep more clients than agents who call manually.' },
  'default':    { market:'Active ACA market. Standard broker commission structure.', pitch:'Renewal Autopilot and ACA quoting are the core value props.' }
};

function getStateIntel(state) { return STATE_INTEL_DASH[state] || STATE_INTEL_DASH['default']; }

function getSizeLabel(sizeId) {
  var s = (SIZES_DASH).filter(function(x){ return x.id === sizeId; })[0];
  return s ? s.label : sizeId || '';
}

function buildIntelHTML(state, sizeId) {
  var intel = getStateIntel(state);
  var size  = SIZES_DASH.filter(function(x){ return x.id === sizeId; })[0];
  var html  = '<div style="display:grid;grid-template-columns:1fr 1fr'+(size?' 1fr':'')+';gap:10px;margin-top:4px;">';
  html += '<div style="background:rgba(255,255,255,0.05);border-radius:8px;padding:10px 12px;"><div style="font-size:9px;font-weight:700;color:#818cf8;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;">'+state+' Market</div><div style="font-size:11px;color:rgba(255,255,255,0.65);line-height:1.55;">'+intel.market+'</div></div>';
  html += '<div style="background:rgba(16,185,129,0.1);border-radius:8px;padding:10px 12px;"><div style="font-size:9px;font-weight:700;color:#10b981;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;">Pitch Angle</div><div style="font-size:11px;color:rgba(255,255,255,0.65);line-height:1.55;">'+intel.pitch+'</div></div>';
  if (size) html += '<div style="background:rgba(255,255,255,0.05);border:1px solid '+size.color+'33;border-radius:8px;padding:10px 12px;"><div style="font-size:9px;font-weight:700;color:'+size.color+';text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;">'+size.label+'</div><div style="font-size:13px;font-weight:800;color:#fff;margin-bottom:2px;">'+size.price+'</div><div style="font-size:11px;color:rgba(255,255,255,0.5);">'+size.desc+'</div></div>';
  return html + '</div>';
}

function buildDashAISuggestions() {
  var state = _dash.prospect && _dash.prospect.state;
  var sizeId = _dash.prospect && _dash.prospect.size;
  var suggs = state && sizeId ? [
    'Best opening line for a '+getSizeLabel(sizeId)+' in '+state+'?',
    'What pain points should I focus on for '+state+'?',
    'How do I handle price objections for a '+getSizeLabel(sizeId)+'?',
    'What competitors are common in '+state+' and how do I beat them?'
  ] : [
    'What is the best cold call opener for a solo agent?',
    'How do I handle "I am happy with my current setup"?',
    'What is the strongest close for a small agency?',
    'How do I position against EZLynx?'
  ];
  return '<div style="display:flex;flex-wrap:wrap;gap:6px;">'
    + suggs.map(function(s){
        return '<button onclick="dashQuickAsk(\''+s.replace(/'/g,"\\'")+'\')" style="background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.1);border-radius:7px;padding:6px 10px;font-size:11.5px;color:rgba(255,255,255,0.65);cursor:pointer;font-family:inherit;">'+s+'</button>';
      }).join('')
    + '</div>';
}

function buildProspectCard() {
  var card = document.createElement('div');
  card.style.cssText = 'background:#0f0f17;border:1px solid rgba(99,102,241,0.25);border-radius:14px;padding:20px 24px;margin-bottom:20px;';
  var stateOpts = '<option value="">Select state...</option>'
    + (typeof US_STATES !== 'undefined' ? US_STATES : US_STATES_DASH).map(function(s){
        return '<option value="'+s+'"'+(_dash.prospect&&_dash.prospect.state===s?' selected':'')+'>'+s+'</option>';
      }).join('');
  var sizeOpts = '<option value="">Select size...</option>'
    + SIZES_DASH.map(function(s){
        return '<option value="'+s.id+'"'+(_dash.prospect&&_dash.prospect.size===s.id?' selected':'')+'>'+s.label+' ('+s.agents+' \u00b7 '+s.price+')</option>';
      }).join('');
  var hasCtx = _dash.prospect && _dash.prospect.state && _dash.prospect.size;
  var intelHTML = hasCtx ? '<div id="dash-intel-panel" style="margin-top:14px;">'+buildIntelHTML(_dash.prospect.state, _dash.prospect.size)+'</div>' : '<div id="dash-intel-panel" style="display:none;margin-top:14px;"></div>';
  card.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">'
    +'<div><div style="font-size:10px;font-weight:700;color:#6366f1;letter-spacing:0.14em;text-transform:uppercase;margin-bottom:3px;">Current Prospect</div>'
    +'<div style="font-size:12px;color:rgba(255,255,255,0.4);">Set state + size — AI and scripts adapt instantly</div></div>'
    +'<div style="font-size:11px;color:rgba(255,255,255,0.3);">'+(hasCtx?'🎯 Context active':'No context set')+'</div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 2fr auto;gap:12px;align-items:end;">'
    +'<div><label style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:6px;">State</label>'
    +'<select id="dash-state-select" style="width:100%;background:#1a1a2e;border:1.5px solid rgba(99,102,241,0.3);border-radius:8px;padding:9px 10px;font-size:13px;font-weight:600;color:#fff;font-family:inherit;outline:none;cursor:pointer;">'+stateOpts+'</select></div>'
    +'<div><label style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:6px;">Agency Size</label>'
    +'<select id="dash-size-select" style="width:100%;background:#1a1a2e;border:1.5px solid rgba(99,102,241,0.3);border-radius:8px;padding:9px 10px;font-size:13px;font-weight:600;color:#fff;font-family:inherit;outline:none;cursor:pointer;">'+sizeOpts+'</select></div>'
    +'<div><label style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:6px;">Prospect Name / Notes</label>'
    +'<input id="dash-prospect-name" type="text" placeholder="e.g. John Smith — mentioned EZLynx pain" value="'+(_dash.prospect&&_dash.prospect.name?_dash.prospect.name:'')+'" style="width:100%;background:#1a1a2e;border:1.5px solid rgba(99,102,241,0.3);border-radius:8px;padding:9px 10px;font-size:13px;color:#fff;font-family:inherit;outline:none;box-sizing:border-box;"></div>'
    +'<div><button onclick="dashApplyContext()" style="background:#6366f1;color:#fff;border:none;border-radius:8px;padding:10px 18px;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap;">Set Context</button></div>'
    +'</div>'
    + intelHTML;
  return card;
}

window.dashApplyContext = function() {
  var state = document.getElementById('dash-state-select');
  var size  = document.getElementById('dash-size-select');
  var name  = document.getElementById('dash-prospect-name');
  if (!_dash.prospect) _dash.prospect = {};
  _dash.prospect.state = state ? state.value : '';
  _dash.prospect.size  = size  ? size.value  : '';
  _dash.prospect.name  = name  ? name.value  : '';
  dashSave();
  var intel = document.getElementById('dash-intel-panel');
  if (intel && _dash.prospect.state) { intel.style.display = ''; intel.innerHTML = buildIntelHTML(_dash.prospect.state, _dash.prospect.size); }
  if (typeof showToast === 'function') showToast('Context set: '+(_dash.prospect.state||'')+' / '+getSizeLabel(_dash.prospect.size||''));
};

function buildPipelineCard() {
  var card = document.createElement('div');
  card.style.cssText = 'background:#fff;border:1px solid #e4e4e7;border-radius:12px;overflow:hidden;';
  card.innerHTML = '<div style="padding:14px 18px;border-bottom:1px solid #e4e4e7;background:#f8f8fa;display:flex;align-items:center;justify-content:space-between;">'
    +'<div><div style="font-size:10px;font-weight:700;color:#10b981;text-transform:uppercase;letter-spacing:0.12em;">My Pipeline</div>'
    +'<div style="font-size:11px;color:#71717a;margin-top:1px;">Deals by state and size</div></div>'
    +'<button onclick="dashAddDeal()" style="background:#6366f1;color:#fff;border:none;border-radius:6px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">+ Add Deal</button>'
    +'</div>'
    +'<div id="dash-pipeline-list" style="padding:12px 18px;max-height:280px;overflow-y:auto;">'
    + buildPipelineHTML()
    +'</div>';
  return card;
}

function buildPipelineHTML() {
  var p = _dash.pipeline || [];
  if (!p.length) return '<div style="text-align:center;padding:20px;color:#a1a1aa;font-size:12px;">No deals yet. Click + Add Deal.</div>';
  var SC = {'Closed Won':'#10b981','Closed Lost':'#ef4444','Demo Booked':'#6366f1','Demo Completed':'#8b5cf6','Demo Done':'#8b5cf6','Proposal Sent':'#f59e0b','Prospecting':'#a1a1aa'};
  return '<div style="display:flex;flex-direction:column;gap:6px;">' + p.map(function(deal,i){
    var sz = SIZES_DASH.filter(function(x){return x.id===deal.size;})[0]||{label:deal.size||'',price:''};
    var stageLabel = typeof anDisplayPipelineStage === 'function' ? anDisplayPipelineStage(deal.stage) : deal.stage;
    var sc = SC[deal.stage] || SC[stageLabel] || '#a1a1aa';
    var clickAttr = deal.leadId
      ? ' onclick="anOpenTrackerDealRef(\'opp\',\''+String(deal.leadId).replace(/'/g, "\\'")+'\')"'
      : '';
    return '<div'+clickAttr+' style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid #f4f4f5;'+(deal.leadId?'cursor:pointer;':'')+'">'
      +'<div style="flex:1;min-width:0;">'
      +'<div style="font-size:12px;font-weight:600;color:#09090b;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+deal.name+'</div>'
      +'<div style="font-size:10px;color:#71717a;margin-top:1px;">'+(deal.state||'—')+' · '+sz.label+' · '+sz.price
      +(deal.sdrName||deal.aeEmail ? ' · ' : '')
      +(deal.sdrName ? '<span style="color:#15803d">SDR: '+anEsc(deal.sdrName.split(' ')[0])+'</span>' : '')
      +((deal.sdrName||deal.sdrEmail) && (deal.aeName||deal.aeEmail) ? ' · ' : '')
      +(deal.aeName ? '<span style="color:#4f46e5">AE: '+anEsc(deal.aeName.split(' ')[0])+'</span>' : '')
      +'</div>'
      +(deal.notes?'<div style="font-size:10px;color:#a1a1aa;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+deal.notes+'</div>':'')
      +'</div>'
      +'<span style="font-size:10px;font-weight:700;color:'+sc+';background:'+sc+'18;padding:2px 8px;border-radius:10px;white-space:nowrap;">'+stageLabel+'</span>'
      +'<button onclick="event.stopPropagation();dashAddDeal('+i+')" style="background:none;border:1px solid #e4e4e7;color:#6366f1;border-radius:5px;padding:2px 7px;font-size:10px;font-weight:600;cursor:pointer;font-family:inherit;flex-shrink:0;">Edit</button>'
      +'<button onclick="event.stopPropagation();dashDemoteDealToLead('+i+')" style="background:none;border:1px solid #fde68a;color:#b45309;border-radius:5px;padding:2px 7px;font-size:10px;font-weight:600;cursor:pointer;font-family:inherit;flex-shrink:0;">To Lead</button>'
      +'<button onclick="event.stopPropagation();dashDeleteDeal('+i+')" style="background:none;border:none;color:#d4d4d8;cursor:pointer;font-size:11px;padding:2px 4px;flex-shrink:0;" title="Remove deal">&#x2715;</button>'
      +'</div>';
  }).join('') + '</div>';
}

function buildByStateHTML() {
  var byState = {};
  (_dash.pipeline||[]).forEach(function(d){ var s=d.state||'Unknown'; byState[s]=(byState[s]||0)+1; });
  var entries = Object.keys(byState).sort(function(a,b){return byState[b]-byState[a];});
  if (!entries.length) return '<div style="color:#a1a1aa;font-size:12px;">No pipeline data yet.</div>';
  var max = byState[entries[0]];
  return entries.map(function(st){
    var n=byState[st], pct=Math.round(n/max*100);
    return '<div style="margin-bottom:10px;"><div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span style="font-size:12px;font-weight:600;color:#09090b;">'+st+'</span><span style="font-size:12px;color:#71717a;">'+n+' deal'+(n!==1?'s':'')+'</span></div><div style="background:#f4f4f5;border-radius:20px;height:6px;"><div style="background:#8b5cf6;height:6px;border-radius:20px;width:'+pct+'%;"></div></div></div>';
  }).join('');
}

function buildBySizeHTML() {
  var total = (_dash.pipeline||[]).length || 1;
  return SIZES_DASH.map(function(s){
    var n = (_dash.pipeline||[]).filter(function(d){return d.size===s.id;}).length;
    var won = (_dash.pipeline||[]).filter(function(d){return d.size===s.id&&d.stage==='Closed Won';}).length;
    var pct = Math.round(n/total*100);
    return '<div style="margin-bottom:12px;"><div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span style="font-size:12px;font-weight:600;color:#09090b;">'+s.label+'</span><span style="font-size:12px;color:#71717a;">'+n+(won?' \u00b7 <span style="color:#10b981;">'+won+' won</span>':'')+'</span></div><div style="background:#f4f4f5;border-radius:20px;height:6px;"><div style="background:'+s.color+';height:6px;border-radius:20px;width:'+pct+'%;"></div></div></div>';
  }).join('');
}

function buildByStateCardEl() {
  var card = document.createElement('div');
  card.style.cssText = 'background:#fff;border:1px solid #e4e4e7;border-radius:12px;overflow:hidden;';
  card.innerHTML = '<div style="padding:14px 18px;border-bottom:1px solid #e4e4e7;background:#f8f8fa;"><div style="font-size:10px;font-weight:700;color:#8b5cf6;text-transform:uppercase;letter-spacing:0.12em;">Pipeline by State</div></div><div style="padding:14px 18px;">'+buildByStateHTML()+'</div>';
  return card;
}

function buildBySizeCardEl() {
  var card = document.createElement('div');
  card.style.cssText = 'background:#fff;border:1px solid #e4e4e7;border-radius:12px;overflow:hidden;';
  card.innerHTML = '<div style="padding:14px 18px;border-bottom:1px solid #e4e4e7;background:#f8f8fa;"><div style="font-size:10px;font-weight:700;color:#f59e0b;text-transform:uppercase;letter-spacing:0.12em;">Pipeline by Size</div></div><div style="padding:14px 18px;">'+buildBySizeHTML()+'</div>';
  return card;
}

function buildAICard() {
  var card = document.createElement('div');
  card.style.cssText = 'background:#0f0f17;border:1px solid rgba(99,102,241,0.2);border-radius:14px;overflow:hidden;';
  var hasCtx = _dash.prospect && _dash.prospect.state && _dash.prospect.size;
  card.innerHTML = '<div style="padding:14px 20px;border-bottom:1px solid rgba(255,255,255,0.07);display:flex;align-items:center;justify-content:space-between;">'
    +'<div style="display:flex;align-items:center;gap:8px;"><span style="font-size:18px;">🧠</span>'
    +'<div><div style="font-size:13px;font-weight:700;color:#fff;">AI Sales Coach</div>'
    +'<div id="dash-ai-ctx" style="font-size:11px;color:rgba(255,255,255,0.4);">'+(hasCtx?'Context: '+_dash.prospect.state+' \u00b7 '+getSizeLabel(_dash.prospect.size):'Set state + size above for context-aware coaching')+'</div></div></div>'
    +'<button onclick="dashClearAI()" style="font-size:10px;color:rgba(255,255,255,0.3);background:none;border:none;cursor:pointer;font-family:inherit;">Clear</button>'
    +'</div>'
    +'<div id="dash-ai-msgs" style="min-height:80px;max-height:280px;overflow-y:auto;padding:14px 18px;display:flex;flex-direction:column;gap:8px;">'+buildDashAISuggestions()+'</div>'
    +'<div style="display:flex;gap:8px;padding:10px 18px;border-top:1px solid rgba(255,255,255,0.07);">'
    +'<input id="dash-ai-input" type="text" placeholder="Ask anything about your prospect, state market, or how to position..." '
    +'style="flex:1;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.12);border-radius:7px;padding:9px 12px;font-size:12px;color:#fff;font-family:inherit;outline:none;" '
    +'onkeydown="if(event.key===\'Enter\'){dashAskAI();}">'
    +'<button onclick="dashAskAI()" style="background:#6366f1;color:#fff;border:none;border-radius:7px;padding:9px 16px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">Ask</button>'
    +'</div>';
  return card;
}

window.dashClearAI = function() {
  var msgs = document.getElementById('dash-ai-msgs');
  if (msgs) msgs.innerHTML = buildDashAISuggestions();
};

window.dashQuickAsk = function(q) {
  var inp = document.getElementById('dash-ai-input');
  if (inp) inp.value = q;
  dashAskAI();
};

window.dashAskAI = function() {
  var inp  = document.getElementById('dash-ai-input');
  var msgs = document.getElementById('dash-ai-msgs');
  if (!inp || !msgs) return;
  var q = inp.value.trim();
  if (!q) return;
  inp.value = '';
  var intel = (_dash.prospect && _dash.prospect.state) ? getStateIntel(_dash.prospect.state) : null;
  var size  = (_dash.prospect && _dash.prospect.size) ? SIZES_DASH.filter(function(x){return x.id===_dash.prospect.size;})[0] : null;
  var system = 'You are an elite AgentNav sales coach. AgentNav: health insurance broker platform, ACA/STM/Life quoting, HealthSherpa+EDE, CRM, SMS, Renewal Autopilot. Pricing: Solo $79/mo, Small $247/mo, Large $597/mo. '
    +(_dash.prospect&&_dash.prospect.state?'Prospect state: '+_dash.prospect.state+'. Market: '+(intel?intel.market:'')+'  ':'')
    +(size?'Prospect size: '+size.label+' ('+size.price+'). ':'')
    +(_dash.prospect&&_dash.prospect.name?'Prospect: '+_dash.prospect.name+'. ':'')
    +'Be specific. Give word-for-word lines.';
  var uB = document.createElement('div');
  uB.style.cssText = 'background:rgba(99,102,241,0.2);border-radius:8px;padding:8px 11px;font-size:12px;color:#c7d2fe;text-align:right;margin-left:20%;';
  uB.textContent = q; msgs.appendChild(uB);
  var tid = 'dat-'+Date.now();
  var tB = document.createElement('div');
  tB.id = tid; tB.style.cssText = 'background:rgba(255,255,255,0.06);border-radius:8px;padding:8px 11px;font-size:12px;color:rgba(255,255,255,0.5);margin-right:8px;';
  tB.textContent = 'Thinking...'; msgs.appendChild(tB); msgs.scrollTop = msgs.scrollHeight;
  fetch('/.netlify/functions/coach', { method:'POST', headers:{'Content-Type':'application/json','Authorization':'Bearer '+(window._anAuthToken||'')},
    body: JSON.stringify({ model:'claude-sonnet-4-6', max_tokens:800, system:system, messages:[{role:'user',content:q}] })
  }).then(function(r){return r.json();}).then(function(data){
    var text = '';
    if (data.content) for (var i=0;i<data.content.length;i++) if(data.content[i].type==='text') text+=data.content[i].text;
    var el = document.getElementById(tid);
    if (el) { el.style.color='rgba(255,255,255,0.85)'; el.innerHTML = typeof renderMD==='function'?renderMD(text):text; }
    msgs.scrollTop = msgs.scrollHeight;
  }).catch(function(e){ var el=document.getElementById(tid); if(el){el.style.color='#fca5a5';el.textContent='Error: '+e.message;} });
};

window.dashDeleteDeal = function(idx, opts) {
  if (typeof _dash === 'undefined' || !_dash.pipeline) return;
  opts = opts || {};
  var deal = _dash.pipeline[idx];
  if (!deal) return;
  if (!opts.skipConfirm && !confirm('Remove "' + (deal.name || 'this deal') + '" from pipeline?\n\nThe linked contact will be sent back to Lead Pipeline (not deleted).')) return;

  var leadId = deal.leadId;
  _dash.pipeline.splice(idx, 1);

  if (leadId && typeof AN !== 'undefined' && AN.leads) {
    var lead = AN.leads.find(function(l) { return l.id === leadId; });
    if (lead && typeof anDemoteOpportunityToLead === 'function') {
      anDemoteOpportunityToLead(lead, {
        fromPipelineStage: deal.stage,
        sdrEmail: deal.sdrEmail,
        aeEmail: deal.aeEmail,
        save: false
      });
    }
  }

  if (typeof dashSave === 'function') dashSave();
  if (typeof AN !== 'undefined' && AN.save) AN.save();
  if (typeof dashRefreshPipelineUI === 'function') dashRefreshPipelineUI('pipeline');
  else if (typeof renderSalesDashboard === 'function') renderSalesDashboard();
  if (typeof showToast === 'function') showToast('Deal removed — contact is back in Lead Pipeline');
};

