// ── DATE RANGE STATE ─────────────────────────────────────────
var _dateRange = { preset: 'week', from: null, to: null };
try {
  var _savedDateRange = JSON.parse(localStorage.getItem('an-date-range') || 'null');
  if (_savedDateRange && _savedDateRange.preset) _dateRange = _savedDateRange;
} catch(e) {}

var DATE_RANGE_PRESETS = [
  { v:'today',     l:'Today' },
  { v:'yesterday', l:'Yesterday' },
  { v:'week',      l:'This Week' },
  { v:'lastweek',  l:'Last Week' },
  { v:'2weeks',    l:'Last 2 Weeks' },
  { v:'3weeks',    l:'Last 3 Weeks' },
  { v:'month',     l:'This Month' },
  { v:'lastmonth', l:'Last Month' },
  { v:'quarter',   l:'Last Quarter (90d)' },
  { v:'year',      l:'This Year' },
  { v:'custom',    l:'Custom Range...' }
];

function getDateRangeLabel() {
  var current = DATE_RANGE_PRESETS.filter(function(p){ return p.v === _dateRange.preset; })[0];
  return current ? current.l : 'This Week';
}

function getDateRangeBounds() {
  var now = new Date();
  var from, to = new Date(now);
  var p = _dateRange.preset;

  if (p === 'today') {
    from = new Date(now); from.setHours(0,0,0,0);
    to.setHours(23,59,59,999);
  } else if (p === 'yesterday') {
    from = new Date(now); from.setDate(from.getDate()-1); from.setHours(0,0,0,0);
    to   = new Date(from); to.setHours(23,59,59,999);
  } else if (p === 'week') {
    from = new Date(now); from.setDate(from.getDate()-7); from.setHours(0,0,0,0);
    to.setHours(23,59,59,999);
  } else if (p === 'lastweek') {
    from = new Date(now); from.setDate(from.getDate()-14); from.setHours(0,0,0,0);
    to   = new Date(now); to.setDate(to.getDate()-7); to.setHours(23,59,59,999);
  } else if (p === '2weeks') {
    from = new Date(now); from.setDate(from.getDate()-14); from.setHours(0,0,0,0);
    to.setHours(23,59,59,999);
  } else if (p === '3weeks') {
    from = new Date(now); from.setDate(from.getDate()-21); from.setHours(0,0,0,0);
    to.setHours(23,59,59,999);
  } else if (p === 'month') {
    from = new Date(now); from.setDate(from.getDate()-30); from.setHours(0,0,0,0);
    to.setHours(23,59,59,999);
  } else if (p === 'lastmonth') {
    from = new Date(now.getFullYear(), now.getMonth()-1, 1); from.setHours(0,0,0,0);
    to   = new Date(now.getFullYear(), now.getMonth(), 0); to.setHours(23,59,59,999);
  } else if (p === 'quarter') {
    from = new Date(now); from.setDate(from.getDate()-90); from.setHours(0,0,0,0);
    to.setHours(23,59,59,999);
  } else if (p === 'year') {
    from = new Date(now); from.setFullYear(from.getFullYear()-1); from.setHours(0,0,0,0);
    to.setHours(23,59,59,999);
  } else if (p === 'custom') {
    from = _dateRange.from ? new Date(_dateRange.from + 'T00:00:00') : new Date(now);
    to   = _dateRange.to   ? new Date(_dateRange.to + 'T23:59:59')   : new Date(now);
  } else {
    from = new Date(now); from.setDate(from.getDate()-7); from.setHours(0,0,0,0);
    to.setHours(23,59,59,999);
  }

  return { from: from, to: to, preset: p, label: getDateRangeLabel() };
}

function inDateRange(dateStr, from, to) {
  if (!dateStr) return false;
  var d = new Date(dateStr + 'T12:00:00');
  return d >= from && d <= to;
}

function getDateRangeDates() {
  var bounds = getDateRangeBounds();
  var from = bounds.from;
  var to = bounds.to;
  var dates = [];
  var cur = new Date(from);
  cur.setHours(12,0,0,0);
  var toDate = new Date(to);
  toDate.setHours(23,59,59,999);
  while (cur <= toDate) {
    dates.push(cur.toISOString().split('T')[0]);
    cur.setDate(cur.getDate()+1);
  }
  return dates;
}

// Override getActivityDates to use new range
window.getActivityDates = function() {
  // getActivityForPeriod() sets a dedicated override flag to scope whichever
  // Activity Goals tab (Today/Week/Month) is active. This must take priority over
  // the separate chart date-range dropdown (_dateRange.preset) — otherwise both
  // controls end up reading the same range and show identical numbers no matter
  // which one you click, which is exactly the bug that was happening here.
  // (Deliberately NOT using _dashTimeRange for this — that variable is already used
  // elsewhere for an unrelated chart's own range toggle and is always set to a
  // truthy default, so it can't reliably signal "an override is active" here.)
  if (window._anGoalDateOverride) {
    var now = new Date();
    var end = new Date(now); end.setHours(23, 59, 59, 999);
    var start = new Date(now); start.setHours(0, 0, 0, 0);
    if (window._anGoalDateOverride === 'week') start.setDate(start.getDate() - 6);
    else if (window._anGoalDateOverride === 'month') start.setDate(start.getDate() - 29);
    var dates = [];
    var cur = new Date(start); cur.setHours(12, 0, 0, 0);
    while (cur <= end) {
      dates.push(cur.toISOString().split('T')[0]);
      cur.setDate(cur.getDate() + 1);
    }
    return dates;
  }
  return getDateRangeDates();
};

// ── DATE RANGE DROPDOWN HTML ─────────────────────────────────
function buildRangeDropdown(selectId) {
  var id = selectId || 'chart-range-select';
  return '<div style="position:relative;display:inline-block;">'
    + '<select id="' + id + '" onchange="applyDateRange(this.value)" '
    + 'style="padding:6px 28px 6px 12px;border-radius:8px;border:1.5px solid #e4e4e7;background:#fff;font-size:12px;font-weight:600;color:#09090b;font-family:inherit;outline:none;cursor:pointer;appearance:none;-webkit-appearance:none;">'
    + DATE_RANGE_PRESETS.map(function(p){
        return '<option value="'+p.v+'"'+(_dateRange.preset===p.v?' selected':'')+'>'+p.l+'</option>';
      }).join('')
    + '</select>'
    + '<div style="position:absolute;right:8px;top:50%;transform:translateY(-50%);pointer-events:none;font-size:10px;color:#71717a;">▼</div>'
    + '</div>'
    // Custom range inputs (shown only when custom selected)
    + '<div id="custom-range-inputs" style="display:'+((_dateRange.preset==='custom')?'inline-flex':'none')+';align-items:center;gap:6px;margin-left:8px;">'
    + '<input type="date" id="range-from" value="'+(_dateRange.from||'')+'" onchange="applyCustomRange()" '
    + 'style="border:1.5px solid #e4e4e7;border-radius:6px;padding:5px 8px;font-size:12px;font-family:inherit;outline:none;">'
    + '<span style="font-size:11px;color:#71717a;">to</span>'
    + '<input type="date" id="range-to" value="'+(_dateRange.to||'')+'" onchange="applyCustomRange()" '
    + 'style="border:1.5px solid #e4e4e7;border-radius:6px;padding:5px 8px;font-size:12px;font-family:inherit;outline:none;">'
    + '</div>';
}

window.applyDateRange = function(preset) {
  _dateRange.preset = preset;
  try { localStorage.setItem('an-date-range', JSON.stringify(_dateRange)); } catch(e) {}
  var customInputs = document.getElementById('custom-range-inputs');
  if (customInputs) customInputs.style.display = preset === 'custom' ? 'inline-flex' : 'none';
  ['chart-range-select', 'sdr-range-select'].forEach(function(selId) {
    var el = document.getElementById(selId);
    if (el && el.value !== preset) el.value = preset;
  });
  if (preset !== 'custom') refreshActiveCharts();
};

window.applyCustomRange = function() {
  var from = document.getElementById('range-from');
  var to   = document.getElementById('range-to');
  if (from) _dateRange.from = from.value;
  if (to)   _dateRange.to   = to.value;
  try { localStorage.setItem('an-date-range', JSON.stringify(_dateRange)); } catch(e) {}
  if (_dateRange.from && _dateRange.to) refreshActiveCharts();
};

function refreshActiveCharts() {
  if (typeof dashRefreshTopStatTiles === 'function') dashRefreshTopStatTiles();

  setTimeout(function() {
    var sdr = document.getElementById('sdr-metrics-section');
    if (sdr && typeof buildSDRMetricsHTML === 'function') {
      sdr.innerHTML = buildSDRMetricsHTML();
      if (typeof loadChartJS === 'function') {
        loadChartJS(function() { setTimeout(renderFunnelChart, 80); });
      }
    }
  }, 50);

  var mainTab = window._dashActiveTab || 0;
  if (mainTab === 1) {
    loadChartJS(function() {
      renderPipelineChart();
      renderStateChart();
      renderSizeChart();
      renderDealsWonChart();
    });
    return;
  }

  var active = ['activity','demos','showrate'].filter(function(k){
    var p = document.getElementById('cp-'+k); return p && p.style.display !== 'none';
  })[0] || 'activity';
  loadChartJS(function() {
    if (active === 'activity') {
      renderActivityChart();
      renderDemosByStateChart();
      renderHotzoneChart();
      renderClosesChart();
      var slots = document.getElementById('hotzone-slots-panel');
      if (slots) {
        var inner = slots.querySelector('div:last-child');
        if (inner) inner.innerHTML = buildHotzoneSlots();
      }
      var top = document.getElementById('hotzone-top-cards');
      if (top) top.innerHTML = buildTopHourCards();
      var sdr = document.getElementById('sdr-metrics-section');
      if (sdr) { sdr.innerHTML = buildSDRMetricsHTML(); renderFunnelChart(); }
    }
    if (active === 'showrate') setTimeout(renderShowRateChart, 50);
    if (active === 'demos') {
      var w = document.getElementById('demo-list-wrap');
      if (w) w.innerHTML = buildDemoListHTML();
    }
  });
}

// ── Override buildAndShowCharts to use dropdown ───────────────
var _origBACS_range = window.buildAndShowCharts;
window.buildAndShowCharts = function() {
  _origBACS_range();
  ['chart-title','chart-title-ae'].forEach(function(id) {
    var titleRow = document.getElementById(id);
    if (titleRow && titleRow.parentNode) {
      var rangeHolder = titleRow.parentNode.querySelector('div:last-child');
      if (rangeHolder && typeof buildRangeDropdown === 'function') rangeHolder.innerHTML = buildRangeDropdown();
    }
  });
};

// ── CALL LOG DATA STRUCTURE ───────────────────────────────────
// Each activityLog entry extended with:
// pickups_by_hour: { 9: 3, 10: 5 }  — answered calls per hour
// demos_by_hour:   { 9: 1, 14: 2 }  — demos booked per hour
// voicemails_by_hour: { 9: 2 }

// ── Override dashIncrP to track call time ────────────────────
var _origDashIncrP_cl = window.dashIncrP;
window.dashIncrP = function(key) {
  _origDashIncrP_cl(key);
  if (key === 'calls') {
    // Open quick call log after incrementing
    openQuickCallLog();
  }
};
window.dashIncrement = window.dashIncrP;

// ── Quick call log popup ──────────────────────────────────────
window.openQuickCallLog = function() {
  var old = document.getElementById('quick-call-log');
  if (old) old.remove();

  var panel = document.createElement('div');
  panel.id = 'quick-call-log';
  panel.style.cssText = 'position:fixed;bottom:80px;right:24px;background:#0f0f17;border:1px solid rgba(99,102,241,0.4);border-radius:12px;padding:16px;width:280px;z-index:8888;box-shadow:0 8px 32px rgba(0,0,0,0.4);';

  var hour = new Date().getHours();
  var h12  = hour > 12 ? hour-12 : (hour===0?12:hour);
  var ampm = hour < 12 ? 'am' : 'pm';

  panel.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">'
    + '<div style="font-size:12px;font-weight:700;color:#fff;">Quick Call Log <span style="font-size:10px;color:rgba(255,255,255,0.4);">'+h12+ampm+'</span></div>'
    + '<button onclick="document.getElementById(\'quick-call-log\').remove()" style="background:none;border:none;color:rgba(255,255,255,0.4);font-size:16px;cursor:pointer;padding:0;">&#x2715;</button>'
    + '</div>'
    + '<div style="font-size:11px;color:rgba(255,255,255,0.5);margin-bottom:10px;">What happened on this call?</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:8px;">'
    + '<button onclick="logCallOutcome(\'pickup\')" style="background:rgba(16,185,129,0.2);border:1px solid rgba(16,185,129,0.4);border-radius:8px;padding:10px 8px;font-size:12px;font-weight:700;color:#6ee7b7;cursor:pointer;font-family:inherit;">✓ Picked Up</button>'
    + '<button onclick="logCallOutcome(\'voicemail\')" style="background:rgba(99,102,241,0.15);border:1px solid rgba(99,102,241,0.3);border-radius:8px;padding:10px 8px;font-size:12px;font-weight:700;color:#a5b4fc;cursor:pointer;font-family:inherit;">📬 Voicemail</button>'
    + '<button onclick="logCallOutcome(\'noanswer\')" style="background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:8px;padding:10px 8px;font-size:12px;font-weight:700;color:rgba(255,255,255,0.5);cursor:pointer;font-family:inherit;">📵 No Answer</button>'
    + '<button onclick="logCallOutcome(\'demo\')" style="background:rgba(245,158,11,0.2);border:1px solid rgba(245,158,11,0.4);border-radius:8px;padding:10px 8px;font-size:12px;font-weight:700;color:#fcd34d;cursor:pointer;font-family:inherit;">🎯 Demo Set!</button>'
    + '</div>'
    + '<button onclick="document.getElementById(\'quick-call-log\').remove()" style="width:100%;background:none;border:none;color:rgba(255,255,255,0.3);font-size:11px;cursor:pointer;font-family:inherit;padding:4px;">Skip</button>';

  document.body.appendChild(panel);

  // Auto-dismiss after 8 seconds
  setTimeout(function() {
    var p = document.getElementById('quick-call-log');
    if (p) p.remove();
  }, 8000);
};

window.logCallOutcome = function(outcome, extra) {
  extra = extra || {};
  var hour  = new Date().getHours();
  var today = typeof anLocalDateStr === 'function' ? anLocalDateStr() : new Date().toISOString().split('T')[0];
  if (!_dash.activityLog) _dash.activityLog = [];
  var entry = _dash.activityLog.filter(function(e){ return e.date === today; })[0];
  if (!entry) { entry = {date:today,calls:0,demos:0,closes:0}; _dash.activityLog.push(entry); }

  if (!entry.pickups_by_hour)   entry.pickups_by_hour   = {};
  if (!entry.voicemails_by_hour) entry.voicemails_by_hour = {};
  if (!entry.demos_by_hour)     entry.demos_by_hour     = {};
  if (!entry.noanswer_by_hour)  entry.noanswer_by_hour  = {};
  if (!entry.calls_by_hour)     entry.calls_by_hour     = {};
  if (!entry.notinterested_by_hour) entry.notinterested_by_hour = {};

  entry.calls = (entry.calls || 0) + 1;
  _dash.activity.calls = (_dash.activity.calls || 0) + 1;
  entry.calls_by_hour[hour] = (entry.calls_by_hour[hour] || 0) + 1;

  if (outcome === 'pickup') {
    entry.pickups_by_hour[hour]   = (entry.pickups_by_hour[hour]   || 0) + 1;
  } else if (outcome === 'voicemail') {
    entry.voicemails_by_hour[hour] = (entry.voicemails_by_hour[hour] || 0) + 1;
  } else if (outcome === 'noanswer') {
    entry.noanswer_by_hour[hour]  = (entry.noanswer_by_hour[hour]  || 0) + 1;
  } else if (outcome === 'not_interested') {
    entry.pickups_by_hour[hour] = (entry.pickups_by_hour[hour] || 0) + 1;
    entry.notinterested_by_hour[hour] = (entry.notinterested_by_hour[hour] || 0) + 1;
  } else if (outcome === 'demo') {
    entry.pickups_by_hour[hour]   = (entry.pickups_by_hour[hour]   || 0) + 1;
    entry.demos_by_hour[hour]     = (entry.demos_by_hour[hour]     || 0) + 1;
    entry.demos = (entry.demos || 0) + 1;
    _dash.activity.demos = (_dash.activity.demos || 0) + 1;
    var dInp = document.getElementById('gact-demos');
    if (dInp) dInp.value = parseInt(dInp.value||0) + 1;
  }

  // ── Also stamp the call on the lead's callLog so the leaderboard
  //    backfill (anBackfillTeamActivityFromLeads) can attribute it correctly ──
  var csLeadId = window._anCsLeadPanelId || (document.getElementById('mcm-overlay') && document.getElementById('mcm-overlay')._leadId);
  if (csLeadId && typeof AN !== 'undefined' && AN.leadById) {
    var csLead = AN.leadById(csLeadId);
    if (csLead) {
      if (!csLead.callLog) csLead.callLog = [];
      var repEmail = (typeof AN !== 'undefined' && AN.currentRepEmail) || (typeof _currentUser !== 'undefined' && _currentUser && _currentUser.email) || '';
      // Only add if not already logged (avoid double-counting if mcmSave also runs)
      var now = new Date();
      var timeStr = String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0');
      var alreadyLogged = csLead.callLog.some(function(c) {
        return c.date === today && c.time === timeStr && c.outcome === outcome && c.rep === repEmail;
      });
      if (!alreadyLogged) {
        var callEntry = {
          id: 'act-' + Date.now(),
          type: 'call',
          outcome: outcome,
          date: today,
          time: timeStr,
          rep: repEmail,
          loggedAt: now.toISOString(),
          _fromSession: true
        };
        if (extra.category) callEntry.category = extra.category;
        if (extra.note) callEntry.notes = extra.note;
        csLead.callLog.push(callEntry);
        csLead.updated = now.toISOString();
      }
      if (outcome === 'not_interested') {
        csLead.status = 'not_interested';
      }
    }
  }

  dashSave();
  // Persist the lead's callLog entry (added above) — without this, the call never
  // syncs to an_leads and the admin's leaderboard/dashboard never sees it.
  if (csLeadId && typeof AN !== 'undefined' && typeof AN.save === 'function') {
    AN.save();
  }
  if (typeof anPushTeamActivityCloud === 'function') {
    var cloudDelta = { calls: 1 };
    if (outcome === 'demo') cloudDelta.demos = 1;
    anPushTeamActivityCloud(cloudDelta);
  }
  var panel = document.getElementById('quick-call-log');
  if (panel) {
    var labels = { pickup:'✓ Logged', voicemail:'📬 Logged', noanswer:'📵 Logged', demo:'🎯 Demo set!', not_interested:'🚫 Logged' };
    panel.innerHTML = '<div style="text-align:center;padding:16px;">'
      + '<div style="font-size:24px;margin-bottom:8px;">'+(outcome==='demo'?'🎯':outcome==='not_interested'?'🚫':'✓')+'</div>'
      + '<div style="font-size:14px;font-weight:700;color:#fff;">'+(labels[outcome]||'Logged')+'</div>'
      + '</div>';
    setTimeout(function(){ if(panel.parentNode) panel.remove(); }, 1500);
  }

  if (outcome === 'not_interested' && csLeadId && typeof anOpenDemoSetFollowup !== 'undefined') {
    // Already handled by anLogNotInterested reason picker — nothing extra needed
  }
  // After a plain pickup (just talked, no demo, no NI), ask what the next step is
  if (outcome === 'pickup' && csLeadId && typeof anOpenNextStepPrompt === 'function') {
    setTimeout(function() { anOpenNextStepPrompt(csLeadId); }, 400);
  }
};

// ── Demo Set follow-up: needs/pain points note + AE assignment ──
window.anOpenDemoSetFollowup = function(leadId) {
  var lead = (typeof AN !== 'undefined' && AN.leadById) ? AN.leadById(leadId) : null;
  if (!lead) return;
  var existing = document.getElementById('an-demo-followup-modal');
  if (existing) existing.remove();

  var reps = typeof anGetKnownRepEmails === 'function' ? anGetKnownRepEmails() : [];
  var myEmail = (typeof AN !== 'undefined' && AN.currentRepEmail) || '';
  var aeOptions = '<option value="">— Select AE —</option>' + reps.map(function(em) {
    var label = typeof anGetRepName === 'function' ? anGetRepName(em) : em.split('@')[0];
    var sel = (lead.aeEmail || '') === em ? ' selected' : '';
    return '<option value="'+anEsc(em)+'"'+sel+'>'+anEsc(label)+(em===myEmail?' (me)':'')+'</option>';
  }).join('');

  var backdrop = document.createElement('div');
  backdrop.id = 'an-demo-followup-modal';
  backdrop.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:21500;display:flex;align-items:center;justify-content:center;';
  backdrop.onclick = function(e) { if (e.target === backdrop) backdrop.remove(); };

  backdrop.innerHTML = '<div style="background:#fff;border-radius:14px;padding:22px;width:420px;max-width:92vw;font-family:inherit;box-shadow:0 24px 80px rgba(0,0,0,0.3);" onclick="event.stopPropagation()">'
    + '<div style="font-size:15px;font-weight:800;color:#09090b;margin-bottom:4px;">🎯 Demo Set — quick details</div>'
    + '<div style="font-size:12px;color:#71717a;margin-bottom:16px;">Helps the AE prep, and feeds the Field Insights board.</div>'
    + '<label style="font-size:11px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">What needs / pain points came up?</label>'
    + '<textarea id="an-df-notes" rows="3" placeholder="e.g. struggling with OEP renewals, currently using spreadsheets, wants to automate quoting..." style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:10px;font-size:12.5px;font-family:inherit;outline:none;resize:vertical;box-sizing:border-box;margin-bottom:14px;">'+anEsc(lead.demoNotes||'')+'</textarea>'
    + '<label style="font-size:11px;font-weight:700;color:#71717a;display:block;margin-bottom:4px;">Who\'s running this demo? (AE)</label>'
    + '<select id="an-df-ae" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 12px;font-size:13px;font-family:inherit;outline:none;box-sizing:border-box;margin-bottom:16px;">'+aeOptions+'</select>'
    + '<div style="display:flex;gap:8px;">'
    + '<button type="button" onclick="document.getElementById(\'an-demo-followup-modal\').remove()" style="flex:1;padding:10px;border:1.5px solid #e4e4e7;border-radius:8px;background:#fff;color:#71717a;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Skip</button>'
    + '<button type="button" onclick="anSaveDemoSetFollowup(\''+leadId+'\')" style="flex:1;padding:10px;border:none;border-radius:8px;background:#6366f1;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Save</button>'
    + '</div>'
    + '</div>';
  document.body.appendChild(backdrop);
};

window.anSaveDemoSetFollowup = function(leadId) {
  var lead = (typeof AN !== 'undefined' && AN.leadById) ? AN.leadById(leadId) : null;
  if (!lead) return;
  var notes = (document.getElementById('an-df-notes').value || '').trim();
  var aeEmail = (document.getElementById('an-df-ae').value || '').trim().toLowerCase();

  if (notes) {
    lead.demoNotes = notes;
    // Surface this as a Field Insight too — tagged "pain" so it lands in Pain/OEP
    if (!lead.callLog) lead.callLog = [];
    var now = new Date();
    lead.callLog.push({
      id: 'act-' + Date.now(),
      type: 'note',
      outcome: 'demo',
      date: typeof anLocalDateStr === 'function' ? anLocalDateStr() : now.toISOString().split('T')[0],
      time: String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0'),
      rep: (typeof AN !== 'undefined' && AN.currentRepEmail) || '',
      loggedAt: now.toISOString(),
      notes: notes,
      category: 'pain'
    });
  }

  if (aeEmail) {
    anAssignAE(lead, aeEmail);
  }

  lead.updated = new Date().toISOString();
  if (typeof AN !== 'undefined' && AN.save) AN.save();
  var modal = document.getElementById('an-demo-followup-modal');
  if (modal) modal.remove();
  if (typeof showToast === 'function') showToast(aeEmail ? 'Demo details saved — AE assigned' : 'Demo details saved');
};

// ── AE Assignment ──────────────────────────────────────────────
// While a lead is still being worked by an SDR, _repEmail = SDR (owner).
// aeEmail = the AE who will run/own the demo, until the lead converts to
// an Opportunity, at which point ownership (_repEmail) transfers to the AE.
window.anAssignAE = function(lead, aeEmail) {
  if (!lead || !aeEmail) return;
  var prevAE = lead.aeEmail;
  lead.aeEmail = aeEmail.toLowerCase();
  if (prevAE !== lead.aeEmail) {
    lead.aeNotified = false;
    lead.aeAssignedAt = new Date().toISOString();
    lead.aeAssignedBy = (typeof AN !== 'undefined' && AN.currentRepEmail) || '';
  }
};

// Called once when an AE views a lead assigned to them, to clear the notification badge
window.anMarkAENotified = function(lead) {
  if (!lead || lead.aeNotified) return;
  lead.aeNotified = true;
  if (typeof AN !== 'undefined' && AN.save) AN.save();
};

// Get all leads where the current user is the assigned AE and hasn't seen it yet
window.anGetUnseenAEAssignments = function() {
  if (typeof AN === 'undefined' || !AN.leads) return [];
  var myEmail = (AN.currentRepEmail || '').toLowerCase();
  if (!myEmail) return [];
  return AN.leads.filter(function(l) {
    return l && (l.aeEmail || '').toLowerCase() === myEmail && !l.aeNotified && !l.isOpportunity;
  });
};

// Get all leads where the current user is the assigned AE (seen or not), demo not yet converted
window.anGetMyAEAssignments = function() {
  if (typeof AN === 'undefined' || !AN.leads) return [];
  var myEmail = (AN.currentRepEmail || '').toLowerCase();
  if (!myEmail) return [];
  return AN.leads.filter(function(l) {
    return l && (l.aeEmail || '').toLowerCase() === myEmail && !l.isOpportunity;
  });
};

// When a lead converts to an Opportunity, ownership transfers from the SDR to the AE
window.anTransferOwnershipToAE = function(lead) {
  if (!lead || !lead.aeEmail) return;
  if (!lead.sdrEmail) lead.sdrEmail = lead._repEmail || ''; // preserve who sourced it
  lead._repEmail = lead.aeEmail.toLowerCase();
};

// ── Next Step prompt — fires after "Just talked" pickup outcome ──────────
window.anOpenNextStepPrompt = function(leadId) {
  var lead = (typeof AN !== 'undefined' && AN.leadById) ? AN.leadById(leadId) : null;
  if (!lead) return;
  var existing = document.getElementById('an-next-step-modal');
  if (existing) existing.remove();
  var now = new Date();
  var tomorrow = new Date(now); tomorrow.setDate(now.getDate() + 1);
  var in3 = new Date(now); in3.setDate(now.getDate() + 3);
  var nextWeek = new Date(now); nextWeek.setDate(now.getDate() + 7);
  function fmt(d) { return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
  var leadName = ((lead.firstName||'')+' '+(lead.lastName||'')).trim() || lead.company || 'this lead';
  var taskTypes = typeof AN_TASK_TYPES !== 'undefined' ? AN_TASK_TYPES : [
    {id:'call',icon:'📞',label:'Call Back',color:'#6366f1'},
    {id:'email',icon:'📧',label:'Send Email',color:'#f59e0b'},
    {id:'text',icon:'💬',label:'Send Text',color:'#10b981'},
    {id:'followup',icon:'🔔',label:'Follow Up',color:'#8b5cf6'},
    {id:'demo',icon:'🎯',label:'Demo Prep',color:'#06b6d4'},
    {id:'other',icon:'📋',label:'Other',color:'#a1a1aa'}
  ];
  var backdrop = document.createElement('div');
  backdrop.id = 'an-next-step-modal';
  backdrop.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:21500;display:flex;align-items:center;justify-content:center;';
  backdrop.onclick = function(e) { if (e.target === backdrop) backdrop.remove(); };
  backdrop.innerHTML = '<div style="background:#fff;border-radius:14px;padding:22px;width:400px;max-width:92vw;font-family:inherit;box-shadow:0 24px 80px rgba(0,0,0,0.3);" onclick="event.stopPropagation()">'
    + '<div style="font-size:15px;font-weight:800;color:#09090b;margin-bottom:4px;">👋 Good talk — what\'s the next step?</div>'
    + '<div style="font-size:12px;color:#71717a;margin-bottom:16px;">Set a follow-up so '+anEsc(leadName)+' doesn\'t slip through the cracks.</div>'
    + '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-bottom:14px;">'
    + taskTypes.map(function(t) {
        return '<button type="button" id="nsp-method-'+t.id+'" onclick="anNspSelectMethod(\''+t.id+'\')" '
          +'style="padding:9px 6px;border:1.5px solid #e4e4e7;border-radius:9px;background:#fff;font-size:12px;font-weight:700;color:#52525b;cursor:pointer;font-family:inherit;display:flex;flex-direction:column;align-items:center;gap:3px;">'
          +'<span style="font-size:16px;">'+t.icon+'</span>'+t.label+'</button>';
      }).join('')
    + '</div>'
    + '<div style="font-size:11px;font-weight:700;color:#71717a;margin-bottom:6px;letter-spacing:0.08em;">WHEN</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-bottom:10px;">'
    + [['Tomorrow',fmt(tomorrow)],['In 3 days',fmt(in3)],['Next week',fmt(nextWeek)]].map(function(opt) {
        return '<button type="button" id="nsp-when-'+opt[1]+'" onclick="anNspSelectWhen(\''+opt[1]+'\')" '
          +'style="padding:8px;border:1.5px solid #e4e4e7;border-radius:8px;background:#fff;font-size:12px;font-weight:600;color:#52525b;cursor:pointer;font-family:inherit;">'+opt[0]+'</button>';
      }).join('')
    + '</div>'
    + '<input type="date" id="nsp-date-input" value="'+fmt(tomorrow)+'" '
      +'style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:8px 12px;font-size:12.5px;font-family:inherit;outline:none;box-sizing:border-box;margin-bottom:12px;" '
      +'oninput="anNspSelectWhen(this.value)">'
    + '<input type="text" id="nsp-note" placeholder="Optional note (e.g. reviewing with her team)" '
      +'style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 12px;font-size:12.5px;font-family:inherit;outline:none;box-sizing:border-box;margin-bottom:16px;">'
    + '<div style="display:flex;gap:8px;">'
    + '<button type="button" onclick="document.getElementById(\'an-next-step-modal\').remove()" style="flex:1;padding:10px;border:1.5px solid #e4e4e7;border-radius:8px;background:#fff;color:#71717a;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Skip</button>'
    + '<button type="button" onclick="anSaveNextStep(\''+leadId+'\')" style="flex:2;padding:10px;border:none;border-radius:8px;background:#6366f1;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Set Follow-Up ✓</button>'
    + '</div>'
    + '</div>';
  document.body.appendChild(backdrop);
  window._anNspState = { method: 'call', when: fmt(tomorrow) };
  anNspSelectMethod('call');
  anNspSelectWhen(fmt(tomorrow));
};

window.anNspSelectMethod = function(id) {
  if (!window._anNspState) return;
  window._anNspState.method = id;
  document.querySelectorAll('[id^="nsp-method-"]').forEach(function(btn) {
    var active = btn.id === 'nsp-method-' + id;
    btn.style.borderColor = active ? '#6366f1' : '#e4e4e7';
    btn.style.background = active ? 'rgba(99,102,241,0.07)' : '#fff';
    btn.style.color = active ? '#6366f1' : '#52525b';
  });
};

window.anNspSelectWhen = function(dateStr) {
  if (!window._anNspState) return;
  window._anNspState.when = dateStr;
  document.querySelectorAll('[id^="nsp-when-"]').forEach(function(btn) {
    var active = btn.id === 'nsp-when-' + dateStr;
    btn.style.borderColor = active ? '#6366f1' : '#e4e4e7';
    btn.style.background = active ? 'rgba(99,102,241,0.07)' : '#fff';
    btn.style.color = active ? '#6366f1' : '#52525b';
  });
  var di = document.getElementById('nsp-date-input');
  if (di && di.value !== dateStr) di.value = dateStr;
};

window.anSaveNextStep = function(leadId) {
  var state = window._anNspState;
  if (!state || !state.when) return;
  var lead = (typeof AN !== 'undefined' && AN.leadById) ? AN.leadById(leadId) : null;
  if (!lead) return;
  var note = (document.getElementById('nsp-note') || {}).value || '';
  if (typeof anCreateFollowUpTask === 'function') {
    anCreateFollowUpTask(lead, state.when, '09:00', state.method, note.trim() || 'Follow-up from call');
  }
  var modal = document.getElementById('an-next-step-modal');
  if (modal) modal.remove();
  if (typeof showToast === 'function') {
    var taskTypes = typeof AN_TASK_TYPES !== 'undefined' ? AN_TASK_TYPES : [];
    var t = taskTypes.find(function(x){return x.id===state.method;});
    showToast((t ? t.icon+' ' : '') + 'Follow-up set for ' + state.when);
  }
  window._anNspState = null;
};

window.anLogNotInterested = function() {
  anOpenReasonPicker({
    title: 'Why not interested?',
    subtitle: 'Quick tag for the Field Insights board — helps marketing & product.',
    onConfirm: function(category, note) {
      logCallOutcome('not_interested', { category: category, note: note });
    },
    onSkip: function() {
      // Still log the outcome even if they skip the reason
      logCallOutcome('not_interested', {});
    }
  });
};

// ── Enhanced hotzone with pickup rate ────────────────────────
function buildEnhancedHotzoneData() {
  var dates = getDateRangeDates();
  var hourCalls    = {}, hourPickups = {}, hourDemos = {}, hourVoicemail = {};
  for (var h=7; h<=19; h++) { hourCalls[h]=0; hourPickups[h]=0; hourDemos[h]=0; hourVoicemail[h]=0; }

  var log = _dash.activityLog || [];
  log.forEach(function(entry) {
    if (dates.indexOf(entry.date) === -1) return;
    if (entry.calls_by_hour) Object.keys(entry.calls_by_hour).forEach(function(h){
      var hr=parseInt(h); if(hr>=7&&hr<=19) hourCalls[hr]+=(entry.calls_by_hour[h]||0);
    });
    if (entry.pickups_by_hour) Object.keys(entry.pickups_by_hour).forEach(function(h){
      var hr=parseInt(h); if(hr>=7&&hr<=19) hourPickups[hr]+=(entry.pickups_by_hour[h]||0);
    });
    if (entry.demos_by_hour) Object.keys(entry.demos_by_hour).forEach(function(h){
      var hr=parseInt(h); if(hr>=7&&hr<=19) hourDemos[hr]+=(entry.demos_by_hour[h]||0);
    });
    if (entry.voicemails_by_hour) Object.keys(entry.voicemails_by_hour).forEach(function(h){
      var hr=parseInt(h); if(hr>=7&&hr<=19) hourVoicemail[hr]+=(entry.voicemails_by_hour[h]||0);
    });
  });

  var hours  = Object.keys(hourCalls).map(Number).sort(function(a,b){return a-b;});
  var labels = hours.map(function(h){ var a=h<12?'am':'pm'; var h12=h>12?h-12:(h===0?12:h); return h12+a; });
  var maxCalls = Math.max.apply(null,Object.values(hourCalls))||1;

  // Best pickup rate hour (min 2 calls)
  var bestPickupHour = null, bestPickupRate = 0;
  hours.forEach(function(h){
    if (hourCalls[h] >= 2) {
      var rate = hourPickups[h] / hourCalls[h];
      if (rate > bestPickupRate) { bestPickupRate = rate; bestPickupHour = h; }
    }
  });

  // Best demo booking hour
  var bestDemoHour = hours.reduce(function(best,h){ return hourDemos[h]>(hourDemos[best]||0)?h:best; }, hours[0]);

  return {
    hours, labels, hourCalls, hourPickups, hourDemos, hourVoicemail,
    maxCalls, bestPickupHour, bestPickupRate, bestDemoHour,
    topHours: hours.slice().sort(function(a,b){return hourCalls[b]-hourCalls[a];}).slice(0,3).filter(function(h){return hourCalls[h]>0;})
  };
}

// Override renderHotzoneChart with enhanced version
window.renderHotzoneChart = function() {
  if (typeof destroyChart === 'function') destroyChart('hotzone');
  var canvas = document.getElementById('chart-hotzone');
  if (!canvas || !window.Chart) return;

  var d = buildEnhancedHotzoneData();
  var hasPickups = d.hours.some(function(h){ return d.hourPickups[h] > 0; });

  var datasets = [{
    label: 'Calls',
    data: d.hours.map(function(h){ return d.hourCalls[h]; }),
    backgroundColor: d.hours.map(function(h){
      var p = d.maxCalls > 0 ? d.hourCalls[h]/d.maxCalls : 0;
      return p>=0.8?'#f59e0b':p>=0.5?'#6366f1':'#c7d2fe';
    }),
    borderRadius: 5, borderSkipped: false
  }];

  if (hasPickups) {
    datasets.push({
      label: 'Pickups',
      data: d.hours.map(function(h){ return d.hourPickups[h]; }),
      backgroundColor: '#10b98188',
      borderRadius: 5, borderSkipped: false
    });
    datasets.push({
      label: 'Demos Set',
      data: d.hours.map(function(h){ return d.hourDemos[h]; }),
      backgroundColor: '#f59e0b',
      borderRadius: 5, borderSkipped: false
    });
  }

  if (typeof _charts !== 'undefined') {
    _charts['hotzone'] = new Chart(canvas, {
      type: 'bar',
      data: { labels: d.labels, datasets: datasets },
      options: {
        responsive: true,
        plugins: {
          legend: { display: hasPickups, position: 'bottom', labels: { font:{size:11}, boxWidth:12, padding:10 }},
          tooltip: {
            callbacks: {
              afterBody: function(items) {
                var h = d.hours[items[0].dataIndex];
                var calls = d.hourCalls[h], picks = d.hourPickups[h], dems = d.hourDemos[h];
                var lines = [];
                if (calls > 0 && picks > 0) lines.push('Pickup rate: ' + Math.round(picks/calls*100) + '%');
                if (dems > 0 && picks > 0)  lines.push('Demo rate: '   + Math.round(dems/picks*100)  + '% of pickups');
                return lines;
              }
            }
          }
        },
        scales: {
          y: { beginAtZero:true, ticks:{stepSize:1}, grid:{color:'#f4f4f5'} },
          x: { grid:{display:false}, ticks:{font:{size:11}} }
        }
      }
    });
  }

  // Update slots and insight cards
  var slotsEl = document.getElementById('hotzone-slots-panel');
  if (slotsEl) {
    var inner = slotsEl.querySelectorAll('div');
    if (inner.length > 1) inner[inner.length-1].innerHTML = buildEnhancedSlots(d);
  }
  var topEl = document.getElementById('hotzone-top-cards');
  if (topEl) topEl.innerHTML = buildEnhancedTopCards(d);
};

function buildEnhancedSlots(d) {
  var slots=[{l:'Early Morning',h:[7,8],e:'🌅'},{l:'Morning',h:[9,10,11],e:'☀️'},{l:'Midday',h:[12,13],e:'🕛'},{l:'Afternoon',h:[14,15,16],e:'🌤️'},{l:'Late Day',h:[17,18,19],e:'🌇'}];
  var totalCalls = d.hours.reduce(function(s,h){return s+d.hourCalls[h];},0);
  var hasPickupData = d.hours.some(function(h){ return d.hourPickups[h]>0; });

  return slots.map(function(slot){
    var sc=slot.h.reduce(function(s,h){return s+(d.hourCalls[h]||0);},0);
    var sp=slot.h.reduce(function(s,h){return s+(d.hourPickups[h]||0);},0);
    var sd=slot.h.reduce(function(s,h){return s+(d.hourDemos[h]||0);},0);
    var pct=totalCalls>0?Math.round(sc/totalCalls*100):0;
    var pickupRate=sc>0&&hasPickupData?Math.round(sp/sc*100):null;
    return '<div style="margin-bottom:10px;">'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">'
      +'<span style="font-size:13px;">'+slot.e+'</span>'
      +'<span style="font-size:12px;font-weight:600;color:#09090b;flex:1;">'+slot.l+'</span>'
      +'<span style="font-size:11px;font-weight:700;color:#09090b;">'+sc+' calls</span>'
      +(pickupRate!==null?'<span style="font-size:10px;color:#10b981;font-weight:700;">'+pickupRate+'% ans</span>':'')
      +(sd>0?'<span style="font-size:10px;color:#f59e0b;font-weight:700;">'+sd+' demos</span>':'')
      +'</div>'
      +'<div style="background:#f4f4f5;border-radius:20px;height:6px;overflow:hidden;">'
      +'<div style="background:'+(pct>=30?'#10b981':pct>=20?'#6366f1':'#e4e4e7')+';height:6px;border-radius:20px;width:'+pct+'%;"></div>'
      +'</div></div>';
  }).join('');
}

function buildEnhancedTopCards(d) {
  var hasPickupData = d.hours.some(function(h){ return d.hourPickups[h]>0; });
  var medals=['🥇','🥈','🥉'], colors=['#f59e0b','#6366f1','#10b981'];
  var cards = '';

  // Top call hours
  if (d.topHours.length) {
    cards += '<div style="margin-bottom:12px;">'
      +'<div style="font-size:10px;font-weight:700;color:#f59e0b;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:8px;">🔥 Most Calls</div>'
      +'<div style="display:grid;grid-template-columns:repeat('+d.topHours.length+',1fr);gap:8px;">'
      +d.topHours.map(function(h,i){
        var a=h<12?'am':'pm',h12=h>12?h-12:(h===0?12:h);
        var pr=d.hourCalls[h]>0&&d.hourPickups[h]>0?Math.round(d.hourPickups[h]/d.hourCalls[h]*100):null;
        return '<div style="background:#fff;border:1px solid #e4e4e7;border-radius:10px;padding:10px;text-align:center;">'
          +'<div style="font-size:16px;margin-bottom:2px;">'+medals[i]+'</div>'
          +'<div style="font-size:18px;font-weight:800;color:'+colors[i]+';">'+h12+a+'</div>'
          +'<div style="font-size:10px;color:#71717a;">'+d.hourCalls[h]+' calls</div>'
          +(pr!==null?'<div style="font-size:10px;color:#10b981;font-weight:700;">'+pr+'% ans</div>':'')
          +'</div>';
      }).join('')+'</div></div>';
  }

  // Best pickup rate hour
  if (hasPickupData && d.bestPickupHour !== null) {
    var h=d.bestPickupHour, a=h<12?'am':'pm', h12=h>12?h-12:(h===0?12:h);
    cards += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">'
      +'<div style="background:linear-gradient(135deg,#ecfdf5,#d1fae5);border:1px solid #a7f3d0;border-radius:10px;padding:10px 12px;">'
      +'<div style="font-size:9px;font-weight:700;color:#10b981;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;">Best Pickup Rate</div>'
      +'<div style="font-size:20px;font-weight:800;color:#065f46;">'+h12+a+'</div>'
      +'<div style="font-size:10px;color:#047857;">'+Math.round(d.bestPickupRate*100)+'% answer rate</div>'
      +'</div>';

    // Best demo booking hour
    if (d.bestDemoHour !== null && d.hourDemos[d.bestDemoHour] > 0) {
      var dh=d.bestDemoHour, da=dh<12?'am':'pm', dh12=dh>12?dh-12:(dh===0?12:dh);
      cards += '<div style="background:linear-gradient(135deg,#fffbeb,#fef3c7);border:1px solid #fde68a;border-radius:10px;padding:10px 12px;">'
        +'<div style="font-size:9px;font-weight:700;color:#f59e0b;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;">Most Demos Set</div>'
        +'<div style="font-size:20px;font-weight:800;color:#92400e;">'+dh12+da+'</div>'
        +'<div style="font-size:10px;color:#b45309;">'+d.hourDemos[d.bestDemoHour]+' demos booked</div>'
        +'</div>';
    }
    cards += '</div>';
  }

  if (!cards) cards = '<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:10px;padding:12px 14px;font-size:12px;color:#92400e;">Press + Calls and log each outcome to build hotzone data. After a few days you\'ll see your best hours for pickups and demo sets.</div>';

  return cards;
}

