    if (btn) { btn._origHTML = btn.innerHTML; btn.innerHTML = '<span class="nav-icon">💰</span>••••••••••••••'; btn.style.opacity='0.4'; btn.style.filter='blur(3px)'; }
    if (eye) eye.innerHTML = '🔒';
    if (sec) sec.style.filter = 'blur(8px)';
