function anBuildCommissionLedgerHTML() {
  var ledger = anEnsureCommissionLedger();
  if (!ledger.length) {
    return '<div style="text-align:center;padding:24px;color:#a1a1aa;font-size:12.5px;">No closed deals logged yet. Deals closed in the CRM appear here automatically.</div>';
  }
  var sizeLabel = { solo: 'Solo Agent', small: 'Small Agency', large: 'Large Agency', enterprise: 'Enterprise' };
  return ledger.filter(function(d) { return (d.status || 'closed') === 'closed'; }).slice(0, 50).map(function(d) {
    var comm = anCommissionPerClose(d.size, d.contractType);
    var dateStr = d.closedDate ? String(d.closedDate).slice(0,10) : '';
    var sourceTag = d.source === 'crm'
      ? '<span style="background:#eef2ff;color:#6366f1;border-radius:10px;padding:1px 7px;font-size:9px;font-weight:700;">CRM</span>'
      : '<span style="background:#f3f4f6;color:#71717a;border-radius:10px;padding:1px 7px;font-size:9px;font-weight:700;">MANUAL</span>';
    return '<div onclick="anOpenTrackerDealRef(\'' + (d.leadId ? 'opp' : 'comm-ae') + '\',\'' + (d.leadId || d.id).replace(/'/g, "\\'") + '\')" style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border:1px solid #e4e4e7;border-radius:8px;margin-bottom:6px;cursor:pointer;" onmouseover="this.style.borderColor=\'#6366f1\'" onmouseout="this.style.borderColor=\'#e4e4e7\'">'
      + '<div style="min-width:0;">'
      + '<div style="font-size:13px;font-weight:700;color:#09090b;display:flex;align-items:center;gap:6px;">'+anEsc(d.name)+sourceTag+' <span style="font-size:10px;color:#a1a1aa;font-weight:600;">↗ open</span></div>'
      + '<div style="font-size:11px;color:#71717a;margin-top:2px;">'+(sizeLabel[d.size]||d.size)+' · '+(d.contractType==='arr'?'Annual':'Monthly')+' · '+dateStr+'</div>'
      + '</div>'
      + '<div style="display:flex;align-items:center;gap:8px;flex-shrink:0;">'
      + '<div style="font-size:13px;font-weight:800;color:#10b981;">+'+fmtDol(comm)+(d.contractType==='arr'?'':'/mo')+'</div>'
      + anBuildTrackerDealActionButtons({ leadId: d.leadId, commissionDealId: d.id, refKind: d.leadId ? 'opp' : 'comm-ae', refId: d.leadId || d.id, name: d.name }, 'ae')
      + '</div></div>';
  }).join('');
}

