var _aiChats = [];        // array of {id, title, messages, created}
var _aiActiveChatId = null;
var _aiChatHistory = []; // messages for current chat

function loadAIChats() {
  try { _aiChats = JSON.parse(localStorage.getItem('ai-chats') || '[]'); } catch(e) { _aiChats = []; }
}
function saveAIChats() {
  // Keep last 20 chats
  _aiChats = _aiChats.slice(-20);
  localStorage.setItem('ai-chats', JSON.stringify(_aiChats));
}

// ── Full system prompt with all AgentNav context ──────────────
function buildAISystemPrompt() {
  var prospect = (_dash && _dash.prospect) || {};
  var pipeline = (_dash && _dash.pipeline) || [];
  var activity = (_dash && _dash.activity) || {};
  var log      = (_dash && _dash.activityLog) || [];
  var demos    = (_dash && _dash.demos) || [];

  // Conversion rates from last 30 days
  var now = new Date(), cutoff = new Date(now); cutoff.setDate(cutoff.getDate()-30);
  var calls=0, demosSt=0, closes=0;
  log.forEach(function(e) {
    if (new Date(e.date+'T12:00:00') >= cutoff) { calls+=e.calls||0; demosSt+=e.demos||0; closes+=e.closes||0; }
  });
  var callToDemo   = calls>0 ? (demosSt/calls*100).toFixed(1)+'%' : 'not enough data';
  var demoToClose  = demosSt>0 ? (closes/demosSt*100).toFixed(0)+'%' : 'not enough data';

  // Won deals
  var wonDeals = pipeline.filter(function(d){ return d.stage==='Closed Won'; });
  var activePipeline = pipeline.filter(function(d){ return d.stage!=='Closed Won'&&d.stage!=='Closed Lost'; });

  var prospectCtx = prospect.state||prospect.size||prospect.name
    ? '\n\nCURRENT PROSPECT: '+(prospect.name||'unnamed')+' | State: '+(prospect.state||'unknown')+' | Size: '+(prospect.size||'unknown')
    : '';

  var activityCtx = (calls>0||demosSt>0)
    ? '\n\nREP ACTIVITY (last 30 days): '+calls+' calls made, '+demosSt+' demos set, '+closes+' closes | Call→Demo: '+callToDemo+' | Demo→Close: '+demoToClose
    : '';

  var pipeCtx = activePipeline.length>0
    ? '\n\nACTIVE PIPELINE: '+activePipeline.length+' deals including '+activePipeline.slice(0,3).map(function(d){return d.name+' ('+d.stage+')'}).join(', ')
    : '';

  return `You are the AgentNav AI Sales Coach — an elite, direct, expert sales assistant built specifically for AgentNav health insurance broker platform sales reps.

ABOUT AGENTNAV:
- Health insurance broker platform: ACA/STM/Life/Ancillary quoting, HealthSherpa + EDE enrollment, full CRM, SMS with dedicated number, Renewal Autopilot for OEP, policy tracker, compliance forms
- Pricing: Solo Agent $79/mo | Small Agency (2-9 agents) $247+/mo | Large Agency (10+ agents) $597+/mo
- Key differentiators: Native ACA quoting (EZLynx has zero), Renewal Autopilot (no competitor has equivalent), built-in SMS, HealthSherpa integration, one platform replaces 4-5 tools

BATTLE CARDS:
- vs EZLynx: Built for P&C not health. Zero ACA enrollment. $150+/user vs our flat fee. Win when they do ACA.
- vs HawkSoft: Desktop software, P&C only, no ACA. Win on cloud-native + ACA quoting.
- vs AgencyBloc: Strong on group but weak on individual ACA + Renewal Autopilot. Win on OEP automation.
- vs Agent CRM: Marketing tool only, zero quoting engine. We win on policy management + ACA.
- vs AgencyZoom: Sales pipeline only, no quoting or enrollment. Win on full-stack health platform.

BUYER PERSONAS:
- Solo Agent ($79): ACA-focused, replacing 4-5 tools, under $100/mo, one-call close
- Small Agency ($247): 2-9 agents, values white-label, team management
- Large Agency ($597): 10+ agents, enterprise mindset, performance tracking, renewal automation at scale

KEY OBJECTIONS & RESPONSES:
- "Happy with setup" → "What does your renewal process look like in November? Most agents we talk to spend 3-4 weeks manually contacting clients. Autopilot handles that automatically."
- "Too expensive" → "What are you paying for your current tools combined? Most agents replace 4-5 tools and come out ahead."
- "Send me info" → "I could, but honestly a 4-minute demo is worth more than any PDF. Are you free Thursday at 10?"
- "I use EZLynx" → "EZLynx is the best P&C rater in the industry. If you write ACA, you still need a separate enrollment tool. We replace that entirely."
${prospectCtx}${activityCtx}${pipeCtx}

YOUR JOB: Give specific, actionable, word-for-word guidance. Be direct. When asked for a script, write the full script. When asked about strategy, give the exact play. Reference the rep's actual data when relevant. Never be generic.`;
}

// ── Render the AI Assistant section ──────────────────────────
