  sidebar.style.cssText = 'width:260px;flex-shrink:0;background:#0f0f17;border-right:1px solid rgba(255,255,255,0.08);display:flex;flex-direction:column;overflow:hidden;';

  sidebar.innerHTML =
    // Header
    '<div style="padding:16px 14px 10px;">'
    +'<div style="font-size:13px;font-weight:800;color:#fff;margin-bottom:12px;display:flex;align-items:center;gap:8px;">'
    +'<span style="font-size:18px;">🤖</span>AI Assistant</div>'
    +'<button onclick="aiNewChat()" style="width:100%;background:rgba(99,102,241,0.2);border:1px solid rgba(99,102,241,0.4);border-radius:8px;padding:9px 12px;font-size:12px;font-weight:700;color:#c7d2fe;cursor:pointer;font-family:inherit;display:flex;align-items:center;gap:8px;">'
    +'<span style="font-size:14px;">+</span> New Chat</button>'
