    +anAdvField('Lead status', '<select id="af-status" style="'+anAdvInputStyle()+'"><option value="">Any</option>'+statusOpts+'</select>')
    +anAdvField('State', '<select id="af-state" style="'+anAdvInputStyle()+'">'+(typeof anBuildLeadStateOptions === 'function' ? anBuildLeadStateOptions(adv.state).replace('— Select state —', 'Any state') : '<option value="">Any state</option>')+'</select>')
    +anAdvField('Company contains', '<input id="af-company" type="text" placeholder="e.g. FHM" value="'+anEsc(adv.company)+'" style="'+anAdvInputStyle()+'">')
    +anAdvField('Company size', '<select id="af-size" style="'+anAdvInputStyle()+'"><option value="">Any size</option><option value="__none__"'+(adv.size==='__none__'?' selected':'')+'>No size set</option>'+AN_SIZES.map(function(s){ return '<option value="'+s.id+'"'+(adv.size===s.id?' selected':'')+'>'+s.label+'</option>'; }).join('')+'</select>')
    +anAdvField('Last activity', '<select id="af-last-act" style="'+anAdvInputStyle()+'"><option value="">Any</option><option value="today"'+(adv.lastActivity==='today'?' selected':'')+'>Active today</option><option value="7d"'+(adv.lastActivity==='7d'?' selected':'')+'>Last 7 days</option><option value="30d"'+(adv.lastActivity==='30d'?' selected':'')+'>Last 30 days</option><option value="never"'+(adv.lastActivity==='never'?' selected':'')+'>Never called</option><option value="stale30"'+(adv.lastActivity==='stale30'?' selected':'')+'>Inactive 30+ days</option><option value="stale90"'+(adv.lastActivity==='stale90'?' selected':'')+'>Inactive 90+ days</option></select>')
    +anAdvField('Title contains', '<input id="af-title" type="text" value="'+anEsc(adv.title)+'" style="'+anAdvInputStyle()+'">')
    +anAdvField('Source contains', '<input id="af-source" type="text" value="'+anEsc(adv.source)+'" style="'+anAdvInputStyle()+'">')
    +anAdvField('Has phone', '<select id="af-phone" style="'+anAdvInputStyle()+'"><option value="">Any</option><option value="yes"'+(adv.hasPhone==='yes'?' selected':'')+'>Yes</option><option value="no"'+(adv.hasPhone==='no'?' selected':'')+'>No</option></select>')
    +anAdvField('Has email', '<select id="af-email" style="'+anAdvInputStyle()+'"><option value="">Any</option><option value="yes"'+(adv.hasEmail==='yes'?' selected':'')+'>Yes</option><option value="no"'+(adv.hasEmail==='no'?' selected':'')+'>No</option></select>')
    +anAdvField('Created after', '<input id="af-created-after" type="date" value="'+anEsc(adv.createdAfter)+'" style="'+anAdvInputStyle()+'">')
    +anAdvField('Created before', '<input id="af-created-before" type="date" value="'+anEsc(adv.createdBefore)+'" style="'+anAdvInputStyle()+'">')
    +anAdvField('Last activity after', '<input id="af-act-after" type="date" value="'+anEsc(adv.lastActivityAfter)+'" style="'+anAdvInputStyle()+'">')
    +anAdvField('Last activity before', '<input id="af-act-before" type="date" value="'+anEsc(adv.lastActivityBefore)+'" style="'+anAdvInputStyle()+'">')
    +'</div>'
    +'<div style="display:flex;gap:12px;margin-top:12px;flex-wrap:wrap;">'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-secondary);cursor:pointer;"><input type="checkbox" id="af-followup"'+(adv.followUpDue?' checked':'')+'> Follow-up due today or earlier</label>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-secondary);cursor:pointer;"><input type="checkbox" id="af-never-called"'+(adv.neverCalled?' checked':'')+'> Never called</label>'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-top:18px;">'
    +'<button type="button" onclick="anApplyAdvancedFiltersFromModal()" style="flex:1;background:#6366f1;color:#fff;border:none;border-radius:8px;padding:10px;font-size:13px;font-weight:700;cursor:pointer;font-family:var(--sans);">Apply filters</button>'
    +'<button type="button" onclick="anOpenSaveContactListModal()" style="flex:1;background:var(--body-bg);color:var(--text-secondary);border:1.5px solid var(--divider);border-radius:8px;padding:10px;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);">Save as list</button>'
    +'<button type="button" onclick="document.getElementById(\'an-adv-filter-modal\').remove()" style="padding:10px 14px;background:transparent;border:1px solid var(--divider);border-radius:8px;font-size:13px;cursor:pointer;font-family:var(--sans);color:var(--text-muted);">Cancel</button>'
    +'</div></div>';
  modal.onclick = function(e){ if(e.target===modal) modal.remove(); };
  document.body.appendChild(modal);
