function anAdvInputStyle(){ return 'width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:8px 10px;font-size:12px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;box-sizing:border-box;'; }
function anAdvField(label, input){ return '<div><label style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:var(--text-muted);display:block;margin-bottom:4px;">'+label+'</label>'+input+'</div>'; }

window.anApplyAdvancedFiltersFromModal = function(){
  var owner = (document.getElementById('af-owner')||{}).value || '';
  AN.advancedFilters = {
    owner: owner === '__mine__' ? '' : owner,
    status: (document.getElementById('af-status')||{}).value || '',
    state: typeof anNormalizeLeadStateValue === 'function' ? anNormalizeLeadStateValue((document.getElementById('af-state')||{}).value || '') : ((document.getElementById('af-state')||{}).value || ''),
    company: (document.getElementById('af-company')||{}).value || '',
    size: (document.getElementById('af-size')||{}).value || '',
    lastActivity: (document.getElementById('af-last-act')||{}).value || '',
    source: (document.getElementById('af-source')||{}).value || '',
    title: (document.getElementById('af-title')||{}).value || '',
    hasPhone: (document.getElementById('af-phone')||{}).value || '',
    hasEmail: (document.getElementById('af-email')||{}).value || '',
    followUpDue: !!(document.getElementById('af-followup')||{}).checked,
    neverCalled: !!(document.getElementById('af-never-called')||{}).checked,
    createdAfter: (document.getElementById('af-created-after')||{}).value || '',
    createdBefore: (document.getElementById('af-created-before')||{}).value || '',
    lastActivityAfter: (document.getElementById('af-act-after')||{}).value || '',
    lastActivityBefore: (document.getElementById('af-act-before')||{}).value || ''
  };
  if(owner === '__mine__') AN.repFilter = '__mine__';
  else if(owner && owner !== '__none__') AN.repFilter = owner;
  else if(owner !== '__none__') AN.repFilter = '';
  if(AN.advancedFilters.status) AN.currentFilter = AN.advancedFilters.status;
  var modal = document.getElementById('an-adv-filter-modal');
  if(modal) modal.remove();
  anOnFilterChanged();
};

window.anOpenSaveContactListModal = function(){
  var name = prompt('Name this contact list:', '');
  if(!name || !name.trim()) return;
  var custom = [];
  try { custom = JSON.parse(localStorage.getItem(AN_LISTS_KEY) || '[]'); } catch(e){}
  if(!Array.isArray(custom)) custom = [];
  var id = 'list-' + Date.now();
  custom.push({ id:id, name:name.trim(), isSystem:false, filters:anCaptureListFilters() });
  anSaveCustomContactLists(custom);
  AN.activeListId = id;
  if(typeof showToast === 'function') showToast('List saved: ' + name.trim());
  anRefreshContactListUI();
};

window.anDeleteContactList = function(id){
  if(!confirm('Delete this contact list?')) return;
  var custom = [];
  try { custom = JSON.parse(localStorage.getItem(AN_LISTS_KEY) || '[]'); } catch(e){}
  custom = custom.filter(function(l){ return l.id !== id; });
  anSaveCustomContactLists(custom);
  if(AN.activeListId === id) anApplyContactList('sys-all');
  else anRefreshContactListUI();
};

// ── Rep vs admin lead visibility ──────────────────────────────
// A plain lead/prospect has one owner (_repEmail). A deal can involve two people —
// the SDR who sourced it and the AE who's running it — and both should see it on
// their own account/device, not just whichever one happens to be the "primary" owner.
window.anLeadVisibleEmails = function(lead) {
  var emails = [];
  if (!lead) return emails;
  var add = function(e) { e = (e || '').toLowerCase().trim(); if (e && emails.indexOf(e) < 0) emails.push(e); };
  add(lead._repEmail);
  if (lead.isOpportunity) {
    add(lead.sdrEmail);
    add(lead.aeEmail);
  }
  return emails;
};

window.anRepOwnsLead = function(lead) {
  if (!lead || typeof AN === 'undefined') return false;
  if (AN.isAdmin) return true;
  var myEmail = (AN.currentRepEmail || '').toLowerCase();
  if (!myEmail) return false;
  return anLeadVisibleEmails(lead).indexOf(myEmail) >= 0;
};

window.anFilterLeadsForCurrentRep = function(leads) {
  if (typeof AN !== 'undefined' && AN.isAdmin) return leads || [];
  var myEmail = (AN.currentRepEmail || '').toLowerCase();
  return (leads || []).filter(function(l) {
    var visible = anLeadVisibleEmails(l);
    // Legacy leads with no owner stamped at all: if it's in this rep's own local/cloud data,
    // it belongs to them — stamp it now rather than silently dropping it.
    if (!visible.length) {
      if (l) l._repEmail = myEmail;
      return true;
    }
    return visible.indexOf(myEmail) >= 0;
  });
};

window.anEnforceRepLeadScope = function() {
  if (typeof AN === 'undefined' || AN.isAdmin || !Array.isArray(AN.leads)) return;
  AN.leads = anFilterLeadsForCurrentRep(AN.leads);
  if (typeof AN.invalidateLeadCaches === 'function') AN.invalidateLeadCaches();
};

// ── Filter leads ──────────────────────────────────────────────
AN.filtered = function(){
  var patchN = 0;
  try { patchN = Object.keys(anGetOwnerPatches()).length; } catch(e){}
  var advKey = '';
  try { advKey = JSON.stringify(AN.advancedFilters || {}); } catch(e){}
  var cacheKey = (AN.activeListId||'')+'|'+(AN.searchQ||'')+'|'+(AN.currentFilter||'')+'|'+(AN.repFilter||'')+'|'+AN.leads.length+'|'+patchN+'|'+advKey+'|'+(AN.sortField||'')+'|'+(AN.sortDir||'');
  if(AN._filteredCache && AN._filteredCache.key === cacheKey) return AN._filteredCache.list.slice();
  var q = (AN.searchQ || '').toLowerCase();
  var adv = AN.advancedFilters || {};
  var demoFilterActive = AN.currentFilter === 'demo' || AN.currentFilter === 'booked_demo';
  var list = AN.leads.filter(function(l){
    if (!demoFilterActive && !q && !anIsProspect(l)) return false;
    if(!AN.isAdmin && !anRepOwnsLead(l)) return false;
    var leadOwner = (l._repEmail || '').toLowerCase();
    if(AN.isAdmin && AN.repFilter === '__mine__'){
      var myEmail = (AN.currentRepEmail || '').toLowerCase();
      if(leadOwner !== myEmail) return false;
    } else if(AN.isAdmin && AN.repFilter && leadOwner !== AN.repFilter.toLowerCase()) return false;
    if(adv.status){
      if((l.status||'new') !== adv.status) return false;
    } else if(AN.currentFilter==='hot') {
      if(['new','contacted','followup','emailed'].indexOf(l.status||'new') < 0) return false;
    } else if(demoFilterActive) {
      if (typeof anLeadMatchesBookedDemoFilter === 'function') {
        if (!anLeadMatchesBookedDemoFilter(l)) return false;
      } else if (l.status !== 'booked_demo') return false;
    } else if(AN.currentFilter==='followup') {
      if(!l.nextFollowUp) return false;
    } else if(AN.currentFilter!=='all' && l.status!==AN.currentFilter) return false;
    if(!anMatchesAdvancedFilters(l, adv)) return false;
    if(q){
      var fullName = ((l.firstName||'') + ' ' + (l.lastName||'')).trim().toLowerCase().replace(/\s+/g,' ');
      var hay = (fullName+' '+( l.company||'')+' '+(l.email||'')+' '+(l.phone||'')+' '+(l.state||'')+' '+(l.title||'')+' '+(l.source||'')+' '+(l.notes||'')).toLowerCase();
      var qDigits = q.replace(/\D/g,'');
      var phoneDigits = anDigitsPhone(l.phone);
      if(!hay.includes(q) && !(qDigits && phoneDigits && phoneDigits.includes(qDigits))) return false;
    }
    return true;
  });
  var sortField = AN.sortField || 'created';
  list.sort(function(a,b){
    var av, bv;
    if(sortField === 'lastContactDate'){
      av = anLeadLastActivityDate(a); bv = anLeadLastActivityDate(b);
    } else {
      av = (a[sortField]||'').toString(); bv = (b[sortField]||'').toString();
    }
    return AN.sortDir==='asc'?av.localeCompare(bv):bv.localeCompare(av);
  });
  AN._filteredCache = { key: cacheKey, list: list };
  return list.slice();
};

// ── RENDER MAIN CRM PAGE ──────────────────────────────────────
window.renderCRM = function(){
  var sec = document.getElementById('section-crm');
  if(!sec) return;

  if(AN.leadsReady && document.getElementById('crm-content')){
    renderLeadsTable();
    if(typeof anUpdateBulkBar === 'function') anUpdateBulkBar();
    return;
  }

  sec.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:60vh;">'
    +'<div style="text-align:center"><div class="loading-spinner" style="margin:0 auto 12px;"></div>'
    +'<div style="font-size:13px;color:var(--text-muted);">'+(AN.leadsLoading ? 'Loading '+((AN.leads&&AN.leads.length)||0).toLocaleString()+' leads...' : 'Loading CRM...')+'</div></div></div>';

  if (AN._crmLoadWatchdog) clearTimeout(AN._crmLoadWatchdog);
  AN._crmLoadWatchdog = setTimeout(function() {
    AN._crmLoadWatchdog = null;
    if (!document.getElementById('crm-content')) {
      AN.leadsLoading = false;
      AN.leadsReady = true;
      AN.leads = AN.leads || [];
      try { renderCRM(); } catch(e) {}
    }
  }, 12000);

  AN.load(function(){
    if (AN._crmLoadWatchdog) { clearTimeout(AN._crmLoadWatchdog); AN._crmLoadWatchdog = null; }
    anEnforceRepLeadScope();
    try { var ps = localStorage.getItem('an-crm-page-size'); if(ps) AN.pageSize = Math.min(1000, Math.max(25, parseInt(ps, 10) || 100)); } catch(e){}
    try { AN.activeListId = localStorage.getItem('an-crm-active-list') || AN.activeListId || 'sys-all'; } catch(e){ AN.activeListId = AN.activeListId || 'sys-all'; }
    if (!AN.isAdmin) {
      if (!AN.activeListId || AN.activeListId === 'sys-all' || AN.activeListId === 'sys-no-owner') {
        AN.activeListId = 'sys-mine';
        try { localStorage.setItem('an-crm-active-list', 'sys-mine'); } catch(e){}
      }
    }
    if(!anGetContactListById(AN.activeListId)) AN.activeListId = AN.isAdmin ? 'sys-all' : 'sys-mine';
    var activeList = anGetContactListById(AN.activeListId);
    if(activeList) anApplyListFiltersToState(activeList.filters);
    sec.innerHTML = buildCRMShell();
    anBindCRMEvents();
    if(typeof anRefreshFilterChips === 'function') anRefreshFilterChips();
    if(typeof anRefreshCRMStatsBar === 'function') anRefreshCRMStatsBar();
    if(typeof anRefreshRepCounts === 'function') anRefreshRepCounts();
    renderLeadsTable();
    if(typeof anUpdateBulkBar === 'function') anUpdateBulkBar();
  });
};

function buildCRMShell(){
  var statCounts = {};
  AN_LEAD_STATUSES.forEach(function(s){ statCounts[s.id]=0; });
  var statPool = AN.isAdmin ? AN.leads : (typeof anFilterLeadsForCurrentRep === 'function' ? anFilterLeadsForCurrentRep(AN.leads) : AN.leads);
  statPool.forEach(function(l){
    if (!anIsProspect(l)) return;
    if ((l.status || '') === 'booked_demo') return;
    if (statCounts[l.status] !== undefined) statCounts[l.status]++;
  });
  statCounts.booked_demo = (typeof anRepScopedLeads === 'function' ? anRepScopedLeads() : statPool).filter(function(l) {
    return typeof anLeadMatchesBookedDemoFilter === 'function' && anLeadMatchesBookedDemoFilter(l);
  }).length;
  var shellDemosToday = typeof anCountBookedDemosToday === 'function' ? anCountBookedDemosToday(typeof anRepScopedLeads === 'function' ? anRepScopedLeads() : AN.leads) : 0;

  // Stats bar
  var statsHTML = AN_LEAD_STATUSES.map(function(s){
    var filterId = s.id === 'booked_demo' ? 'demo' : s.id;
    var sub = (s.id === 'booked_demo' && shellDemosToday > 0) ? '<div style="font-size:9px;font-weight:600;color:var(--text-muted);margin-top:2px;">'+shellDemosToday+' booked today</div>' : '';
    return '<div onclick="AN.currentFilter=\''+filterId+'\';if(AN.advancedFilters)AN.advancedFilters.status=\'\';anOnFilterChanged();" style="padding:12px 16px;cursor:pointer;border-right:1px solid var(--divider);flex:1;min-width:0;transition:background 0.15s;" onmouseover="this.style.background=\'var(--body-bg)\'" onmouseout="this.style.background=\'transparent\'">'
      +'<div style="display:flex;align-items:center;gap:5px;margin-bottom:4px;">'
      +'<span style="width:7px;height:7px;border-radius:50%;background:'+s.dot+';flex-shrink:0;"></span>'
      +'<span style="font-size:10px;font-weight:700;color:'+s.color+';text-transform:uppercase;letter-spacing:0.1em;white-space:nowrap;">'+s.label+'</span>'
      +'</div>'
      +'<div style="font-size:22px;font-weight:900;color:var(--text-primary);letter-spacing:-1px;line-height:1;">'+statCounts[s.id]+'</div>'
      +sub
      +'</div>';
  }).join('');

  // Filters
  var filterBtns = [
    {id:'all',label:'All Leads'},
    {id:'hot',label:'🔥 Hot'},
    {id:'demo',label:'Booked Demo'},
    {id:'won',label:'Won'},
    {id:'followup',label:'📅 Follow Up'}
  ].map(function(f){
    var active = AN.currentFilter===f.id;
    return '<button onclick="AN.currentFilter=\''+f.id+'\';anOnFilterChanged();" '
      +'style="padding:5px 13px;border-radius:20px;border:1.5px solid '+(active?'#6366f1':'var(--divider)')+';background:'+(active?'rgba(99,102,241,0.1)':'transparent')+';color:'+(active?'#6366f1':'var(--text-secondary)')+';font-size:12.5px;font-weight:'+(active?'700':'500')+';cursor:pointer;font-family:var(--sans);white-space:nowrap;">'+f.label+'</button>';
  }).join('');

  // Rep filter (admin only)
  var repFilterHTML = '';
  if(AN.isAdmin){
    var reps = [];
    AN.leads.forEach(function(l){ if(l._repEmail&&reps.indexOf(l._repEmail)<0) reps.push(l._repEmail); });
    if(reps.length){
      repFilterHTML = '<div id="crm-rep-bar" style="display:flex;align-items:center;gap:6px;padding:8px 16px;border-top:1px solid var(--divider);overflow-x:auto;">'
        +'<span style="font-size:10px;font-weight:700;font-family:var(--mono);letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);white-space:nowrap;margin-right:4px;">Rep:</span>'
        +'<button onclick="AN.repFilter=\'\';anResetLeadsPage();renderLeadsTable()" style="padding:3px 10px;border-radius:20px;border:1.5px solid '+(AN.repFilter===''?'#6366f1':'var(--divider)')+';background:'+(AN.repFilter===''?'rgba(99,102,241,0.1)':'transparent')+';color:'+(AN.repFilter===''?'#6366f1':'var(--text-secondary)')+';font-size:11.5px;font-weight:600;cursor:pointer;font-family:var(--sans);white-space:nowrap;">All</button>'
        +reps.map(function(email){
          var name=typeof anGetRepName==='function'?anGetRepName(email):email.split('@')[0], col=anColor(email), cnt=AN.leads.filter(function(l){return l._repEmail===email;}).length;
          var active=AN.repFilter===email;
          return '<button onclick="AN.repFilter=\''+email+'\';anResetLeadsPage();renderLeadsTable()" style="padding:3px 10px;border-radius:20px;border:1.5px solid '+(active?col:'var(--divider)')+';background:'+(active?col+'1a':'transparent')+';color:'+(active?col:'var(--text-secondary)')+';font-size:11.5px;font-weight:600;cursor:pointer;font-family:var(--sans);white-space:nowrap;display:flex;align-items:center;gap:5px;">'
            +'<span style="width:6px;height:6px;border-radius:50%;background:'+col+';"></span>'+name+' ('+cnt+')</button>';
        }).join('')
        +'</div>';
    }
  }

  return '<div style="display:flex;flex-direction:column;height:calc(100vh - 60px);overflow:hidden;">'

    // Header
    +'<div style="padding:16px 28px 12px;background:var(--card-bg);border-bottom:1px solid var(--divider);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;flex-wrap:wrap;gap:10px;">'
    +'<div><div style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.18em;text-transform:uppercase;color:#6366f1;margin-bottom:3px;">AgentNav</div>'
    +'<h1 style="font-size:22px;font-weight:900;letter-spacing:-0.5px;color:var(--text-primary);margin:0;">Lead Pipeline</h1></div>'
    +'<div style="display:flex;gap:8px;align-items:center;">'
    +'<div style="position:relative;">'
    +'<input id="crm-search" type="text" placeholder="Search contacts..." value="'+anEsc(AN.searchQ)+'" oninput="AN.searchQ=this.value;anOnFilterChanged()" '
    +'style="padding:8px 12px 8px 32px;border:1.5px solid var(--divider);border-radius:8px;font-size:13px;color:var(--text-primary);background:var(--card-bg);outline:none;width:200px;font-family:var(--sans);" '
    +'onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'">'
    +'<span style="position:absolute;left:10px;top:50%;transform:translateY(-50%);font-size:13px;pointer-events:none;color:var(--text-muted);">🔍</span>'
    +'</div>'
    +'<button onclick="anOpenCallSessionSetup()" style="display:flex;align-items:center;gap:6px;padding:8px 14px;border:1.5px solid #a7f3d0;border-radius:8px;font-size:13px;font-weight:700;color:#10b981;background:#ecfdf5;cursor:pointer;font-family:var(--sans);">📞 Lead Session</button>'
    +'<button onclick="anOpenBulkEmail()" style="display:flex;align-items:center;gap:6px;padding:8px 14px;border:1.5px solid #ddd6fe;border-radius:8px;font-size:13px;font-weight:700;color:#8b5cf6;background:#f5f3ff;cursor:pointer;font-family:var(--sans);">📧 Bulk Email</button>'
    +'<button onclick="anOpenImport()" style="display:flex;align-items:center;gap:6px;padding:8px 14px;border:1.5px solid var(--divider);border-radius:8px;font-size:13px;font-weight:600;color:var(--text-secondary);background:var(--card-bg);cursor:pointer;font-family:var(--sans);">📂 Import CSV</button>'
    +'<button onclick="anOpenFixFromCSV()" style="display:flex;align-items:center;gap:6px;padding:8px 14px;border:1.5px solid #fde68a;border-radius:8px;font-size:13px;font-weight:600;color:#b45309;background:#fffbeb;cursor:pointer;font-family:var(--sans);">🔧 Fix from CSV</button>'
    +'<button onclick="anNewLead()" style="display:flex;align-items:center;gap:6px;padding:8px 16px;border:none;border-radius:8px;font-size:13px;font-weight:700;color:#fff;background:#6366f1;cursor:pointer;font-family:var(--sans);box-shadow:0 2px 8px rgba(99,102,241,0.3);">+ Add Lead</button>'
    +'</div></div>'

    // Contact list tabs (saved views)
    + (typeof anBuildContactListTabs === 'function' ? anBuildContactListTabs() : '')

    // Sort + advanced filter toolbar
    + (typeof anBuildContactFilterBar === 'function' ? anBuildContactFilterBar() : '')

    // Stats
    +'<div id="crm-stats-bar" style="display:flex;background:var(--card-bg);border-bottom:1px solid var(--divider);flex-shrink:0;overflow-x:auto;">'+statsHTML+'</div>'

    // Rep filter (admin)
    + repFilterHTML

    // Filter + view toggle bar
    +'<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 16px;background:var(--body-bg);border-bottom:1px solid var(--divider);flex-shrink:0;gap:10px;flex-wrap:wrap;">'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap;">'+filterBtns+'</div>'
    +'<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">'
    +'<div style="display:flex;background:var(--card-bg);border:1.5px solid var(--divider);border-radius:8px;padding:2px;gap:1px;">'
    +'<button onclick="AN.currentView=\'list\';renderLeadsTable()" id="crm-view-list" style="padding:4px 10px;border-radius:6px;border:none;font-size:12px;cursor:pointer;font-family:var(--sans);background:'+(AN.currentView==='list'?'#6366f1':'transparent')+';color:'+(AN.currentView==='list'?'#fff':'var(--text-muted)')+';">☰ List</button>'
    +'<button onclick="AN.currentView=\'kanban\';renderLeadsTable()" id="crm-view-kanban" style="padding:4px 10px;border-radius:6px;border:none;font-size:12px;cursor:pointer;font-family:var(--sans);background:'+(AN.currentView==='kanban'?'#6366f1':'transparent')+';color:'+(AN.currentView==='kanban'?'#fff':'var(--text-muted)')+';">⬛ Board</button>'
    +'</div>'
    +'<button id="crm-bulk-call" onclick="anStartCallSessionFromSelected()" style="display:'+(AN.selectedIds.length?'inline-flex':'none')+';align-items:center;gap:5px;padding:5px 12px;border-radius:7px;border:1.5px solid #a7f3d0;background:#ecfdf5;color:#10b981;font-size:12px;font-weight:700;cursor:pointer;font-family:var(--sans);">📞 Call Selected ('+AN.selectedIds.length+')</button>'
    +'<button id="crm-bulk-seq" onclick="anEnrollSelectedInSequence()" style="display:'+(AN.selectedIds.length?'inline-flex':'none')+';align-items:center;gap:5px;padding:5px 12px;border-radius:7px;border:1.5px solid #c4b5fd;background:#f5f3ff;color:#7c3aed;font-size:12px;font-weight:700;cursor:pointer;font-family:var(--sans);">📨 Enroll in Sequence ('+AN.selectedIds.length+')</button>'
    +'<button id="crm-bulk-owner" onclick="anBulkReassignOwner()" style="display:'+(AN.selectedIds.length?'inline-flex':'none')+';align-items:center;gap:5px;padding:5px 12px;border-radius:7px;border:1.5px solid #fde68a;background:#fffbeb;color:#b45309;font-size:12px;font-weight:700;cursor:pointer;font-family:var(--sans);">👤 Assign Owner ('+AN.selectedIds.length+')</button>'
    +'<button id="crm-bulk-delete" onclick="anDeleteSelected()" style="display:'+(AN.selectedIds.length?'inline-flex':'none')+';align-items:center;gap:5px;padding:5px 12px;border-radius:7px;border:1.5px solid #fca5a5;background:#fef2f2;color:#ef4444;font-size:12px;font-weight:700;cursor:pointer;font-family:var(--sans);">🗑 Delete ('+AN.selectedIds.length.toLocaleString()+')</button>'
    +'<button id="crm-bulk-clear" onclick="anClearSelection()" style="display:'+(AN.selectedIds.length?'inline-flex':'none')+';align-items:center;gap:5px;padding:5px 12px;border-radius:7px;border:1.5px solid var(--divider);background:var(--card-bg);color:var(--text-secondary);font-size:12px;font-weight:600;cursor:pointer;font-family:var(--sans);">✕ Clear</button>'
    +'<span id="crm-count" style="font-size:12px;color:var(--text-muted);"></span>'
    +'</div></div>'

    // Table/Board
    +'<div id="crm-content" style="flex:1;overflow:auto;"></div>'
    +'</div>';
}

function anResetLeadsPage(){
  AN.listPage = 0;
}

function anLeadsPageSlice(list){
  var pageSize = AN.pageSize || 100;
  var totalPages = Math.max(1, Math.ceil(list.length / pageSize));
  if(AN.listPage >= totalPages) AN.listPage = totalPages - 1;
  if(AN.listPage < 0) AN.listPage = 0;
  var start = AN.listPage * pageSize;
  return { pageList: list.slice(start, start + pageSize), totalPages: totalPages, start: start };
}

function anSetLeadsPageSize(n){
  n = parseInt(n, 10);
  if(isNaN(n) || n < 25) n = 100;
  if(n > 1000) n = 1000;
  AN.pageSize = n;
  try { localStorage.setItem('an-crm-page-size', String(n)); } catch(e){}
  anResetLeadsPage();
  renderLeadsTable();
}

window.anGoToLeadsPage = function(pageNum, totalPages){
  pageNum = parseInt(pageNum, 10);
  totalPages = parseInt(totalPages, 10) || 1;
  if(isNaN(pageNum) || pageNum < 1) pageNum = 1;
  if(pageNum > totalPages) pageNum = totalPages;
  AN.listPage = pageNum - 1;
  renderLeadsTable();
  var inp = document.getElementById('crm-page-input');
  if(inp) inp.value = pageNum;
};

function anRenderLeadsPagination(list, totalPages, start){
  var pageSize = AN.pageSize || 100;
  var end = Math.min(start + pageSize, list.length);
  var pageOpts = [100, 250, 500, 1000].map(function(n){
    return '<option value="'+n+'"'+(pageSize===n?' selected':'')+'>'+n+'</option>';
  }).join('');
  var pagNav = list.length <= pageSize ? '' :
    '<div style="display:flex;gap:6px;align-items:center;">'
    +'<button onclick="AN.listPage=0;renderLeadsTable()" '+(AN.listPage<=0?'disabled':'')+' style="padding:5px 10px;border-radius:6px;border:1px solid var(--divider);background:var(--body-bg);font-size:11px;font-weight:600;cursor:pointer;">First</button>'
    +'<button onclick="AN.listPage=Math.max(0,AN.listPage-1);renderLeadsTable()" '+(AN.listPage<=0?'disabled':'')+' style="padding:5px 10px;border-radius:6px;border:1px solid var(--divider);background:var(--body-bg);font-size:11px;font-weight:600;cursor:pointer;">Prev</button>'
    +'<label style="display:flex;align-items:center;gap:5px;font-size:12px;font-weight:700;color:var(--text-secondary);white-space:nowrap;">Page'
    +'<input id="crm-page-input" type="number" min="1" max="'+totalPages+'" value="'+(AN.listPage+1)+'" title="Type a page number and press Enter" '
    +'onkeydown="if(event.key===\'Enter\'){event.preventDefault();anGoToLeadsPage(this.value,'+totalPages+');}" '
    +'onchange="anGoToLeadsPage(this.value,'+totalPages+')" '
    +'style="width:56px;border:1px solid var(--divider);border-radius:6px;padding:4px 6px;font-size:11px;font-weight:700;text-align:center;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;" '
    +'onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'">'
    +' / '+totalPages.toLocaleString()+'</label>'
    +'<button onclick="AN.listPage=Math.min('+(totalPages-1)+',AN.listPage+1);renderLeadsTable()" '+(AN.listPage>=totalPages-1?'disabled':'')+' style="padding:5px 10px;border-radius:6px;border:1px solid var(--divider);background:var(--body-bg);font-size:11px;font-weight:600;cursor:pointer;">Next</button>'
    +'<button onclick="AN.listPage='+(totalPages-1)+';renderLeadsTable()" '+(AN.listPage>=totalPages-1?'disabled':'')+' style="padding:5px 10px;border-radius:6px;border:1px solid var(--divider);background:var(--body-bg);font-size:11px;font-weight:600;cursor:pointer;">Last</button>'
    +'</div>';
  return '<div id="crm-pagination" style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px 10px 14px;padding-right:max(14px,min(42vw,170px));border-top:1px solid var(--divider);background:var(--card-bg);flex-shrink:0;gap:10px;flex-wrap:wrap;">'
    +'<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">'
    +'<div style="font-size:12px;color:var(--text-muted);">Showing '+(start+1).toLocaleString()+'–'+end.toLocaleString()+' of '+list.length.toLocaleString()+'</div>'
    +'<label style="font-size:11px;color:var(--text-muted);display:flex;align-items:center;gap:6px;">Per page <select onchange="anSetLeadsPageSize(this.value)" style="border:1px solid var(--divider);border-radius:6px;padding:4px 8px;font-size:11px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);">'+pageOpts+'</select></label>'
    +'</div>'
    + pagNav
    +'</div>';
}

function renderLeadsTable(){
  try {
  if(typeof anSanitizeSelection === 'function') anSanitizeSelection();
  var list = AN.filtered();
  var el = document.getElementById('crm-content');
  var countEl = document.getElementById('crm-count');
  if(countEl){
    var totalProspects = AN.leads.filter(anIsProspect).length;
    if(typeof anHasActiveCRMFilters === 'function' && anHasActiveCRMFilters()){
      countEl.textContent = list.length.toLocaleString()+' filtered · '+totalProspects.toLocaleString()+' total';
    } else {
      countEl.textContent = list.length.toLocaleString()+' of '+totalProspects.toLocaleString();
    }
  }
  if(typeof anRefreshContactListUI === 'function' && document.getElementById('crm-list-tabs')){
    clearTimeout(window._anListTabTimer);
    window._anListTabTimer = setTimeout(function(){
      anRefreshContactListUI();
      if(typeof anRefreshTransferFilteredBtn === 'function') anRefreshTransferFilteredBtn();
    }, 250);
  }
  if(!el) return;

  if(AN.currentView==='kanban'){
    el.innerHTML = buildKanban(list);
    return;
  }

  if(!list.length){
    var notSignedIn = (typeof _currentUser === 'undefined' || !_currentUser);
    var sbMissing = (typeof getSupabase === 'function' && !getSupabase());
    el.innerHTML = '<div style="text-align:center;padding:64px 20px;">'
      +'<div style="font-size:48px;margin-bottom:14px;">👥</div>'
      +'<div style="font-size:16px;font-weight:700;color:var(--text-primary);margin-bottom:6px;">No leads found</div>'
      +(notSignedIn
        ? '<div style="font-size:13px;color:var(--text-muted);margin-bottom:20px;max-width:420px;margin-left:auto;margin-right:auto;line-height:1.55;">Your leads are saved in the cloud. <strong>Sign in</strong> (bottom of sidebar) to load them on this device.</div>'
          +'<button onclick="openAuthModal()" style="padding:10px 20px;border-radius:8px;border:none;background:#6366f1;font-size:13px;font-weight:700;color:#fff;cursor:pointer;font-family:var(--sans);margin-bottom:16px;">Sign In to Load Leads</button>'
        : sbMissing
          ? '<div style="font-size:13px;color:#b45309;margin-bottom:20px;max-width:420px;margin-left:auto;margin-right:auto;line-height:1.55;">Supabase is not connected. Add <strong>SUPABASE_ANON_KEY</strong> in Netlify environment variables, then redeploy.</div>'
          : '<div style="font-size:13px;color:var(--text-muted);margin-bottom:20px;">Try adjusting your filters, switch to <strong>All contacts</strong>, or import from CSV</div>')
      +'<div style="display:flex;gap:10px;justify-content:center;">'
      +'<button onclick="anOpenImport()" style="padding:9px 16px;border-radius:8px;border:1.5px solid var(--divider);background:var(--card-bg);font-size:13px;font-weight:600;color:var(--text-secondary);cursor:pointer;font-family:var(--sans);">📂 Import CSV</button>'
      +'<button onclick="anNewLead()" style="padding:9px 16px;border-radius:8px;border:none;background:#6366f1;font-size:13px;font-weight:700;color:#fff;cursor:pointer;font-family:var(--sans);">+ Add Lead</button>'
      +'</div></div>';
    return;
  }

  var th = function(label, field){
    var active = AN.sortField===field;
    return '<th onclick="AN.sortField=\''+field+'\';AN.sortDir=AN.sortDir===\'asc\'?\'desc\':\'asc\';renderLeadsTable();" '
      +'style="padding:9px 12px;text-align:left;font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:'+(active?'#6366f1':'var(--text-muted)')+';cursor:pointer;white-space:nowrap;user-select:none;border-bottom:2px solid var(--divider);">'
      +label+(active?(AN.sortDir==='asc'?' ↑':' ↓'):'')+'</th>';
  };

  var pageInfo = anLeadsPageSlice(list);
  var pageList = pageInfo.pageList;
  var rows = pageList.map(function(lead, i){
    var rowIndex = pageInfo.start + i;
    var st = anStatus(lead.status||'new');
    var sz = anSize(lead.size||'');
    var calls = (lead.callLog||[]).length;
    var repEmail = lead._repEmail||'';
    var repName  = typeof anGetRepName==='function'?anGetRepName(repEmail):(repEmail?repEmail.split('@')[0]:'');
    var repCol   = anColor(repEmail);
    var today    = new Date().toISOString().split('T')[0];
    var fuDue    = lead.nextFollowUp && lead.nextFollowUp <= today;
    var rowBg    = rowIndex%2===0?'transparent':'rgba(0,0,0,0.012)';

    var isOppRow = typeof anIsOpportunityRecord === 'function' && anIsOpportunityRecord(lead);
    var rowOpen = isOppRow
      ? 'anOpenTrackerDealRef(\'opp\',\''+lead.id+'\')'
      : 'anOpenLead(\''+lead.id+'\')';
    var demoBadge = (lead.demoDate ? '<div style="font-size:10px;color:#10b981;margin-top:2px;">🎯 '+anEsc(lead.demoDate)+(lead.demoTime ? ' '+lead.demoTime : '')+(isOppRow ? ' · Deal' : '')+'</div>' : (isOppRow ? '<div style="font-size:10px;color:#6366f1;margin-top:2px;">💎 Converted to deal</div>' : ''));
    return '<tr data-lead-id="'+lead.id+'" style="border-bottom:1px solid var(--divider);background:'+rowBg+';cursor:pointer;" '
      +'onclick="'+rowOpen+'" '
      +'onmouseover="this.style.background=\'rgba(99,102,241,0.04)\'" onmouseout="this.style.background=\''+rowBg+'\'">'
      +'<td style="padding:10px 12px;" onclick="event.stopPropagation()"><input type="checkbox" class="lead-cb" data-id="'+lead.id+'"'+(AN.selectedIds.indexOf(lead.id)>=0?' checked':'')+' onchange="anToggleSelect(\''+lead.id+'\',this.checked)" style="width:14px;height:14px;accent-color:#6366f1;cursor:pointer;"></td>'
      +'<td style="padding:10px 12px;min-width:140px;" title="Double-click to edit name">'
      +'<div style="font-size:13.5px;font-weight:700;color:var(--text-primary);">'+anEsc((lead.firstName||'')+' '+(lead.lastName||''))+'</div>'
      +(lead.title?'<div style="font-size:11px;color:var(--text-muted);">'+anEsc(lead.title)+'</div>':'')
      +(lead.email?'<div style="font-size:11.5px;color:var(--text-muted);">'+anEsc(lead.email)+'</div>':'')
      +demoBadge
      +'</td>'
      +'<td data-field="company" style="padding:10px 12px;font-size:13px;color:var(--text-secondary);cursor:text;" title="Click to edit">'+anEsc(lead.company||'—')+'</td>'
      +'<td data-field="state" style="padding:10px 12px;font-size:13px;color:var(--text-secondary);cursor:text;" title="Click to edit">'+anEsc((typeof anResolveLeadState==='function'?anResolveLeadState(lead):lead.state)||'—')+'</td>'
      +'<td data-field="size" style="padding:10px 12px;cursor:text;" title="Click to edit">'+(lead.size?'<span style="background:var(--body-bg);border:1px solid var(--divider);border-radius:5px;padding:2px 8px;font-size:11.5px;font-weight:600;color:var(--text-secondary);">'+anEsc(sz.label)+'</span>':'<span style="color:var(--text-muted);font-size:12px;">—</span>')+'</td>'
      +'<td data-field="phone" style="padding:10px 12px;cursor:text;" title="Click to edit"><a href="tel:'+anEsc(anTelPhone(lead.phone)||'')+'" onclick="event.stopPropagation()" style="color:var(--text-secondary);text-decoration:none;font-size:13px;">'+anEsc(anPhoneDisplay(lead.phone))+'</a></td>'
      +'<td data-field="status" onclick="event.stopPropagation()" style="padding:10px 12px;cursor:text;" title="Click to edit"><span style="background:'+st.color+'18;color:'+st.color+';border-radius:20px;padding:3px 10px;font-size:11px;font-weight:700;white-space:nowrap;">'+st.label+'</span>'+(isOppRow?'<span style="margin-left:6px;background:#eef2ff;color:#6366f1;border-radius:20px;padding:3px 8px;font-size:10px;font-weight:700;white-space:nowrap;">💎 Deal</span>':'')+'</td>'
      +(anShowOwnerColumn()?'<td style="padding:10px 12px;" onclick="event.stopPropagation()">'+(repEmail?'<span style="background:'+repCol+'18;color:'+repCol+';border-radius:5px;padding:2px 8px;font-size:11px;font-weight:700;cursor:pointer;" title="Change owner" onclick="anOpenOwnerPicker({leadId:\''+lead.id+'\'})">'+anEsc(repName)+' ▾</span>':'<span style="color:var(--text-muted);font-size:12px;cursor:pointer;" onclick="anOpenOwnerPicker({leadId:\''+lead.id+'\'})">+ Assign ▾</span>')+'</td>':'')
      +'<td data-field="nextFollowUp" style="padding:10px 12px;font-size:12.5px;color:'+(fuDue?'#ef4444':'var(--text-muted)')+';font-weight:'+(fuDue?'700':'400')+';cursor:text;" title="Click to edit">'+(lead.nextFollowUp?anDate(lead.nextFollowUp):'—')+'</td>'
      +'<td style="padding:10px 12px;">'+(function(){
        var lastCall=(lead.callLog&&lead.callLog.length)?lead.callLog.slice().sort(function(a,b){return b.date.localeCompare(a.date);})[0]:null;
        var actIcons={pickup:'☎️',demo:'🎯',voicemail:'📬',noanswer:'📵',note:'📝'};
        var actLabels={pickup:'Picked Up',demo:'Demo Set',voicemail:'Voicemail',noanswer:'No Answer',note:'Note'};
        var actColors={pickup:'#10b981',demo:'#f59e0b',voicemail:'#6366f1',noanswer:'#a1a1aa',note:'#06b6d4'};
        if(lastCall){
          var ic=actIcons[lastCall.outcome]||'📞';
          var lb=actLabels[lastCall.outcome]||'Call';
          var cl=actColors[lastCall.outcome]||'#a1a1aa';
          return '<div style="display:flex;align-items:center;gap:3px;"><span style="font-size:12px;">'+ic+'</span>'
            +'<div><div style="font-size:11px;font-weight:600;color:'+cl+';white-space:nowrap;">'+lb+'</div>'
            +'<div style="font-size:10px;color:var(--text-muted);">'+anTimeAgo(lastCall.date+(lastCall.time?'T'+lastCall.time:''))+'</div></div></div>';
        }
        return '<div style="font-size:12px;color:var(--text-muted);">'+anTimeAgo(lead.lastContactDate||lead.created)+'</div>'
          +(calls?'<div style="font-size:10px;color:var(--text-muted);">'+calls+' call'+(calls!==1?'s':'')+'</div>':'<div style="font-size:10px;color:var(--text-muted);">No calls</div>');
      })()+'</td>'
      +'<td style="padding:10px 12px;" onclick="event.stopPropagation()">'
      +'<div style="display:flex;gap:4px;">'
      +'<button onclick="anLogCall(\''+lead.id+'\')" style="background:#ecfdf5;color:#10b981;border:1px solid #a7f3d0;border-radius:6px;padding:4px 8px;font-size:11.5px;font-weight:700;cursor:pointer;font-family:var(--sans);" title="Log Activity">📞</button>'
      +(anCanReassignOwner(lead)?'<button onclick="event.stopPropagation();anOpenOwnerPicker({leadId:\''+lead.id+'\'})" style="background:#fffbeb;color:#f59e0b;border:1px solid #fde68a;border-radius:6px;padding:4px 8px;font-size:11.5px;cursor:pointer;font-family:var(--sans);" title="Change owner">👤</button>':'')
      +'<button onclick="anDeleteLead(\''+lead.id+'\')" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:12px;padding:4px 6px;" title="Delete">✕</button>'
      +'</div></td>'
      +'</tr>';
  }).join('');

  el.innerHTML = '<div style="display:flex;flex-direction:column;min-height:100%;">'
    +'<div style="flex:1;overflow:auto;"><table style="width:100%;border-collapse:collapse;font-size:13.5px;min-width:800px;">'
    +'<thead><tr>'
    +'<th style="width:52px;padding:9px 8px;border-bottom:2px solid var(--divider);vertical-align:bottom;"><input type="checkbox" id="crm-select-all" onclick="anToggleSelectAll(this.checked)" title="Select leads on this page only ('+(AN.pageSize||100)+' max)" style="width:14px;height:14px;accent-color:#6366f1;cursor:pointer;"><div style="font-size:8px;color:var(--text-muted);margin-top:3px;line-height:1.35;"><div style="display:flex;flex-direction:column;gap:3px;margin-top:4px;"><a href="#" onclick="event.preventDefault();anSelectAllFilteredLeads()" title="Select all +list.length.toLocaleString()+leads" style="font-size:9.5px;font-weight:700;color:#6366f1;text-decoration:none;white-space:nowrap;">All '+list.length.toLocaleString()+'</a><a href="#" onclick="event.preventDefault();anPromptTransferCount()" title="Pick a specific number" style="font-size:9.5px;font-weight:600;color:var(--text-muted);text-decoration:none;white-space:nowrap;">Pick...</a></div></th>'
    +th('Name','lastName')+th('Company','company')+th('State','state')+th('Size','size')+th('Phone','phone')+th('Status','status')
    +(anShowOwnerColumn()?'<th style="padding:9px 12px;border-bottom:2px solid var(--divider);font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:#f59e0b;">Owner</th>':'')
    +th('Follow Up','nextFollowUp')+th('Last Activity','lastContactDate')
    +'<th style="padding:9px 12px;border-bottom:2px solid var(--divider);font-family:var(--mono);font-size:9px;font-weight:700;color:var(--text-muted);">ACTIONS</th>'
    +'</tr></thead>'
    +'<tbody>'+rows+'</tbody></table></div>'
    +anRenderLeadsPagination(list, pageInfo.totalPages, pageInfo.start)
    +'</div>';
  setTimeout(function(){ if(typeof anUpdateBulkBar==='function') anUpdateBulkBar(); }, 0);
  } catch(err) {
    console.error('[CRM] renderLeadsTable failed:', err);
    var el2 = document.getElementById('crm-content');
    if(el2) el2.innerHTML = '<div style="padding:40px 20px;text-align:center;color:#ef4444;font-size:14px;">Could not render leads table. Try refreshing — your data may still be saved.</div>';
  }
}

function buildKanban(list){
  var KANBAN_COL_LIMIT = 60;
  var cols = AN_STATUSES.map(function(s){
    var leads = list.filter(function(l){ return l.status===s.id; });
    var shown = leads.slice(0, KANBAN_COL_LIMIT);
    var cards = shown.map(function(l){
      return '<div onclick="anOpenLead(\''+l.id+'\')" style="background:var(--card-bg);border:1px solid var(--divider);border-radius:9px;padding:12px;margin-bottom:8px;cursor:pointer;transition:box-shadow 0.15s;border-left:3px solid '+s.color+';" onmouseover="this.style.boxShadow=\'0 4px 12px rgba(0,0,0,0.08)\'" onmouseout="this.style.boxShadow=\'none\'">'
        +'<div style="font-size:13px;font-weight:700;color:var(--text-primary);margin-bottom:3px;">'+anEsc((l.firstName||'')+' '+(l.lastName||''))+'</div>'
        +(l.title?'<div style="font-size:11px;color:#7c3aed;font-weight:600;">'+anEsc(l.title)+'</div>':'')
        +(l.company?'<div style="font-size:12px;color:var(--text-muted);">'+anEsc(l.company)+'</div>':'')
        +'<div style="display:flex;align-items:center;justify-content:space-between;margin-top:8px;">'
        +(l.size?'<span style="font-size:11px;color:var(--text-muted);">'+anEsc(anSize(l.size).label)+'</span>':'<span></span>')
        +(l.nextFollowUp?'<span style="font-size:10.5px;color:#6366f1;">📅 '+anDate(l.nextFollowUp)+'</span>':'')
        +'</div></div>';
    }).join('');
    return '<div style="flex:0 0 200px;background:var(--body-bg);border-radius:10px;padding:12px;">'
      +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:10px;">'
      +'<span style="width:8px;height:8px;border-radius:50%;background:'+s.dot+';"></span>'
      +'<span style="font-size:12px;font-weight:700;color:var(--text-primary);">'+s.label+'</span>'
      +'<span style="background:var(--card-bg);border:1px solid var(--divider);border-radius:10px;padding:1px 7px;font-size:11px;color:var(--text-muted);margin-left:auto;">'+leads.length+'</span>'
      +'</div>'+cards+(leads.length > KANBAN_COL_LIMIT ? '<div style="font-size:11px;color:var(--text-muted);padding:6px 2px;">+'+(leads.length - KANBAN_COL_LIMIT)+' more — switch to List view</div>' : '')+'</div>';
  }).join('');
  return '<div style="display:flex;gap:10px;padding:16px;overflow-x:auto;min-height:100%;">'+cols+'</div>';
}

// ── Lead detail modal ─────────────────────────────────────────
window.anOpenLead = function(id){
  var lead = AN.leads.find(function(l){ return l.id===id; });
  if(!lead) return;
  if (typeof anRepOwnsLead === 'function' && !anRepOwnsLead(lead)) {
    if (typeof showToast === 'function') showToast('You can only open contacts assigned to you');
    return;
  }

  var old = document.getElementById('an-lead-modal');
  if(old) old.remove();

  var st = anStatus(lead.status||'new');
  var STATUS_OPTS = anStatusesFor(lead).map(function(s){ return '<option value="'+s.id+'"'+(lead.status===s.id?' selected':'')+'>'+s.label+'</option>'; }).join('');
  var SIZE_OPTS   = '<option value="">Size...</option>'+AN_SIZES.map(function(s){ return '<option value="'+s.id+'"'+(lead.size===s.id?' selected':'')+'>'+s.label+'</option>'; }).join('');
  var STATE_OPTS  = '<option value="">State...</option>'+['Alabama','Alaska','Arizona','Arkansas','California','Colorado','Connecticut','Delaware','Florida','Georgia','Hawaii','Idaho','Illinois','Indiana','Iowa','Kansas','Kentucky','Louisiana','Maine','Maryland','Massachusetts','Michigan','Minnesota','Mississippi','Missouri','Montana','Nebraska','Nevada','New Hampshire','New Jersey','New Mexico','New York','North Carolina','North Dakota','Ohio','Oklahoma','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming'].map(function(s){ return '<option value="'+s+'"'+(lead.state===s?' selected':'')+'>'+s+'</option>'; }).join('');
  var LANG_OPTS   = anBuildLeadLangOptions(lead.preferredLang || 'en');

  var callLog = (lead.callLog||[]).slice().sort(function(a,b){ return b.date.localeCompare(a.date); });
  var callHTML = callLog.length?callLog.map(function(c){
    var icons = {pickup:'☎️',demo:'🎯',voicemail:'📬',noanswer:'📵',note:'📝'};
    var colors = {pickup:'#10b981',demo:'#f59e0b',voicemail:'#6366f1',noanswer:'#a1a1aa',note:'#06b6d4'};
    var col = colors[c.outcome]||'#a1a1aa';
    return '<div style="display:flex;gap:10px;padding:10px 0;border-bottom:1px solid var(--divider);">'
      +'<div style="width:32px;height:32px;border-radius:50%;background:'+col+'18;border:1.5px solid '+col+'44;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0;">'+(icons[c.outcome]||'📞')+'</div>'
      +'<div style="flex:1;"><div style="font-size:13px;font-weight:700;color:'+col+';margin-bottom:2px;">'+(c.outcome?c.outcome.charAt(0).toUpperCase()+c.outcome.slice(1):'Call')+'</div>'
      +'<div style="font-size:11.5px;color:var(--text-muted);">'+anDate(c.date)+(c.time?' · '+c.time:'')+(c.duration?' · '+c.duration+' min':'')+'</div>'
      +(c.notes?'<div style="font-size:13px;color:var(--text-secondary);margin-top:4px;line-height:1.6;">'+anEsc(c.notes)+'</div>':'')
      +'</div></div>';
  }).join(''):'<div style="text-align:center;padding:32px;color:var(--text-muted);font-size:13px;">No calls logged yet.</div>';

  var ov = document.createElement('div');
  ov.id = 'an-lead-modal';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:32px 20px;overflow-y:auto;backdrop-filter:blur(4px);';

  var isNewLead = !!lead._isDraftNew;
  var headerTitle = isNewLead ? 'Add New Lead' : anEsc((lead.firstName||'')+' '+(lead.lastName||'')).trim() || 'Lead';
  var headerSub = isNewLead
    ? 'Enter contact and agency details — saves to your pipeline'
    : anEsc([lead.company,lead.state,lead.size?anSize(lead.size).label:''].filter(Boolean).join(' · '));

  ov.innerHTML = '<div style="background:var(--card-bg);border-radius:16px;width:780px;max-width:95vw;box-shadow:0 24px 80px rgba(0,0,0,0.3);overflow:hidden;">'

    // Header
    +'<div style="background:linear-gradient(135deg,#0a0a14,#1a1640);padding:20px 26px;display:flex;align-items:center;justify-content:space-between;">'
    +'<div><div style="font-size:20px;font-weight:800;color:#fff;letter-spacing:-0.5px;">'+headerTitle+'</div>'
    +'<div style="font-size:13px;color:rgba(255,255,255,0.45);margin-top:2px;">'+headerSub+'</div>'
    +'</div>'
    +'<div style="display:flex;align-items:center;gap:10px;">'
    +(isNewLead ? '' : '<span style="background:'+st.color+'28;color:'+st.color+';border-radius:20px;padding:5px 14px;font-size:12px;font-weight:700;">'+st.label+'</span>')
    +'<button onclick="anCloseLeadModal(\''+lead.id+'\')" style="background:rgba(255,255,255,0.1);border:none;color:rgba(255,255,255,0.6);width:30px;height:30px;border-radius:8px;cursor:pointer;font-size:16px;">✕</button>'
    +'</div></div>'

    // Tabs
    +'<div style="display:flex;border-bottom:1px solid var(--divider);background:var(--body-bg);">'
    +['details','calls','notes'].map(function(t,i){
      return '<button onclick="anLeadTab(\''+t+'\')" id="alt-'+t+'" style="padding:11px 20px;border:none;border-bottom:2px solid '+(i===0?'#6366f1':'transparent')+';font-size:13px;font-weight:'+(i===0?'700':'600')+';color:'+(i===0?'#6366f1':'var(--text-muted)')+';background:transparent;cursor:pointer;font-family:var(--sans);">'
        +{details:'Details',calls:'Call Log ('+(lead.callLog||[]).length+')',notes:'Notes'}[t]
        +'</button>';
    }).join('')
    +'</div>'

    // Details pane
    +'<div id="alp-details" style="padding:22px 26px;display:grid;grid-template-columns:1fr 1fr;gap:12px;">'
    +anField('First Name','alf-fn',lead.firstName||'','text')
    +anField('Last Name','alf-ln',lead.lastName||'','text')
    +(isNewLead
      ? '<div style="grid-column:1/-1;background:#f5f3ff;border:1.5px solid #c7d2fe;border-radius:10px;padding:12px 14px;">'
        +'<label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:#6366f1;display:block;margin-bottom:5px;">Company / Agency</label>'
        +'<input id="alf-co" type="text" value="'+anEsc(lead.company||'')+'" placeholder="e.g. Compass Insurance Advisors, ABC Agency..." style="width:100%;border:1.5px solid #c7d2fe;border-radius:8px;padding:10px 12px;font-size:14px;font-weight:600;color:var(--text-primary);background:#fff;outline:none;font-family:var(--sans);box-sizing:border-box;" onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'#c7d2fe\'">'
        +'<div style="font-size:11px;color:#71717a;margin-top:6px;line-height:1.45;">Creates or links a company record automatically when you save.</div>'
        +'</div>'
      : anField('Company','alf-co',lead.company||'','text').replace('type="text"','type="text" placeholder="Agency name — add anytime, even if blank on import"'))
    +anField('Title / Role','alf-title',lead.title||'','text').replace('type="text"','type="text" placeholder="e.g. Owner, Agent, Agency Owner, Producer"')
    +anField('Email','alf-em',lead.email||'','email')
    +anField('Phone','alf-ph',lead.phone||'','tel')
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">State</label><select id="alf-st" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);">'+STATE_OPTS+'</select></div>'
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Preferred Language</label><select id="alf-lang" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);">'+LANG_OPTS+'</select></div>'
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Size</label><select id="alf-sz" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);">'+SIZE_OPTS+'</select></div>'
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Status</label><select id="alf-sta" onchange="injectDemoScheduler(AN.leads.find(function(l){return l.id===\''+lead.id+'\'}),this)" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);">'+STATUS_OPTS+'</select></div>'
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Source</label>'
    +'<input id="alf-src" list="an-source-list" value="'+anEsc(lead.source||'')+'" placeholder="e.g. Apollo, Referral, HubSpot..." style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);box-sizing:border-box;" onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'"></div>'
    +anField('Next Follow-Up','alf-fu',lead.nextFollowUp||'','date')
    +'<div style="grid-column:1/-1;"><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Notes</label>'
    +'<textarea id="alf-notes" rows="4" placeholder="Imported notes, pain points, context..." style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:10px 12px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;resize:vertical;font-family:var(--sans);line-height:1.6;box-sizing:border-box;" onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'">'+anEsc(lead.notes||'')+'</textarea></div>'
    +anBuildSourceDatalist()
    +'<div id="alf-demo-wrap" style="grid-column:1/-1;display:none;"></div>'
    +'<div style="grid-column:1/-1;display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid var(--divider);">'
    +'<button onclick="anCloseLeadModal(\''+lead.id+'\')" style="padding:9px 16px;border-radius:8px;border:1.5px solid var(--divider);background:transparent;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);color:var(--text-secondary);">Cancel</button>'
    +'<button type="button" id="an-save-lead-btn" data-lead-id="'+lead.id+'" style="padding:9px 18px;border-radius:8px;border:none;background:#6366f1;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:var(--sans);box-shadow:0 2px 8px rgba(99,102,241,0.3);touch-action:manipulation;">'+(isNewLead?'Save Lead':'Save Changes')+'</button>'
    +'</div></div>'

    // Calls pane
    +'<div id="alp-calls" style="display:none;padding:22px 26px;">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">'
    +'<div style="font-size:14px;font-weight:700;color:var(--text-primary);">Call History</div>'
    +'<button onclick="anLogCall(\''+lead.id+'\')" style="background:#6366f1;border:none;border-radius:7px;padding:7px 14px;font-size:12.5px;font-weight:700;color:#fff;cursor:pointer;font-family:var(--sans);">+ Log Call</button>'
    +'</div><div id="an-call-log-list">'+callHTML+'</div></div>'

    // Notes pane
    +'<div id="alp-notes" style="display:none;padding:22px 26px;">'
    +'<textarea id="an-notes-ta" rows="10" placeholder="Notes, pain points, next steps..." style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:12px;font-size:14px;color:var(--text-primary);background:var(--card-bg);outline:none;resize:vertical;font-family:var(--sans);line-height:1.7;box-sizing:border-box;">'+anEsc(lead.notes||'')+'</textarea>'
    +'<div style="display:flex;justify-content:flex-end;margin-top:10px;"><button onclick="anSaveNotes(\''+lead.id+'\')" style="background:#6366f1;border:none;border-radius:8px;padding:9px 18px;font-size:13px;font-weight:700;color:#fff;cursor:pointer;font-family:var(--sans);">Save Notes</button></div>'
    +'</div></div>';

  document.body.appendChild(ov);
  ov.onclick = function(e){ if(e.target===ov) anCloseLeadModal(lead.id); };
  if (typeof anWireLeadModalSave === 'function') anWireLeadModalSave(lead.id);
  if (isNewLead) {
    setTimeout(function(){
      var focusEl = document.getElementById('alf-fn') || document.getElementById('alf-co');
      if (focusEl) focusEl.focus();
    }, 80);
  }
  var statusSel = document.getElementById('alf-sta');
  if (statusSel && typeof injectDemoScheduler === 'function') injectDemoScheduler(lead, statusSel);
};

function anField(label,id,value,type){
  var blurExtra = '';
  if(type === 'tel'){
    value = anFormatPhone(value);
    blurExtra = 'this.value=anFormatPhone(this.value)||this.value;';
  }
  return '<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">'+label+'</label>'
    +'<input id="'+id+'" type="'+type+'" value="'+anEsc(value)+'"'+(type==='tel'?' placeholder="801-888-8888"':'')
    +' style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);box-sizing:border-box;" onfocus="this.style.borderColor=\'#6366f1\'" onblur="'+blurExtra+'this.style.borderColor=\'var(--divider)\'"></div>';
}

window.anLeadTab = function(tab){
  ['details','calls','notes'].forEach(function(t){
    var p=document.getElementById('alp-'+t), b=document.getElementById('alt-'+t);
    if(p) p.style.display=t===tab?(t==='details'?'grid':'block'):'none';
    if(b){ b.style.borderBottomColor=t===tab?'#6366f1':'transparent'; b.style.color=t===tab?'#6366f1':'var(--text-muted)'; b.style.fontWeight=t===tab?'700':'600'; }
  });
};

function anLinkLeadToCompanyRecord(lead, companyName){
  if(!lead || typeof coNormName !== 'function') return;
  var cn = (companyName || '').trim();
  if(!cn){
    delete lead.companyId;
    return;
  }
  if(typeof coIsValidCompanyName === 'function' && !coIsValidCompanyName(cn)){
    delete lead.companyId;
    return;
  }
  if(typeof coSave !== 'function') return;
  var companies = (typeof _coData !== 'undefined' && _coData && _coData.length) ? _coData.slice() : [];
  try { if(!companies.length) companies = JSON.parse(localStorage.getItem('agentnav-companies')||'[]'); } catch(e){}
  var key = coNormName(cn);
  var found = companies.find(function(c){ return coNormName(c.name) === key; });
  if(!found){
    found = { id:'co-'+Date.now()+'-'+Math.random().toString(36).slice(2,6), name:cn, industry:'Insurance Agency', notes:'', website:'', lifecycleStage:'', created:new Date().toISOString() };
    companies.push(found);
    coSave(companies);
  }
  lead.companyId = found.id;
}

