window.anUpdateLeadPreferredLang = function(leadId, lang) {
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  if (!lead) return false;
  lead.preferredLang = lang || 'en';
  lead.updated = new Date().toISOString();
  if (typeof AN.save === 'function') AN.save();
  if (document.getElementById('an-cs-lead-panel') && typeof anRenderCallSessionLeadPanel === 'function') {
    anRenderCallSessionLeadPanel(leadId);
  }
  if (document.getElementById('an-side-panel') && window._anPanelLeadId === leadId && typeof anRefreshLeadPanel === 'function') {
    anRefreshLeadPanel(leadId);
  }
  var overlay = document.getElementById('mcm-overlay');
  if (overlay && typeof anRenderCallScript === 'function') {
    overlay._scriptId = null;
    anRenderCallScript(leadId);
  }
  if (typeof showToast === 'function') showToast('Preferred language: ' + anGetLeadLangLabel(lead.preferredLang));
  return true;
};

window.anSaveLeadCore = function(id){
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id===id; }) : null;
  if(!lead) {
    if(typeof showToast==='function') showToast('Could not save — reopen Add Lead and try again');
    return false;
  }
  var g = function(eid){ var el=document.getElementById(eid); return el?el.value:''; };
  lead.firstName=(g('alf-fn')||'').trim();
  lead.lastName=(g('alf-ln')||'').trim();
  lead.company=(g('alf-co')||'').trim();
  lead.title=(g('alf-title')||'').trim();
  lead.email=(g('alf-em')||'').trim();
  lead.phone=anNormalizePhone(g('alf-ph'));
  lead.state=typeof anNormalizeLeadStateValue==='function'?anNormalizeLeadStateValue(g('alf-st')):g('alf-st');
  lead.size=g('alf-sz');
  var nextStatus = g('alf-sta') || lead.status || 'new';
  if (typeof anApplyLeadStatusChange === 'function') {
    anApplyLeadStatusChange(lead, nextStatus, { save: false, source: 'lead_modal' });
  } else {
    lead.status = nextStatus;
  }
  lead.source=(g('alf-src')||'').trim();
  lead.preferredLang=g('alf-lang') || 'en';
  lead.nextFollowUp=g('alf-fu');
  var notesEl=document.getElementById('alf-notes');
  if(notesEl) lead.notes=notesEl.value;
  var demoDateEl=document.getElementById('alf-demo-date');
  var demoTimeEl=document.getElementById('alf-demo-time');
  var tzEl=document.getElementById('alf-prospect-tz');
  if(demoDateEl) lead.demoDate=demoDateEl.value;
  if(demoTimeEl) lead.demoTime=demoTimeEl.value;
  if(tzEl && tzEl.value) lead.demoTz=tzEl.value;
  if(!lead.firstName && !lead.lastName && !lead.company && !lead.phone && !lead.email) {
    if(typeof showToast==='function') showToast('Add a name, company, phone, or email before saving');
    return false;
  }
  if(typeof anLinkLeadToCompanyRecord==='function') anLinkLeadToCompanyRecord(lead, lead.company);
  if(typeof anSyncCompaniesFromLeads==='function') anSyncCompaniesFromLeads();
  lead.updated=new Date().toISOString();
  delete lead._isDraftNew;
  if(typeof AN.save==='function') AN.save();
  if (typeof anAfterLeadDataChange === 'function') anAfterLeadDataChange(id, { field: 'status' });
  else if (document.getElementById('crm-content') && typeof renderLeadsTableNow === 'function') renderLeadsTableNow();
  else if (document.getElementById('crm-content') && typeof renderLeadsTable === 'function') renderLeadsTable();
  if (typeof hdRender === 'function') {
    var homeSec = document.getElementById('section-home');
    if (homeSec && homeSec.classList.contains('active')) hdRender();
  }
  var modal = document.getElementById('an-lead-modal');
  if (modal) modal.remove();
  return true;
};
window.anSaveLead = window.anSaveLeadCore;

window.anSaveNotes = function(id){
  var lead = AN.leads.find(function(l){ return l.id===id; });
  if(!lead) return;
  var ta=document.getElementById('an-notes-ta'); if(ta) lead.notes=ta.value;
  lead.updated=new Date().toISOString();
  AN.save();
  if(typeof showToast==='function') showToast('Notes saved');
};

