    + '</div>'

    // Activity type selector
    + '<div style="padding:16px 20px 0;">'
    + '<div style="font-size:9.5px;font-weight:700;font-family:var(--mono);letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);margin-bottom:8px;">Activity Type</div>'
    + '<div style="display:flex;gap:6px;margin-bottom:16px;">'
