    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;"><div style="font-size:17px;font-weight:800;color:var(--text-primary);">Fix Lead Company Names from CSV</div>'
    +'<button onclick="document.getElementById(\'an-fix-csv-modal\').remove()" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--text-muted);">✕</button></div>'
