    +'ondragover="event.preventDefault();event.stopPropagation();this.style.borderColor=\'#f59e0b\';this.style.background=\'rgba(245,158,11,0.06)\'" '
    +'ondragleave="event.preventDefault();this.style.borderColor=\'var(--divider)\';this.style.background=\'transparent\'" '
    +'ondrop="event.preventDefault();event.stopPropagation();anHandleFixDrop(event);">'
    +'<div style="font-size:28px;margin-bottom:6px;">🔧</div>'
    +'<div style="font-size:14px;font-weight:700;color:var(--text-primary);">Drop your CSV here or click to browse</div>'
    +'<div style="font-size:12px;color:var(--text-muted);margin-top:4px;">Same file you used before (e.g. adrian-fl.csv)</div></div>'
    +'<input type="file" id="an-fix-file-input" accept=".csv,text/csv" style="display:none;" onchange="anHandleFixCsvFile(this)">'
    +'<div id="an-fix-preview" style="display:none;"></div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;">'
    +'<button onclick="document.getElementById(\'an-fix-csv-modal\').remove()" style="padding:9px 16px;border-radius:8px;border:1.5px solid var(--divider);background:transparent;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);color:var(--text-secondary);">Cancel</button>'
    +'<button id="an-fix-confirm" onclick="anConfirmFixFromCSV()" disabled style="padding:9px 18px;border-radius:8px;border:none;background:#f59e0b;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:var(--sans);opacity:0.5;">Fix Company Names</button>'
    +'</div></div>';
  document.body.appendChild(m);
