var _anFixCsvRaw = null;
var _anFixCsvMapping = null;

window.anHandleFixDrop = function(e){
  if(e && e.preventDefault) e.preventDefault();
  if(e && e.stopPropagation) e.stopPropagation();
  var zone = document.getElementById('an-fix-drop-zone');
  if(zone){ zone.style.borderColor = 'var(--divider)'; zone.style.background = 'transparent'; }
  var f = e && e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
  if(f) anProcessFixCsvFile(f);
};

window.anHandleFixCsvFile = function(inp){
  var file = inp && inp.files && inp.files[0];
  if(file) anProcessFixCsvFile(file);
};

function anProcessFixCsvFile(file){
  if(!file) return;
  var zone = document.getElementById('an-fix-drop-zone');
  if(zone) zone.innerHTML = '<div style="font-size:13px;color:var(--text-muted);">Reading '+anEsc(file.name)+'...</div>';

  var reader = new FileReader();
  reader.onload = function(e){
    var parsed = anParseCSVText(e.target.result);
    if(!parsed || !parsed.rows.length){
      if(zone) zone.innerHTML = '<div style="color:#ef4444;font-weight:700;">Could not parse CSV</div>';
      return;
    }
    _anFixCsvRaw = parsed;
    _anFixCsvMapping = anBuildImportMapping(parsed.headers);
    anSanitizeImportCompanyMapping(_anFixCsvMapping, parsed.headers);
    var preview = anPreviewFixFromCsv(parsed, _anFixCsvMapping);
    var companyCol = _anFixCsvMapping.company >= 0 ? parsed.headers[_anFixCsvMapping.company] : null;

    if(zone){
      zone.style.borderColor = '#10b981';
      zone.style.background = 'rgba(16,185,129,0.04)';
      zone.innerHTML = '<div style="font-size:22px;margin-bottom:4px;">✅</div><div style="font-size:14px;font-weight:700;color:#10b981;">'+parsed.rows.length+' CSV rows loaded</div>';
    }

    var wrap = document.getElementById('an-fix-preview');
    var btn = document.getElementById('an-fix-confirm');
    if(wrap){
      wrap.style.display = 'block';
      var sampleHtml = preview.sample.length
        ? '<div style="margin-top:10px;font-size:12px;color:var(--text-secondary);"><strong>Preview:</strong> '
          + preview.sample.map(function(s){ return anEsc(s.name)+': '+anEsc(s.oldCo)+' → <span style="color:#10b981;font-weight:700;">'+anEsc(s.newCo)+'</span>'; }).join(' · ')
          +'</div>'
        : '';
      var importAlert = preview.shouldImport
        ? '<div style="background:#fef2f2;border:1.5px solid #fca5a5;border-radius:8px;padding:12px;margin-bottom:10px;">'
          +'<div style="font-size:13px;font-weight:800;color:#b91c1c;margin-bottom:4px;">Your leads didn\'t fully save</div>'
          +'<div style="font-size:12px;color:#7f1d1d;line-height:1.5;">Only <strong>'+preview.totalLeads+'</strong> lead'+(preview.totalLeads!==1?'s':'')+' in Lead Pipeline vs <strong>'+preview.csvRows.toLocaleString()+'</strong> CSV rows. Use <strong>Import Leads</strong> below — don\'t use Fix.</div>'
          +'</div>'
        : '';
      wrap.innerHTML = importAlert
        +'<div style="background:var(--body-bg);border-radius:8px;padding:12px;font-size:13px;color:var(--text-secondary);">'
        +'<div style="margin-bottom:8px;">Lead Pipeline: <strong>'+preview.totalLeads.toLocaleString()+'</strong> saved · CSV: <strong>'+preview.csvRows.toLocaleString()+'</strong> rows</div>'
        +'<div><strong style="color:'+(preview.matchable ? '#10b981' : '#f59e0b')+';">'+preview.matchable+'</strong> of <strong>'+preview.needsFix+'</strong> bad leads can be fixed from this CSV.</div>'
        +(preview.shouldImport ? '<div style="font-size:12px;color:#6366f1;margin-top:6px;font-weight:600;">~'+preview.importable.toLocaleString()+' new leads ready to import by email.</div>' : '')
        +(companyCol ? '<div style="font-size:11px;color:var(--text-muted);margin-top:6px;">Company column: <strong>'+anEsc(companyCol)+'</strong></div>' : '<div style="font-size:11px;color:#ef4444;margin-top:6px;">⚠️ No company column detected — check CSV headers.</div>')
        +'<label style="display:flex;align-items:center;gap:8px;margin-top:10px;font-size:12px;cursor:pointer;"><input type="checkbox" id="an-fix-fill-empty" checked style="accent-color:#f59e0b;"> Also fill empty title, source, state, notes from CSV</label>'
        +'<label style="display:flex;align-items:center;gap:8px;margin-top:6px;font-size:12px;cursor:pointer;"><input type="checkbox" id="an-fix-clean-junk-cos" checked style="accent-color:#f59e0b;"> Remove junk company records after</label>'
        +sampleHtml
        +'</div>'
        +(preview.shouldImport && _anFixCsvMapping.company >= 0
          ? '<button type="button" id="an-fix-import-btn" onclick="anImportLeadsFromFixCsv()" style="width:100%;margin-top:12px;padding:12px 16px;border-radius:8px;border:none;background:#6366f1;color:#fff;font-size:14px;font-weight:800;cursor:pointer;font-family:var(--sans);">Import '+preview.csvRows.toLocaleString()+' Leads into Lead Pipeline</button>'
          : '');
    }
    if(btn){
      var canFix = preview.matchable > 0 && _anFixCsvMapping.company >= 0 && !preview.shouldImport;
      btn.disabled = !canFix;
      btn.style.opacity = btn.disabled ? '0.5' : '1';
      btn.textContent = preview.shouldImport ? 'Use Import button above' : (preview.matchable ? ('Fix '+preview.matchable+' Company Names') : 'No matches to fix');
    }
  };
  reader.onerror = function(){
    if(zone) zone.innerHTML = '<div style="color:#ef4444;font-weight:700;">Failed to read file — try click to browse</div>';
    if(typeof showToast === 'function') showToast('Could not read CSV file');
  };
  reader.readAsText(file);
}

function anPurgeJunkCompaniesSilent(){
  if(typeof coIsJunkCompanyName !== 'function' || typeof coSave !== 'function') return;
  var junk = (_coData || []).filter(function(c){ return coIsJunkCompanyName(c.name); });
  if(!junk.length) return;
  var junkIds = {};
  junk.forEach(function(c){ junkIds[c.id] = true; });
  var companies = _coData.filter(function(c){ return !junkIds[c.id]; });
  coSave(companies);
}

window.anImportLeadsFromFixCsv = function(){
  if(!_anFixCsvRaw || !_anFixCsvMapping){
    if(typeof showToast === 'function') showToast('Load a CSV first');
    return;
  }
  if(!anImportMappingHasIdentity(_anFixCsvMapping)){
    if(typeof showToast === 'function') showToast('CSV needs name, email, or company column');
    return;
  }
  var rowCount = _anFixCsvRaw.rows.length;
  if(!confirm('Import '+rowCount.toLocaleString()+' contacts into Lead Pipeline?\n\nThis may take 1–2 minutes. Junk company records will be cleared after.')) return;

  window._anImportCleanJunkAfter = true;
  window._anImportGoToCrmAfter = true;
  var fixModal = document.getElementById('an-fix-csv-modal');
  if(fixModal) fixModal.remove();

  var overlay = document.createElement('div');
  overlay.id = 'an-fix-import-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:10002;display:flex;align-items:center;justify-content:center;padding:20px;';
  overlay.innerHTML = '<div style="background:var(--card-bg);border-radius:12px;padding:28px 32px;text-align:center;min-width:280px;"><div style="font-size:16px;font-weight:800;color:var(--text-primary);margin-bottom:8px;">Importing leads...</div><div id="an-fix-import-status" style="font-size:13px;color:var(--text-muted);">Building contacts (0%)...</div></div>';
  document.body.appendChild(overlay);

  var mapping = _anFixCsvMapping;
  setTimeout(function(){
    try {
      _anImportAssignEmail = anGetDefaultImportAssignEmail();
      window._anImportOwnerLabel = anImportOwnerLabel(_anImportAssignEmail);
      _anPending = anBuildContactsFromMapping(mapping, undefined, _anImportAssignEmail, _anFixCsvRaw);
      var statusEl = document.getElementById('an-fix-import-status');
      if(statusEl) statusEl.textContent = 'Checking duplicates...';
      anClassifyImportBatchChunked(_anPending, function(classified){
        var runImport = function(){
          if(statusEl) statusEl.textContent = 'Saving '+_anPending.length.toLocaleString()+' leads...';
          anExecuteImport(_anPending, { skipDupes:true, updateDupes:false, importAnyway:false, cleanJunkCompanies:true, goToCrm:true });
        };
        if(classified.duplicates.length > 0){
          var ov = document.getElementById('an-fix-import-overlay');
          if(ov) ov.remove();
          anShowDuplicateReview(classified);
        } else {
          runImport();
        }
      }, function(done, total){
        var statusEl2 = document.getElementById('an-fix-import-status');
        if(statusEl2 && total) statusEl2.textContent = 'Checking duplicates ('+Math.round(done/total*100)+'%)...';
      });
    } catch(err) {
      console.error('[CRM] Import from fix CSV failed:', err);
      var ov2 = document.getElementById('an-fix-import-overlay');
      if(ov2) ov2.remove();
      if(typeof showToast === 'function') showToast('Import failed — try Lead Pipeline → Import CSV');
    }
  }, 50);
};

window.anConfirmFixFromCSV = function(){
  if(!_anFixCsvRaw || !_anFixCsvMapping || _anFixCsvMapping.company < 0){
    if(typeof showToast === 'function') showToast('Load a CSV with a company column first');
    return;
  }
  var btn = document.getElementById('an-fix-confirm');
  var fillEmpty = document.getElementById('an-fix-fill-empty');
  var cleanJunk = document.getElementById('an-fix-clean-junk-cos');
  if(btn){ btn.disabled = true; btn.textContent = 'Fixing (0%)...'; }

  anFixLeadsFromCsvChunked(_anFixCsvRaw, _anFixCsvMapping, {
    fillEmpty: fillEmpty ? fillEmpty.checked : true
  }, function(done, total, fixed){
    if(btn && total) btn.textContent = 'Fixing ('+Math.round(done/total*100)+'%)...';
  }, function(result){
    AN.listPage = 0;
    AN.save(function(ok){
      var msg = 'Fixed '+result.fixed+' company name'+(result.fixed!==1?'s':'');
      if(result.notFound) msg += ' · '+result.notFound+' not matched in CSV';
      if(!ok) msg += ' · save issue — refresh and try again';
      if(typeof showToast === 'function') showToast(msg);

      if(cleanJunk && cleanJunk.checked && typeof coDeleteJunkCompanies === 'function'){
        var junk = (_coData || []).filter(function(c){ return coIsJunkCompanyName(c.name); });
        if(junk.length){
          var junkIds = {};
          junk.forEach(function(c){ junkIds[c.id] = true; });
          var companies = _coData.filter(function(c){ return !junkIds[c.id]; });
          coSave(companies, function(){
            if(typeof anSyncCompaniesFromLeads === 'function') anSyncCompaniesFromLeads();
          });
        } else if(typeof anSyncCompaniesFromLeads === 'function') {
          anSyncCompaniesFromLeads();
        }
      } else if(typeof anSyncCompaniesFromLeads === 'function') {
        anSyncCompaniesFromLeads();
      }

      var modal = document.getElementById('an-fix-csv-modal');
      if(modal) modal.remove();
      _anFixCsvRaw = null;
      _anFixCsvMapping = null;
      try { renderLeadsTable(); } catch(e){}
      if(typeof coRender === 'function'){
        var coSec = document.getElementById('section-companies');
        if(coSec && coSec.style.display !== 'none') coRender();
      }
    });
  });
};

