    +'<div id="an-drop-zone" style="border:2px dashed var(--divider);border-radius:12px;padding:32px;text-align:center;cursor:pointer;transition:all 0.15s;margin-bottom:14px;" '
    +'onclick="document.getElementById(\'an-file-input\').click()" '
