  m.innerHTML = '<div style="background:var(--card-bg);border-radius:14px;padding:24px;width:520px;max-width:95vw;box-shadow:0 24px 80px rgba(0,0,0,0.35);">'
    +'<div style="font-size:17px;font-weight:800;color:var(--text-primary);margin-bottom:6px;">Confirm import destination</div>'
    +'<div style="font-size:13px;color:var(--text-muted);margin-bottom:16px;line-height:1.5;">Choose what to create before we save anything.</div>'
    +ownerBanner
    +advisoryHtml
    +'<div style="display:flex;flex-direction:column;gap:10px;margin-bottom:16px;">'
    +'<label style="display:flex;align-items:flex-start;gap:10px;padding:12px;border:2px solid #6366f1;border-radius:10px;background:rgba(99,102,241,0.05);cursor:default;">'
    +'<input type="checkbox" checked disabled style="margin-top:3px;accent-color:#6366f1;">'
    +'<div><div style="font-size:13px;font-weight:800;color:var(--text-primary);">👤 Create '+newCount.toLocaleString()+' lead'+(newCount!==1?'s':'')+' in Lead Pipeline</div>'
    +'<div style="font-size:11px;color:var(--text-muted);margin-top:2px;">Always — every contact becomes a lead. Missing or numeric company? Still a lead; add the agency name later.'+(dupeCount ? ' ('+dupeCount+' duplicates handled next)' : '')+'</div></div></label>'
    +'<label style="display:flex;align-items:flex-start;gap:10px;padding:12px;border:1.5px solid var(--divider);border-radius:10px;cursor:pointer;" id="an-import-co-label">'
    +'<input type="checkbox" id="an-import-create-companies" '+(defaultCreateCompanies ? 'checked' : '')+' style="margin-top:3px;accent-color:#10b981;">'
    +'<div><div style="font-size:13px;font-weight:800;color:var(--text-primary);">🏢 Create '+stats.companyCount.toLocaleString()+' company page'+(stats.companyCount!==1?'s':'')+' in Companies</div>'
    +'<div style="font-size:11px;color:var(--text-muted);margin-top:2px;">Only unique agency names (e.g. "Network Insurance"). Numeric IDs are never created.'+(stats.junkCompanyLeads ? ' · '+stats.junkCompanyLeads+' rows with bad IDs skipped' : '')+'</div></div></label>'
    +'</div>'
    +'<div style="font-size:11px;color:var(--text-muted);margin-bottom:16px;padding:10px;background:var(--body-bg);border-radius:8px;">💡 Tip: Import leads first. You can always sync companies later from Lead Pipeline → Fix from CSV.</div>'
