window.anShowDuplicateReview = function(classified){
  var old = document.getElementById('an-dupe-modal');
  if(old) old.remove();

  var m = document.createElement('div');
  m.id = 'an-dupe-modal';
  m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.65);z-index:10001;display:flex;align-items:center;justify-content:center;padding:20px;overflow-y:auto;';
  var rows = classified.duplicates.slice(0, 8).map(function(d){
    var match = d.matches[0];
    var reason = d.contact.email && match.email && d.contact.email.toLowerCase() === match.email.toLowerCase() ? 'Same email'
      : 'Same name at same company';
    return '<div style="padding:10px 12px;border:1px solid var(--divider);border-radius:8px;margin-bottom:8px;background:var(--body-bg);">'
      +'<div style="font-size:13px;font-weight:700;color:var(--text-primary);">'+anEsc(anContactLabel(d.contact))+'</div>'
      +'<div style="font-size:11px;color:#f59e0b;margin-top:2px;">'+reason+' — matches existing: '+anEsc(anContactLabel(match))+(match.company?' @ '+anEsc(match.company):'')+'</div>'
      +'</div>';
  }).join('');

  m.innerHTML = '<div style="background:var(--card-bg);border-radius:14px;padding:24px;width:560px;max-width:95vw;max-height:90vh;overflow-y:auto;box-shadow:0 24px 80px rgba(0,0,0,0.35);">'
    +'<div style="font-size:17px;font-weight:800;color:var(--text-primary);margin-bottom:6px;">⚠️ '+classified.duplicates.length+' Possible Duplicate'+(classified.duplicates.length!==1?'s':'')+'</div>'
    +'<div style="font-size:13px;color:var(--text-muted);margin-bottom:16px;line-height:1.5;">These contacts look like ones you already have. Choose what to do before importing <strong>'+(classified.newOnes.length + classified.duplicates.length)+'</strong> total contacts.</div>'
    +'<div style="max-height:240px;overflow-y:auto;margin-bottom:16px;">'+rows+(classified.duplicates.length>8?'<div style="font-size:12px;color:var(--text-muted);padding:8px;">+' +(classified.duplicates.length-8)+' more...</div>':'')+'</div>'
    +'<div style="display:flex;flex-direction:column;gap:8px;">'
    +'<button onclick="anExecuteImport(_anPending,Object.assign({skipDupes:true,updateDupes:false,importAnyway:false},window._anImportOpts||{}))" style="padding:11px 16px;border-radius:8px;border:none;background:#6366f1;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:var(--sans);">Skip duplicates — import '+classified.newOnes.length+' new only</button>'
    +'<button onclick="anExecuteImport(_anPending,Object.assign({skipDupes:false,updateDupes:true,importAnyway:false},window._anImportOpts||{}))" style="padding:11px 16px;border-radius:8px;border:1.5px solid #10b981;background:rgba(16,185,129,0.08);color:#10b981;font-size:13px;font-weight:700;cursor:pointer;font-family:var(--sans);">Update existing records with CSV data</button>'
    +'<button onclick="anExecuteImport(_anPending,Object.assign({skipDupes:false,updateDupes:false,importAnyway:true},window._anImportOpts||{}))" style="padding:11px 16px;border-radius:8px;border:1.5px solid #f59e0b;background:rgba(245,158,11,0.08);color:#b45309;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);">Import all anyway (keep duplicates)</button>'
    +'<button onclick="document.getElementById(\'an-dupe-modal\').remove()" style="padding:9px 16px;border-radius:8px;border:1.5px solid var(--divider);background:transparent;color:var(--text-secondary);font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);">Cancel</button>'
    +'</div></div>';
  document.body.appendChild(m);
  m.onclick = function(e){ if(e.target === m) m.remove(); };
};

window.anConfirmImport = function(){
  var btn = document.getElementById('an-import-confirm');
  anFinalizePendingImportSkips();
  var mapping = anGetImportMapping();
  if(!anImportMappingHasIdentity(mapping)){
    if(typeof showToast === 'function') showToast('Map at least one column (name, email, or company) before importing');
    return;
  }
  if(btn){ btn.disabled = true; btn.textContent = 'Building contacts...'; }

  setTimeout(function(){
    try {
      _anImportAssignEmail = anGetImportAssignEmail();
      window._anImportOwnerLabel = anImportOwnerLabel(_anImportAssignEmail);
      _anPending = anBuildContactsFromMapping(mapping);
      if(!_anPending.length){
        if(btn){ btn.disabled = false; btn.textContent = 'Map columns to import'; }
        if(typeof showToast === 'function') showToast('No importable rows — check your column mapping');
        return;
      }
      if(btn) btn.textContent = 'Checking duplicates (0%)...';
      anClassifyImportBatchChunked(_anPending, function(classified){
        if(btn){ btn.disabled = false; btn.textContent = 'Import '+_anPending.length+' Contacts'; }
        anShowImportDestinationModal(classified, function(opts){
          if(classified.duplicates.length > 0){
            anShowDuplicateReview(classified);
            return;
          }
          if(btn){ btn.disabled = true; btn.textContent = 'Importing '+_anPending.length+'...'; }
          anExecuteImport(_anPending, opts);
        });
      }, function(done, total){
        if(btn && total){
          var pct = Math.round((done / total) * 100);
          btn.textContent = 'Checking duplicates ('+pct+'%)...';
        }
      });
    } catch(err) {
      console.error('[CRM] Import build failed:', err);
      if(btn){ btn.disabled = false; btn.textContent = 'Import Contacts'; }
      if(typeof showToast === 'function') showToast('Import failed while building contacts');
    }
  }, 30);
};

