window.anCommTab=function(t){
  document.getElementById('ac-ae').style.display=t==='ae'?'block':'none';
  document.getElementById('ac-sdr').style.display=t==='sdr'?'block':'none';
  document.getElementById('ac-tab-ae').style.borderBottomColor=t==='ae'?'#6366f1':'transparent';
  document.getElementById('ac-tab-ae').style.color=t==='ae'?'#6366f1':'var(--text-muted)';
  document.getElementById('ac-tab-ae').style.fontWeight=t==='ae'?'700':'600';
  document.getElementById('ac-tab-sdr').style.borderBottomColor=t==='sdr'?'#6366f1':'transparent';
  document.getElementById('ac-tab-sdr').style.color=t==='sdr'?'#6366f1':'var(--text-muted)';
  document.getElementById('ac-tab-sdr').style.fontWeight=t==='sdr'?'700':'600';
};

window.anCalcAE=function(){
  var full=parseInt(document.getElementById('ae-full')?.value)||0;
  var annual=parseInt(document.getElementById('ae-annual')?.value)||0;
  // Base: $79 avg × 11% per close
  var basePay=full*79*0.11;
  var annualBonus=annual*100; // $100 bonus per annual upgrade
  var total=basePay+annualBonus;
  var el=document.getElementById('ae-total'); if(el) el.textContent=anFmt$(Math.round(total));
  var br=document.getElementById('ae-break'); if(br) br.innerHTML=(full?full+' closes × $79 × 11% = '+anFmt$(Math.round(basePay))+'<br>':'')+(annual?annual+' annual upgrades × $100 = '+anFmt$(annualBonus)+'<br>':'');
};

window.anCalcSDR=function(){
  var shows=parseInt(document.getElementById('sdr-shows')?.value)||0;
  var creds=parseInt(document.getElementById('sdr-creds')?.value)||0;
  var tier,rate,tierLabel;
  if(shows<=10){ tier=1; rate=25; tierLabel='Tier 1 — $25/show-up'; }
  else if(shows<=20){ tier=2; rate=35; tierLabel='Tier 2 — $35/show-up'; }
  else { tier=3; rate=45; tierLabel='Tier 3 — $45/show-up'; }
  var showPay=shows*rate;
  var volBonus=creds>=21?500:creds>=16?250:creds>=10?125:0;
  var credBonus=creds*25; // $25 per closing credit
  var total=showPay+volBonus+credBonus;
  var tb=document.getElementById('sdr-tier-badge'); if(tb) tb.innerHTML='<span style="background:rgba(99,102,241,0.2);color:#a5b4fc;border-radius:20px;padding:4px 12px;font-size:11px;font-weight:700;">'+tierLabel+'</span>';
  var el=document.getElementById('sdr-total'); if(el) el.textContent=anFmt$(Math.round(total));
  var br=document.getElementById('sdr-break'); if(br) br.innerHTML=shows+' shows × $'+rate+' = '+anFmt$(showPay)+(credBonus?'<br>'+creds+' credits × $25 = '+anFmt$(credBonus):'')+(volBonus?'<br>Volume bonus = '+anFmt$(volBonus):'');
};

