var _origLogin_crm = window.onUserLoggedIn;
window.onUserLoggedIn = function(user){
  if(typeof _origLogin_crm==='function') _origLogin_crm(user);
  if(user){
    if(typeof anRememberRepUserId === 'function') anRememberRepUserId(user);
    AN.currentRepEmail = user.email;
    AN.isAdmin = user.email === AN_CRM_ADMIN_EMAIL;
    AN.currentRep = (user.user_metadata&&user.user_metadata.full_name)||user.email.split('@')[0];
    if (typeof checkCommissionAccess === 'function') checkCommissionAccess();
    if (!AN.isAdmin && Array.isArray(AN.leads) && AN.leads.length && typeof anEnforceRepLeadScope === 'function') {
      anEnforceRepLeadScope();
    }
    AN.leadsReady = false;
    if (typeof AN.invalidateLeadCaches === 'function') AN.invalidateLeadCaches();
    if (typeof AN.load === 'function') {
      AN.load(function(){
        if (typeof anEnforceRepLeadScope === 'function') anEnforceRepLeadScope();
        var crmSec = document.getElementById('section-crm');
        if (crmSec && crmSec.classList.contains('active') && typeof renderCRM === 'function') {
          AN.leadsReady = false;
          renderCRM();
        }
        var homeSec = document.getElementById('section-home');
        if (homeSec && homeSec.classList.contains('active') && typeof hdRender === 'function') hdRender();
      });
    }
  }
};

