// ─── inline block 26 ───────────────────────
// ============================================================
// UNIFIED CRM DATA LAYER
// All calls, demos, closes from CRM feed into Sales Dashboard
// Inline-editable leads table, Opportunities section, per-rep reporting
// ============================================================

// ── 1. INLINE EDITABLE CELLS ─────────────────────────────────
// Override renderLeadsTable to make cells click-to-edit
var _origRenderLeadsTable = window.renderLeadsTable;
window.renderLeadsTable = function() {
  _origRenderLeadsTable && _origRenderLeadsTable();
  attachInlineEdit();
};

function attachInlineEdit() {
  if (window._anInlineEditDelegated) return;
  window._anInlineEditDelegated = true;
  document.addEventListener('click', function(e) {
    var td = e.target.closest('#crm-content tbody td[data-field]');
    if (!td || td.querySelector('input,select')) return;
    e.stopPropagation();
    startInlineEdit(td);
  }, true);
}

function startInlineEdit(td) {
  var field  = td.dataset.field;
  var leadId = td.closest('tr').dataset.leadId;
  var lead   = AN.leads.find(function(l){ return l.id === leadId; });
  if (!lead) return;

  var val = lead[field] || '';
  if (field === 'phone') val = anFormatPhone(val);
  var original = td.innerHTML;
  td.style.padding = '2px 6px';

  // Select/dropdown fields
  if (field === 'status') {
    var sel = document.createElement('select');
    sel.style.cssText = 'width:100%;border:1.5px solid #6366f1;border-radius:6px;padding:5px 8px;font-size:12px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;';
    (typeof anStatusesFor === 'function' ? anStatusesFor(lead) : AN_STATUSES).forEach(function(s) {
      var opt = document.createElement('option');
      opt.value = s.id; opt.textContent = s.label;
      if (s.id === val) opt.selected = true;
      sel.appendChild(opt);
    });
    sel.onchange = function() { saveInlineEdit(lead, field, sel.value, td, original); };
    sel.onkeydown = function(e) {
      if (e.key === 'Escape') { td.innerHTML = original; td.style.padding = ''; td.dataset.field = field; }
    };
    td.innerHTML = ''; td.appendChild(sel); sel.focus();
    return;
  }

  if (field === 'size') {
    var sel2 = document.createElement('select');
    sel2.style.cssText = 'width:100%;border:1.5px solid #6366f1;border-radius:6px;padding:5px 8px;font-size:12px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;';
    [['','—'],['solo','Solo'],['small','Small'],['large','Large'],['enterprise','Enterprise']].forEach(function(opt) {
      var o = document.createElement('option');
      o.value = opt[0]; o.textContent = opt[1];
      if (opt[0] === val) o.selected = true;
      sel2.appendChild(o);
    });
    sel2.onchange = function() { saveInlineEdit(lead, field, sel2.value, td, original); };
    sel2.onkeydown = function(e) {
      if (e.key === 'Escape') { td.innerHTML = original; td.style.padding = ''; td.dataset.field = field; }
    };
    td.innerHTML = ''; td.appendChild(sel2); sel2.focus();
    return;
  }

  // Text input
  var inp = document.createElement('input');
  inp.type = field === 'nextFollowUp' ? 'date' : (field === 'phone' ? 'tel' : 'text');
  inp.value = val;
  if (field === 'phone') inp.placeholder = '801-888-8888';
  inp.style.cssText = 'width:100%;border:1.5px solid #6366f1;border-radius:6px;padding:5px 8px;font-size:13px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;min-width:80px;';
  inp.onblur  = function() { saveInlineEdit(lead, field, inp.value, td, original); };
  inp.onkeydown = function(e) {
    if (e.key === 'Enter') { inp.blur(); }
    if (e.key === 'Escape') { td.innerHTML = original; td.style.padding = ''; }
  };
  td.innerHTML = ''; td.appendChild(inp); inp.focus(); inp.select();
}

window.anPatchLeadTableRow = function(leadId, fields) {
  if (!leadId) return false;
  var lead = (typeof AN !== 'undefined' && typeof AN.leadById === 'function') ? AN.leadById(leadId) : null;
  if (!lead && typeof AN !== 'undefined' && AN.leads) {
    lead = AN.leads.find(function(l) { return l.id === leadId; });
  }
  if (!lead) return false;
  var tr = document.querySelector('#crm-content tbody tr[data-lead-id="' + leadId + '"]');
  if (!tr) return false;
  var patchFields = fields && fields.length ? fields : ['status', 'size', 'company', 'state', 'phone', 'nextFollowUp'];
  patchFields.forEach(function(f) {
    var cell = tr.querySelector('td[data-field="' + f + '"]');
    if (cell) renderCellContent(cell, f, lead);
  });
  return true;
};

window.anLeadStillInFilteredView = function(leadId) {
  if (!leadId || typeof AN === 'undefined' || typeof AN.filtered !== 'function') return true;
  return AN.filtered().some(function(l) { return l.id === leadId; });
};

window.anRefreshCrmCountLabel = function() {
  var countEl = document.getElementById('crm-count');
  if (!countEl || typeof AN === 'undefined' || typeof AN.filtered !== 'function' || typeof anIsProspect !== 'function') return;
  var list = AN.filtered();
  var totalProspects = AN.leads.filter(anIsProspect).length;
  if (typeof anHasActiveCRMFilters === 'function' && anHasActiveCRMFilters()) {
    countEl.textContent = list.length.toLocaleString() + ' filtered · ' + totalProspects.toLocaleString() + ' total';
  } else {
    countEl.textContent = list.length.toLocaleString() + ' of ' + totalProspects.toLocaleString();
  }
};

window.anAfterLeadDataChange = function(leadId, opts) {
  opts = opts || {};
  var lead = (typeof AN !== 'undefined' && typeof AN.leadById === 'function') ? AN.leadById(leadId) : null;
  if (!lead && typeof AN !== 'undefined' && AN.leads) {
    lead = AN.leads.find(function(l) { return l.id === leadId; });
  }
  if (!lead) return;
  anRefreshAfterInlineEdit(lead, opts.field || 'status', opts.td || null);
  var homeSec = document.getElementById('section-home');
  if (homeSec && homeSec.classList.contains('active') && typeof hdRefreshTeamWidgets === 'function') {
    hdRefreshTeamWidgets();
  }
};

function anRefreshAfterInlineEdit(lead, field, td) {
  if (!lead || !lead.id) return;
  if (typeof AN.invalidateLeadCaches === 'function') AN.invalidateLeadCaches();

  var leadId = lead.id;
  var stillHere = typeof anLeadStillInFilteredView === 'function' ? anLeadStillInFilteredView(leadId) : true;

  if (stillHere) {
    if (td) {
      td.style.padding = '';
      renderCellContent(td, field, lead);
      td.style.background = 'rgba(16,185,129,0.1)';
      setTimeout(function() { td.style.background = ''; }, 600);
    } else if (typeof anPatchLeadTableRow === 'function') {
      anPatchLeadTableRow(leadId, field ? [field] : ['status']);
    }
  } else {
    var tr = document.querySelector('#crm-content tbody tr[data-lead-id="' + leadId + '"]');
    if (tr && tr.parentNode) tr.parentNode.removeChild(tr);
    if (typeof anRefreshCrmCountLabel === 'function') anRefreshCrmCountLabel();
  }

  if (field === 'status' || field === 'size' || !stillHere) {
    if (typeof anRefreshCRMStatsBar === 'function') anRefreshCRMStatsBar();
    if (typeof anRefreshRepCounts === 'function') anRefreshRepCounts();
  }

  if (document.getElementById('an-side-panel') && window._anPanelLeadId === leadId && typeof anRefreshLeadPanel === 'function') {
    anRefreshLeadPanel(leadId);
  }

  if (typeof AN !== 'undefined' && AN.currentView === 'kanban') {
    if (typeof renderLeadsTableNow === 'function') renderLeadsTableNow();
    else if (typeof renderLeadsTable === 'function') renderLeadsTable();
  }
}

function saveInlineEdit(lead, field, value, td, original) {
  if (td.dataset.inlineSaving === '1') return;
  if (field === 'phone') value = anNormalizePhone(value);

  // Normalize value comparison
  var currentVal = field === 'status' ? lead.status : lead[field];
  if (currentVal === value) {
    td.style.padding = '';
    renderCellContent(td, field, lead);
    return;
  }

  td.dataset.inlineSaving = '1';

  // ── Mutate lead immediately so any re-render sees the new value ──
  if (field === 'status') {
    var _rltBlocked = false;
    var _origRLTInline = window.renderLeadsTable;
    window.renderLeadsTable = function() {
      if (!_rltBlocked && typeof _origRLTInline === 'function') _origRLTInline.apply(this, arguments);
    };
    _rltBlocked = true;

    if (typeof anApplyLeadStatusChange === 'function') {
      anApplyLeadStatusChange(lead, value, { save: false });
    } else {
      lead.status = value;
    }
    if (value === 'booked_demo' && lead.demoDate && typeof anRecordDemoBooked === 'function') {
      anRecordDemoBooked(lead, { source: 'inline_edit' });
    }
    if (value === 'won' && typeof syncActivityFromCRM === 'function') syncActivityFromCRM('closes', 1);

    // Restore before save so AN.save()'s internal render call works normally
    window.renderLeadsTable = _origRLTInline;
    _rltBlocked = false;
  } else {
    lead[field] = value;
  }

  lead.updated = new Date().toISOString();

  // Invalidate caches so the next render reads fresh data
  if (typeof AN !== 'undefined' && AN.invalidateLeadCaches) AN.invalidateLeadCaches();

  // Save
  if (typeof AN !== 'undefined' && AN.save) AN.save();

  delete td.dataset.inlineSaving;

  // Update just this cell — no full table re-render needed for most field changes
  td.style.padding = '';
  if (typeof renderCellContent === 'function') {
    renderCellContent(td, field, lead);
  }

  // For status changes, do a targeted row badge update rather than full re-render
  if (field === 'status') {
    var tr = td.closest('tr');
    if (tr) {
      // Update row highlight class
      tr.dataset.status = lead.status || '';
      // Refresh the status cell display
      renderCellContent(td, 'status', lead);
    }
    // Debounce full table re-render to avoid rapid-fire re-renders
    clearTimeout(window._anStatusRenderTimer);
    window._anStatusRenderTimer = setTimeout(function() {
      if (typeof renderLeadsTable === 'function') renderLeadsTable();
    }, 600);
  }
}

function renderCellContent(td, field, lead) {
  var anSizeLabel = function(id) { var s = AN_SIZES.find(function(x){return x.id===id;}); return s?s.label:'—'; };
  if (field === 'status') {
    var st = anStatus(lead.status||'new');
    td.innerHTML = '<span style="background:'+st.color+'18;color:'+st.color+';border-radius:20px;padding:3px 10px;font-size:11px;font-weight:700;white-space:nowrap;">'+st.label+'</span>';
  } else if (field === 'size') {
    td.innerHTML = lead.size ? '<span style="background:var(--body-bg);border:1px solid var(--divider);border-radius:5px;padding:2px 8px;font-size:11.5px;font-weight:600;color:var(--text-secondary);">'+anSizeLabel(lead.size)+'</span>' : '<span style="color:var(--text-muted);">—</span>';
  } else if (field === 'nextFollowUp') {
    td.innerHTML = lead.nextFollowUp ? anDate(lead.nextFollowUp) : '—';
  } else if (field === 'phone') {
    td.innerHTML = lead.phone
      ? '<a href="tel:'+anEsc(anTelPhone(lead.phone))+'" onclick="event.stopPropagation()" style="color:var(--text-secondary);text-decoration:none;font-size:13px;">'+anEsc(anPhoneDisplay(lead.phone))+'</a>'
      : '<span style="color:var(--text-muted);">—</span>';
  } else {
    td.innerHTML = anEsc(lead[field]||'—');
  }
  td.dataset.field = field;
}

// ── 2. SYNC CRM → SALES DASHBOARD ────────────────────────────
function syncActivityFromCRM(key, count) {
  if (typeof _dash === 'undefined') return;
  if (!_dash.activity) _dash.activity = { calls:0, demos:0, closes:0 };
  _dash.activity[key] = (_dash.activity[key]||0) + count;

  // Also log to activityLog for today
  var today = typeof anLocalDateStr === 'function' ? anLocalDateStr() : new Date().toISOString().split('T')[0];
  if (!_dash.activityLog) _dash.activityLog = [];
  var entry = _dash.activityLog.find(function(e){ return e.date === today; });
  if (!entry) { entry = {date:today,calls:0,demos:0,closes:0}; _dash.activityLog.push(entry); }
  entry[key] = (entry[key]||0) + count;

  if (typeof dashSave === 'function') dashSave();
  if (typeof anPushTeamActivityCloud === 'function') {
    var delta = {};
    delta[key] = count;
    anPushTeamActivityCloud(delta);
  }

  // Update goals display if visible
  var inp = document.getElementById('gact-'+key);
  if (inp) inp.value = parseInt(inp.value||0) + count;
  if (typeof updateGB === 'function') updateGB(key);
}

// Override anSaveCall to also sync dashboard
var _origAnSaveCall = window.anSaveCall;
window.anSaveCall = function(leadId) {
  _origAnSaveCall && _origAnSaveCall(leadId);
  var lead = AN.leads.find(function(l){ return l.id === leadId; });
  if (!lead) return;
  var outcome = document.getElementById('an-lc-outcome') ? document.getElementById('an-lc-outcome').value : 'pickup';
  // Sync to dashboard
  syncActivityFromCRM('calls', 1);
  if (outcome === 'demo') syncActivityFromCRM('demos', 1);
  if (outcome === 'won')  syncActivityFromCRM('closes', 1);
  // Track hour for hotzone
  if (typeof _dash !== 'undefined' && _dash.activityLog) {
    var today = new Date().toISOString().split('T')[0];
    var entry = _dash.activityLog.find(function(e){ return e.date===today; });
    if (entry) {
      var hr = new Date().getHours();
      if (!entry.calls_by_hour) entry.calls_by_hour = {};
      entry.calls_by_hour[hr] = (entry.calls_by_hour[hr]||0) + 1;
      if (outcome === 'pickup' || outcome === 'demo') {
        if (!entry.pickups_by_hour) entry.pickups_by_hour = {};
        entry.pickups_by_hour[hr] = (entry.pickups_by_hour[hr]||0) + 1;
      }
      if (outcome === 'demo') {
        if (!entry.demos_by_hour) entry.demos_by_hour = {};
        entry.demos_by_hour[hr] = (entry.demos_by_hour[hr]||0) + 1;
      }
      if (typeof dashSave === 'function') dashSave();
    }
  }
};

// ── 3. LEAD SIDE PANEL (detail view) ─────────────────────────
window.anBuildLeadDetailRowHtml = function(label, value, opts) {
  opts = opts || {};
  var rv = (value === null || value === undefined) ? '' : String(value).trim();
  if (!rv || rv === '—') return '';
  var href = opts.href || '';
  var allowWrap = !!opts.wrap;
  var valStyle = 'font-size:12.5px;font-weight:600;text-align:right;'
    + (allowWrap
      ? 'color:#6366f1;text-decoration:none;word-break:break-all;max-width:220px;line-height:1.4;'
      : 'color:var(--text-primary);white-space:nowrap;');
  var val = href
    ? '<a href="'+href+'" style="'+valStyle+'">'+anEsc(rv)+'</a>'
    : '<span style="'+valStyle+'">'+anEsc(rv)+'</span>';
  var copyBtn = opts.copy
    ? '<button type="button" onclick="anCopyToClipboard(\''+String(rv).replace(/\\/g,'\\\\').replace(/'/g,"\\'")+'\')" title="Copy" style="flex-shrink:0;background:none;border:1px solid var(--divider);border-radius:4px;padding:1px 6px;font-size:10px;color:var(--text-muted);cursor:pointer;">📋</button>'
    : '';
  return '<div style="display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px 16px;align-items:center;padding:8px 0;border-bottom:1px solid var(--divider);">'
    +'<span style="font-size:12px;color:var(--text-muted);line-height:1.35;">'+label+'</span>'
    +'<span style="display:inline-flex;align-items:center;justify-content:flex-end;gap:5px;flex-shrink:0;min-width:0;">'+val+copyBtn+'</span>'
    +'</div>';
};

