window.anHaversineMiles = function(lat1, lng1, lat2, lng2) {
  var R = 3958.8;
  var dLat = (lat2 - lat1) * Math.PI / 180;
  var dLng = (lng2 - lng1) * Math.PI / 180;
  var a = Math.sin(dLat / 2) * Math.sin(dLat / 2)
    + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
};
window.anGeoFromLead = function(lead) {
  if (!lead) return null;
  var state = typeof anResolveLeadState === 'function' ? anResolveLeadState(lead) : (lead.state || '');
  var digits = (lead.phone || '').replace(/\D/g, '');
  if (digits.length === 11 && digits.charAt(0) === '1') digits = digits.slice(1);
  var npa = digits.length >= 10 ? digits.slice(0, 3) : '';
  var npaHit = npa && AN_NPA_GEO[npa] ? AN_NPA_GEO[npa] : null;
  var stateCoords = state && AN_STATE_COORDS[state] ? AN_STATE_COORDS[state] : null;
  if (npaHit) {
    return { lat: npaHit.lat, lng: npaHit.lng, state: npaHit.s || state, city: npaHit.c,
      source: state ? 'phone_area+state' : 'phone_area', confidence: state ? 'high' : 'medium',
      label: npaHit.c + (npaHit.s ? ', ' + npaHit.s : '') };
  }
  if (stateCoords) {
    return { lat: stateCoords[0], lng: stateCoords[1], state: state, city: state,
      source: 'state', confidence: 'low', label: state + ' (state estimate)' };
  }
  return null;
};
window.anFindNearestWins = function(lead, limit) {
  limit = limit || 5;
  var geo = anGeoFromLead(lead);
  if (!geo || typeof AN === 'undefined' || !AN.leads) return [];
  var out = [];
  AN.leads.filter(function(l) { return l.status === 'won'; }).forEach(function(w) {
    var wg = anGeoFromLead(w);
    if (!wg) return;
    var name = ((w.firstName || '') + ' ' + (w.lastName || '')).trim() || w.company || 'Won deal';
    out.push({ lead: w, miles: anHaversineMiles(geo.lat, geo.lng, wg.lat, wg.lng), name: name });
  });
  out.sort(function(a, b) { return a.miles - b.miles; });
  return out.slice(0, limit);
};
window.anEnsureLeaflet = function(cb) {
  if (window.L && window.L.map) { if (cb) cb(); return; }
  if (!document.getElementById('leaflet-css')) {
    var link = document.createElement('link');
    link.id = 'leaflet-css'; link.rel = 'stylesheet';
    link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
    document.head.appendChild(link);
  }
  if (document.getElementById('leaflet-js')) {
    var wait = setInterval(function() { if (window.L) { clearInterval(wait); if (cb) cb(); } }, 50);
    return;
  }
  var script = document.createElement('script');
  script.id = 'leaflet-js'; script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
  script.onload = function() { if (cb) cb(); };
  document.head.appendChild(script);
};
window.anRenderLeadIntelMap = function(leadId) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  var el = document.getElementById('an-intel-map-' + leadId);
  if (!lead || !el) return;
  var geo = anGeoFromLead(lead);
  if (!geo) {
    el.innerHTML = '<div style="padding:24px;text-align:center;color:var(--text-muted);font-size:12px;">Add phone or state to see map</div>';
    return;
  }
  anEnsureLeaflet(function() {
    el.innerHTML = '';
    if (el._map) { try { el._map.remove(); } catch(e) {} el._map = null; }
    var map = L.map(el, { zoomControl: false }).setView([geo.lat, geo.lng], geo.confidence === 'low' ? 6 : 8);
    el._map = map;
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 18, attribution: '&copy; OSM' }).addTo(map);
    L.circleMarker([geo.lat, geo.lng], { radius: 9, color: '#6366f1', fillColor: '#6366f1', fillOpacity: 0.85, weight: 2 })
      .addTo(map).bindPopup(anEsc(((lead.firstName||'')+' '+(lead.lastName||'')).trim() || lead.company || 'Lead'));
    var bounds = [[geo.lat, geo.lng]];
    anFindNearestWins(lead, 8).forEach(function(n) {
      var wg = anGeoFromLead(n.lead);
      if (!wg) return;
      bounds.push([wg.lat, wg.lng]);
      L.circleMarker([wg.lat, wg.lng], { radius: 7, color: '#10b981', fillColor: '#10b981', fillOpacity: 0.75, weight: 2 })
        .addTo(map).bindPopup('🏆 ' + anEsc(n.name) + '<br>' + Math.round(n.miles) + ' mi');
    });
    if (bounds.length > 1) map.fitBounds(bounds, { padding: [24, 24], maxZoom: 9 });
    setTimeout(function() { map.invalidateSize(); }, 120);
  });
};
window.anFormatLeadIntelResults = function(lead, intel) {
  if (!intel) return '';
  var html = '';
  if (intel.geo) {
    html += '<div style="font-size:12px;color:var(--text-secondary);margin-bottom:10px;">📍 <strong>' + anEsc(intel.geo.label) + '</strong></div>';
  }
  var nearest = intel.nearestWins || anFindNearestWins(lead, 4);
  if (nearest.length) {
    html += '<div style="margin-bottom:10px;"><div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;margin-bottom:6px;">Nearest closed wins</div>';
    nearest.forEach(function(n) {
      html += '<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--divider);font-size:12px;">'
        + '<span style="font-weight:600;">🏆 ' + anEsc(n.name) + '</span>'
        + '<span style="color:#10b981;font-weight:700;">' + Math.round(n.miles) + ' mi</span></div>';
    });
    html += '</div>';
  }
  if (intel.website && intel.website.meta) {
    html += '<div style="background:#ecfdf5;border:1px solid #a7f3d0;border-radius:8px;padding:10px;margin-bottom:10px;">'
      + '<div style="font-size:10px;font-weight:700;color:#059669;margin-bottom:4px;">WEBSITE</div>'
      + '<a href="' + anEsc(intel.website.url) + '" target="_blank" rel="noopener" style="font-size:12px;font-weight:700;color:#6366f1;">' + anEsc(intel.website.meta.title || intel.website.url) + '</a>'
      + (intel.website.meta.description ? '<div style="font-size:11px;color:var(--text-secondary);margin-top:6px;">' + anEsc(intel.website.meta.description.slice(0, 220)) + '</div>' : '')
      + '</div>';
  }
  if (intel.searchResults && intel.searchResults.length) {
    html += '<div style="margin-bottom:8px;"><div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;margin-bottom:6px;">Web matches</div>';
    intel.searchResults.slice(0, 4).forEach(function(r) {
      html += '<div style="padding:8px 0;border-bottom:1px solid var(--divider);">'
        + '<a href="' + anEsc(r.url) + '" target="_blank" rel="noopener" style="font-size:12px;font-weight:700;color:#6366f1;">' + anEsc(r.title || r.url) + '</a>'
        + (r.snippet ? '<div style="font-size:11px;color:var(--text-muted);margin-top:3px;">' + anEsc(r.snippet) + '</div>' : '')
        + '</div>';
    });
    html += '</div>';
  }
  if (intel.quickLinks && intel.quickLinks.length) {
    html += '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;">';
    intel.quickLinks.forEach(function(l) {
      html += '<a href="' + anEsc(l.url) + '" target="_blank" rel="noopener" style="font-size:10px;font-weight:700;padding:4px 9px;border-radius:20px;border:1px solid var(--divider);color:var(--text-secondary);text-decoration:none;">' + anEsc(l.label) + ' ↗</a>';
    });
    html += '</div>';
  }
  return html || '<div style="font-size:12px;color:var(--text-muted);">No web results — map uses phone/state.</div>';
};
window.anFormatNameSoundResults = function(lead, ns) {
  ns = ns || {};
  if (!ns.firstPhonetic) {
    return '<div style="font-size:12px;color:var(--text-muted);line-height:1.5;">Tap <strong>Hear name</strong> to load pronunciation guide.</div>';
  }
  var html = '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap;">'
    + '<div style="flex:1;min-width:140px;">'
    + '<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.08em;margin-bottom:4px;">Say the first name like</div>'
    + '<div style="font-size:22px;font-weight:900;color:#b45309;letter-spacing:0.02em;line-height:1.2;">' + anEsc(ns.firstPhonetic) + '</div>';
  if (ns.firstSyllables && ns.firstSyllables !== ns.firstPhonetic) {
    html += '<div style="font-size:11px;color:var(--text-muted);margin-top:4px;">' + anEsc(ns.firstSyllables) + '</div>';
  }
  if (ns.lastPhonetic) {
    html += '<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.08em;margin-top:10px;margin-bottom:4px;">Last name</div>'
      + '<div style="font-size:16px;font-weight:800;color:var(--text-primary);">' + anEsc(ns.lastPhonetic) + '</div>';
  }
  html += '</div>'
    + '<div style="display:flex;flex-direction:column;gap:6px;flex-shrink:0;">'
    + '<button type="button" onclick="anPlayNameSound(\'' + lead.id + '\', \'first\')" style="background:#fef3c7;color:#b45309;border:1px solid #fcd34d;border-radius:8px;padding:8px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap;">▶ Hear first name</button>';
  if ((lead.lastName || '').trim()) {
    html += '<button type="button" onclick="anPlayNameSound(\'' + lead.id + '\', \'full\')" style="background:var(--body-bg);color:var(--text-secondary);border:1px solid var(--divider);border-radius:8px;padding:7px 12px;font-size:10px;font-weight:600;cursor:pointer;font-family:inherit;white-space:nowrap;">▶ Full name</button>';
  }
  html += '</div></div>';
  if (ns.tip) {
    html += '<div style="font-size:11px;color:var(--text-secondary);margin-top:10px;line-height:1.5;padding:8px 10px;background:rgba(245,158,11,0.08);border-radius:8px;border:1px solid rgba(245,158,11,0.2);">💡 ' + anEsc(ns.tip) + '</div>';
  }
  if (ns.origin) {
    html += '<div style="font-size:10px;color:var(--text-muted);margin-top:6px;">' + anEsc(ns.origin) + '</div>';
  }
  return html;
};

window.anBuildNameSoundSection = function(lead) {
  if (!lead || !(lead.firstName || '').trim()) return '';
  var ns = lead.nameSound || {};
  var body = ns.firstPhonetic ? anFormatNameSoundResults(lead, ns)
    : '<div style="font-size:12px;color:var(--text-muted);line-height:1.5;">Loads phonetic spelling + audio so you say <strong>' + anEsc(lead.firstName) + '</strong> correctly on the call.</div>';
  return '<div id="an-name-sound-wrap-' + lead.id + '" style="background:linear-gradient(135deg,#fffbeb,#fef3c7);border-radius:10px;padding:14px;margin-bottom:14px;border:1px solid #fcd34d;">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;gap:8px;">'
    + '<div style="font-size:10px;font-weight:700;color:#b45309;text-transform:uppercase;letter-spacing:0.12em;">🔊 How the name sounds</div>'
    + '<button type="button" id="an-name-sound-btn-' + lead.id + '" onclick="anRunNamePronounce(\'' + lead.id + '\')" style="background:#f59e0b;color:#fff;border:none;border-radius:7px;padding:5px 11px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap;">' + (ns.firstPhonetic ? 'Refresh' : 'Hear name') + '</button>'
    + '</div>'
    + '<div id="an-name-sound-body-' + lead.id + '">' + body + '</div></div>';
};

window.anPlayNameSound = function(leadId, part) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  var ns = lead.nameSound || {};
  var text = part === 'full'
    ? (ns.speakFull || ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim())
    : (ns.speakFirst || lead.firstName || '');
  text = (text || '').trim();
  if (!text) {
    if (typeof showToast === 'function') showToast('No pronunciation loaded yet');
    return;
  }
  if (!window.speechSynthesis) {
    if (typeof showToast === 'function') showToast('Audio not supported in this browser');
    return;
  }
  window.speechSynthesis.cancel();
  var u = new SpeechSynthesisUtterance(text);
  var langMap = { en: 'en-US', es: 'es-MX', pt: 'pt-BR', fr: 'fr-FR' };
  u.lang = langMap[lead.preferredLang || 'en'] || 'en-US';
  u.rate = 0.88;
  u.pitch = 1;
  var voices = window.speechSynthesis.getVoices() || [];
  var match = voices.find(function(v) { return v.lang && v.lang.indexOf((u.lang || '').split('-')[0]) === 0; });
  if (match) u.voice = match;
  window.speechSynthesis.speak(u);
};

window.anMaybeAutoNamePronounce = function(leadId) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead || !(lead.firstName || '').trim() || (lead.firstName || '').trim().length < 2) return;
  if (lead.nameSound && lead.nameSound.firstPhonetic) return;
  if (!window._anNameSoundAutoRan) window._anNameSoundAutoRan = {};
  if (window._anNameSoundAutoRan[leadId]) return;
  window._anNameSoundAutoRan[leadId] = true;
  setTimeout(function() { anRunNamePronounce(leadId, true); }, 500);
};

window.anRunNamePronounce = function(leadId, quiet) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead || !(lead.firstName || '').trim()) return;
  var btn = document.getElementById('an-name-sound-btn-' + leadId);
  var body = document.getElementById('an-name-sound-body-' + leadId);
  if (btn) { btn.disabled = true; btn.textContent = 'Loading…'; }
  fetch('/.netlify/functions/name-pronounce', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (window._anAuthToken||'') },
    body: JSON.stringify({
      firstName: lead.firstName || '',
      lastName: lead.lastName || '',
      state: typeof anResolveLeadState === 'function' ? anResolveLeadState(lead) : (lead.state || ''),
      preferredLang: lead.preferredLang || 'en'
    })
  }).then(function(res) { return res.json(); })
    .then(function(data) {
      if (data.error && !data.firstPhonetic) throw new Error(data.error);
      lead.nameSound = Object.assign({}, lead.nameSound || {}, data);
      lead.updated = new Date().toISOString();
      if (AN.save) AN.save();
      if (body) body.innerHTML = anFormatNameSoundResults(lead, lead.nameSound);
      if (btn) btn.textContent = 'Refresh';
      anUpdateCallScriptNameBanner(leadId);
      if (!quiet && typeof showToast === 'function') showToast('Name pronunciation ready');
    })
    .catch(function(err) {
      if (body && !lead.nameSound) {
        body.innerHTML = '<div style="font-size:12px;color:#b45309;">Could not load guide — use ▶ Hear first name after retry, or say "' + anEsc(lead.firstName) + '" as written.</div>'
          + '<button type="button" onclick="anPlayNameSound(\'' + lead.id + '\', \'first\')" style="margin-top:8px;background:#fef3c7;color:#b45309;border:1px solid #fcd34d;border-radius:7px;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">▶ Try basic audio</button>';
      }
      if (!quiet && typeof showToast === 'function') showToast('Name guide unavailable');
    })
    .finally(function() {
      if (btn) { btn.disabled = false; if (btn.textContent === 'Loading…') btn.textContent = lead.nameSound && lead.nameSound.firstPhonetic ? 'Refresh' : 'Hear name'; }
    });
};

window.anUpdateCallScriptNameBanner = function(leadId) {
  var el = document.getElementById('mcm-name-pronounce-banner');
  if (!el) return;
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead || !lead.nameSound || !lead.nameSound.firstPhonetic) {
    el.innerHTML = '';
    el.style.display = 'none';
    return;
  }
  el.style.display = 'block';
  el.innerHTML = '<span style="font-size:10px;font-weight:700;color:#fcd34d;text-transform:uppercase;letter-spacing:0.08em;">Say their name:</span> '
    + '<span style="font-size:14px;font-weight:800;color:#fff;">' + anEsc(lead.nameSound.firstPhonetic) + '</span> '
    + '<button type="button" onclick="anPlayNameSound(\'' + leadId + '\', \'first\')" style="margin-left:8px;background:rgba(245,158,11,0.2);border:1px solid rgba(245,158,11,0.4);color:#fcd34d;border-radius:6px;padding:3px 8px;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;">▶</button>';
};

window.anBuildLeadIntelSection = function(lead) {
  if (!lead) return '';
  var intel = lead.intel || {};
  var body = intel.researchedAt || intel.geo ? anFormatLeadIntelResults(lead, intel)
    : '<div style="font-size:12px;color:var(--text-muted);line-height:1.5;">Scans public web (company site + search). Map from phone area code. No Apollo.</div>';
  return '<div id="an-intel-wrap-' + lead.id + '" style="background:var(--body-bg);border-radius:10px;padding:14px;margin-bottom:14px;border:1px solid var(--divider);">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">'
    + '<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;">🔍 Lead Intel</div>'
    + '<button type="button" id="an-intel-btn-' + lead.id + '" onclick="anRunLeadResearch(\'' + lead.id + '\')" style="background:#6366f1;color:#fff;border:none;border-radius:7px;padding:5px 11px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">Research</button>'
    + '</div>'
    + '<div id="an-intel-map-' + lead.id + '" style="height:160px;border-radius:8px;overflow:hidden;background:#f4f4f5;margin-bottom:10px;"></div>'
    + '<div id="an-intel-body-' + lead.id + '">' + body + '</div></div>';
};
window.anShouldAutoResearchLead = function(lead) {
  if (!lead) return false;
  var last = lead.intel && lead.intel.researchedAt;
  if (!last) return true;
  var age = Date.now() - new Date(last).getTime();
  return age > 24 * 60 * 60 * 1000;
};

window.anInitLeadIntelUI = function(leadId) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  if (!lead.intel) lead.intel = {};
  lead.intel.geo = anGeoFromLead(lead);
  lead.intel.nearestWins = anFindNearestWins(lead, 4);
  setTimeout(function() { anRenderLeadIntelMap(leadId); }, 60);
  if (typeof anShouldAutoResearchLead === 'function' && anShouldAutoResearchLead(lead)) {
    if (!window._anIntelAutoRan) window._anIntelAutoRan = {};
    if (!window._anIntelAutoRan[leadId]) {
      window._anIntelAutoRan[leadId] = true;
      setTimeout(function() { anRunLeadResearch(leadId); }, 400);
    }
  }
  if (typeof anMaybeAutoNamePronounce === 'function') anMaybeAutoNamePronounce(leadId);
};
window.anRunLeadResearch = function(leadId) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  var btn = document.getElementById('an-intel-btn-' + leadId);
  var body = document.getElementById('an-intel-body-' + leadId);
  if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
  var geo = anGeoFromLead(lead);
  var nearestWins = anFindNearestWins(lead, 5);
  var name = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim();
  fetch('/.netlify/functions/lead-research', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (window._anAuthToken||'') },
    body: JSON.stringify({ name: name, company: lead.company || '', email: lead.email || '', phone: lead.phone || '',
      state: typeof anResolveLeadState === 'function' ? anResolveLeadState(lead) : (lead.state || '') })
  }).then(function(res) { return res.json(); })
    .then(function(data) {
      if (data.error) throw new Error(data.error);
      lead.intel = Object.assign({}, lead.intel || {}, data, { geo: geo, nearestWins: nearestWins });
      lead.updated = new Date().toISOString();
      if (AN.save) AN.save();
      if (body) body.innerHTML = anFormatLeadIntelResults(lead, lead.intel);
      anRenderLeadIntelMap(leadId);
      if (typeof showToast === 'function') showToast('Lead intel updated');
    })
    .catch(function() {
      lead.intel = { geo: geo, nearestWins: nearestWins, researchedAt: new Date().toISOString() };
      if (body) body.innerHTML = anFormatLeadIntelResults(lead, lead.intel)
        + '<div style="font-size:11px;color:#b45309;margin-top:8px;">Web scan unavailable — showing map from phone/state.</div>';
      anRenderLeadIntelMap(leadId);
    })
    .finally(function() { if (btn) { btn.disabled = false; btn.textContent = 'Research'; } });
};

window.anLeadMatchesTeamScope = function(lead) {
  if (!lead || typeof AN === 'undefined') return true;
  if (!AN.isAdmin) {
    return typeof anRepOwnsLead === 'function' ? anRepOwnsLead(lead) : true;
  }
  var scope = anGetTeamViewScope();
  if (!scope || scope === '') return true;
  var owner = (lead._repEmail || '').toLowerCase();
  if (scope === '__mine__') return owner === (AN.currentRepEmail || '').toLowerCase();
  return owner === scope.toLowerCase();
};

window.anGetTeamMapMode = function() {
  if (typeof AN === 'undefined') return 'leads';
  if (!AN._teamMapModeLoaded) {
    AN._teamMapModeLoaded = true;
    try {
      var saved = localStorage.getItem('an-team-map-mode');
      if (saved === 'won' || saved === 'leads') AN.teamMapMode = saved;
      else AN.teamMapMode = 'leads';
    } catch(e) { AN.teamMapMode = 'leads'; }
  }
  return AN.teamMapMode === 'won' ? 'won' : 'leads';
};

window.anSetTeamMapMode = function(mode) {
  if (typeof AN === 'undefined') return;
  AN.teamMapMode = mode === 'won' ? 'won' : 'leads';
  AN._teamMapModeLoaded = true;
  try { localStorage.setItem('an-team-map-mode', AN.teamMapMode); } catch(e) {}
  var sel = document.getElementById('hd-team-map-mode');
  if (sel) sel.value = AN.teamMapMode;
  anRenderTeamMap();
};

window.anGetTeamMapScope = function() {
  if (typeof AN === 'undefined') return '__mine__';
  if (!AN._teamMapScopeLoaded) {
    AN._teamMapScopeLoaded = true;
    try {
      var saved = localStorage.getItem('an-team-map-scope');
      if (saved !== null) AN.teamMapScope = saved;
      else AN.teamMapScope = AN.isAdmin ? '' : '__mine__';
    } catch(e) {
      AN.teamMapScope = AN.isAdmin ? '' : '__mine__';
    }
  }
  return AN.teamMapScope || '';
};

window.anSetTeamMapScope = function(val) {
  if (typeof AN === 'undefined') return;
  AN.teamMapScope = val || '';
  AN._teamMapScopeLoaded = true;
  try { localStorage.setItem('an-team-map-scope', AN.teamMapScope); } catch(e) {}
  var sel = document.getElementById('hd-team-map-scope');
  if (sel) sel.value = AN.teamMapScope;
  anRenderTeamMap();
};

window.anLeadMatchesMapScope = function(lead) {
  if (!lead || typeof AN === 'undefined') return false;
  if (!AN.isAdmin) {
    return typeof anRepOwnsLead === 'function' ? anRepOwnsLead(lead) : true;
  }
  var scope = anGetTeamMapScope();
  if (!scope || scope === '') return true;
  var owner = (lead._repEmail || '').toLowerCase();
  if (scope === '__mine__') return owner === (AN.currentRepEmail || '').toLowerCase();
  return owner === scope.toLowerCase();
};

window.anBuildTeamMapScopeSelectHTML = function() {
  if (typeof AN === 'undefined' || !AN.isAdmin) return '';
  var scope = anGetTeamMapScope();
  var reps = typeof anGetKnownRepEmails === 'function' ? anGetKnownRepEmails() : [];
  var html = '<select id="hd-team-map-scope" onchange="anSetTeamMapScope(this.value)" title="Filter by rep" style="padding:5px 10px;border-radius:8px;border:1.5px solid #e4e4e7;background:#fff;font-size:12px;font-weight:600;color:#52525b;cursor:pointer;font-family:inherit;">'
    + '<option value=""'+((!scope || scope==='')?' selected':'')+'>All team</option>'
    + '<option value="__mine__"'+(scope==='__mine__'?' selected':'')+'>My leads</option>';
  reps.forEach(function(em) {
    var name = typeof anGetRepName === 'function' ? anGetRepName(em) : em.split('@')[0];
    html += '<option value="'+anEsc(em)+'"'+(scope===em.toLowerCase()?' selected':'')+'>'+anEsc(name)+'</option>';
  });
  html += '</select>';
  return html;
};

window.anMergeTeamMapLeadPool = function(localLeads, extraLeads) {
  var byId = {};
  (localLeads || []).forEach(function(l) { if (l && l.id) byId[l.id] = l; });
  (extraLeads || []).forEach(function(l) {
    if (!l || !l.id) return;
    var existing = byId[l.id];
    if (!existing || anLeadUpdatedMs(l) > anLeadUpdatedMs(existing)) byId[l.id] = l;
  });
  return Object.keys(byId).map(function(id) { return byId[id]; });
};

window.anEnsureTeamMapLeads = function(cb) {
  cb = cb || function() {};
  if (typeof AN === 'undefined') { cb([]); return; }
  var local = AN.leads ? AN.leads.slice() : [];
  // Admin's AN.leads already IS the full, current team dataset (loaded from the
  // shared team table), so there's nothing extra to fetch or merge in anymore.
  AN._teamMapLeadsPool = AN.isAdmin ? local : (typeof anFilterLeadsForCurrentRep === 'function' ? anFilterLeadsForCurrentRep(local) : local);
  cb(AN._teamMapLeadsPool);
};

window.anLeadMapStatusLabel = function(lead) {
  if (!lead) return 'Lead';
  if (lead.status === 'won') return 'Closed Won';
  var labels = { new:'New', contacted:'Contacted', booked_demo:'Demo Booked', followup:'Following Up', demo:'Demo Set', showed:'Showed', proposal:'Proposal', nurture:'Nurture', emailed:'Emailed', lost:'Lost' };
  return labels[lead.status] || (lead.status || 'Lead');
};

window.anLeadMapOwnerLabel = function(lead) {
  var em = (lead && lead._repEmail) ? lead._repEmail : '';
  if (!em) return 'Unassigned';
  return typeof anGetRepName === 'function' ? anGetRepName(em) : em.split('@')[0].replace(/[._]/g, ' ');
};

window.anGetTeamMapLeads = function(pool) {
  pool = pool || (AN && AN._teamMapLeadsPool) || (AN && AN.leads) || [];
  var mode = anGetTeamMapMode();
  var items = [];
  pool.forEach(function(l) {
    if (!l || !anLeadMatchesMapScope(l)) return;
    if (!anGeoFromLead(l)) return;
    if (mode === 'won') {
      if (l.status === 'won') items.push(l);
      return;
    }
    if (l.status === 'won' || l.status === 'lost' || l.status === 'not_interested') return;
    if (typeof anIsOpportunityRecord === 'function' && anIsOpportunityRecord(l)) return;
    items.push(l);
  });
  items.sort(function(a, b) {
    return ((a.lastName || '') + (a.firstName || '')).localeCompare((b.lastName || '') + (b.firstName || ''));
  });
  return { mode: mode, items: items, total: items.length, shown: items.slice(0, 300) };
};

window.anRenderTeamMapPopup = function(lead, mode) {
  var name = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || lead.company || 'Contact';
  var company = lead.company && name !== lead.company ? lead.company : '';
  var g = anGeoFromLead(lead);
  var owner = anLeadMapOwnerLabel(lead);
  var status = anLeadMapStatusLabel(lead);
  var loc = g ? g.label : '';
  var lines = [];
  if (mode === 'won') lines.push('<b>🏆 ' + anEsc(name) + '</b>');
  else lines.push('<b>' + anEsc(name) + '</b>');
  if (company) lines.push(anEsc(company));
  lines.push('<span style="color:#6366f1;font-weight:700;">' + anEsc(status) + '</span>');
  lines.push('👤 ' + anEsc(owner));
  if (loc) lines.push('📍 ' + anEsc(loc));
  if (lead.phone) lines.push('📞 ' + anEsc(lead.phone));
  return lines.join('<br>');
};

window.anRenderTeamMap = function() {
  var el = document.getElementById('hd-team-map');
  if (!el) return;
  anEnsureTeamMapLeads(function(pool) {
    var data = anGetTeamMapLeads(pool);
    var mode = data.mode;
    var countEl = document.getElementById('hd-team-map-count');
    if (countEl) {
      var modeLabel = mode === 'won' ? 'closed won' : 'active leads';
      var scopeLabel = 'all team';
      if (AN.isAdmin) {
        var scope = anGetTeamMapScope();
        if (scope === '__mine__') scopeLabel = 'my leads';
        else if (scope) scopeLabel = anLeadMapOwnerLabel({ _repEmail: scope });
      }
      countEl.innerHTML = '<span style="color:'+(mode==='won'?'#10b981':'#6366f1')+'">●</span> '
        + data.total + ' ' + modeLabel + ' · ' + scopeLabel
        + (data.total > data.shown.length ? ' (showing ' + data.shown.length + ')' : '');
    }
    var modeSel = document.getElementById('hd-team-map-mode');
    if (modeSel) modeSel.value = mode;
    if (!data.shown.length) {
      if (el._map) { try { el._map.remove(); } catch(e) {} el._map = null; }
      el.innerHTML = '<div style="padding:32px;text-align:center;color:#9999aa;font-size:13px;">No '
        + (mode === 'won' ? 'closed won deals' : 'active leads')
        + ' with a state or phone to plot.<br><small style="font-size:11px;margin-top:8px;display:block;">Add state on the lead record, or a phone number for area-code placement.</small></div>';
      return;
    }
    anEnsureLeaflet(function() {
      el.innerHTML = '';
      if (el._map) { try { el._map.remove(); } catch(e) {} el._map = null; }
      var map = L.map(el, { zoomControl: true }).setView([39.5, -98.35], 4);
      el._map = map;
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 18, attribution: '&copy; OSM' }).addTo(map);
      var bounds = [];
      var color = mode === 'won' ? '#10b981' : '#6366f1';
      var radius = mode === 'won' ? 7 : 5;
      data.shown.forEach(function(l) {
        var g = anGeoFromLead(l);
        if (!g) return;
        bounds.push([g.lat, g.lng]);
        L.circleMarker([g.lat, g.lng], { radius: radius, color: color, fillColor: color, fillOpacity: mode === 'won' ? 0.85 : 0.7, weight: 2 })
          .addTo(map).bindPopup(anRenderTeamMapPopup(l, mode));
      });
      if (bounds.length === 1) map.setView(bounds[0], 7);
      else if (bounds.length) map.fitBounds(bounds, { padding: [30, 30], maxZoom: 8 });
      setTimeout(function() { map.invalidateSize(); }, 200);
    });
  });
};

window.anOpenLeadPanel = function(leadId) {
  var lead = AN.leadById(leadId);
  if (!lead) return;
  if (typeof anHydrateLeadState === 'function') anHydrateLeadState(lead);
  if (typeof anRepOwnsLead === 'function' && !anRepOwnsLead(lead)) {
    if (typeof showToast === 'function') showToast('You can only view contacts assigned to you');
    return;
  }

  var panel = document.getElementById('an-side-panel');
  var sameLead = panel && window._anPanelLeadId === leadId;
  if (!panel) {
    panel = document.createElement('div');
    panel.id = 'an-side-panel';
    // If call session is open, position lead panel to its left
    var callSessionOpen = document.body.classList.contains('call-panel-open') || !!document.getElementById('mcm-panel-wrap');
    var oppPanelOpen = !!document.getElementById('opp-record-panel');
    var rightOffset = callSessionOpen ? '360px' : '0';
    var panelWidth  = callSessionOpen ? '440px' : '440px';
    var panelZ = callSessionOpen ? '19999' : (oppPanelOpen ? '9100' : '8888');
    panel.style.cssText = 'position:fixed;top:0;right:' + rightOffset + ';width:' + panelWidth + ';max-width:100vw;height:100vh;background:var(--card-bg);box-shadow:-4px 0 40px rgba(0,0,0,0.15);z-index:' + panelZ + ';display:flex;flex-direction:column;overflow:hidden;transform:translateX(100%);transition:transform 0.26s cubic-bezier(0.16,1,0.3,1);box-sizing:border-box;';
    document.body.appendChild(panel);
    setTimeout(function(){ panel.style.transform = 'translateX(0)'; }, 10);
  } else if (!sameLead) {
    panel.remove();
    panel = document.createElement('div');
    panel.id = 'an-side-panel';
    var oppPanelOpen2 = !!document.getElementById('opp-record-panel');
    panel.style.cssText = 'position:fixed;top:0;right:0;width:440px;max-width:100vw;height:100vh;background:var(--card-bg);box-shadow:-4px 0 40px rgba(0,0,0,0.15);z-index:' + (oppPanelOpen2 ? '9100' : '8888') + ';display:flex;flex-direction:column;overflow:hidden;transform:translateX(100%);transition:transform 0.26s cubic-bezier(0.16,1,0.3,1);box-sizing:border-box;';
    document.body.appendChild(panel);
    setTimeout(function(){ panel.style.transform = 'translateX(0)'; }, 10);
  }

  function refreshPanel() {
    if (panel.dataset) delete panel.dataset.callAgainPatched;
    var st = anStatus(lead.status||'new');
    var sz = lead.size ? AN_SIZES.find(function(s){return s.id===lead.size;}) : null;
    var leadState = typeof anResolveLeadState === 'function' ? anResolveLeadState(lead) : (lead.state || '');
    var today = new Date().toISOString().split('T')[0];
    var todayCalls = (lead.callLog || []).filter(function(c){ return c.date === today && c.outcome !== 'emailed'; }).length;
    var calls = (lead.callLog||[]).slice().sort(function(a,b){return b.date.localeCompare(a.date);});
    var callIcons = {pickup:'☎️',demo:'🎯',voicemail:'📬',noanswer:'📵',note:'📝'};
    var callColors = {pickup:'#10b981',demo:'#f59e0b',voicemail:'#6366f1',noanswer:'#a1a1aa',note:'#06b6d4'};
    var totalCalls = calls.length;
    var pickups = calls.filter(function(c){return c.outcome==='pickup'||c.outcome==='demo';}).length;
    var demosSet = calls.filter(function(c){return c.outcome==='demo';}).length;

    panel.innerHTML =
      // Header
      '<div style="background:linear-gradient(135deg,#0a0a14,#1a1640);padding:18px 20px;flex-shrink:0;">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px;">'
      +'<div>'
      +'<div style="font-size:18px;font-weight:800;color:#fff;letter-spacing:-0.4px;">'+anEsc((lead.firstName||'')+' '+(lead.lastName||''))+'</div>'
      +(lead.title?'<div style="font-size:12px;color:rgba(255,255,255,0.55);margin-top:2px;">'+anEsc(lead.title)+'</div>':'')
      +((lead.company && (document.body.classList.contains('call-panel-open') || document.getElementById('mcm-panel-wrap')) && typeof anBuildClickableCompanyHtml === 'function')
        ? '<div data-panel-company style="font-size:13px;margin-top:2px;color:rgba(255,255,255,0.5);">'+anBuildClickableCompanyHtml(lead.company, 'color:rgba(255,255,255,0.5);')+'</div>'
        : '<div data-panel-company style="font-size:13px;margin-top:2px;color:'+(lead.company?'rgba(255,255,255,0.5)':'#fcd34d')+';">'+anEsc(lead.company||'No company — add below')+'</div>')
      +'</div>'
      +'<div style="display:flex;gap:7px;align-items:center;">'
      +'<span style="background:'+st.color+'28;color:'+st.color+';border-radius:20px;padding:4px 12px;font-size:11px;font-weight:700;">'+st.label+'</span>'
      +'<button onclick="document.getElementById(\'an-side-panel\').style.transform=\'translateX(100%)\';setTimeout(function(){document.getElementById(\'an-side-panel\').remove();},300)" style="background:rgba(255,255,255,0.1);border:none;color:rgba(255,255,255,0.6);width:28px;height:28px;border-radius:7px;cursor:pointer;font-size:14px;">✕</button>'
      +'</div></div>'

      // Quick stats
      +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;">'
      +['<div style="background:rgba(255,255,255,0.06);border-radius:8px;padding:8px;text-align:center;"><div style="font-size:18px;font-weight:800;color:#fff;">'+totalCalls+'</div><div style="font-size:9px;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.1em;">Calls</div></div>',
        '<div style="background:rgba(255,255,255,0.06);border-radius:8px;padding:8px;text-align:center;"><div style="font-size:18px;font-weight:800;color:#10b981;">'+pickups+'</div><div style="font-size:9px;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.1em;">Pickups</div></div>',
        '<div style="background:rgba(255,255,255,0.06);border-radius:8px;padding:8px;text-align:center;"><div style="font-size:18px;font-weight:800;color:#f59e0b;">'+demosSet+'</div><div style="font-size:9px;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.1em;">Demos</div></div>'
      ].join('')+'</div>'
      +'<div data-call-again style="margin-top:10px;padding:10px 12px;border-radius:8px;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.08);display:flex;align-items:center;justify-content:space-between;gap:10px;">'
      +'<span id="sp-call-counter-'+lead.id+'" style="font-size:12px;color:rgba(255,255,255,0.55);white-space:nowrap;">'
      +(todayCalls > 0 ? todayCalls + ' call attempt' + (todayCalls !== 1 ? 's' : '') + ' today' : 'No calls logged today')
      +'</span>'
      +(lead.phone
        ? '<button type="button" onclick="anCallAgain(\''+lead.id+'\')" style="flex-shrink:0;background:rgba(16,185,129,0.18);border:1px solid rgba(16,185,129,0.35);border-radius:7px;padding:6px 12px;font-size:12px;font-weight:700;color:#6ee7b7;cursor:pointer;font-family:var(--sans);white-space:nowrap;">📞 Call Again</button>'
        : '<button type="button" onclick="openMobileCallMode(\''+lead.id+'\')" style="flex-shrink:0;background:rgba(99,102,241,0.18);border:1px solid rgba(99,102,241,0.35);border-radius:7px;padding:6px 12px;font-size:12px;font-weight:700;color:#c7d2fe;cursor:pointer;font-family:var(--sans);white-space:nowrap;">📞 Start Call</button>')
      +'</div></div>'

      // Action buttons
      +'<div style="padding:12px 16px;border-bottom:1px solid var(--divider);display:flex;gap:7px;flex-shrink:0;">'
      +'<button onclick="anLogCall(\''+lead.id+'\')" style="flex:1;background:#ecfdf5;color:#10b981;border:1px solid #a7f3d0;border-radius:8px;padding:8px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:var(--sans);">⚡ Activity</button>'
      +'<button onclick="anOpenLeadModal(\''+lead.id+'\')" style="flex:1;background:#eef2ff;color:#6366f1;border:1px solid #c7d2fe;border-radius:8px;padding:8px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:var(--sans);">✏️ Edit</button>'
      +'<button onclick="anConvertToOpportunity(\''+lead.id+'\')" style="flex:1;background:#fffbeb;color:#f59e0b;border:1px solid #fde68a;border-radius:8px;padding:8px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:var(--sans);">💎 Opportunity</button>'
      +'</div>'

      // Scrollable content
      +'<div style="flex:1;overflow-y:auto;padding:16px 18px;min-width:0;">'

      + (typeof anBuildLeadOwnerCardHtml === 'function' ? anBuildLeadOwnerCardHtml(lead) : '')

      // Contact details card
      +'<div style="background:var(--body-bg);border-radius:10px;padding:14px;margin-bottom:14px;min-width:0;">'
      +'<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:10px;">Contact Details</div>'
      +'<div style="margin-bottom:12px;padding-bottom:12px;border-bottom:1px solid var(--divider);">'
      +'<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">🏢 Company / Agency</div>'
      +(lead.company ? '<div style="font-size:12.5px;font-weight:600;color:var(--text-primary);margin-bottom:6px;">'+anEsc(lead.company)+'</div>' : '<div style="font-size:11px;color:#b45309;margin-bottom:6px;">Not set</div>')
      +'<div style="display:flex;gap:6px;">'
      +'<input id="sp-company-input" type="text" value="'+anEsc(lead.company||'')+'" placeholder="Add agency name" style="flex:1;border:1.5px solid var(--divider);border-radius:8px;padding:7px 10px;font-size:12px;background:var(--card-bg);color:var(--text-primary);outline:none;font-family:var(--sans);">'
      +'<button type="button" onclick="anUpdateLeadCompany(\''+lead.id+'\', document.getElementById(\'sp-company-input\').value)" style="background:#eef2ff;color:#6366f1;border:1px solid #c7d2fe;border-radius:8px;padding:7px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:var(--sans);">Save</button>'
      +'</div></div>'
      +'<div style="margin-bottom:12px;padding-bottom:12px;border-bottom:1px solid var(--divider);">'
      +'<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">💼 Title / Role</div>'
      +(lead.title ? '<div style="font-size:12.5px;font-weight:600;color:var(--text-primary);margin-bottom:6px;">'+anEsc(lead.title)+'</div>' : '<div style="font-size:11px;color:#b45309;margin-bottom:6px;">Not set</div>')
      +'<div style="display:flex;gap:6px;">'
      +'<input id="sp-title-input" type="text" value="'+anEsc(lead.title||'')+'" placeholder="Owner, Agent, Producer..." style="flex:1;border:1.5px solid var(--divider);border-radius:8px;padding:7px 10px;font-size:12px;background:var(--card-bg);color:var(--text-primary);outline:none;font-family:var(--sans);">'
      +'<button type="button" onclick="anUpdateLeadTitle(\''+lead.id+'\', document.getElementById(\'sp-title-input\').value)" style="background:#f5f3ff;color:#7c3aed;border:1px solid #c4b5fd;border-radius:8px;padding:7px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:var(--sans);">Save</button>'
      +'</div>'
      + anBuildTitleQuickPicksLight(lead.id, 'sp-title-input')
      +'</div>'
      + anBuildLeadDetailRowHtml('📧 Email', lead.email, { href: lead.email ? 'mailto:'+lead.email : '', wrap: true, copy: !!lead.email })
      + anBuildLeadDetailRowHtml('📞 Phone', lead.phone ? anPhoneDisplay(lead.phone) : '', { href: lead.phone ? 'tel:'+anTelPhone(lead.phone) : '', copy: !!lead.phone })
      + anBuildLeadDetailRowHtml('📍 State', leadState)
      + anBuildLeadDetailRowHtml('🌐 Preferred Language', anGetLeadLangLabel(lead.preferredLang || 'en'))
      + anBuildLeadDetailRowHtml('🏢 Size', sz ? sz.label : '')
      + anBuildLeadDetailRowHtml('🔗 Source', lead.source, { wrap: true })
      + anBuildLeadDetailRowHtml('📅 Next Follow-Up', lead.nextFollowUp ? anDate(lead.nextFollowUp) : '')
      + anBuildLeadDetailRowHtml('🔄 Status', st.label)
      + anBuildLeadDetailRowHtml('⏱ Last Contact', anTimeAgo(lead.lastContactDate || lead.created))
      + anBuildLeadDetailRowHtml('📆 Created', anDate(lead.created))
      +'</div>'

      + anBuildCompanyContactsSection(lead)
      + anBuildQuickLogSection(lead)
      + anBuildNameSoundSection(lead)
      + anBuildLeadIntelSection(lead)

      // Notes
      +(lead.notes?'<div style="background:var(--body-bg);border-radius:10px;padding:14px;margin-bottom:14px;">'
        +'<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:8px;">Notes</div>'
        +'<div style="font-size:13px;color:var(--text-secondary);line-height:1.7;">'+anEsc(lead.notes)+'</div>'
        +'</div>':'')

      // Call timeline
      +'<div style="margin-bottom:14px;">'
      +'<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:10px;">Activity Timeline</div>'
      +(calls.length ? calls.slice(0,10).map(function(c){
        var col = callColors[c.outcome]||'#a1a1aa';
        return '<div style="display:flex;gap:10px;padding:8px 0;border-bottom:1px solid var(--divider);">'
          +'<div style="width:28px;height:28px;border-radius:50%;background:'+col+'18;border:1.5px solid '+col+'44;display:flex;align-items:center;justify-content:center;font-size:12px;flex-shrink:0;">'+(callIcons[c.outcome]||'📞')+'</div>'
          +'<div style="flex:1;"><div style="font-size:12.5px;font-weight:700;color:var(--text-primary);">'+(c.outcome||'Call')+'</div>'
          +'<div style="font-size:11px;color:var(--text-muted);">'+anDate(c.date)+(c.time?' · '+c.time:'')+(c.duration?' · '+c.duration+'m':'')+'</div>'
          +(c.notes?'<div style="font-size:12px;color:var(--text-secondary);margin-top:3px;">'+anEsc(c.notes)+'</div>':'')
          +'</div></div>';
      }).join(''):'<div style="text-align:center;padding:20px;color:var(--text-muted);font-size:13px;">No activity logged yet</div>')
      +'</div>'
      +'</div>';
  }

  refreshPanel();
  if (typeof anInitLeadIntelUI === 'function') anInitLeadIntelUI(leadId);
  // Refresh after call logged
  window._anPanelLeadId = leadId;
};

window.anOpenLeadModal = window.anOpenLead; // alias

// ── Call Session lead context panel (full lead view beside call panel) ──
window.anCloseCallSessionLeadPanel = function() {
  var panel = document.getElementById('an-cs-lead-panel');
  if (panel) {
    if (panel._removeTimer) { clearTimeout(panel._removeTimer); panel._removeTimer = null; }
    panel.style.transform = 'translateX(100%)';
    panel._removeTimer = setTimeout(function(){
      if (panel.parentNode) panel.remove();
      panel._removeTimer = null;
    }, 260);
  }
  document.body.classList.remove('call-session-dual', 'call-lead-front');
};

window.anGetCompanyLeadsForRep = function(name) {
  var cn = (name || '').trim();
  if (!cn || typeof AN === 'undefined' || !Array.isArray(AN.leads)) return [];
  var leads = AN.leads.filter(function(l){ return (l.company || '').trim() === cn; });
  if (!AN.isAdmin) {
    leads = leads.filter(function(l){
      return typeof anRepOwnsLead === 'function' ? anRepOwnsLead(l) : (l._repEmail === AN.currentRepEmail);
    });
  }
  return leads;
};

window.anGetSessionVisitHistory = function() {
  var queue = typeof anGetActiveCallQueue === 'function' ? anGetActiveCallQueue() : null;
  if (queue && Array.isArray(queue.visitHistory) && queue.visitHistory.length) return queue.visitHistory;
  if (!AN._adhocVisitHistory) AN._adhocVisitHistory = [];
  return AN._adhocVisitHistory;
};

window.anTrackSessionVisit = function(leadId, opts) {
  opts = opts || {};
  if (!leadId || opts.fromBack || opts.skipHistory) return;
  var queue = typeof anGetActiveCallQueue === 'function' ? anGetActiveCallQueue() : null;
  if (queue) {
    if (!Array.isArray(queue.visitHistory)) queue.visitHistory = [];
    if (queue.visitHistory[queue.visitHistory.length - 1] !== leadId) queue.visitHistory.push(leadId);
    if (queue.visitHistory.length > 80) queue.visitHistory = queue.visitHistory.slice(-80);
    if (typeof anPersistCallQueue === 'function') anPersistCallQueue();
  } else {
    if (!AN._adhocVisitHistory) AN._adhocVisitHistory = [];
    if (AN._adhocVisitHistory[AN._adhocVisitHistory.length - 1] !== leadId) AN._adhocVisitHistory.push(leadId);
    if (AN._adhocVisitHistory.length > 80) AN._adhocVisitHistory = AN._adhocVisitHistory.slice(-80);
  }
};

window.anCanGoBackInSession = function(leadId) {
  var hist = anGetSessionVisitHistory();
  if (hist.length < 2) return false;
  var idx = hist.lastIndexOf(leadId);
  if (idx > 0) return true;
  return hist.length >= 2 && hist[0] !== leadId;
};

window.mcmPrevLead = function(leadId) {
  var hist = anGetSessionVisitHistory().slice();
  if (hist.length < 2) {
    if (typeof showToast === 'function') showToast('No previous contact in this session');
    return;
  }
  if (hist[hist.length - 1] === leadId) hist.pop();
  var prevId = hist[hist.length - 1];
  if (!prevId) {
    if (typeof showToast === 'function') showToast('No previous contact in this session');
    return;
  }
  var noteEl = document.getElementById('mcm-note');
  var overlay = document.getElementById('mcm-overlay');
  var dirty = (noteEl && noteEl.value.trim()) || (overlay && overlay._outcome);
  if (dirty && !confirm('Go back without logging this call? Unsaved notes and outcome will be lost.')) return;
  if (typeof anSwitchCallSessionLead === 'function') anSwitchCallSessionLead(prevId, { force: true, fromBack: true });
};

window.anSwitchCallSessionLead = function(targetId, opts) {
  opts = opts || {};
  if (!targetId) return;
  var overlay = document.getElementById('mcm-overlay');
  var currentId = overlay && overlay._leadId;
  if (currentId && currentId !== targetId && !opts.force) {
    var noteEl = document.getElementById('mcm-note');
    var dirty = (noteEl && noteEl.value.trim()) || (overlay && overlay._outcome);
    if (dirty && !confirm('Switch to this contact without logging the current call?')) return;
  }
  if (typeof openMobileCallMode === 'function') {
    openMobileCallMode(targetId, { fromBack: !!opts.fromBack, switchContact: true });
  }
};

window.anQuickAddCompanyContact = function(fromLeadId) {
  var from = AN.leads.find(function(l) { return l.id === fromLeadId; });
  if (!from) return;
  var company = (from.company || '').trim();
  if (!company) {
    if (typeof showToast === 'function') showToast('Add agency name first');
    return;
  }
  var firstName = prompt('First name of the person they mentioned:');
  if (!firstName || !firstName.trim()) return;
  var lastName = prompt('Last name (optional):') || '';
  var phone = prompt('Phone (optional):') || '';
  var title = prompt('Title / role (optional):') || '';
  var newLead = {
    id: 'l-' + Date.now(),
    firstName: firstName.trim(),
    lastName: (lastName || '').trim(),
    company: company,
    title: (title || '').trim(),
    phone: phone ? anNormalizePhone(phone) : '',
    email: '',
    state: typeof anResolveLeadState === 'function' ? anResolveLeadState(from) : (from.state || ''),
    preferredLang: from.preferredLang || 'en',
    size: from.size || '',
    source: 'Referral from ' + ((from.firstName || '') + ' ' + (from.lastName || '')).trim(),
    status: 'new',
    callLog: [],
    notes: 'Referred by ' + ((from.firstName || '') + ' ' + (from.lastName || '')).trim() + ' at ' + company,
    _repEmail: AN.currentRepEmail,
    created: new Date().toISOString(),
    updated: new Date().toISOString()
  };
  AN.leads.unshift(newLead);
  if (AN.save) AN.save();
  if (typeof renderLeadsTable === 'function') renderLeadsTable();
  if (typeof showToast === 'function') showToast('Added ' + newLead.firstName + ' — switching call');
  anSwitchCallSessionLead(newLead.id, { force: true });
};

window.anBuildCompanyContactsSection = function(lead) {
  var company = (lead.company || '').trim();
  if (!company) {
    return '<div style="background:var(--body-bg);border-radius:10px;padding:12px;margin-bottom:12px;border:1px dashed var(--divider);">'
      + '<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:6px;">👥 People at agency</div>'
      + '<div style="font-size:12px;color:var(--text-muted);line-height:1.5;">Save the agency name above — then you can jump to other contacts there or add someone they refer you to.</div>'
      + '</div>';
  }
  var contacts = anGetCompanyLeadsForRep(company).filter(function(l) { return l.id !== lead.id; });
  var rows = contacts.map(function(l) {
    var name = ((l.firstName || '') + ' ' + (l.lastName || '')).trim() || 'Unnamed';
    var lc = typeof anColor === 'function' ? anColor(name) : '#6366f1';
    var phone = l.phone ? anFormatPhone(l.phone) : '';
    return '<div style="display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid var(--divider);">'
      + '<div style="width:28px;height:28px;border-radius:50%;background:' + lc + '18;border:1.5px solid ' + lc + '33;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:' + lc + ';flex-shrink:0;">' + ((l.firstName || '?')[0].toUpperCase()) + '</div>'
      + '<div style="flex:1;min-width:0;cursor:pointer;" onclick="anSwitchCallSessionLead(\'' + l.id + '\')">'
      + '<div style="font-size:12.5px;font-weight:700;color:var(--text-primary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + anEsc(name) + '</div>'
      + '<div style="font-size:10.5px;color:var(--text-muted);">' + anEsc(l.title || 'No title') + (phone ? ' · ' + anEsc(phone) : '') + '</div>'
      + '</div>'
      + '<button type="button" onclick="event.stopPropagation();anSwitchCallSessionLead(\'' + l.id + '\',{force:true})" style="flex-shrink:0;background:#ecfdf5;color:#10b981;border:1px solid #a7f3d0;border-radius:6px;padding:5px 10px;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;">📞 Call</button>'
      + '</div>';
  }).join('');
  return '<div style="background:var(--body-bg);border-radius:10px;padding:12px;margin-bottom:12px;border:1px solid var(--divider);">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;gap:8px;">'
    + '<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;">👥 Also at ' + anEsc(company) + '</div>'
    + '<button type="button" onclick="anQuickAddCompanyContact(\'' + lead.id + '\')" style="background:#eef2ff;color:#6366f1;border:1px solid #c7d2fe;border-radius:6px;padding:4px 9px;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap;">+ Add person</button>'
    + '</div>'
    + (rows || '<div style="font-size:12px;color:var(--text-muted);padding:6px 0 8px;">No other contacts yet — add someone they refer you to.</div>')
    + '</div>';
};

window.anBuildQuickLogSection = function(lead) {
  if (!lead) return '';
  var id = lead.id;
  return '<div style="background:var(--body-bg);border-radius:10px;padding:12px;margin-bottom:12px;border:1px solid var(--divider);">'
    + '<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:8px;">⚡ Quick log (no full workflow)</div>'
    + '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;">'
    + ['noanswer:📵 No answer', 'voicemail:📬 VM', 'pickup:☎️ Pickup', 'emailed:✉️ Email', 'callback:⏰ Follow-up'].map(function(pair) {
      var p = pair.split(':');
      return '<button type="button" onclick="anQuickLogActivity(\'' + id + '\',\'' + p[0] + '\')" style="padding:6px 10px;border-radius:20px;border:1px solid var(--divider);background:var(--card-bg);color:var(--text-secondary);font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;">' + p[1] + '</button>';
    }).join('')
    + '</div>'
    + '<div style="display:flex;gap:6px;">'
    + '<input id="an-quick-note-' + id + '" type="text" placeholder="Quick note — press Enter to save" onkeydown="if(event.key===\'Enter\')anQuickLogActivity(\'' + id + '\',\'note\',this.value)" style="flex:1;border:1.5px solid var(--divider);border-radius:8px;padding:8px 10px;font-size:12px;background:var(--card-bg);color:var(--text-primary);outline:none;font-family:inherit;">'
    + '<button type="button" onclick="var el=document.getElementById(\'an-quick-note-' + id + '\');anQuickLogActivity(\'' + id + '\',\'note\',el?el.value:\'\')" style="background:#f4f4f5;color:#52525b;border:1px solid var(--divider);border-radius:8px;padding:8px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">Save</button>'
    + '</div>'
    + '<div style="font-size:10px;color:var(--text-muted);margin-top:6px;line-height:1.4;">Logs activity on this lead without advancing the queue. Use the call panel for full outcomes + demo booking.</div>'
    + '</div>';
};

window.anQuickLogActivity = function(leadId, outcome, noteArg) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  var overlay = document.getElementById('mcm-overlay');
  var inCall = overlay && overlay._leadId === leadId;
  var note = typeof noteArg === 'string' ? noteArg.trim() : '';
  if (!note && inCall) {
    var noteEl = document.getElementById('mcm-note');
    note = noteEl ? noteEl.value.trim() : '';
  }
  if (!note && outcome === 'note') {
    var qn = document.getElementById('an-quick-note-' + leadId);
    note = qn ? qn.value.trim() : '';
  }
  if (outcome === 'note' && !note) {
    if (typeof showToast === 'function') showToast('Type a note first');
    return;
  }
  if (inCall && typeof mcmSetOutcome === 'function' && outcome !== 'note') {
    mcmSetOutcome(outcome, leadId);
    if (note) {
      var mcmNote = document.getElementById('mcm-note');
      if (mcmNote) mcmNote.value = note;
    }
    if (typeof mcmSave === 'function') mcmSave(leadId, { keepOpen: true });
    return;
  }
  var now = new Date();
  var entry = {
    date: now.toISOString().split('T')[0],
    time: now.toTimeString().slice(0, 5),
    outcome: outcome === 'note' ? 'note' : outcome,
    notes: note || (outcome === 'note' ? '' : outcome),
    rep: AN.currentRepEmail || ''
  };
  if (!lead.callLog) lead.callLog = [];
  lead.callLog.unshift(entry);
  lead.lastContactDate = entry.date;
  if (note) {
    var stamp = now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
    var line = '[' + stamp + '] ' + note;
    lead.notes = lead.notes ? (lead.notes + '\n' + line) : line;
  }
  if (outcome === 'pickup' && lead.status === 'new') lead.status = 'contacted';
  if (outcome === 'callback') lead.status = 'followup';
  if (outcome === 'emailed') lead.status = 'emailed';
  lead.updated = now.toISOString();
  if (AN.save) AN.save();
  if (typeof anAfterLeadDataChange === 'function') anAfterLeadDataChange(leadId, { field: 'status' });
  else if (typeof renderLeadsTableNow === 'function') renderLeadsTableNow();
  else if (typeof renderLeadsTable === 'function') renderLeadsTable();
  if (typeof anRenderCallSessionLeadPanel === 'function') anRenderCallSessionLeadPanel(leadId);
  var qn2 = document.getElementById('an-quick-note-' + leadId);
  if (qn2) qn2.value = '';
  if (typeof showToast === 'function') showToast(outcome === 'note' ? 'Note saved' : 'Activity logged');
};

window.mcmSaveNoteOnly = function(leadId) {
  var noteEl = document.getElementById('mcm-note');
  var note = noteEl ? noteEl.value.trim() : '';
  if (!note) {
    if (typeof showToast === 'function') showToast('Type a note in the box first');
    if (noteEl) noteEl.focus();
    return;
  }
  anQuickLogActivity(leadId, 'note', note);
  if (noteEl) noteEl.value = '';
};

window.mcmRefreshSessionNavButtons = function(leadId) {
  var prevBtn = document.getElementById('mcm-btn-prev');
  if (!prevBtn) return;
  var canBack = typeof anCanGoBackInSession === 'function' && anCanGoBackInSession(leadId);
  prevBtn.disabled = !canBack;
  prevBtn.style.opacity = canBack ? '1' : '0.4';
  prevBtn.style.cursor = canBack ? 'pointer' : 'not-allowed';
};

window.anGetCsCompanyPanelRight = function() {
  if (window.innerWidth <= 900) return 0;
  var callW = 360;
  var leadW = document.body.classList.contains('call-lead-collapsed') ? 0 : (window.innerWidth <= 1200 ? 340 : 400);
  return callW + leadW;
};

window.anCloseCallSessionCompanyPanel = function() {
  var panel = document.getElementById('an-cs-company-panel');
  if (panel) {
    panel.style.transform = 'translateX(100%)';
    setTimeout(function(){ if (panel.parentNode) panel.remove(); }, 260);
  }
  var pill = document.getElementById('an-cs-company-pill');
  if (pill) pill.remove();
  document.body.classList.remove('call-company-open', 'call-company-front');
  window._anCsCompanyName = null;
  var btn = document.getElementById('mcm-company-toggle');
  if (btn) btn.style.background = 'rgba(255,255,255,0.08)';
};

window.anMinimizeCallSessionCompanyPanel = function() {
  var panel = document.getElementById('an-cs-company-panel');
  if (!panel) return;
  var name = panel.dataset.company || window._anCsCompanyName || '';
  panel.style.transform = 'translateX(100%)';
  setTimeout(function(){ if (panel.parentNode) panel.remove(); }, 260);
  document.body.classList.remove('call-company-front');

  var existingPill = document.getElementById('an-cs-company-pill');
  if (existingPill) existingPill.remove();

  var pill = document.createElement('button');
  pill.id = 'an-cs-company-pill';
  pill.type = 'button';
  pill.title = 'Restore agency profile';
  pill.onclick = function() { anRestoreCallSessionCompanyPanel(); };
  pill.style.cssText = 'position:fixed;bottom:18px;right:' + (anGetCsCompanyPanelRight() + 14) + 'px;z-index:19998;display:flex;align-items:center;gap:8px;background:linear-gradient(135deg,#0f172a,#1e293b);color:#fff;border:1px solid rgba(255,255,255,0.15);border-radius:24px;padding:8px 16px 8px 10px;font-size:12.5px;font-weight:700;font-family:var(--sans);cursor:pointer;box-shadow:0 4px 16px rgba(0,0,0,0.25);max-width:240px;';
  pill.innerHTML = '<span style="font-size:14px;">🏢</span><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + anEsc(name) + '</span><span style="opacity:0.5;font-size:10px;">▲</span>';
  document.body.appendChild(pill);
};

window.anRestoreCallSessionCompanyPanel = function() {
  var pill = document.getElementById('an-cs-company-pill');
  var name = pill ? pill.title && window._anCsCompanyName : window._anCsCompanyName;
  name = window._anCsCompanyName;
  if (pill) pill.remove();
  if (name && typeof anOpenCallSessionCompanyPanel === 'function') {
    anOpenCallSessionCompanyPanel(name);
  }
};

window.anRepositionCallSessionCompanyPanel = function() {
  var panel = document.getElementById('an-cs-company-panel');
  if (!panel) return;
  if (window.innerWidth <= 900) {
    panel.style.right = '0';
    panel.style.width = '100vw';
    panel.style.maxWidth = '100vw';
    return;
  }
  panel.style.right = anGetCsCompanyPanelRight() + 'px';
  panel.style.width = '380px';
  panel.style.maxWidth = 'calc(100vw - 380px)';
};

window.anBuildClickableCompanyHtml = function(companyName, style) {
  if (!companyName) return '';
  var escJs = String(companyName).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return '<span role="button" tabindex="0" onclick="event.stopPropagation();anOpenCallSessionCompanyPanel(\'' + escJs + '\')" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();anOpenCallSessionCompanyPanel(\'' + escJs + '\');}" style="' + (style || '') + 'cursor:pointer;text-decoration:underline;text-decoration-style:dotted;text-underline-offset:3px;" title="View agency profile">' + anEsc(companyName) + '</span>';
};

window.coDismissNativeMenus = function() {
  if (typeof coCloseAllLifeMenus === 'function') coCloseAllLifeMenus();
  if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
};

window.coCloseAllLifeMenus = function() {
  document.querySelectorAll('.co-life-menu').forEach(function(m) {
    m.style.display = 'none';
    if (m._coRestoreParent) {
      m._coRestoreParent.appendChild(m);
      m._coRestoreParent = null;
    }
    m.style.top = '';
    m.style.left = '';
    m.style.right = '';
    m.style.bottom = '';
  });
  if (window._coLifeMenuReposition) {
    window.removeEventListener('scroll', window._coLifeMenuReposition, true);
    window.removeEventListener('resize', window._coLifeMenuReposition);
    window._coLifeMenuReposition = null;
  }
};

window.coPositionLifeMenu = function(menu, btn) {
  if (!menu || !btn) return;
  menu.style.display = 'block';
  menu.style.visibility = 'hidden';
  if (menu.parentNode !== document.body) {
    menu._coRestoreParent = menu.parentNode;
    document.body.appendChild(menu);
  }
  var rect = btn.getBoundingClientRect();
  var menuW = menu.offsetWidth || 168;
  var menuH = menu.offsetHeight || 220;
  var gap = 6;
  var top = rect.bottom + gap;
  var left = rect.right - menuW;
  if (top + menuH > window.innerHeight - 8) top = rect.top - menuH - gap;
  if (top < 8) top = 8;
  if (left < 8) left = 8;
  if (left + menuW > window.innerWidth - 8) left = window.innerWidth - menuW - 8;
  menu.style.top = top + 'px';
  menu.style.left = left + 'px';
  menu.style.right = 'auto';
  menu.style.bottom = 'auto';
  menu.style.visibility = '';
};

window.coToggleLifeMenu = function(e, coId) {
  if (e) { e.preventDefault(); e.stopPropagation(); }
  var menu = document.getElementById('co-life-menu-' + coId);
  if (!menu) return;
  var wasOpen = menu.style.display === 'block' && menu.style.visibility !== 'hidden';
  coCloseAllLifeMenus();
  if (wasOpen) return;
  var btn = (e && e.currentTarget) || (menu.parentNode && menu.parentNode.querySelector('button'));
  if (!btn) return;
  coPositionLifeMenu(menu, btn);
  window._coLifeMenuReposition = function() {
    if (menu.style.display === 'block') coPositionLifeMenu(menu, btn);
    else coCloseAllLifeMenus();
  };
  window.addEventListener('scroll', window._coLifeMenuReposition, true);
  window.addEventListener('resize', window._coLifeMenuReposition);
};

window.coPickLifecycle = function(coId, stageId) {
  coCloseAllLifeMenus();
  if (typeof coSaveField === 'function') coSaveField(coId, 'lifecycleStage', stageId);
  if (typeof coOpenCompanyPanel === 'function') coOpenCompanyPanel(coId);
};

function coBuildLifecyclePicker(coId, currentVal) {
  var stage = typeof coNormalizeLifecycleStage === 'function' ? coNormalizeLifecycleStage(currentVal) : (currentVal || 'prospecting');
  var stageObj = CO_STAGES.find(function(s) { return s.id === stage; }) || CO_STAGES[0];
  return '<div class="co-life-picker" data-co-id="' + coId + '">'
    + '<button type="button" onclick="coToggleLifeMenu(event,\'' + coId + '\')" style="border:1.5px solid var(--divider);border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700;font-family:inherit;background:var(--card-bg);color:' + stageObj.color + ';cursor:pointer;white-space:nowrap;">' + (typeof coEsc === 'function' ? coEsc(stageObj.label) : stageObj.label) + ' ▾</button>'
    + '<div class="co-life-menu" id="co-life-menu-' + coId + '">'
    + CO_STAGES.map(function(s) {
      var active = s.id === stageObj.id;
      return '<button type="button" onclick="event.stopPropagation();coPickLifecycle(\'' + coId + '\',\'' + s.id + '\')" style="display:block;width:100%;text-align:left;padding:8px 12px;border:none;background:' + (active ? 'rgba(99,102,241,0.08)' : 'transparent') + ';color:' + s.color + ';font-size:12px;font-weight:' + (active ? '700' : '600') + ';cursor:pointer;font-family:inherit;">' + (active ? '✓ ' : '') + (typeof coEsc === 'function' ? coEsc(s.label) : s.label) + '</button>';
    }).join('')
    + '</div></div>';
}

if (!window._coLifeMenuBound) {
  window._coLifeMenuBound = true;
  document.addEventListener('click', function() { coCloseAllLifeMenus(); });
}

window.anOpenFullCompanyRecord = function(companyName) {
  companyName = (companyName || '').trim();
  if (!companyName) {
    if (typeof showToast === 'function') showToast('No company on file');
    return;
  }
  var inCall = !!(document.getElementById('mcm-panel-wrap') || document.body.classList.contains('call-panel-open'));
  var finishOpen = function(c) {
    if (typeof anCloseCallSessionCompanyPanel === 'function') anCloseCallSessionCompanyPanel();
    var oldDet = document.getElementById('co-detail-panel');
    if (oldDet) oldDet.remove();
    if (typeof coDismissNativeMenus === 'function') coDismissNativeMenus();
    if (inCall) {
      document.body.classList.add('co-full-record-over-call', 'call-lead-collapsed');
      document.body.classList.remove('call-lead-front', 'call-company-front');
    }
    if (c && typeof coOpenCompanyPanel === 'function') {
      if (!inCall && typeof showSection === 'function') showSection('companies');
      setTimeout(function() { coOpenCompanyPanel(c.id); }, inCall ? 40 : 120);
      return;
    }
    if (typeof showToast === 'function') showToast('Could not open company record');
  };
  var openRecord = function() {
    var key = typeof coNormName === 'function' ? coNormName(companyName) : companyName.toLowerCase();
    var c = (_coData || []).find(function(x) {
      return typeof coNormName === 'function' && coNormName(x.name) === key;
    });
    if (!c && typeof AN !== 'undefined' && Array.isArray(AN.leads)) {
      var ownerEmail = (AN.currentRepEmail || '').toLowerCase();
      AN.leads.forEach(function(l) {
        if (c || coNormName(l.company) !== key) return;
        c = {
          id: 'co-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
          name: companyName,
          industry: 'Insurance Agency',
          notes: '', website: '', lifecycleStage: 'prospecting',
          ownerEmail: (l._repEmail || ownerEmail).toLowerCase(),
          created: new Date().toISOString(),
          updated: new Date().toISOString(),
          updatedBy: ownerEmail
        };
      });
      if (c) {
        var list = (_coData || []).slice();
        list.push(c);
        if (typeof coSave === 'function') {
          coSave(list, function() { finishOpen(c); });
          return;
        }
        _coData = list;
      }
    }
    finishOpen(c);
  };
  if (typeof coEnsureSyncedFromLeads === 'function') coEnsureSyncedFromLeads(openRecord);
  else openRecord();
};

window.anOpenCallSessionCompanyPanel = function(name) {
  name = (name || '').trim();
  if (!name) {
    if (typeof showToast === 'function') showToast('No company on this lead — add agency name first');
    return;
  }
  if (!document.getElementById('mcm-panel-wrap') && !document.getElementById('an-cs-lead-panel')) {
    if (typeof openCompanyDetail === 'function') { openCompanyDetail(name); return; }
  }

  var leads = anGetCompanyLeadsForRep(name);
  var cd = typeof getCoData === 'function' ? getCoData(name) : { stage: 'prospecting', notes: '', industry: '' };
  var col = typeof anColor === 'function' ? anColor(name) : '#6366f1';
  var st = typeof coStage === 'function' ? coStage(cd.stage || 'prospecting') : { label: 'Prospecting', color: '#6366f1' };
  var totalCalls = leads.reduce(function(s, l){ return s + (l.callLog || []).length; }, 0);
  var dmReached = leads.filter(function(l){
    return (l.callLog || []).some(function(c){ return c.outcome === 'pickup' || c.outcome === 'demo' || c.outcome === 'connected'; });
  }).length;
  var currentLeadId = ((document.getElementById('mcm-overlay') || {})._leadId) || window._anCsLeadPanelId || '';
  var allCalls = [];
  leads.forEach(function(l){
    (l.callLog || []).forEach(function(c){
      allCalls.push(Object.assign({}, c, { _cname: (l.firstName || '') + ' ' + (l.lastName || ''), _lid: l.id }));
    });
  });
  allCalls.sort(function(a, b){ return (b.date + (b.time || '')).localeCompare(a.date + (a.time || '')); });
  var callColors = { pickup: '#10b981', demo: '#f59e0b', voicemail: '#6366f1', noanswer: '#a1a1aa', connected: '#10b981', emailed: '#8b5cf6' };
  var callIcons = { pickup: '☎️', demo: '🎯', voicemail: '📬', noanswer: '📵', connected: '☎️', emailed: '✉️' };
  var escName = name.replace(/\\/g, '\\\\').replace(/'/g, "\\'");

  var contactRows = leads.slice().sort(function(a, b){
    if (a.id === currentLeadId) return -1;
    if (b.id === currentLeadId) return 1;
    var ad = (a.callLog || []).some(function(c){ return c.outcome === 'pickup' || c.outcome === 'demo'; });
    var bd = (b.callLog || []).some(function(c){ return c.outcome === 'pickup' || c.outcome === 'demo'; });
    return (bd ? 1 : 0) - (ad ? 1 : 0);
  }).map(function(l) {
    var isCurrent = l.id === currentLeadId;
    var isDM = (l.callLog || []).some(function(c){ return c.outcome === 'pickup' || c.outcome === 'demo' || c.outcome === 'connected'; });
    var lastC = (l.callLog || []).slice().sort(function(a, b){ return b.date.localeCompare(a.date); })[0];
    var lc = typeof anColor === 'function' ? anColor((l.firstName || '') + (l.lastName || '')) : '#6366f1';
    return '<div onclick="anSwitchCallSessionLead(\'' + l.id + '\')" style="padding:10px 12px;border-bottom:1px solid var(--divider);display:flex;align-items:center;gap:9px;cursor:pointer;background:' + (isCurrent ? 'rgba(99,102,241,0.08)' : 'transparent') + ';" onmouseover="if(!' + isCurrent + ')this.style.background=\'var(--body-bg)\'" onmouseout="this.style.background=\'' + (isCurrent ? 'rgba(99,102,241,0.08)' : 'transparent') + '\'">'
      + '<div style="width:28px;height:28px;border-radius:50%;background:' + lc + '18;border:1.5px solid ' + lc + '33;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:' + lc + ';flex-shrink:0;">' + ((l.firstName || '?')[0].toUpperCase()) + '</div>'
      + '<div style="flex:1;min-width:0;">'
      + '<div style="font-size:12.5px;font-weight:700;color:var(--text-primary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + anEsc((l.firstName || '') + ' ' + (l.lastName || '')) + (isCurrent ? ' <span style="font-size:9px;color:#6366f1;">(on call)</span>' : '') + '</div>'
      + '<div style="font-size:10.5px;color:var(--text-muted);">' + (l.title ? anEsc(l.title) + ' · ' : '') + (lastC ? anTimeAgo(lastC.date) : 'No calls') + '</div>'
      + '</div>'
      + (isDM ? '<span style="font-size:9px;font-weight:700;background:#ecfdf5;color:#10b981;border-radius:4px;padding:2px 5px;flex-shrink:0;">DM</span>' : '')
      + '</div>';
  }).join('');

  var activityRows = allCalls.slice(0, 12).map(function(c) {
    var col2 = callColors[c.outcome] || '#a1a1aa';
    return '<div style="display:flex;gap:10px;padding:10px 0;border-bottom:1px solid var(--divider);">'
      + '<div style="width:26px;height:26px;border-radius:50%;background:' + col2 + '15;border:1.5px solid ' + col2 + '44;display:flex;align-items:center;justify-content:center;font-size:11px;flex-shrink:0;">' + (callIcons[c.outcome] || '📞') + '</div>'
      + '<div style="flex:1;min-width:0;">'
      + '<div style="font-size:11.5px;font-weight:600;color:var(--text-primary);">' + anEsc(c._cname) + ' <span style="color:' + col2 + ';font-weight:700;">' + (c.outcome || 'call') + '</span></div>'
      + '<div style="font-size:10px;color:var(--text-muted);">' + anDate(c.date) + (c.time ? ' · ' + c.time : '') + '</div>'
      + (c.notes ? '<div style="font-size:11px;color:var(--text-secondary);margin-top:3px;line-height:1.45;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + anEsc(c.notes) + '</div>' : '')
      + '</div></div>';
  }).join('');

  var existing = document.getElementById('an-cs-company-panel');
  if (existing) existing.remove();

  var panel = document.createElement('div');
  panel.id = 'an-cs-company-panel';
  panel.dataset.company = name;
  panel.style.cssText = 'position:fixed;top:0;right:' + anGetCsCompanyPanelRight() + 'px;bottom:0;width:380px;max-width:calc(100vw - 380px);background:var(--card-bg);box-shadow:-4px 0 40px rgba(0,0,0,0.12);z-index:19998;display:flex;flex-direction:column;overflow:hidden;transform:translateX(100%);transition:transform 0.26s cubic-bezier(0.16,1,0.3,1);';

  panel.innerHTML =
    '<div style="background:linear-gradient(135deg,#0f172a,#1e293b);padding:16px 18px;flex-shrink:0;">'
    + '<div style="display:flex;justify-content:space-between;align-items:flex-start;">'
    + '<div style="display:flex;gap:12px;align-items:center;min-width:0;">'
    + '<div style="width:38px;height:38px;border-radius:9px;background:' + col + '22;border:2px solid ' + col + '44;display:flex;align-items:center;justify-content:center;font-size:17px;font-weight:900;color:' + col + ';flex-shrink:0;">' + name[0].toUpperCase() + '</div>'
    + '<div style="min-width:0;">'
    + '<div style="font-size:10px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:3px;">Agency Profile</div>'
    + '<div style="font-size:16px;font-weight:800;color:#fff;letter-spacing:-0.3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + anEsc(name) + '</div>'
    + (cd.industry ? '<div style="font-size:11px;color:rgba(255,255,255,0.45);margin-top:2px;">' + anEsc(cd.industry) + '</div>' : '')
    + '</div></div>'
    + '<button onclick="anMinimizeCallSessionCompanyPanel()" title="Minimize" style="background:rgba(255,255,255,0.1);border:none;color:rgba(255,255,255,0.55);width:28px;height:28px;border-radius:7px;cursor:pointer;font-size:16px;flex-shrink:0;line-height:1;margin-right:4px;">–</button>'
    + '<button onclick="anCloseCallSessionCompanyPanel()" title="Close" style="background:rgba(255,255,255,0.1);border:none;color:rgba(255,255,255,0.55);width:28px;height:28px;border-radius:7px;cursor:pointer;font-size:14px;flex-shrink:0;">✕</button>'
    + '</div>'
    + '<div style="display:flex;gap:6px;margin-top:12px;flex-wrap:wrap;">'
    + '<span style="background:' + st.color + '22;color:' + st.color + ';border-radius:20px;padding:3px 10px;font-size:10px;font-weight:700;">' + st.label + '</span>'
    + '<span style="background:rgba(255,255,255,0.08);color:rgba(255,255,255,0.55);border-radius:20px;padding:3px 10px;font-size:10px;font-weight:600;">' + leads.length + ' contact' + (leads.length !== 1 ? 's' : '') + '</span>'
    + '<span style="background:rgba(16,185,129,0.15);color:#6ee7b7;border-radius:20px;padding:3px 10px;font-size:10px;font-weight:700;">' + dmReached + ' DM' + (dmReached !== 1 ? 's' : '') + ' reached</span>'
    + (typeof anAgencyTierBadgeHtml === 'function' ? anAgencyTierBadgeHtml(cd.agentCount, { showUnknown:true, fallbackLeads:leads }) : '')
    + '</div></div>'
    + '<div style="padding:12px 14px;border-bottom:1px solid var(--divider);flex-shrink:0;background:var(--body-bg);">'
    + '<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;color:var(--text-muted);margin-bottom:8px;">Before you dial</div>'
    + '<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px;">'
    + '<label style="font-size:11px;font-weight:600;color:var(--text-secondary);white-space:nowrap;"># of agents</label>'
    + '<input id="cs-co-agentcount" type="number" min="0" placeholder="?" value="' + (cd.agentCount ? anEsc(String(cd.agentCount)) : '') + '" onblur="typeof saveCoData===\'function\'&&saveCoData(\'' + escName + '\',{agentCount:this.value});typeof anOpenCallSessionCompanyPanel===\'function\'&&anOpenCallSessionCompanyPanel(\'' + escName + '\')" style="width:60px;border:1.5px solid var(--divider);border-radius:6px;padding:5px 8px;font-size:12px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);">'
    + '<span style="font-size:10.5px;color:var(--text-muted);">ask on call if unknown — updates badge above</span>'
    + '</div>'
    + '<div style="display:flex;gap:6px;flex-wrap:wrap;">'
    + '<a href="' + (cd.website ? (cd.website.indexOf('http')===0?anEsc(cd.website):'https://'+anEsc(cd.website)) : ('https://www.google.com/search?q=' + encodeURIComponent(name))) + '" target="_blank" rel="noopener" style="flex:1;min-width:90px;text-align:center;padding:7px 8px;border:1.5px solid var(--divider);border-radius:7px;background:var(--card-bg);color:var(--text-secondary);font-size:11px;font-weight:600;text-decoration:none;">🌐 ' + (cd.website ? 'Website' : 'Search') + '</a>'
    + '<a href="https://www.linkedin.com/search/results/companies/?keywords=' + encodeURIComponent(name) + '" target="_blank" rel="noopener" style="flex:1;min-width:90px;text-align:center;padding:7px 8px;border:1.5px solid var(--divider);border-radius:7px;background:var(--card-bg);color:var(--text-secondary);font-size:11px;font-weight:600;text-decoration:none;">in LinkedIn</a>'
    + '<a href="https://www.google.com/search?q=' + encodeURIComponent(name + ' insurance agency reviews') + '" target="_blank" rel="noopener" style="flex:1;min-width:90px;text-align:center;padding:7px 8px;border:1.5px solid var(--divider);border-radius:7px;background:var(--card-bg);color:var(--text-secondary);font-size:11px;font-weight:600;text-decoration:none;">🔍 Reviews</a>'
    + '</div>'
    + (!cd.website ? '<input id="cs-co-website" type="text" placeholder="Add website (e.g. acmeins.com)" onblur="if(this.value.trim()){typeof saveCoData===\'function\'&&saveCoData(\'' + escName + '\',{website:this.value.trim()});typeof anOpenCallSessionCompanyPanel===\'function\'&&anOpenCallSessionCompanyPanel(\'' + escName + '\')}" style="width:100%;margin-top:8px;border:1.5px solid var(--divider);border-radius:6px;padding:6px 9px;font-size:11.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);box-sizing:border-box;">' : '')
    + '</div>'
    + '<div style="display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid var(--divider);flex-shrink:0;">'
    + [{ l: 'Contacts', v: leads.length, c: '#6366f1' }, { l: 'Calls', v: totalCalls, c: '#f59e0b' }, { l: 'Reached', v: dmReached, c: '#10b981' }]
      .map(function(s, i){
        return '<div style="padding:10px;text-align:center;border-right:' + (i < 2 ? '1px solid var(--divider)' : 'none') + ';"><div style="font-size:18px;font-weight:900;color:' + s.c + ';">' + s.v + '</div><div style="font-size:9px;font-weight:700;text-transform:uppercase;color:var(--text-muted);margin-top:2px;">' + s.l + '</div></div>';
      }).join('')
    + '</div>'
    + '<div style="flex:1;overflow-y:auto;">'
    + '<div style="padding:12px 14px 6px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.12em;color:var(--text-muted);">Contacts at Agency</div>'
    + (contactRows || '<div style="padding:16px;text-align:center;color:var(--text-muted);font-size:12px;">No contacts</div>')
    + '<div style="padding:12px 14px 6px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.12em;color:var(--text-muted);border-top:1px solid var(--divider);margin-top:4px;">Recent Activity</div>'
    + '<div style="padding:0 14px 12px;">' + (activityRows || '<div style="padding:16px;text-align:center;color:var(--text-muted);font-size:12px;">No calls logged yet</div>') + '</div>'
    + '<div style="padding:12px 14px 6px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.12em;color:var(--text-muted);border-top:1px solid var(--divider);">Company Notes</div>'
    + '<div style="padding:0 14px 16px;">'
    + '<textarea id="cs-co-notes" rows="4" placeholder="Pain points, objections, agency size..." onblur="typeof saveCoData===\'function\'&&saveCoData(\'' + escName + '\',{notes:this.value})" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:10px;font-size:12px;color:var(--text-primary);background:var(--body-bg);outline:none;resize:vertical;font-family:var(--sans);line-height:1.6;box-sizing:border-box;">' + anEsc(cd.notes || '') + '</textarea>'
    + '</div></div>'
    + '<div style="padding:10px 14px;border-top:1px solid var(--divider);flex-shrink:0;display:flex;gap:6px;">'
    + '<button type="button" onclick="anOpenFullCompanyRecord(\'' + escName + '\')" style="flex:1;padding:8px;border:1.5px solid var(--divider);border-radius:8px;background:var(--card-bg);font-size:11px;font-weight:600;color:var(--text-secondary);cursor:pointer;font-family:var(--sans);touch-action:manipulation;">Open full record</button>'
    + '<button onclick="typeof anNewLeadForCompany===\'function\'&&anNewLeadForCompany(\'' + escName + '\')" style="flex:1;padding:8px;border:none;border-radius:8px;background:#6366f1;font-size:11px;font-weight:700;color:#fff;cursor:pointer;font-family:var(--sans);">+ Contact</button>'
    + '</div>';

  document.body.appendChild(panel);
  setTimeout(function(){ panel.style.transform = 'translateX(0)'; }, 10);
  document.body.classList.add('call-company-open');
  window._anCsCompanyName = name;
  var btn = document.getElementById('mcm-company-toggle');
  if (btn) btn.style.background = 'rgba(99,102,241,0.22)';
};

window.mcmToggleCompanyPanel = function(companyName) {
  if (document.body.classList.contains('call-company-open')) {
    anCloseCallSessionCompanyPanel();
    document.body.classList.remove('call-company-front');
    return;
  }
  var pill = document.getElementById('an-cs-company-pill');
  if (pill && window._anCsCompanyName) {
    anRestoreCallSessionCompanyPanel();
    return;
  }
  if (!companyName) {
    var ov = document.getElementById('mcm-overlay');
    var leadId = ov && ov._leadId;
    var lead = leadId && AN.leads && AN.leads.find(function(l){ return l.id === leadId; });
    companyName = lead && lead.company;
  }
  if (!companyName) {
    if (typeof anOpenCallSessionAddCompanyPanel === 'function') { anOpenCallSessionAddCompanyPanel(leadId); return; }
    if (typeof showToast === 'function') showToast('No agency on this lead — add one in the lead profile');
    if (window.innerWidth <= 900 && !document.body.classList.contains('call-lead-collapsed')) {
      document.body.classList.add('call-lead-front');
    } else if (window.innerWidth <= 900) {
      mcmToggleLeadPanel();
    }
    return;
  }
  document.body.classList.remove('call-lead-front');
  if (window.innerWidth <= 900) document.body.classList.add('call-company-front');
  anOpenCallSessionCompanyPanel(companyName);
};

window.anOpenCallSessionAddCompanyPanel = function(leadId) {
  var existing = document.getElementById('an-cs-company-panel');
  if (existing) existing.remove();
  var pill = document.getElementById('an-cs-company-pill');
  if (pill) pill.remove();
  var panel = document.createElement('div');
  panel.id = 'an-cs-company-panel';
  panel.style.cssText = 'position:fixed;top:0;right:' + anGetCsCompanyPanelRight() + 'px;bottom:0;width:380px;max-width:calc(100vw - 380px);background:var(--card-bg);box-shadow:-4px 0 40px rgba(0,0,0,0.12);z-index:19998;display:flex;flex-direction:column;overflow:hidden;transform:translateX(100%);transition:transform 0.26s cubic-bezier(0.16,1,0.3,1);';
  panel.innerHTML =
    '<div style="background:linear-gradient(135deg,#0f172a,#1e293b);padding:16px 18px;flex-shrink:0;display:flex;justify-content:space-between;align-items:flex-start;">'
    + '<div><div style="font-size:10px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:3px;">Agency Profile</div>'
    + '<div style="font-size:15px;font-weight:800;color:#fff;">No agency linked yet</div></div>'
    + '<button onclick="anCloseCallSessionCompanyPanel()" title="Close" style="background:rgba(255,255,255,0.1);border:none;color:rgba(255,255,255,0.55);width:28px;height:28px;border-radius:7px;cursor:pointer;font-size:14px;flex-shrink:0;">✕</button>'
    + '</div>'
    + '<div style="padding:18px;flex:1;overflow-y:auto;">'
    + '<div style="font-size:12px;color:var(--text-secondary);line-height:1.6;margin-bottom:14px;">This lead isn\'t tied to an agency yet. Link it to an existing one or create a new record — without leaving the call.</div>'
    + '<label style="font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.08em;">Agency name</label>'
    + '<input id="cs-add-co-input" type="text" placeholder="Start typing..." autocomplete="off" oninput="typeof anRefreshCsAddCompanySuggestions===\'function\'&&anRefreshCsAddCompanySuggestions(this.value)" style="width:100%;margin-top:6px;border:1.5px solid var(--divider);border-radius:8px;padding:10px;font-size:13px;color:var(--text-primary);background:var(--body-bg);outline:none;font-family:var(--sans);box-sizing:border-box;">'
    + '<div id="cs-add-co-matches" style="margin-top:10px;"></div>'
    + '<button type="button" onclick="anSaveCallSessionAddCompany(\'' + leadId + '\')" style="width:100%;margin-top:14px;padding:10px;border:none;border-radius:8px;background:#6366f1;font-size:12.5px;font-weight:700;color:#fff;cursor:pointer;font-family:var(--sans);">Link / Create Agency</button>'
    + '</div>';
  document.body.appendChild(panel);
  setTimeout(function(){ panel.style.transform = 'translateX(0)'; var inp = document.getElementById('cs-add-co-input'); if (inp) inp.focus(); }, 10);
  document.body.classList.add('call-company-open');
  var btn = document.getElementById('mcm-company-toggle');
  if (btn) btn.style.background = 'rgba(99,102,241,0.22)';
};

window.anRefreshCsAddCompanySuggestions = function(q) {
  var box = document.getElementById('cs-add-co-matches');
  if (!box) return;
  var matches = typeof anGetCompanyNameSuggestions === 'function' ? anGetCompanyNameSuggestions(q, 6) : [];
  if (!q || !q.trim() || !matches.length) { box.innerHTML = ''; return; }
  box.innerHTML = '<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.08em;margin-bottom:6px;">Existing agencies</div>'
    + matches.map(function(m) {
        var nm = typeof m === 'string' ? m : (m.name || m);
        var esc = String(nm).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
        return '<div onclick="document.getElementById(\'cs-add-co-input\').value=\'' + esc + '\';anRefreshCsAddCompanySuggestions(\'\')" style="padding:8px 10px;border:1px solid var(--divider);border-radius:7px;margin-bottom:5px;font-size:12px;color:var(--text-primary);cursor:pointer;background:var(--body-bg);">🏢 ' + (nm+'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</div>';
      }).join('');
};

window.anSaveCallSessionAddCompany = function(leadId) {
  var inp = document.getElementById('cs-add-co-input');
  var name = inp ? inp.value.trim() : '';
  if (!name) { if (typeof showToast === 'function') showToast('Type an agency name first'); if (inp) inp.focus(); return; }
  if (typeof anUpdateLeadCompany === 'function') anUpdateLeadCompany(leadId, name);
  if (typeof anOpenCallSessionCompanyPanel === 'function') anOpenCallSessionCompanyPanel(name);
};

window.anRefreshCallSessionCompanyPanel = function(leadId) {
  if (!document.body.classList.contains('call-company-open')) return;
  var lead = AN.leads && AN.leads.find(function(l){ return l.id === leadId; });
  var co = (lead && lead.company || '').trim();
  if (!co) { anCloseCallSessionCompanyPanel(); return; }
  anOpenCallSessionCompanyPanel(co);
};

window.anGetLeadActivityMeta = function() {
  return {
    icons: { pickup:'☎️', demo:'🎯', voicemail:'📬', noanswer:'📵', note:'📝', emailed:'✉️', callback:'⏰', connected:'☎️', objection:'🛡️', next_step:'📋', won:'🏆' },
    colors: { pickup:'#10b981', demo:'#f59e0b', voicemail:'#6366f1', noanswer:'#a1a1aa', note:'#06b6d4', emailed:'#8b5cf6', callback:'#06b6d4', connected:'#10b981', objection:'#f59e0b', next_step:'#06b6d4', won:'#10b981' },
    labels: { pickup:'Call — Picked Up', demo:'Demo Set', voicemail:'Voicemail', noanswer:'No Answer', emailed:'Email Sent', callback:'Follow Up', connected:'Connected', objection:'Objection', next_step:'Next Step', won:'Closed Won', note:'Note' }
  };
};

window.anRenderCallSessionLeadPanel = function(leadId) {
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  if (!lead) return;

  var old = document.getElementById('an-side-panel');
  if (old) old.remove();

  var panel = document.getElementById('an-cs-lead-panel');
  if (!panel) {
    panel = document.createElement('div');
    panel.id = 'an-cs-lead-panel';
    panel.style.cssText = 'position:fixed;top:0;right:360px;bottom:0;width:400px;max-width:calc(100vw - 360px);background:var(--card-bg);box-shadow:-4px 0 40px rgba(0,0,0,0.12);z-index:19999;display:flex;flex-direction:column;overflow:hidden;transform:translateX(100%);transition:transform 0.26s cubic-bezier(0.16,1,0.3,1);';
    document.body.appendChild(panel);
    setTimeout(function(){ panel.style.transform = 'translateX(0)'; }, 10);
  } else {
    if (panel._removeTimer) { clearTimeout(panel._removeTimer); panel._removeTimer = null; }
    panel.style.transform = 'translateX(0)';
  }

  document.body.classList.add('call-session-dual');

  var leadState = typeof anHydrateLeadState === 'function' ? anHydrateLeadState(lead) : (lead.state || '');

  var st = anStatus(lead.status || 'new');
  var sz = lead.size ? AN_SIZES.find(function(s){ return s.id === lead.size; }) : null;
  var meta = anGetLeadActivityMeta();
  var calls = (lead.callLog || []).slice().sort(function(a, b){ return (b.date + (b.time || '')).localeCompare(a.date + (a.time || '')); });
  var totalCalls = calls.filter(function(c){ return c.outcome !== 'emailed'; }).length;
  var pickups = calls.filter(function(c){ return c.outcome === 'pickup' || c.outcome === 'demo' || c.outcome === 'connected'; }).length;
  var emailsSent = calls.filter(function(c){ return c.outcome === 'emailed'; }).length;
  var mode = (typeof anGetCallPanelMode === 'function') ? anGetCallPanelMode(lead) : 'lead';
  var modeLabel = mode === 'opportunity' ? 'Deal' : 'Lead';
  var csLang = lead.preferredLang || 'en';
  var csLangLabel = anGetLeadLangLabel(csLang);
  var csLangHighlight = csLang !== 'en';
  var csMetaRow = '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;align-items:center;">'
    +'<span style="display:inline-flex;align-items:center;gap:5px;background:'+(leadState ? 'rgba(99,102,241,0.18)' : 'rgba(255,255,255,0.06)')+';border:1px solid '+(leadState ? 'rgba(99,102,241,0.4)' : 'rgba(255,255,255,0.12)')+';border-radius:20px;padding:3px 11px;font-size:11px;font-weight:700;color:'+(leadState ? '#c7d2fe' : 'rgba(255,255,255,0.45)')+';">📍 '+anEsc(leadState || 'State not set')+'</span>'
    +'<span style="display:inline-flex;align-items:center;gap:4px;background:'+(csLangHighlight?'rgba(245,158,11,0.18)':'rgba(255,255,255,0.06)')+';border:1px solid '+(csLangHighlight?'rgba(245,158,11,0.45)':'rgba(255,255,255,0.12)')+';border-radius:20px;padding:3px 10px;font-size:11px;font-weight:700;color:'+(csLangHighlight?'#fcd34d':'rgba(255,255,255,0.65)')+';" title="Speak in this language">🌐 '+anEsc(csLangLabel)+'</span>'
    +'</div>';

  panel.innerHTML =
    '<div style="background:linear-gradient(135deg,#0a0a14,#1a1640);padding:16px 18px;flex-shrink:0;">'
    +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px;">'
    +'<div>'
    +'<div style="font-size:10px;font-weight:700;color:#a5b4fc;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;">'+modeLabel+' Profile</div>'
    +'<div style="font-size:17px;font-weight:800;color:#fff;letter-spacing:-0.4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+anEsc((lead.firstName || '') + ' ' + (lead.lastName || ''))+'</div>'
    +(lead.title ? '<div style="font-size:11px;color:rgba(255,255,255,0.55);margin-top:2px;">'+anEsc(lead.title)+'</div>' : '')
    +(lead.company
      ? '<div style="font-size:12px;color:rgba(255,255,255,0.5);margin-top:2px;">'+(typeof anBuildClickableCompanyHtml === 'function' ? anBuildClickableCompanyHtml(lead.company, 'color:rgba(255,255,255,0.55);') : anEsc(lead.company))+'</div>'
      : '<div style="font-size:11px;color:#fcd34d;margin-top:2px;">No agency on file</div>')
    +csMetaRow
    +'</div>'
    +'<div style="display:flex;gap:6px;align-items:center;">'
    +'<span style="background:'+st.color+'28;color:'+st.color+';border-radius:20px;padding:4px 11px;font-size:10px;font-weight:700;">'+st.label+'</span>'
    +'<button type="button" id="mcm-lead-panel-hide" onclick="mcmToggleLeadPanel()" title="Hide lead profile" style="display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,0.1);border:none;color:rgba(255,255,255,0.55);width:26px;height:26px;border-radius:6px;cursor:pointer;font-size:13px;line-height:1;">✕</button>'
    +'</div></div>'
    +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:7px;">'
    +'<div style="background:rgba(255,255,255,0.06);border-radius:8px;padding:7px;text-align:center;"><div style="font-size:16px;font-weight:800;color:#fff;">'+totalCalls+'</div><div style="font-size:9px;color:rgba(255,255,255,0.4);text-transform:uppercase;">Calls</div></div>'
    +'<div style="background:rgba(255,255,255,0.06);border-radius:8px;padding:7px;text-align:center;"><div style="font-size:16px;font-weight:800;color:#10b981;">'+pickups+'</div><div style="font-size:9px;color:rgba(255,255,255,0.4);text-transform:uppercase;">Pickups</div></div>'
    +'<div style="background:rgba(255,255,255,0.06);border-radius:8px;padding:7px;text-align:center;"><div style="font-size:16px;font-weight:800;color:#8b5cf6;">'+emailsSent+'</div><div style="font-size:9px;color:rgba(255,255,255,0.4);text-transform:uppercase;">Emails</div></div>'
    +'</div></div>'

    +'<div style="padding:10px 14px;border-bottom:1px solid var(--divider);display:flex;gap:6px;flex-shrink:0;flex-wrap:wrap;">'
    +'<button onclick="anLogCall(\''+lead.id+'\')" style="flex:1;min-width:90px;background:#ecfdf5;color:#10b981;border:1px solid #a7f3d0;border-radius:8px;padding:7px;font-size:11px;font-weight:700;cursor:pointer;font-family:var(--sans);">⚡ Activity</button>'
    +'<button onclick="anOpenSendEmail({name:\''+anEsc((lead.firstName||'')+' '+(lead.lastName||'')).trim()+'\',email:\''+anEsc(lead.email||'')+'\',leadId:\''+lead.id+'\'})" style="flex:1;min-width:90px;background:#f5f3ff;color:#8b5cf6;border:1px solid #ddd6fe;border-radius:8px;padding:7px;font-size:11px;font-weight:700;cursor:pointer;font-family:var(--sans);">📧 Send Email</button>'
    +'<button onclick="anOpenBookMeeting({name:\''+anEsc((lead.firstName||'')+' '+(lead.lastName||'')).trim()+'\',email:\''+anEsc(lead.email||'')+'\',leadId:\''+lead.id+'\'})" style="flex:1;min-width:90px;background:#fff7ed;color:#ea580c;border:1px solid #fed7aa;border-radius:8px;padding:7px;font-size:11px;font-weight:700;cursor:pointer;font-family:var(--sans);">📅 Meeting</button>'
    +'<button onclick="anOpenLeadModal(\''+lead.id+'\')" style="flex:1;min-width:70px;background:#eef2ff;color:#6366f1;border:1px solid #c7d2fe;border-radius:8px;padding:7px;font-size:11px;font-weight:700;cursor:pointer;font-family:var(--sans);">✏️ Edit</button>'
    +'</div>'

    +'<div style="flex:1;overflow-y:auto;padding:14px 16px;">'

    + anBuildLeadOwnerCardHtml(lead)

    + anBuildCompanyContactsSection(lead)

    + anBuildQuickLogSection(lead)

    + anBuildNameSoundSection(lead)

    + anBuildLeadIntelSection(lead)

    +'<div style="background:var(--body-bg);border-radius:10px;padding:12px;margin-bottom:12px;">'
    +'<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:8px;">Contact</div>'
    +'<div style="margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--divider);">'
    +'<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">📍 State</div>'
    +(leadState ? '<div style="font-size:12.5px;font-weight:600;color:var(--text-primary);margin-bottom:6px;">'+anEsc(leadState)+'</div>' : '<div style="font-size:11px;color:#b45309;margin-bottom:6px;">Not set — pick their state</div>')
    +'<select id="cs-state-select" onchange="anUpdateLeadState(\''+lead.id+'\', this.value)" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:7px 10px;font-size:12px;background:var(--card-bg);color:var(--text-primary);outline:none;font-family:var(--sans);cursor:pointer;">'
    +anBuildLeadStateOptions(leadState)
    +'</select>'
    +'</div>'
    +'<div style="margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--divider);">'
    +'<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">🏢 Company / Agency</div>'
    +(lead.company ? '<div style="font-size:12.5px;font-weight:600;color:var(--text-primary);margin-bottom:6px;">'+anEsc(lead.company)+'</div>' : '<div style="font-size:11px;color:#b45309;margin-bottom:6px;">Not set — add if they tell you on the call</div>')
    +'<div style="display:flex;gap:6px;">'
    +'<input id="cs-company-input" type="text" value="'+anEsc(lead.company||'')+'" placeholder="Agency name" style="flex:1;border:1.5px solid var(--divider);border-radius:8px;padding:7px 10px;font-size:12px;background:var(--card-bg);color:var(--text-primary);outline:none;font-family:var(--sans);">'
    +'<button type="button" onclick="anUpdateLeadCompany(\''+lead.id+'\', document.getElementById(\'cs-company-input\').value)" style="background:#eef2ff;color:#6366f1;border:1px solid #c7d2fe;border-radius:8px;padding:7px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:var(--sans);">Save</button>'
    +'</div></div>'
    +'<div style="margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--divider);">'
    +'<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">💼 Title / Role</div>'
    +(lead.title ? '<div style="font-size:12.5px;font-weight:600;color:var(--text-primary);margin-bottom:6px;">'+anEsc(lead.title)+'</div>' : '<div style="font-size:11px;color:#b45309;margin-bottom:6px;">Not set — Owner, Agent, etc.</div>')
    +'<div style="display:flex;gap:6px;">'
    +'<input id="cs-title-input" type="text" value="'+anEsc(lead.title||'')+'" placeholder="Owner, Agent, Producer..." style="flex:1;border:1.5px solid var(--divider);border-radius:8px;padding:7px 10px;font-size:12px;background:var(--card-bg);color:var(--text-primary);outline:none;font-family:var(--sans);">'
    +'<button type="button" onclick="anUpdateLeadTitle(\''+lead.id+'\', document.getElementById(\'cs-title-input\').value)" style="background:#f5f3ff;color:#7c3aed;border:1px solid #c4b5fd;border-radius:8px;padding:7px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:var(--sans);">Save</button>'
    +'</div>'
    + anBuildTitleQuickPicksLight(lead.id, 'cs-title-input')
    +'</div>'
    +'<div style="padding:8px 0;border-bottom:1px solid var(--divider);">'
    +'<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">🌐 Preferred Language</div>'
    +'<select id="cs-lang-select" onchange="anUpdateLeadPreferredLang(\''+lead.id+'\', this.value)" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:7px 10px;font-size:12px;background:var(--card-bg);color:var(--text-primary);outline:none;font-family:var(--sans);cursor:pointer;">'
    +anBuildLeadLangOptions(lead.preferredLang || 'en')
    +'</select>'
    +'<div style="font-size:10px;color:var(--text-muted);margin-top:5px;line-height:1.4;">So the next rep knows what language to use on the call.</div>'
    +'</div>'
    +(lead.phone
      ? '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid var(--divider);">'
        +'<span style="font-size:12px;color:var(--text-muted);">📞 Phone</span>'
        +'<span style="display:flex;align-items:center;gap:6px;">'
        +'<a href="tel:'+anTelPhone(lead.phone)+'" style="font-size:12.5px;font-weight:600;color:#6366f1;text-decoration:none;">'+anEsc(anFormatPhone(lead.phone))+'</a>'
        +'<button onclick="anCopyToClipboard(\''+anEsc(lead.phone)+'\')" title="Copy phone" style="background:none;border:1px solid var(--divider);border-radius:4px;padding:1px 6px;font-size:10px;color:var(--text-muted);cursor:pointer;">📋</button>'
        +'</span></div>'
      : '')
    +(lead.email
      ? '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid var(--divider);">'
        +'<span style="font-size:12px;color:var(--text-muted);">📧 Email</span>'
        +'<span style="display:flex;align-items:center;gap:6px;">'
        +'<a href="mailto:'+anEsc(lead.email)+'" style="font-size:12.5px;font-weight:600;color:#6366f1;text-decoration:none;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+anEsc(lead.email)+'</a>'
        +'<button onclick="anCopyToClipboard(\''+anEsc(lead.email)+'\')" title="Copy email" style="background:none;border:1px solid var(--divider);border-radius:4px;padding:1px 6px;font-size:10px;color:var(--text-muted);cursor:pointer;">📋</button>'
        +'</span></div>'
      : '')
    +'</div>'

    +(lead.notes
      ? '<div style="background:var(--body-bg);border-radius:10px;padding:12px;margin-bottom:12px;">'
        +'<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:6px;">Notes</div>'
        +'<div style="font-size:12.5px;color:var(--text-secondary);line-height:1.65;white-space:pre-wrap;max-height:140px;overflow-y:auto;">'+anEsc(lead.notes)+'</div>'
        +'</div>'
      : '<div style="background:var(--body-bg);border-radius:10px;padding:12px;margin-bottom:12px;text-align:center;color:var(--text-muted);font-size:12px;">No notes yet — log calls or add a quick note in the call panel.</div>')

    +'<div style="margin-bottom:8px;">'
    +'<div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:8px;">Activity — calls & emails</div>'
    +(calls.length ? calls.slice(0, 15).map(function(c){
      var col = meta.colors[c.outcome] || '#a1a1aa';
      var label = meta.labels[c.outcome] || c.outcome || 'Activity';
      return '<div style="display:flex;gap:9px;padding:7px 0;border-bottom:1px solid var(--divider);">'
        +'<div style="width:26px;height:26px;border-radius:50%;background:'+col+'18;border:1.5px solid '+col+'44;display:flex;align-items:center;justify-content:center;font-size:11px;flex-shrink:0;">'+(meta.icons[c.outcome] || '📋')+'</div>'
        +'<div style="flex:1;min-width:0;"><div style="font-size:12px;font-weight:700;color:var(--text-primary);">'+label+'</div>'
        +'<div style="font-size:10px;color:var(--text-muted);">'+anDate(c.date)+(c.time ? ' · '+c.time : '')+(c.duration ? ' · '+c.duration+'m' : '')+'</div>'
        +(c.notes ? '<div style="font-size:11px;color:var(--text-secondary);margin-top:2px;line-height:1.45;">'+anEsc(c.notes)+'</div>' : '')
        +'</div></div>';
    }).join('') : '<div style="text-align:center;padding:18px;color:var(--text-muted);font-size:12px;">No activity logged yet</div>')
    +'</div>'
    +'</div>';

  window._anCsLeadPanelId = leadId;
  if (typeof anInitLeadIntelUI === 'function') anInitLeadIntelUI(leadId);
};

window.anQuickLogEmail = function(leadId, note) {
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  if (!lead) return;
  var overlay = document.getElementById('mcm-overlay');
  if (overlay) {
    if (typeof mcmSetOutcome === 'function') mcmSetOutcome('emailed', leadId);
    var noteEl = document.getElementById('mcm-note');
    var noteText = (note || '').trim() || 'Email sent';
    if (noteEl) noteEl.value = noteText;
    if (typeof showToast === 'function') showToast('✉️ Email outcome set — click Save & Next to log & continue');
    if (lead.email) { try { window.open('mailto:' + lead.email, '_blank'); } catch(e) {} }
    return;
  }
  var now = new Date();
  var entry = {
    date: now.toISOString().split('T')[0],
    time: now.toTimeString().slice(0, 5),
    outcome: 'emailed',
    notes: (note || '').trim() || 'Email sent',
    rep: (typeof AN !== 'undefined' && AN.currentRepEmail) || ''
  };
  if (!lead.callLog) lead.callLog = [];
  lead.callLog.unshift(entry);
  lead.lastContactDate = entry.date;
  if (['new', 'contacted', 'followup'].indexOf(lead.status || 'new') >= 0) lead.status = 'emailed';
  lead.updated = now.toISOString();
  if (typeof AN !== 'undefined' && AN.save) AN.save();
  anRenderCallSessionLeadPanel(leadId);
  if (typeof renderLeadsTable === 'function') renderLeadsTable();
  if (typeof showToast === 'function') showToast('✉️ Email logged');
  if (lead.email) { try { window.open('mailto:' + lead.email, '_blank'); } catch(e) {} }
};

// ── 4. OPPORTUNITIES SECTION ──────────────────────────────────
window.renderOpportunities = function() {
  var sec = document.getElementById('section-opportunities');
  if (!sec) return;

  // Opportunities = leads with status demo, showed, proposal, won
  var opps = AN.leads.filter(function(l){
    return ['demo','showed','proposal','won'].indexOf(l.status||'new') >= 0;
  });
  if (!AN.isAdmin) opps = opps.filter(function(l){ return typeof anRepOwnsLead === 'function' ? anRepOwnsLead(l) : (l._repEmail === AN.currentRepEmail); });

  var stages = [
    {id:'demo',     label:'Demo Set',   color:'#8b5cf6'},
    {id:'showed',   label:'Showed',     color:'#06b6d4'},
    {id:'proposal', label:'Proposal',   color:'#3b82f6'},
    {id:'won',      label:'Closed Won', color:'#10b981'}
  ];

  // Stats
  var totalValue = opps.reduce(function(s,o){
    var sz = AN_SIZES.find(function(x){return x.id===o.size;})||{price:79};
    return s + sz.price;
  }, 0);
  var wonCount = opps.filter(function(o){return o.status==='won';}).length;

  var statsHTML = '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px;">'
    +[
      {label:'Total Opportunities', val:opps.length, color:'#6366f1'},
      {label:'Pipeline MRR', val:'$'+totalValue+'/mo', color:'#10b981'},
      {label:'Closed Won', val:wonCount, color:'#f59e0b'},
      {label:'Win Rate', val:opps.length>0?Math.round(wonCount/opps.length*100)+'%':'—', color:'#8b5cf6'}
    ].map(function(s){
      return '<div style="background:var(--card-bg);border:1px solid var(--divider);border-radius:12px;padding:16px;text-align:center;">'
        +'<div style="font-size:9px;font-weight:700;color:'+s.color+';text-transform:uppercase;letter-spacing:0.12em;margin-bottom:6px;">'+s.label+'</div>'
        +'<div style="font-size:24px;font-weight:900;color:var(--text-primary);letter-spacing:-1px;">'+s.val+'</div>'
        +'</div>';
    }).join('')
    +'</div>';

  // Kanban board
  var kanbanHTML = '<div style="display:flex;gap:12px;overflow-x:auto;padding-bottom:16px;">'
    +stages.map(function(stage){
      var stageLead = opps.filter(function(o){return o.status===stage.id;});
      var stageVal  = stageLead.reduce(function(s,o){ var sz=AN_SIZES.find(function(x){return x.id===o.size;})||{price:79}; return s+sz.price; },0);
      var cards = stageLead.map(function(opp){
        var sz = opp.size ? (AN_SIZES.find(function(s){return s.id===opp.size;})||{label:opp.size,price:79}) : {label:'Solo',price:79};
        var calls = (opp.callLog||[]).length;
        return '<div onclick="anOpenLeadPanel(\''+opp.id+'\')" style="background:var(--card-bg);border:1px solid var(--divider);border-radius:10px;padding:14px;margin-bottom:8px;cursor:pointer;border-left:3px solid '+stage.color+';transition:box-shadow 0.15s;" onmouseover="this.style.boxShadow=\'0 4px 16px rgba(0,0,0,0.1)\'" onmouseout="this.style.boxShadow=\'none\'">'
          +'<div style="font-size:13.5px;font-weight:700;color:var(--text-primary);margin-bottom:2px;">'+anEsc((opp.firstName||'')+' '+(opp.lastName||''))+'</div>'
          +(opp.company?'<div style="font-size:12px;color:var(--text-muted);">'+anEsc(opp.company)+'</div>':'')
          +'<div style="display:flex;justify-content:space-between;align-items:center;margin-top:8px;">'
          +'<span style="font-size:12px;font-weight:700;color:'+stage.color+';">$'+sz.price+'/mo</span>'
          +'<span style="font-size:11px;color:var(--text-muted);">'+calls+' calls</span>'
          +'</div>'
          +(opp.nextFollowUp?'<div style="font-size:11px;color:#6366f1;margin-top:5px;">📅 '+anDate(opp.nextFollowUp)+'</div>':'')
          +(anShowOwnerColumn()?'<div onclick="event.stopPropagation();anOpenOwnerPicker({leadId:\''+opp.id+'\'})" style="font-size:10px;color:var(--text-muted);margin-top:4px;cursor:pointer;" title="Change owner">👤 '+anEsc(opp._repEmail?anGetRepName(opp._repEmail):'Assign owner')+' ▾</div>':'')
          +'</div>';
      }).join('');

      return '<div style="flex:0 0 240px;">'
        +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;padding:8px 10px;background:var(--body-bg);border-radius:8px;">'
        +'<div style="display:flex;align-items:center;gap:6px;">'
        +'<span style="width:8px;height:8px;border-radius:50%;background:'+stage.color+';"></span>'
        +'<span style="font-size:12.5px;font-weight:700;color:var(--text-primary);">'+stage.label+'</span>'
        +'<span style="background:var(--card-bg);border:1px solid var(--divider);border-radius:10px;padding:1px 7px;font-size:11px;color:var(--text-muted);">'+stageLead.length+'</span>'
        +'</div>'
        +'<span style="font-size:11px;font-weight:600;color:'+stage.color+';">$'+stageVal+'/mo</span>'
        +'</div>'
        +(cards||'<div style="text-align:center;padding:24px 10px;color:var(--text-muted);font-size:12px;">No opportunities</div>')
        +'</div>';
    }).join('')
    +'</div>';

  sec.innerHTML = '<div class="page-header">'
    +'<div class="page-label">Pipeline</div>'
    +'<h1>Opportunities</h1>'
    +''
    +'</div>'
    +'<div class="content">'
    + statsHTML
    + '<div style="font-size:13px;font-weight:700;color:var(--text-primary);margin-bottom:14px;">Pipeline Board</div>'
    + kanbanHTML
    +'</div>';
};

// Convert a lead to opportunity (moves status to demo if needed)
window.anConvertToOpportunity = function(leadId) {
  var lead = AN.leads.find(function(l){ return l.id===leadId; });
  if (!lead) return;
  if (['demo','showed','proposal','won'].indexOf(lead.status) < 0) {
    lead.status = 'demo';
    lead.updated = new Date().toISOString();
    AN.save();
    if (typeof showToast === 'function') showToast('Moved to Opportunities pipeline');
    // Close side panel and open opportunities
    var panel = document.getElementById('an-side-panel');
    if (panel) { panel.style.transform='translateX(100%)'; setTimeout(function(){panel.remove();},300); }
    setTimeout(function(){ if(typeof showSection==='function') showSection('opportunities'); }, 400);
  } else {
    if (typeof showSection === 'function') showSection('opportunities');
  }
};

// ── 5. WIRE showSection for opportunities ─────────────────────
var _origShowSection_opp = window.showSection;
window.showSection = function(id, btn) {
  _origShowSection_opp(id, btn);
  if (id === 'opportunities') {
    setTimeout(function(){
      if (typeof renderOpportunities === 'function') renderOpportunities();
    }, 50);
  }
};

// ── 6. PATCH renderLeadsTable to add data-field attrs ─────────
// Override to add data-lead-id on tr and data-field on editable tds
var _origRLT2 = window.renderLeadsTable;
window.renderLeadsTable = function() {
  _origRLT2 && _origRLT2();
  attachInlineEdit();
};

console.log('[UNIFIED CRM] Inline edit, side panel, opportunities, dashboard sync loaded.');

// ─── inline block 27 ───────────────────────
// ============================================================
// NAV COLLAPSE + COLLAPSIBLE GROUPS + OPP CONVERSION POPUP
// DRAGGABLE KANBAN + COMPANY VIEW + CRM IMPROVEMENTS
// ============================================================

// ── 1. SIDEBAR COLLAPSE ───────────────────────────────────────
var _sidebarCollapsed = false;

window._navGoComm  = function(){ if(typeof showSection==='function') showSection('commission'); };
window._navGoAdmin = function(){ if(typeof showSection==='function') showSection('admin'); };

window.toggleSidebar = function() {
  _sidebarCollapsed = !_sidebarCollapsed;
  var sb  = document.getElementById('sidebar');
  var btn = document.getElementById('nav-collapse-btn');
  if (!sb) return;

  if (_sidebarCollapsed) {
    document.body.classList.add('sb-collapsed');
    if (btn) btn.innerHTML = '›';

    // Theme toggle — icon only
    var themeBtn = sb.querySelector('.theme-toggle-btn');
    if (themeBtn) { themeBtn._origHTML = themeBtn.innerHTML; themeBtn.innerHTML = '<span style="font-size:16px;margin:0 auto;">'+(document.body.classList.contains('dark-mode')?'🌙':'☀️')+'</span>'; themeBtn.style.justifyContent='center'; themeBtn.style.padding='8px 0'; themeBtn.title='Toggle theme'; }

    // Logo — hide image, show nothing
    sb.querySelectorAll('.sidebar-brand img,.sidebar-brand .brand-icon').forEach(function(el){ el.style.display='none'; });

    // Commission plan
    var commWrap = document.getElementById('nav-commission-wrap');
    if (commWrap) { commWrap._origHTML = commWrap.innerHTML; commWrap.innerHTML = '<button onclick="window._navGoComm()" title="Commission Plan" style="width:100%;background:rgba(16,185,129,0.1);border:none;color:#6ee7b7;border-radius:6px;padding:9px 0;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;">💰</button>'; }

    // Admin panel
    var adminWrap = document.getElementById('nav-admin-wrap');
    if (adminWrap) { adminWrap._origHTML = adminWrap.innerHTML; adminWrap.innerHTML = '<button onclick="window._navGoAdmin()" title="Admin Panel" style="width:100%;background:rgba(239,68,68,0.1);border:none;color:#fca5a5;border-radius:6px;padding:9px 0;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;">⚙️</button>'; }

    // User area
    sb.querySelectorAll('.sidebar-user-info,.sidebar-user-signout').forEach(function(el){ el.style.display='none'; });
    var authBtn = sb.querySelector('.sidebar-auth-btn');
    if (authBtn) { authBtn._origHTML = authBtn.innerHTML; authBtn.innerHTML = '<span style="font-size:20px;">👤</span>'; authBtn.style.justifyContent='center'; }

    // Nav group icons — hide the chevrons
    sb.querySelectorAll('[id$="-icon"]').forEach(function(el){ el.style.display='none'; });

    // Add tooltips to all nav items
    sb.querySelectorAll('.nav-item').forEach(function(item) {
      var label = item.querySelector('.nav-label');
      if (!label) return;
      var tip = document.createElement('span');
      tip.className = 'nav-tooltip';
      tip.textContent = label.textContent.trim();
      item.appendChild(tip);
    });

  } else {
    document.body.classList.remove('sb-collapsed');
    if (btn) btn.innerHTML = '‹';

    // Restore all
    var themeBtn = sb.querySelector('.theme-toggle-btn');
    if (themeBtn && themeBtn._origHTML) { themeBtn.innerHTML = themeBtn._origHTML; themeBtn.style.justifyContent=''; themeBtn.style.padding=''; }

    sb.querySelectorAll('.sidebar-brand img,.sidebar-brand .brand-icon').forEach(function(el){ el.style.display=''; });

    var commWrap = document.getElementById('nav-commission-wrap');
    if (commWrap && commWrap._origHTML) commWrap.innerHTML = commWrap._origHTML;

    var adminWrap = document.getElementById('nav-admin-wrap');
    if (adminWrap && adminWrap._origHTML) adminWrap.innerHTML = adminWrap._origHTML;

    sb.querySelectorAll('.sidebar-user-info,.sidebar-user-signout').forEach(function(el){ el.style.display=''; });
    var authBtn = sb.querySelector('.sidebar-auth-btn');
    if (authBtn && authBtn._origHTML) { authBtn.innerHTML = authBtn._origHTML; authBtn.style.justifyContent=''; }

    sb.querySelectorAll('[id$="-icon"]').forEach(function(el){ el.style.display=''; });

    // Remove tooltips
    sb.querySelectorAll('.nav-tooltip').forEach(function(t){ t.remove(); });

    // Re-apply collapsed groups
    Object.keys(_navGroupState).forEach(function(g){ if(!_navGroupState[g]) collapseNavGroup(g); });
  }
};


// ── 2. NAV GROUP TOGGLE ───────────────────────────────────────
var _navGroupState = { overview: true, sales: true, tools: true };

window.toggleNavGroup = function(group) {
  if (_sidebarCollapsed) return;
  _navGroupState[group] = !_navGroupState[group];
  if (_navGroupState[group]) {
    expandNavGroup(group);
  } else {
    collapseNavGroup(group);
  }
};

function collapseNavGroup(group) {
  var items = document.getElementById('ng-'+group+'-items');
  var icon  = document.getElementById('ng-'+group+'-icon');
  if (items) { items.style.display = 'none'; }
  if (icon)  { icon.style.transform = 'rotate(-90deg)'; }
}

function expandNavGroup(group) {
  var items = document.getElementById('ng-'+group+'-items');
  var icon  = document.getElementById('ng-'+group+'-icon');
  if (items) { items.style.display = ''; }
  if (icon)  { icon.style.transform = 'rotate(0deg)'; }
}

// ── 3. OPPORTUNITY CONVERSION POPUP ──────────────────────────
window.anCloseOppConvertModal = function(leadId) {
  var m = document.getElementById('opp-convert-modal');
  var fromDemo = m && m._fromDemoComplete;
  var prev = m && m._prevStatus;
  if (m) m.remove();
  if (fromDemo && leadId && typeof anCancelDemoCompleteConversion === 'function') {
    anCancelDemoCompleteConversion(leadId, prev);
  }
};

window.anConvertToOpportunity = function(leadId, opts) {
  opts = opts || {};
  var lead = AN.leads.find(function(l){ return l.id===leadId; });
  if (!lead) return;

  var old = document.getElementById('opp-convert-modal');
  if (old) old.remove();

  var fromDemoComplete = !!opts.fromDemoComplete || lead.status === 'demo_complete';
  var prevStatus = opts.prevStatus || lead._demoCompletePrevStatus || 'booked_demo';
  var SIZE_OPTS = '<option value="">Select size...</option>'+AN_SIZES.map(function(s){
    return '<option value="'+s.id+'"'+(lead.size===s.id?' selected':'')+'>'+s.label+' ($'+s.price+'/mo)</option>';
  }).join('');
  var headerTitle = fromDemoComplete ? '✅ Demo Complete — Create Opportunity' : '💎 Convert to Opportunity';
  var leadLine = anEsc((lead.firstName||'')+' '+(lead.lastName||''))+(lead.company?' · '+anEsc(lead.company):'');
  var headerSub = fromDemoComplete
    ? leadLine + ' · Fill in deal details to create the opportunity'
    : leadLine;
  var ownersLine = '';
  if (lead.sdrEmail || lead.aeEmail) {
    var sdrLbl = lead.sdrEmail && typeof anGetRepName === 'function' ? anGetRepName(lead.sdrEmail) : (lead.sdrEmail || '').split('@')[0];
    var aeLbl = lead.aeEmail && typeof anGetRepName === 'function' ? anGetRepName(lead.aeEmail) : (lead.aeEmail || '').split('@')[0];
    ownersLine = '<div style="display:flex;gap:12px;margin-top:10px;flex-wrap:wrap;">'
      +(lead.sdrEmail ? '<span style="font-size:11px;color:rgba(255,255,255,0.55);background:rgba(255,255,255,0.08);padding:4px 10px;border-radius:20px;">SDR: <strong style="color:#c4b5fd;">'+anEsc(sdrLbl)+'</strong></span>' : '')
      +(lead.aeEmail ? '<span style="font-size:11px;color:rgba(255,255,255,0.55);background:rgba(255,255,255,0.08);padding:4px 10px;border-radius:20px;">AE: <strong style="color:#86efac;">'+anEsc(aeLbl)+'</strong></span>' : '')
      +'</div>';
  }

  var m = document.createElement('div');
  m.id = 'opp-convert-modal';
  m._fromDemoComplete = fromDemoComplete;
  m._prevStatus = prevStatus;
  m._leadId = leadId;
  m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.65);z-index:10001;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(4px);';

  m.innerHTML = '<div style="background:var(--card-bg);border-radius:16px;width:520px;max-width:95vw;box-shadow:0 24px 80px rgba(0,0,0,0.35);overflow:hidden;">'
    // Header
    +'<div style="background:linear-gradient(135deg,#0a0a14,#1a1640);padding:22px 26px;display:flex;justify-content:space-between;align-items:center;">'
    +'<div><div style="font-size:18px;font-weight:800;color:#fff;letter-spacing:-0.4px;">'+headerTitle+'</div>'
    +'<div style="font-size:12px;color:rgba(255,255,255,0.45);margin-top:3px;">'+headerSub+'</div>'
    +ownersLine
    +'</div>'
    +'<button onclick="anCloseOppConvertModal(\''+leadId+'\')" style="background:rgba(255,255,255,0.1);border:none;color:rgba(255,255,255,0.6);width:30px;height:30px;border-radius:8px;cursor:pointer;font-size:16px;">✕</button>'
    +'</div>'

    // Form
    +'<div style="padding:24px 26px;">'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;">'

    // Number of agents — PRIMARY driver of deal value
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Number of Agents</label>'
    +'<input id="opp-agents" type="number" min="1" value="1" placeholder="e.g. 4" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);box-sizing:border-box;" onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'"></div>'

    // Size — auto-derived from agent count, still shown/overridable for display purposes
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Agency Size</label>'
    +'<select id="opp-size" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);">'+SIZE_OPTS+'</select></div>'

    // Contract type
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Contract Type</label>'
    +'<select id="opp-contract" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);">'
    +'<option value="mrr">Monthly (MRR)</option>'
    +'<option value="arr">Annual Prepaid (ARR)</option>'
    +'<option value="2yr">2-Year Prepaid</option>'
    +'<option value="3yr">3-Year Prepaid</option>'
    +'</select></div>'

    // MRR value — auto-filled from agent count, editable for manual overrides/discounts
    +'<div><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Monthly Value ($)</label>'
    +'<input id="opp-mrr" type="number" min="0" placeholder="auto from agents" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);box-sizing:border-box;" onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'">'
    +'<div style="font-size:10.5px;color:var(--text-muted);margin-top:3px;">Auto-calculated from agent count — edit to override</div></div>'

    +'</div>'

    // Close date
    +'<div style="margin-bottom:14px;"><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Expected Close Date</label>'
    +'<input id="opp-close-date" type="date" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);box-sizing:border-box;" onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'"></div>'

    // Notes
    +'<div style="margin-bottom:18px;"><label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">Opportunity Notes</label>'
    +'<textarea id="opp-notes" rows="3" placeholder="Pain points, decision timeline, competitors mentioned..." style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13px;font-family:var(--sans);outline:none;resize:none;color:var(--text-primary);background:var(--card-bg);line-height:1.6;box-sizing:border-box;" onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'"></textarea></div>'

    // Value preview
    +'<div id="opp-value-preview" style="background:var(--body-bg);border-radius:10px;padding:12px 14px;margin-bottom:16px;display:flex;gap:16px;flex-wrap:wrap;"></div>'

    +'<div style="display:flex;gap:8px;justify-content:flex-end;">'
    +'<button onclick="anCloseOppConvertModal(\''+leadId+'\')" style="padding:10px 18px;border-radius:8px;border:1.5px solid var(--divider);background:transparent;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);color:var(--text-secondary);">Cancel</button>'
    +'<button onclick="anFinalizeConversion(\''+leadId+'\')" style="padding:10px 20px;border-radius:8px;border:none;background:#6366f1;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:var(--sans);box-shadow:0 2px 8px rgba(99,102,241,0.3);">'+(fromDemoComplete ? '✅ Create Opportunity' : '💎 Convert to Opportunity')+'</button>'
    +'</div></div></div>';

  document.body.appendChild(m);
  m.onclick = function(e){ if(e.target===m) anCloseOppConvertModal(leadId); };

  // Auto-fill MRR + Agency Size from Number of Agents — value follows how many agents
  // this deal can sign on, using the same pricing tiers as the Quote Calculator.
  document.getElementById('opp-agents').addEventListener('input', function(){
    var agents = parseInt(this.value) || 0;
    var pricing = anAgentPricing(agents, 0);
    document.getElementById('opp-mrr').value = pricing.monthly || '';
    var sizeEl = document.getElementById('opp-size');
    if (sizeEl) sizeEl.value = pricing.sizeId;
    updateOppValuePreview();
  });
  document.getElementById('opp-mrr').addEventListener('input', updateOppValuePreview);
  document.getElementById('opp-contract').addEventListener('change', updateOppValuePreview);

  // Seed the initial value from the default agent count (1)
  (function(){
    var pricing = anAgentPricing(parseInt(document.getElementById('opp-agents').value)||1, 0);
    document.getElementById('opp-mrr').value = pricing.monthly || '';
    document.getElementById('opp-size').value = pricing.sizeId;
  })();
};

function updateOppValuePreview() {
  var preview = document.getElementById('opp-value-preview');
  if (!preview) return;
  var mrr  = parseFloat(document.getElementById('opp-mrr')?.value)||0;
  var type = document.getElementById('opp-contract')?.value||'mrr';
  if (!mrr) { preview.innerHTML = ''; return; }
  var arr1   = Math.round(mrr*12*0.80);
  var arr2   = Math.round(mrr*24*0.75);
  var arr3   = Math.round(mrr*36*0.72);
  var values = [
    {label:'MRR', val:'$'+mrr+'/mo', color:'#6366f1'},
    {label:'1-Yr ARR (20% off)', val:'$'+arr1+'/yr', color:'#10b981'},
    {label:'2-Yr (25% off)', val:'$'+arr2+' total', color:'#f59e0b'},
    {label:'3-Yr (28% off)', val:'$'+arr3+' total', color:'#8b5cf6'}
  ];
  preview.innerHTML = values.map(function(v){
    return '<div style="text-align:center;flex:1;min-width:80px;">'
      +'<div style="font-size:10px;font-weight:700;color:'+v.color+';text-transform:uppercase;letter-spacing:0.1em;margin-bottom:3px;">'+v.label+'</div>'
      +'<div style="font-size:15px;font-weight:800;color:var(--text-primary);">'+v.val+'</div>'
      +'</div>';
  }).join('');
}

window.anFinalizeConversion = function(leadId) {
  var lead = AN.leads.find(function(l){ return l.id===leadId; });
  if (!lead) return;
  var modal = document.getElementById('opp-convert-modal');
  var fromDemoComplete = modal && modal._fromDemoComplete;
  var size      = document.getElementById('opp-size')?.value||lead.size||'solo';
  var contract  = document.getElementById('opp-contract')?.value||'mrr';
  var mrr       = parseFloat(document.getElementById('opp-mrr')?.value)||0;
  var agents    = parseInt(document.getElementById('opp-agents')?.value)||1;
  var closeDate = document.getElementById('opp-close-date')?.value||'';
  var notes     = document.getElementById('opp-notes')?.value||'';

  // Update lead
  lead.size           = size;
  lead.status         = fromDemoComplete ? 'showed' : 'demo';
  lead.oppContract    = contract;
  lead.oppMRR         = mrr || anAgentPricing(agents, 0).monthly || 79;
  lead.oppAgents      = agents;
  lead.oppCloseDate   = closeDate;
  lead.oppNotes       = notes;
  lead.isOpportunity  = true;
  if (!lead.sdrEmail && lead._repEmail) lead.sdrEmail = lead._repEmail;
  if (lead.aeEmail) lead._repEmail = lead.aeEmail.toLowerCase();
  lead.convertedAt    = new Date().toISOString();
  if (fromDemoComplete) lead.demoCompletedAt = lead.demoCompletedAt || new Date().toISOString();
  delete lead._demoCompletePrevStatus;
  lead.updated        = new Date().toISOString();

  if (typeof anRecordDemoConverted === 'function') {
    anRecordDemoConverted(lead, { source: fromDemoComplete ? 'demo_complete_modal' : 'convert_modal' });
  }
  if (typeof anSyncOpportunityToPipeline === 'function') anSyncOpportunityToPipeline(lead);
  AN.leads = anDedupeOpportunityLeads(AN.leads);
  if (typeof AN.invalidateLeadCaches === 'function') AN.invalidateLeadCaches();
  AN.save();
  if (modal) modal.remove();
  if (typeof renderLeadsTable === 'function') renderLeadsTable();
  if (typeof renderOpportunities === 'function') renderOpportunities();
  var panel = document.getElementById('an-side-panel');
  if (panel) { panel.style.transform='translateX(100%)'; setTimeout(function(){panel.remove();},300); }
  var overlay = document.getElementById('mcm-overlay');
  if (overlay && typeof openMobileCallMode === 'function') {
    setTimeout(function() { openMobileCallMode(leadId); }, 350);
  } else {
    setTimeout(function(){ showSection('opportunities'); }, 350);
  }
  if (typeof showToast==='function') showToast(fromDemoComplete ? 'Opportunity created — demo complete!' : 'Converted to opportunity!');
};

// ── Opportunities views + full record ───────────────────────
if (typeof AN !== 'undefined' && !AN.oppView) {
  try { AN.oppView = localStorage.getItem('an-opp-view') || 'board'; } catch(e) { AN.oppView = 'board'; }
  AN.oppSearchQ = AN.oppSearchQ || '';
}

window.anSetOppView = function(view) {
  if (!AN) return;
  AN.oppView = view || 'board';
  try { localStorage.setItem('an-opp-view', AN.oppView); } catch(e) {}
  if (typeof renderOpportunities === 'function') renderOpportunities();
};

function anFilterOppsForSearch(opps) {
  var q = (AN && AN.oppSearchQ || '').toLowerCase().trim();
  if (!q) return opps;
  return opps.filter(function(o) {
    var hay = (((o.firstName||'')+' '+(o.lastName||'')).trim()+' '+(o.company||'')+' '+(o.email||'')+' '+(o.phone||'')).toLowerCase().replace(/\s+/g,' ');
    return hay.indexOf(q) >= 0;
  });
}

window.anResolveOppSdrEmail = function(opp) {
  if (!opp) return '';
  var sdr = (opp.sdrEmail || '').toLowerCase().trim();
  if (sdr) return sdr;
  if (typeof _dash !== 'undefined' && Array.isArray(_dash.pipeline) && opp.id) {
    var deal = _dash.pipeline.find(function(d) { return d.leadId === opp.id; });
    if (deal && deal.sdrEmail) return String(deal.sdrEmail).toLowerCase().trim();
  }
  return '';
};

window.anResolveOppAeEmail = function(opp) {
  if (!opp) return '';
  var ae = (opp.aeEmail || '').toLowerCase().trim();
  if (ae) return ae;
  if (typeof _dash !== 'undefined' && Array.isArray(_dash.pipeline) && opp.id) {
    var deal = _dash.pipeline.find(function(d) { return d.leadId === opp.id; });
    if (deal && deal.aeEmail) return String(deal.aeEmail).toLowerCase().trim();
  }
  var rep = (opp._repEmail || '').toLowerCase().trim();
  var sdr = typeof anResolveOppSdrEmail === 'function' ? anResolveOppSdrEmail(opp) : '';
  if (rep && (!sdr || rep !== sdr)) return rep;
  return '';
};

window.anBuildOppOwnerChipsHTML = function(opp) {
  if (!opp) return '';
  var sdrEm = typeof anResolveOppSdrEmail === 'function' ? anResolveOppSdrEmail(opp) : '';
  var aeEm = typeof anResolveOppAeEmail === 'function' ? anResolveOppAeEmail(opp) : '';
  var sdrName = sdrEm && typeof anGetRepName === 'function' ? anGetRepName(sdrEm) : '';
  var aeName = aeEm && typeof anGetRepName === 'function' ? anGetRepName(aeEm) : '';
  return '<div style="font-size:10px;color:var(--text-muted);margin-top:6px;padding-top:6px;border-top:1px solid var(--divider);display:flex;gap:6px;flex-wrap:wrap;align-items:center;">'
    + '<span style="background:#f0fdf4;color:#15803d;border-radius:6px;padding:2px 8px;font-weight:600;">SDR: ' + anEsc(sdrName || '—') + '</span>'
    + '<span style="background:#eef2ff;color:#4f46e5;border-radius:6px;padding:2px 8px;font-weight:600;">AE: ' + anEsc(aeName || '—') + '</span>'
    + '</div>';
};

function anBuildOppTableHTML(opps, stages) {
  if (!opps.length) return '<div style="text-align:center;padding:48px;color:var(--text-muted);">No deals match your search.</div>';
  var stageMap = {};
  stages.forEach(function(s) { stageMap[s.id] = s; });
  var rows = opps.map(function(o) {
    var stageId = typeof anOppPipelineStage === 'function' ? anOppPipelineStage(o) : o.status;
    var st = stageMap[stageId] || { label: stageId, color: '#6366f1' };
    var mrr = o.oppMRR || (AN_SIZES.find(function(s){ return s.id === o.size; }) || { price: 79 }).price;
    var cv = anOppContractValue(o);
    var contractTag = { arr:'ARR', '2yr':'2-YR', '3yr':'3-YR' }[o.oppContract];
    var szMeta = typeof anAgencySizeMeta === 'function' ? anAgencySizeMeta(o.size || 'solo') : { label: 'Solo Agent', short: 'Solo', color: '#6366f1', bg: '#eef2ff' };
    var szLabel = (AN_SIZES.find(function(s){ return s.id === o.size; }) || { label: szMeta.label }).label;
    var agents = (o.oppAgents != null && o.oppAgents !== '') ? o.oppAgents : null;
    var agentsDisplay = agents != null ? agents : '?';
    var sdrEm = typeof anResolveOppSdrEmail === 'function' ? anResolveOppSdrEmail(o) : '';
    var aeEm = typeof anResolveOppAeEmail === 'function' ? anResolveOppAeEmail(o) : '';
    var owners = (sdrEm ? 'SDR: ' + anGetRepName(sdrEm) : 'SDR: —')
      + (aeEm ? ' · AE: ' + anGetRepName(aeEm) : ' · AE: —');
    var name = ((o.firstName||'')+' '+(o.lastName||'')).trim() || o.company || 'Deal';
    return '<tr data-lead-id="'+o.id+'" onclick="anOpenOppRecord(\''+o.id+'\')" style="border-bottom:1px solid var(--divider);cursor:pointer;" onmouseover="this.style.background=\'rgba(99,102,241,0.04)\'" onmouseout="this.style.background=\'transparent\'">'
      +'<td style="padding:12px 14px;font-weight:700;color:var(--text-primary);">'+anEsc(name)+'</td>'
      +'<td data-field="company" style="padding:12px 14px;color:var(--text-secondary);cursor:text;" title="Click to edit">'+anEsc(o.company||'—')+'</td>'
      +'<td data-field="agents" style="padding:12px 14px;cursor:text;" title="Click to edit number of agents"><span style="background:'+szMeta.bg+';color:'+szMeta.color+';border:1px solid '+szMeta.color+'33;border-radius:20px;padding:3px 10px;font-size:11px;font-weight:700;">'+anEsc(szLabel)+' · '+agentsDisplay+'</span></td>'
      +'<td data-field="stage" style="padding:12px 14px;cursor:text;" title="Click to edit"><span style="background:'+st.color+'18;color:'+st.color+';border-radius:20px;padding:3px 10px;font-size:11px;font-weight:700;">'+anEsc(st.label)+'</span></td>'
      +'<td data-field="value" style="padding:12px 14px;font-weight:800;color:#6366f1;cursor:text;" title="Click to edit">'+cv.display+(contractTag?' <span style="background:#f5f3ff;color:#7c3aed;border-radius:5px;padding:1px 6px;font-size:9.5px;font-weight:800;letter-spacing:0.05em;margin-left:4px;">'+contractTag+'</span>':'')+'</td>'
      +'<td data-field="closeDate" style="padding:12px 14px;color:var(--text-muted);cursor:text;" title="Click to edit">'+(o.oppCloseDate ? anDate(o.oppCloseDate) : '—')+'</td>'
      +'<td style="padding:12px 14px;color:var(--text-muted);font-size:12px;cursor:pointer;" title="Click to edit SDR / AE" onclick="event.stopPropagation();anOpenSdrAePicker(\''+o.id+'\')">'+anEsc(owners)+' <span style="color:#6366f1;">▾</span></td>'
      +'</tr>';
  }).join('');
  return '<div class="opp-table-wrap"><table style="width:100%;border-collapse:collapse;font-size:13px;min-width:820px;">'
    +'<thead><tr style="background:var(--body-bg);">'
    +'<th style="padding:10px 14px;text-align:left;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text-muted);">Deal</th>'
    +'<th style="padding:10px 14px;text-align:left;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text-muted);">Company</th>'
    +'<th style="padding:10px 14px;text-align:left;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text-muted);">Agency Size</th>'
    +'<th style="padding:10px 14px;text-align:left;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text-muted);">Stage</th>'
    +'<th style="padding:10px 14px;text-align:left;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text-muted);">Value</th>'
    +'<th style="padding:10px 14px;text-align:left;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text-muted);">Close Date</th>'
    +'<th style="padding:10px 14px;text-align:left;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text-muted);">SDR / AE</th>'
    +'</tr></thead><tbody>'+rows+'</tbody></table></div>';
}

// ── Inline click-to-edit for the Deals table (mirrors Leads table pattern) ──
(function() {
  document.addEventListener('click', function(e) {
    var td = e.target.closest('.opp-table-wrap tbody td[data-field]');
    if (!td || td.querySelector('input,select')) return;
    e.stopPropagation();
    startOppInlineEdit(td);
  }, true);
})();

function startOppInlineEdit(td) {
  var field  = td.dataset.field;
  var leadId = td.closest('tr').dataset.leadId;
  var lead   = AN.leads.find(function(l){ return l.id === leadId; });
  if (!lead) return;
  var original = td.innerHTML;
  td.style.padding = '2px 6px';

  if (field === 'stage') {
    var sel = document.createElement('select');
    sel.style.cssText = 'width:100%;border:1.5px solid #6366f1;border-radius:6px;padding:5px 8px;font-size:12px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;';
    AN_OPP_STATUSES.forEach(function(s) {
      var opt = document.createElement('option');
      opt.value = s.id; opt.textContent = s.label;
      if (s.id === (lead.status||'')) opt.selected = true;
      sel.appendChild(opt);
    });
    sel.onchange = function() { anMoveOppStage(leadId, sel.value); };
    sel.onkeydown = function(e) { if (e.key === 'Escape') { td.innerHTML = original; td.style.padding = ''; } };
    td.innerHTML = ''; td.appendChild(sel); sel.focus();
    return;
  }

  if (field === 'agents') {
    var inpA = document.createElement('input');
    inpA.type = 'number'; inpA.min = '1';
    inpA.value = lead.oppAgents || 1;
    inpA.style.cssText = 'width:80px;border:1.5px solid #6366f1;border-radius:6px;padding:5px 8px;font-size:13px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;';
    inpA.onblur = function() { anOppSetAgents(leadId, inpA.value); };
    inpA.onkeydown = function(e) {
      if (e.key === 'Enter') inpA.blur();
      if (e.key === 'Escape') { td.innerHTML = original; td.style.padding = ''; }
    };
    td.innerHTML = ''; td.appendChild(inpA); inpA.focus(); inpA.select();
    return;
  }

  if (field === 'value') {
    var inpV = document.createElement('input');
    inpV.type = 'number'; inpV.min = '0';
    inpV.value = lead.oppMRR || 0;
    inpV.style.cssText = 'width:100px;border:1.5px solid #6366f1;border-radius:6px;padding:5px 8px;font-size:13px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;';
    inpV.onblur = function() { anOppSetMRR(leadId, inpV.value); };
    inpV.onkeydown = function(e) {
      if (e.key === 'Enter') inpV.blur();
      if (e.key === 'Escape') { td.innerHTML = original; td.style.padding = ''; }
    };
    td.innerHTML = ''; td.appendChild(inpV); inpV.focus(); inpV.select();
    return;
  }

  if (field === 'closeDate') {
    var inpD = document.createElement('input');
    inpD.type = 'date';
    inpD.value = lead.oppCloseDate || '';
    inpD.style.cssText = 'width:100%;border:1.5px solid #6366f1;border-radius:6px;padding:5px 8px;font-size:12px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;';
    inpD.onchange = function() { anOppSaveField(leadId, 'oppCloseDate', inpD.value); };
    inpD.onkeydown = function(e) { if (e.key === 'Escape') { td.innerHTML = original; td.style.padding = ''; } };
    td.innerHTML = ''; td.appendChild(inpD); inpD.focus();
    return;
  }

  // Plain text fields (company)
  var inp = document.createElement('input');
  inp.type = 'text';
  inp.value = lead[field] || '';
  inp.style.cssText = 'width:100%;border:1.5px solid #6366f1;border-radius:6px;padding:5px 8px;font-size:13px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;min-width:80px;';
  inp.onblur = function() { anOppSaveField(leadId, field, inp.value); };
  inp.onkeydown = function(e) {
    if (e.key === 'Enter') inp.blur();
    if (e.key === 'Escape') { td.innerHTML = original; td.style.padding = ''; }
  };
  td.innerHTML = ''; td.appendChild(inp); inp.focus(); inp.select();
}

// Editing agent count is the primary lever for deal value — recompute MRR + size bucket together
// Manually picking an agency size bucket sets a representative agent count for that tier
window.anOppSetSizeBucket = function(leadId, sizeId) {
  var defaults = { solo: 1, small: 4, large: 10, enterprise: 20 };
  anOppSetAgents(leadId, defaults[sizeId] || 1);
};

window.anOppSetAgents = function(leadId, agentsVal) {
  var lead = AN.leads.find(function(l){ return l.id === leadId; });
  if (!lead) return;
  var agents = Math.max(1, parseInt(agentsVal) || 1);
  var pricing = anAgentPricing(agents, 0);
  lead.oppAgents = agents;
  lead.size = pricing.sizeId;
  lead.oppMRR = pricing.monthly;
  lead.updated = new Date().toISOString();
  AN.save();
  if (typeof anSyncOpportunitiesToCommissionTrackers === 'function') anSyncOpportunitiesToCommissionTrackers({ skipSave: true });
  if (typeof renderOpportunities === 'function') renderOpportunities();
  anRefreshOppPanelIfOpen(leadId);
};

// Manual override of the computed value (e.g. custom discount)
window.anOppSetMRR = function(leadId, value) {
  var lead = AN.leads.find(function(l){ return l.id === leadId; });
  if (!lead) return;
  var v = parseFloat(value);
  if (isNaN(v) || v < 0) v = 0;
  lead.oppMRR = v;
  lead.updated = new Date().toISOString();
  AN.save();
  if (typeof renderOpportunities === 'function') renderOpportunities();
  anRefreshOppPanelIfOpen(leadId);
};

window.anRefreshOppPanelIfOpen = function(leadId) {
  var panel = document.getElementById('opp-record-panel');
  if (!panel || window._anOppDetailLeadId !== leadId) return;
  var lead = AN.leads.find(function(l){ return l.id === leadId; });
  if (lead && typeof oppBuildRecordHTML === 'function') panel.innerHTML = oppBuildRecordHTML(lead);
};

// Editable SDR / AE picker — used by the Deals table cell and the record panel
window.anOpenSdrAePicker = function(leadId) {
  var lead = AN.leads.find(function(l){ return l.id === leadId; });
  if (!lead) return;
  var old = document.getElementById('an-sdrae-popover');
  if (old) old.remove();

  var knownEmails = typeof anGetKnownRepEmails === 'function' ? anGetKnownRepEmails() : [];
  var repOpts = function(selected) {
    return '<option value="">— None —</option>' + knownEmails.map(function(em) {
      var nm = typeof anGetRepName === 'function' ? anGetRepName(em) : em.split('@')[0];
      return '<option value="'+em+'"'+(em===selected?' selected':'')+'>'+anEsc(nm)+'</option>';
    }).join('');
  };
  var currentSdr = typeof anResolveOppSdrEmail === 'function' ? anResolveOppSdrEmail(lead) : (lead.sdrEmail||'');
  var currentAe  = typeof anResolveOppAeEmail === 'function' ? anResolveOppAeEmail(lead) : (lead.aeEmail||'');

  var pop = document.createElement('div');
  pop.id = 'an-sdrae-popover';
  pop.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:10002;display:flex;align-items:center;justify-content:center;padding:20px;';
  pop.onclick = function(e){ if (e.target===pop) pop.remove(); };
  var selStyle = 'width:100%;border:1.5px solid var(--divider,#e4e4e7);border-radius:8px;padding:9px 12px;font-size:13px;font-family:inherit;outline:none;box-sizing:border-box;background:var(--card-bg,#fff);color:var(--text-primary,#09090b);cursor:pointer;';
  pop.innerHTML = '<div style="background:var(--card-bg,#fff);border-radius:14px;padding:22px;width:340px;max-width:95vw;box-shadow:0 16px 48px rgba(0,0,0,0.28);" onclick="event.stopPropagation()">'
    +'<div style="font-size:15px;font-weight:800;color:var(--text-primary);margin-bottom:14px;">Assign SDR / AE</div>'
    +'<label style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--text-muted);margin-bottom:5px;display:block;">SDR (sourced the lead)</label>'
    +'<select id="sdrae-sdr" style="'+selStyle+'margin-bottom:14px;">'+repOpts(currentSdr)+'</select>'
    +'<label style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--text-muted);margin-bottom:5px;display:block;">AE (ran the demo / closed)</label>'
    +'<select id="sdrae-ae" style="'+selStyle+'margin-bottom:18px;">'+repOpts(currentAe)+'</select>'
    +'<div style="display:flex;gap:8px;">'
    +'<button onclick="document.getElementById(\'an-sdrae-popover\').remove()" style="flex:1;padding:10px;border:1.5px solid var(--divider);border-radius:8px;background:var(--card-bg);color:var(--text-muted);font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">Cancel</button>'
    +'<button onclick="anSaveSdrAe(\''+leadId+'\')" style="flex:2;padding:10px;border:none;border-radius:8px;background:#6366f1;color:#fff;font-size:13px;font-weight:800;cursor:pointer;font-family:inherit;">Save</button>'
    +'</div></div>';
  document.body.appendChild(pop);
};

window.anSaveSdrAe = function(leadId) {
  var lead = AN.leads.find(function(l){ return l.id === leadId; });
  if (!lead) return;
  var sdrEl = document.getElementById('sdrae-sdr');
  var aeEl  = document.getElementById('sdrae-ae');
  lead.sdrEmail = sdrEl ? sdrEl.value : lead.sdrEmail;
  lead.aeEmail  = aeEl ? aeEl.value : lead.aeEmail;
  if (lead.aeEmail) lead._repEmail = lead.aeEmail;
  else if (lead.sdrEmail) lead._repEmail = lead.sdrEmail;
  lead.updated = new Date().toISOString();
  AN.save();
  var pop = document.getElementById('an-sdrae-popover');
  if (pop) pop.remove();
  if (typeof renderOpportunities === 'function') renderOpportunities();
  if (typeof anRefreshOppPanelIfOpen === 'function') anRefreshOppPanelIfOpen(leadId);
  if (typeof showToast === 'function') showToast('SDR / AE updated');
};

function anBuildOppCalendarHTML(opps) {
  if (!opps.length) return '<div style="text-align:center;padding:48px;color:var(--text-muted);">No deals with close dates yet.</div>';
  var byMonth = {};
  opps.forEach(function(o) {
    var d = o.oppCloseDate || 'Unscheduled';
    if (d !== 'Unscheduled') d = d.slice(0, 7);
    if (!byMonth[d]) byMonth[d] = [];
    byMonth[d].push(o);
  });
  var months = Object.keys(byMonth).sort();
  return months.map(function(m) {
    var label = m === 'Unscheduled' ? 'No close date' : (function() {
      try { return new Date(m + '-01').toLocaleDateString('en-US', { month: 'long', year: 'numeric' }); } catch(e) { return m; }
    })();
    var items = byMonth[m].map(function(o) {
      var name = ((o.firstName||'')+' '+(o.lastName||'')).trim() || o.company || 'Deal';
      var stageId = typeof anOppPipelineStage === 'function' ? anOppPipelineStage(o) : (o.status || 'demo');
      var st = (typeof anStatus === 'function') ? anStatus(stageId) : { label: stageId, color: '#6366f1' };
      var cv = anOppContractValue(o);
      return '<div onclick="anOpenOppRecord(\''+o.id+'\')" style="display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border:1px solid var(--divider);border-radius:10px;margin-bottom:8px;cursor:pointer;background:var(--card-bg);" onmouseover="this.style.borderColor=\'#c7d2fe\'" onmouseout="this.style.borderColor=\'var(--divider)\'">'
        +'<div><div style="font-weight:700;color:var(--text-primary);">'+anEsc(name)+'</div>'
        +'<div style="font-size:12px;color:var(--text-muted);">'+(o.oppCloseDate ? anDate(o.oppCloseDate) : 'TBD')+' · '+cv.display+'</div></div>'
        +'<span style="font-size:11px;font-weight:700;color:'+st.color+';background:'+st.color+'18;padding:4px 10px;border-radius:20px;">'+anEsc(st.label)+'</span>'
        +'</div>';
    }).join('');
    return '<div class="opp-cal-month"><h3>'+anEsc(label)+' ('+byMonth[m].length+')</h3>'+items+'</div>';
  }).join('');
}

function oppBuildRecordHTML(lead) {
  var st = (typeof anStatus === 'function') ? anStatus(lead.status || 'demo') : { label: lead.status, color: '#6366f1' };
  var sz = lead.size ? (AN_SIZES.find(function(s){ return s.id === lead.size; }) || { label: lead.size, price: 79 }) : { label: 'Solo Agent', price: 79 };
  var mrr = lead.oppMRR || sz.price;
  var cv = anOppContractValue(lead);
  var ctLabel = { mrr: 'Monthly (MRR)', arr: 'Annual (ARR)', '2yr': '2-Year Prepaid', '3yr': '3-Year Prepaid' }[lead.oppContract || 'mrr'] || 'Monthly';
  var name = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || lead.company || 'Deal';
  var safeId = lead.id.replace(/'/g, "\\'");
  var STATUS_OPTS = AN_OPP_STATUSES.map(function(s) {
    return '<option value="'+s.id+'"'+(lead.status === s.id ? ' selected' : '')+'>'+s.label+'</option>';
  }).join('');

  var demoLabels = { booked: 'Demo booked', completed: 'Demo completed', converted: 'Demo → opportunity' };
  var timeline = [];
  (lead.demoLifecycle || []).forEach(function(ev) {
    timeline.push({
      date: ev.date || (ev.at ? ev.at.slice(0, 10) : ''),
      time: ev.at ? ev.at.slice(11, 16) : '',
      label: demoLabels[ev.type] || ('Demo ' + ev.type),
      detail: (ev.demoDate ? 'Scheduled ' + ev.demoDate + (ev.demoTime ? ' ' + ev.demoTime : '') : '') + (ev.source ? (ev.demoDate ? ' · ' : '') + ev.source : ''),
      type: 'demo_lifecycle',
      demoType: ev.type
    });
  });
  if (lead.convertedAt) timeline.push({ date: lead.convertedAt.slice(0, 10), label: 'Converted to opportunity', detail: 'Deal created in pipeline' });
  if (lead.demoCompletedAt && !(lead.demoLifecycle || []).some(function(e) { return e.type === 'completed'; })) {
    timeline.push({ date: lead.demoCompletedAt.slice(0, 10), label: 'Demo completed', detail: 'Ready for proposal / next step' });
  }
  (lead.callLog || []).forEach(function(c) {
    timeline.push({ date: c.date, time: c.time, label: (c.outcome || 'Call').charAt(0).toUpperCase() + (c.outcome || 'call').slice(1), detail: c.notes || '', type: 'call', outcome: c.outcome });
  });
  timeline.sort(function(a, b) { return (b.date || '').localeCompare(a.date || ''); });

  var callIcons = { pickup: '☎️', demo: '🎯', voicemail: '📬', noanswer: '📵', connected: '✅', objection: '🛡', next_step: '📋', won: '🏆' };
  var demoIcons = { booked: '📅', completed: '✅', converted: '💎' };
  var activityHTML = timeline.length ? timeline.slice(0, 40).map(function(ev) {
    var ic = ev.type === 'demo_lifecycle' ? (demoIcons[ev.demoType] || '🎯') : (ev.outcome ? (callIcons[ev.outcome] || '📞') : '💎');
    return '<div style="padding:14px 0;border-bottom:1px solid var(--divider);">'
      +'<div style="display:flex;align-items:flex-start;gap:10px;">'
      +'<span style="font-size:16px;">'+ic+'</span>'
      +'<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:700;color:var(--text-primary);">'+anEsc(ev.label)+'</div>'
      +'<div style="font-size:11px;color:var(--text-muted);margin-top:2px;">'+anEsc(ev.date)+(ev.time ? ' '+ev.time : '')+'</div>'
      +(ev.detail ? '<div style="font-size:12.5px;color:var(--text-secondary);margin-top:6px;line-height:1.5;background:var(--body-bg);border-radius:8px;padding:10px;">'+anEsc(ev.detail)+'</div>' : '')
      +'</div></div></div>';
  }).join('') : '<div style="text-align:center;padding:40px;color:var(--text-muted);">No activity yet — log a call or note from quick actions.</div>';

  var companyName = (lead.company || '').trim();
  var companyHTML = companyName
    ? '<div class="co-contact-row" onclick="typeof anOpenFullCompanyRecord===\'function\'?anOpenFullCompanyRecord(\''+companyName.replace(/'/g, "\\'")+'\'):void(0)">'
      +'<div style="width:34px;height:34px;border-radius:10px;background:#6366f122;color:#6366f1;display:flex;align-items:center;justify-content:center;font-weight:800;">'+companyName.charAt(0).toUpperCase()+'</div>'
      +'<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:700;">'+anEsc(companyName)+'</div><div style="font-size:11px;color:var(--text-muted);">View company record →</div></div></div>'
    : '<div style="text-align:center;padding:24px;color:var(--text-muted);font-size:12px;">No company linked</div>';

  return ''
    +'<div class="co-record-layout">'
    +'<aside class="co-record-left">'
    +(function() {
      var ret = typeof anGetSectionReturn === 'function' ? anGetSectionReturn() : null;
      var backLabel = ret ? ('← ' + ret.label) : '← Deals';
      var backAction = ret ? 'anNavigateSectionReturn()' : 'anCloseOppRecord()';
      return '<button type="button" class="co-record-back" onclick="'+backAction+'">'+anEsc(backLabel)+'</button>';
    })()
    +'<div style="display:flex;align-items:center;gap:12px;margin-bottom:8px;">'
    +'<div style="width:48px;height:48px;border-radius:12px;background:'+st.color+'22;color:'+st.color+';display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:900;">💎</div>'
    +'<div style="min-width:0;"><div style="font-size:20px;font-weight:800;color:var(--text-primary);line-height:1.2;">'+anEsc(name)+'</div>'
    +'<div style="font-size:12px;color:var(--text-muted);margin-top:2px;">Sales Pipeline</div></div></div>'
    +'<div class="co-quick-actions">'
    +'<button type="button" class="co-quick-btn" title="Log activity" onclick="anLogCall(\''+safeId+'\')">📞</button>'
    +'<button type="button" class="co-quick-btn" title="Email" onclick="anQuickLogEmail(\''+safeId+'\')">✉️</button>'
    +'<button type="button" class="co-quick-btn" title="Deal session" onclick="typeof openMobileCallMode===\'function\'?openMobileCallMode(\''+safeId+'\'):void(0)">💎</button>'
    +'<button type="button" class="co-quick-btn" title="Delete" onclick="anDeleteOpportunity(\''+safeId+'\')">🗑</button>'
    +'</div>'
    +'<div class="co-key-info"><div class="co-key-info-head">About this deal</div>'
    +'<div class="co-panel-row"><span>Monthly rate</span><input type="number" min="0" value="'+mrr+'" onchange="anOppSetMRR(\''+safeId+'\',this.value)" style="border:none;border-bottom:1px solid var(--divider);background:transparent;font-family:inherit;font-size:13px;font-weight:800;color:#6366f1;text-align:right;width:80px;">/mo</div>'
    +'<div class="co-panel-row"><span>Deal value</span><span style="color:#6366f1;font-weight:800;">'+cv.display+'</span></div>'
    +'<div class="co-panel-row"><span>Close date</span><input type="date" value="'+(lead.oppCloseDate||'')+'" onchange="anOppSaveField(\''+safeId+'\',\'oppCloseDate\',this.value)" style="border:none;border-bottom:1px solid var(--divider);background:transparent;font-family:inherit;font-size:12px;text-align:right;"></div>'
    +'<div class="co-panel-row"><span>Deal stage</span><span style="color:'+st.color+';">'+anEsc(st.label)+'</span></div>'
    +'<div class="co-panel-row"><span>Contract</span><select onchange="anOppSaveField(\''+safeId+'\',\'oppContract\',this.value)" style="border:none;background:transparent;font-family:inherit;font-size:12px;text-align:right;">'
    +['mrr','arr','2yr','3yr'].map(function(ct){
        var lbl = { mrr:'Monthly (MRR)', arr:'Annual (ARR)', '2yr':'2-Year Prepaid', '3yr':'3-Year Prepaid' }[ct];
        return '<option value="'+ct+'"'+((lead.oppContract||'mrr')===ct?' selected':'')+'>'+lbl+'</option>';
      }).join('')
    +'</select></div>'
    +'<div class="co-panel-row"><span>Agency size</span><select onchange="anOppSetSizeBucket(\''+safeId+'\',this.value)" style="border:none;background:transparent;font-family:inherit;font-size:12px;text-align:right;">'
    +AN_SIZES.map(function(s){ return '<option value="'+s.id+'"'+((lead.size||'solo')===s.id?' selected':'')+'>'+anEsc(s.label)+'</option>'; }).join('')
    +'</select></div>'
    +'<div class="co-panel-row"><span>Agents</span><input type="number" min="1" value="'+(lead.oppAgents || 1)+'" onchange="anOppSetAgents(\''+safeId+'\',this.value)" style="border:none;border-bottom:1px solid var(--divider);background:transparent;font-family:inherit;font-size:12px;text-align:right;width:50px;"></div>'
    +'<div class="co-panel-row"><span>Owner</span>'
    +(typeof anCanReassignOwner === 'function' && anCanReassignOwner(lead)
      ? '<button type="button" onclick="anOpenOwnerPicker({leadId:\''+safeId+'\'})" style="background:#fffbeb;color:#b45309;border:1px solid #fde68a;border-radius:6px;padding:3px 9px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">'+anEsc(lead._repEmail ? anGetRepName(lead._repEmail) : 'Assign')+' ▾</button>'
      : '<span>'+anEsc(lead._repEmail ? anGetRepName(lead._repEmail) : '—')+'</span>')
    +'</div>'
    +'<div class="co-panel-row"><span>SDR / AE</span>'
    +'<button type="button" onclick="anOpenSdrAePicker(\''+safeId+'\')" style="background:#eef2ff;color:#4f46e5;border:1px solid #c7d2fe;border-radius:6px;padding:3px 9px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">'
    +anEsc((typeof anResolveOppSdrEmail==='function'&&anResolveOppSdrEmail(lead))?anGetRepName(anResolveOppSdrEmail(lead)):'—')
    +' / '+anEsc((typeof anResolveOppAeEmail==='function'&&anResolveOppAeEmail(lead))?anGetRepName(anResolveOppAeEmail(lead)):'—')+' ▾</button>'
    +'</div>'
    +'<div style="padding:12px 14px;"><label style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:6px;">Move stage</label>'
    +'<select onchange="anMoveOppStage(\''+safeId+'\',this.value);anOpenOppRecord(\''+safeId+'\')" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:8px 10px;font-size:13px;background:var(--card-bg);font-family:inherit;">'+STATUS_OPTS+'</select></div>'
    +'</div>'
    +'<div style="margin-top:14px;"><div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;margin-bottom:6px;">Deal notes</div>'
    +'<textarea rows="4" placeholder="Pain points, timeline, competitors..." onblur="anOppSaveField(\''+safeId+'\',\'oppNotes\',this.value)" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:10px;font-size:12px;font-family:inherit;resize:vertical;box-sizing:border-box;">'+anEsc(lead.oppNotes || lead.notes || '')+'</textarea></div>'
    +'</aside>'
    +'<main class="co-record-center">'
    +'<div class="co-activity-head"><div style="font-size:14px;font-weight:800;">Activities</div><div style="font-size:12px;color:var(--text-muted);margin-top:2px;">Calls, stage changes, and notes on this deal</div></div>'
    +'<div class="co-activity-feed">'+activityHTML+'</div>'
    +'</main>'
    +'<aside class="co-record-right">'
    +'<div class="co-assoc-card"><div class="co-assoc-head"><span>Contact</span><button type="button" onclick="anOpenLeadPanel(\''+safeId+'\')" style="background:none;border:none;color:#6366f1;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">Profile →</button></div>'
    +'<div class="co-assoc-body"><div class="co-contact-row" onclick="anOpenLeadPanel(\''+safeId+'\')">'
    +'<div style="width:34px;height:34px;border-radius:50%;background:'+st.color+'22;color:'+st.color+';display:flex;align-items:center;justify-content:center;font-weight:800;">'+name.charAt(0).toUpperCase()+'</div>'
    +'<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:700;">'+anEsc(name)+'</div>'
    +'<div style="font-size:11px;color:var(--text-muted);">'+(lead.title ? anEsc(lead.title)+' · ' : '')+(lead.email || lead.phone || '')+'</div></div></div>'
    +(lead.email ? '<div style="padding:8px 10px;font-size:12px;"><a href="mailto:'+anEsc(lead.email)+'" style="color:#6366f1;">'+anEsc(lead.email)+'</a></div>' : '')
    +(lead.phone ? '<div style="padding:4px 10px 10px;font-size:12px;"><a href="tel:'+anEsc(anTelPhone(lead.phone))+'" style="color:var(--text-secondary);">'+anEsc(anFormatPhone(lead.phone))+'</a></div>' : '')
    +'</div></div>'
    +'<div class="co-assoc-card"><div class="co-assoc-head"><span>Company</span></div><div class="co-assoc-body">'+companyHTML+'</div></div>'
    +'<div style="background:linear-gradient(135deg,#0a0a14,#1a1640);border-radius:10px;padding:14px;color:#fff;margin-top:8px;"><div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;opacity:0.55;">Pipeline value</div><div style="font-size:26px;font-weight:900;margin-top:4px;">'+cv.display+'</div></div>'
    +'</aside></div>';
}

window.anOpenOppRecord = function(leadId, opts) {
  opts = opts || {};
  window._anOppDetailLeadId = leadId;
  if (!opts.preserveReturn) {
    var activeSection = typeof anGetActiveSectionId === 'function' ? anGetActiveSectionId() : '';
    if (activeSection === 'opportunities') {
      anClearSectionReturn();
    }
  }
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  var existing = document.getElementById('opp-record-panel');
  var existingBackdrop = document.getElementById('opp-panel-backdrop');
  if (existing) {
    existing.innerHTML = oppBuildRecordHTML(lead);
    if (!existing.classList.contains('open')) requestAnimationFrame(function() { existing.classList.add('open'); });
    if (existingBackdrop && !existingBackdrop.classList.contains('open')) requestAnimationFrame(function() { existingBackdrop.classList.add('open'); });
    return;
  }
  if (existingBackdrop) existingBackdrop.remove();
  var modal = document.getElementById('an-opp-detail-modal');
  if (modal) modal.remove();
  var backdrop = document.createElement('div');
  backdrop.id = 'opp-panel-backdrop';
  backdrop.onclick = anCloseOppRecord;
  document.body.appendChild(backdrop);
  var panel = document.createElement('div');
  panel.id = 'opp-record-panel';
  panel.innerHTML = oppBuildRecordHTML(lead);
  document.body.appendChild(panel);
  requestAnimationFrame(function() {
    backdrop.classList.add('open');
    panel.classList.add('open');
  });
};

window.anCloseOppRecord = function() {
  var panel = document.getElementById('opp-record-panel');
  var backdrop = document.getElementById('opp-panel-backdrop');
  if (panel) panel.classList.remove('open');
  if (backdrop) backdrop.classList.remove('open');
  setTimeout(function() {
    if (panel && !panel.classList.contains('open')) panel.remove();
    if (backdrop && !backdrop.classList.contains('open')) backdrop.remove();
  }, 300);
};

function leadBuildRecordHTML(lead) {
  var st = (typeof anStatus === 'function') ? anStatus(lead.status || 'new') : { label: lead.status || 'new', color: '#6366f1' };
  var sz = lead.size ? (AN_SIZES.find(function(s) { return s.id === lead.size; }) || { label: lead.size }) : null;
  var name = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || lead.company || 'Contact';
  var safeId = (lead.id || '').replace(/'/g, "\\'");
  var safeCo = (lead.company || '').replace(/'/g, "\\'");
  var leadState = typeof anResolveLeadState === 'function' ? anResolveLeadState(lead) : (lead.state || '');
  var STATUS_OPTS = (typeof anStatusesFor === 'function' ? anStatusesFor(lead) : AN_LEAD_STATUSES).map(function(s) {
    return '<option value="' + s.id + '"' + (lead.status === s.id ? ' selected' : '') + '>' + s.label + '</option>';
  }).join('');
  var companyOpen = !!(document.getElementById('co-company-panel') && document.getElementById('co-company-panel').classList.contains('open'));
  var backLabel = companyOpen ? '← Back to company' : '← Lead Pipeline';
  var backAction = companyOpen ? 'anCloseLeadRecord()' : 'anCloseLeadRecord();if(typeof showSection===\'function\')showSection(\'crm\')';

  var calls = (lead.callLog || []).slice().sort(function(a, b) { return (b.date || '').localeCompare(a.date || ''); });
  var callIcons = { pickup: '☎️', demo: '🎯', voicemail: '📬', noanswer: '📵', note: '📝', connected: '✅' };
  var activityHTML = calls.length ? calls.slice(0, 40).map(function(c) {
    var ic = callIcons[c.outcome] || '📞';
    return '<div style="padding:12px 0;border-bottom:1px solid var(--divider);">'
      + '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">'
      + '<span>' + ic + '</span><span style="font-size:13px;font-weight:700;color:var(--text-primary);">' + anEsc((c.outcome || 'call').charAt(0).toUpperCase() + (c.outcome || 'call').slice(1)) + '</span>'
      + '<span style="margin-left:auto;font-size:11px;color:var(--text-muted);">' + anEsc(c.date || '') + (c.time ? ' ' + c.time : '') + '</span>'
      + '</div>'
      + (c.notes ? '<div style="font-size:12.5px;color:var(--text-secondary);background:var(--body-bg);border-radius:8px;padding:10px;line-height:1.5;">' + anEsc(c.notes) + '</div>' : '')
      + '</div>';
  }).join('') : '<div style="text-align:center;padding:40px;color:var(--text-muted);">No activity yet — log a call from quick actions.</div>';

  var siblings = [];
  if (lead.company && typeof AN !== 'undefined' && Array.isArray(AN.leads)) {
    siblings = AN.leads.filter(function(l) {
      if (l.id === lead.id) return false;
      if ((l.company || '').trim() !== (lead.company || '').trim()) return false;
      if (typeof anRepOwnsLead === 'function' && !anRepOwnsLead(l) && !(AN.isAdmin)) return false;
      return true;
    }).slice(0, 12);
  }
  var siblingsHTML = siblings.length ? siblings.map(function(l) {
    var sname = ((l.firstName || '') + ' ' + (l.lastName || '')).trim() || 'Contact';
    var sst = (typeof anStatus === 'function') ? anStatus(l.status || 'new') : { label: l.status, color: '#6366f1' };
    return '<div class="co-contact-row" ondblclick="coOpenContact(\'' + l.id + '\')" onclick="coOpenContact(\'' + l.id + '\')" title="Open contact">'
      + '<div style="width:30px;height:30px;border-radius:50%;background:' + sst.color + '22;color:' + sst.color + ';display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;flex-shrink:0;">' + sname.charAt(0).toUpperCase() + '</div>'
      + '<div style="flex:1;min-width:0;"><div class="co-contact-name" style="font-size:12.5px;font-weight:700;">' + anEsc(sname) + '</div>'
      + '<div style="font-size:10px;color:var(--text-muted);">' + (l.title ? anEsc(l.title) : (l.email || l.phone || '')) + '</div></div>'
      + '<span style="font-size:9px;font-weight:700;color:' + sst.color + ';background:' + sst.color + '18;padding:2px 7px;border-radius:10px;">' + sst.label + '</span>'
      + '</div>';
  }).join('') : '<div style="text-align:center;padding:20px 10px;color:var(--text-muted);font-size:12px;">No other contacts at this company.</div>';

  var companyHTML = lead.company
    ? '<div class="co-contact-row" onclick="anCloseLeadRecord();typeof anOpenFullCompanyRecord===\'function\'?anOpenFullCompanyRecord(\'' + safeCo + '\'):void(0)">'
      + '<div style="width:34px;height:34px;border-radius:10px;background:#6366f122;color:#6366f1;display:flex;align-items:center;justify-content:center;font-weight:800;">' + lead.company.charAt(0).toUpperCase() + '</div>'
      + '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:700;">' + anEsc(lead.company) + '</div><div style="font-size:11px;color:var(--text-muted);">View company record →</div></div></div>'
    : '<div style="text-align:center;padding:20px;color:var(--text-muted);font-size:12px;">No company linked</div>';

  var ownerBtn = (typeof anCanReassignOwner === 'function' && anCanReassignOwner(lead))
    ? '<button type="button" onclick="anOpenOwnerPicker({leadId:\'' + safeId + '\'})" style="background:#fffbeb;color:#b45309;border:1px solid #fde68a;border-radius:6px;padding:3px 9px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">' + anEsc(lead._repEmail ? anGetRepName(lead._repEmail) : 'Assign') + ' ▾</button>'
    : '<span>' + anEsc(lead._repEmail ? anGetRepName(lead._repEmail) : '—') + '</span>';

  return ''
    + '<div class="co-record-layout">'
    + '<aside class="co-record-left">'
    + '<button type="button" class="co-record-back" onclick="' + backAction + '">' + backLabel + '</button>'
    + '<div style="display:flex;align-items:center;gap:12px;margin-bottom:8px;">'
    + '<div style="width:48px;height:48px;border-radius:12px;background:' + st.color + '22;color:' + st.color + ';display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:900;">' + name.charAt(0).toUpperCase() + '</div>'
    + '<div style="min-width:0;"><div style="font-size:20px;font-weight:800;color:var(--text-primary);line-height:1.2;">' + anEsc(name) + '</div>'
    + '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;">' + (lead.title ? anEsc(lead.title) : 'Contact') + (lead.company ? ' · ' + anEsc(lead.company) : '') + '</div></div></div>'
    + '<div class="co-quick-actions">'
    + '<button type="button" class="co-quick-btn" title="Log activity" onclick="anLogCall(\'' + safeId + '\')">📞</button>'
    + '<button type="button" class="co-quick-btn" title="Email" onclick="anQuickLogEmail(\'' + safeId + '\')">✉️</button>'
    + '<button type="button" class="co-quick-btn" title="Edit" onclick="anOpenLeadModal(\'' + safeId + '\')">✏️</button>'
    + '<button type="button" class="co-quick-btn" title="Call session" onclick="typeof openMobileCallMode===\'function\'?openMobileCallMode(\'' + safeId + '\'):void(0)">📱</button>'
    + '<button type="button" class="co-quick-btn" title="Create opportunity" onclick="anConvertToOpportunity(\'' + safeId + '\')">💎</button>'
    + '</div>'
    + '<div class="co-key-info"><div class="co-key-info-head">About this contact</div>'
    + '<div class="co-panel-row"><span>Status</span><span style="color:' + st.color + ';">' + anEsc(st.label) + '</span></div>'
    + '<div class="co-panel-row"><span>Owner</span>' + ownerBtn + '</div>'
    + '<div class="co-panel-row"><span>Email</span>' + (lead.email ? '<a href="mailto:' + anEsc(lead.email) + '" style="color:#6366f1;font-weight:600;">' + anEsc(lead.email) + '</a>' : '<span>—</span>') + '</div>'
    + '<div class="co-panel-row"><span>Phone</span>' + (lead.phone ? '<a href="tel:' + anEsc(typeof anTelPhone === 'function' ? anTelPhone(lead.phone) : lead.phone) + '" style="color:var(--text-primary);font-weight:600;">' + anEsc(typeof anFormatPhone === 'function' ? anFormatPhone(lead.phone) : lead.phone) + '</a>' : '<span>—</span>') + '</div>'
    + '<div class="co-panel-row"><span>State</span><span>' + anEsc(leadState || '—') + '</span></div>'
    + '<div class="co-panel-row"><span>Agency size</span><span>' + anEsc(sz ? sz.label : '—') + '</span></div>'
    + '<div class="co-panel-row"><span>Source</span><span>' + anEsc(lead.source || '—') + '</span></div>'
    + '<div style="padding:12px 14px;"><label style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:6px;">Move status</label>'
    + '<select onchange="anLeadRecordSaveStatus(\'' + safeId + '\',this.value)" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:8px 10px;font-size:13px;background:var(--card-bg);font-family:inherit;">' + STATUS_OPTS + '</select></div>'
    + '</div>'
    + '<div style="margin-top:14px;"><div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;margin-bottom:6px;">Notes</div>'
    + '<textarea rows="4" placeholder="Objections, follow-ups, context..." onblur="anLeadRecordSaveField(\'' + safeId + '\',\'notes\',this.value)" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:10px;font-size:12px;font-family:inherit;resize:vertical;box-sizing:border-box;">' + anEsc(lead.notes || '') + '</textarea></div>'
    + '</aside>'
    + '<main class="co-record-center">'
    + '<div class="co-activity-head"><div style="font-size:14px;font-weight:800;">Activities</div><div style="font-size:12px;color:var(--text-muted);margin-top:2px;">Calls, emails, and notes on this contact</div></div>'
    + '<div class="co-activity-feed">' + activityHTML + '</div>'
    + '</main>'
    + '<aside class="co-record-right">'
    + '<div class="co-assoc-card"><div class="co-assoc-head"><span>Company</span></div><div class="co-assoc-body">' + companyHTML + '</div></div>'
    + '<div class="co-assoc-card"><div class="co-assoc-head"><span>Other contacts' + (siblings.length ? ' (' + siblings.length + ')' : '') + '</span></div><div class="co-assoc-body">' + siblingsHTML + '</div></div>'
    + '<div style="background:linear-gradient(135deg,#0a0a14,#1a1640);border-radius:10px;padding:14px;color:#fff;margin-top:8px;"><div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;opacity:0.55;">Engagement</div>'
    + '<div style="font-size:26px;font-weight:900;margin-top:4px;">' + calls.length + '<span style="font-size:13px;opacity:0.5;"> activities</span></div>'
    + '<div style="font-size:11px;opacity:0.55;margin-top:4px;">Last contact: ' + (typeof anTimeAgo === 'function' ? anTimeAgo(lead.lastContactDate || lead.created) : '—') + '</div></div>'
    + '</aside></div>';
}

window.anOpenLeadRecord = function(leadId, opts) {
  opts = opts || {};
  window._anLeadDetailLeadId = leadId;
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l) { return l.id === leadId; }) : null;
  if (!lead) {
    if (typeof showToast === 'function') showToast('Contact not found');
    return;
  }
  if (typeof anHydrateLeadState === 'function') anHydrateLeadState(lead);
  if (typeof anRepOwnsLead === 'function' && !anRepOwnsLead(lead) && !(typeof AN !== 'undefined' && AN.isAdmin)) {
    if (typeof showToast === 'function') showToast('You can only view contacts assigned to you');
    return;
  }
  if (typeof anIsOpportunityRecord === 'function' && anIsOpportunityRecord(lead)) {
    if (typeof anOpenOppRecord === 'function') anOpenOppRecord(leadId);
    return;
  }

  var existing = document.getElementById('lead-record-panel');
  var existingBackdrop = document.getElementById('lead-panel-backdrop');
  if (existing) {
    existing.innerHTML = leadBuildRecordHTML(lead);
    if (!existing.classList.contains('open')) requestAnimationFrame(function() { existing.classList.add('open'); });
    if (existingBackdrop && !existingBackdrop.classList.contains('open')) requestAnimationFrame(function() { existingBackdrop.classList.add('open'); });
    return;
  }
  if (existingBackdrop) existingBackdrop.remove();

  var backdrop = document.createElement('div');
  backdrop.id = 'lead-panel-backdrop';
  backdrop.onclick = anCloseLeadRecord;
  document.body.appendChild(backdrop);
  var panel = document.createElement('div');
  panel.id = 'lead-record-panel';
  panel.innerHTML = leadBuildRecordHTML(lead);
  document.body.appendChild(panel);
  requestAnimationFrame(function() {
    backdrop.classList.add('open');
    panel.classList.add('open');
  });
};

window.anCloseLeadRecord = function() {
  var panel = document.getElementById('lead-record-panel');
  var backdrop = document.getElementById('lead-panel-backdrop');
  if (panel) panel.classList.remove('open');
  if (backdrop) backdrop.classList.remove('open');
  window._anLeadDetailLeadId = null;
  setTimeout(function() {
    if (panel && !panel.classList.contains('open')) panel.remove();
    if (backdrop && !backdrop.classList.contains('open')) backdrop.remove();
  }, 300);
};

window.anLeadRecordSaveField = function(leadId, field, value) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  lead[field] = value;
  lead.updated = new Date().toISOString();
  AN.save();
};

window.anLeadRecordSaveStatus = function(leadId, newStatus) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead || !newStatus) return;
  if (typeof anApplyLeadStatusChange === 'function') anApplyLeadStatusChange(lead, newStatus, { save: false });
  else lead.status = newStatus;
  lead.updated = new Date().toISOString();
  AN.save();
  if (document.getElementById('lead-record-panel')) anOpenLeadRecord(leadId);
  if (typeof renderLeadsTable === 'function') renderLeadsTable();
  var coPanel = document.getElementById('co-company-panel');
  if (coPanel && coPanel.classList.contains('open') && typeof _coSelected !== 'undefined' && _coSelected && typeof coOpenCompanyPanel === 'function') {
    coOpenCompanyPanel(_coSelected);
  }
};

window.anOppSaveField = function(leadId, field, value) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  lead[field] = value;
  if (field === 'oppNotes') lead.notes = value;
  lead.updated = new Date().toISOString();
  AN.save();
  if (typeof anSyncOpportunitiesToCommissionTrackers === 'function') {
    anSyncOpportunitiesToCommissionTrackers({ skipSave: true });
  }
  if (typeof renderOpportunities === 'function') renderOpportunities();
  if (typeof anRefreshOppPanelIfOpen === 'function') anRefreshOppPanelIfOpen(leadId);
};

// ── 4. OVERRIDE renderOpportunities with DRAGGABLE KANBAN ─────
window.renderOpportunities = function() {
  var sec = document.getElementById('section-opportunities');
  if (!sec) return;
  try {
  if (typeof AN === 'undefined') {
    sec.innerHTML = '<div class="content" style="padding:48px 20px;text-align:center;color:var(--text-muted);">Loading CRM...</div>';
    return;
  }
  if (!Array.isArray(AN.leads)) AN.leads = [];

  if (typeof anRepairMisclassifiedLeads === 'function' && anRepairMisclassifiedLeads(AN.leads)) {
    if (typeof AN.invalidateLeadCaches === 'function') AN.invalidateLeadCaches();
    clearTimeout(window._anOppRepairSaveTimer);
    window._anOppRepairSaveTimer = setTimeout(function() {
      if (typeof AN.save === 'function') AN.save();
    }, 600);
  }

  var opps = AN.leads.filter(function(l){
    return anIsOpportunity(l);
  });
  if (!AN.isAdmin) opps = opps.filter(function(l){ return typeof anRepOwnsLead === 'function' ? anRepOwnsLead(l) : (l._repEmail === AN.currentRepEmail); });
  if (typeof anNormalizeOpportunityStatuses === 'function' && anNormalizeOpportunityStatuses(opps)) {
    if (typeof AN.invalidateLeadCaches === 'function') AN.invalidateLeadCaches();
    clearTimeout(window._anOppNormSaveTimer);
    window._anOppNormSaveTimer = setTimeout(function() {
      if (typeof AN.save === 'function') AN.save();
    }, 400);
  }
  opps = anDedupeOpportunitiesForDisplay(opps);
  opps = anFilterOppsForSearch(opps);
  var oppView = (AN && AN.oppView) || 'board';

  var stages = [
    {id:'demo',     label:'Demo Set',    color:'#8b5cf6'},
    {id:'showed',   label:'Demo Completed',   color:'#06b6d4'},
    {id:'proposal', label:'Proposal',    color:'#3b82f6'},
    {id:'negotiation', label:'Negotiating', color:'#f59e0b'},
    {id:'won',      label:'Closed Won',  color:'#10b981'},
    {id:'lost',     label:'Closed Lost', color:'#ef4444'}
  ];

  var totalMRR = opps.filter(function(o){return o.status!=='lost';})
    .reduce(function(s,o){ return s+anOppContractValue(o).monthlyEquivalent; },0);
  var wonCount = opps.filter(function(o){return o.status==='won';}).length;
  var winRate  = opps.length>0 ? Math.round(wonCount/opps.length*100) : 0;

  var statsHTML = '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px;">'
    +[{l:'Opportunities',v:opps.length,c:'#6366f1'},{l:'Pipeline MRR',v:'$'+anFmtMoney(totalMRR)+'/mo',c:'#10b981'},{l:'Closed Won',v:wonCount,c:'#f59e0b'},{l:'Win Rate',v:winRate+'%',c:'#8b5cf6'}]
    .map(function(s){ return '<div style="background:var(--card-bg);border:1px solid var(--divider);border-radius:12px;padding:16px;text-align:center;"><div style="font-size:9px;font-weight:700;color:'+s.c+';text-transform:uppercase;letter-spacing:0.12em;margin-bottom:6px;">'+s.l+'</div><div style="font-size:24px;font-weight:900;color:var(--text-primary);letter-spacing:-1px;">'+s.v+'</div></div>'; })
    .join('')+'</div>';

  var kanbanHTML = '<div style="display:flex;gap:12px;overflow-x:auto;padding-bottom:16px;min-height:400px;">'
    +stages.map(function(stage){
      var stageLead = opps.filter(function(o){ return anOppPipelineStage(o) === stage.id; });
      var stageMRR  = stageLead.reduce(function(s,o){ return s+anOppContractValue(o).monthlyEquivalent; },0);

      var cards = stageLead.map(function(opp){
        var cv     = anOppContractValue(opp);
        var sz     = opp.size ? (AN_SIZES.find(function(s){return s.id===opp.size;})||{label:opp.size}) : {label:'Solo'};
        var szMeta = typeof anAgencySizeMeta === 'function' ? anAgencySizeMeta(opp.size || 'solo') : { color: stage.color, bg: '#fff', border: '#e4e4e7', short: 'Solo' };
        var cardBorder = szMeta.color;
        var ctLabel= {mrr:'Monthly',arr:'Annual','2yr':'2-Year','3yr':'3-Year'}[opp.oppContract||'mrr']||'Monthly';
        return '<div class="opp-card" data-lead-id="'+opp.id+'" draggable="true" '
          +'onclick="anOpenOppRecord(\''+opp.id+'\')" '
          +'style="background:'+szMeta.bg+';border:1px solid '+szMeta.border+';border-radius:10px;padding:14px;margin-bottom:8px;cursor:pointer;border-left:3px solid '+cardBorder+';transition:box-shadow 0.15s,transform 0.15s;position:relative;" '
          +'onmouseover="this.style.boxShadow=\'0 4px 16px rgba(0,0,0,0.1)\';this.style.transform=\'translateY(-1px)\'" '
          +'onmouseout="this.style.boxShadow=\'none\';this.style.transform=\'none\'">'
          +'<button type="button" onclick="event.stopPropagation();anDeleteOpportunity(\''+opp.id+'\')" title="Delete opportunity" style="position:absolute;top:8px;right:8px;width:24px;height:24px;border-radius:6px;border:1px solid #fecaca;background:#fef2f2;color:#ef4444;font-size:12px;cursor:pointer;display:flex;align-items:center;justify-content:center;padding:0;line-height:1;">🗑</button>'
          +'<div style="font-size:13.5px;font-weight:700;color:var(--text-primary);margin-bottom:2px;padding-right:28px;">'+anEsc((opp.firstName||'')+' '+(opp.lastName||''))+'</div>'
          +(opp.company?'<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">'+anEsc(opp.company)+'</div>':'<div style="margin-bottom:8px;"></div>')
          +'<div style="display:flex;justify-content:space-between;align-items:center;">'
          +'<div><div style="font-size:14px;font-weight:800;color:'+szMeta.color+';">'+cv.display+'</div>'
          +'<div style="font-size:10px;color:var(--text-muted);"><span style="font-weight:700;color:'+szMeta.color+';">'+anEsc(sz.label)+'</span> · '+ctLabel+'</div>'
          +'</div>'
          +(opp.oppCloseDate?'<div style="font-size:10.5px;color:#6366f1;text-align:right;">📅<br>'+anDate(opp.oppCloseDate)+'</div>':'')
          +'</div>'
          +(typeof anBuildOppOwnerChipsHTML === 'function' ? anBuildOppOwnerChipsHTML(opp) : '')
          +'</div>';
      }).join('');

      return '<div class="opp-column" data-stage="'+stage.id+'" '
        +'style="flex:0 0 220px;background:var(--body-bg);border-radius:10px;padding:12px;min-height:300px;">'
        +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">'
        +'<div style="display:flex;align-items:center;gap:6px;">'
        +'<span style="width:8px;height:8px;border-radius:50%;background:'+stage.color+';"></span>'
        +'<span style="font-size:12.5px;font-weight:700;color:var(--text-primary);">'+stage.label+'</span>'
        +'<span style="background:var(--card-bg);border:1px solid var(--divider);border-radius:10px;padding:1px 7px;font-size:11px;color:var(--text-muted);">'+stageLead.length+'</span>'
        +'</div>'
        +(stageMRR?'<span style="font-size:11px;font-weight:600;color:'+stage.color+';">$'+anFmtMoney(stageMRR)+'/mo</span>':'')
        +'</div>'
        + cards
        +'</div>';
    }).join('')
    +'</div>';

  var oppCallable = AN.leads.filter(function(l){
    return anLeadBelongsToRep(l) && anIsOpportunity(l) && l.status !== 'won' && l.status !== 'lost';
  }).length;

  var viewToggle = '<div class="opp-toolbar">'
    +'<div class="co-view-toggle">'
    +'<button type="button" class="co-view-btn'+(oppView==='board'?' active':'')+'" onclick="anSetOppView(\'board\')">▦ Board</button>'
    +'<button type="button" class="co-view-btn'+(oppView==='table'?' active':'')+'" onclick="anSetOppView(\'table\')">☰ Table</button>'
    +'<button type="button" class="co-view-btn'+(oppView==='calendar'?' active':'')+'" onclick="anSetOppView(\'calendar\')">📅 Calendar</button>'
    +'</div>'
    +'<div style="position:relative;"><span style="position:absolute;left:10px;top:50%;transform:translateY(-50%);font-size:13px;pointer-events:none;color:var(--text-muted);">🔍</span>'
    +'<input type="search" class="opp-search" placeholder="Search deals..." value="'+anEsc(AN.oppSearchQ||'')+'" oninput="AN.oppSearchQ=this.value;renderOpportunities()"></div>'
    +'</div>';

  var mainView = oppView === 'table' ? anBuildOppTableHTML(opps, stages)
    : oppView === 'calendar' ? anBuildOppCalendarHTML(opps)
    : kanbanHTML;

  sec.innerHTML = '<div class="page-header" style="display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;">'
    +'<div><div class="page-label">Pipeline</div>'
    +'<h1>Deals</h1>'
    +'</div>'
    +'<button onclick="anOpenOppCallSessionSetup()" style="display:flex;align-items:center;gap:6px;padding:10px 18px;border:1.5px solid #fde68a;border-radius:10px;font-size:13px;font-weight:700;color:#b45309;background:#fffbeb;cursor:pointer;font-family:var(--sans);flex-shrink:0;">💎 Deal Session'+(oppCallable?' ('+oppCallable+')':'')+'</button>'
    +'<button onclick="anOpenQuickAddDeal()" style="display:flex;align-items:center;gap:6px;padding:10px 18px;border:none;border-radius:10px;font-size:13px;font-weight:700;color:#fff;background:#6366f1;cursor:pointer;font-family:var(--sans);flex-shrink:0;box-shadow:0 2px 8px rgba(99,102,241,0.3);">+ Add Deal</button>'
    +'</div><div class="content">'+statsHTML+viewToggle+mainView+'</div>';

  if (oppView === 'board') setTimeout(initOppDragDrop, 80);
  if (typeof anSyncOpportunitiesToCommissionTrackers === 'function') {
    anSyncOpportunitiesToCommissionTrackers({ skipSave: true });
  }
  } catch (err) {
    console.error('[CRM] renderOpportunities failed:', err);
    sec.innerHTML = '<div class="content" style="padding:48px 20px;text-align:center;">'
      + '<div style="font-size:16px;font-weight:700;color:#ef4444;margin-bottom:8px;">Could not load Opportunities</div>'
      + '<div style="font-size:13px;color:var(--text-muted);margin-bottom:16px;">' + (err && err.message ? err.message : 'Unknown error') + '</div>'
      + '<button type="button" onclick="anMountOpportunitiesSection()" style="padding:10px 18px;border-radius:8px;border:none;background:#6366f1;color:#fff;font-weight:700;cursor:pointer;font-family:var(--sans);">Retry</button>'
      + '</div>';
  }
};

// ── 5. DRAG AND DROP ──────────────────────────────────────────
var _dragLeadId = null;

function initOppDragDrop() {
  document.querySelectorAll('.opp-card').forEach(function(card) {
    card.addEventListener('dragstart', function(e) {
      _dragLeadId = card.dataset.leadId;
      card.style.opacity = '0.5';
      e.dataTransfer.effectAllowed = 'move';
    });
    card.addEventListener('dragend', function() {
      card.style.opacity = '1';
    });
  });

  document.querySelectorAll('.opp-column').forEach(function(col) {
    col.addEventListener('dragover', function(e) {
      e.preventDefault();
      col.style.background = 'rgba(99,102,241,0.06)';
      col.style.outline = '2px dashed rgba(99,102,241,0.3)';
      e.dataTransfer.dropEffect = 'move';
    });
    col.addEventListener('dragleave', function() {
      col.style.background = '';
      col.style.outline = '';
    });
    col.addEventListener('drop', function(e) {
      e.preventDefault();
      col.style.background = '';
      col.style.outline = '';
      if (!_dragLeadId) return;
      var newStage = col.dataset.stage;
      var lead = AN.leads.find(function(l){ return l.id===_dragLeadId; });
      if (!lead || lead.status===newStage) return;
      lead.status = newStage;
      lead.updated = new Date().toISOString();
      // Sync wins to dashboard
      if (newStage==='won') syncActivityFromCRM('closes',1);
      AN.save();
      renderOpportunities();
      if (typeof showToast==='function') showToast('Moved to '+newStage);
      _dragLeadId = null;
    });
  });
}

// ── 6. OPP DETAIL (full record) ─────────────────────────────
window.anOpenOppDetail = function(leadId) {
  if (typeof anOpenOppRecord === 'function') anOpenOppRecord(leadId);
};

window.anMoveOppStage = function(leadId, newStage) {
  var lead = AN.leads.find(function(l){ return l.id===leadId; });
  if (!lead) return;
  var prevStage = lead.status;
  lead.status = newStage;
  lead.isOpportunity = true;
  lead.updated = new Date().toISOString();
  if (newStage==='won') {
    syncActivityFromCRM('closes',1);
    if (!lead.closedAt) lead.closedAt = lead.updated;
    if (typeof anSyncOpportunityToPipeline === 'function') anSyncOpportunityToPipeline(lead, { skipSave: true, skipRefresh: true });
  }
  AN.save();
  if (typeof renderOpportunities === 'function') renderOpportunities();
  if (document.getElementById('opp-record-panel') && typeof anOpenOppRecord === 'function') anOpenOppRecord(leadId);
  if (typeof showToast==='function') showToast('Stage updated');

  // Newly marked Closed Lost — ask why, feeds Field Insights
  if (newStage === 'lost' && prevStage !== 'lost') {
    anOpenReasonPicker({
      title: 'Why was this deal lost?',
      subtitle: 'Quick tag for the Field Insights board — helps marketing & product.',
      onConfirm: function(category, note) {
        anRecordOppLossReason(lead, category, note);
      },
      onSkip: function() {
        anRecordOppLossReason(lead, '', '');
      }
    });
  }
};

// Records the loss reason as a callLog entry so it surfaces in Field Insights,
// and tags the lead's status as not_interested-equivalent for classification.
window.anRecordOppLossReason = function(lead, category, note) {
  if (!lead) return;
  if (!lead.callLog) lead.callLog = [];
  var now = new Date();
  var repEmail = (typeof AN !== 'undefined' && AN.currentRepEmail) || (typeof _currentUser !== 'undefined' && _currentUser && _currentUser.email) || '';
  var entry = {
    id: 'act-' + Date.now(),
    type: 'call',
    outcome: 'lost',
    date: typeof anLocalDateStr === 'function' ? anLocalDateStr() : now.toISOString().split('T')[0],
    time: String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0'),
    rep: repEmail,
    loggedAt: now.toISOString(),
    notes: note || ('Deal closed lost' + (category ? ' (' + (AN_INSIGHT_CATEGORIES[category] ? AN_INSIGHT_CATEGORIES[category].label : category) + ')' : ''))
  };
  if (category) entry.category = category;
  lead.callLog.push(entry);
  lead.updated = now.toISOString();
  AN.save();
};

