// ─── inline block 28 ───────────────────────
// ============================================================
// CRM FIX PATCH — All CRM UX improvements
// 1. Rename "CRM" → "Lead Pipeline" in nav + page header
// 2. Double-click name cell for inline edit (like state/size/phone)
// 3. Status change in side panel no longer re-opens side panel
// 4. Rep displayed as full name (not email username)
// 5. Last Activity shows type icon + label (📞 Call, 🎯 Demo, etc.)
// 6. Rep column is editable / assignable inline
// 7. After Save Changes modal — show "View Lead" + "Add New Lead" actions
// ============================================================

// ── 1. RENAME CRM → Lead Pipeline ────────────────────────────
document.addEventListener('DOMContentLoaded', function() {
  setTimeout(function() {
    // Nav item label
    document.querySelectorAll('.nav-item[data-section="crm"] .nav-label').forEach(function(el) {
      el.textContent = 'Lead Pipeline';
    });
    // Page header h1 inside section-crm (rendered dynamically, patch below)
  }, 400);
});

// ── Helper: get rep display name from email ────────────────────
window.anSetRepDisplayName = function(email, name) {
  if (!email) return;
  name = (name || '').replace(/\s+/g, ' ').trim();
  if (typeof _repViews === 'undefined' || !_repViews) return;
  if (!_repViews[email]) _repViews[email] = { hidden: [] };
  var oldName = _repViews[email].displayName;
  if (!name) { delete _repViews[email].displayName; } else { _repViews[email].displayName = name; }
  if (name === oldName) return; // no actual change, skip a pointless save
  saveRepViews();
  // Refresh anywhere a name might currently be shown
  if (typeof AN !== 'undefined' && AN.currentRepEmail === email && typeof anSyncCurrentRepName === 'function') anSyncCurrentRepName();
  if (typeof updateSidebarAuth === 'function' && typeof _currentUser !== 'undefined' && _currentUser) updateSidebarAuth(_currentUser);
  if (typeof renderOpportunities === 'function') renderOpportunities();
  if (typeof showToast === 'function') showToast(name ? 'Name updated' : 'Name reset to default');
};

window.anGetRepTitle = function(email) {
  if (typeof _repViews === 'undefined' || !_repViews || !_repViews[email]) return '';
  return _repViews[email].title || '';
};

window.anSetRepTitle = function(email, title) {
  if (!email) return;
  title = (title || '').replace(/\s+/g, ' ').trim();
  if (typeof _repViews === 'undefined' || !_repViews) return;
  if (!_repViews[email]) _repViews[email] = { hidden: [] };
  var oldTitle = _repViews[email].title;
  if (!title) { delete _repViews[email].title; } else { _repViews[email].title = title; }
  if (title === oldTitle) return;
  saveRepViews();
  if (typeof renderOpportunities === 'function') renderOpportunities();
  if (typeof showToast === 'function') showToast(title ? 'Title updated' : 'Title cleared');
};

function anGetRepName(email) {
  if (!email) return '—';
  // Check _repViews for stored display name
  if (typeof _repViews !== 'undefined' && _repViews[email] && _repViews[email].displayName) {
    return _repViews[email].displayName;
  }
  // Check current user
  if (typeof _currentUser !== 'undefined' && _currentUser && _currentUser.email === email) {
    var name = (_currentUser.user_metadata && _currentUser.user_metadata.full_name) || '';
    if (name) return name;
  }
  // Fall back to capitalised first part of email (e.g. asmithee → A. Smithee)
  var local = email.split('@')[0];
  // Try to split camelCase / underscores / dots
  var parts = local.replace(/[._]/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2').split(/\s+/);
  return parts.map(function(p) { return p.charAt(0).toUpperCase() + p.slice(1); }).join(' ');
}

window.anSyncCurrentRepName = function() {
  if (typeof AN === 'undefined' || !AN.currentRepEmail) return;
  if (typeof anGetRepName === 'function') AN.currentRep = anGetRepName(AN.currentRepEmail);
};
setTimeout(function(){ if (typeof anSyncCurrentRepName === 'function') anSyncCurrentRepName(); }, 100);
setTimeout(function(){ if (typeof anSyncCurrentRepName === 'function') anSyncCurrentRepName(); }, 2500);

var _origOnUserLoggedIn_repName = window.onUserLoggedIn;
window.onUserLoggedIn = function(user) {
  if (typeof _origOnUserLoggedIn_repName === 'function') _origOnUserLoggedIn_repName(user);
  setTimeout(function(){ if (typeof anSyncCurrentRepName === 'function') anSyncCurrentRepName(); }, 50);
  // Restore the section the user was on before refreshing
  try {
    var lastSection = localStorage.getItem('an-active-section');
    if (lastSection && lastSection !== 'home' && typeof showSection === 'function') {
      var navBtn = document.querySelector('.nav-item[data-section="'+lastSection+'"]');
      showSection(lastSection, navBtn || null);
    }
  } catch(e) {}
};

// ── 2. PATCH renderLeadsTable to fix: name inline edit, last activity icon, rep name ──
var _origRenderLeadsTable_fixes = window.renderLeadsTable;
window.renderLeadsTable = function() {
  _origRenderLeadsTable_fixes && _origRenderLeadsTable_fixes();
  setTimeout(function() {
    var tbody = document.querySelector('#crm-content tbody');
    if (!tbody) return;

    tbody.querySelectorAll('tr').forEach(function(tr) {
      var cb = tr.querySelector('.lead-cb');
      if (!cb) return;
      var leadId = cb.dataset.id;
      var lead = AN.leads.find(function(l){ return l.id === leadId; });
      if (!lead) return;

      var cells = tr.querySelectorAll('td');

      // ── Fix name cell (index 1) — make double-click editable ──
      var nameCell = cells[1];
      if (nameCell && !nameCell.dataset.nameFixed) {
        nameCell.dataset.nameFixed = '1';
        nameCell.style.cursor = 'text';
        nameCell.title = 'Double-click to edit name';
        nameCell.addEventListener('dblclick', function(e) {
          e.stopPropagation();
          if (nameCell.querySelector('input')) return;
          var currentFirst = lead.firstName || '';
          var currentLast  = lead.lastName  || '';
          var orig = nameCell.innerHTML;
          nameCell.innerHTML = '';
          var wrap = document.createElement('div');
          wrap.style.cssText = 'display:flex;gap:4px;';
          var inpF = document.createElement('input');
          inpF.type = 'text'; inpF.value = currentFirst; inpF.placeholder = 'First';
          inpF.style.cssText = 'width:80px;border:1.5px solid #6366f1;border-radius:5px;padding:4px 6px;font-size:12px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;';
          var inpL = document.createElement('input');
          inpL.type = 'text'; inpL.value = currentLast; inpL.placeholder = 'Last';
          inpL.style.cssText = 'width:90px;border:1.5px solid #6366f1;border-radius:5px;padding:4px 6px;font-size:12px;font-family:var(--sans);background:var(--card-bg);color:var(--text-primary);outline:none;';
          wrap.appendChild(inpF); wrap.appendChild(inpL);
          nameCell.appendChild(wrap); inpF.focus();
          function saveName() {
            var newFirst = inpF.value.trim();
            var newLast  = inpL.value.trim();
            if (newFirst !== currentFirst || newLast !== currentLast) {
              lead.firstName = newFirst; lead.lastName = newLast;
              lead.updated = new Date().toISOString();
              AN.save();
              if (typeof showToast === 'function') showToast('Name saved');
            }
            nameCell.innerHTML = '<div style="font-size:13.5px;font-weight:700;color:var(--text-primary);">'+(newFirst+' '+newLast).trim()+'</div>'
              +(lead.email?'<div style="font-size:11.5px;color:var(--text-muted);">'+anEsc(lead.email)+'</div>':'');
          }
          inpL.addEventListener('keydown', function(ev) { if(ev.key==='Enter') saveName(); if(ev.key==='Escape'){nameCell.innerHTML=orig;} });
          inpF.addEventListener('keydown', function(ev) { if(ev.key==='Tab'){ev.preventDefault();inpL.focus();} if(ev.key==='Escape'){nameCell.innerHTML=orig;} });
          inpL.addEventListener('blur', function() { setTimeout(saveName, 150); });
        });
      }

      // ── Fix last activity cell — show icon + label ──
      // Last activity cell: find it by its content (after rep col if admin)
      var lastActIdx = AN.isAdmin ? 9 : 8;
      var lastActCell = cells[lastActIdx];
      if (lastActCell && !lastActCell.dataset.actFixed) {
        lastActCell.dataset.actFixed = '1';
        var lastCall = (lead.callLog && lead.callLog.length)
          ? lead.callLog.slice().sort(function(a,b){ return b.date.localeCompare(a.date); })[0]
          : null;
        var actIcons = {pickup:'☎️',demo:'🎯',voicemail:'📬',noanswer:'📵',note:'📝'};
        var actLabels = {pickup:'Call — Picked Up',demo:'Demo Set',voicemail:'Call — Voicemail',noanswer:'Call — No Answer',note:'Note'};
        var actColors = {pickup:'#10b981',demo:'#f59e0b',voicemail:'#6366f1',noanswer:'#a1a1aa',note:'#06b6d4'};
        if (lastCall) {
          var ic = actIcons[lastCall.outcome] || '📞';
          var lb = actLabels[lastCall.outcome] || 'Call';
          var cl = actColors[lastCall.outcome] || '#a1a1aa';
          var ago = anTimeAgo(lastCall.date + (lastCall.time ? 'T' + lastCall.time : ''));
          lastActCell.innerHTML = '<div style="display:flex;align-items:center;gap:4px;">'
            +'<span style="font-size:12px;" title="'+lb+'">'+ic+'</span>'
            +'<div><div style="font-size:11.5px;font-weight:600;color:'+cl+';">'+lb+'</div>'
            +'<div style="font-size:10.5px;color:var(--text-muted);">'+ago+'</div></div></div>';
        } else {
          var sinceCreate = anTimeAgo(lead.lastContactDate || lead.created);
          lastActCell.innerHTML = '<div style="font-size:12px;color:var(--text-muted);">'+sinceCreate+'</div>'
            +'<div style="font-size:10.5px;color:var(--text-muted);margin-top:1px;">No calls yet</div>';
        }
      }

      // ── Fix owner cell — show full name + picker ──
      if (typeof anShowOwnerColumn === 'function' && anShowOwnerColumn()) {
        var repCell = Array.prototype.slice.call(cells).find(function(c) {
          return c && c.cellIndex === 7;
        });
        if (repCell) {
          var curOwner = (lead._repEmail || '');
          if(repCell.dataset.repEmail === curOwner && repCell.dataset.repFixed) return;
          repCell.dataset.repFixed = '1';
          repCell.dataset.repEmail = curOwner;
          var repEmail = lead._repEmail || '';
          var repDisplayName = anGetRepName(repEmail);
          var repCol2 = repEmail ? anColor(repEmail) : '#a1a1aa';
          repCell.innerHTML = repEmail
            ? '<span style="background:'+repCol2+'18;color:'+repCol2+';border-radius:5px;padding:2px 8px;font-size:11px;font-weight:700;cursor:pointer;" title="Change owner" onclick="event.stopPropagation();anOpenOwnerPicker({leadId:\''+leadId+'\'})">'
              +anEsc(repDisplayName)+' ▾</span>'
            : '<span style="color:var(--text-muted);font-size:12px;cursor:pointer;" onclick="event.stopPropagation();anOpenOwnerPicker({leadId:\''+leadId+'\'})">+ Assign ▾</span>';
          repCell.style.cursor = 'default';
        }
      }
    });

    // ── Fix CRM page header title ──
    var crmH1 = document.querySelector('#crm-content h1, #section-crm h1');
    if (crmH1 && crmH1.textContent.trim() === 'CRM') crmH1.textContent = 'Lead Pipeline';
    var crmLabel = document.querySelector('#section-crm .page-label');
    if (crmLabel && crmLabel.textContent.trim() === 'Sales') crmLabel.textContent = 'Sales';
  }, 100);
};

// ── 3. FIX: Status change in side panel must NOT reopen side panel ─
// The inline-edit status dropdown fires startInlineEdit → saveInlineEdit,
// which currently doesn't prevent the row-click listener from firing.
// Fix: suppress side panel open when a cell edit completes.
(function() {
  var _origSaveInlineEdit = window.saveInlineEdit || null;
  // The actual saveInlineEdit is a local function — patch via the unified table patcher instead
  // The row-click listener checks: if (e.target.dataset.field) return;
  // The status cell has data-field="status", so clicking its dropdown should be safe.
  // The issue is: the select onblur/onchange dispatches, and then the containing <tr> click fires.
  // We block <tr> click during any active edit via a flag.
  document.addEventListener('mousedown', function(e) {
    var sel = e.target.closest('select,input');
    if (sel) {
      var tr = sel.closest('tr');
      if (tr) tr.dataset.editing = '1';
    }
  }, true);
  document.addEventListener('blur', function(e) {
    if (e.target.tagName === 'SELECT' || e.target.tagName === 'INPUT') {
      var tr = e.target.closest('tr');
      if (tr) setTimeout(function(){ delete tr.dataset.editing; }, 300);
    }
  }, true);

  // Patch the row-click handler added in the unified CRM patch
  var _origRLT_opp = window.renderLeadsTable;
  window.renderLeadsTable = function() {
    _origRLT_opp && _origRLT_opp();
    setTimeout(function() {
      var tbody = document.querySelector('#crm-content tbody');
      if (!tbody) return;
      tbody.querySelectorAll('tr').forEach(function(tr) {
        // Mark all select dropdowns in this row to stop propagation
        tr.querySelectorAll('select').forEach(function(sel) {
          if (!sel.dataset.clickFixed) {
            sel.dataset.clickFixed = '1';
            sel.addEventListener('click', function(e) { e.stopPropagation(); });
            sel.addEventListener('mousedown', function(e) { e.stopPropagation(); });
          }
        });
      });
    }, 200);
  };
})();

