// ── Role definitions ─────────────────────────────────────────
var AN_ROLES = {
  admin: { label:'Admin', color:'#ef4444', tabs:['activity','deals','demos','showrate'] },
  ae:    { label:'AE',    color:'#6366f1', tabs:['activity','deals','demos','showrate'] },
  sdr:   { label:'SDR',   color:'#f59e0b', tabs:['activity','demos'] }
};

var DASH_TAB_DEFS = {
  activity: { label:'Activity',     icon:'📊' },
  deals:    { label:'Deals',        icon:'💼' },
  demos:    { label:'Demo Tracker', icon:'🎯' },
  showrate: { label:'Show Rate',    icon:'📈' }
};

function anGetMyRole() {
  if (AN && AN.isAdmin) return 'admin';
  var email = (AN && AN.currentRepEmail) || '';
  if (!email) return 'sdr';
  if (typeof loadRepViews === 'function') loadRepViews();
  var rv = (typeof _repViews !== 'undefined') ? _repViews[email] : null;
  return (rv && rv.role) ? rv.role : 'sdr';
}

function anGetAllowedTabs(role) {
  return (AN_ROLES[role] || AN_ROLES.sdr).tabs;
}

// ── Patch buildAndShowCharts to filter sub-tabs by role ──────
// We patch AFTER all existing overrides so we run last in chain.
// We don't rebuild the entire pane — just hide/remove tabs the
// role can't see after the existing code has rendered them.
document.addEventListener('DOMContentLoaded', function() {
  setTimeout(function() {
    var _lastBAC = window.buildAndShowCharts;
    window.buildAndShowCharts = function() {
      _lastBAC && _lastBAC();
      // After charts render, enforce role tab visibility
      setTimeout(applyRoleTabVisibility, 80);
    };
  }, 600); // run after all other overrides
});

function applyRoleTabVisibility() {
  var role = anGetMyRole();
  var allowed = anGetAllowedTabs(role);
  var sdrTabs = ['activity','demos','showrate'];

  sdrTabs.forEach(function(k) {
    var tabBtn = document.getElementById('rt-'+k);
    if (!tabBtn) return;
    tabBtn.style.display = allowed.indexOf(k) < 0 ? 'none' : '';
  });

  // Hide AE main tab for SDR-only roles (no deals access)
  var tabBar = document.getElementById('dash-tab-bar');
  if (tabBar && tabBar.children[1]) {
    tabBar.children[1].style.display = allowed.indexOf('deals') < 0 ? 'none' : '';
  }
}

