// ── 1. Fix anSaveLead to also capture demoTz dropdown ────────
var _origAnSaveLead_tz = window.anSaveLead;
window.anSaveLead = function(id) {
  var tzEl = document.getElementById('alf-prospect-tz');
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id===id; }) : null;
  if (lead && tzEl && tzEl.value) lead.demoTz = tzEl.value;
  _origAnSaveLead_tz && _origAnSaveLead_tz(id);
};

// ── 2. CALL MODE SIDE PANEL — tap phone or Call Session to launch ─
window.mcmCloseCallPanelOnly = function(){
  var wrap = document.getElementById('mcm-panel-wrap');
  if (wrap) {
    var ov = document.getElementById('mcm-overlay');
    if (ov && ov._keyHandler) document.removeEventListener('keydown', ov._keyHandler);
    wrap.remove();
  }
  var backdrop = document.getElementById('call-panel-backdrop');
  if (backdrop) backdrop.remove();
  var dock = document.getElementById('mcm-dock-bar');
  if (dock) dock.remove();
  document.body.classList.remove('call-panel-open', 'call-panel-minimized', 'call-lead-collapsed', 'call-session-dual', 'call-lead-front', 'call-company-front');
  if (typeof anRenderCallSessionBanner === 'function') anRenderCallSessionBanner();
};

window.mcmToggleLeadPanel = function() {
  var collapsed = !document.body.classList.contains('call-lead-collapsed');
  if (!collapsed) {
    var ov = document.getElementById('mcm-overlay');
    if (!document.getElementById('an-cs-lead-panel') && ov && ov._leadId && typeof anRenderCallSessionLeadPanel === 'function') {
      anRenderCallSessionLeadPanel(ov._leadId);
    }
  }
  if (!collapsed && document.body.classList.contains('co-full-record-over-call') && typeof coCloseCompanyPanel === 'function') {
    coCloseCompanyPanel();
  }
  document.body.classList.toggle('call-lead-collapsed', collapsed);
  if (window.innerWidth <= 900) {
    document.body.classList.toggle('call-lead-front', !collapsed);
    if (!collapsed) {
      document.body.classList.remove('call-company-front');
      if (typeof anCloseCallSessionCompanyPanel === 'function') anCloseCallSessionCompanyPanel();
    }
  }
  var btn = document.getElementById('mcm-lead-toggle');
  if (btn) {
    btn.textContent = '👤';
    btn.title = collapsed ? 'Show lead profile' : 'Hide lead profile';
    btn.style.background = collapsed ? 'rgba(255,255,255,0.08)' : 'rgba(99,102,241,0.22)';
  }
  var panelHide = document.getElementById('mcm-lead-panel-hide');
  if (panelHide) panelHide.style.display = collapsed ? 'none' : 'flex';
  try { localStorage.setItem('mcm-lead-collapsed', collapsed ? '1' : '0'); } catch(e) {}
  if (typeof anRepositionCallSessionCompanyPanel === 'function') anRepositionCallSessionCompanyPanel();
};

window.mcmWireCallPanelHeader = function() {
  var overlay = document.getElementById('mcm-overlay');
  if (!overlay) return;
  var companyBtn = document.getElementById('mcm-company-toggle');
  var leadBtn = document.getElementById('mcm-lead-toggle');
  var minBtn = overlay.querySelector('button[title="Minimize"]');
  var closeBtn = document.getElementById('mcm-header-close');
  if (companyBtn) companyBtn.onclick = function(e){ e.preventDefault(); e.stopPropagation(); mcmToggleCompanyPanel(); };
  if (leadBtn) leadBtn.onclick = function(e){ e.preventDefault(); e.stopPropagation(); mcmToggleLeadPanel(); };
  if (minBtn) minBtn.onclick = function(e){ e.preventDefault(); e.stopPropagation(); mcmToggleMinimize(true); };
  if (closeBtn) closeBtn.onclick = function(e){
    e.preventDefault(); e.stopPropagation();
    if (overlay._keyHandler) document.removeEventListener('keydown', overlay._keyHandler);
    mcmClose();
  };
};

window.mcmToggleMinimize = function(forceMin) {
  var minimized = typeof forceMin === 'boolean' ? forceMin : !document.body.classList.contains('call-panel-minimized');
  document.body.classList.toggle('call-panel-minimized', minimized);
  if (minimized) document.body.classList.remove('call-lead-front', 'call-company-front');
  if (typeof mcmRenderDockBar === 'function') mcmRenderDockBar();
  if (!minimized && typeof mcmRenderDayGoalsWidget === 'function') mcmRenderDayGoalsWidget();
};

window.mcmRenderDayGoalsWidget = function() {
  var slot = document.getElementById('mcm-day-goals-slot');
  if (!slot) return;
  var items = [
    { key: 'calls', label: 'Calls', color: '#6366f1' },
    { key: 'demos', label: 'Demos', color: '#14b8a6' },
    { key: 'closes', label: 'Closes', color: '#f59e0b' }
  ];
  var act = (typeof getActivityForPeriod === 'function') ? getActivityForPeriod('today') : { calls: 0, demos: 0, closes: 0, demos_showed: 0 };
  var rows = items.map(function(it) {
    var actual = act[it.key] || 0;
    var goal = (typeof getGoalForPeriod === 'function') ? getGoalForPeriod(it.key, 'today') : 0;
    var pct = goal > 0 ? Math.min(100, Math.round((actual / goal) * 100)) : (actual > 0 ? 100 : 0);
    var sub = (it.key === 'demos' && act.demos_showed) ? ' <span style="font-size:8px;color:rgba(255,255,255,0.35);">('+act.demos_showed+' showed)</span>' : '';
    return '<div style="min-width:0;">'
      + '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px;">'
      + '<span style="font-size:10px;font-weight:600;color:rgba(255,255,255,0.55);">'+it.label+'</span>'
      + '<span style="font-size:11px;font-weight:800;color:'+it.color+';">'+actual+'<span style="font-size:9px;font-weight:600;color:rgba(255,255,255,0.35);">/'+(goal || '—')+'</span>'+sub+'</span>'
      + '</div>'
      + '<div style="background:rgba(255,255,255,0.08);border-radius:6px;height:4px;overflow:hidden;">'
      + '<div style="width:'+pct+'%;height:100%;background:'+it.color+';border-radius:6px;transition:width 0.3s;"></div>'
      + '</div></div>';
  }).join('');
  var ov = document.getElementById('mcm-overlay');
  var sessionLine = '';
  if (ov && ov._leadId && typeof anGetCallQueueProgress === 'function') {
    var prog = anGetCallQueueProgress(ov._leadId);
    if (prog) {
      sessionLine = '<div style="font-size:9px;color:rgba(255,255,255,0.32);margin-top:8px;text-align:center;">Session '+prog.pos+'/'+prog.total+' logged · '+prog.remaining+' left in queue</div>';
    }
  }
  slot.innerHTML = '<div style="padding:10px 14px 12px;background:rgba(99,102,241,0.07);border-bottom:1px solid rgba(255,255,255,0.06);flex-shrink:0;">'
    + '<div style="font-size:9px;font-weight:700;color:rgba(255,255,255,0.38);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:8px;">Today\'s Activity Goals</div>'
    + '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;">'+rows+'</div>'
    + sessionLine
    + '</div>';
};

window.mcmRenderDockBar = function() {
  var dock = document.getElementById('mcm-dock-bar');
  if (!document.body.classList.contains('call-panel-minimized')) {
    if (dock) dock.style.display = 'none';
    return;
  }
  if (!dock) {
    dock = document.createElement('div');
    dock.id = 'mcm-dock-bar';
    document.body.appendChild(dock);
  }
  dock.style.cssText = 'position:fixed;bottom:16px;right:16px;z-index:20002;background:#0f0f1f;border:1.5px solid rgba(99,102,241,0.35);border-radius:14px;padding:12px 14px;display:flex;flex-direction:column;gap:8px;font-family:var(--sans);box-shadow:0 8px 32px rgba(0,0,0,0.35);min-width:240px;max-width:320px;';
  var act = (typeof getActivityForPeriod === 'function') ? getActivityForPeriod('today') : { calls: 0, demos: 0, closes: 0 };
  var ov = document.getElementById('mcm-overlay');
  var leadId = ov && ov._leadId;
  var lead = leadId && typeof AN !== 'undefined' ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  var leadName = lead ? (((lead.firstName||'')+' '+(lead.lastName||'')).trim() || lead.company || 'Lead') : 'Call session';
  var sessionTxt = '';
  if (leadId && typeof anGetCallQueueProgress === 'function') {
    var prog = anGetCallQueueProgress(leadId);
    if (prog) sessionTxt = ' · Queue '+prog.pos+'/'+prog.total;
  }
  dock.innerHTML = '<div style="font-size:11px;font-weight:800;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">📞 '+mcmEsc(leadName)+sessionTxt+'</div>'
    + '<div style="display:flex;gap:10px;font-size:10px;font-weight:700;">'
    + '<span style="color:#818cf8;">'+((act.calls||0))+' calls</span>'
    + '<span style="color:#2dd4bf;">'+((act.demos||0))+' demos</span>'
    + '<span style="color:#fbbf24;">'+((act.closes||0))+' closes</span>'
    + '</div>'
    + '<button type="button" onclick="mcmToggleMinimize(false)" style="width:100%;padding:8px 12px;border-radius:8px;border:none;background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">Expand call panel</button>';
  dock.style.display = 'flex';
};

window.mcmClose = function(){
  var ov = document.getElementById('mcm-overlay');
  var leadId = ov && (ov._leadId || window._anCsLeadPanelId);
  if (leadId && ov && (ov._pendingDemo || ov._demoModalShown || ov._outcome === 'demo')) {
    mcmDismissDemoFlow(leadId);
  } else {
    mcmCloseDemoAutomationModal();
  }
  mcmCloseCallPanelOnly();
  if (typeof anCloseCallSessionLeadPanel === 'function') anCloseCallSessionLeadPanel();
  if (typeof anCloseCallSessionCompanyPanel === 'function') anCloseCallSessionCompanyPanel();
};

window.openMobileCallMode = function(leadId) {
  mcmCloseCallPanelOnly();
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id===leadId; }) : null;
  if (!lead) return;
  if (typeof anHydrateLeadState === 'function') anHydrateLeadState(lead);

  var mode = anGetCallPanelMode(lead);
  var name = ((lead.firstName||'') + ' ' + (lead.lastName||'')).trim() || lead.company || (mode === 'opportunity' ? 'Deal' : 'Lead');
  var phone = anFormatPhone(lead.phone || '');
  var telPhone = anTelPhone(lead.phone || '');
  var rawPhone = lead.phone || '';
  var rawEmail = lead.email || '';
  var statuses = mode === 'opportunity'
    ? AN_OPP_STATUSES.map(function(s){ return { v:s.id, l:s.label, c:s.color }; })
    : AN_LEAD_STATUSES.map(function(s){ return { v:s.id, l:s.label, c:s.color }; });

  var outcomes = mode === 'opportunity'
    ? [
        { v:'connected',  l:'✅ Connected',       c:'#10b981' },
        { v:'noanswer',   l:'📵 No Answer',       c:'#a1a1aa' },
        { v:'voicemail',  l:'📬 Voicemail',       c:'#6366f1' },
        { v:'objection',  l:'🛡 Objection',        c:'#f59e0b' },
        { v:'next_step',  l:'📋 Next Step Set',   c:'#06b6d4' },
        { v:'won',        l:'🏆 Closed Won',      c:'#10b981' }
      ]
    : [
        { v:'pickup',    l:'📞 Picked Up',    c:'#10b981' },
        { v:'noanswer',  l:'📵 No Answer',    c:'#a1a1aa' },
        { v:'voicemail', l:'📬 Voicemail',    c:'#6366f1' },
        { v:'emailed',   l:'✉️ Sent Email',   c:'#8b5cf6' },
        { v:'demo',      l:'🎯 Book Demo',    c:'#f59e0b' },
        { v:'demo_complete', l:'✅ Demo Completed', c:'#06b6d4' },
        { v:'callback',  l:'⏰ Follow Up',    c:'#06b6d4' }
      ];

  var sessionBadge = mode === 'opportunity'
    ? '<span style="font-size:10px;font-weight:700;color:#f59e0b;text-transform:uppercase;letter-spacing:0.1em;">💎 Deal Session</span>'
    : '<span style="font-size:10px;font-weight:700;color:#10b981;text-transform:uppercase;letter-spacing:0.1em;">📞 Lead Session</span>';
  var sessionStatusLabel = typeof anStatus === 'function' ? anStatus(lead.status || 'new').label : (lead.status || 'new');
  var sessionMeta = '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:6px;align-items:center;">'
    +(lead.state ? '<span style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.45);">📍 '+mcmEsc(lead.state)+'</span>' : '')
    +'<span style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.55);background:rgba(255,255,255,0.08);border-radius:20px;padding:2px 9px;">'+mcmEsc(sessionStatusLabel)+'</span>'
    +'</div>';

  var wrap = document.createElement('div');
  wrap.id = 'mcm-panel-wrap';

  var overlay = document.createElement('div');
  overlay.id = 'mcm-overlay';
  overlay.style.cssText = 'width:100%;height:100%;background:#0a0a14;display:flex;flex-direction:column;overflow-y:auto;-webkit-overflow-scrolling:touch;';

  overlay.innerHTML =
    // Header — compact; title/agency live in the lead profile panel
    '<div id="mcm-call-header" style="background:linear-gradient(135deg,#1a1640,#0f0f1f);padding:12px 16px;border-bottom:1px solid rgba(255,255,255,0.06);flex-shrink:0;position:sticky;top:0;z-index:12;">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px;">'
    +sessionBadge
    +'<div class="mcm-header-toolbar" style="display:flex;gap:4px;align-items:center;flex-shrink:0;">'
    +'<button type="button" id="mcm-company-toggle" onclick="event.stopPropagation();mcmToggleCompanyPanel();" title="Agency profile" style="background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.12);color:rgba(255,255,255,0.65);width:34px;height:34px;border-radius:8px;font-size:14px;cursor:pointer;font-family:inherit;line-height:1;touch-action:manipulation;">🏢</button>'
    +'<button type="button" id="mcm-lead-toggle" onclick="event.stopPropagation();mcmToggleLeadPanel();" title="Hide lead profile" style="background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.12);color:rgba(255,255,255,0.65);width:34px;height:34px;border-radius:8px;font-size:14px;cursor:pointer;font-family:inherit;line-height:1;touch-action:manipulation;">👤</button>'
    +'<button type="button" title="Minimize" onclick="event.stopPropagation();mcmToggleMinimize();" style="background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.12);color:rgba(255,255,255,0.65);width:34px;height:34px;border-radius:8px;font-size:16px;font-weight:700;cursor:pointer;font-family:inherit;line-height:1;touch-action:manipulation;">−</button>'
    +'<button type="button" id="mcm-header-close" onclick="event.stopPropagation();mcmClose();" title="Close session" style="background:rgba(255,255,255,0.08);border:none;color:rgba(255,255,255,0.5);width:34px;height:34px;border-radius:8px;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;touch-action:manipulation;">×</button>'
    +'</div></div>'
    +'<div id="mcm-header-name" style="font-size:17px;font-weight:800;color:#fff;letter-spacing:-0.3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.2;">'+mcmEsc(name)+'</div>'
    +sessionMeta
    +'</div>'

    +'<div id="mcm-day-goals-slot"></div>'

    // Phone + Call button
    +'<div style="padding:16px 18px;border-bottom:1px solid rgba(255,255,255,0.06);">'
    +(phone
      ? '<div style="background:rgba(16,185,129,0.08);border:1.5px solid rgba(16,185,129,0.2);border-radius:12px;padding:12px 16px;margin-bottom:10px;">'
        +'<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:4px;">Phone Number</div>'
        +(telPhone
          ? '<a href="tel:'+mcmEsc(telPhone)+'" style="display:block;font-size:16px;font-weight:700;color:#fff;letter-spacing:0.03em;text-decoration:none;">'+mcmEsc(phone)+'</a>'
          : '<div style="font-size:16px;font-weight:700;color:#fff;letter-spacing:0.03em;">'+mcmEsc(phone)+'</div>')
        +'<div id="mcm-attempt-badge" style="font-size:10px;color:rgba(110,231,183,0.85);margin-top:5px;line-height:1.45;"></div>'
        +'<div style="font-size:10px;color:rgba(255,255,255,0.38);margin-top:8px;line-height:1.5;">Tap number to dial · pick an outcome → <strong style="color:#6ee7b7;">Log Call &amp; Stay</strong> to redial</div>'
        +'</div>'
      : '<div style="background:rgba(255,255,255,0.04);border:1.5px solid rgba(255,255,255,0.1);border-radius:14px;padding:16px 20px;text-align:center;margin-bottom:10px;">'
        +'<div style="font-size:13px;color:rgba(255,255,255,0.4);">No phone number on file</div>'
        +'<button onclick="mcmEditPhone(\''+leadId+'\')" style="margin-top:8px;background:rgba(99,102,241,0.2);border:1px solid rgba(99,102,241,0.4);color:#a5b4fc;border-radius:8px;padding:7px 16px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">+ Add Phone Number</button>'
        +'</div>')
    +(rawEmail
      ? '<div style="background:rgba(99,102,241,0.08);border:1.5px solid rgba(99,102,241,0.2);border-radius:12px;padding:12px 16px;">'
        +'<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:4px;">Email</div>'
        +'<a href="mailto:'+mcmEsc(rawEmail)+'" style="display:block;font-size:13px;font-weight:600;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-decoration:none;">'+mcmEsc(rawEmail)+'</a>'
        +'</div>'
      : '')
    +'</div>'

    // Cold call script (filled when Call Session is active)
    +'<div id="mcm-script-slot"></div>'

    // Quick outcome buttons
    +'<div style="padding:16px 18px;border-bottom:1px solid rgba(255,255,255,0.06);">'
    +'<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:12px;">'+(mode==='opportunity'?'Call Result':'Call Outcome')+'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">'
    +outcomes.map(function(o) {
      return '<button onclick="mcmSetOutcome(\''+o.v+'\',\''+leadId+'\')" id="mcm-outcome-'+o.v+'" '
        +'style="padding:12px;border-radius:10px;border:1.5px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.04);color:rgba(255,255,255,0.7);font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;text-align:left;transition:all 0.15s;">'
        +o.l+'</button>';
    }).join('')
    +'</div></div>'

    // Demo scheduler (shown when Demo Set is selected)
    +'<div id="mcm-demo-slot"></div>'

    // Follow-up scheduler (shown when Follow Up is selected)
    +'<div id="mcm-followup-slot"></div>'

    // Quick status update
    +'<div style="padding:16px 18px;border-bottom:1px solid rgba(255,255,255,0.06);">'
    +'<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.12em;margin-bottom:12px;">Update Status</div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:6px;">'
    +statuses.map(function(s) {
      var curStatus = lead.status || (mode === 'opportunity' ? 'demo' : 'new');
      var isCurrent = curStatus === s.v;
      return '<button onclick="mcmSetStatus(\''+s.v+'\',\''+leadId+'\')" id="mcm-status-'+s.v+'" '
        +'style="padding:8px 14px;border-radius:20px;border:1.5px solid '+(isCurrent?s.c:'rgba(255,255,255,0.1)')+';background:'+(isCurrent?s.c+'22':'transparent')+';color:'+(isCurrent?s.c:'rgba(255,255,255,0.5)')+';font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;transition:all 0.15s;">'
        +s.l+'</button>';
    }).join('')
    +'</div></div>'

    // Quick note + email log shortcut
    +'<div style="padding:16px 18px;border-bottom:1px solid rgba(255,255,255,0.06);">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">'
    +'<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.12em;">Quick Note</div>'
    +'<button type="button" onclick="mcmSaveNoteOnly(\''+leadId+'\')" style="background:rgba(245,158,11,0.15);border:1px solid rgba(245,158,11,0.4);color:#fcd34d;border-radius:6px;padding:4px 10px;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;">📝 Note only</button>'
    +'<button type="button" onclick="anQuickLogEmail(\''+leadId+'\', document.getElementById(\'mcm-note\') ? document.getElementById(\'mcm-note\').value : \'\')" style="background:rgba(139,92,246,0.2);border:1px solid rgba(139,92,246,0.45);color:#c4b5fd;border-radius:6px;padding:4px 10px;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;">✉️ Email only</button>'
    +'</div>'
    +'<textarea id="mcm-note" rows="3" placeholder="What happened on this call..." '
    +'style="width:100%;background:rgba(255,255,255,0.05);border:1.5px solid rgba(255,255,255,0.1);border-radius:10px;padding:12px 14px;font-size:13px;color:#fff;font-family:inherit;outline:none;resize:none;box-sizing:border-box;" '
    +'onfocus="this.style.borderColor=\'rgba(99,102,241,0.6)\'" onblur="this.style.borderColor=\'rgba(255,255,255,0.1)\'"></textarea>'
    +'</div>'

    // Save + next actions
    +'<div id="mcm-action-buttons" style="padding:16px 18px 24px;display:flex;flex-direction:column;gap:10px;flex-shrink:0;">'
    +'<div style="display:flex;gap:8px;">'
    +'<button id="mcm-btn-prev" onclick="mcmPrevLead(\''+leadId+'\')" title="Previous contact in this session" style="flex:0 0 auto;padding:14px 14px;border-radius:12px;border:1.5px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.06);color:rgba(255,255,255,0.75);font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;">← Back</button>'
    +'<button id="mcm-btn-save-next" onclick="mcmSaveAndNext(\''+leadId+'\')" style="flex:1;padding:14px;border-radius:12px;border:none;background:linear-gradient(135deg,#10b981,#059669);color:#fff;font-size:15px;font-weight:800;cursor:pointer;font-family:inherit;box-shadow:0 4px 20px rgba(16,185,129,0.35);">✓ Log &amp; Next →</button>'
    +'</div>'
    +'<button id="mcm-btn-save-stay" onclick="mcmSaveAndStay(\''+leadId+'\')" style="width:100%;padding:12px;border-radius:12px;border:1.5px solid rgba(99,102,241,0.45);background:rgba(99,102,241,0.12);color:#c7d2fe;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;">📞 Log Call &amp; Stay</button>'
    +'<button id="mcm-btn-skip" onclick="mcmNextLead(\''+leadId+'\')" style="width:100%;padding:11px;border-radius:12px;border:1.5px solid rgba(255,255,255,0.12);background:transparent;color:rgba(255,255,255,0.55);font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;">⏭ Skip to Next (no log)</button>'
    +'<div style="font-size:10px;color:rgba(255,255,255,0.35);text-align:center;line-height:1.45;">Shortcuts: <strong style="color:rgba(255,255,255,0.5);">B</strong> back · <strong style="color:rgba(255,255,255,0.5);">N</strong> next · <strong style="color:rgba(255,255,255,0.5);">S</strong> stay · <strong style="color:rgba(255,255,255,0.5);">⌘↵</strong> note only</div>'
    +'<button onclick="mcmClose()" style="width:100%;padding:10px;border-radius:12px;border:none;background:transparent;color:rgba(255,255,255,0.3);font-size:13px;cursor:pointer;font-family:inherit;">Close panel</button>'
    +'</div>';

  wrap.appendChild(overlay);
  document.body.appendChild(wrap);
  document.body.classList.add('call-panel-open');
  document.body.classList.remove('call-panel-minimized');
  var oldBackdrop = document.getElementById('call-panel-backdrop');
  if (oldBackdrop) oldBackdrop.remove();
  if (typeof anRenderCallSessionBanner === 'function') anRenderCallSessionBanner();
  if (typeof mcmRenderDayGoalsWidget === 'function') mcmRenderDayGoalsWidget();
  try {
    if (localStorage.getItem('mcm-lead-collapsed') === '1') mcmToggleLeadPanel();
  } catch(e) {}

  // Track selected outcome + session mode
  overlay._outcome = null;
  overlay._callMode = mode;
  overlay._leadId = leadId;
  overlay._pendingDemo = false;
  overlay._demoModalShown = false;
  overlay._demoSaved = !!(lead.status === 'booked_demo' && lead.demoDate && lead.demoTime);

  if (typeof anRenderCallScript === 'function') anRenderCallScript(leadId);
  if (typeof anRenderCallSessionLeadPanel === 'function') anRenderCallSessionLeadPanel(leadId);
  if (typeof mcmRefreshAttemptBadge === 'function') mcmRefreshAttemptBadge(leadId);
  if (typeof mcmWireCallPanelHeader === 'function') mcmWireCallPanelHeader();
};

function mcmEsc(s) { return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

function mcmCountTodayAttempts(lead) {
  if (!lead || !lead.callLog || !lead.callLog.length) return 0;
  var today = new Date().toISOString().split('T')[0];
  return lead.callLog.filter(function(c) {
    return c.date === today && c.outcome !== 'emailed';
  }).length;
}

window.mcmRefreshAttemptBadge = function(leadId) {
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  var el = document.getElementById('mcm-attempt-badge');
  if (!el) return;
  var n = mcmCountTodayAttempts(lead);
  el.textContent = n
    ? (n + ' call attempt' + (n !== 1 ? 's' : '') + ' logged today — dial again anytime')
    : 'No calls logged today yet';
};

window.mcmSaveAndStay = function(leadId) {
  if (!mcmSave(leadId, { keepOpen: true })) return;
  if (typeof mcmRefreshAttemptBadge === 'function') mcmRefreshAttemptBadge(leadId);
  var noteEl = document.getElementById('mcm-note');
  if (noteEl) noteEl.focus();
};

window.mcmCloseDemoAutomationModal = function() {
  var m = document.getElementById('demo-auto-modal');
  if (m) m.remove();
  var ov = document.getElementById('mcm-overlay');
  if (ov) ov._demoModalShown = false;
};

window.anCloseDemoAutoModal = function() {
  mcmCloseDemoAutomationModal();
};

window.mcmHighlightOutcome = function(outcome) {
  var outcomeColors = {
    pickup:'#10b981', noanswer:'#a1a1aa', voicemail:'#6366f1', demo:'#f59e0b', demo_complete:'#06b6d4', callback:'#06b6d4', emailed:'#8b5cf6',
    connected:'#10b981', objection:'#f59e0b', next_step:'#06b6d4', won:'#10b981'
  };
  document.querySelectorAll('[id^="mcm-outcome-"]').forEach(function(btn) {
    btn.style.background = 'rgba(255,255,255,0.04)';
    btn.style.borderColor = 'rgba(255,255,255,0.1)';
    btn.style.color = 'rgba(255,255,255,0.7)';
  });
  if (!outcome) return;
  var sel = document.getElementById('mcm-outcome-' + outcome);
  if (sel) {
    var col = outcomeColors[outcome] || '#6366f1';
    sel.style.background = col + '22';
    sel.style.borderColor = col;
    sel.style.color = col;
  }
};

window.mcmUpdateStatusPills = function(status) {
  var statusColors = {};
  AN_LEAD_STATUSES.concat(AN_OPP_STATUSES).forEach(function(s){ statusColors[s.id] = s.color; });
  document.querySelectorAll('[id^="mcm-status-"]').forEach(function(btn) {
    btn.style.background = 'transparent';
    btn.style.borderColor = 'rgba(255,255,255,0.1)';
    btn.style.color = 'rgba(255,255,255,0.5)';
  });
  var sel = document.getElementById('mcm-status-' + status);
  if (sel) {
    var col = statusColors[status] || '#6366f1';
    sel.style.background = col + '22';
    sel.style.borderColor = col;
    sel.style.color = col;
  }
  var overlay = document.getElementById('mcm-overlay');
  if (overlay) overlay._status = status;
};

window.mcmDismissDemoFlow = function(leadId) {
  mcmCloseDemoAutomationModal();
  mcmHideDemoForm();
  var overlay = document.getElementById('mcm-overlay');
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  if (!overlay) return;
  var wasDemo = overlay._pendingDemo || overlay._demoModalShown || overlay._outcome === 'demo';
  if (!wasDemo) return;
  var revertStatus = overlay._prevStatus || (lead && lead.status !== 'booked_demo' ? lead.status : 'new') || 'new';
  overlay._pendingDemo = false;
  overlay._demoModalShown = false;
  overlay._demoDate = '';
  overlay._demoTime = '';
  overlay._demoTz = '';
  overlay._demoTzConfirmed = false;
  if (overlay._outcome === 'demo') overlay._outcome = null;
  mcmHighlightOutcome(null);
  if (lead && !overlay._demoSaved) {
    if (lead.status === 'booked_demo') lead.status = revertStatus;
    delete lead.demoDate;
    delete lead.demoTime;
    delete lead.demoTz;
  }
  mcmUpdateStatusPills(revertStatus);
};

window.mcmEnterDemoScheduling = function(leadId) {
  var overlay = document.getElementById('mcm-overlay');
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  if (!overlay || !lead) return;
  if (!overlay._pendingDemo && overlay._outcome !== 'demo') {
    overlay._prevStatus = lead.status || 'new';
    overlay._demoSaved = false;
  }
  mcmCloseDemoAutomationModal();
  overlay._pendingDemo = true;
  overlay._demoModalShown = false;
  overlay._outcome = 'demo';
  mcmHighlightOutcome('demo');
  mcmHideFollowupForm();
  mcmRenderDemoForm(leadId);
};

window.mcmTryOpenDemoFollowThroughModal = function(leadId) {
  var overlay = document.getElementById('mcm-overlay');
  if (!overlay || !overlay._pendingDemo || overlay._demoModalShown) return;
  if (!overlay._demoDate || !overlay._demoTime || !overlay._demoTz) return;
  mcmOpenDemoFollowThroughModal(leadId);
};

window.mcmOpenDemoFollowThroughModal = function(leadId) {
  var overlay = document.getElementById('mcm-overlay');
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  if (!overlay || !lead) return;
  if (!overlay._demoDate || !overlay._demoTime || !overlay._demoTz) return;
  lead.demoDate = overlay._demoDate;
  lead.demoTime = overlay._demoTime;
  lead.demoTz = overlay._demoTz;
  overlay._outcome = 'demo';
  overlay._status = 'booked_demo';
  overlay._pendingDemo = false;
  overlay._demoModalShown = true;
  mcmHideDemoForm();
  mcmUpdateStatusPills('booked_demo');
  mcmHighlightOutcome('demo');
  if (typeof showDemoAutomationPanel === 'function') showDemoAutomationPanel(lead);
};

window.mcmSetOutcome = function(outcome, leadId) {
  var overlay = document.getElementById('mcm-overlay');
  if (!overlay) return;

  var mode = overlay._callMode || 'lead';
  if (mode === 'lead') {
    if (outcome === 'demo') {
      mcmEnterDemoScheduling(leadId);
      return;
    }
    if (outcome === 'demo_complete') {
      mcmSetStatus('demo_complete', leadId);
      return;
    }
    if (overlay._pendingDemo || overlay._demoModalShown || overlay._outcome === 'demo') {
      mcmDismissDemoFlow(leadId);
    }
    overlay._outcome = outcome;
    mcmHighlightOutcome(outcome);
    if (outcome === 'callback') {
      mcmSetStatus('followup', leadId);
      mcmRenderFollowupForm(leadId);
    } else {
      mcmHideFollowupForm();
      if (outcome === 'pickup') mcmSetStatus('contacted', leadId);
      else if (outcome === 'emailed') mcmSetStatus('emailed', leadId);
      else mcmUpdateStatusPills(overlay._status || 'new');
    }
  } else {
    overlay._outcome = outcome;
    mcmHighlightOutcome(outcome);
    mcmHideDemoForm();
    mcmDismissDemoFlow(leadId);
    if (outcome === 'connected') mcmSetStatus('showed', leadId);
    else if (outcome === 'next_step') mcmSetStatus('proposal', leadId);
    else if (outcome === 'objection') mcmSetStatus('negotiation', leadId);
    else if (outcome === 'won') mcmSetStatus('won', leadId);
  }
};

window.mcmHideDemoForm = function() {
  var slot = document.getElementById('mcm-demo-slot');
  if (slot) slot.innerHTML = '';
};

window.mcmHideFollowupForm = function() {
  var slot = document.getElementById('mcm-followup-slot');
  if (slot) slot.innerHTML = '';
};

window.mcmSetFollowupQuick = function(leadId, daysFromNow) {
  var overlay = document.getElementById('mcm-overlay');
  if (!overlay) return;
  var d = new Date();
  d.setDate(d.getDate() + (daysFromNow || 0));
  overlay._followupDate = d.toISOString().split('T')[0];
  if (!overlay._followupTime) overlay._followupTime = '14:00';
  mcmRenderFollowupForm(leadId);
};

window.mcmRenderFollowupForm = function(leadId) {
  var overlay = document.getElementById('mcm-overlay');
  var slot = document.getElementById('mcm-followup-slot');
  if (!overlay || !slot) return;
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  if (!lead) return;

  if (!overlay._followupDate) {
    var def = new Date();
    def.setDate(def.getDate() + 1);
    overlay._followupDate = lead.nextFollowUp || def.toISOString().split('T')[0];
  }
  if (!overlay._followupTime) overlay._followupTime = lead.followUpTime || '14:00';
  if (!overlay._followupMethod) overlay._followupMethod = lead.followUpMethod || 'call';

  var methods = [
    { id:'call', label:'📞 Call', color:'#6366f1' },
    { id:'email', label:'📧 Email', color:'#f59e0b' },
    { id:'text', label:'💬 Text', color:'#10b981' }
  ];

  slot.innerHTML =
    '<div id="mcm-followup-block" style="padding:16px 18px;border-bottom:1px solid rgba(255,255,255,0.06);background:rgba(6,182,212,0.08);">'
    +'<div style="font-size:10px;font-weight:700;color:#67e8f9;text-transform:uppercase;letter-spacing:0.12em;margin-bottom:10px;">⏰ Schedule Follow-Up</div>'
    +'<div style="font-size:11px;color:rgba(255,255,255,0.5);margin-bottom:12px;line-height:1.45;">When should you reach back out? This appears on Home under Follow-ups Due.</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px;">'
    +'<div><div style="font-size:9px;font-weight:700;color:rgba(255,255,255,0.35);margin-bottom:4px;">DATE</div>'
    +'<input id="mcm-fu-date" type="date" value="'+overlay._followupDate+'" onchange="var o=document.getElementById(\'mcm-overlay\');if(o)o._followupDate=this.value;" '
    +'style="width:100%;background:rgba(255,255,255,0.06);border:1.5px solid rgba(6,182,212,0.35);border-radius:8px;padding:9px 10px;font-size:12px;color:#fff;font-family:inherit;box-sizing:border-box;"></div>'
    +'<div><div style="font-size:9px;font-weight:700;color:rgba(255,255,255,0.35);margin-bottom:4px;">TIME</div>'
    +'<input id="mcm-fu-time" type="time" value="'+overlay._followupTime+'" onchange="var o=document.getElementById(\'mcm-overlay\');if(o)o._followupTime=this.value;" '
    +'style="width:100%;background:rgba(255,255,255,0.06);border:1.5px solid rgba(6,182,212,0.35);border-radius:8px;padding:9px 10px;font-size:12px;color:#fff;font-family:inherit;box-sizing:border-box;"></div>'
    +'</div>'
    +'<div style="font-size:9px;font-weight:700;color:rgba(255,255,255,0.35);margin-bottom:6px;">HOW</div>'
    +'<div style="display:flex;gap:6px;margin-bottom:10px;flex-wrap:wrap;">'
    + methods.map(function(m) {
      var active = overlay._followupMethod === m.id;
      return '<button type="button" onclick="var o=document.getElementById(\'mcm-overlay\');if(o){o._followupMethod=\''+m.id+'\';}mcmRenderFollowupForm(\''+leadId+'\')" '
        +'style="flex:1;min-width:80px;padding:8px 10px;border-radius:8px;border:1.5px solid '+(active?m.color:'rgba(255,255,255,0.12)')+';background:'+(active?m.color+'22':'rgba(255,255,255,0.04)')+';color:'+(active?m.color:'rgba(255,255,255,0.6)')+';font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">'+m.label+'</button>';
    }).join('')
    +'</div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap;">'
    +[['Tomorrow',1],['In 3 days',3],['In 1 week',7],['In 1 month',30]].map(function(opt) {
      return '<button type="button" onclick="mcmSetFollowupQuick(\''+leadId+'\','+opt[1]+')" style="padding:5px 10px;border-radius:20px;border:1px solid rgba(255,255,255,0.15);background:transparent;color:rgba(255,255,255,0.55);font-size:10px;font-weight:600;cursor:pointer;font-family:inherit;">'+opt[0]+'</button>';
    }).join('')
    +'</div>'
    +'</div>';
};

window.mcmApplyFollowupToLead = function(lead, overlay) {
  if (!lead || !overlay) return false;
  var dateEl = document.getElementById('mcm-fu-date');
  var timeEl = document.getElementById('mcm-fu-time');
  var date = (dateEl && dateEl.value) || overlay._followupDate;
  var time = (timeEl && timeEl.value) || overlay._followupTime || '14:00';
  var method = overlay._followupMethod || 'call';
  if (!date) return false;

  lead.nextFollowUp = date;
  lead.followUpTime = time;
  lead.followUpMethod = method;
  overlay._followupDate = date;
  overlay._followupTime = time;

  var noteEl = document.getElementById('mcm-note');
  var noteText = noteEl ? noteEl.value.trim() : '';
  if (typeof anCreateFollowUpTask === 'function') {
    anCreateFollowUpTask(lead, date, time, method, noteText || 'Follow-up scheduled from call session');
  }
  return true;
};

var AN_STATE_TZ = {
  AL:'CST',AK:'AKT',AZ:'MST',AR:'CST',CA:'PST',CO:'MST',CT:'EST',DE:'EST',FL:'EST',GA:'EST',
  HI:'HST',ID:'MST',IL:'CST',IN:'EST',IA:'CST',KS:'CST',KY:'EST',LA:'CST',ME:'EST',MD:'EST',
  MA:'EST',MI:'EST',MN:'CST',MS:'CST',MO:'CST',MT:'MST',NE:'CST',NV:'PST',NH:'EST',NJ:'EST',
  NM:'MST',NY:'EST',NC:'EST',ND:'CST',OH:'EST',OK:'CST',OR:'PST',PA:'EST',RI:'EST',SC:'EST',
  SD:'CST',TN:'CST',TX:'CST',UT:'MST',VT:'EST',VA:'EST',WA:'PST',WV:'EST',WI:'CST',WY:'MST',DC:'EST'
};

window.anTzFromState = function(state) {
  if (!state) return null;
  var st = (state || '').toString().trim().toUpperCase();
  if (st.length > 2) {
    var names = { ALABAMA:'AL',ALASKA:'AK',ARIZONA:'AZ',ARKANSAS:'AR',CALIFORNIA:'CA',COLORADO:'CO',
      CONNECTICUT:'CT',DELAWARE:'DE',FLORIDA:'FL',GEORGIA:'GA',HAWAII:'HI',IDAHO:'ID',ILLINOIS:'IL',
      INDIANA:'IN',IOWA:'IA',KANSAS:'KS',KENTUCKY:'KY',LOUISIANA:'LA',MAINE:'ME',MARYLAND:'MD',
      MASSACHUSETTS:'MA',MICHIGAN:'MI',MINNESOTA:'MN',MISSISSIPPI:'MS',MISSOURI:'MO',MONTANA:'MT',
      NEBRASKA:'NE',NEVADA:'NV','NEW HAMPSHIRE':'NH','NEW JERSEY':'NJ','NEW MEXICO':'NM','NEW YORK':'NY',
      'NORTH CAROLINA':'NC','NORTH DAKOTA':'ND',OHIO:'OH',OKLAHOMA:'OK',OREGON:'OR',PENNSYLVANIA:'PA',
      'RHODE ISLAND':'RI','SOUTH CAROLINA':'SC','SOUTH DAKOTA':'SD',TENNESSEE:'TN',TEXAS:'TX',UTAH:'UT',
      VERMONT:'VT',VIRGINIA:'VA',WASHINGTON:'WA','WEST VIRGINIA':'WV',WISCONSIN:'WI',WYOMING:'WY' };
    st = names[st] || st.slice(0, 2);
  }
  return AN_STATE_TZ[st] || null;
};

window.mcmGetUpcomingBooked = function(limit) {
  if (typeof scLoadBooked === 'function') scLoadBooked();
  var list = [];
  var todayStr = new Date().toISOString().split('T')[0];
  Object.keys(SC.bookedSlots || {}).forEach(function(key) {
    if (key.indexOf('_tz_') >= 0) return;
    var slots = SC.bookedSlots[key];
    if (!Array.isArray(slots)) return;
    slots.forEach(function(slot) {
      if (key >= todayStr) list.push({ date: key, slot: slot, tzId: SC.bookedSlots[key + '_tz_' + slot] || 'MST' });
    });
  });
  list.sort(function(a, b) { return (a.date + a.slot).localeCompare(b.date + b.slot); });
  return list.slice(0, limit || 6);
};

window.mcmBuildMiniCalendar = function(leadId) {
  var overlay = document.getElementById('mcm-overlay');
  if (!overlay) return '';
  if (!overlay._demoMonth) {
    var now = new Date();
    overlay._demoMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  }
  if (typeof scLoadBooked === 'function') scLoadBooked();
  var tz = overlay._demoTz ? scGetTz(overlay._demoTz) : scGetTz('MST');
  var year = overlay._demoMonth.getFullYear();
  var mon = overlay._demoMonth.getMonth();
  var monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  var dayLabels = ['S','M','T','W','T','F','S'];
  var firstDay = new Date(year, mon, 1).getDay();
  var daysInMonth = new Date(year, mon + 1, 0).getDate();
  var today = new Date();
  var todayStr = today.getFullYear() + '-' + pad2(today.getMonth() + 1) + '-' + pad2(today.getDate());
  var cells = '';
  var i;
  for (i = 0; i < firstDay; i++) cells += '<div></div>';
  for (var d = 1; d <= daysInMonth; d++) {
    var dateStr = year + '-' + pad2(mon + 1) + '-' + pad2(d);
    var dayOfWeek = new Date(year, mon, d).getDay();
    var isPast = dateStr < todayStr;
    var isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
    var isSelected = dateStr === overlay._demoDate;
    var isDisabled = isPast || isWeekend;
    var bookedCount = (SC.bookedSlots[dateStr] || []).length;
    var bg = isSelected ? tz.color : 'transparent';
    var border = isSelected ? tz.color : (bookedCount ? 'rgba(245,158,11,0.5)' : 'rgba(255,255,255,0.08)');
    var textCol = isSelected ? '#fff' : isDisabled ? 'rgba(255,255,255,0.2)' : '#fff';
    cells += '<div ' + (isDisabled ? '' : 'onclick="mcmPickDemoDate(\'' + dateStr + '\',\'' + leadId + '\')" ')
      + 'style="aspect-ratio:1;display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:6px;background:' + bg + ';border:1.5px solid ' + border + ';cursor:' + (isDisabled ? 'default' : 'pointer') + ';font-size:11px;font-weight:' + (isSelected ? '800' : '600') + ';color:' + textCol + ';position:relative;">'
      + d + (bookedCount ? '<span style="position:absolute;bottom:2px;width:4px;height:4px;border-radius:50%;background:' + (isSelected ? '#fff' : '#f59e0b') + ';"></span>' : '')
      + '</div>';
  }
  return '<div style="margin-bottom:10px;">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">'
    + '<button type="button" onclick="mcmShiftDemoMonth(-1,\'' + leadId + '\')" style="background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.12);color:#fff;border-radius:6px;width:28px;height:28px;cursor:pointer;font-family:inherit;">‹</button>'
    + '<div style="font-size:12px;font-weight:700;color:#fff;">' + monthNames[mon] + ' ' + year + ' <span style="color:rgba(255,255,255,0.4);font-weight:500;">· orange dot = booked</span></div>'
    + '<button type="button" onclick="mcmShiftDemoMonth(1,\'' + leadId + '\')" style="background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.12);color:#fff;border-radius:6px;width:28px;height:28px;cursor:pointer;font-family:inherit;">›</button>'
    + '</div>'
    + '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px;margin-bottom:4px;">'
    + dayLabels.map(function(l) { return '<div style="text-align:center;font-size:9px;font-weight:700;color:rgba(255,255,255,0.3);">' + l + '</div>'; }).join('')
    + '</div>'
    + '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px;">' + cells + '</div>'
    + '</div>';
};

window.mcmShiftDemoMonth = function(dir, leadId) {
  var overlay = document.getElementById('mcm-overlay');
  if (!overlay || !overlay._demoMonth) return;
  overlay._demoMonth = new Date(overlay._demoMonth.getFullYear(), overlay._demoMonth.getMonth() + dir, 1);
  mcmRenderDemoForm(leadId);
};

window.mcmConfirmDemoTz = function(leadId, yes) {
  var overlay = document.getElementById('mcm-overlay');
  if (!overlay) return;
  if (yes) overlay._demoTzConfirmed = true;
  else overlay._demoTzConfirmed = false;
  mcmRenderDemoForm(leadId);
};

window.mcmRenderDemoForm = function(leadId) {
  var overlay = document.getElementById('mcm-overlay');
  var slot = document.getElementById('mcm-demo-slot');
  if (!overlay || !slot) return;
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
  if (!lead) return;

  var guessedTz = anTzFromState(lead.state);
  if (!overlay._demoTz) {
    overlay._demoTz = lead.demoTz || guessedTz || 'MST';
    if (lead.demoTz || guessedTz) overlay._demoTzConfirmed = true;
  }
  if (!overlay._demoDate) overlay._demoDate = lead.demoDate || '';
  if (!overlay._demoTime) overlay._demoTime = lead.demoTime || '';

  var todayStr = new Date().toISOString().split('T')[0];
  if (typeof scLoadBooked === 'function') scLoadBooked();

  var leadName = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || lead.company || 'this prospect';
  var ptz = scGetTz(overlay._demoTz);
  var tzConfirmHtml = '';
  if (guessedTz && !overlay._demoTzConfirmed) {
    var gtz = scGetTz(guessedTz);
    tzConfirmHtml = '<div style="background:rgba(99,102,241,0.15);border:1px solid rgba(99,102,241,0.35);border-radius:10px;padding:12px;margin-bottom:12px;">'
      + '<div style="font-size:12px;color:#c7d2fe;line-height:1.55;margin-bottom:10px;">'
      + mcmEsc(leadName) + (lead.state ? ' is in <strong>' + mcmEsc(lead.state) + '</strong>' : '') + ' — that\'s usually <strong>' + gtz.label + ' (' + gtz.abbr + ')</strong>. Is that right?'
      + '</div>'
      + '<div style="display:flex;gap:8px;">'
      + '<button type="button" onclick="mcmConfirmDemoTz(\'' + leadId + '\',true);mcmPickDemoTz(\'' + guessedTz + '\',\'' + leadId + '\')" style="flex:1;padding:8px;border-radius:8px;border:none;background:#6366f1;color:#fff;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;">✓ Yes, ' + gtz.abbr + '</button>'
      + '<button type="button" onclick="mcmConfirmDemoTz(\'' + leadId + '\',false)" style="padding:8px 12px;border-radius:8px;border:1px solid rgba(255,255,255,0.2);background:transparent;color:rgba(255,255,255,0.6);font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;">Pick different</button>'
      + '</div></div>';
  } else if (guessedTz && overlay._demoTzConfirmed) {
    tzConfirmHtml = '<div style="font-size:11px;color:rgba(255,255,255,0.45);margin-bottom:10px;">📍 Using <strong style="color:' + ptz.color + ';">' + ptz.label + ' (' + ptz.abbr + ')</strong>' + (lead.state ? ' for ' + mcmEsc(lead.state) : '') + ' · <button type="button" onclick="mcmResetDemoTzConfirm(\'' + leadId + '\')" style="background:none;border:none;color:#a5b4fc;cursor:pointer;font-size:11px;font-family:inherit;text-decoration:underline;">change</button></div>';
  }

  var tzBtns = SC_TIMEZONES.map(function(tz) {
    var active = overlay._demoTz === tz.id;
    var show = !guessedTz || overlay._demoTzConfirmed || overlay._demoTz === tz.id;
    if (!show && !overlay._demoTzConfirmed) return '';
    return '<button type="button" onclick="mcmPickDemoTz(\''+tz.id+'\',\''+leadId+'\')" '
      +'style="padding:8px 4px;border-radius:8px;border:1.5px solid '+(active?tz.color:'rgba(255,255,255,0.12)')+';background:'+(active?tz.color+'22':'rgba(255,255,255,0.04)')+';cursor:pointer;font-family:inherit;text-align:center;min-width:0;">'
      +'<div style="font-size:14px;">'+tz.flag+'</div>'
      +'<div style="font-size:9px;font-weight:700;color:'+(active?tz.color:'rgba(255,255,255,0.5)')+';">'+tz.abbr+'</div>'
      +'</button>';
  }).join('');

  var slotBtns = '';
  if (overlay._demoDate && overlay._demoTz) {
    slotBtns = '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:5px;max-height:140px;overflow-y:auto;margin-bottom:10px;">'
      + (SC_SLOTS || []).map(function(s) {
        var booked = SC.bookedSlots && SC.bookedSlots[overlay._demoDate] && SC.bookedSlots[overlay._demoDate].indexOf(s) >= 0;
        var isSel = s === overlay._demoTime;
        var mst = scConvertToMST(overlay._demoDate, s, overlay._demoTz);
        return '<button type="button" ' + (booked ? 'disabled' : 'onclick="mcmPickDemoTime(\'' + s + '\',\'' + leadId + '\')"') + ' '
          + 'style="padding:8px 4px;border-radius:8px;border:1.5px solid ' + (isSel ? ptz.color : booked ? 'rgba(239,68,68,0.3)' : 'rgba(255,255,255,0.12)') + ';background:' + (isSel ? ptz.color + '33' : booked ? 'rgba(239,68,68,0.08)' : 'rgba(255,255,255,0.04)') + ';cursor:' + (booked ? 'not-allowed' : 'pointer') + ';font-family:inherit;text-align:center;">'
          + '<div style="font-size:11px;font-weight:700;color:' + (booked ? 'rgba(255,255,255,0.25)' : '#fff') + ';">' + fmt12(+s.split(':')[0], +s.split(':')[1]) + '</div>'
          + '<div style="font-size:9px;color:rgba(255,255,255,0.35);">' + (booked ? 'booked' : mst.h12 + ' MST') + '</div>'
          + '</button>';
      }).join('')
      + '</div>';
  }

  var upcoming = mcmGetUpcomingBooked(5);
  var upcomingHtml = upcoming.length ? '<div style="margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,0.08);">'
    + '<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.35);text-transform:uppercase;letter-spacing:0.1em;margin-bottom:6px;">Your booked demos</div>'
    + upcoming.map(function(b) {
      var btz = scGetTz(b.tzId);
      var parts = b.date.split('-');
      return '<div style="font-size:11px;color:rgba(255,255,255,0.55);padding:4px 0;display:flex;justify-content:space-between;">'
        + '<span>' + parts[1] + '/' + parts[2] + ' · ' + fmt12(+b.slot.split(':')[0], +b.slot.split(':')[1]) + ' ' + btz.abbr + '</span>'
        + '<span style="color:rgba(255,255,255,0.3);">booked</span></div>';
    }).join('')
    + '</div>' : '';

  var preview = '';
  if (overlay._demoDate && overlay._demoTime && overlay._demoTz) {
    var pmst = scConvertToMST(overlay._demoDate, overlay._demoTime, overlay._demoTz);
    preview = fmt12(+overlay._demoTime.split(':')[0], +overlay._demoTime.split(':')[1])+' '+ptz.abbr+' · Your time: '+pmst.h12+' MST';
  }

  slot.innerHTML =
    '<div id="mcm-demo-block" style="padding:16px 18px;border-bottom:1px solid rgba(255,255,255,0.06);background:rgba(245,158,11,0.06);">'
    +'<div style="font-size:10px;font-weight:700;color:#fbbf24;text-transform:uppercase;letter-spacing:0.12em;margin-bottom:10px;">🎯 Schedule Demo</div>'
    + tzConfirmHtml
    + (overlay._demoTzConfirmed || !guessedTz ? '<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.35);margin-bottom:6px;">Prospect timezone</div><div style="display:grid;grid-template-columns:repeat(6,1fr);gap:5px;margin-bottom:12px;">'+tzBtns+'</div>' : '')
    + mcmBuildMiniCalendar(leadId)
    + (overlay._demoDate ? '<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.35);margin-bottom:6px;">Pick a time' + (overlay._demoDate ? ' · ' + overlay._demoDate : '') + '</div>' + slotBtns : '<div style="font-size:11px;color:rgba(255,255,255,0.35);margin-bottom:8px;">Tap a date on the calendar — orange dots are already booked</div>')
    +(preview ? '<div id="mcm-demo-preview" style="font-size:11px;color:rgba(255,255,255,0.55);padding:8px 10px;background:rgba(255,255,255,0.04);border-radius:8px;margin-bottom:10px;">'+mcmEsc(preview)+'</div>'
      : '<div id="mcm-demo-preview" style="font-size:11px;color:rgba(255,255,255,0.35);margin-bottom:8px;">Select date & time — booked slots are blocked</div>')
    +'<div style="font-size:10px;color:rgba(255,255,255,0.38);line-height:1.45;margin-bottom:4px;">Pick timezone → date → time slot. The <strong style="color:#6ee7b7;">Demo Booked</strong> popup opens after you choose a time — then log the call when ready.</div>'
    + upcomingHtml
    +'</div>';
};

window.mcmResetDemoTzConfirm = function(leadId) {
  var overlay = document.getElementById('mcm-overlay');
  if (overlay) overlay._demoTzConfirmed = false;
  mcmRenderDemoForm(leadId);
};

window.mcmPickDemoTz = function(tzId, leadId) {
  var overlay = document.getElementById('mcm-overlay');
  if (overlay) { overlay._demoTz = tzId; overlay._demoTzConfirmed = true; }
  mcmRenderDemoForm(leadId);
  mcmTryOpenDemoFollowThroughModal(leadId);
};

window.mcmPickDemoDate = function(val, leadId) {
  var overlay = document.getElementById('mcm-overlay');
  if (overlay) { overlay._demoDate = val; overlay._demoTime = ''; }
  mcmRenderDemoForm(leadId);
};

window.mcmPickDemoTime = function(val, leadId) {
  var overlay = document.getElementById('mcm-overlay');
  if (overlay) overlay._demoTime = val;
  mcmRenderDemoForm(leadId);
  mcmTryOpenDemoFollowThroughModal(leadId);
};

window.mcmApplyDemoToLead = function(lead, overlay) {
  if (!lead || !overlay) return false;
  if (!overlay._demoDate || !overlay._demoTime || !overlay._demoTz) return false;
  lead.demoDate = overlay._demoDate;
  lead.demoTime = overlay._demoTime;
  lead.demoTz = overlay._demoTz;
  lead.status = 'booked_demo';
  if (typeof scLoadBooked === 'function') scLoadBooked();
  if (!SC.bookedSlots[lead.demoDate]) SC.bookedSlots[lead.demoDate] = [];
  if (SC.bookedSlots[lead.demoDate].indexOf(lead.demoTime) < 0) {
    SC.bookedSlots[lead.demoDate].push(lead.demoTime);
    SC.bookedSlots[lead.demoDate + '_tz_' + lead.demoTime] = lead.demoTz;
  }
  if (typeof scSaveBooked === 'function') scSaveBooked();
  if (typeof anRecordDemoBooked === 'function') anRecordDemoBooked(lead, { source: 'call_session' });
  return true;
};

window.mcmSetStatus = function(status, leadId) {
  var overlay = document.getElementById('mcm-overlay');
  var mode = overlay ? (overlay._callMode || 'lead') : 'lead';
  if (mode === 'lead' && status === 'booked_demo') {
    mcmEnterDemoScheduling(leadId);
    return;
  }
  if (mode === 'lead' && status === 'demo_complete') {
    var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id === leadId; }) : null;
    if (lead && typeof anTriggerDemoCompleteConversion === 'function') {
      mcmUpdateStatusPills('demo_complete');
      if (overlay) overlay._status = 'demo_complete';
      anTriggerDemoCompleteConversion(lead, { save: true, silent: true });
      return;
    }
  }
  if (mode === 'lead' && (overlay._pendingDemo || overlay._demoModalShown || overlay._outcome === 'demo')) {
    mcmDismissDemoFlow(leadId);
  }
  mcmUpdateStatusPills(status);
  if (mode === 'lead' && status === 'followup') {
    if (overlay) overlay._outcome = 'callback';
    mcmHighlightOutcome('callback');
    mcmRenderFollowupForm(leadId);
  } else if (mode === 'lead') {
    mcmHideFollowupForm();
  }
};

window.mcmEditPhone = function(leadId) {
  var phone = prompt('Enter phone number:');
  if (!phone) return;
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id===leadId; }) : null;
  if (!lead) return;
  lead.phone = anNormalizePhone(phone);
  lead.updated = new Date().toISOString();
  if (typeof AN !== 'undefined' && AN.save) AN.save();
  openMobileCallMode(leadId);
};

window.mcmSaveCompany = function(leadId) {
  var input = document.getElementById('mcm-company-input') || document.getElementById('cs-company-input');
  var cn = input ? input.value : '';
  if(!anUpdateLeadCompany(leadId, cn)) return;
  if (document.getElementById('mcm-overlay')) openMobileCallMode(leadId);
};

window.mcmSaveTitle = function(leadId) {
  var input = document.getElementById('mcm-title-input') || document.getElementById('cs-title-input');
  var t = input ? input.value : '';
  if (!anUpdateLeadTitle(leadId, t)) return;
  if (document.getElementById('mcm-overlay')) openMobileCallMode(leadId);
};

window.mcmSave = function(leadId, opts) {
  var overlay = document.getElementById('mcm-overlay');
  var noteEl  = document.getElementById('mcm-note');
  var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id===leadId; }) : null;
  if (!lead) { mcmClose(); return; }

  var titleIn = document.getElementById('mcm-title-input') || document.getElementById('cs-title-input');
  if (titleIn && titleIn.value.trim() !== (lead.title || '').trim()) {
    anUpdateLeadTitle(leadId, titleIn.value, { silent: true });
  }
  var companyIn = document.getElementById('mcm-company-input') || document.getElementById('cs-company-input');
  if (companyIn && companyIn.value.trim() !== (lead.company || '').trim()) {
    anUpdateLeadCompany(leadId, companyIn.value, { silent: true });
  }

  var outcome = (overlay && overlay._outcome) || 'noanswer';
  var newStatus = (overlay && overlay._status) || lead.status;
  var note = noteEl ? noteEl.value.trim() : '';
  var keepOpen = !!(opts && opts.keepOpen);

  var mode = (overlay && overlay._callMode) || 'lead';

  var demoJustBooked = false;
  if (mode === 'lead' && (outcome === 'demo' || newStatus === 'booked_demo')) {
    if (!mcmApplyDemoToLead(lead, overlay)) {
      mcmRenderDemoForm(leadId);
      if (typeof showToast === 'function') showToast('Pick demo date, time & timezone first');
      return false;
    }
    lead.isOpportunity = false;
    lead.status = 'booked_demo';
    newStatus = 'booked_demo';
    demoJustBooked = true;
    if (overlay) overlay._demoSaved = true;
  } else if ((outcome === 'callback' || newStatus === 'followup') && mode === 'lead') {
    if (!mcmApplyFollowupToLead(lead, overlay)) {
      mcmRenderFollowupForm(leadId);
      if (typeof showToast === 'function') showToast('Pick follow-up date, time & method first');
      return false;
    }
    lead.status = 'followup';
    newStatus = 'followup';
  } else if (mode === 'lead' && (outcome === 'demo_complete' || newStatus === 'demo_complete') && !anIsOpportunity(lead)) {
    if (typeof anTriggerDemoCompleteConversion === 'function') {
      anTriggerDemoCompleteConversion(lead, { save: false, silent: true });
      newStatus = 'demo_complete';
    } else {
      lead.status = newStatus;
    }
  } else {
    lead.status = newStatus;
    if (mode === 'opportunity' || anIsOpportunity(lead)) {
      lead.isOpportunity = true;
      if (newStatus === 'won' && typeof anPostTeamShout === 'function') anPostTeamShout('won', lead);
    }
  }

  // Log call / email activity
  var now = new Date();
  if (demoJustBooked) outcome = 'demo';
  var entry = {
    date: typeof anLocalDateStr === 'function' ? anLocalDateStr(now) : now.toISOString().split('T')[0],
    time: now.toTimeString().slice(0,5),
    outcome: outcome,
    notes: note,
    rep: anActiveRepEmail()
  };
  if (demoJustBooked) entry.bookedDemo = true;
  if (!lead.callLog) lead.callLog = [];
  lead.callLog.unshift(entry);
  lead.lastContactDate = entry.date;
  lead.updated = now.toISOString();

  if (typeof AN !== 'undefined' && AN.save) AN.save();
  if (typeof renderLeadsTable === 'function') renderLeadsTable();
  if (document.getElementById('an-side-panel') && window._anPanelLeadId === leadId && typeof anRefreshLeadPanel === 'function') {
    anRefreshLeadPanel(leadId);
  }

  if (!keepOpen) {
    mcmClose();
  } else if (typeof anRenderCallSessionLeadPanel === 'function') {
    anRenderCallSessionLeadPanel(leadId);
    if (noteEl) noteEl.value = '';
    if (overlay) {
      overlay._outcome = null;
      overlay._status = lead.status;
    }
    document.querySelectorAll('[id^="mcm-outcome-"]').forEach(function(btn) {
      btn.style.background = 'rgba(255,255,255,0.04)';
      btn.style.borderColor = 'rgba(255,255,255,0.1)';
      btn.style.color = 'rgba(255,255,255,0.7)';
    });
    if (typeof mcmRefreshAttemptBadge === 'function') mcmRefreshAttemptBadge(leadId);
  }

  if (typeof anSyncCallToDashboard === 'function') anSyncCallToDashboard(lead, outcome, newStatus);
  if (typeof hdRefreshTeamWidgets === 'function') {
    clearTimeout(window._anPostCallLbTimer);
    window._anPostCallLbTimer = setTimeout(hdRefreshTeamWidgets, 400);
  }
  if (typeof hdRender === 'function' && (outcome === 'callback' || newStatus === 'followup')) {
    var homeSec = document.getElementById('section-home');
    if (homeSec && homeSec.classList.contains('active')) hdRender();
  }
  if (typeof anPostTeamShout === 'function') {
    if (newStatus === 'won') anPostTeamShout('won', lead);
    else if (outcome === 'demo' || newStatus === 'demo' || newStatus === 'booked_demo') anPostTeamShout('demo', lead);
  }

  if (typeof showToast === 'function') {
    var labels = {
      pickup:'📞 Call logged', noanswer:'📵 No answer logged', voicemail:'📬 Voicemail logged',
      demo:'🎯 Demo scheduled!', demo_complete:'✅ Demo complete — create the opportunity', callback:'⏰ Follow-up logged', emailed:'✉️ Email logged',
      connected:'📞 Connected', objection:'🛡 Objection noted', next_step:'📋 Next step set', won:'🏆 Won logged'
    };
    showToast(labels[outcome] || 'Activity logged');
  }

  if (demoJustBooked && overlay && !overlay._demoModalShown && typeof anMaybeShowDemoAutomationPanel === 'function') {
    anMaybeShowDemoAutomationPanel(lead);
  }
  if (overlay && demoJustBooked) {
    overlay._pendingDemo = false;
  }

  return true;
};

window.mcmNextLead = function(leadId) {
  if (!mcmSave(leadId)) return;
  // Find next lead in the filtered list
  if (typeof AN === 'undefined' || !AN.leads) return;
  var leads = AN.leads.filter(function(l){ return l.status !== 'won' && l.status !== 'lost'; });
  var idx = leads.findIndex(function(l){ return l.id===leadId; });
  var next = leads[idx+1] || leads[0];
  if (next && next.id !== leadId) {
    setTimeout(function(){ openMobileCallMode(next.id); }, 200);
  }
};

// ── 3. Wire mobile call mode to Lead Pipeline table's phone cell ─
// Patch renderLeadsTable to make the phone number a tappable "Call" button
var _origRLT_mobile = window.renderLeadsTable;
window.renderLeadsTable = function() {
  if (typeof _origRLT_mobile === 'function') _origRLT_mobile();
  setTimeout(function() {
    var tbody = document.querySelector('#crm-content tbody');
    if (!tbody) return;
    tbody.querySelectorAll('tr').forEach(function(tr) {
      var cb = tr.querySelector('.lead-cb');
      if (!cb) return;
      var leadId = cb.dataset.id;
      var lead = (typeof AN !== 'undefined' && AN.leads) ? AN.leads.find(function(l){ return l.id===leadId; }) : null;
      if (!lead) return;

      // Find phone cell (index 5 in the table)
      var cells = tr.querySelectorAll('td');
      var phoneCell = cells[5];
      if (!phoneCell || phoneCell.dataset.mobilePatch) return;
      phoneCell.dataset.mobilePatch = '1';

      if (lead.phone) {
        phoneCell.innerHTML = '<div style="display:flex;align-items:center;gap:6px;">'
          +'<span style="font-size:12.5px;color:var(--text-primary);">'+mcmEsc(anFormatPhone(lead.phone))+'</span>'
          +'<button onclick="event.stopPropagation();openMobileCallMode(\''+leadId+'\')" '
          +'style="background:#ecfdf5;color:#10b981;border:1px solid #a7f3d0;border-radius:5px;padding:2px 7px;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;flex-shrink:0;">📞</button>'
          +'</div>';
      } else {
        phoneCell.innerHTML = '<span style="color:var(--text-muted);font-size:12px;">—</span>';
      }
    });
  }, 220);
};

