  var dashMsg = (typeof anGetDashMessage === 'function') ? anGetDashMessage(firstName, now) : { msg: '', sub: '' };
  var dashClock = (typeof anFormatDashClock === 'function') ? anFormatDashClock(now) : (days[now.getDay()]+', '+months[now.getMonth()]+' '+now.getDate()+', '+now.getFullYear());

