      var outcomeLabels = { pickup:'Picked up', demo:'Demo set', voicemail:'Voicemail', noanswer:'No answer', note:'Note', callback:'Callback' };
      var outcomeColors = { pickup:'#ecfdf5', demo:'#fff7ed', voicemail:'#eef2ff', noanswer:'#f9f9f9', note:'#f0fdff', callback:'#f0fdf4' };
      var icon = outcomeIcons[c.outcome] || '📞';
      var label = outcomeLabels[c.outcome] || 'Call';
      var bg = outcomeColors[c.outcome] || '#f9f9f9';
