// ============================================================
// 1. SIDEBAR FIX — Fix blank space and AS avatar alignment
// ============================================================
// Patch toggleSidebar to also handle the user area cleanly
var _origToggleSidebar_fix = window.toggleSidebar;
window.toggleSidebar = function() {
  if (typeof _origToggleSidebar_fix === 'function') _origToggleSidebar_fix();
  // After toggle, add/remove class for CSS
  var sb = document.getElementById('sidebar');
  if (!sb) return;
  if (sb.style.width === '52px') {
    sb.classList.add('sidebar-collapsed');
    // Fix user avatar area in collapsed state
    var ua = sb.querySelector('.sidebar-user-area');
    if (ua) {
      ua.style.justifyContent = 'center';
      ua.style.padding = '10px 0';
      ua.querySelectorAll('.sidebar-user-info, .sidebar-user-signout, .sidebar-user-email').forEach(function(el){ el.style.display = 'none'; });
    }
    // Fix sidebar-auth in collapsed state
    var authBtn = sb.querySelector('#sidebar-signin-btn');
    if (authBtn) { authBtn.style.padding = '10px 0'; authBtn.style.justifyContent = 'center'; }
  } else {
    sb.classList.remove('sidebar-collapsed');
    var ua = sb.querySelector('.sidebar-user-area');
    if (ua) {
      ua.style.justifyContent = '';
      ua.style.padding = '';
      ua.querySelectorAll('.sidebar-user-info, .sidebar-user-signout, .sidebar-user-email').forEach(function(el){ el.style.display = ''; });
    }
    var authBtn = sb.querySelector('#sidebar-signin-btn');
    if (authBtn) { authBtn.style.padding = ''; authBtn.style.justifyContent = ''; }
  }
};

// ============================================================
// 2. FIRST-LOGIN ONBOARDING — Ask for display name
// ============================================================
var _AN_ONBOARD_KEY = 'agentnav-display-name-set';

function anShowOnboardingModal(user) {
  if (localStorage.getItem(_AN_ONBOARD_KEY)) return; // already done
  if (!user || !user.email) return;

  var existing = document.getElementById('an-onboard-modal');
  if (existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.id = 'an-onboard-modal';
  overlay.innerHTML =
    '<div id="an-onboard-box">'
    +'<div style="font-size:40px;text-align:center;margin-bottom:16px;">👋</div>'
    +'<h2 style="text-align:center;">Welcome to AgentNav!</h2>'
    +'<p style="text-align:center;">Before you dive in, tell us what you\'d like to be called. This is how your name will appear on your dashboard and to your team.</p>'
    +'<input id="an-onboard-name" type="text" placeholder="e.g. Alex, Sarah, Coach Mike..." maxlength="40" onkeydown="if(event.key===\'Enter\')anSaveOnboardName()">'
    +'<input id="an-onboard-role-title" type="text" placeholder="Your title (optional) e.g. Senior AE, SDR..." maxlength="60" style="margin-top:0;" onkeydown="if(event.key===\'Enter\')anSaveOnboardName()">'
    +'<button class="an-onboard-btn" onclick="anSaveOnboardName()">Let\'s go 🚀</button>'
    +'<button onclick="anSkipOnboarding()" style="width:100%;background:none;border:none;color:#a1a1aa;font-size:13px;cursor:pointer;margin-top:10px;font-family:inherit;padding:6px;">Skip for now</button>'
    +'</div>';

  document.body.appendChild(overlay);
  setTimeout(function(){ var inp = document.getElementById('an-onboard-name'); if(inp) inp.focus(); }, 100);
}

window.anSaveOnboardName = function() {
  var nameEl  = document.getElementById('an-onboard-name');
  var titleEl = document.getElementById('an-onboard-role-title');
  var name  = nameEl  ? nameEl.value.trim()  : '';
  var title = titleEl ? titleEl.value.trim() : '';

  if (!name) { if (nameEl) nameEl.style.borderColor = '#ef4444'; return; }

  // Save to _repViews for this user
  if (typeof loadRepViews === 'function') loadRepViews();
  var email = (typeof AN !== 'undefined' && AN.currentRepEmail) || '';
  if (email) {
    if (!_repViews[email]) _repViews[email] = { hidden: [] };
    _repViews[email].displayName = name;
    if (title) _repViews[email].jobTitle = title;
    if (typeof saveRepViews === 'function') saveRepViews();
  }

  localStorage.setItem(_AN_ONBOARD_KEY, '1');
  var modal = document.getElementById('an-onboard-modal');
  if (modal) modal.remove();

  // Re-render dashboard with new name
  if (typeof hdRender === 'function') hdRender();
  if (typeof showToast === 'function') showToast('Welcome, '+name+'! 🎉');
};

window.anSkipOnboarding = function() {
  localStorage.setItem(_AN_ONBOARD_KEY, '1');
  var modal = document.getElementById('an-onboard-modal');
  if (modal) modal.remove();
};

// Hook into login
var _origOULI_onboard = window.onUserLoggedIn;
window.onUserLoggedIn = function(user) {
  if (typeof _origOULI_onboard === 'function') _origOULI_onboard(user);
  // Show onboarding if first time
  setTimeout(function() { anShowOnboardingModal(user); }, 800);
};

// ============================================================
// 3. TIME-AWARE GREETING — clock + 2-hour message blocks
// ============================================================
window.anGetDashTimeBlock = function(d) {
  d = d || new Date();
  return Math.floor(d.getHours() / 2); // 0–11, one block every 2 hours
};

window.anFormatDashClock = function(d) {
  d = d || new Date();
  var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  var months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  var datePart = days[d.getDay()] + ', ' + months[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
  var timePart = new Intl.DateTimeFormat('en-US', {
    hour: 'numeric', minute: '2-digit', hour12: true, timeZoneName: 'short'
  }).format(d);
  return datePart + ' · <span class="hd-date-time">' + timePart + '</span>';
};

window.anGetDashGreeting = function(d) {
  d = d || new Date();
  var h = d.getHours();
  return h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening';
};

