window.coCloseCompanyPanel = function() {
  var panel = document.getElementById('co-company-panel');
  var backdrop = document.getElementById('co-panel-backdrop');
  _coSelected = null;
  if (typeof coDismissNativeMenus === 'function') coDismissNativeMenus();
  document.body.classList.remove('co-full-record-over-call');
  document.querySelectorAll('.co-kanban-card.active').forEach(function(el) { el.classList.remove('active'); });
  if (panel) panel.classList.remove('open');
  if (backdrop) backdrop.classList.remove('open');
  setTimeout(function() {
    if (panel && !panel.classList.contains('open')) panel.remove();
    if (backdrop && !backdrop.classList.contains('open')) backdrop.remove();
  }, 300);
};

window.coOpenCompanyPanel = function(coId) {
  var co = (_coData || []).find(function(c){ return c.id === coId; });
  if (!co) return;
  _coSelected = coId;
  document.querySelectorAll('.co-kanban-card').forEach(function(el) {
    el.classList.toggle('active', el.getAttribute('data-co-id') === coId);
  });

  var stats = coGetCompanyStats(co.name, co, co.id);
  var existing = document.getElementById('co-company-panel');
  var existingBackdrop = document.getElementById('co-panel-backdrop');

  if (existing) {
    existing.innerHTML = coBuildCompanyPanelHTML(co, stats);
    if (!existing.classList.contains('open')) {
      requestAnimationFrame(function() { existing.classList.add('open'); });
    }
    if (existingBackdrop && !existingBackdrop.classList.contains('open')) {
      requestAnimationFrame(function() { existingBackdrop.classList.add('open'); });
    }
    return;
  }

  if (existingBackdrop) existingBackdrop.remove();
  var backdrop = document.createElement('div');
  backdrop.id = 'co-panel-backdrop';
  backdrop.onclick = coCloseCompanyPanel;
  document.body.appendChild(backdrop);

  var panel = document.createElement('div');
  panel.id = 'co-company-panel';
  panel.innerHTML = coBuildCompanyPanelHTML(co, stats);
  document.body.appendChild(panel);
  requestAnimationFrame(function() {
    backdrop.classList.add('open');
    panel.classList.add('open');
  });
};

window.coToggleSelect = function(id, checked) {
  if (checked) { if (CO.selectedIds.indexOf(id) < 0) CO.selectedIds.push(id); }
  else { CO.selectedIds = CO.selectedIds.filter(function(x){ return x !== id; }); }
  coRefreshBulkBar();
};

window.coToggleSelectAll = function(checked) {
  var companies = _coData.length ? _coData : [];
  CO.selectedIds = checked ? companies.map(function(c){ return c.id; }) : [];
  coRender();
};

function coRemoveCompaniesByIds(ids, skipConfirm){
  if(!ids || !ids.length) return 0;
  var idMap = {};
  ids.forEach(function(id){ idMap[id] = true; });
  var names = [];
  var companies = (_coData || []).filter(function(c){
    if(idMap[c.id]){ names.push(c.name); return false; }
    return true;
  });
  if(companies.length === (_coData || []).length) return 0;

  if(typeof AN !== 'undefined' && Array.isArray(AN.leads)){
    var leadsTouched = false;
    AN.leads.forEach(function(l){
      if(l.companyId && idMap[l.companyId]){ delete l.companyId; leadsTouched = true; }
    });
    if(leadsTouched && typeof AN.save === 'function') AN.save();
  }

  CO.selectedIds = CO.selectedIds.filter(function(id){ return !idMap[id]; });
  if(_coSelected && idMap[_coSelected]) _coSelected = companies.length ? companies[0].id : null;

  coSave(companies, function(){
    coRender();
    if(typeof showToast === 'function'){
      var n = ids.length;
      showToast('Deleted '+n+' compan'+(n!==1?'ies':'y')+(names.length===1 ? ': '+names[0] : ''));
    }
  });
  return ids.length;
}

window.coDeleteSelected = function() {
  if (!CO.selectedIds.length) return;
  var n = CO.selectedIds.length;
  if (!confirm('Delete '+n+' selected compan'+(n!==1?'ies':'y')+'?\n\nLeads in Lead Pipeline are kept — only these company pages are removed.')) return;
  coRemoveCompaniesByIds(CO.selectedIds.slice(), true);
};

window.coDeleteAll = function() {
  if (typeof AN !== 'undefined' && !AN.isAdmin) {
    if (typeof showToast === 'function') showToast('Only admin can delete all companies');
    return;
  }
  var n = _coData.length;
  if (!n) return;
  if (!confirm('Delete ALL '+n.toLocaleString()+' companies?\n\nLeads in Lead Pipeline are NOT deleted.')) return;
  if (!confirm('Last chance — remove every company record?')) return;
  CO.selectedIds = [];
  _coSelected = null;
  coRemoveCompaniesByIds(_coData.map(function(c){ return c.id; }), true);
};

window.coDeleteJunkCompanies = function() {
  var junk = _coData.filter(function(c){ return coIsJunkCompanyName(c.name); });
  if (!junk.length) {
    if(typeof showToast==='function') showToast('No junk company records found');
    return;
  }
  if (!confirm('Delete '+junk.length.toLocaleString()+' junk compan'+(junk.length!==1?'ies':'y')+' (numeric IDs)?\n\nLeads are kept.')) return;
  coRemoveCompaniesByIds(junk.map(function(c){ return c.id; }), true);
};

