window.coAddContact = function(coId) {
  var companies = _coData;
  var co = companies.find(function(c){ return c.id===coId; });
  if (!co) return;

  // Create blank lead pre-filled with company name
  var blank = {
    id: 'l-'+Date.now(),
    firstName: '', lastName: '', company: co.name,
    title: '', email: '', phone: '', state: '', size: '',
    source: '', status: 'new', callLog: [], notes: '',
    _repEmail: (typeof AN !== 'undefined' ? AN.currentRepEmail : ''),
    created: new Date().toISOString(), updated: new Date().toISOString()
  };
  if (typeof AN !== 'undefined' && AN.leads) {
    AN.leads.unshift(blank);
    if (AN.save) AN.save();
  }

  // Open lead modal
  if (typeof anOpenLeadModal === 'function') anOpenLeadModal(blank.id);

  // After modal closes, refresh the companies view
  // Poll until the modal is gone
  var pollCount = 0;
  var poll = setInterval(function() {
    pollCount++;
    var modal = document.getElementById('an-lead-modal');
    var postsave = document.getElementById('an-postsave-modal');
    if ((!modal && !postsave) || pollCount > 60) {
      clearInterval(poll);
      var sec = document.getElementById('section-companies');
      if (sec) coRender(); // always refresh even if not visible, data will be current
    }
  }, 500);
};

window.coSyncOwnerForCompanyName = function(companyName, email) {
  if (!companyName || typeof coSave !== 'function') return;
  var companies = (_coData || []).slice();
  var key = coNormName(companyName);
  var changed = false;
  companies.forEach(function(c) {
    if (coNormName(c.name) === key) {
      c.ownerEmail = (email || '').toLowerCase();
      coTouchCompany(c);
      changed = true;
    }
  });
  if (changed) {
    coInvalidateStatsCache();
    coSave(companies, function() {
      if (typeof coRender === 'function') coRender();
      if (_coSelected && typeof coOpenCompanyPanel === 'function') {
        var co = companies.find(function(c) { return c.id === _coSelected; });
        if (co && coNormName(co.name) === key) coOpenCompanyPanel(_coSelected);
      }
    });
  }
};

window.coSaveField = function(coId, field, value) {
  var companies = _coData.slice();
  var co = companies.find(function(c){ return c.id===coId; });
  if (!co) return;
  co[field] = value;
  coTouchCompany(co);
  coSave(companies);
};

window.coDeleteCompany = function(coId, skipConfirm) {
  var co = (_coData || []).find(function(c){ return c.id === coId; });
  if(!co) return;
  var cache = coBuildStatsCache(_coData || []);
  if (!coCompanyBelongsToRep(co, cache.statsMap)) {
    if (typeof showToast === 'function') showToast('You can only remove accounts you own');
    return;
  }
  if(!skipConfirm && !confirm('Delete "'+co.name+'"?\n\nLeads in Lead Pipeline are kept — only this company page is removed.')) return;
  coRemoveCompaniesByIds([coId], true);
};

