(function(){
  if (!document.getElementById('mcm-side-styles')) {
    var st = document.createElement('style');
    st.id = 'mcm-side-styles';
    st.textContent = '@keyframes mcmSlideIn{from{transform:translateX(100%);opacity:0.8;}to{transform:translateX(0);opacity:1;}}'
      + '@keyframes shoutPop{0%{transform:translateY(-20px);opacity:0;}15%{transform:translateY(0);opacity:1;}85%{opacity:1;}100%{transform:translateY(-10px);opacity:0;}}'
      + '#mcm-panel-wrap{position:fixed;top:0;right:0;bottom:0;width:360px;max-width:100vw;z-index:20000;pointer-events:auto;box-shadow:-8px 0 28px rgba(0,0,0,0.22);animation:mcmSlideIn 0.22s ease;}'
      + '#an-cs-lead-panel{animation:mcmSlideIn 0.26s ease;z-index:19999;pointer-events:auto;}'
      + '#an-cs-company-panel{animation:mcmSlideIn 0.26s ease;z-index:19998;pointer-events:auto;}'
      + '#mcm-call-header,#mcm-call-header button{pointer-events:auto;}'
      + 'body.call-panel-open .main{margin-right:0!important;}'
      + 'body.call-panel-open #call-panel-backdrop{display:none!important;}'
      + 'body.call-lead-collapsed #an-cs-lead-panel{display:none!important;}'
      + 'body.call-panel-minimized #mcm-panel-wrap,body.call-panel-minimized #an-cs-lead-panel,body.call-panel-minimized #an-cs-company-panel{transform:translateX(110%);pointer-events:none;opacity:0;}'
      + '#mcm-call-header .mcm-header-toolbar button{-webkit-tap-highlight-color:transparent;touch-action:manipulation;}'
      + '@media(max-width:1200px){body.call-session-dual #an-cs-lead-panel{width:340px;right:360px;}}'
      + '@media(max-width:900px){#mcm-panel-wrap{width:100vw;}#an-cs-lead-panel{right:0;width:100vw;max-width:100vw;}'
      + 'body.call-lead-front:not(.call-lead-collapsed) #an-cs-lead-panel{z-index:20003!important;right:0!important;width:100vw!important;max-width:100vw!important;}'
      + 'body.call-company-front #an-cs-company-panel{z-index:20004!important;right:0!important;width:100vw!important;max-width:100vw!important;}}'
      + 'body.sb-collapsed #an-cs-banner{left:68px;max-width:calc(100vw - 500px);}';
    document.head.appendChild(st);
  }
})();

window.anSyncCallToDashboard = function(lead, outcome, newStatus) {
  if (typeof _dash === 'undefined') return;
  var today = typeof anLocalDateStr === 'function' ? anLocalDateStr() : new Date().toISOString().split('T')[0];
  if (!_dash.activity) _dash.activity = { calls:0, demos:0, closes:0 };
  if (!_dash.activityLog) _dash.activityLog = [];
  var e = _dash.activityLog.filter(function(x){ return x.date === today; })[0];
  if (!e) { e = { date:today, calls:0, demos:0, closes:0 }; _dash.activityLog.push(e); }

  e.calls = (e.calls || 0) + 1;
  _dash.activity.calls = (_dash.activity.calls || 0) + 1;
  if (!e.calls_by_hour) e.calls_by_hour = {};
  var hr = new Date().getHours();
  e.calls_by_hour[hr] = (e.calls_by_hour[hr] || 0) + 1;

  var isDemoBooked = outcome === 'demo' || newStatus === 'booked_demo' || newStatus === 'demo';
  var isDemoComplete = newStatus === 'demo_complete' || outcome === 'demo_complete';
  var isWon = newStatus === 'won';

  if (isDemoBooked && typeof anRecordDemoBooked === 'function') {
    anRecordDemoBooked(lead, { source: 'call_log', silentActivity: true });
    e.demos = (e.demos || 0) + 1;
    _dash.activity.demos = (_dash.activity.demos || 0) + 1;
  } else if (isDemoComplete && typeof anRecordDemoCompleted === 'function') {
    anRecordDemoCompleted(lead, { source: 'call_log' });
  }

  if (isWon) {
    e.closes = (e.closes || 0) + 1;
    _dash.activity.closes = (_dash.activity.closes || 0) + 1;
    if (!_dash.pipeline) _dash.pipeline = [];
    var leadName = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || lead.company || 'Lead';
    var wonName = lead.company || leadName;
    var hasDeal = _dash.pipeline.some(function(d){
      return d.stage === 'Closed Won' && d.name && wonName && d.name.toLowerCase() === wonName.toLowerCase();
    });
    if (!hasDeal) {
      _dash.pipeline.push({
        name: wonName,
        state: lead.state || '',
        size: lead.size || 'solo',
        stage: 'Closed Won',
        notes: '',
        added: new Date().toISOString()
      });
    }
  }

  if (typeof dashSave === 'function') dashSave();
  if (typeof anPushTeamActivityCloud === 'function') {
    var cloudDelta = { calls: 1 };
    if (isDemoBooked) cloudDelta.demos = 1;
    if (isWon) cloudDelta.closes = 1;
    anPushTeamActivityCloud(cloudDelta);
  }
  if (typeof anRefreshCRMStatsBar === 'function') anRefreshCRMStatsBar();
  if (typeof mcmRenderDayGoalsWidget === 'function') mcmRenderDayGoalsWidget();
  if (typeof mcmRenderDockBar === 'function') mcmRenderDockBar();
  var dashSec = document.getElementById('section-dashboard');
  if (dashSec && dashSec.classList.contains('active') && typeof renderSalesDashboard === 'function') {
    renderSalesDashboard();
  }
  var homeSec = document.getElementById('section-home');
  if (homeSec && homeSec.classList.contains('active')) {
    if (typeof hdRefreshTeamWidgets === 'function') hdRefreshTeamWidgets();
    else if (typeof hdRender === 'function') hdRender();
  }
};

window.anGetTeamShouts = function(){
  try { return JSON.parse(localStorage.getItem('team-shouts') || '[]'); } catch(e) { return []; }
};

window.anPostTeamShout = function(type, lead) {
  var repEmail = (typeof AN !== 'undefined' && AN.currentRepEmail) || (typeof _currentUser !== 'undefined' && _currentUser ? _currentUser.email : '') || '';
  var repName = (typeof anGetRepName === 'function' && repEmail) ? anGetRepName(repEmail) : (repEmail ? repEmail.split('@')[0] : 'A rep');
  var leadName = ((lead.firstName||'')+' '+(lead.lastName||'')).trim() || lead.company || 'a lead';
  var msgs = {
    demo: '🎯 '+repName+' set a demo with '+leadName+'!',
    won:  '🏆 '+repName+' CLOSED '+leadName+'!'
  };
  if (!msgs[type]) return;

  var shout = {
    id: 'shout-'+Date.now(),
    type: type,
    message: msgs[type],
    repEmail: repEmail,
    repName: repName,
    leadName: leadName,
    company: lead.company || '',
    createdAt: new Date().toISOString()
  };

  var shouts = anGetTeamShouts();
  shouts.unshift(shout);
  shouts = shouts.slice(0, 50);
  localStorage.setItem('team-shouts', JSON.stringify(shouts));

  var sb = typeof getSupabase === 'function' ? getSupabase() : null;
  if (sb && typeof _currentUser !== 'undefined' && _currentUser) {
    sb.from('admin_content').select('value').eq('key', 'team_shouts').maybeSingle().then(function(r){
      var all = [];
      try { if (r.data && r.data.value) all = JSON.parse(r.data.value); } catch(e) {}
      if (!Array.isArray(all)) all = [];
      all.unshift(shout);
      all = all.slice(0, 100);
      sb.from('admin_content').upsert({
        key: 'team_shouts',
        value: JSON.stringify(all),
        updated_by: repEmail,
        updated_at: new Date().toISOString()
      }, { onConflict: 'key' });
    });
  }

  anShowShoutCelebration(shout.message, type);
};

window.anShowShoutCelebration = function(message, type) {
  var old = document.getElementById('team-shout-banner');
  if (old) old.remove();
  var colors = { demo:'linear-gradient(135deg,#f59e0b,#d97706)', won:'linear-gradient(135deg,#10b981,#059669)' };
  var el = document.createElement('div');
  el.id = 'team-shout-banner';
  el.style.cssText = 'position:fixed;top:52px;left:50%;transform:translateX(-50%);z-index:25000;background:'+(colors[type]||colors.demo)+';color:#fff;padding:14px 28px;border-radius:14px;font-size:15px;font-weight:800;box-shadow:0 8px 32px rgba(0,0,0,0.3);animation:shoutPop 4s ease forwards;pointer-events:none;text-align:center;max-width:90vw;';
  el.textContent = message;
  document.body.appendChild(el);
  setTimeout(function(){ if (el.parentNode) el.remove(); }, 4000);
};

window.anLoadTeamShoutsFromCloud = function(cb) {
  var sb = typeof getSupabase === 'function' ? getSupabase() : null;
  if (!sb) { if (cb) cb(anGetTeamShouts()); return; }
  sb.from('admin_content').select('value').eq('key', 'team_shouts').maybeSingle().then(function(r){
    if (r.data && r.data.value) {
      try {
        var cloud = JSON.parse(r.data.value);
        if (Array.isArray(cloud) && cloud.length) {
          localStorage.setItem('team-shouts', JSON.stringify(cloud));
        }
      } catch(e) {}
    }
    if (cb) cb(anGetTeamShouts());
  }).catch(function(){ if (cb) cb(anGetTeamShouts()); });
};

function anBuildShoutFeedHTML(shouts, limit) {
  shouts = (shouts || []).slice(0, limit || 6);
  if (!shouts.length) {
    return '<div class="hd-empty"><div class="hd-empty-icon">📣</div>Demo sets &amp; closes show up here for the whole team</div>';
  }
  return shouts.map(function(s){
    var col = s.type === 'won' ? '#10b981' : '#f59e0b';
    var icon = s.type === 'won' ? '🏆' : '🎯';
    var ago = '';
    try {
      var diff = Date.now() - new Date(s.createdAt).getTime();
      if (diff < 3600000) ago = Math.max(1, Math.floor(diff/60000))+'m ago';
      else if (diff < 86400000) ago = Math.floor(diff/3600000)+'h ago';
      else ago = new Date(s.createdAt).toLocaleDateString('en-US',{month:'short',day:'numeric'});
    } catch(e) {}
    return '<div class="hd-list-item" style="border-left:3px solid '+col+';padding-left:12px;">'
      +'<div class="hd-avatar" style="background:'+col+';">'+icon+'</div>'
      +'<div class="hd-item-main"><div class="hd-item-name">'+hdEsc(s.message)+'</div>'
      +'<div class="hd-item-sub">'+hdEsc(s.repName||'')+(ago?' · '+ago:'')+'</div></div></div>';
  }).join('');
}

window.hdRefreshShoutCard = function(shouts) {
  var card = document.getElementById('hd-shout-card');
  if (!card) return;
  var feed = card.querySelector('.hd-shout-feed');
  if (feed && typeof anBuildShoutFeedHTML === 'function') {
    feed.innerHTML = anBuildShoutFeedHTML(shouts, 6);
  }
  var statsEl = card.querySelector('.hd-shout-stats');
  if (statsEl && typeof hdGetTodayDashStats === 'function') {
    var stats = hdGetTodayDashStats();
    statsEl.textContent = 'Today: '+stats.dashCalls+' calls · '+stats.dashDemos+' demos · '+stats.dashCloses+' closes';
  }
};

// Refresh shout content in place — never re-insert (prevents card order swap on load)
var _origHdRender = window.hdRender;
if (typeof _origHdRender === 'function') {
  window.hdRender = function() {
    _origHdRender();
    anLoadTeamShoutsFromCloud(function(shouts){
      hdRefreshShoutCard(shouts);
    });
  };
}

