    +'<button onclick="saveCoData(\''+anEsc(name)+'\',{});coTab(\'notes\')" style="display:flex;align-items:center;gap:5px;padding:6px 13px;border:1.5px solid var(--divider);border-radius:7px;background:var(--card-bg);font-size:12px;font-weight:600;color:var(--text-secondary);cursor:pointer;font-family:var(--sans);">📝 Note</button>'
    +'<button onclick="createDealForCompany(\''+anEsc(name)+'\')" style="display:flex;align-items:center;gap:5px;padding:6px 13px;border:1px solid rgba(99,102,241,0.3);border-radius:7px;background:rgba(99,102,241,0.08);font-size:12px;font-weight:700;color:#6366f1;cursor:pointer;font-family:var(--sans);">💎 Deal</button>'
    +'</div>'

    // ── Two-column body ───────────────────────────────────────
    +'<div style="display:grid;grid-template-columns:1fr 290px;flex:1;overflow:hidden;">'

    // Main: activity feed + tabs
    +'<div style="display:flex;flex-direction:column;border-right:1px solid var(--divider);overflow:hidden;">'
