    +['activity','calls','notes'].map(function(t,i){
      var labels={activity:'All Activities ('+allCalls.length+')',calls:'Calls',notes:'Notes'};
      return '<button id="cot-'+t+'" onclick="coTab(\''+t+'\')" style="padding:10px 14px;border:none;border-bottom:2px solid '+(i===0?'#6366f1':'transparent')+';font-size:12.5px;font-weight:'+(i===0?'700':'600')+';color:'+(i===0?'#6366f1':'var(--text-muted)')+';background:transparent;cursor:pointer;font-family:var(--sans);">'+labels[t]+'</button>';
    }).join('')
    +'</div>'
    +'<div style="flex:1;overflow-y:auto;">'
