      var col2=callColors[c.outcome]||'#a1a1aa';
      var ds=anDate(c.date)+(c.time?' · '+c.time:'');
      return '<div style="display:flex;gap:14px;padding:14px 0;border-bottom:1px solid var(--divider);">'
