        +(i<allCalls.length-1?'<div style="width:2px;flex:1;background:var(--divider);margin-top:3px;border-radius:2px;min-height:12px;"></div>':'')
        +'</div>'
        +'<div style="flex:1;">'
        +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:3px;">'
        +'<div><span style="font-size:13px;font-weight:700;color:'+col2+';">'+(c.outcome||'call').charAt(0).toUpperCase()+(c.outcome||'call').slice(1)+'</span>'
        +'<span style="font-size:12px;color:var(--text-muted);margin-left:7px;">with <strong style="color:var(--text-primary);">'+anEsc(c._cname)+'</strong></span></div>'
        +'<span style="font-size:11px;color:var(--text-muted);">'+ds+(c.duration?' · '+c.duration+'m':'')+'</span>'
