    +(allCalls.length?allCalls.map(function(c){var col2=callColors[c.outcome]||'#a1a1aa'; return '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--divider);">'+'<div style="width:26px;height:26px;border-radius:50%;background:'+col2+'15;border:1.5px solid '+col2+'44;display:flex;align-items:center;justify-content:center;font-size:12px;">'+(callIcons[c.outcome]||'📞')+'</div><div style="flex:1;"><div style="font-size:12.5px;font-weight:600;color:var(--text-primary);">'+anEsc(c._cname)+'</div><div style="font-size:11px;color:var(--text-muted);">'+anDate(c.date)+(c.duration?' · '+c.duration+'m':'')+'</div>'+( c.notes?'<div style="font-size:12px;color:var(--text-secondary);">'+anEsc(c.notes)+'</div>':'')+'</div><span style="font-size:11px;font-weight:700;color:'+col2+';">'+(c.outcome||'').charAt(0).toUpperCase()+(c.outcome||'').slice(1)+'</span></div>'; }).join(''):'<div style="padding:32px;text-align:center;color:var(--text-muted);font-size:12.5px;">No calls yet</div>')
    +'</div>'
    // Notes tab
    +'<div id="cop-notes" style="display:none;padding:20px;">'
