// ─── inline block 43 ───────────────────────
// ============================================================
// REP MANAGEMENT + LEAD ASSIGNMENT FIX
// 1. Admin can invite reps with email + set their display name
// 2. Assigned leads sync via rep_email even before first login
// 3. Rep onboarding: first login prompts set-password flow
// ============================================================

var AN_ADMIN_EMAIL = typeof AN_CRM_ADMIN_EMAIL !== 'undefined' ? AN_CRM_ADMIN_EMAIL : 'asmithee@insurewithcompass.com';

// ── LEAD ASSIGNMENT FIX ───────────────────────────────────────
// When admin assigns leads, write them to an_lead_assignments
// keyed by rep_email. Reps pick them up on next load regardless
// of whether they've logged in before.

var _origANSyncRepLeads = window.anSyncRepLeadsToCloud || function(){};

window.anSyncRepLeadsToCloud = function(opts, cb) {
  opts = opts || {}; cb = cb || function(){};
  var sb = typeof getSupabase==='function' ? getSupabase() : null;
  if (!sb || !_currentUser || !AN.isAdmin) { cb(); return; }

  // Original sync (needs user_id map)
  _origANSyncRepLeads(opts, function() {
    // ALSO write to an_lead_assignments keyed by rep_email
    // This is the fallback for reps who haven't logged in yet
    var byRep = {};
    AN.leads.forEach(function(l) {
      if (!l || !l._repEmail) return;
      var em = l._repEmail.toLowerCase();
      if (!em || em === AN_ADMIN_EMAIL.toLowerCase()) return;
      if (!byRep[em]) byRep[em] = [];
      var copy = Object.assign({}, l);
      delete copy._repEmail;
      byRep[em].push(copy);
    });

    var upserts = Object.keys(byRep).map(function(em) {
      return { rep_email: em, data: byRep[em], updated_at: new Date().toISOString() };
    });

    if (!upserts.length) { cb(); return; }

    // Upsert to an_lead_assignments
    sb.from('an_lead_assignments')
      .upsert(upserts, { onConflict: 'rep_email' })
      .then(function(r) {
        if (r.error) console.warn('[CRM] Lead assignment sync warning:', r.error.message);
        else console.log('[CRM] Lead assignments synced for', upserts.length, 'reps');
        cb();
      })
      .catch(function(e) { console.warn('[CRM] Lead assignment error:', e); cb(); });
  });
};

// Patch AN.load for reps — also check an_lead_assignments
var _origANFinishCloudLoad = window.anFinishCloudLeadLoad;
window.anFinishCloudLeadLoad = function(sb, cb) {
  if (!sb || !_currentUser) { if(cb) cb(); return; }
  var repEmail = (_currentUser.email || '').toLowerCase();
  var isAdmin  = repEmail === AN_ADMIN_EMAIL.toLowerCase();

  // Call original load
  if (typeof _origANFinishCloudLoad === 'function') {
    _origANFinishCloudLoad(sb, function() {
      if (isAdmin) { if(cb) cb(); return; }
      // After normal load, also merge from an_lead_assignments
      sb.from('an_lead_assignments')
        .select('data, updated_at')
        .eq('rep_email', repEmail)
        .then(function(r) {
          if (r.data && r.data[0] && r.data[0].data) {
            var assigned = r.data[0].data;
            if (assigned.length) {
              assigned.forEach(function(l) { l._repEmail = repEmail; });
              var existing = AN.leads || [];
              var existingIds = existing.map(function(l){ return l.id; });
              var newLeads = assigned.filter(function(l){ return existingIds.indexOf(l.id) < 0; });
              if (newLeads.length) {
                AN.leads = existing.concat(newLeads);
                AN.invalidateLeadCaches && AN.invalidateLeadCaches();
                if (typeof anPersistLeadsLocal === 'function') anPersistLeadsLocal(function(){});
                console.log('[CRM] Merged', newLeads.length, 'assigned leads from admin');
                if (typeof showToast === 'function') showToast(newLeads.length + ' new leads assigned to you');
              }
            }
          }
          if (cb) cb();
        })
        .catch(function() { if(cb) cb(); });
    });
  } else {
    if(cb) cb();
  }
};

// ── REP MANAGEMENT UI ─────────────────────────────────────────
function buildRepManagementPanel() {
  var reps = _repViews ? Object.keys(_repViews) : [];

  return '<div id="rep-mgmt-panel" style="margin-top:28px;">'
    // Header
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">'
    + '<div>'
    + '<div style="font-size:16px;font-weight:800;color:var(--text-primary);letter-spacing:-0.4px;">Rep Management</div>'
    + '<div style="font-size:13px;color:var(--text-muted);margin-bottom:16px;">Invite reps, manage access, and assign leads.</div>'
    + '</div>'
    + '<button onclick="openInviteRepModal()" style="padding:8px 16px;border:none;border-radius:8px;background:#6366f1;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:var(--sans);box-shadow:0 2px 8px rgba(99,102,241,0.3);">+ Invite Rep</button>'
    + '</div>'

    // Rep cards
    + '<div id="rep-cards-list" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px;margin-bottom:24px;">'
    + (reps.length ? reps.map(function(email) {
        return buildRepCard(email);
      }).join('')
      : '<div style="background:var(--card-bg);border:1.5px dashed var(--divider);border-radius:12px;padding:28px;text-align:center;color:var(--text-muted);">'
        + '<div style="font-size:24px;margin-bottom:8px;">👥</div>'
        + '<div style="font-size:13.5px;font-weight:600;margin-bottom:4px;">No reps added yet</div>'
        + '<div style="font-size:12px;">Click + Invite Rep to get started</div>'
        + '</div>')
    + '</div>'

    // Rep View Control
    + buildRepViewPanel()
    + '</div>';
}

function buildRepCard(email) {
  var name  = typeof anGetRepName === 'function' ? anGetRepName(email) : email.split('@')[0];
  var col   = anColor ? anColor(email) : '#6366f1';
  var views = (_repViews && _repViews[email]) || {};
  var title = views.title || '';
  var hidden = (views.hidden || []).length;
  var leadCount = typeof AN !== 'undefined' ? AN.leads.filter(function(l){ return l._repEmail === email; }).length : 0;

  return '<div style="background:var(--card-bg);border:1px solid var(--divider);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:10px;">'
    + '<div style="display:flex;align-items:center;gap:10px;">'
    + '<div style="width:38px;height:38px;border-radius:50%;background:' + col + '18;border:2px solid ' + col + '33;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:800;color:' + col + ';flex-shrink:0;">' + name[0].toUpperCase() + '</div>'
    + '<div style="flex:1;min-width:0;">'
    + '<div style="display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;">'
    + '<div contenteditable="true" spellcheck="false" data-rep-email="' + anEsc(email) + '" onblur="anSetRepDisplayName(this.dataset.repEmail,this.textContent)" onkeydown="if(event.key===\'Enter\'){event.preventDefault();this.blur();}" title="Click to edit name" style="font-size:13.5px;font-weight:700;color:var(--text-primary);cursor:text;outline:none;border-bottom:1px dashed transparent;" onmouseover="this.style.borderBottomColor=\'' + col + '\'" onmouseout="this.style.borderBottomColor=\'transparent\'">' + anEsc(name) + '</div>'
    + '<div contenteditable="true" spellcheck="false" data-rep-email="' + anEsc(email) + '" data-placeholder="+ title" onblur="anSetRepTitle(this.dataset.repEmail,this.textContent)" onkeydown="if(event.key===\'Enter\'){event.preventDefault();this.blur();}" title="Click to edit title (e.g. SDR, AE)" style="font-size:11px;font-weight:600;color:' + col + ';cursor:text;outline:none;border-bottom:1px dashed transparent;" onmouseover="this.style.borderBottomColor=\'' + col + '\'" onmouseout="this.style.borderBottomColor=\'transparent\'">' + (title ? anEsc(title) : '') + '</div>'
    + '</div>'
    + '<div style="font-size:12px;color:var(--text-muted);">' + anEsc(email) + '</div>'
    + '</div>'
    + '<button onclick="removeRep(\'' + anEsc(email) + '\')" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:16px;padding:4px;" title="Remove rep">✕</button>'
    + '</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">'
    + '<div style="background:var(--body-bg);border-radius:8px;padding:8px;text-align:center;">'
    + '<div style="font-size:18px;font-weight:800;color:#6366f1;">' + leadCount + '</div>'
    + '<div style="font-size:10px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;">Leads</div>'
    + '</div>'
    + '<div style="background:var(--body-bg);border-radius:8px;padding:8px;text-align:center;">'
    + '<div style="font-size:18px;font-weight:800;color:' + (hidden > 0 ? '#f59e0b' : '#10b981') + ';">' + (hidden > 0 ? hidden + ' hidden' : 'All') + '</div>'
    + '<div style="font-size:10px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;">Sections</div>'
    + '</div>'
    + '</div>'
    + '<div style="display:flex;gap:6px;">'
    + '<button onclick="openAssignLeadsModal(\'' + anEsc(email) + '\')" style="flex:1;padding:6px 0;border:1.5px solid var(--divider);border-radius:7px;background:var(--card-bg);font-size:12px;font-weight:600;color:var(--text-secondary);cursor:pointer;font-family:var(--sans);">📋 Assign Leads</button>'
    + '<button onclick="resendInvite(\'' + anEsc(email) + '\')" style="flex:1;padding:6px 0;border:none;border-radius:7px;background:rgba(99,102,241,0.1);font-size:12px;font-weight:700;color:#6366f1;cursor:pointer;font-family:var(--sans);">📧 Resend Invite</button>'
    + '</div>'
    + '<button onclick="openSetPasswordModal(\'' + anEsc(email) + '\')" style="width:100%;padding:6px 0;border:1.5px solid rgba(245,158,11,0.3);border-radius:7px;background:rgba(245,158,11,0.08);font-size:12px;font-weight:700;color:#b45309;cursor:pointer;font-family:var(--sans);">🔑 Set Password Directly</button>'
    + '</div>';
}

// ── SET PASSWORD DIRECTLY (bypasses fragile email-link reset flow) ────
window.openSetPasswordModal = function(email) {
  var old = document.getElementById('set-rep-pw-modal'); if (old) old.remove();
  var m = document.createElement('div');
  m.id = 'set-rep-pw-modal';
  m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.65);z-index:10001;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(4px);';
  m.innerHTML = '<div style="background:var(--card-bg);border-radius:16px;width:420px;max-width:95vw;box-shadow:0 24px 80px rgba(0,0,0,0.35);overflow:hidden;">'
    + '<div style="background:linear-gradient(135deg,#0a0a14,#1a1640);padding:22px 26px;display:flex;justify-content:space-between;align-items:center;">'
    + '<div><div style="font-size:18px;font-weight:800;color:#fff;">Set Password Directly</div>'
    + '<div style="font-size:12px;color:rgba(255,255,255,0.45);margin-top:2px;">' + anEsc(email) + '</div></div>'
    + '<button onclick="document.getElementById(\'set-rep-pw-modal\').remove()" style="background:rgba(255,255,255,0.1);border:none;color:rgba(255,255,255,0.6);width:30px;height:30px;border-radius:8px;cursor:pointer;font-size:16px;">✕</button>'
    + '</div>'
    + '<div style="padding:24px 26px;">'
    + '<div style="background:rgba(245,158,11,0.08);border:1px solid rgba(245,158,11,0.25);border-radius:8px;padding:12px 14px;margin-bottom:18px;font-size:12.5px;color:var(--text-primary);line-height:1.6;">'
    + '⚠️ This sets their password immediately — no email involved. Use this when reset emails keep expiring before they\'re clicked. Share the password with them directly and have them change it once they\'re in.'
    + '</div>'
    + '<label style="font-family:var(--mono);font-size:9.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-muted);display:block;margin-bottom:5px;">New Password</label>'
    + '<input id="set-pw-input" type="text" placeholder="At least 8 characters" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:9px 11px;font-size:13.5px;color:var(--text-primary);background:var(--card-bg);outline:none;font-family:var(--sans);box-sizing:border-box;margin-bottom:14px;">'
    + '<div id="set-pw-error" style="display:none;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:10px 13px;font-size:13px;color:#ef4444;margin-bottom:12px;"></div>'
    + '<div style="display:flex;gap:8px;">'
    + '<button onclick="document.getElementById(\'set-rep-pw-modal\').remove()" style="flex:1;padding:11px;border-radius:8px;border:1.5px solid var(--divider);background:transparent;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);color:var(--text-secondary);">Cancel</button>'
    + '<button id="set-pw-submit-btn" onclick="submitSetPassword(\'' + anEsc(email) + '\')" style="flex:2;padding:11px;border-radius:8px;border:none;background:#f59e0b;color:#fff;font-size:13.5px;font-weight:700;cursor:pointer;font-family:var(--sans);">Set Password</button>'
    + '</div></div></div>';
  document.body.appendChild(m);
  m.onclick = function(e) { if (e.target === m) m.remove(); };
  setTimeout(function(){ var f = document.getElementById('set-pw-input'); if (f) f.focus(); }, 50);
};

window.submitSetPassword = function(email) {
  var pw  = (document.getElementById('set-pw-input')?.value || '').trim();
  var btn = document.getElementById('set-pw-submit-btn');
  var err = document.getElementById('set-pw-error');

  if (!pw || pw.length < 8) {
    err.textContent = 'Password must be at least 8 characters';
    err.style.display = 'block';
    return;
  }
  err.style.display = 'none';
  btn.disabled = true;
  btn.textContent = 'Setting password...';

  var sb = typeof getSupabase === 'function' ? getSupabase() : null;
  var getToken = sb ? sb.auth.getSession().then(function(r) { return (r.data && r.data.session && r.data.session.access_token) || ''; }) : Promise.resolve('');

  getToken.then(function(token) {
    return fetch('/.netlify/functions/admin-set-password', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
      body: JSON.stringify({ email: email, newPassword: pw })
    });
  }).then(function(res) {
    return res.json().then(function(data) {
      if (!res.ok || data.error) throw new Error(data.error || 'Could not set password');
      return data;
    });
  }).then(function() {
    var modal = document.getElementById('set-rep-pw-modal');
    if (modal) modal.remove();
    if (typeof showToast === 'function') showToast('Password set for ' + email + ' — share it with them directly');
  }).catch(function(e) {
    err.textContent = (e && e.message) ? e.message : 'Could not set password';
    err.style.display = 'block';
    btn.disabled = false;
    btn.textContent = 'Set Password';
  });
};

