    + '</div>'

    + '<div style="padding:14px 20px;border-bottom:1px solid var(--divider);display:flex;gap:8px;flex-shrink:0;">'
    + '<input type="text" placeholder="Search leads..." oninput="filterAssignList(this.value)" '
    + 'style="flex:1;padding:7px 11px;border:1.5px solid var(--divider);border-radius:7px;font-size:12.5px;color:var(--text-primary);background:var(--body-bg);outline:none;font-family:var(--sans);" '
    + 'onfocus="this.style.borderColor=\'#6366f1\'" onblur="this.style.borderColor=\'var(--divider)\'">'
    + '<button onclick="selectAllAssign()" style="padding:7px 12px;border:1.5px solid var(--divider);border-radius:7px;background:var(--card-bg);font-size:12px;font-weight:600;color:var(--text-secondary);cursor:pointer;font-family:var(--sans);">Select All</button>'
