window.filterAssignList = function(q) {
  q = q.toLowerCase();
  document.querySelectorAll('.assign-row').forEach(function(row) {
    var text = row.textContent.toLowerCase();
    row.style.display = text.includes(q) ? '' : 'none';
  });
};

window.selectAllAssign = function() {
  var cbs = document.querySelectorAll('.assign-cb');
  var allChecked = Array.from(cbs).every(function(cb){ return cb.checked; });
  cbs.forEach(function(cb){ cb.checked = !allChecked; });
  var count = allChecked ? 0 : cbs.length;
  var el = document.getElementById('assign-selected-count');
  if (el) el.textContent = count + ' selected';
};

window.confirmAssignLeads = function(repEmail) {
  var selected = Array.from(document.querySelectorAll('.assign-cb:checked')).map(function(cb){ return cb.dataset.id; });
  if (!selected.length) { if(typeof showToast==='function') showToast('Select at least one lead'); return; }

  selected.forEach(function(id) {
    var lead = AN.leads.find(function(l){ return l.id===id; });
    if (lead) {
      lead._repEmail = repEmail.toLowerCase();
      lead.updated = new Date().toISOString();
    }
  });

  AN.save(function() {
    // Also sync to an_lead_assignments immediately
    anSyncRepLeadsToCloud({ onlyEmails: [repEmail] }, function(){});
  });

  document.getElementById('assign-leads-modal').remove();
  if (typeof showToast === 'function') showToast('Assigned ' + selected.length + ' leads to ' + repEmail.split('@')[0]);

  // Refresh rep card
  var cards = document.getElementById('rep-cards-list');
  if (cards) cards.innerHTML = Object.keys(_repViews||{}).map(buildRepCard).join('');
};

