window.createDemoReminder = function(leadId) {
  var lead = AN.leads.find(function(l){ return l.id===leadId; });
  if (!lead) return;
  var dateEl = document.getElementById('demo-date');
  var timeEl = document.getElementById('demo-time');
  var demoDate = dateEl ? dateEl.value : new Date().toISOString().split('T')[0];
  var demoTime = timeEl ? timeEl.value : '13:00';

  // Create reminder 15 min before
  var demoMs = new Date(demoDate+'T'+demoTime).getTime();
  var remindMs = demoMs - 15*60*1000;
  var remindDate = new Date(remindMs);
  var remindDateStr = remindDate.toISOString().split('T')[0];
  var remindTimeStr = remindDate.getHours().toString().padStart(2,'0')+':'+remindDate.getMinutes().toString().padStart(2,'0');

  if (!AN._tasks) AN._tasks = [];
  AN._tasks.push({
    id:        'task-demo-'+Date.now(),
    leadId:    leadId,
    leadName:  ((lead.firstName||'')+' '+(lead.lastName||'')).trim()||lead.company||'Unknown',
    leadPhone: lead.phone||'',
    repEmail:  AN.currentRepEmail||'',
    type:      'demo',
    dueDate:   remindDateStr,
    dueTime:   remindTimeStr,
    notes:     'Demo at ' + demoTime + ' — prep and join 5 min early',
    notify:    true,
    done:      false,
    createdAt: new Date().toISOString()
  });

  // Also create a follow-up task for 2 hours after the demo
  var followMs = demoMs + 2*60*60*1000;
  var followDate = new Date(followMs);
  var followDateStr = followDate.toISOString().split('T')[0];
  var followTimeStr = followDate.getHours().toString().padStart(2,'0')+':'+followDate.getMinutes().toString().padStart(2,'0');

  AN._tasks.push({
    id:        'task-followup-'+Date.now(),
    leadId:    leadId,
    leadName:  ((lead.firstName||'')+' '+(lead.lastName||'')).trim()||lead.company||'Unknown',
    leadPhone: lead.phone||'',
    repEmail:  AN.currentRepEmail||'',
    type:      'followup',
    dueDate:   followDateStr,
    dueTime:   followTimeStr,
    notes:     'Follow up after demo — send recap, answer questions',
    notify:    true,
    done:      false,
    createdAt: new Date().toISOString()
  });

  if (typeof saveTasks === 'function') saveTasks();
  if (typeof startTaskNotifier === 'function') startTaskNotifier();

  var btn = document.querySelector('#demo-auto-modal button[onclick*="createDemoReminder"]');
  if (btn) { btn.textContent = '✓ Created!'; btn.style.background='#10b981'; btn.disabled=true; }
  if (typeof showToast==='function') showToast('Demo reminder + follow-up tasks created ✓');
};

window.openDemoConfirmEmail = function(leadId) {
  var lead = AN.leads.find(function(l){ return l.id===leadId; });
  if (!lead || !lead.email) return;

  var dateEl = document.getElementById('demo-date');
  var timeEl = document.getElementById('demo-time');
  var demoDate = dateEl ? dateEl.value : '';
  var demoTime = timeEl ? timeEl.value : '';

  var dateLabel = demoDate
    ? new Date(demoDate+'T12:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})
    : '';

  var bodyEl = document.getElementById('demo-email-body');
  var body = bodyEl ? bodyEl.value : '';

  var subject = 'Your AgentNav Demo' + (dateLabel ? ' — ' + dateLabel : '');

  // Open mailto: with pre-filled subject and body
  var mailto = 'mailto:' + encodeURIComponent(lead.email)
    + '?subject=' + encodeURIComponent(subject)
    + '&body=' + encodeURIComponent(body);

  window.open(mailto, '_blank');

  // Log as email activity
  if (!lead.callLog) lead.callLog = [];
  lead.callLog.push({
    id:      'email-'+Date.now(),
    type:    'email',
    outcome: 'emailed',
    date:    new Date().toISOString().split('T')[0],
    time:    new Date().getHours().toString().padStart(2,'0')+':'+new Date().getMinutes().toString().padStart(2,'0'),
    notes:   'Demo confirmation email sent' + (dateLabel?' for '+dateLabel:''),
    subject: subject
  });
  lead.updated = new Date().toISOString();
  AN.save();

  if (typeof showToast==='function') showToast('Email opened in your mail app ✓');
};

window.copyDemoEmail = function(leadId) {
  var bodyEl = document.getElementById('demo-email-body');
  if (!bodyEl) return;
  var text = bodyEl.value;

  if (navigator.clipboard) {
    navigator.clipboard.writeText(text).then(function() {
      var btn = document.getElementById('demo-copy-btn');
      if (btn) { btn.textContent = '✓ Copied!'; btn.style.background='#10b981'; btn.style.color='#fff'; btn.style.borderColor='#10b981'; }
      if (typeof showToast==='function') showToast('Email template copied to clipboard ✓');
    });
  } else {
    // Fallback
    bodyEl.select();
    document.execCommand('copy');
    if (typeof showToast==='function') showToast('Email template copied ✓');
  }
};

console.log('[OWNERSHIP + DEMO AUTO] Loaded.');

