function anSeqEsc(s) {
  return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function sqTextareaSafe(s) {
  return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
}

function anSeqToday() {
  var d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

function anSeqAddDays(dateStr, days) {
  var d = new Date(dateStr + 'T12:00:00');
  d.setDate(d.getDate() + (days || 0));
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

function anLoadSequences() {
  try {
    AN._sequences = JSON.parse(localStorage.getItem(AN_SEQ_STORAGE_KEY) || '[]');
  } catch (e) {
    AN._sequences = [];
  }
  if (!AN._sequences.length) {
    AN._sequences = [JSON.parse(JSON.stringify(AN_DEFAULT_SEQUENCE))];
    anSaveSequences();
  }
  return AN._sequences;
}

function anSaveSequences() {
  try { localStorage.setItem(AN_SEQ_STORAGE_KEY, JSON.stringify(AN._sequences || [])); } catch (e) {}
}

function anGetSequence(seqId) {
  anLoadSequences();
  return (AN._sequences || []).find(function(s) { return s.id === seqId; }) || null;
}

function anGetLeadEnrollment(lead) {
  return lead && lead.seqEnrollment ? lead.seqEnrollment : null;
}

function anGetEnrollmentStep(lead) {
  var en = anGetLeadEnrollment(lead);
  if (!en || en.status === 'completed' || en.status === 'paused') return null;
  var seq = anGetSequence(en.sequenceId);
  if (!seq || !seq.steps || !seq.steps.length) return null;
  var idx = en.stepIndex || 0;
  if (idx >= seq.steps.length) return null;
  return { sequence: seq, step: seq.steps[idx], stepIndex: idx, enrollment: en };
}

window.anEnrollLeadInSequence = function(leadId, sequenceId) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  var seq = anGetSequence(sequenceId || 'seq-aca-5touch');
  if (!lead || !seq) return false;
  var today = anSeqToday();
  lead.seqEnrollment = {
    sequenceId: seq.id,
    stepIndex: 0,
    enrolledAt: today,
    nextStepDue: today,
    status: 'active'
  };
  if (!lead.seqLog) lead.seqLog = [];
  lead.updated = new Date().toISOString();
  if (typeof AN !== 'undefined' && AN.save) AN.save();
  return true;
};

window.anEnrollSelectedInSequence = function() {
  if (!AN.selectedIds || !AN.selectedIds.length) {
    if (typeof showToast === 'function') showToast('Select leads first');
    return;
  }
  anLoadSequences();
  var seqOpts = (AN._sequences || []).map(function(s) {
    return '<option value="' + s.id + '">' + anSeqEsc(s.name) + '</option>';
  }).join('');
  var old = document.getElementById('an-seq-enroll-modal');
  if (old) old.remove();
  var m = document.createElement('div');
  m.id = 'an-seq-enroll-modal';
  m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:10002;display:flex;align-items:center;justify-content:center;padding:20px;';
  m.innerHTML = '<div style="background:var(--card-bg);border-radius:16px;padding:26px;width:440px;max-width:95vw;box-shadow:0 24px 80px rgba(0,0,0,0.35);">'
    + '<div style="font-size:18px;font-weight:800;color:var(--text-primary);margin-bottom:6px;">📨 Enroll in Sequence</div>'
    + '<div style="font-size:13px;color:var(--text-muted);margin-bottom:16px;">' + AN.selectedIds.length + ' lead(s) will start at Step 1 today.</div>'
    + '<label style="font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:6px;">Sequence</label>'
    + '<select id="an-seq-enroll-pick" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:10px 12px;font-size:14px;margin-bottom:18px;font-family:inherit;background:var(--card-bg);color:var(--text-primary);">' + seqOpts + '</select>'
    + '<button onclick="anConfirmEnrollSelected()" style="width:100%;padding:14px;border-radius:10px;border:none;background:linear-gradient(135deg,#7c3aed,#6366f1);color:#fff;font-size:15px;font-weight:800;cursor:pointer;font-family:inherit;">Enroll →</button>'
    + '</div>';
  document.body.appendChild(m);
  m.onclick = function(e) { if (e.target === m) m.remove(); };
};

window.anConfirmEnrollSelected = function() {
  var pick = document.getElementById('an-seq-enroll-pick');
  var seqId = pick ? pick.value : 'seq-aca-5touch';
  var n = 0;
  (AN.selectedIds || []).forEach(function(id) {
    if (anEnrollLeadInSequence(id, seqId)) n++;
  });
  document.getElementById('an-seq-enroll-modal') && document.getElementById('an-seq-enroll-modal').remove();
  if (typeof showToast === 'function') showToast('📨 ' + n + ' lead(s) enrolled in sequence');
  if (typeof renderLeadsTable === 'function') renderLeadsTable();
  if (typeof hdRender === 'function') hdRender();
};

function anCountSeqDueLeads(opts) {
  opts = opts || {};
  var today = anSeqToday();
  var myEmail = (typeof AN !== 'undefined' && AN.currentRepEmail) || '';
  var isAdmin = (typeof AN !== 'undefined' && AN.isAdmin) || false;
  return (AN.leads || []).filter(function(l) {
    if (l.status === 'won' || l.status === 'lost') return false;
    if (!isAdmin && l._repEmail && l._repEmail !== myEmail) return false;
    var en = anGetLeadEnrollment(l);
    if (!en || en.status !== 'active' || !en.nextStepDue) return false;
    if (opts.dueOnly !== false && en.nextStepDue > today) return false;
    return true;
  }).length;
}

function anBuildSeqQueueIds(opts) {
  opts = opts || {};
  var today = anSeqToday();
  var limit = opts.limit || 50;
  var myEmail = AN.currentRepEmail || '';
  var isAdmin = AN.isAdmin || false;
  var leads = (AN.leads || []).filter(function(l) {
    if (l.status === 'won' || l.status === 'lost') return false;
    if (!isAdmin && l._repEmail && l._repEmail !== myEmail) return false;
    var en = anGetLeadEnrollment(l);
    if (!en || en.status !== 'active') return false;
    if (en.nextStepDue && en.nextStepDue > today) return false;
    return true;
  });
  leads.sort(function(a, b) {
    return (a.seqEnrollment.nextStepDue || '').localeCompare(b.seqEnrollment.nextStepDue || '');
  });
  if (opts.useSelected && AN.selectedIds && AN.selectedIds.length) {
    var sel = {};
    AN.selectedIds.forEach(function(id) { sel[id] = 1; });
    leads = leads.filter(function(l) { return sel[l.id]; });
  }
  return leads.slice(0, limit).map(function(l) { return l.id; });
}

function anPersistSeqQueue() {
  try { localStorage.setItem(AN_SEQ_QUEUE_KEY, JSON.stringify(AN.seqQueue || null)); } catch (e) {}
}

function anLoadSeqQueue() {
  try { AN.seqQueue = JSON.parse(localStorage.getItem(AN_SEQ_QUEUE_KEY) || 'null'); } catch (e) { AN.seqQueue = null; }
  if (AN.seqQueue && !Array.isArray(AN.seqQueue.completed)) AN.seqQueue.completed = [];
  return AN.seqQueue;
}

window.anStartSequenceSession = function(ids, sequenceId) {
  anLoadSeqQueue();
  AN.seqQueue = {
    sequenceId: sequenceId || 'seq-aca-5touch',
    ids: ids,
    completed: [],
    startedAt: new Date().toISOString()
  };
  anPersistSeqQueue();
  if (typeof showToast === 'function') showToast('📨 Sequence session started — ' + ids.length + ' due');
  anOpenSeqPanel(ids[0]);
  anRenderSeqSessionBanner();
};

window.anEndSequenceSession = function(showDone) {
  AN.seqQueue = null;
  anPersistSeqQueue();
  anCloseSeqPanel();
  var bar = document.getElementById('an-seq-banner');
  if (bar) bar.remove();
  if (showDone && typeof showToast === 'function') showToast('🎉 Sequence session complete!');
  if (typeof hdRender === 'function') hdRender();
};

window.anResumeSequenceSession = function() {
  anLoadSeqQueue();
  if (!AN.seqQueue || !AN.seqQueue.ids || !AN.seqQueue.ids.length) {
    if (typeof showToast === 'function') showToast('No active sequence session');
    return;
  }
  var nextId = null;
  AN.seqQueue.ids.forEach(function(id) {
    if (!nextId && AN.seqQueue.completed.indexOf(id) < 0) nextId = id;
  });
  if (!nextId) { anEndSequenceSession(true); return; }
  anOpenSeqPanel(nextId);
};

window.anAdvanceSeqQueue = function(completedId) {
  anLoadSeqQueue();
  if (!AN.seqQueue || !AN.seqQueue.ids) return false;
  if (AN.seqQueue.completed.indexOf(completedId) < 0) AN.seqQueue.completed.push(completedId);
  anPersistSeqQueue();
  var nextId = null;
  AN.seqQueue.ids.forEach(function(id) {
    if (!nextId && AN.seqQueue.completed.indexOf(id) < 0) nextId = id;
  });
  if (!nextId) {
    anEndSequenceSession(true);
    return false;
  }
  setTimeout(function() { anOpenSeqPanel(nextId); }, 180);
  return true;
};

window.anOpenSequenceSessionSetup = function() {
  anEnsureLeadsLoaded(function() {
    anLoadSequences();
    anLoadSeqQueue();
    var old = document.getElementById('an-seq-setup-modal');
    if (old) old.remove();
    var dueCount = anCountSeqDueLeads();
    var selected = (AN.selectedIds || []).length;
    var defaultCount = selected ? Math.min(selected, 50) : Math.min(dueCount || 25, 50);
    var seqOpts = (AN._sequences || []).map(function(s) {
      return '<option value="' + s.id + '">' + anSeqEsc(s.name) + ' (' + s.steps.length + ' steps)</option>';
    }).join('');
    var m = document.createElement('div');
    m.id = 'an-seq-setup-modal';
    m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:10002;display:flex;align-items:center;justify-content:center;padding:20px;';
    m.innerHTML = '<div style="background:var(--card-bg);border-radius:16px;padding:26px;width:500px;max-width:95vw;box-shadow:0 24px 80px rgba(0,0,0,0.35);">'
      + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">'
      + '<div style="font-size:18px;font-weight:800;color:var(--text-primary);">📨 Sequence Session</div>'
      + '<button onclick="document.getElementById(\'an-seq-setup-modal\').remove()" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--text-muted);">✕</button></div>'
      + '<div style="font-size:13px;color:var(--text-muted);margin-bottom:18px;line-height:1.5;">Work through due sequence steps one lead at a time — open emails in Gmail, log calls, then Save &amp; Next.</div>'
      + '<div style="margin-bottom:14px;"><label style="font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:6px;">Sequence</label>'
      + '<select id="an-seq-setup-pick" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:10px 12px;font-size:14px;font-family:inherit;background:var(--card-bg);color:var(--text-primary);">' + seqOpts + '</select></div>'
      + '<div style="margin-bottom:14px;"><label style="font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.1em;display:block;margin-bottom:6px;">How many leads?</label>'
      + '<input id="an-seq-count" type="number" min="1" max="200" value="' + defaultCount + '" style="width:100%;border:1.5px solid var(--divider);border-radius:8px;padding:10px 12px;font-size:15px;font-weight:700;font-family:inherit;box-sizing:border-box;"></div>'
      + '<div style="margin-bottom:10px;font-size:13px;color:var(--text-secondary);">' + dueCount + ' sequence step(s) due today or overdue</div>'
      + '<div style="margin-bottom:16px;"><button type="button" onclick="showSection(\'sequenceeditor\',null)" style="background:none;border:none;padding:0;font-size:12px;font-weight:600;color:#7c3aed;cursor:pointer;font-family:inherit;text-decoration:underline;">✏️ Edit sequences in Sequence Editor</button></div>'
      + (AN.seqQueue && AN.seqQueue.ids && AN.seqQueue.ids.length
        ? '<button onclick="document.getElementById(\'an-seq-setup-modal\').remove();anResumeSequenceSession()" style="width:100%;padding:12px;border-radius:10px;border:1.5px solid #c4b5fd;background:#f5f3ff;color:#7c3aed;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;margin-bottom:8px;">▶ Resume session (' + AN.seqQueue.completed.length + '/' + AN.seqQueue.ids.length + ')</button>'
        : '')
      + '<button onclick="anConfirmSequenceSessionSetup()" style="width:100%;padding:14px;border-radius:10px;border:none;background:linear-gradient(135deg,#7c3aed,#6366f1);color:#fff;font-size:15px;font-weight:800;cursor:pointer;font-family:inherit;">Start Sequence Session →</button>'
      + '</div>';
    document.body.appendChild(m);
    m.onclick = function(e) { if (e.target === m) m.remove(); };
  });
};

window.anConfirmSequenceSessionSetup = function() {
  var countEl = document.getElementById('an-seq-count');
  var limit = countEl ? parseInt(countEl.value, 10) : 25;
  if (isNaN(limit) || limit < 1) limit = 25;
  var pick = document.getElementById('an-seq-setup-pick');
  var seqId = pick ? pick.value : 'seq-aca-5touch';
  var ids = anBuildSeqQueueIds({ limit: limit, useSelected: !!(AN.selectedIds && AN.selectedIds.length) });
  if (!ids.length) {
    if (typeof showToast === 'function') showToast('No due sequence steps — enroll leads or check back tomorrow');
    return;
  }
  document.getElementById('an-seq-setup-modal') && document.getElementById('an-seq-setup-modal').remove();
  anStartSequenceSession(ids, seqId);
  if (typeof hdRender === 'function') hdRender();
};

function anCompleteSeqStep(lead, result, notes) {
  var info = anGetEnrollmentStep(lead);
  if (!info) return false;
  var step = info.step;
  var idx = info.stepIndex;
  var seq = info.sequence;
  var now = new Date();
  var today = anSeqToday();
  if (!lead.seqLog) lead.seqLog = [];
  lead.seqLog.unshift({
    sequenceId: seq.id,
    stepIndex: idx,
    stepType: step.type,
    stepTitle: step.title,
    result: result || 'completed',
    date: today,
    time: now.toTimeString().slice(0, 5),
    notes: notes || '',
    rep: AN.currentRepEmail || ''
  });
  var nextIdx = idx + 1;
  if (result === 'replied' || result === 'stop') {
    lead.seqEnrollment.status = result === 'replied' ? 'replied' : 'paused';
    lead.seqEnrollment.completedAt = today;
  } else if (nextIdx >= seq.steps.length) {
    lead.seqEnrollment.status = 'completed';
    lead.seqEnrollment.stepIndex = nextIdx;
    lead.seqEnrollment.completedAt = today;
    lead.seqEnrollment.nextStepDue = null;
  } else {
    lead.seqEnrollment.stepIndex = nextIdx;
    var delay = (seq.steps[nextIdx] && seq.steps[nextIdx].delayDays) || 0;
    lead.seqEnrollment.nextStepDue = anSeqAddDays(today, delay);
  }
  lead.lastContactDate = today;
  lead.updated = now.toISOString();
  if (step.type === 'email' && lead.status === 'new') lead.status = 'emailed';
  if (step.type === 'call' && (result === 'sent' || result === 'completed' || result === 'no_response')) {
    if (!lead.callLog) lead.callLog = [];
    lead.callLog.unshift({
      date: today,
      time: now.toTimeString().slice(0, 5),
      outcome: result === 'no_response' ? 'noanswer' : 'pickup',
      notes: (notes || '') + ' [Sequence: ' + step.title + ']',
      rep: AN.currentRepEmail || ''
    });
  }
  if (typeof AN !== 'undefined' && AN.save) AN.save();
  return true;
}

window.anCloseSeqPanel = function() {
  var wrap = document.getElementById('seq-panel-wrap');
  if (wrap) wrap.remove();
  var backdrop = document.getElementById('seq-panel-backdrop');
  if (backdrop) backdrop.remove();
  document.body.classList.remove('seq-panel-open');
  anRenderSeqSessionBanner();
};

window.anOpenSeqPanel = function(leadId) {
  anCloseSeqPanel();
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  var info = anGetEnrollmentStep(lead);
  if (!info) {
    if (typeof showToast === 'function') showToast('No active sequence step for this lead');
    return;
  }
  var step = info.step;
  var seq = info.sequence;
  var name = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || lead.company || 'Lead';
  var subject = step.subject ? anApplyScriptMergeFields(step.subject, lead) : '';
  var body = anApplyScriptMergeFields(step.body || '', lead);
  var typeIcons = { call: '📞', email: '📧', text: '💬' };
  var typeLabels = { call: 'Call Step', email: 'Email Step', text: 'Text Step' };
  var prog = null;
  anLoadSeqQueue();
  if (AN.seqQueue && AN.seqQueue.ids && AN.seqQueue.ids.length) {
    var pos = AN.seqQueue.ids.indexOf(leadId) + 1;
    prog = { pos: pos, total: AN.seqQueue.ids.length, done: AN.seqQueue.completed.length };
  }

  var wrap = document.createElement('div');
  wrap.id = 'seq-panel-wrap';
  var overlay = document.createElement('div');
  overlay.id = 'seq-overlay';
  overlay.style.cssText = 'width:100%;height:100%;background:#0a0a14;display:flex;flex-direction:column;overflow-y:auto;-webkit-overflow-scrolling:touch;';

  var stepContent = '';
  if (step.type === 'email') {
    stepContent = '<div style="background:rgba(139,92,246,0.1);border:1.5px solid rgba(139,92,246,0.25);border-radius:12px;padding:14px;margin-bottom:12px;">'
      + '<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;margin-bottom:6px;">Subject</div>'
      + '<div style="font-size:14px;font-weight:700;color:#fff;margin-bottom:12px;">' + anSeqEsc(subject) + '</div>'
      + '<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;margin-bottom:6px;">Body</div>'
      + '<div style="font-size:13px;color:rgba(255,255,255,0.75);line-height:1.65;white-space:pre-wrap;">' + anSeqEsc(body) + '</div>'
      + '</div>'
      + '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">'
      + (lead.email
        ? '<button onclick="anSeqOpenEmail(\'' + leadId + '\')" style="flex:1;min-width:120px;padding:12px;border-radius:10px;border:none;background:linear-gradient(135deg,#8b5cf6,#6366f1);color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">📧 Open in Email</button>'
        : '<div style="font-size:12px;color:#fca5a5;">No email on file</div>')
      + '<button onclick="anCopyToClipboard(document.getElementById(\'seq-body-copy\').value)" style="padding:12px 14px;border-radius:10px;border:1.5px solid rgba(255,255,255,0.15);background:transparent;color:#c4b5fd;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;">📋 Copy</button>'
      + '</div>'
      + '<textarea id="seq-body-copy" style="position:absolute;left:-9999px;opacity:0;"></textarea>';
  } else {
    stepContent = '<div style="background:rgba(16,185,129,0.08);border:1.5px solid rgba(16,185,129,0.2);border-radius:12px;padding:14px;margin-bottom:12px;">'
      + '<div style="font-size:13px;color:rgba(255,255,255,0.8);line-height:1.65;white-space:pre-wrap;">' + anSeqEsc(body) + '</div>'
      + '</div>'
      + (lead.phone
        ? '<a href="tel:' + anSeqEsc((lead.phone || '').replace(/\D/g, '')) + '" style="display:block;text-align:center;padding:14px;border-radius:12px;background:rgba(16,185,129,0.15);border:1.5px solid rgba(16,185,129,0.3);color:#6ee7b7;font-size:15px;font-weight:800;text-decoration:none;margin-bottom:12px;">📞 Call ' + anSeqEsc(anFormatPhone ? anFormatPhone(lead.phone) : lead.phone) + '</a>'
        : '')
      + '<button onclick="openMobileCallMode(\'' + leadId + '\')" style="width:100%;padding:11px;border-radius:10px;border:1.5px solid rgba(99,102,241,0.4);background:rgba(99,102,241,0.12);color:#c7d2fe;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;margin-bottom:8px;">Open Lead Session for full call log</button>';
  }

  overlay.innerHTML = '<div style="background:linear-gradient(135deg,#2e1065,#1a1640);padding:14px 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,0.06);">'
    + '<div><div style="font-size:10px;font-weight:700;color:#c4b5fd;text-transform:uppercase;letter-spacing:0.1em;">📨 Sequence Session</div>'
    + '<div style="font-size:16px;font-weight:800;color:#fff;">' + anSeqEsc(name) + '</div>'
    + (lead.title ? '<div style="font-size:12px;color:#c4b5fd;font-weight:600;margin-top:2px;">' + anSeqEsc(lead.title) + '</div>' : '')
    + (lead.company ? '<div style="font-size:12px;color:rgba(255,255,255,0.4);margin-top:2px;">' + anSeqEsc(lead.company) + '</div>' : '')
    + '</div>'
    + '<button onclick="anCloseSeqPanel()" style="background:rgba(255,255,255,0.08);border:none;color:rgba(255,255,255,0.5);width:36px;height:36px;border-radius:50%;font-size:18px;cursor:pointer;">×</button>'
    + '</div>'
    + (prog ? '<div style="padding:8px 18px;background:rgba(124,58,237,0.15);border-bottom:1px solid rgba(124,58,237,0.25);font-size:11px;font-weight:700;color:#c4b5fd;">Lead ' + prog.pos + ' of ' + prog.total + ' · ' + prog.done + ' done this session</div>' : '')
    + '<div style="padding:16px 18px;border-bottom:1px solid rgba(255,255,255,0.06);">'
    + '<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;margin-bottom:8px;">' + anSeqEsc(seq.name) + ' · Step ' + (info.stepIndex + 1) + '/' + seq.steps.length + '</div>'
    + '<div style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:20px;background:rgba(124,58,237,0.2);color:#ddd6fe;font-size:12px;font-weight:700;margin-bottom:12px;">' + (typeIcons[step.type] || '📋') + ' ' + (typeLabels[step.type] || 'Step') + ' — ' + anSeqEsc(step.title) + '</div>'
    + stepContent
    + '</div>'
    + '<div style="padding:16px 18px;border-bottom:1px solid rgba(255,255,255,0.06);">'
    + '<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;margin-bottom:10px;">Log Result</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">'
    + '<button onclick="anSeqSetResult(\'sent\',\'' + leadId + '\')" id="seq-result-sent" style="padding:12px;border-radius:10px;border:1.5px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.04);color:rgba(255,255,255,0.7);font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;">✅ Sent / Done</button>'
    + '<button onclick="anSeqSetResult(\'no_response\',\'' + leadId + '\')" id="seq-result-no_response" style="padding:12px;border-radius:10px;border:1.5px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.04);color:rgba(255,255,255,0.7);font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;">📵 No Response</button>'
    + '<button onclick="anSeqSetResult(\'replied\',\'' + leadId + '\')" id="seq-result-replied" style="padding:12px;border-radius:10px;border:1.5px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.04);color:rgba(255,255,255,0.7);font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;">💬 They Replied</button>'
    + '<button onclick="anSeqSetResult(\'skip\',\'' + leadId + '\')" id="seq-result-skip" style="padding:12px;border-radius:10px;border:1.5px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.04);color:rgba(255,255,255,0.7);font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;">⏭ Skip Step</button>'
    + '</div></div>'
    + '<div style="padding:0 18px 12px;"><textarea id="seq-note" rows="2" placeholder="Optional note for this step..." style="width:100%;background:rgba(255,255,255,0.05);border:1.5px solid rgba(255,255,255,0.1);border-radius:10px;padding:12px;font-size:13px;color:#fff;font-family:inherit;resize:none;box-sizing:border-box;"></textarea></div>'
    + '<div style="padding:0 18px 24px;display:flex;flex-direction:column;gap:10px;">'
    + '<button onclick="anSeqSaveAndNext(\'' + leadId + '\')" style="width:100%;padding:14px;border-radius:12px;border:none;background:linear-gradient(135deg,#7c3aed,#6366f1);color:#fff;font-size:15px;font-weight:800;cursor:pointer;font-family:inherit;">✓ Save & Next →</button>'
    + '<button onclick="anCloseSeqPanel()" style="width:100%;padding:10px;border:none;background:transparent;color:rgba(255,255,255,0.3);font-size:13px;cursor:pointer;font-family:inherit;">Close panel</button>'
    + '</div>';

  overlay._seqResult = null;
  wrap.appendChild(overlay);
  document.body.appendChild(wrap);
  var copyTa = document.getElementById('seq-body-copy');
  if (copyTa) copyTa.value = 'Subject: ' + subject + '\n\n' + body;
  document.body.classList.add('seq-panel-open');
  if (!document.getElementById('seq-panel-backdrop')) {
    var backdrop = document.createElement('div');
    backdrop.id = 'seq-panel-backdrop';
    document.body.appendChild(backdrop);
  }
  anRenderSeqSessionBanner();
};

window.anSeqSetResult = function(result, leadId) {
  var overlay = document.getElementById('seq-overlay');
  if (overlay) overlay._seqResult = result;
  var colors = { sent: '#10b981', no_response: '#a1a1aa', replied: '#06b6d4', skip: '#f59e0b' };
  document.querySelectorAll('[id^="seq-result-"]').forEach(function(btn) {
    btn.style.background = 'rgba(255,255,255,0.04)';
    btn.style.borderColor = 'rgba(255,255,255,0.1)';
    btn.style.color = 'rgba(255,255,255,0.7)';
  });
  var sel = document.getElementById('seq-result-' + result);
  if (sel) {
    var col = colors[result] || '#7c3aed';
    sel.style.background = col + '22';
    sel.style.borderColor = col;
    sel.style.color = col;
  }
};

window.anSeqOpenEmail = function(leadId) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  var info = anGetEnrollmentStep(lead);
  if (!lead || !info || !lead.email) return;
  var step = info.step;
  var subject = encodeURIComponent(anApplyScriptMergeFields(step.subject || 'Following up', lead));
  var body = encodeURIComponent(anApplyScriptMergeFields(step.body || '', lead));
  window.open('mailto:' + encodeURIComponent(lead.email) + '?subject=' + subject + '&body=' + body, '_blank');
};

window.anSeqSaveAndNext = function(leadId) {
  var overlay = document.getElementById('seq-overlay');
  var result = overlay && overlay._seqResult;
  if (!result) {
    if (typeof showToast === 'function') showToast('Pick a result first (Sent, No Response, etc.)');
    return;
  }
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  var noteEl = document.getElementById('seq-note');
  var note = noteEl ? noteEl.value.trim() : '';
  var logResult = result === 'skip' ? 'skipped' : (result === 'replied' ? 'replied' : 'completed');
  anCompleteSeqStep(lead, logResult, note);
  if (typeof renderLeadsTable === 'function') renderLeadsTable();
  if (typeof hdRender === 'function') hdRender();
  if (typeof showToast === 'function') {
    var msgs = { completed: '✅ Step logged', skipped: '⏭ Step skipped', replied: '💬 Sequence paused — they replied!' };
    showToast(msgs[logResult] || 'Step saved');
  }
  anLoadSeqQueue();
  if (AN.seqQueue && AN.seqQueue.ids && AN.seqQueue.ids.length) {
    anAdvanceSeqQueue(leadId);
  } else {
    anCloseSeqPanel();
  }
};

function anRenderSeqSessionBanner() {
  anLoadSeqQueue();
  var existing = document.getElementById('an-seq-banner');
  if (!AN.seqQueue || !AN.seqQueue.ids || !AN.seqQueue.ids.length) {
    if (existing) existing.remove();
    return;
  }
  if (document.getElementById('seq-panel-wrap')) {
    if (existing) existing.style.display = 'none';
    return;
  }
  var done = AN.seqQueue.completed.length;
  var total = AN.seqQueue.ids.length;
  var pct = Math.round((done / total) * 100);
  if (!existing) {
    existing = document.createElement('div');
    existing.id = 'an-seq-banner';
    document.body.appendChild(existing);
  }
  existing.style.display = 'flex';
  existing.style.cssText = 'position:fixed;bottom:18px;left:calc(var(--sb-width,228px) + 16px);z-index:19997;background:#fff;border:1.5px solid #c4b5fd;border-radius:12px;padding:10px 14px;display:flex;align-items:center;gap:10px;font-family:var(--sans);box-shadow:0 4px 20px rgba(0,0,0,0.12);';
  existing.innerHTML = '<div style="width:36px;height:36px;border-radius:10px;background:linear-gradient(135deg,#7c3aed,#6366f1);display:flex;align-items:center;justify-content:center;font-size:16px;">📨</div>'
    + '<div style="flex:1;"><div style="font-size:12px;font-weight:800;color:#5b21b6;">Sequence Session · ' + done + '/' + total + '</div>'
    + '<div style="height:5px;background:#f5f3ff;border-radius:3px;margin-top:5px;"><div style="height:100%;background:#7c3aed;width:' + pct + '%;border-radius:3px;"></div></div></div>'
    + '<button onclick="anResumeSequenceSession()" style="background:#f5f3ff;border:1px solid #c4b5fd;color:#5b21b6;border-radius:8px;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">Open</button>'
    + '<button onclick="if(confirm(\'End sequence session?\'))anEndSequenceSession()" style="background:transparent;border:1px solid #e4e4e7;color:#71717a;border-radius:8px;padding:6px 10px;font-size:11px;cursor:pointer;font-family:inherit;">End</button>';
}

// ── COMPASS FMO REFERRAL ──────────────────────────────────────

function anGetFmoStatus(lead) {
  return lead && lead.compassFmo && lead.compassFmo.status ? lead.compassFmo : null;
}

function anFmoStatusMeta(statusId) {
  return AN_FMO_STATUSES.find(function(s) { return s.id === statusId; }) || AN_FMO_STATUSES[0];
}

window.anSetFmoStatus = function(leadId, status, opts) {
  opts = opts || {};
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  if (!lead.compassFmo) lead.compassFmo = {};
  lead.compassFmo.status = status;
  lead.compassFmo.updatedAt = new Date().toISOString();
  lead.compassFmo.referredBy = AN.currentRepEmail || lead.compassFmo.referredBy || '';
  if (status === 'referred' && !lead.compassFmo.referredAt) {
    lead.compassFmo.referredAt = anSeqToday();
  }
  var noteEl = document.getElementById('mcm-fmo-notes');
  if (noteEl && noteEl.value.trim()) {
    lead.compassFmo.notes = noteEl.value.trim();
  } else if (opts.notes) {
    lead.compassFmo.notes = opts.notes;
  }
  if (!lead.fmoLog) lead.fmoLog = [];
  lead.fmoLog.unshift({
    date: anSeqToday(),
    status: status,
    notes: lead.compassFmo.notes || '',
    rep: AN.currentRepEmail || ''
  });
  lead.updated = new Date().toISOString();
  if (typeof AN !== 'undefined' && AN.save) AN.save();
  anInjectFmoReferralSection(leadId);
  if (typeof hdRender === 'function') hdRender();
  if (typeof showToast === 'function') showToast('🧭 FMO status: ' + anFmoStatusMeta(status).label);
};

window.anReferToCompassFmo = function(leadId) {
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!lead) return;
  var name = ((lead.firstName || '') + ' ' + (lead.lastName || '')).trim() || 'Unknown';
  var repName = typeof anGetRepName === 'function' && AN.currentRepEmail ? anGetRepName(AN.currentRepEmail) : 'AgentNav Rep';
  var noteEl = document.getElementById('mcm-fmo-notes');
  var notes = noteEl ? noteEl.value.trim() : (lead.compassFmo && lead.compassFmo.notes) || '';
  var body = 'FMO Referral from AgentNav lead session\n\n'
    + 'Agent/Broker: ' + name + '\n'
    + 'Title/Role: ' + (lead.title || '—') + '\n'
    + 'Company: ' + (lead.company || '—') + '\n'
    + 'Phone: ' + (lead.phone || '—') + '\n'
    + 'Email: ' + (lead.email || '—') + '\n'
    + 'State: ' + (lead.state || '—') + '\n'
    + 'Referred by: ' + repName + ' (' + (AN.currentRepEmail || '') + ')\n\n'
    + 'Notes from call:\n' + (notes || '(none)') + '\n\n'
  + 'Please follow up about Compass Insurance Advisors / FMO contracting options.';
  var subject = encodeURIComponent('FMO Referral: ' + name + (lead.company ? ' — ' + lead.company : ''));
  window.open('mailto:' + encodeURIComponent(AN_FMO_REFERRAL_EMAIL) + '?subject=' + subject + '&body=' + encodeURIComponent(body), '_blank');
  anSetFmoStatus(leadId, 'referred', { notes: notes });
};

window.anToggleFmoSection = function(leadId) {
  var body = document.getElementById('mcm-fmo-body');
  var chev = document.getElementById('mcm-fmo-chevron');
  if (!body) return;
  var open = body.style.display === 'none';
  body.style.display = open ? 'block' : 'none';
  if (chev) chev.textContent = open ? '▾' : '▸';
  try { localStorage.setItem('mcm-fmo-expanded', open ? '1' : '0'); } catch(e) {}
};

window.anInjectFmoReferralSection = function(leadId) {
  var overlay = document.getElementById('mcm-overlay');
  var lead = AN.leads.find(function(l) { return l.id === leadId; });
  if (!overlay || !lead) return;
  var mode = overlay._callMode || 'lead';
  if (mode !== 'lead') return;
  var slot = document.getElementById('mcm-fmo-slot');
  if (!slot) {
    slot = document.createElement('div');
    slot.id = 'mcm-fmo-slot';
    var followSlot = document.getElementById('mcm-followup-slot');
    var anchor = followSlot || document.getElementById('mcm-demo-slot');
    if (anchor && anchor.parentNode) anchor.parentNode.insertBefore(slot, anchor.nextSibling);
    else overlay.appendChild(slot);
  }
  var fmo = anGetFmoStatus(lead);
  var curStatus = fmo ? fmo.status : '';
  var statusMeta = curStatus ? anFmoStatusMeta(curStatus) : null;
  var expanded = false;
  try { expanded = localStorage.getItem('mcm-fmo-expanded') === '1'; } catch(e) {}
  if (curStatus && curStatus !== 'declined') expanded = true;
  var statusBadge = statusMeta
    ? '<span style="font-size:10px;font-weight:700;color:' + statusMeta.color + ';background:' + statusMeta.color + '18;border:1px solid ' + statusMeta.color + '44;border-radius:12px;padding:2px 8px;margin-left:8px;">' + statusMeta.icon + ' ' + statusMeta.label + '</span>'
    : '';
  slot.innerHTML = '<div style="padding:10px 18px 12px;border-bottom:1px solid rgba(255,255,255,0.06);">'
    + '<button type="button" onclick="anToggleFmoSection(\'' + leadId + '\')" style="width:100%;display:flex;align-items:center;justify-content:space-between;gap:8px;background:none;border:none;padding:0;cursor:pointer;font-family:inherit;text-align:left;">'
    + '<span style="display:flex;align-items:center;flex-wrap:wrap;gap:4px;min-width:0;">'
    + '<span style="font-size:10px;font-weight:600;color:rgba(255,255,255,0.38);text-transform:uppercase;letter-spacing:0.1em;">🧭 Compass FMO</span>'
    + '<span style="font-size:10px;font-weight:500;color:rgba(255,255,255,0.28);text-transform:none;letter-spacing:0;">optional</span>'
    + statusBadge
    + '</span>'
    + '<span id="mcm-fmo-chevron" style="font-size:11px;color:rgba(255,255,255,0.35);flex-shrink:0;">' + (expanded ? '▾' : '▸') + '</span>'
    + '</button>'
    + '<div id="mcm-fmo-body" style="display:' + (expanded ? 'block' : 'none') + ';margin-top:10px;">'
    + '<div style="font-size:11px;color:rgba(255,255,255,0.38);margin-bottom:8px;line-height:1.4;">Only if they ask about FMO / agency contracting — not your main pitch.</div>'
    + '<div style="display:flex;flex-wrap:wrap;gap:5px;margin-bottom:8px;">'
    + AN_FMO_STATUSES.map(function(s) {
      var on = curStatus === s.id;
      return '<button type="button" onclick="anSetFmoStatus(\'' + leadId + '\',\'' + s.id + '\')" style="padding:5px 10px;border-radius:16px;border:1px solid ' + (on ? s.color : 'rgba(255,255,255,0.1)') + ';background:' + (on ? s.color + '18' : 'transparent') + ';color:' + (on ? s.color : 'rgba(255,255,255,0.5)') + ';font-size:10.5px;font-weight:600;cursor:pointer;font-family:inherit;">' + s.icon + ' ' + s.label + '</button>';
    }).join('')
    + '</div>'
    + '<textarea id="mcm-fmo-notes" rows="2" placeholder="FMO notes (optional)…" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:8px;padding:8px 10px;font-size:11.5px;color:rgba(255,255,255,0.85);font-family:inherit;resize:none;box-sizing:border-box;">' + anSeqEsc((fmo && fmo.notes) || '') + '</textarea>'
    + '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px;flex-wrap:wrap;">'
    + (fmo && fmo.referredAt ? '<span style="font-size:10px;color:rgba(255,255,255,0.32);">Referred ' + fmo.referredAt + (fmo.referredBy ? ' · ' + fmo.referredBy.split('@')[0] : '') + '</span>' : '<span></span>')
    + '<button type="button" onclick="anReferToCompassFmo(\'' + leadId + '\')" style="padding:6px 11px;border-radius:8px;border:1px solid rgba(245,158,11,0.35);background:transparent;color:rgba(252,211,77,0.85);font-size:10.5px;font-weight:600;cursor:pointer;font-family:inherit;white-space:nowrap;">✉️ Email Compass team</button>'
    + '</div>'
    + '</div>'
    + '</div>';
};

function anGetMyFmoReferrals() {
  var myEmail = AN.currentRepEmail || '';
  var isAdmin = AN.isAdmin || false;
  return (AN.leads || []).filter(function(l) {
    if (!l.compassFmo || !l.compassFmo.status) return false;
    if (l.compassFmo.status === 'declined') return false;
    if (!isAdmin && l._repEmail && l._repEmail !== myEmail) return false;
    return ['interested', 'referred', 'contacted'].indexOf(l.compassFmo.status) >= 0;
  }).sort(function(a, b) {
    return (b.compassFmo.updatedAt || '').localeCompare(a.compassFmo.updatedAt || '');
  });
}

function anInjectHomeSeqFmoCards() {
  var root = document.getElementById('home-dashboard-root');
  if (!root) return;
  var oldSeq = document.getElementById('hd-seq-card');
  var oldFmo = document.getElementById('hd-fmo-card');
  if (oldSeq) oldSeq.remove();
  if (oldFmo) oldFmo.remove();

  anLoadSeqQueue();
  var activeSeq = AN.seqQueue && AN.seqQueue.ids && AN.seqQueue.ids.length;
  var seqDone = activeSeq ? AN.seqQueue.completed.length : 0;
  var seqTotal = activeSeq ? AN.seqQueue.ids.length : 0;
  var dueCount = anCountSeqDueLeads();
  var seqPct = seqTotal ? Math.round((seqDone / seqTotal) * 100) : 0;

  var csCard = root.querySelector('.hd-cs-card');
  var seqCard = '<div class="hd-card hd-cs-card" id="hd-seq-card" style="grid-column:1/-1;border-color:#e9d5ff;">'
    + '<div class="hd-cs-inner"><div class="hd-cs-icon" style="background:linear-gradient(135deg,#7c3aed,#6366f1);">📨</div>'
    + '<div style="flex:1;min-width:200px;"><div class="hd-cs-title">' + (activeSeq ? 'Sequence Session in progress' : 'Start a Sequence Session') + '</div>'
    + '<div class="hd-cs-sub">' + (activeSeq ? (seqDone + ' of ' + seqTotal + ' logged · email & call steps') : (dueCount + ' sequence step(s) due today · enroll leads from CRM or blast through due steps')) + '</div>'
    + (activeSeq ? '<div class="hd-cs-bar"><div class="hd-cs-bar-fill" style="width:' + seqPct + '%;background:#7c3aed;"></div></div>' : '')
    + '</div><div style="display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap;">'
    + (activeSeq
      ? '<button class="hd-cs-btn hd-cs-btn-resume" onclick="anResumeSequenceSession()" style="border-color:#c4b5fd;color:#5b21b6;background:#f5f3ff;">▶ Resume</button><button class="hd-cs-btn hd-cs-btn-end" onclick="if(confirm(\'End sequence session?\'))anEndSequenceSession()">End Session</button>'
      : '<button class="hd-cs-btn hd-cs-btn-start" onclick="anOpenSequenceSessionSetup()" style="background:linear-gradient(135deg,#7c3aed,#6366f1);color:#fff;border:none;">📨 Start Sequence Session</button>')
    + '</div></div></div>';

  if (csCard) csCard.insertAdjacentHTML('afterend', seqCard);
  else {
    var body = root.querySelector('.hd-body');
    if (body) body.insertAdjacentHTML('afterbegin', seqCard);
  }

  var fmoLeads = anGetMyFmoReferrals();
  var fmoCard = '<div class="hd-card" id="hd-fmo-card" style="grid-column:1/-1;"><div class="hd-card-header"><span class="hd-card-title">🧭 Compass FMO Referrals'
    + (fmoLeads.length ? ' <span style="background:#fef3c7;color:#b45309;border-radius:20px;padding:1px 7px;font-size:10px;">' + fmoLeads.length + '</span>' : '')
    + '</span><button class="hd-card-action" onclick="showSection(\'crm\',null)">CRM →</button></div><div class="hd-card-body">'
    + (fmoLeads.length ? fmoLeads.slice(0, 5).map(function(l) {
      var name = ((l.firstName || '') + ' ' + (l.lastName || '')).trim() || l.company || 'Unknown';
      var st = anFmoStatusMeta(l.compassFmo.status);
      return '<div class="hd-list-item" onclick="showSection(\'crm\',null);setTimeout(function(){openMobileCallMode(\'' + l.id + '\')},300)" style="cursor:pointer;">'
        + '<div class="hd-avatar" style="background:' + st.color + ';">' + name.charAt(0).toUpperCase() + '</div>'
        + '<div class="hd-item-main"><div class="hd-item-name">' + anSeqEsc(name) + '</div>'
        + '<div class="hd-item-sub">' + anSeqEsc(l.company || 'No company') + (l.compassFmo.notes ? ' · ' + anSeqEsc(l.compassFmo.notes.slice(0, 40)) : '') + '</div></div>'
        + '<div class="hd-item-badge" style="background:' + st.color + '15;color:' + st.color + ';">' + st.icon + ' ' + st.label + '</div></div>';
    }).join('') : '<div class="hd-empty"><div class="hd-empty-icon">🧭</div>Mark FMO interest during lead sessions — referrals show here</div>')
    + '</div></div>';

  var insightsCard = document.getElementById('hd-insights-card');
  var mapCard = document.getElementById('hd-team-map-card');
  if (insightsCard) insightsCard.insertAdjacentHTML('beforebegin', fmoCard);
  else if (mapCard) mapCard.insertAdjacentHTML('afterend', fmoCard);
  else {
    var body2 = root.querySelector('.hd-body');
    if (body2) body2.insertAdjacentHTML('beforeend', fmoCard);
  }
}

// Inject sequence steps due into follow-ups area
function anPatchHdFollowupsWithSeq() {
  var root = document.getElementById('home-dashboard-root');
  if (!root) return;
  var today = anSeqToday();
  var myEmail = AN.currentRepEmail || '';
  var isAdmin = AN.isAdmin || false;
  var seqDue = (AN.leads || []).filter(function(l) {
    if (l.status === 'won' || l.status === 'lost') return false;
    if (!isAdmin && l._repEmail && l._repEmail !== myEmail) return false;
    var en = anGetLeadEnrollment(l);
    return en && en.status === 'active' && en.nextStepDue && en.nextStepDue <= today;
  }).slice(0, 3);
  if (!seqDue.length) return;
  var titles = root.querySelectorAll('.hd-card-title');
  for (var i = 0; i < titles.length; i++) {
    if ((titles[i].textContent || '').indexOf('Follow-Ups Due') >= 0) {
      var body = titles[i].closest('.hd-card');
      if (!body || body.querySelector('.hd-seq-due-block')) return;
      var block = '<div class="hd-seq-due-block" style="margin-bottom:12px;padding-bottom:12px;border-bottom:1px dashed #e4e4e7;">'
        + '<div style="font-size:10px;font-weight:700;color:#7c3aed;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:8px;">📨 Sequence Steps Due</div>'
        + seqDue.map(function(l) {
          var name = ((l.firstName || '') + ' ' + (l.lastName || '')).trim() || l.company || 'Unknown';
          var info = anGetEnrollmentStep(l);
          var stepLabel = info && info.step ? info.step.title : 'Step';
          return '<div class="hd-list-item" onclick="anOpenSeqPanel(\'' + l.id + '\')" style="cursor:pointer;margin-bottom:4px;">'
            + '<div class="hd-avatar" style="background:#7c3aed;">📨</div>'
            + '<div class="hd-item-main"><div class="hd-item-name">' + anSeqEsc(name) + '</div>'
            + '<div class="hd-item-sub">' + anSeqEsc(stepLabel) + '</div></div>'
            + '<button onclick="event.stopPropagation();anOpenSeqPanel(\'' + l.id + '\')" style="background:#f5f3ff;color:#7c3aed;border:1px solid #c4b5fd;border-radius:6px;padding:4px 9px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;">Do Step</button></div>';
        }).join('')
        + '</div>';
      var cardBody = body.querySelector('.hd-card-body');
      if (cardBody) cardBody.insertAdjacentHTML('afterbegin', block);
      break;
    }
  }
}

var _origEnhanceFmo = window._anEnhanceCallPanel;
window._anEnhanceCallPanel = function(leadId) {
  if (typeof _origEnhanceFmo === 'function') _origEnhanceFmo(leadId);
  anInjectFmoReferralSection(leadId);
};

var _origHdRenderSeqFmo = window.hdRender;
window.hdRender = function() {
  if (typeof _origHdRenderSeqFmo === 'function') _origHdRenderSeqFmo();
  setTimeout(function() {
    anInjectHomeSeqFmoCards();
    anPatchHdFollowupsWithSeq();
    anRenderSeqSessionBanner();
  }, 100);
};

// ── SEQUENCE EDITOR ───────────────────────────────────────────
var sqCurrentId = null;
var sqDirty = false;
var SQ_STEP_TYPES = [
  { id: 'call', label: '📞 Call', color: '#10b981' },
  { id: 'email', label: '📧 Email', color: '#8b5cf6' },
  { id: 'text', label: '💬 Text', color: '#06b6d4' }
];
var SQ_MERGE_FIELDS = ['{{first_name}}', '{{last_name}}', '{{full_name}}', '{{title}}', '{{company}}', '{{state}}', '{{phone}}', '{{email}}', '{{rep_name}}'];

window.sqInitEditor = function() {
  var root = document.getElementById('sq-root');
  if (!root || root.dataset.inited) return;
  root.dataset.inited = '1';
  root.style.cssText = 'display:grid;grid-template-columns:260px 1fr;height:calc(100vh - 0px);min-height:0;overflow:hidden;';
  sqRenderMergeChips();
  sqLoad();
  sqRenderLib();
};

function sqRenderMergeChips() {
  var el = document.getElementById('sq-merge-chips');
  if (!el) return;
  el.innerHTML = SQ_MERGE_FIELDS.map(function(tok) {
    return '<button type="button" onclick="sqInsertMerge(\'' + tok.replace(/'/g, "\\'") + '\')" style="padding:4px 9px;border-radius:6px;border:1px solid #e4e4e7;background:#fff;font-size:11px;font-weight:600;color:#6366f1;cursor:pointer;font-family:monospace;">' + tok + '</button>';
  }).join('');
}

window.sqInsertMerge = function(token) {
  var active = document.activeElement;
  if (active && (active.classList.contains('sq-step-body') || active.classList.contains('sq-step-subject') || active.id === 'sq-seq-desc')) {
    var start = active.selectionStart || 0;
    var end = active.selectionEnd || 0;
    var val = active.value || '';
    active.value = val.slice(0, start) + token + val.slice(end);
    active.focus();
    active.selectionStart = active.selectionEnd = start + token.length;
    sqMarkDirty();
    return;
  }
  if (typeof anCopyToClipboard === 'function') anCopyToClipboard(token);
  else if (typeof showToast === 'function') showToast('Copied ' + token);
};

window.sqLoad = function() {
  anLoadSequences();
  return AN._sequences || [];
};

window.sqPersist = function() {
  anSaveSequences();
  sqDirty = false;
  var badge = document.getElementById('sq-dirty-badge');
  if (badge) badge.style.display = 'none';
};

window.sqMarkDirty = function() {
  sqDirty = true;
  var badge = document.getElementById('sq-dirty-badge');
  if (badge) badge.style.display = 'inline-block';
};

function sqGenId(prefix) {
  return (prefix || 'sq') + '-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6);
}

function sqCountEnrolled(seqId) {
  return (AN.leads || []).filter(function(l) {
    return l.seqEnrollment && l.seqEnrollment.sequenceId === seqId && l.seqEnrollment.status === 'active';
  }).length;
}

window.sqRenderLib = function() {
  sqLoad();
  var list = document.getElementById('sq-lib-list');
  if (!list) return;
  var seqs = AN._sequences || [];
  if (!seqs.length) {
    list.innerHTML = '<div style="padding:16px;font-size:12px;color:#71717a;text-align:center;">No sequences yet</div>';
    return;
  }
  list.innerHTML = seqs.map(function(s) {
    var active = s.id === sqCurrentId;
    var enrolled = sqCountEnrolled(s.id);
    var stepCount = (s.steps || []).length;
    return '<div onclick="sqOpenSequence(\'' + s.id + '\')" style="padding:10px 14px;cursor:pointer;border-left:3px solid ' + (active ? '#a78bfa' : 'transparent') + ';background:' + (active ? 'rgba(124,58,237,0.12)' : 'transparent') + ';transition:background 0.12s;" onmouseover="if(\'' + s.id + '\'!==sqCurrentId)this.style.background=\'rgba(255,255,255,0.04)\'" onmouseout="if(\'' + s.id + '\'!==sqCurrentId)this.style.background=\'' + (active ? 'rgba(124,58,237,0.12)' : 'transparent') + '\'">'
      + '<div style="font-size:13px;font-weight:700;color:' + (active ? '#e9d5ff' : '#e4e4e7') + ';white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + anSeqEsc(s.name || 'Untitled') + '</div>'
      + '<div style="font-size:10px;color:#71717a;margin-top:3px;">' + stepCount + ' step' + (stepCount === 1 ? '' : 's') + (enrolled ? ' · ' + enrolled + ' active' : '') + '</div>'
      + '</div>';
  }).join('');
};

function sqShowEditor(show) {
  var empty = document.getElementById('sq-empty');
  var wrap = document.getElementById('sq-editor-wrap');
  if (empty) empty.style.display = show ? 'none' : 'flex';
  if (wrap) wrap.style.display = show ? 'flex' : 'none';
}

window.sqNewSequence = function() {
  sqLoad();
  var seq = {
    id: sqGenId('seq'),
    name: 'New Outreach Sequence',
    description: '',
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    steps: [
      { id: sqGenId('st'), type: 'call', delayDays: 0, title: 'Step 1 — Intro Call', subject: '', body: 'Hey {{first_name}}, this is {{rep_name}} from AgentNav...' },
      { id: sqGenId('st'), type: 'email', delayDays: 2, title: 'Step 2 — Follow-Up Email', subject: 'Quick follow-up', body: 'Hi {{first_name}},\n\nWanted to follow up from my call...\n\n{{rep_name}}' }
    ]
  };
  AN._sequences.push(seq);
  sqPersist();
  sqOpenSequence(seq.id);
  sqMarkDirty();
};

window.sqOpenSequence = function(id) {
  if (sqDirty && !confirm('You have unsaved changes. Discard them?')) return;
  sqCurrentId = id;
  sqDirty = false;
  var badge = document.getElementById('sq-dirty-badge');
  if (badge) badge.style.display = 'none';
  var seq = anGetSequence(id);
  if (!seq) return;
  sqShowEditor(true);
  var nameEl = document.getElementById('sq-seq-name');
  var descEl = document.getElementById('sq-seq-desc');
  if (nameEl) nameEl.value = seq.name || '';
  if (descEl) descEl.value = seq.description || '';
  sqRenderSteps();
  sqRenderTimeline();
  sqRenderLib();
};

function sqRenderTimeline() {
  var el = document.getElementById('sq-timeline');
  var seq = anGetSequence(sqCurrentId);
  if (!el || !seq) return;
  var day = 0;
  var parts = (seq.steps || []).map(function(st, i) {
    day += (i === 0 ? 0 : (parseInt(st.delayDays, 10) || 0));
    var type = SQ_STEP_TYPES.find(function(t) { return t.id === st.type; }) || SQ_STEP_TYPES[0];
    return '<span style="display:inline-flex;align-items:center;gap:4px;margin-right:10px;margin-bottom:4px;padding:3px 8px;border-radius:6px;background:#fff;border:1px solid #e4e4e7;"><span style="color:' + type.color + ';">' + type.label + '</span> Day ' + day + '</span>';
  });
  el.innerHTML = parts.length ? '<span style="color:#a1a1aa;margin-right:8px;">Timeline:</span>' + parts.join('') : '';
}

function sqCollectStepsFromDOM() {
  var cards = document.querySelectorAll('.sq-step-card');
  var steps = [];
  cards.forEach(function(card, i) {
    var typeEl = card.querySelector('.sq-step-type');
    var delayEl = card.querySelector('.sq-step-delay');
    var titleEl = card.querySelector('.sq-step-title');
    var subjectEl = card.querySelector('.sq-step-subject');
    var bodyEl = card.querySelector('.sq-step-body');
    steps.push({
      id: card.dataset.stepId || sqGenId('st'),
      type: typeEl ? typeEl.value : 'call',
      delayDays: delayEl ? (parseInt(delayEl.value, 10) || 0) : 0,
      title: titleEl ? titleEl.value.trim() : ('Step ' + (i + 1)),
      subject: subjectEl ? subjectEl.value.trim() : '',
      body: bodyEl ? bodyEl.value.trim() : ''
    });
  });
  return steps;
}

window.sqCollectSequence = function() {
  var seq = anGetSequence(sqCurrentId);
  if (!seq) return null;
  var nameEl = document.getElementById('sq-seq-name');
  var descEl = document.getElementById('sq-seq-desc');
  seq.name = nameEl ? nameEl.value.trim() || 'Untitled Sequence' : seq.name;
  seq.description = descEl ? descEl.value.trim() : '';
  seq.steps = sqCollectStepsFromDOM();
  seq.updatedAt = new Date().toISOString();
  return seq;
};

window.sqSaveSequence = function() {
  if (!sqCurrentId) return;
  var seq = sqCollectSequence();
  if (!seq || !seq.steps.length) {
    if (typeof showToast === 'function') showToast('Add at least one step');
    return;
  }
  sqPersist();
  sqRenderLib();
  sqRenderTimeline();
  if (typeof showToast === 'function') showToast('✓ Sequence saved');
};

window.sqDeleteSequence = function() {
  if (!sqCurrentId) return;
  var enrolled = sqCountEnrolled(sqCurrentId);
  var msg = enrolled
    ? enrolled + ' lead(s) are actively enrolled in this sequence. Delete anyway?'
    : 'Delete this sequence permanently?';
  if (!confirm(msg)) return;
  AN._sequences = (AN._sequences || []).filter(function(s) { return s.id !== sqCurrentId; });
  if (!AN._sequences.length) {
    AN._sequences.push(JSON.parse(JSON.stringify(AN_DEFAULT_SEQUENCE)));
  }
  sqCurrentId = null;
  sqDirty = false;
  sqPersist();
  sqShowEditor(false);
  sqRenderLib();
  if (typeof showToast === 'function') showToast('Sequence deleted');
};

window.sqDuplicateSequence = function() {
  if (!sqCurrentId) return;
  var seq = sqCollectSequence();
  if (!seq) return;
  var copy = JSON.parse(JSON.stringify(seq));
  copy.id = sqGenId('seq');
  copy.name = (seq.name || 'Sequence') + ' (Copy)';
  copy.createdAt = new Date().toISOString();
  copy.updatedAt = copy.createdAt;
  (copy.steps || []).forEach(function(st) { st.id = sqGenId('st'); });
  AN._sequences.push(copy);
  sqPersist();
  sqOpenSequence(copy.id);
  if (typeof showToast === 'function') showToast('Sequence duplicated');
};

window.sqAddStep = function() {
  if (!sqCurrentId) return;
  sqCollectSequence();
  var seq = anGetSequence(sqCurrentId);
  if (!seq) return;
  var n = (seq.steps || []).length + 1;
  seq.steps.push({
    id: sqGenId('st'),
    type: 'email',
    delayDays: 2,
    title: 'Step ' + n + ' — New Step',
    subject: 'Following up',
    body: 'Hi {{first_name}},\n\n...\n\n{{rep_name}}'
  });
  sqMarkDirty();
  sqRenderSteps();
  sqRenderTimeline();
  var list = document.getElementById('sq-steps-scroll');
  if (list) list.scrollTop = list.scrollHeight;
};

window.sqRemoveStep = function(idx) {
  var seq = anGetSequence(sqCurrentId);
  if (!seq || !seq.steps || seq.steps.length <= 1) {
    if (typeof showToast === 'function') showToast('Sequences need at least one step');
    return;
  }
  sqCollectSequence();
  seq.steps.splice(idx, 1);
  sqMarkDirty();
  sqRenderSteps();
  sqRenderTimeline();
};

window.sqMoveStep = function(idx, dir) {
  var seq = anGetSequence(sqCurrentId);
  if (!seq || !seq.steps) return;
  sqCollectSequence();
  var next = idx + dir;
  if (next < 0 || next >= seq.steps.length) return;
  var tmp = seq.steps[idx];
  seq.steps[idx] = seq.steps[next];
  seq.steps[next] = tmp;
  sqMarkDirty();
  sqRenderSteps();
  sqRenderTimeline();
};

window.sqOnStepTypeChange = function(idx) {
  sqMarkDirty();
  sqRenderSteps();
  sqRenderTimeline();
};

window.sqRenderSteps = function() {
  var list = document.getElementById('sq-steps-list');
  var seq = anGetSequence(sqCurrentId);
  if (!list || !seq) return;
  var steps = seq.steps || [];
  list.innerHTML = steps.map(function(st, idx) {
    var type = st.type || 'call';
    var typeMeta = SQ_STEP_TYPES.find(function(t) { return t.id === type; }) || SQ_STEP_TYPES[0];
    var isEmail = type === 'email';
    var delayLabel = idx === 0 ? 'Starts immediately' : 'Days after previous step';
    return '<div class="sq-step-card" data-step-id="' + anSeqEsc(st.id || '') + '" style="background:#fff;border:1.5px solid #e4e4e7;border-radius:12px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,0.04);">'
      + '<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:#fafafa;border-bottom:1px solid #f0f0f5;">'
      + '<span style="width:26px;height:26px;border-radius:8px;background:' + typeMeta.color + '18;color:' + typeMeta.color + ';display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;flex-shrink:0;">' + (idx + 1) + '</span>'
      + '<select class="sq-step-type" onchange="sqCollectSequence();sqOnStepTypeChange(' + idx + ')" style="border:1.5px solid #e4e4e7;border-radius:6px;padding:5px 8px;font-size:12px;font-weight:600;font-family:inherit;cursor:pointer;background:#fff;">'
      + SQ_STEP_TYPES.map(function(t) {
        return '<option value="' + t.id + '"' + (type === t.id ? ' selected' : '') + '>' + t.label + '</option>';
      }).join('')
      + '</select>'
      + '<div style="flex:1;min-width:80px;"><div style="font-size:9px;font-weight:700;color:#a1a1aa;text-transform:uppercase;margin-bottom:2px;">' + delayLabel + '</div>'
      + (idx === 0 ? '<span style="font-size:12px;color:#71717a;">Day 0</span>' : '<input class="sq-step-delay" type="number" min="0" max="90" value="' + (st.delayDays || 0) + '" oninput="sqMarkDirty();sqRenderTimeline()" style="width:56px;border:1.5px solid #e4e4e7;border-radius:6px;padding:4px 6px;font-size:12px;font-weight:700;font-family:inherit;">')
      + '</div>'
      + '<div style="display:flex;gap:4px;flex-shrink:0;">'
      + '<button type="button" onclick="sqMoveStep(' + idx + ',-1)" ' + (idx === 0 ? 'disabled style="opacity:0.3;"' : '') + ' style="padding:4px 8px;border:1px solid #e4e4e7;border-radius:6px;background:#fff;cursor:pointer;font-size:11px;">↑</button>'
      + '<button type="button" onclick="sqMoveStep(' + idx + ',1)" ' + (idx === steps.length - 1 ? 'disabled style="opacity:0.3;"' : '') + ' style="padding:4px 8px;border:1px solid #e4e4e7;border-radius:6px;background:#fff;cursor:pointer;font-size:11px;">↓</button>'
      + '<button type="button" onclick="sqRemoveStep(' + idx + ')" style="padding:4px 8px;border:1px solid #fca5a5;border-radius:6px;background:#fef2f2;color:#ef4444;cursor:pointer;font-size:11px;">✕</button>'
      + '</div></div>'
      + '<div style="padding:12px 14px;display:flex;flex-direction:column;gap:10px;">'
      + '<input class="sq-step-title" type="text" value="' + anSeqEsc(st.title || '') + '" placeholder="Step title..." oninput="sqMarkDirty();sqRenderTimeline()" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-weight:700;font-family:inherit;box-sizing:border-box;">'
      + (isEmail ? '<input class="sq-step-subject" type="text" value="' + anSeqEsc(st.subject || '') + '" placeholder="Email subject..." oninput="sqMarkDirty()" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:9px 11px;font-size:13px;font-family:inherit;box-sizing:border-box;">' : '<input class="sq-step-subject" type="hidden" value="">')
      + '<textarea class="sq-step-body" rows="' + (isEmail ? 8 : 5) + '" placeholder="' + (isEmail ? 'Email body...' : (type === 'text' ? 'Text message...' : 'Call script / talking points...')) + '" oninput="sqMarkDirty()" style="width:100%;border:1.5px solid #e4e4e7;border-radius:8px;padding:10px 12px;font-size:13px;line-height:1.6;font-family:inherit;resize:vertical;box-sizing:border-box;min-height:100px;">' + sqTextareaSafe(st.body || '') + '</textarea>'
      + '</div></div>';
  }).join('');
};

var _origShowSectionSq = window.showSection;
