  bd.onclick = function(e){ if(e.target===bd) bd.remove(); };

  bd.innerHTML = '<div style="background:var(--card-bg,#fff);border-radius:14px;width:580px;max-width:95vw;max-height:90vh;overflow-y:auto;box-shadow:0 24px 80px rgba(0,0,0,0.3);font-family:inherit;" onclick="event.stopPropagation()">'
    + '<div style="padding:18px 20px;border-bottom:1px solid var(--divider);display:flex;align-items:center;justify-content:space-between;">'
    + '<div>'
    + '<div style="font-size:15px;font-weight:800;color:var(--text-primary);">📧 Bulk Email</div>'
